select x.region_id, x.theme from jsonb_to_recordset($J$[{"region_id":"deungdo_landing","theme":"water"},{"region_id":"dark_yamen","theme":"city"},{"region_id":"martial_row","theme":"mountain"},{"region_id":"red_shrine_lane","theme":"shrine"},{"region_id":"old_ferry_market","theme":"water"},{"region_id":"lamp_rest","theme":"city"},{"region_id":"first_observatory","theme":"sky"},{"region_id":"ash_palace","theme":"desert"},{"region_id":"pact_court","theme":"shrine"},{"region_id":"jeongni_vault","theme":"deep"}]$J$::jsonb) as x(region_id text, theme text)
