insert into public.world_region_profiles(region_id, biome_key, biome_name, faction_style, signature_clue, signature_event, signature_items, survival_hazard, visual_identity, signature_resources, investigation_reward)
select x.region_id, x.biome_key, x.biome_name, x.faction_style, x.signature_clue, x.signature_event, array(select jsonb_array_elements_text(x.signature_items)), x.survival_hazard, x.visual_identity, array(select jsonb_array_elements_text(x.signature_resources)), x.investigation_reward from jsonb_to_recordset($J$[{"region_id":"deungdo_landing","biome_key":"water","biome_name":"물가·나루","faction_style":"흑련 장부지기·수향 뱃사람","signature_clue":"남문 수로 선착의 말뚝: 거룻배마다 판자를 덧댄 자국이 남아 있다.","signature_event":"남문 수로 선착 고유 사건: 수로 물에 닿은 손등이 잿빛으로 바랜다.","signature_items":["white_night_frost","river_reed","tonic"],"survival_hazard":"흰 밤·비싼 물자","visual_identity":"돌계단, 거룻배, 야영소 천막","signature_resources":["herb","river_reed","tonic","travel_ration","white_night_frost"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"dark_yamen","biome_key":"city","biome_name":"관아·옛터","faction_style":"부르다 굳은 넋들","signature_clue":"꺼진 관아 터의 현판: 「등도 관아, 도제조 백운서 쓰다」라는 글씨만 바래지 않았다.","signature_event":"꺼진 관아 터 고유 사건: 안채 벽 서식의 미룸 칸이 하나도 채워지지 않았다.","signature_items":["white_night_frost","medicine_base","herb"],"survival_hazard":"흰 밤·매복·무리","visual_identity":"흰 하늘, 쓰러진 대문, 이름 바랜 등롱","signature_resources":["bleached_lantern_paper","century_form_scrap","herb","medicine_base","seal_paper","travel_ration","white_night_frost"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"martial_row","biome_key":"mountain","biome_name":"거리·연무장","faction_style":"북령 무관의 넋","signature_clue":"무관 거리의 목인: 가슴께에 새긴 이름이 모두 하얗게 바랬다.","signature_event":"무관 거리 고유 사건: 허공에 멈춘 화살이 일흔 해째 과녁으로 날아가는 중이다.","signature_items":["white_night_frost","travel_ration","herb"],"survival_hazard":"흰 밤·서리·되울림","visual_identity":"녹지 않는 서리, 멈춘 화살, 종루","signature_resources":["frost_bell_iron","frozen_arrow_shaft","herb","ore","raw_iron","travel_ration","white_night_frost","wood"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"red_shrine_lane","biome_key":"shrine","biome_name":"사당·골목","faction_style":"적월 무리의 넋","signature_clue":"붉은 사당 골목의 축문 벽: 구절 하나만 거꾸로 적혀 있다.","signature_event":"붉은 사당 골목 고유 사건: 첫 기름 곳간의 기름이 끊긴 날짜가 그날 밤과 같다.","signature_items":["red_shrine_lacquer","resin","wood"],"survival_hazard":"흰 밤·결계·독","visual_identity":"거꾸로 건 등, 기름때 낀 축문, 붉은 우물","signature_resources":["herb","red_shrine_lacquer","resin","river_reed","severed_lamp_oil","travel_ration","white_night_frost","wood"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"old_ferry_market","biome_key":"water","biome_name":"물가·저자","faction_style":"수향 무리의 넋","signature_clue":"옛 나루 저자의 장부 좌판: 값을 적은 칸 옆에 빈칸이 하나씩 남아 있다.","signature_event":"옛 나루 저자 고유 사건: 우물의 물이 붙드는 손처럼 사람을 놓아주지 않는다.","signature_items":["white_night_frost","medicine_base","herb"],"survival_hazard":"흰 밤·물살·되갚음","visual_identity":"마른 물길, 얹힌 배, 돛대 셋","signature_resources":["herb","medicine_base","river_reed","waterlogged_plank","white_night_frost","wood"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"lamp_rest","biome_key":"city","biome_name":"쉼막·등 가게","faction_style":"수향 뱃사람·명등지기의 자취","signature_clue":"등지기 쉼막의 마루: 등을 고치던 연장 자국이 마루에 깊게 남았다.","signature_event":"등지기 쉼막 고유 사건: 쉼막에 켜 둔 등 하나 둘레만 저녁 빛깔이 돈다.","signature_items":["white_night_frost","river_reed","severed_lamp_oil"],"survival_hazard":"흰 밤·비싼 물자","visual_identity":"고친 처마, 등 하나, 뱃사람 거처","signature_resources":["herb","river_reed","severed_lamp_oil","travel_ration","white_night_frost"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"first_observatory","biome_key":"sky","biome_name":"누대·관측","faction_style":"잘못 읽힌 별의 넋","signature_clue":"첫 관상대의 별 기록판: 그날 밤 적은 별 하나가 지워져 있다.","signature_event":"첫 관상대 고유 사건: 출입 장부의 마지막 줄에 이름 없는 관측관이 적혀 있다.","signature_items":["star_record_plate","seal_paper","faded_star_glass"],"survival_hazard":"흰 밤·하늘·매복","visual_identity":"녹슨 혼천의, 별 없는 흰 하늘, 기록판","signature_resources":["faded_star_glass","ore","seal_paper","spirit_dust","star_record_plate","star_sand"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"ash_palace","biome_key":"desert","biome_name":"궁궐·재","faction_style":"남명 무리의 넋","signature_clue":"잿빛 왕궁 터의 돌 단: 임금의 등이 놓였던 둥근 자국이 남았다.","signature_event":"잿빛 왕궁 터 고유 사건: 그림자 없는 땅에서 빈 옥좌만 그림자를 드리운다.","signature_items":["white_night_frost","medicine_base","herb"],"survival_hazard":"흰 밤·결계·독","visual_identity":"바랜 기둥, 빈 옥좌, 재 덮인 정원","signature_resources":["ghost_ash","herb","king_ember_ash","medicine_base","seal_paper","spirit_dust","white_night_frost"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"pact_court","biome_key":"shrine","biome_name":"마당·맹약","faction_style":"맹약에 묶인 것들","signature_clue":"맹약 마당의 돌상: 일곱 홈 가운데 하나만 비어 있다.","signature_event":"맹약 마당 고유 사건: 먹 도랑에 귀를 대면 정리된 이름들이 웅얼거린다.","signature_items":["white_night_frost","spirit_dust","pact_stone_dust"],"survival_hazard":"흰 밤·봉인·껍질","visual_identity":"둥근 돌상, 꺼진 등롱 일곱, 먹 도랑","signature_resources":["ore","pact_stone_dust","raw_iron","seal_paper","spirit_dust","white_night_frost"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"},{"region_id":"jeongni_vault","biome_key":"deep","biome_name":"지하·정리","faction_style":"정리소의 넋","signature_clue":"정리소의 가늠 저울: 접시 한쪽이 늘 내려앉아 있다.","signature_event":"정리소 고유 사건: 봉연 수위 표의 눈금이 해마다 한 칸씩 오른다.","signature_items":["ledger_tab","seal_paper","balance_weight"],"survival_hazard":"먹 도랑·껍질·매복","visual_identity":"먹 도랑, 가늠 저울, 봉연 수위 표","signature_resources":["balance_weight","ledger_tab","ore","raw_iron","seal_paper"],"investigation_reward":"흰 밤에 멈춘 이름의 기록"}]$J$::jsonb) as x(region_id text, biome_key text, biome_name text, faction_style text, signature_clue text, signature_event text, signature_items jsonb, survival_hazard text, visual_identity text, signature_resources jsonb, investigation_reward text)
on conflict (region_id) do update set biome_name = excluded.biome_name, faction_style = excluded.faction_style, signature_clue = excluded.signature_clue, signature_event = excluded.signature_event, signature_items = excluded.signature_items, survival_hazard = excluded.survival_hazard, visual_identity = excluded.visual_identity, signature_resources = excluded.signature_resources;
insert into public.world_region_lore(region_id, lines)
select x.region_id, x.lines from jsonb_to_recordset($J$[{"region_id":"deungdo_landing","lines":[{"s":null,"t":"남문 수로 선착입니다. 옛 남문 물길이 닿는 돌계단 아래로 거룻배 몇 척이 말뚝에 매여 있습니다."},{"s":null,"t":"흑련 장부지기와 수향 뱃사람이 이곳에 임시 야영소를 차렸습니다. 수로 물에 손을 담그지 말라는 말이 천막마다 붙어 있습니다."}]},{"region_id":"dark_yamen","lines":[{"s":null,"t":"꺼진 관아 터입니다. 하늘은 해도 달도 없이 동트기 직전처럼 희고, 발밑에는 그림자가 생기지 않습니다."},{"s":null,"t":"쓰러진 대문 위로 현판 하나만 비스듬히 매달려 있습니다. 안채 벽에는 백 년 전 서식과 셈표가 바래지 않은 채 남아 있습니다."}]},{"region_id":"martial_row","lines":[{"s":null,"t":"무관 거리입니다. 돌바닥 틈마다 서리가 끼었는데, 공기는 차갑지 않은데도 서리가 녹지 않습니다."},{"s":null,"t":"연무 마당의 짚 목인 앞에 화살 몇 대가 허공에 멈춰 있습니다. 거리 끝 종루는 소등 밤 종을 울린 뒤로 한 번도 울리지 않았습니다."}]},{"region_id":"red_shrine_lane","lines":[{"s":null,"t":"붉은 사당 골목입니다. 처마마다 등이 거꾸로 걸려 있고, 담장마다 기름 얼룩이 번져 있습니다."},{"s":null,"t":"사당 벽은 기름때 낀 축문으로 빈틈없이 덮였습니다. 해 지는 쪽 담장 너머에 첫 기름을 두었던 곳간이 있다고 합니다."}]},{"region_id":"old_ferry_market","lines":[{"s":null,"t":"옛 나루 저자입니다. 물이 마른 물길 위에 배들이 얹혀 있고, 빈 좌판마다 값을 적은 나무패가 꽂혀 있습니다."},{"s":null,"t":"돛대 셋이 만나는 자리에 우물이 하나 있습니다. 수향 사람들은 그 물을 「붙드는 물」이라 부르며 가까이 가지 않습니다."}]},{"region_id":"lamp_rest","lines":[{"s":null,"t":"등지기 쉼막입니다. 명등지기가 등을 고치던 쉼막 터에 수향 뱃사람들이 처마를 고쳐 거처를 차렸습니다."},{"s":null,"t":"쉼막 한가운데에 등 하나가 늘 켜져 있습니다. 그 등 둘레에서만 하늘이 저녁 빛깔로 물듭니다."}]},{"region_id":"first_observatory","lines":[{"s":null,"t":"첫 관상대입니다. 녹슨 혼천의가 마당에 놓여 있고, 계단 위로 별 기록판 방이 있습니다."},{"s":null,"t":"흰 하늘에는 별이 하나도 없습니다. 기록판에 적힌 별 가운데 하나는 누군가 일부러 지운 듯 긁혀 있습니다."}]},{"region_id":"ash_palace","lines":[{"s":null,"t":"잿빛 왕궁 터입니다. 하얗게 바랜 궁궐 기둥이 늘어섰고, 계단마다 재가 고르게 덮여 있습니다."},{"s":null,"t":"돌 단 위에 빈 옥좌가 놓여 있습니다. 그 앞 바닥에는 임금의 등이 놓였던 둥근 자국이 선명합니다."}]},{"region_id":"pact_court","lines":[{"s":null,"t":"맹약 마당입니다. 흰 밤이 가장 짙어 손끝조차 흐리게 보입니다."},{"s":null,"t":"일곱 홈이 원을 그린 둥근 돌상 둘레로 꺼진 등롱 일곱이 서 있습니다. 마당 가장자리를 감도는 먹 도랑에서 웅얼거리는 소리가 올라옵니다."}]},{"region_id":"jeongni_vault","lines":[{"s":null,"t":"정리소입니다. 장서각 지하서고 맨 끝 우물을 내려오면 먹 도랑이 흐르는 돌방들이 이어집니다."},{"s":null,"t":"가늠 저울과 봉연 수위 표가 줄지어 서 있습니다. 맨 안쪽 금고 문 앞을 무언가 커다란 것이 지키고 있습니다."}]}]$J$::jsonb) as x(region_id text, lines jsonb)
on conflict (region_id) do update set lines = excluded.lines;
insert into public.world_exploration_nodes(node_id, region_id, parent_node_id, hierarchy_level, node_name, description, min_level, sort_order)
