on conflict (spot_id) do update set spot_name = excluded.spot_name, loot_items = excluded.loot_items, min_level = excluded.min_level;
insert into public.world_region_monsters(monster_id, region_id, monster_name, monster_type, min_level, max_level, hp, attack_power, spawn_weight, description, drops, difficulty_rank, mechanic_key, mechanic_description, role, kind)
select x.monster_id, x.region_id, x.monster_name, x.monster_type, x.min_level, x.max_level, x.hp, x.attack_power, x.spawn_weight, x.description, x.drops, x.difficulty_rank, x.mechanic_key, x.mechanic_description, x.role, x.kind from jsonb_to_recordset($J$[{"monster_id":"dd_yamen_1","region_id":"dark_yamen","monster_name":"부르다 굳은 넋","monster_type":"원령","min_level":45,"max_level":48,"hp":700,"attack_power":58,"spawn_weight":14,"description":"누군가의 이름을 부르다 그대로 굳어 버린 넋이다. 입은 크게 벌렸는데 소리는 한 걸음 밖으로 나가지 않는다.","drops":{"lamp_wick_core":1,"white_night_frost":1},"difficulty_rank":2,"mechanic_key":"spectral","mechanic_description":"몸이 반쯤 비친다. 물리 공격이 덜 듣고 술법이 잘 듣는다.","role":"common","kind":"ghost"},{"monster_id":"dd_yamen_2","region_id":"dark_yamen","monster_name":"바랜 등롱 나방","monster_type":"비행 요괴","min_level":45,"max_level":48,"hp":700,"attack_power":58,"spawn_weight":14,"description":"꺼진 등롱 종이를 갉아 먹고 자란 흰 나방이다. 날개를 털 때마다 바랜 글자 가루가 흩날린다.","drops":{"bleached_lantern_paper":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"bird"},{"monster_id":"dd_yamen_3","region_id":"dark_yamen","monster_name":"서식 긁는 손톱귀","monster_type":"매복 요괴","min_level":47,"max_level":51,"hp":6750,"attack_power":338,"spawn_weight":15,"description":"안채 벽 서식 뒤에 숨어 칸마다 손톱자국을 내는 요괴다. 서식을 읽는 이의 등 뒤로 소리 없이 다가온다.","drops":{"century_form_scrap":2,"lamp_wick_core":2,"white_night_frost":1},"difficulty_rank":5,"mechanic_key":"ambush","mechanic_description":"숨어 있다 먼저 친다. 낌새를 살피고 방어를 섞어라.","role":"main","kind":"shadow"},{"monster_id":"dd_yamen_4","region_id":"dark_yamen","monster_name":"멈춘 물방울 무리","monster_type":"무리 요괴","min_level":47,"max_level":51,"hp":6750,"attack_power":338,"spawn_weight":15,"description":"처마 끝에서 떨어지다 멈춘 물방울들이 떼를 지었다. 살갗에 닿으면 얼음처럼 들러붙는다.","drops":{"white_night_frost":2,"lamp_wick_core":2},"difficulty_rank":5,"mechanic_key":"swarm","mechanic_description":"떼로 몰려든다. 세 번째 행동마다 강하게 반격한다.","role":"main","kind":"swarm"},{"monster_id":"dd_yamen_5","region_id":"dark_yamen","monster_name":"현판 아래 문지기","monster_type":"지역 우두머리","min_level":45,"max_level":47,"hp":1050,"attack_power":80,"spawn_weight":12,"description":"비스듬히 매달린 현판 아래를 지키는 거대한 문지기다. 서식에 이름이 없는 자는 한 발짝도 들이지 않는다.","drops":{"century_form_scrap":3,"lamp_wick_core":3,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"boss","mechanic_description":"보스급 위협. 세 번째 행동마다 광역급 강공격을 하므로 방어 태세를 섞어라.","role":"guardian","kind":"giant"},{"monster_id":"dd_martial_1","region_id":"martial_row","monster_name":"과녁 못 닿은 화살귀","monster_type":"비행 요괴","min_level":46,"max_level":49,"hp":714,"attack_power":59,"spawn_weight":14,"description":"과녁에 닿지 못하고 허공에 멈췄던 화살이 요괴가 되었다. 일흔 해 묵은 기세로 사람을 과녁 삼아 날아든다.","drops":{"frozen_arrow_shaft":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"aerial","mechanic_description":"하늘에서 내리꽂는다. 원거리 사격이 잘 듣는다.","role":"common","kind":"bird"},{"monster_id":"dd_martial_2","region_id":"martial_row","monster_name":"짚 목인 그림자","monster_type":"매복 요괴","min_level":46,"max_level":49,"hp":714,"attack_power":59,"spawn_weight":14,"description":"그림자 없는 땅에서 목인이 제 그림자를 찾아 걸어 나왔다. 줄지어 선 목인 사이에 섞여 있다가 덮친다.","drops":{"white_night_frost":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"ambush","mechanic_description":"숨어 있다 먼저 친다. 낌새를 살피고 방어를 섞어라.","role":"common","kind":"shadow"},{"monster_id":"dd_martial_3","region_id":"martial_row","monster_name":"서리 갑옷 무관","monster_type":"갑각 요괴","min_level":48,"max_level":51,"hp":6900,"attack_power":345,"spawn_weight":15,"description":"녹지 않는 서리를 갑옷처럼 두른 무관의 넋이다. 소등 밤 종이 울린 그날의 자세로 연무 마당을 지킨다.","drops":{"frost_bell_iron":2,"lamp_wick_core":2,"white_night_frost":1},"difficulty_rank":5,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"main","kind":"shell"},{"monster_id":"dd_martial_4","region_id":"martial_row","monster_name":"종소리 먹은 늑대","monster_type":"거울 요괴","min_level":48,"max_level":51,"hp":6900,"attack_power":345,"spawn_weight":15,"description":"종루에서 흩어진 종소리를 삼킨 늑대다. 맞은 소리를 그대로 되울려 상대에게 돌려준다.","drops":{"frost_bell_iron":2,"lamp_wick_core":2,"white_night_frost":1},"difficulty_rank":5,"mechanic_key":"reflect","mechanic_description":"공격의 일부를 되돌린다. 원거리 사격이나 봉인 제압을 써라.","role":"main","kind":"mirror"},{"monster_id":"dd_martial_5","region_id":"martial_row","monster_name":"녹아내린 종지기 그림자","monster_type":"지역 우두머리","min_level":46,"max_level":48,"hp":1071,"attack_power":82,"spawn_weight":12,"description":"종채가 녹아내린 종루 꼭대기에서 일어선 종지기의 그림자다. 몸을 흔들 때마다 봉인이 종소리처럼 갈라진다.","drops":{"frost_bell_iron":3,"lamp_wick_core":3,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"seal_breaker","mechanic_description":"봉인을 약하게 만든다. 부적과 봉인 재료를 챙겨라.","role":"guardian","kind":"breaker"},{"monster_id":"dd_shrine_1","region_id":"red_shrine_lane","monster_name":"거꾸로 매달린 등귀","monster_type":"원령","min_level":47,"max_level":50,"hp":728,"attack_power":60,"spawn_weight":14,"description":"거꾸로 건 등 안에 갇힌 넋이다. 등이 흔들릴 때마다 뒤집힌 얼굴이 종이 너머로 비친다.","drops":{"severed_lamp_oil":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"spectral","mechanic_description":"몸이 반쯤 비친다. 물리 공격이 덜 듣고 술법이 잘 듣는다.","role":"common","kind":"ghost"},{"monster_id":"dd_shrine_2","region_id":"red_shrine_lane","monster_name":"기름 핥는 쥐떼","monster_type":"무리 요괴","min_level":47,"max_level":50,"hp":728,"attack_power":60,"spawn_weight":14,"description":"끊긴 등 기름을 핥으며 불어난 흰 쥐떼다. 지나간 자리마다 기름 자국이 길게 남는다.","drops":{"severed_lamp_oil":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"swarm","mechanic_description":"떼로 몰려든다. 세 번째 행동마다 강하게 반격한다.","role":"common","kind":"swarm"},{"monster_id":"dd_shrine_3","region_id":"red_shrine_lane","monster_name":"거꾸로 외는 축문귀","monster_type":"결계 요괴","min_level":49,"max_level":51,"hp":7050,"attack_power":352,"spawn_weight":15,"description":"사당 벽의 축문을 끝에서부터 거꾸로 외는 요괴다. 한 구절을 욀 때마다 몸에 붉은 금줄이 한 겹 감긴다.","drops":{"red_shrine_lacquer":2,"lamp_wick_core":2,"white_night_frost":1},"difficulty_rank":5,"mechanic_key":"warded","mechanic_description":"결계를 두른다. 결계를 깨는 한 방을 모아 두어라.","role":"main","kind":"ward"},{"monster_id":"dd_shrine_4","region_id":"red_shrine_lane","monster_name":"달 지기 허물","monster_type":"독충","min_level":49,"max_level":51,"hp":7050,"attack_power":352,"spawn_weight":15,"description":"반쪽 달을 지키던 벌레가 벗어 둔 허물이 스스로 움직인다. 허물 틈으로 붉은 독기가 샌다.","drops":{"red_shrine_lacquer":2,"lamp_wick_core":2,"white_night_frost":1},"difficulty_rank":5,"mechanic_key":"toxic","mechanic_description":"독을 뿜는다. 해독할 약초와 회복품을 챙겨라.","role":"main","kind":"venom"},{"monster_id":"dd_shrine_5","region_id":"red_shrine_lane","monster_name":"반쪽 달 무녀","monster_type":"지역 우두머리","min_level":47,"max_level":49,"hp":1092,"attack_power":84,"spawn_weight":12,"description":"얼굴 반쪽만 남은 무녀의 넋이다. 첫 기름 곳간 앞을 지키며 서약을 거꾸로 되뇐다.","drops":{"red_shrine_lacquer":3,"lamp_wick_core":3,"spirit_core":1},"difficulty_rank":10,"mechanic_key":"warded","mechanic_description":"결계를 두른다. 결계를 깨는 한 방을 모아 두어라.","role":"guardian","kind":"ward"},{"monster_id":"dd_ferry_1","region_id":"old_ferry_market","monster_name":"마른 물길 게","monster_type":"갑각 요괴","min_level":48,"max_level":50,"hp":742,"attack_power":61,"spawn_weight":14,"description":"물이 마른 물길 바닥에서 껍질만 단단해진 커다란 게다. 얹힌 배 밑에 숨어 집게를 벌린다.","drops":{"waterlogged_plank":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"armored","mechanic_description":"껍질이 단단하다. 방어를 무시하는 공격이나 술법이 낫다.","role":"common","kind":"shell"},{"monster_id":"dd_ferry_2","region_id":"old_ferry_market","monster_name":"문패 문 물귀","monster_type":"수귀","min_level":48,"max_level":50,"hp":742,"attack_power":61,"spawn_weight":14,"description":"배 이름이 적힌 문패를 입에 문 채 마른 물길을 헤엄치는 물귀다. 물 한 방울 없는 바닥에서도 물살을 일으킨다.","drops":{"white_night_frost":1,"lamp_wick_core":1},"difficulty_rank":2,"mechanic_key":"tide","mechanic_description":"물살로 끌어당겨 발을 묶는다. 거리를 두고 싸우거나 묶이기 전에 끊어라.","role":"common","kind":"water"},{"monster_id":"dd_ferry_3","region_id":"old_ferry_market","monster_name":"값 매기는 뱃사공","monster_type":"거울 요괴","min_level":50,"max_level":51,"hp":7200,"attack_power":360,"spawn_weight":15,"