update public.world_item_catalog i set reference_price = greatest(
    ceil(1.2 * (select min(t.v) from (select sum(m.reference_price * (x.value)::int * 1.0 / greatest(1, cr.output_qty)) v from public.world_crafting_recipes cr, jsonb_each_text(cr.ingredients) x
      join public.world_item_catalog m on m.item_id = x.key where cr.output_item = i.item_id group by cr.recipe_id) t)),
    coalesce(ceil(1.15 * (select max(f.reference_price) from public.world_item_catalog f where f.tier = 7 and f.category = i.category and f.base_item_id is null
      and f.item_id not like 'raid%' and coalesce((f.equipment_traits ->> 'life_slot'), '') = coalesce((i.equipment_traits ->> 'life_slot'), ''))), 0))
 where i.item_id in (select jsonb_array_elements_text($J$["w_melee8_base","w_melee8_heavy","w_melee8_keen","w_melee8_silent","w_ranged8_base","w_ranged8_heavy","w_ranged8_keen","w_ranged8_silent","w_magic8_base","w_magic8_heavy","w_magic8_keen","w_magic8_silent","a8_iron","a8_brig","a8_light","a8_shade","a8_robe","a8_star","h8_calm","h8_guard","h8_wise","s8_road","s8_sturdy","s8_swift","n8_keen","n8_luck","n8_plenty","m8_purify","m8_spell","m8_ward","k8_awe","k8_ghost","k8_hide","lt_knife_mzl","lt_pick_mzl","lt_sickle_mzl","lt_lantern_mzl","n_mzl_night","mz_lamp_incense","w_melee_mzl","w_ranged_mzl","w_magic_mzl","a_mzl_vit","a_mzl_agi","a_mzl_will","h_mzl_herb","s_mzl_wood","m_mzl_stone","k_mzl_wood","lt_knife_9","lt_pick_8","lt_sickle_8","lt_lantern_8","lt_compass_8","lt_rod_8","lt_hammer_8","lt_needle_8","lt_carve_8","lt_still_8","lt_cook_8"]$J$::jsonb)) and i.category <> 'consumable';
