    ceil(1.1 * (select min(t.v) from (select sum(m.reference_price * (x.value)::int * 1.0 / greatest(1, cr.output_qty)) v from public.world_crafting_recipes cr, jsonb_each_text(cr.ingredients) x
      join public.world_item_catalog m on m.item_id = x.key where cr.output_item = i.item_id group by cr.recipe_id) t)))
 where i.item_id in (select jsonb_array_elements_text($J$["minnow_fritter","smelt_clear_soup","burrow_scale","cheong_carp_steam","lampfish_oil_lamp","goldcarp_feast","myeongdeung_lamp","night_tea","ember_ash_pill","hf_wall_bleached_eave_lamp","hf_floor_frozen_target","hf_floor_cheong_prow","hf_surface_armillary_model","hf_floor_empty_throne_stool","hf_rubbing_undying_lampfish","hf_rubbing_burrow_goldcarp","mz_lamp_incense"]$J$::jsonb))
   and exists (select 1 from public.world_crafting_recipes cr where cr.output_item = i.item_id);
insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, required_stats, required_job, required_faction, minimum_level,
  rarity, acquisition_difficulty, drop_rate_modifier, equipment_traits, crafting_specialization, tradeable, reference_price, stack_size, base_item_id, quality_grade, use_fx)
select i.item_id || '_hq', i.item_name || ' (우수)', i.category, i.tier, i.description || ' ' || public.world_item_hq_note(i.item_id, i.category), i.stackable,
  i.required_stats, i.required_job, i.required_faction, i.minimum_level, i.rarity, i.acquisition_difficulty, i.drop_rate_modifier,
  case when i.category in ('weapon', 'armor', 'hat', 'shoes', 'norigae', 'amulet', 'mask', 'tool') then public.world_item_hq_traits(i.equipment_traits) else i.equipment_traits end,
  i.crafting_specialization, i.tradeable, ceil(coalesce(i.reference_price, 0) * 1.3), i.stack_size, i.item_id, 1, null
  from public.world_item_catalog i
 where i.item_id in (select jsonb_array_elements_text($J$["myeongdeung_lamp","night_tea","ember_ash_pill","minnow_fritter","smelt_clear_soup","cheong_carp_steam","lampfish_oil_lamp","goldcarp_feast","lt_knife_9","lt_pick_8","lt_sickle_8","lt_lantern_8","lt_compass_8","lt_rod_8","lt_hammer_8","lt_needle_8","lt_carve_8","lt_still_8","lt_cook_8","w_melee8_base","w_melee8_heavy","w_melee8_keen","w_melee8_silent","w_ranged8_base","w_ranged8_heavy","w_ranged8_keen","w_ranged8_silent","w_magic8_base","w_magic8_heavy","w_magic8_keen","w_magic8_silent","a8_iron","a8_brig","a8_light","a8_shade","a8_robe","a8_star","h8_calm","h8_guard","h8_wise","s8_road","s8_sturdy","s8_swift","n8_keen","n8_luck","n8_plenty","m8_purify","m8_spell","m8_ward","k8_awe","k8_ghost","k8_hide","lt_knife_mzl","lt_pick_mzl","lt_sickle_mzl","lt_lantern_mzl","n_mzl_night","mz_lamp_incense","w_melee_mzl","w_ranged_mzl","w_magic_mzl","a_mzl_vit","a_mzl_agi","a_mzl_will","h_mzl_herb","s_mzl_wood","m_mzl_stone","k_mzl_wood"]$J$::jsonb))
on conflict (item_id) do nothing;
insert into public.world_fish_species(fish_id, fish_name, habitat, rarity, min_level, phase, weather, size_min, size_max, description, sort, active, grounds, bait_for, named)
select x.fish_id, x.fish_name, x.habitat, x.rarity, x.min_level, x.phase, x.weather, x.size_min, x.size_max, x.description,
       (select coalesce(max(sort), 0) from public.world_fish_species) + x.n, true, case when x.ground is null then null else array[x.ground] end, '{}'::text[], x.named
  from jsonb_to_recordset($J$[{"fish_id":"snow_minnow","fish_name":"흰눈 송사리","habitat":"canal","rarity":"common","phase":null,"weather":null,"min_level":30,"size_min":3,"size_max":7,"description":"흰 밤의 물길에서 눈송이처럼 하얗게 떼 지어 다니는 송사리다.","ground":null,"named":false,"n":1},{"fish_id":"lantern_smelt","fish_name":"등불 빙어","habitat":"canal","rarity":"uncommon","phase":"dusk","weather":null,"min_level":30,"size_min":8,"size_max":16,"description":"몸속이 등불처럼 비치는 빙어다. 땅거미가 지면 물길 위로 떠오른다.","ground":null,"named":false,"n":2},{"fish_id":"burrow_hagfish","fish_name":"물굴 먹장어","habitat":"deep","rarity":"rare","phase":"night","weather":null,"min_level":32,"size_min":50,"size_max":110,"description":"우물 밑 물굴 바닥에 숨어 사는 먹장어다. 삼경에만 굴 밖으로 몸을 내민다.","ground":null,"named":false,"n":3},{"fish_id":"cheong_carp","fish_name":"청씨 잉어","habitat":"deep","rarity":"uncommon","phase":null,"weather":null,"min_level":30,"size_min":30,"size_max":70,"description":"청씨 선단 뱃사람들이 우물에 놓아 길렀다는 잉어의 후손이다. 비늘이 푸른빛을 띤다.","ground":null,"named":false,"n":4},{"fish_id":"undying_lampfish","fish_name":"꺼지지 않는 등어","habitat":"canal","rarity":"legendary","phase":"dusk","weather":"fog","min_level":45,"size_min":40,"size_max":90,"description":"배 속에 꺼지지 않는 불씨를 품은 물고기다. 안개 낀 땅거미에 물길 물고기 냄새를 따라 올라온다더라.","ground":"deungdo_landing","named":true,"n":5},{"fish_id":"burrow_goldcarp","fish_name":"물굴 금잉어","habitat":"deep","rarity":"legendary","phase":"night","weather":"cloudy","min_level":45,"size_min":70,"size_max":150,"description":"물굴 가장 깊은 곳에 산다는 금빛 잉어다. 구름 낀 삼경에 깊은 물고기 냄새가 내려가면 올라온다더라.","ground":"old_ferry_market","named":true,"n":6}]$J$::jsonb)
    as x(fish_id text, fish_name text, habitat text, rarity text, min_level int, phase text, weather text, size_min numeric, size_max numeric, description text, ground text, named boolean, n int)
on conflict (fish_id) do update set fish_name = excluded.fish_name, habitat = excluded.habitat, rarity = excluded.rarity, min_level = excluded.min_level, phase = excluded.phase,
  weather = excluded.weather, size_min = excluded.size_min, size_max = excluded.size_max, description = excluded.description, grounds = excluded.grounds, named = excluded.named;
update public.world_fish_species s set bait_for = array(select distinct unnest(s.bait_for || array(select jsonb_array_elements_text($J${"snow_minnow":["undying_lampfish"],"lantern_smelt":["undying_lampfish"],"stone_goby":["undying_lampfish"],"sluice_carp":["undying_lampfish"],"cheong_carp":["burrow_goldcarp"],"well_blindfish":["burrow_goldcarp"],"bronze_catfish":["burrow_goldcarp"]}$J$::jsonb -> s.fish_id))) order by 1)
 where s.fish_id in (select jsonb_object_keys($J${"snow_minnow":["undying_lampfish"],"lantern_smelt":["undying_lampfish"],"stone_goby":["undying_lampfish"],"sluice_carp":["undying_lampfish"],"cheong_carp":["burrow_goldcarp"],"well_blindfish":["burrow_goldcarp"],"bronze_catfish":["burrow_goldcarp"]}$J$::jsonb));
do $c$ begin
  if exists (select 1 from public.world_fish_species n where n.named and (select count(*) from public.world_fish_species b where n.fish_id = any (b.bait_for) and b.rarity in ('common', 'uncommon', 'rare')) < 3) then
    raise exception '명어마다 미끼가 셋 이상이어야 합니다';
  end if;
end $c$;
insert into public.world_shop_catalog(shop_id, item_id, base_price, stock_min, stock_max, daily_cap)
select 'deungdo_landing_shop', x.item_id, case when x.price > 0 then x.price else (select i.reference_price * 3 from public.world_item_catalog i where i.item_id = x.item_id) end, 1, 1, x.cap
  from jsonb_to_recordset($J$[{"item_id":"myeongdeung_lamp","price":1200,"cap":3},{"item_id":"night_tea","price":420,"cap":5},{"item_id":"tonic","price":210,"cap":10},{"item_id":"ward_talisman","price":260,"cap":8},{"item_id":"travel_ration","price":160,"cap":10},{"item_id":"repair_kit","price":0,"cap":3},{"item_id":"spirit_qi_pill","price":0,"cap":5},{"item_id":"revival_charm","price":1100,"cap":1},{"item_id":"ammo_arrow","price":0,"cap":200},{"item_id":"ammo_bolt","price":0,"cap":200},{"item_id":"ammo_dart","price":0,"cap":200},{"item_id":"hf_wall_bleached_eave_lamp","price":0,"cap":2}]$J$::jsonb) as x(item_id text, price bigint, cap int)
on conflict (shop_id, item_id) do update set base_price = excluded.base_price, daily_cap = excluded.daily_cap;
insert into public.world_shop_catalog(shop_id, item_id, base_price, stock_min, stock_max, daily_cap)
select 'lamp_rest_shop', x.item_id, case when x.price > 0 then x.price else (select i.reference_price * 3 from public.world_item_catalog i where i.item_id = x.item_id) end, 1, 1, x.cap
  from jsonb_to_recordset($J$[{"item_id":"myeongdeung_lamp","price":1200,"cap":3},{"item_id":"night_tea","price":420,"cap":5},{"item_id":"ember_ash_pill","price":520,"cap":4},{"item_id":"tonic","price":210,"cap":10},{"item_id":"travel_ration","price":160,"cap":10},{"item_id":"repair_kit","price":0,"cap":3},{"item_id":"revival_charm","price":1100,"cap":1},{"item_id":"ammo_arrow","price":0,"cap":200},{"item_id":"ammo_bolt","price":0,"cap":200},{"item_id":"ammo_dart","price":0,"cap":200}]$J$::jsonb) as x(item_id text, price bigint, cap int)
on conflict (shop_id, item_id) do update set base_price = excluded.base_price, daily_cap = excluded.daily_cap;
insert into public.world_furniture_sources(source, item_id, chance) select x.source, x.item_id, x.chance from jsonb_to_recordset($J$[{"source":"drop_normal","item_id":"hf_floor_frozen_target","chance":1},{"source":"drop_normal","item_id":"hf_floor_cheong_prow","chance":1},{"source":"drop_guardian","item_id":"hf_surface_armillary_model","chance":1},{"source":"expedition","item_id":"hf_surface_armillary_model","chance":1},{"source":"drop_guardian","item_id":"hf_floor_empty_throne_stool","chance":1},{"source":"expedition","item_id":"hf_floor_empty_throne_stool","chance":1},{"source":"boss:dd_pact_5","item_id":"hf_floor_seven_seat_table","chance":1}]$J$::jsonb) as x(source text, item_id text, chance numeric)
 where not exists (select 1 from public.world_furniture_sources s where s.source = x.source and s.item_id = x.item_id);
insert into public.world_meisho(meisho_id, meisho_name, region_id, node_id, kind, phase, weather, weather2, min_level, description, sort)
select x.id, x.name, x.region, n.node_id, x.kind, x.phase, x.weather, x.weather2, n.min_level, x."desc", x.sort
  from jsonb_to_recordset($J$[{"id":"mz_dd_target_tree","name":"과녁 못 닿은 고목","region":"martial_row","node":"연무 마당 끝","kind":"wood","phase":"dawn","weather":"clear","weather2":"wind","desc":"연무 마당 끝에 선 고목이다. 빗나간 화살이 일흔 해째 가지 끝에 멈춰 있고, 밤을 되찾은 뒤 맑거나 삭풍 부는 해돋이에만 결이 풀린다.","sort":100},{"id":"mz_dd_star_plinth","name":"별 떨어진 주춧돌","region":"first_observatory","node":"혼천의 받침 아래","kind":"stone","phase":"night","weather":"clear","weather2":"cloudy","desc":"혼천의 받침 아래 박힌 주춧돌이다. 별이 하나 떨어져 박혔다는 말이 있고, 밤을 되찾은 뒤 맑거나 흐린 삼경에만 돌결이 빛난다.","sort":101},{"id":"mz_dd_ash_flower","name":"임금 뜰의 재꽃","region":"ash_palace","node":"옥좌 뒤 정원","kind":"herb","phase":"dusk","weather":"drizzle","weather2":"fog","desc":"옥좌 뒤 정원 재 속에서 피는 꽃이다. 밤을 되찾은 뒤 가는 비가 내리거나 안개 낀 땅거미에만 잎을 연다.","sort":102}]$J$::jsonb) as x(id text, name text, region text, node text, kind text, phase text, weather text, weather2 text, "desc" text, sort int)
  join lateral (select z.node_id, z.min_level from public.world_exploration_nodes z where z.region_id = x.region and z.node_name = x.node order by z.hierarchy_level limit 1) n on true
on conflict (meisho_id) do update set meisho_name = excluded.meisho_name, region_id = excluded.region_id, node_id = excluded.node_id, kind = excluded.kind, phase = excluded.phase,
  weather = excluded.weather, weather2 = excluded.weather2, min_level = excluded.min_level, description = excluded.description, sort = excluded.sort;
do $c$ begin
  if (select count(*) from public.world_meisho where meisho_id in (select jsonb_array_elements_text($J$["mz_dd_target_tree","mz_dd_star_plinth","mz_dd_ash_flower"]$J$::jsonb))) <> 3 then raise exception '등도 명소 답사 지점을 찾지 못했습니다'; end if;
end $c$;
insert into public.world_title_catalog(title_key, title_name, description, condition_text, bonus, hidden, rule, sort, category, grade)
