  from jsonb_to_recordset($J$[{"title_key":"dd_arrive","title_name":"흰 밤에 닿은 이","grade":3,"bonus":{"mental_loss_pct":-3},"rule":{"n":1,"p":{"region_id":"deungdo_landing"},"ev":"travel","has":"travel_history_id"},"cond":"남문 수로 선착에 닿는다","hidden":false,"description":"남문 수로 선착에 닿는다.","n":0},{"title_key":"dd_walker","title_name":"흰 거리를 걸은 이","grade":4,"bonus":{"travel_time_pct":-4,"encounter_pct":-3},"rule":{"all":[{"p":{"region_id":"dark_yamen"},"ev":"travel","has":"travel_history_id"},{"p":{"region_id":"martial_row"},"ev":"travel","has":"travel_history_id"},{"p":{"region_id":"red_shrine_lane"},"ev":"travel","has":"travel_history_id"},{"p":{"region_id":"old_ferry_market"},"ev":"travel","has":"travel_history_id"},{"p":{"region_id":"first_observatory"},"ev":"travel","has":"travel_history_id"},{"p":{"region_id":"ash_palace"},"ev":"travel","has":"travel_history_id"},{"p":{"region_id":"pact_court"},"ev":"travel","has":"travel_history_id"}]},"cond":"등도 일곱 구역에 모두 닿는다","hidden":false,"description":"등도 일곱 구역에 모두 닿는다.","n":1},{"title_key":"dd_boss_all","title_name":"일곱 등을 밝힌 이","grade":5,"bonus":{"erosion_pct":-5,"mental_loss_pct":-5,"combat_damage_pct":2},"rule":{"all":[{"p":{"monster_id":"dd_yamen_5","defeated":true},"ev":"combat"},{"p":{"monster_id":"dd_martial_5","defeated":true},"ev":"combat"},{"p":{"monster_id":"dd_shrine_5","defeated":true},"ev":"combat"},{"p":{"monster_id":"dd_ferry_5","defeated":true},"ev":"combat"},{"p":{"monster_id":"dd_obs_5","defeated":true},"ev":"combat"},{"p":{"monster_id":"dd_palace_5","defeated":true},"ev":"combat"},{"p":{"monster_id":"dd_pact_5","defeated":true},"ev":"combat"}]},"cond":"등도 일곱 구역의 우두머리를 모두 풀어 보낸다","hidden":false,"description":"등도 일곱 구역의 우두머리를 모두 풀어 보낸다.","n":2},{"title_key":"dd_alone","title_name":"홀로 흰 밤을 헤맨 이","grade":4,"bonus":{"mental_loss_pct":-4},"rule":{"n":100,"p":{"kind":"field_search","wn_alone":true},"ev":"explore"},"cond":"흰 밤 속에서 파티원 없이 100번 탐색한다","hidden":true,"description":"흰 밤 속에서 파티원 없이 100번 탐색한다.","n":3},{"title_key":"dd_wick","title_name":"심지를 모은 이","grade":3,"bonus":{"rare_loot_pct":3},"rule":{"n":50,"p":{"wick":true},"ev":"combat"},"cond":"요괴를 풀어 보내고 명등 심지를 50번 거둔다","hidden":false,"description":"요괴를 풀어 보내고 명등 심지를 50번 거둔다.","n":4},{"title_key":"dd_fish_undying_lampfish","title_name":"꺼지지 않는 이름을 낚은 이","grade":4,"bonus":{"fish_bite_pct":3},"rule":{"n":1,"p":{"fish":"undying_lampfish"},"ev":"fish"},"cond":"꺼지지 않는 등어를 낚는다","hidden":true,"description":"꺼지지 않는 등어를 낚는다.","n":5},{"title_key":"dd_fish_burrow_goldcarp","title_name":"물굴의 금빛을 낚은 이","grade":4,"bonus":{"fish_rare_pct":3},"rule":{"n":1,"p":{"fish":"burrow_goldcarp"},"ev":"fish"},"cond":"물굴 금잉어를 낚는다","hidden":true,"description":"물굴 금잉어를 낚는다.","n":6},{"title_key":"dd_named_all","title_name":"등도의 명어를 낚은 이","grade":5,"bonus":{"fish_bite_pct":4,"fish_rare_pct":8,"fish_size_pct":8},"rule":{"all":[{"p":{"fish":"undying_lampfish"},"ev":"fish"},{"p":{"fish":"burrow_goldcarp"},"ev":"fish"}]},"cond":"등도의 명어 둘을 모두 낚는다","hidden":true,"description":"등도의 명어 둘을 모두 낚는다.","n":7},{"title_key":"gg_kill1","title_name":"값을 치르지 않은 이","grade":5,"bonus":{"presence":6,"erosion_pct":-6,"combat_damage_pct":3},"rule":{"n":1,"ev":"gg_win"},"cond":"깊은 장부에서 값귀를 쓰러뜨린다","hidden":false,"description":"깊은 장부에서 값귀를 쓰러뜨린다.","n":8},{"title_key":"gg_kill10","title_name":"장부를 덮은 이","grade":5,"bonus":{"mental_loss_pct":-6,"combat_damage_pct":2},"rule":{"n":10,"ev":"gg_win"},"cond":"깊은 장부에서 값귀를 10번 쓰러뜨린다","hidden":false,"description":"깊은 장부에서 값귀를 10번 쓰러뜨린다.","n":9},{"title_key":"gg_solo","title_name":"홀로 셈을 맞춘 이","grade":5,"bonus":{"evasion_pct":2,"combat_damage_pct":3},"rule":{"p":{"solo":true},"ev":"gg_win"},"cond":"혼자 깊은 장부에서 값귀를 쓰러뜨린다","hidden":false,"description":"혼자 깊은 장부에서 값귀를 쓰러뜨린다.","n":10},{"title_key":"gg_flawless","title_name":"한 섬도 거두이지 않은 장부","grade":5,"bonus":{"healing_pct":5,"incoming_damage_pct":-3},"rule":{"p":{"flawless":true},"ev":"gg_win"},"cond":"둘 이상이 함께, 아무도 물러나지 않고 깊은 장부에서 값귀를 쓰러뜨린다","hidden":true,"description":"둘 이상이 함께, 아무도 물러나지 않고 깊은 장부에서 값귀를 쓰러뜨린다.","n":11},{"title_key":"by_kill1","title_name":"흰 밤을 걷어 낸 이","grade":5,"bonus":{"presence":6,"erosion_pct":-8,"mental_loss_pct":-4},"rule":{"n":1,"ev":"by_win"},"cond":"깊은 판에서 백야를 이긴다","hidden":false,"description":"깊은 판에서 백야를 이긴다.","n":12},{"title_key":"by_kill10","title_name":"맹약 마당의 등지기","grade":5,"bonus":{"mental_loss_pct":-6,"combat_damage_pct":3},"rule":{"n":10,"ev":"by_win"},"cond":"깊은 판에서 백야를 10번 이긴다","hidden":false,"description":"깊은 판에서 백야를 10번 이긴다.","n":13},{"title_key":"by_solo","title_name":"제 이름으로 등을 켠 이","grade":5,"bonus":{"evasion_pct":2,"combat_damage_pct":3},"rule":{"p":{"solo":true},"ev":"by_win"},"cond":"혼자 깊은 판에서 백야를 이긴다","hidden":false,"description":"혼자 깊은 판에서 백야를 이긴다.","n":14},{"title_key":"by_flawless","title_name":"일곱 등이 꺼지지 않은 밤","grade":5,"bonus":{"healing_pct":5,"incoming_damage_pct":-3},"rule":{"p":{"flawless":true},"ev":"by_win"},"cond":"둘 이상이 함께, 아무도 물러나지 않고 깊은 판에서 백야를 이긴다","hidden":true,"description":"둘 이상이 함께, 아무도 물러나지 않고 깊은 판에서 백야를 이긴다.","n":15}]$J$::jsonb)
    as x(title_key text, title_name text, grade int, bonus jsonb, rule jsonb, cond text, hidden boolean, description text, n int)
on conflict (title_key) do update set title_name = excluded.title_name, description = excluded.description, condition_text = excluded.condition_text, bonus = excluded.bonus,
  hidden = excluded.hidden, rule = excluded.rule, category = excluded.category, grade = excluded.grade;
insert into public.world_cosmetic_catalog(cosmetic_key, kind, tier, cosmetic_name, condition_text, category, rule, hidden, sort)
select x.k, x.kind, x.tier, x.name, x.cond, '명등기', x.rule, false, x.sort
  from jsonb_to_recordset($J$[{"k":"fr_white_night","kind":"frame","tier":"legend","name":"흰 밤 테","cond":"등도 일곱 구역에 모두 닿으면","rule":{"title":"dd_walker"},"sort":1510},{"k":"sl_myeongdeung","kind":"seal","tier":"legend","name":"낙관 「明燈」","cond":"등도 일곱 구역의 우두머리를 모두 풀어 보내면","rule":{"title":"dd_boss_all"},"sort":1511}]$J$::jsonb) as x(k text, kind text, tier text, name text, cond text, rule jsonb, sort int)
on conflict (cosmetic_key) do update set cosmetic_name = excluded.cosmetic_name, condition_text = excluded.condition_text, rule = excluded.rule, tier = excluded.tier, category = excluded.category;
select pg_temp.yh_patch('public.world_name_styles()', '(1031, ''cat'', ''묵적록'', 6)', '(1031, ''cat'', ''묵적록'', 6), (1034, ''cat'', ''명등기'', 6)');
insert into public.world_gathering_discoveries(owner_id, spot_id)
select c.owner_id, gs.spot_id from public.world_characters c
  cross join public.world_gathering_spots gs join public.world_exploration_nodes n on n.node_id = gs.node_id and n.hierarchy_level = 1 and n.region_id in ('deungdo_landing', 'dark_yamen', 'martial_row', 'red_shrine_lane', 'old_ferry_market', 'lamp_rest', 'first_observatory', 'ash_palace', 'pact_court', 'jeongni_vault')
on conflict do nothing;
insert into public.world_quest_npcs(npc_key, npc_name, bio)
select x.npc_key, x.npc_name, x.bio from jsonb_to_recordset($J$[{"npc_key":"q:md_gyeonghyeon","npc_name":"정리관 경현","bio":"정청 정리소의 정리관. 공손하고 느긋한 말투에 비꼬는 농담을 섞는다. 말하면서 장부 모서리를 접는 버릇이 있다."},{"npc_key":"q:md_gwak_duchil","npc_name":"곽두칠","bio":"열 해 전 흑련회에 빚을 지고 사라진 사람. 정리 명부에 이름이 올라 줄이 반만 그어진 채 먹손이 되었다."},{"npc_key":"q:md_hooded","npc_name":"두건 쓴 사람","bio":"무관 거리 우물가에서 일행의 뒤를 밟던 그림자 흐린 사람. 누군가 쥔 제 줄이 마저 그어질까 떤다."},{"npc_key":"q:md_clerk","npc_name":"불 끄는 젊은 서리","bio":"장서각에 불이 난 밤, 정청 마당에서 물동이를 나르며 소리치던 젊은 서리."},{"npc_key":"q:md_courier","npc_name":"정청 파발꾼","bio":"한설의 서신을 품고 사흘을 따라온 정청 파발꾼."},{"npc_key":"q:md_runner","npc_name":"먼 길 심부름꾼","bio":"서신과 등짐을 지고 거점 사이를 뛰어다니는 심부름꾼."},{"npc_key":"q:md_red_runner","npc_name":"적월 심부름꾼","bio":"백골 장터와 적월 사람들 사이를 오가는 심부름꾼."},{"npc_key":"q:md_lotus_runner","npc_name":"흑련 심부름꾼","bio":"검은 끈을 손목에 맨 흑련회 심부름꾼. 장부고의 말을 전한다."},{"npc_key":"q:md_south_runner","npc_name":"남명 심부름꾼","bio":"잔불촌 화로의 소식을 전하는 남명 심부름꾼."},{"npc_key":"q:md_dorm_doctor","npc_name":"객사 의원","bio":"본부 객사에서 불에 덴 사람들을 돌보는 의원."},{"npc_key":"q:md_red_doctor","npc_name":"적월 의원","bio":"백골 장터에서 무녀들을 돌보는 적월 의원."},{"npc_key":"q:md_river_doctor","npc_name":"수향 의원","bio":"구름나루에서 물에 빠진 사람과 물에 홀린 사람을 돌보는 수향 의원."},{"npc_key":"q:md_sledder","npc_name":"북령 썰매꾼","bio":"여운비의 호송대를 따라 눈 고개를 넘는 북령 썰매꾼."},{"npc_key":"q:md_gatekeeper","npc_name":"철벽 고찰 산문 지기","bio":"철벽 고찰 산문을 지키는 젊은 지기."},{"npc_key":"q:md_vault_guard","npc_name":"봉인고 문지기","bio":"봉인고 창고 문을 지키는 문지기. 정청에서 온 서신을 조사원에게 건넨다."},{"npc_key":"q:md_plate_wife","npc_name":"문패 집 아낙","bio":"구름나루 선창가에 사는 아낙. 사흘 전 아들을 물에 잃었다."},{"npc_key":"q:md_south_watch","npc_name":"잔불촌 파수꾼","bio":"불씨 고개를 바라보며 잔불촌 어귀를 지키는 남명 파수꾼."},{"npc_key":"q:md_child","npc_name":"잔불촌 아이","bio":"잔불촌 뒷산 밭에서 뛰어 내려온 아이."}]$J$::jsonb) as x(npc_key text, npc_name text, bio text)
on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, required_stats, minimum_level, rarity, acquisition_difficulty, drop_rate_modifier, equipment_traits, tradeable, reference_price, stack_size, use_fx)
select x.item_id, x.item_name, x.category, x.tier, x.description, x.stackable, x.required_stats, x.minimum_level, x.rarity, x.acquisition_difficulty, x.drop_rate_modifier, x.equipment_traits, x.tradeable, x.reference_price, x.stack_size, x.use_fx from jsonb_to_recordset($J$[{"item_id":"plank_water_jar","item_name":"뱃판 물동이","category":"material","tier":3,"description":"옛 나루 저자의 물 먹은 뱃판으로 짜고 진흙으로 틈을 메운 나무 동이다. 쇠 냄새가 배지 않아 물이 쉬 흐려지지 않는다.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"rare","acquisition_difficulty":3,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":true,"reference_price":0,"stack_size":40,"use_fx":null},{"item_id":"md_litter","item_name":"들것","category":"material","tier":3,"description":"가공 부적목 두 대에 부적실을 촘촘히 엮어 만든 들것이다. 사람 하나를 눕혀 둘이 들고 먼 길을 갈 수 있다.","stackable":true,"required_stats":{},"minimum_level":1,"rarity":"rare","acquisition_difficulty":3,"drop_rate_modifier":1,"equipment_traits":{},"tradeable":true,"reference_price":0,"stack_size":40,"use_fx":null}]$J$::jsonb) as x(item_id text, item_name text, category text, tier int, description text, stackable boolean, required_stats jsonb, minimum_level int, rarity text, acquisition_difficulty int, drop_rate_modifier numeric, equipment_traits jsonb, tradeable boolean, reference_price bigint, stack_size int, use_fx jsonb)
on conflict (item_id) do update set item_name = excluded.item_name, category = excluded.category, tier = excluded.tier, description = excluded.description, required_stats = excluded.required_stats, equipment_traits = excluded.equipment_traits, minimum_level = excluded.minimum_level, stack_size = excluded.stack_size, tradeable = excluded.tradeable, reference_price = excluded.reference_price, use_fx = excluded.use_fx;
insert into public.world_crafting_recipes(recipe_id, recipe_name, output_item, output_qty, ingredients, required_tool_tier, required_location, description, minimum_level, recipe_difficulty, quality_bonus, required_skill, required_skill_rank, craft_field)
select x.recipe_id, x.recipe_name, x.output_item, x.output_qty, x.ingredients, x.required_tool_tier, x.required_location, x.description, x.minimum_level, x.recipe_difficulty, x.quality_bonus, x.required_skill, x.required_skill_rank, x.craft_field from jsonb_to_recordset($J$[{"recipe_id":"r_plank_water_jar","recipe_name":"뱃판 물동이 만들기","output_item":"plank_water_jar","output_qty":3,"ingredients":{"waterlogged_plank":2,"resin":1},"required_tool_tier":1,"required_location":null,"description":"뱃판 물동이을(를) 만든다.","minimum_level":45,"recipe_difficulty":3,"quality_bonus":0,"required_skill":null,"required_skill_rank":1,"craft_field":"carpentry"},{"recipe_id":"r_md_litter","recipe_name":"들것 만들기","output_item":"md_litter","output_qty":1,"ingredients":{"lumber":2,"talisman_thread":2},"required_tool_tier":1,"required_location":null,"description":"들것을(를) 만든다.","minimum_level":45,"recipe_difficulty":3,"quality_bonus":0,"required_skill":null,"required_skill_rank":1,"craft_field":"carpentry"}]$J$::jsonb) as x(recipe_id text, recipe_name text, output_item text, output_qty int, ingredients jsonb, required_tool_tier int, required_location text, description text, minimum_level int, recipe_difficulty int, quality_bonus int, required_skill text, required_skill_rank int, craft_field text)
on conflict (recipe_id) do update set recipe_name = excluded.recipe_name, output_item = excluded.output_item, output_qty = excluded.output_qty, ingredients = excluded.ingredients, craft_field = excluded.craft_field, required_location = excluded.required_location, minimum_level = excluded.minimum_level, description = excluded.description, recipe_difficulty = excluded.recipe_difficulty, required_skill = excluded.required_skill, required_skill_rank = excluded.required_skill_rank;
update public.world_item_catalog i set reference_price = ceil(1.1 * (select sum(m.reference_price * (x.value)::int * 1.0 / greatest(1, cr.output_qty)) from public.world_crafting_recipes cr, jsonb_each_text(cr.ingredients) x
      join public.world_item_catalog m on m.item_id = x.key where cr.output_item = i.item_id))
 where i.item_id in (select jsonb_array_elements_text($J$["plank_water_jar","md_litter"]$J$::jsonb));
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, sort, epilogue, active)
select x.quest_id, 'side', x.cat, x.title, x.summary, x.region_id, x.min_level, array(select jsonb_array_elements_text(x.after)), x.sort, x.epilogue, true from jsonb_to_recordset($J$[{"quest_id":"mdq_1","cat":"외전·명등기","title":"불탄 서가","summary":"정청 장서각 봉인 서가에 불이 난다. 기록관 모가람이 불 속에서 반쯤 탄 종이 한 장을 품고 나오고, 정리관 경현이 그를 업고 나온다.","region_id":"hq_archive","min_level":45,"after":["mkq_5"],"sort":1400,"epilogue":[]},{"quest_id":"mdq_2","cat":"외전·명등기","title":"검은 끈","summary":"흑련 장부고. 그림자가 옅은 이들이 회주의 장부 한 권을 들고 사라졌고, 거둠꾼 월하의 손가락이 먹으로 풀린다. 정리관 경현이 공문을 들고 찾아오고, 정청에서는 두 통의 서신이 나간다.","region_id":"ledger_cellar","min_level":45,"after":["mdq_1"],"sort":1401,"epilogue":[]},{"quest_id":"mdq_3","cat":"외전·명등기","title":"두 통의 서신","summary":"북쪽 철벽 고찰과 붉은 백골 장터. 두 수장은 명령서와 한설의 편지를 함께 받아 들고 저마다 다른 셈을 한다. 북령의 여운비가 길잡이로 붙고, 적월의 단비가 스스로 따라나선다.","region_id":"iron_monastery","min_level":45,"after":["mdq_2"],"sort":1402,"epilogue":[]},{"quest_id":"mdq_4","cat":"외전·명등기","title":"다섯 갈래 길","summary":"구름나루·잔불촌·무극 관성대. 수장들은 저마다의 셈으로 사람을 붙이고, 일행은 한 사람씩 늘어 다음 거점으로 함께 간다. 다섯이 다 모여 봉인고에 닿자, 정리관 경현이 먼저 와 있다.","region_id":"river_ferry","min_level":45,"after":["mdq_3"],"sort":1403,"epilogue":[]},{"quest_id":"mdq_5","cat":"외전·명등기","title":"꺼진 관아","summary":"봉인고 아래 옛 수로에서 거룻배를 고쳐 타고, 일흔 해 동안 흰 밤 속에 있던 등도 옛터로 들어간다. 다섯은 그 땅에서 처음으로 서로의 이름을 부르고, 관아 벽에서 백 년 전 정리관의 서명을 본다.","region_id":"dark_yamen","min_level":45,"after":["mdq_4"],"sort":1404,"epilogue":[]},{"quest_id":"mdq_6","cat":"외전·명등기","title":"바람 방향","summary":"등도 북쪽 무관 거리. 북령 무관들이 살던 구역이고, 칠십 년 전 동짓밤에 종이 울린 자리다. 일행은 우물가에서 그림자 흐린 사람을 붙잡았다 놓치고, 여운비는 종루 꼭대기에서 집안이 묻은 이름을 처음 본다. 그 밤 정리관이 혼자 모닥불을 찾아온다.","region_id":"martial_row","min_level":46,"after":["mdq_5"],"sort":1405,"epilogue":[]},{"quest_id":"mdq_7","cat":"외전·명등기","title":"묻은 이름","summary":"북령 철벽 고찰. 얼음 인장 아래에 둘째 장이 집안이 묻은 이름과 함께 얼어 있다. 여운비가 그 이름을 처음 부르고, 주인공이 「이을 이」 칸에 이름을 적자 일행은 왜 함께 다녀야 하는지를 처음으로 제대로 안다.","region_id":"iron_monastery","min_level":46,"after":["mdq_6"],"sort":1406,"epilogue":[]},{"quest_id":"mdq_8","cat":"외전·명등기","title":"끊긴 기름","summary":"등도 서쪽 붉은 사당 골목. 적월 무리 「달 지기」가 등도의 등에 기름을 대던 구역이다. 단비는 사당 벽에서 적월이 백 년 동안 거꾸로 외워 온 서약을 읽고, 그 밤 처음으로 제 죄를 일행 앞에 내놓는다.","region_id":"red_shrine_lane","min_level":47,"after":["mdq_7"],"sort":1407,"epilogue":[]},{"quest_id":"mdq_9","cat":"외전·명등기","title":"달 반쪽","summary":"적월 교주 월화의 가슴에 셋째 장이 꿰매져 있다. 장을 꺼내려면 서약을 거꾸로 돌려야 하고, 거꾸로 도는 서약은 이름 하나를 값으로 받는다. 월화는 그 값을 이미 정해 두었다.","region_id":"bone_market","min_level":47,"after":["mdq_8"],"sort":1408,"epilogue":[]},{"quest_id":"mdq_10","cat":"외전·명등기","title":"마른 물길","summary":"등도 동쪽 옛 나루 저자. 물이 빠진 물길 위에 배들이 얹혀 있는 수향 무리의 옛 구역이다. 일행은 거꾸로 돈 서약에 반쪽을 먹힌 단비를 업고, 교주 월화가 일러 준 「이름을 실어 나르던 물」을 찾아온다. 그 물 밑에는 수향이 일흔 해 동안 감춰 온 배가 있다.","region_id":"old_ferry_market","min_level":48,"after":["mdq_9"],"sort":1409,"epilogue":[]},{"quest_id":"mdq_11","cat":"외전·명등기","title":"값을 치른 배","summary":"옛 나루 저자 우물 밑 물굴. 수향이 가라앉힌 배에서 넷째 장을 건진다. 청파는 장과 함께 묻힌 「태우지 못한 아이들」의 명단을 건지러 다시 내려가고, 숨이 끊긴 청파를 건져 올린 것은 정리관의 배였다.","region_id":"old_ferry_market","min_level":48,"after":["mdq_10"],"sort":1410,"epilogue":[]},{"quest_id":"mdq_12","cat":"외전·명등기","title":"잘못 읽은 별","summary":"등도 남쪽 끝 첫 관상대와 무극 관성대. 백 년 전 천명원은 별을 잘못 읽었고, 그 말 한마디로 칸이 긁혔다. 스무 해 전에는 한 아기의 이름이 사람의 명부가 아니라 별 기록 속에 숨겨졌다.","region_id":"first_observatory","min_level":49,"after":["mdq_11"],"sort":1411,"epilogue":[]},{"quest_id":"mdq_13","cat":"외전·명등기","title":"앉게","summary":"정청. 안쪽 방은 도제조 백운서의 심지가 타는 방이다. 묵창 나루 밤 뒤로 심지가 짧아져 그 등잔 곁을 떠나지 못하던 그는, 장서각 불이 난 뒤로 방문을 열어 둔 채 앉아 있다. 하루 한 번만 입을 여는 그에게 일행은 모은 흔적을 하나씩 들고 들어간다. 그사이 감찰관 한설은 고쳐 쓴 보고서를 들고 정청에 돌아오고, 일행은 그 보고서를 들고 정리소 문을 연다.","region_id":"hq_yard","min_level":49,"after":["mdq_12"],"sort":1412,"epilogue":[]},{"quest_id":"mdq_14","cat":"외전·명등기","title":"첫 부름이","summary":"잔불촌 화로 앞의 장무현에게 붉은 줄이 그어졌다. 일행은 사흘 동안 번갈아 그 이름을 부르고, 장무현은 화로 속의 다섯째 장을 꺼내 갈매에게 건넨다. 「마지막 아이」의 까닭이 풀리고, 잿빛 왕궁 터의 동틀 녘에 장무현이 먹으로 풀린다.","region_id":"ember_village","min_level":49,"after":["mdq_13"],"sort":1413,"epilogue":[]},{"quest_id":"mdq_15","cat":"외전·명등기","title":"검은 끈의 장","summary":"갈매가 쪽지 한 장을 남기고 사라진다. 일행은 불씨 고개에서 갈매를 찾아 함께 장무현의 옷을 묻는다. 흑련 장부고 밑 먹 도랑을 거슬러 정리소 금고에 닿아, 먹손들이 지키는 검은 끈 장부와 일곱째 장을 되찾는다. 월하가 깨어난다.","region_id":"ledger_cellar","min_level":50,"after":["mdq_14"],"sort":1414,"epilogue":[]},{"quest_id":"mdq_16","cat":"외전·명등기","title":"맹약 마당","summary":"일곱 장을 품고 등도로 돌아온 일행은 싸움 전날 밤 서로의 이름을 몸에 써 준다. 맹약 마당에서 정리관 경현이 먹 도랑의 먹을 몸에 받아들여 흰 밤 「백야」가 된다. 여운비가 주인공의 이름에 그어진 붉은 줄을 대신 맞고, 일행은 그의 몸에 붙은 이름을 하나씩 불러 떼어 낸다.","region_id":"pact_court","min_level":50,"after":["mdq_15"],"sort":1415,"epilogue":[]},{"quest_id":"mdq_17","cat":"외전·명등기","title":"명등","summary":"진이 꺼지고 일곱 장이 재가 된다. 서하람은 두 눈을 잃고, 경현은 문틈을 막으러 먹 도랑으로 내려간다. 백운서가 등도의 밤을 보며 눈을 감고, 여운비가 깨어난다. 그해 동짓밤 첫 명등제가 열린다.","region_id":"pact_court","min_level":50,"after":["mdq_16"],"sort":1416,"epilogue":[]}]$J$::jsonb) as x(quest_id text, kind text, cat text, title text, summary text, region_id text, min_level int, after jsonb, sort int, epilogue jsonb, active boolean)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, epilogue = excluded.epilogue, active = excluded.active;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward)
select x.quest_id, x.step, x.title, x.goal, x.need, x.lines, x.reward from jsonb_to_recordset($J$[{"quest_id":"mdq_1","step":1,"title":"밤의 종","goal":"본부 정청 마당에서 비상 종소리를 듣는다","need":{"at":["hq_yard"]},"lines":[{"s":null,"t":"땡, 땡, 땡그랑. 정청 마당의 비상 종소리가 잠을 깨웠다."},{"s":null,"t":"세 번째 소리는 길게 끌리다가 뚝 끊겼다. 종채를 쥔 손이 미끄러진 것 같았다."},{"s":null,"t":"객사 문을 밀고 나서자 뜨거운 바람이 얼굴을 확 덮쳤다. 종이와 아교가 타는 매캐한 냄새에 목구멍이 따끔거렸다."},{"s":null,"t":"장서각 쪽 하늘이 벌겋게 일렁였다. 기와 틈마다 연기가 실처럼 비집고 나와 지붕 위에서 시커멓게 뭉쳤다."},{"s":null,"t":"맨발의 서리들이 물동이를 들고 계단을 오르내렸다. 누군가 미끄러지며 쏟은 물이 돌바닥에서 치익 소리를 내며 김이 되었다."},{"s":null,"t":"마당 저쪽에서 젊은 서리 하나가 목이 터져라 소리쳤다."},{"s":"q:md_clerk","t":"물! 물 더 가져와요! 서가 쪽 계단으로요! 연기가 내려가는 길을 막고 있어요!"},{"s":null,"t":"물동이를 받아 나르던 여자 하나가 나를 보고 걸음을 멈췄다. 붉은 인장 일 때 내 담당 서기관이던 연서희였다. 요즘은 정청 서당에서 아이들 글을 가르친다고 들었다. 걷어붙인 소매가 팔꿈치까지 젖어 있었다."},{"s":"q:m_yeon","t":"{이름} 님! 객사에 묵고 있었어요? 서고 쪽은 연기가 계단까지 찼대요. 설마 또 거기로 들어가려는 거 아니죠?"},{"s":null,"t":"나는 감찰관을 따라가 봐야 한다고 했다. 연서희가 한숨을 쉬더니 내 소매 끝을 물동이에 푹 담갔다가 꺼냈다."},{"s":"q:m_yeon","t":"연기 마실 땐 이걸로 입을 막아요. 목도리는 이번엔 안 빌려줘요. 돌려받는 데 석 달 걸렸으니까요. …꼭 나와요."},{"s":null,"t":"고함과 발소리 한가운데, 대청 섬돌 위에 감찰관 한설이 서 있었다. 모두가 장서각으로 쏠려 가는데 한설만 제자리였다."},{"s":null,"t":"한설은 붓을 소매 끝으로 천천히 닦고 있었다. 불빛에 반쯤 붉어진 얼굴이 돌처럼 굳어 있었다."},{"s":null,"t":"나를 알아본 한설이 붓을 닦던 손을 멈췄다."},{"s":"night_office:han","t":"조사원, 마침 잘 왔다. 손이 하나라도 더 있어야 하는 밤이다.","fac_not":"night_office","spec":2,"grp":1},{"s":"night_office:han","t":"조사원, 마침 잘 왔다. 정통파 패를 받은 지 얼마 안 됐을 테니 오늘 밤은 내 뒤에 바짝 붙어 있어라.","fac":"night_office","rank":[1,2],"spec":0,"grp":1},{"s":"night_office:han","t":"조사원, 마침 잘 왔다. {등급}이면 봉인 서가 출입패가 있겠지. 서리들을 시켜 문을 따느니 네 패로 여는 게 빠르겠다.","fac":"night_office","rank":[3,4],"spec":0,"grp":1},{"s":"night_office:han","t":"조사원, 마침 잘 왔다. 판관께서 오셨으니 오늘 밤 일은 나 혼자 장부에 적지 않아도 되겠군.","fac":"night_office","rank":[5,5],"spec":0,"grp":1},{"s":"night_office:han","t":"지하서고 봉인 서가에 불이 났다. 물은 서리들이 붓는다. 너는 나랑 같이 불이 어디서 시작됐는지 보러 가자."},{"s":null,"t":"나는 불부터 끄는 게 먼저가 아니냐고 물었다. 한설이 장서각 쪽으로 턱을 들었다."},{"s":"night_office:han","t":"봉인 서가에는 등잔을 두지 않는다. 불씨가 들어갈 틈이 없는 곳이야. 누가 불을 손에 들고 들어갔다는 얘기지. 그놈이 아직 안에 있을지도 모르고."},{"s":null,"t":"한설이 붓을 품에 꽂고 섬돌을 내려섰다. 뛰지는 않았지만 걸음이 평소보다 빨랐다."},{"s":null,"t":"장서각 문 앞에서 서리 문수가 빈 물동이를 끌어안고 덜덜 떨고 있었다. 우리를 보자 문수가 울음 섞인 소리를 질렀다."},{"s":"q:dh_munsu","t":"감찰관님! 기록관님이 아직 안에 계세요! 불이 나자마자 서가 쪽으로 뛰어 들어가셨거든요. 나오시라고 그렇게 불렀는데요…!"},{"s":null,"t":"한설의 걸음이 처음으로 흐트러졌다. 한설이 문수의 어깨를 붙잡았다."},{"s":"night_office:han","t":"모가람이? 왜 그 사람이 거길… 조사원, 서둘러라. 연기가 계단을 다 막기 전에 내려가야 한다."}],"reward":{}},{"quest_id":"mdq_1","step":2,"title":"불 속의 품","goal":"장서각 지하서고에 도착해 연기 속을 2번 탐색하며 봉인 서가로 가는 길을 찾는다","need":{"at":["hq_archive"],"tasks":[{"t":"travel","r":["hq_archive"],"n":1},{"t":"search","r":["hq_archive"],"n":2}]},"lines":[{"s":null,"t":"계단을 한 칸 내려갈 때마다 열기가 얼굴을 짓눌렀다. 젖은 소매로 입을 막아도 뜨거운 재가 혀끝에 내려앉았다."},{"s":null,"t":"바닥에는 물과 재가 섞인 잿물이 발목까지 찰랑였다. 미지근하게 데워진 물이었다."},{"s":null,"t":"연기 저편으로 누군가의 뒷모습이 지나갔다. 서고 맨 끝 어둠 쪽으로 미끄러지듯 멀어지는 사람이었다."},{"s":null,"t":"불빛이 그 사람을 비추는데도 발밑의 그림자가 반쯤밖에 없었다. 축 늘어뜨린 손끝이 먹을 찍은 듯 새까맸다."},{"s":null,"t":"나는 거기 서라고 소리치며 그 뒤를 쫓았다. 서너 걸음 만에 연기가 확 덮쳐 와 눈앞이 캄캄해졌다."},{"s":null,"t":"연기가 걷혔을 때 그 사람은 없었고, 철벅, 철벅, 젖은 발소리만 서고 끝 쪽으로 멀어져 갔다."},{"s":null,"t":"한설이 내 어깨를 붙잡았다. 한설의 눈도 그 어둠에 박혀 있었다."},{"s":"night_office:han","t":"봤나? 그림자가… 아니, 지금은 사람부터다. 쫓는 건 나중이야."},{"s":null,"t":"봉인 서가 여섯 칸 가운데 맨 안쪽 한 칸이 통째로 주저앉아 있었다. 숯이 된 기둥이 벌겋게 숨을 쉬며 타닥타닥 불티를 튀겼다."},{"s":null,"t":"무너진 서가 앞에 기록관 모가람이 웅크리고 있었다. 무언가를 가슴에 끌어안고 쏟아지는 불티를 등으로 받아 내고 있었다."},{"s":null,"t":"품을 감싼 두 손이 벌겋게 부풀었고, 군데군데 살갗이 하얗게 일어나 있었다."},{"s":null,"t":"그 품에서 불빛과 다른 빛이 새어 나왔다. 끝이 그을린 두꺼운 닥종이 한 장 위에 손바닥만 한 흰 불꽃이 떠 있었다."},{"s":null,"t":"사방이 타는데 그 불꽃만은 조금도 흔들리지 않았다. 종이를 태우지도 않았고, 타는 소리도 냄새도 없었다."},{"s":null,"t":"나는 불꽃 가까이 손을 대 보았다. 뜨겁지도 차갑지도 않았다. 손등에 아무 느낌도 없다는 것이 오히려 소름 끼쳤다."},{"s":null,"t":"모가람이 고개를 들었다. 그을음투성이 얼굴로 웃으려 했지만 입꼬리가 덜덜 떨렸다."},{"s":"night_office:mo","t":"아, 조사원님…! 오셨어요? 보리차라도 내 드려야 하는데, 오늘은 손이 이래서요."},{"s":null,"t":"바로 그때 머리 위에서 우지끈 소리가 났다. 불붙은 들보 하나가 모가람 쪽으로 기울었다."},{"s":null,"t":"나는 모가람의 어깨를 잡아 옆으로 확 끌어당겼다. 쿵! 들보가 방금까지 모가람이 있던 자리에 떨어지며 불티를 뿜었다."},{"s":null,"t":"내 뒤에서 한설이 숨을 들이켰다. 한설이 잿물을 철벅철벅 헤치며 달려왔다."},{"s":"night_office:han","t":"기록관! 정신이 있는 거야, 없는 거야! 그걸 놓고 당장 나와!"},{"s":null,"t":"모가람은 종이를 더 깊이 끌어안았다. 데인 손가락이 종이에 스칠 때마다 어깨가 움찔거렸다."},{"s":"night_office:mo","t":"못 놔요. 서른 해 동안 매일 그 앞을 지나다닌 상자에 들어 있던 거예요. 반은 벌써 탔어요. 남은 반은 제가 쥐고 있어야 해요."},{"s":null,"t":"계단 쪽에서 다급한 발소리가 쿵쿵 내려왔다. 물동이 두 개를 양손에 든 사내 하나가 잿물을 헤치며 다가왔다."},{"s":null,"t":"쉰 남짓 되어 보이는 사내였다. 회색 관복 차림에 이마와 콧등이 그을음으로 얼룩져 있었다."},{"s":null,"t":"사내는 아무 말 없이 물 한 동이를 모가람의 등에 쏟았다. 치이익, 등에 붙은 불티가 한꺼번에 꺼지며 하얀 김이 솟았다."},{"s":"q:md_gyeonghyeon","t":"기록관, 실례하겠소. 업히시오. 그 종이는 품에 그대로 두셔도 되오."},{"s":null,"t":"사내가 모가람을 등에 업고 일어섰다. 남은 물동이 하나는 발로 밀어 내 앞에 보냈다."},{"s":"q:md_gyeonghyeon","t":"그건 당신 몫이오. 계단에 불길이 붙었으니 길을 열어 주시오."},{"s":null,"t":"나는 물동이를 들어 계단 앞 불길에 끼얹었다. 치익, 불길이 주저앉으며 길이 열렸다."},{"s":null,"t":"마당으로 나오자 사내가 모가람을 의원 쪽 서리들에게 조심스레 넘겼다. 사내는 품에서 젖은 수건 한 장을 꺼내 내게 내밀었다."},{"s":"q:md_gyeonghyeon","t":"얼굴부터 닦으시오. 그을음이 눈에 들어가면 사흘은 고생하오."},{"s":null,"t":"수건을 건넨 사내가 그을음 사이로 내 얼굴을 찬찬히 뜯어보았다. 무언가를 장부와 맞춰 보는 눈이었다."},{"s":"q:md_gyeonghyeon","t":"묵창 나루 서리가 명부에 새 칸을 긋고 거기 당신 이름을 적었다는 이야기는 들었소. 그 밤에 당신 이름이 우리 서고의 장을 흔들었다지요."},{"s":null,"t":"나는 수건을 받다 말고 사내를 보았다. 처음 보는 얼굴이었는데, 사내는 내 이름도 묵창 나루의 일도 알고 있었다."},{"s":null,"t":"한설이 사내 앞으로 다가서서 고개를 깊이 숙였다."},{"s":"night_office:han","t":"…스승님."},{"s":null,"t":"사내가 바닥에 떨어진 반쯤 탄 장부 사본 한 장을 주웠다. 그 오른쪽 위 모서리를 반듯하게 한 번 접어 한설에게 내밀었다."},{"s":"q:md_gyeonghyeon","t":"서가에서 날려 나온 것이오. 감찰관이 챙기시오. 오늘 밤 불에 탄 종이는 기록관이 품은 그 한 장으로 충분하오."},{"s":null,"t":"사내는 소매에 앉은 재를 털고 대청 쪽으로 걸어갔다. 불난 마당을 가로지르는데도 걸음이 느긋했다."},{"s":null,"t":"나는 한설에게 저 사람이 누구냐고 물었다. 한설이 접힌 모서리를 엄지로 한 번 쓸었다."},{"s":"night_office:han","t":"정리관 경현. 내 스승이시다. 그때는 기록감찰국 교수관이셨지. 고친 글씨는 먹이 두 번 앉는다는 걸 가르쳐 주신 분이야. 그분 아니었으면 나는 감찰관이 못 됐어."},{"s":null,"t":"나는 정리관이 무슨 일을 하는 자리냐고 물었다. 한설이 대답하려다 입을 다물었다."},{"s":"night_office:han","t":"…명부 일을 맡는 자리다. 생긴 지 일 년밖에 안 됐어."},{"s":null,"t":"한설이 무언가 더 말하려다 붓을 쥔 손에 힘을 주었다. 붓대가 손안에서 삐걱 소리를 냈다."},{"s":"night_office:han","t":"그 이상은… 지금 내 입으로 말하기 어렵다. 묻지 마라."},{"s":null,"t":"저쪽에서 의원이 모가람의 손을 보고 고개를 젓는 것이 보였다. 한설이 그쪽을 보며 이를 악물었다."},{"s":"night_office:han","t":"지금은 기록관 손이 급하다. 객사 의원은 쑥과 약초를 달인 고약을 쓰는데, 오늘 밤 다친 서리가 열이 넘어서 의원 혼자로는 모자라. 조사원, 네가 약초를 모아서 농축 약초액을 내다 줘라. 의원이 그걸로 고약을 갤 거다."},{"s":null,"t":"객사 의원의 고약은 농축 약초액에 기름을 섞어 개는 것이라, 약초액만 넉넉하면 의원 손으로 금방 지을 수 있었다."}],"reward":{"xp":2880}},{"quest_id":"mdq_1","step":3,"title":"들지 못한 찻잔","goal":"야령초 6개를 모아 농축 약초액 2개를 만들고 본부 객사의 의원에게 넘긴다","need":{"at":["hq_dorm"],"tasks":[{"t":"gather","n":6,"items":["herb"]},{"t":"craft","items":["herbal_extract"],"n":2}],"give":{"herbal_extract":2}},"lines":[{"s":null,"t":"객사 의원 방은 쑥 달이는 김으로 뿌옜다. 화로 위 약탕기가 보글보글 끓었다."},{"s":null,"t":"한설은 서고 뒷정리를 서리들에게 맡기고 와서 방 한쪽 걸상에 앉아 있었다. 늘 쥐고 다니는 붓을 아무 말 없이 닦고 있었다."},{"s":null,"t":"의원이 내가 내 온 농축 약초액으로 고약을 개어 모가람의 두 손에 두껍게 발랐다. 그 위로 무명을 감자 열 손가락이 하얗고 뭉툭해졌다."},{"s":null,"t":"의원은 붕대 끝을 묶고도 한참 손을 놓지 않았다. 의원이 모가람이 아니라 나를 보았다."},{"s":"q:md_dorm_doctor","t":"살갗은 아물 겁니다. 다만 손가락 마디가 다시 굽을지는… 장담을 못 하겠습니다."},{"s":null,"t":"모가람은 그 말을 못 들은 척 붕대 감긴 손을 무릎에 얹었다. 흰 불꽃이 뜬 종이가 그 무릎 위에 펼쳐져 있었다."},{"s":"night_office:mo","t":"조사원님, 고약 고마워요. 보리차 한 잔 드실래요? 이번엔 진짜로 내 드릴게요."},{"s":null,"t":"모가람이 탁자 위 찻주전자로 손을 뻗었다. 붕대 감긴 손가락이 손잡이를 감싸지 못하고 툭 미끄러졌다."},{"s":null,"t":"찻주전자가 기우뚱 기울었다. 나는 얼른 주전자를 받쳐 들었다. 식은 보리차가 주둥이에서 찰랑 넘칠 뻔했다."},{"s":null,"t":"모가람이 제 손을 내려다보며 웃으려 했지만, 끝내 웃지 못했다."},{"s":"night_office:mo","t":"…허, 참. 서른 해 동안 남한테 차를 따라 주기만 했는데요. 이제 보니 그게 큰 재주였네요."},{"s":null,"t":"나는 잔에 보리차를 따라 모가람의 입가에 대 주었다. 모가람이 잠깐 망설이다가 한 모금 마셨다."},{"s":"night_office:mo","t":"식었네요. 늘 식은 걸 드렸는데, 받아 마시는 쪽은 이런 맛이었구나."},{"s":null,"t":"모가람이 두 모금째를 마시고 숨을 길게 내쉬었다. 눈길이 무릎 위 불꽃으로 내려갔다."},{"s":"night_office:mo","t":"조사원님, 저는 서른 해 동안 그 서가를 지켰어요. 해마다 동지가 지나면 서고 맨 아래 칸에서 장부 사본이 한 권씩 올라왔어요. 저는 그걸 정서해서 봉인 서가에 꽂았고요."},{"s":null,"t":"나는 맨 아래 칸이 어디냐고 물었다. 모가람이 찻잔 쪽으로 눈을 돌렸다가 다시 나를 보았다."},{"s":"night_office:mo","t":"아무도 내려가지 않는 칸이요. 그곳 사람들은 자기네를 정리소라고 불러요. 무슨 장부인지는… 묻지 않았어요. 아니, 실은 알았어요. 알면서 웃으며 보리차를 내밀었죠."},{"s":"night_office:mo","t":"붉은 인장 일 때 기억나세요? 남쪽 등대들이 꺼지던 해에, 제가 서희한테 명부 정리 얘기를 했잖아요. 조사원님도 곁에서 들으셨고요. 부를 사람도 제사를 이을 사람도 없는 이름부터 거둔다고요. 그 명부가 올라오던 데가 거기예요."},{"s":null,"t":"방 한쪽에서 붓을 닦던 한설의 손이 「정리소」라는 말에 멈췄다. 한설은 아무 말 없이 다시 붓을 닦았다."},{"s":"night_office:mo","t":"오늘 밤 불나기 직전에 그 칸에서 누가 올라왔어요. 등불도 없이 걸어오는데 발밑에서 철벅, 철벅 젖은 소리가 났어요. 제가 소리를 지르니까 서가에 불을 붙이고 아래로 사라졌어요."},{"s":null,"t":"나는 서고 끝에서 그림자가 반쯤밖에 없는 사람을 보았다고 했다. 쫓아갔지만 연기 속에서 놓쳤다고도 했다. 모가람이 숨을 삼켰다."},{"s":"night_office:mo","t":"그림자가요? 서른 해를 서고에 있었지만 그런 사람 얘기는 처음 들어요. 저는 연기 때문에 발소리밖에 못 들었어요. …정리관 어르신 등에 업혀 나온 것만 어렴풋이 기억나요. 등이 참 넓더라고요. 고맙다는 말도 못 했네요."},{"s":null,"t":"모가람이 붕대 낀 손으로 종이의 그을린 끝을 감쌌다. 다친 짐승을 쓰다듬는 손짓이었다."},{"s":"night_office:mo","t":"사실 이 상자가 이상했던 건 오늘이 처음이 아니에요. 몇 달 전 어느 밤에, 상자 뚜껑 틈으로 흰빛이 새어 나와서 한 번 크게 흔들렸어요. 서른 해 동안 처음 본 일이었어요."},{"s":"night_office:mo","t":"며칠 뒤에 소식이 왔어요. 바로 그 밤에 묵창 나루의 희수 서리가 다온이라는 아이 이름 옆에 「불러 주는 이」 칸을 긋고, 그 칸에 조사원님 이름을 적었다고요. 백 년 동안 정청 명부에 없던 칸이래요."},{"s":null,"t":"나는 그 밤을 떠올렸다. 명부 탑 아래 뜰에서 깨어났을 때 다온이 공책을 펼쳐 내 이름을 짚어 주었고, 희수가 마지막 획까지 똑바로 그 이름을 적었다."},{"s":null,"t":"나는 종이 쪽으로 손을 내밀어 보았다. 바람 한 점 없는 방인데도 흰 불꽃이 내 손 쪽으로 살며시 기울었다."},{"s":"night_office:mo","t":"보세요, 또 이래요. 이 장이 조사원님 이름에 대답하는 거예요. 저는 그렇게 믿어요."},{"s":null,"t":"그때 문이 벌컥 열렸다. 빈 물동이를 든 문수가 문턱에 걸려 휘청이며 뛰어들었다."},{"s":"q:dh_munsu","t":"기록관님, 괜찮으세요? 아, 괜찮으실 리가 없지요, 죄송해요! 그게 아니라요, 지금 정청 안쪽이 난리거든요."},{"s":"q:dh_munsu","t":"도제조께서 지키시는 안쪽 방 등잔 있잖아요. 그게 불나기 조금 전에 또 깜빡였대요! 묵창 나루에서 칸이 그어지던 그 밤에, 삼백 년 만에 처음 깜빡였다던 그 등잔이요. 그 뒤로 서리들이 밤마다 번갈아 지켰는데, 오늘 밤 지키던 서리는 그걸 보고 그 자리에 털썩 주저앉았거든요."},{"s":null,"t":"모가람이 숨을 훅 들이켜며 무릎 위의 종이를 내려다보았다. 방 한쪽에서 한설의 붓이 다시 멈췄다가, 아까보다 훨씬 느리게 움직였다."},{"s":"night_office:han","t":"문수야, 그 얘기는 이 방에서 끝내라. 밖에서 한 번만 더 꺼내면 그때는 장부에 적을 거다."},{"s":null,"t":"문수가 입술을 꾹 깨물고 물동이를 끌어안았다. 한설이 붓을 거두고 나를 보았다."},{"s":"night_office:han","t":"조사원, 기록관이 들었다는 젖은 발소리를 따라가 보자. 날이 밝으면 서리들이 재를 다 쓸어 버린다. 발자국도, 타다 남은 종이도 그 전에 찾아야 해."}],"reward":{"xp":2880}},{"quest_id":"mdq_1","step":4,"title":"재 속의 인장","goal":"장서각 지하서고를 4번 탐색해 재 속의 젖은 발자국과 타다 남은 종이를 찾는다","need":{"at":["hq_archive"],"tasks":[{"t":"search","r":["hq_archive"],"n":4}]},"lines":[{"s":null,"t":"불이 꺼진 지하서고는 다른 곳 같았다. 뜨겁던 공기가 식으며 축축하게 가라앉았다."},{"s":null,"t":"숯 더미에서 이따금 픽, 픽 김 빠지는 소리가 났다. 그 소리 말고는 사방이 고요했다."},{"s":null,"t":"한설과 나는 무릎을 꿇고 재를 손으로 헤쳤다. 한설은 감찰관 관복 소매를 팔꿈치까지 둘둘 걷어 올렸다."},{"s":null,"t":"재 위에 젖은 발자국이 여럿 찍혀 있었다. 가장자리가 검게 번진 자국이었다."},{"s":null,"t":"한설이 그 자국을 손끝으로 문질렀다. 손끝이 먹을 찍은 것처럼 까매졌다."},{"s":"night_office:han","t":"먹이군. 갓 간 먹이 아니야. 오래 고여서 썩은 물 냄새가 난다."},{"s":null,"t":"나는 숯 더미 밑에서 손톱만 한 종잇조각 하나를 찾아냈다. 붉은 인장의 한 귀퉁이가 남아 있었다."},{"s":null,"t":"한설이 조각을 받아 등잔 가까이 가져갔다. 한참 들여다보던 눈이 커졌다."},{"s":"night_office:han","t":"이 인장… 도제조 인장이랑 생김새가 같다. 획 하나 다르지 않아. 그런데 그 상자는 정청이 세워진 날부터 있었다고 했지."},{"s":null,"t":"나는 그럼 삼백 년 전에도 같은 인장을 썼던 거냐고 물었다. 한설이 조각을 수첩 사이에 끼웠다."},{"s":"night_office:han","t":"인장은 대를 이어 쓰기도 한다. …그렇게 적어 두마. 지금은 그 정도밖에 말 못 하겠다."},{"s":null,"t":"한참 재를 헤치던 한설이 손등으로 이마의 땀을 훔쳤다. 이마에 시커먼 줄이 쭉 그어졌다."},{"s":null,"t":"나는 아까 받은 수건을 내밀었다. 한설이 수건을 보더니 피식 웃었다. 한설이 웃는 것을 나는 그날 처음 보았다."},{"s":"night_office:han","t":"스승님 수건이구나. 그분은 늘 수건을 두 장 갖고 다니셨다. 하나는 자기 거, 하나는 남 줄 거."},{"s":null,"t":"나는 한설에게 스승님은 어떤 분이냐고 물었다. 한설이 수건으로 이마를 꾹꾹 누르며 대답했다."},{"s":"night_office:han","t":"열다섯 해 전 내가 정청에 갓 들어왔을 때, 붓 하나 살 돈이 없었다. 그분이 쓰던 붓을 쥐여 주면서 그러셨지. 「적는 사람은 잊으면 안 되오. 그러니 이름은 한 번 들으면 외우시오.」"},{"s":"night_office:han","t":"그 붓으로 첫 보고서를 써 갔더니, 내가 한 글자 고친 자리를 손끝으로 짚으셨다. 「고친 글씨는 먹이 두 번 앉소. 고칠 거면 고쳤다고 적으시오.」 나는 그날 들은 두 마디로 지금까지 감찰관 일을 한다."},{"s":"night_office:han","t":"그분은 지금도 정청 사람 이름을 하나도 안 잊으신다. 처음 보는 네 이름도 벌써 알고 계시더구나. 이제 평생 안 잊으실 거다."},{"s":null,"t":"한설이 수건을 돌려주려다 손을 멈추고는, 수건을 접어 제 품에 넣었다."},{"s":"night_office:han","t":"빨아서 돌려드려야겠다. 그을음 묻은 걸 그냥 드릴 수는 없지."},{"s":null,"t":"발자국은 서고 맨 끝 배수 우물 쪽으로 이어져 있었다. 내가 아까 그 사람을 놓친 쪽이었다. 우물의 돌 뚜껑이 반쯤 밀려나 있었다."},{"s":null,"t":"한설이 수첩에서 빈 종이 한 장을 뜯어 발자국 위에 꾹 눌렀다. 종이를 떼자 먹 자국이 고스란히 찍혀 나왔다."},{"s":null,"t":"한설이 그 종이를 반으로 접어 내게 내밀었다."},{"s":"night_office:han","t":"조사원, 이건 네가 지니고 있다가 기록관한테 보여라. 서고 먹 냄새는 그 사람이 정청에서 제일 잘 안다."},{"s":null,"t":"한설이 일어나 무릎의 재를 털고 우물 쪽으로 턱짓을 했다."},{"s":"night_office:han","t":"기록관한테 가기 전에 할 일이 하나 더 있다. 발자국이 저기서 끊겼어. 물길로 내려갔다는 거지. 네가 두레박을 내려서 물부터 떠 봐라. 그 물이 어디서 오는지 알아야 따라갈 수 있다."}],"reward":{"xp":2880}},{"quest_id":"mdq_1","step":5,"title":"검은 우물","goal":"장서각 지하서고 끝 우물에서 1번 낚시해 물을 떠 본다","need":{"at":["hq_archive"],"tasks":[{"t":"fish","n":1,"r":["hq_archive"]}]},"lines":[{"s":null,"t":"두레박 줄이 한참이나 풀려 나갔다. 스르르, 스르르 끝없이 내려가다가 퐁, 하고 멀리서 소리가 났다."},{"s":null,"t":"끌어 올린 물은 먹을 풀어 놓은 듯 새카맸다. 두레박 바닥이 보이지 않았다."},{"s":null,"t":"나는 물을 한 움큼 떠서 손등에 흘려 보았다. 얼음을 댄 것처럼 시렸다."},{"s":null,"t":"물이 닿은 자리가 잿빛으로 바래 갔다. 살갗이 오래된 종이 색이 되었다."},{"s":null,"t":"손가락으로 그 자리를 꾹 눌러 보았는데 아무 느낌도 없었다. 남의 손을 누르는 것 같았다."},{"s":null,"t":"숨을 몇 번 쉬고 나서야 바랜 자리에 핏기가 천천히 돌아왔다. 찌르르 저린 감각도 함께 돌아왔다."},{"s":null,"t":"서가 앞에 쭈그려 앉아 발자국 둘레를 수첩에 옮겨 그리던 한설이 그제야 고개를 들었다. 잿빛이 된 내 손등을 본 한설이 붓을 내던지고 달려와 내 손목을 낚아챘다."},{"s":"night_office:han","t":"이 바보야, 맨손으로 그걸 왜 만져! …괜찮나? 손가락 움직여 봐."},{"s":null,"t":"나는 손가락을 쥐었다 폈다 해 보였다. 한설이 그제야 내 손목을 놓았다."},{"s":"night_office:han","t":"이 우물은 정청이 세워진 날부터 있던 거다. 지난달에 내가 이 물로 먹을 갈았어. 그때는 맑았다. 내가 장담한다."},{"s":null,"t":"우물 안쪽 벽에 쇠 손잡이가 사다리처럼 박혀 어둠 속으로 이어져 있었다. 손잡이 하나에 종이 한 조각이 걸려 팔랑거렸다."},{"s":null,"t":"한설이 팔을 뻗어 그 종이를 떼어 냈다. 한설의 앞머리도 아래에서 올라오는 바람에 살랑 흔들렸다."},{"s":"night_office:han","t":"팔랑거리는구나. 아래에서 바람이 올라온다는 거다. 우물 밑이 막힌 데가 아니라는 얘기지."},{"s":null,"t":"한설이 떼어 낸 종이는 반쯤 탄 장부 사본 한 쪽이었다. 적힌 이름마다 붉은 줄이 그어져 있었다. 오른쪽 위 모서리가 반듯하게 한 번 접혀 있었다."},{"s":null,"t":"한설이 품에서 아까 스승이 건넨 사본을 꺼냈다. 두 장의 접힌 모서리를 나란히 맞대 보았다."},{"s":null,"t":"접힌 너비가 똑같자 한설은 그대로 한참 움직이지 않았다."},{"s":null,"t":"나는 한설을 불렀다. 한설이 두 장을 겹쳐 품에 넣었다."},{"s":"night_office:han","t":"…모서리 접는 사람은 많다. 정청 서리 절반은 그렇게 한다."},{"s":"night_office:han","t":"아무것도 아니다. 적어만 두마. 기록에 없는 일은 끝내 일어나지 않은 일이 되니까."},{"s":null,"t":"한설의 목소리는 평소처럼 단단했지만, 붓을 쥔 손가락만은 하얗게 질려 있었다."},{"s":"night_office:han","t":"정청 안에서 벌어진 일은 도제조께 먼저 아뢰어야 한다. 아뢸 때 이 물도 보여 드려야 하니 한 병 떠 가자."},{"s":"night_office:han","t":"조사원, 그냥 들고 가면 병 주둥이부터 바랠 거다. 네가 정화 부적을 접어 병을 막아라."},{"s":null,"t":"정화 부적은 먹 기운이 스며드는 것을 막는 부적이라, 병에 담은 우물물이 주둥이부터 바래는 것도 막아 줄 것이었다."}],"reward":{"xp":2880}},{"quest_id":"mdq_1","step":6,"title":"닫힌 문 너머","goal":"정화 부적 2장을 만들어 우물물 병을 봉하고 본부 정청에 도착한다","need":{"at":["hq_yard"],"tasks":[{"t":"craft","items":["ward_talisman"],"n":2},{"t":"travel","r":["hq_yard"],"n":1}],"give":{"ward_talisman":2}},"lines":[{"s":null,"t":"동트기 직전의 대청은 텅 비어 있었다. 마당에는 엎어진 물동이와 젖은 발자국만 남았다."},{"s":null,"t":"그을린 종잇조각이 눈처럼 천천히 내려앉았다. 하나가 내 어깨에 앉았다가 바스러졌다."},{"s":null,"t":"대청 안쪽 방에서 누가 나왔다. 정리관 경현이었다. 관복은 깨끗한 것으로 갈아입었고, 그을음 묻은 얼굴도 말끔히 씻은 뒤였다."},{"s":null,"t":"경현이 우리를 보고 걸음을 멈췄다. 손에 든 얇은 장부의 모서리를 접으며 고개를 숙였다."},{"s":"q:md_gyeonghyeon","t":"감찰관, 조사원. 불난 일은 내가 먼저 아뢰었소. 도제조께서 두 분 이야기도 기다리시오."},{"s":null,"t":"경현의 눈길이 내 손등에 머물렀다. 아직 핏기가 다 돌아오지 않은 자리였다."},{"s":"q:md_gyeonghyeon","t":"그 검은 물을 벌써 한 번 만지셨구려. 다음엔 장갑을 끼시오. 조사원 손은 둘뿐이니 아껴 쓰셔야지."},{"s":null,"t":"나는 그 물이 무엇이냐고 물었다. 경현이 접힌 모서리를 엄지로 쓸며 빙그레 웃었다."},{"s":"q:md_gyeonghyeon","t":"땅 밑에 오래 고인 물이오. 무엇이든 오래 고이면 다 저런 색이 되지. 사람도 그렇소."},{"s":null,"t":"경현은 그 말만 남기고 마당을 가로질러 갔다. 한설은 그 등을 끝까지 보지 않았다."},{"s":null,"t":"안쪽 방 문은 닫혀 있었다. 문틈으로 새어 나온 등잔 불빛이 마룻바닥에 가는 금을 그었다. 그 금은 조금도 떨리지 않았다."},{"s":null,"t":"한설이 문밖에 무릎을 꿇었다. 불이 시작된 칸, 모가람의 두 손, 흰 불꽃, 검은 우물, 접힌 사본까지 하나도 빼놓지 않고 아뢰었다."},{"s":null,"t":"아뢰기를 마친 한설이 정화 부적으로 주둥이를 막은 병을 문지방 앞에 내려놓았다. 부적 아래로 검은 물이 느리게 출렁였다."},{"s":null,"t":"말이 끝나고도 문 안은 오래 조용했다."},{"s":"night_office:baek","t":"불은 꺼졌나."},{"s":null,"t":"한설이 문지방에 이마가 닿도록 고개를 숙였다."},{"s":"night_office:han","t":"꺼졌습니다. 다만 서가 한 칸이 다 탔고, 기록관이 두 손을 데었습니다."},{"s":null,"t":"문 안쪽에서 숨을 고르는 소리가 났다. 다음 말은 한참 뒤에야 왔다."},{"s":"night_office:baek","t":"기록관에게 고맙다고 전해 주게. 그 병은 문 앞에 두고 가게. 그 검은 물은… 내가 오래전부터 아는 물이네."},{"s":null,"t":"문틈의 불빛이 병 쪽으로 가늘게 기울었다가 도로 곧아졌다. 다음 말은 더 오래 걸렸다."},{"s":"night_office:baek","t":"타다 남은 그 장은 조사원이 지니고 있게."},{"s":null,"t":"나는 장을 왜 정청 서가에 두지 않느냐고 물었다. 문 안은 대답이 없었고, 등잔 불빛만 한 번 아주 약하게 흔들렸다."},{"s":null,"t":"한설이 일어섰다. 무언가 묻고 싶은 듯 입을 열었다가 다시 다물었다."},{"s":null,"t":"대청을 나서자 동쪽 하늘이 희끄무레하게 밝아 왔다. 섬돌 아래에서 한설이 걸음을 멈췄다."},{"s":"night_office:han","t":"도제조께서 불을 보러 나오지 않으신 건 처음이다. 묵창 나루 일이 있고부터 안쪽 방을 잘 안 떠나시긴 했지만, 정청에 불이 났는데도… 내가 정청에 온 열다섯 해 동안 한 번도 없던 일이야."},{"s":"night_office:han","t":"구중 봉연에서 네가 마지막 문을 닫고 온 날, 도제조께서 판관들 앞에서 「올해 먹 거두기는 하지 않는다」 하셨지. 그 뒤로 그분 목소리가 저렇게 가늘어진 건 처음이다."},{"s":"night_office:han","t":"조사원, 그 장은 네가 지녀라. 누가 무엇 때문에 이걸 노렸는지 알기 전에는 아무한테도 내주지 마. 정청 사람한테도."},{"s":null,"t":"나는 판관 어르신들한테도냐고 물었다.","fac_not":"night_office","spec":2,"grp":1},{"s":null,"t":"나는 판관 어르신들한테도냐고 물었다.","fac":"night_office","rank":[1,4],"spec":0,"grp":1},{"s":null,"t":"나는 판관 패를 찬 나한테도 그러냐고, 다른 판관들한테도냐고 물었다.","fac":"night_office","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"한설이 나를 똑바로 보았다."},{"s":"night_office:han","t":"…아무한테도라고 했다.","fac_not":"night_office","spec":2,"grp":2},{"s":"night_office:han","t":"…아무한테도라고 했다.","fac":"night_office","rank":[1,4],"spec":0,"grp":2},{"s":"night_office:han","t":"판관 패는 네 손목에 있는 거지 그 장에 있는 게 아니다. 네가 지니라는 거다. 다른 판관들한테도 내주지 마라. …아무한테도라고 했다.","fac":"night_office","rank":[5,5],"spec":0,"grp":2},{"s":null,"t":"한설이 고개를 돌려 객사 쪽 창을 보았다. 의원 방에 아직 불이 켜져 있었다."},{"s":"night_office:han","t":"기록관은 아침을 못 먹었을 거다. 저 손으로는 숟가락을 못 든다. 월광 이끼죽이라도 한 그릇 쑤어서 객사에 가 봐라. 나는 그동안 서고 출입 장부를 뒤지마."},{"s":null,"t":"월광 이끼죽은 객사에서 앓는 사람에게 늘 쑤어 주는 죽이라, 숟가락을 들지 못하는 모가람도 떠 넣어 주면 쉽게 넘길 수 있을 것이었다."}],"reward":{"xp":2880}},{"quest_id":"mdq_1","step":7,"title":"받아 적는 손","goal":"월광 이끼죽 1그릇을 쑤어 본부 객사의 모가람에게 넘긴다","need":{"at":["hq_dorm"],"tasks":[{"t":"craft","items":["moss_porridge"],"n":1},{"t":"travel","r":["hq_dorm"],"n":1}],"give":{"moss_porridge":1}},"lines":[{"s":null,"t":"객사 창으로 아침 햇살이 들었다. 모가람은 침상에 기대앉아 붕대 감긴 손을 이불 위에 얹어 두고 있었다."},{"s":null,"t":"내가 죽 그릇을 들고 들어가자 모가람의 눈이 동그래졌다."},{"s":"night_office:mo","t":"조사원님이 쑤셨어요? 아이고, 김 나는 것 좀 보세요. 정청 와서 남이 쑤어 준 죽은 처음이에요."},{"s":null,"t":"나는 죽을 한 숟갈 떠서 후후 불어 모가람의 입에 넣어 주었다. 모가람이 오물거리다가 큭큭 웃었다."},{"s":"night_office:mo","t":"서른 해 기록관이 아기처럼 받아먹네요. 문수가 보면 정청에 소문이 열흘은 돌겠어요."},{"s":null,"t":"문밖에서 쿵 소리가 났다. 문틈으로 들여다보던 문수가 문짝에 이마를 찧은 것이었다."},{"s":"q:dh_munsu","t":"저, 저는 아무것도 못 봤거든요! 기록관님 아침 드시나 보러 왔을 뿐이거든요!"},{"s":null,"t":"모가람이 웃다가 사레가 들려 콜록거렸다. 나는 모가람의 등을 두드려 주었다. 문수가 쭈뼛쭈뼛 들어와 물그릇을 내밀었다."},{"s":"q:dh_munsu","t":"그… 조사원님, 고맙습니다. 저는 어젯밤에 물만 날랐거든요. 기록관님이 안에 계신 걸 알면서도 무서워서 못 들어갔거든요."},{"s":null,"t":"문수의 목소리가 떨렸다. 모가람이 붕대 낀 손으로 문수의 손등을 톡 건드렸다."},{"s":"night_office:mo","t":"물 나르는 사람이 있었으니 불이 꺼진 거예요. 너는 네 몫을 다 했어."},{"s":null,"t":"문수가 물그릇을 내려놓고 목소리를 낮췄다. 수다를 참지 못하는 얼굴이었다."},{"s":"q:dh_munsu","t":"근데요, 조사원님. 어젯밤 기록관님 업고 나온 분, 정리관 어르신이시잖아요. 그 자리가 어떻게 생긴 건지 아세요? 정청 서리들은 다 쉬쉬하거든요."},{"s":null,"t":"나는 모른다고 했다. 문수가 문 쪽을 한 번 돌아보고 다가앉았다."},{"s":"q:dh_munsu","t":"작년에 도제조께서 「올해는 거두지 않는다」 하셨잖아요. 그해에 구룡 폐수로 둘레 우물이 시커메졌거든요. 그 물을 길어 먹은 집부터 하룻밤에 열한 명이 없어졌대요. 물동이 옆에 옷이랑 신만 남고요."},{"s":"q:dh_munsu","t":"경현 어르신이 그 열한 벌을 판관 회의 탁자에 하나하나 올려놓으셨대요. 그러고는 명부 일을 맡을 정리관을 두자, 명부 일에는 정청 인장을 쓰게 하자, 그 안을 직접 내셨거든요. 판관 여섯 분이 아무도 반대를 못 하셨대요."},{"s":null,"t":"모가람이 붕대 낀 손을 무릎 위에서 꼭 맞잡았다. 문수를 나무라지도 않았다."},{"s":"night_office:mo","t":"도제조께서는 그 자리에 계셨는데도 아무 말씀이 없으셨대요. …정리관 어르신 셈에는 틀린 데가 없으니까요. 그게 무서운 거예요."},{"s":null,"t":"나는 한설이 찍어 준 먹 자국 종이를 모가람의 코앞에 펼쳤다. 모가람이 냄새를 맡더니 얼굴이 하얘졌다."},{"s":"night_office:mo","t":"이 냄새… 명부 먹이에요. 정청 명부를 쓸 때만 쓰는 묵은 그을음 먹이요. 서른 해 동안 매일 맡은 냄새라 틀릴 리가 없어요."},{"s":"night_office:mo","t":"명부 먹을 발에 묻히고 다니는 사람이라니요. 명부 곁에 사는 사람이 아니면 그럴 수가 없는데요."},{"s":null,"t":"죽 그릇이 비자 모가람이 머뭇거리며 나를 보았다."},{"s":"night_office:mo","t":"조사원님, 부탁 하나만 해도 될까요? 어젯밤 일을 기록해 둬야 하는데, 손이 이래서요. 제가 불러 드리면 받아 적어 주실래요?"},{"s":null,"t":"나는 탁자에서 붓과 종이를 가져왔다. 모가람이 천천히 불러 주는 대로 받아 적었다."},{"s":"night_office:mo","t":"「장서각 봉인 서가 맨 안쪽 칸에 불. 기록관 모가람이 첫 상자의 장을 품고 나옴. 반은 탔음. 정리관이 기록관을 업고 나옴.」"},{"s":"night_office:mo","t":"…그리고 이렇게도 적어 주세요. 「기록관은 서른 해 동안 정리소의 사본을 정서했다. 묻지 않았다.」"},{"s":null,"t":"내 붓이 멈췄다. 모가람이 적으라는 듯 고개를 끄덕였다."},{"s":"night_office:mo","t":"적기만 하던 사람이 이제야 말로 남기네요. 이상하죠. 손이 성할 때는 한 줄도 못 쓴 말인데."},{"s":null,"t":"그때 정문 쪽에서 말발굽 소리가 다급하게 다가왔다. 다그닥다그닥, 소리가 객사 마당에서 뚝 멈췄다."},{"s":null,"t":"흑련 매듭을 단 심부름꾼이 말에서 굴러떨어지듯 내렸다. 밤새 달린 말의 옆구리에서 하얀 김이 솟았다."},{"s":null,"t":"마당을 지나던 한설이 심부름꾼의 팔을 붙잡았다. 심부름꾼은 숨을 헐떡이며 객사 창 쪽으로 소리쳤다."},{"s":"q:md_lotus_runner","t":"정청 조사원 계십니까! 어젯밤 이 시각에 흑련 장부고에 누가 숨어들었습니다! 회주님 장부를 한 권 들고 사라졌어요!"},{"s":"q:md_lotus_runner","t":"그 일로 거둠꾼 월하가 쓰러졌습니다. 손가락이… 손가락이 녹고 있어요! 곁을 지키는 아이가 조사원님을 찾으며 울고 있습니다!"},{"s":null,"t":"나는 벌떡 일어났다. 월하 곁의 아이라면 다온이었다. 봄까지 정청 서당에서 글을 배우기로 하고, 내가 본부까지 바래다준 아이였다."},{"s":null,"t":"한설이 창 너머로 나와 눈을 맞췄다."},{"s":"night_office:han","t":"정청 서가와 흑련 금고가 같은 밤에 털렸다. 둘 다 같은 손이 벌인 일일 거다. 가 봐라. 정청 일은 내가 맡겠다."},{"s":null,"t":"서당 쪽 담장 문으로 연서희가 뛰어 들어왔다. 심부름꾼의 고함을 들었는지 얼굴이 하얬다."},{"s":"q:m_yeon","t":"다온이 흑련에 있었어요? 보름 전에 서당에서 없어져서 아이들이랑 사흘을 찾았어요. 보러 온 사람 소매를 붙잡고 따라갔다는 말만 들었고요."},{"s":null,"t":"나는 그 사람이 월하일 거라고 했다. 연서희가 입술을 깨물다가 고개를 끄덕였다."},{"s":"q:m_yeon","t":"그 애 보거든 서당 자리는 비워 뒀다고 전해 줘요. 그리고 {이름} 님도 다치지 말고요. 어젯밤에 소매 적셔 준 게 아깝잖아요."},{"s":null,"t":"모가람이 붕대 감긴 손을 들어 내 소매 끝을 붙잡으려 했지만, 손가락이 굽지 않아 소매가 스르르 빠져나갔다."},{"s":"night_office:mo","t":"조사원님, 그 장을 잘 지니세요. 그리고 다녀오시면 보리차 한 잔 따라 주세요. 이번엔 제가 받아 마실 차례니까요."}],"reward":{"xp":2880,"gil":470,"items":{"night_tea":2,"revival_charm":2}}},{"quest_id":"mdq_2","step":1,"title":"아홉째 손가락","goal":"흑련 장부고에 도착해 월하와 다온을 만난다","need":{"at":["ledger_cellar"],"tasks":[{"t":"travel","r":["ledger_cellar"],"n":1}]},"lines":[{"s":null,"t":"흑련 장부고는 땅 밑으로 세 층을 내려가야 했다. 계단을 내려갈수록 공기가 차고 눅눅해졌다."},{"s":null,"t":"벽마다 장부가 천장까지 빽빽했다. 오래된 종이 냄새와 곰팡이 냄새가 코를 찔렀다."},{"s":null,"t":"계단 끝 문지기가 내 옷깃의 정청 표식을 보고 칼자루를 움켜쥐었다. 앞서 달려온 심부름꾼이 귓속말을 하고서야 문지기가 마지못해 비켜섰다.","fac_not":"black_lotus","spec":2,"grp":1},{"s":null,"t":"계단 끝 문지기가 내 손목의 흑련 매듭을 보고 고개를 까딱였다. 정청 표식과 흑련 매듭을 함께 단 사람은 드문지, 문지기는 내가 지나가는 동안 두 가지를 번갈아 흘끔거렸다.","fac":"black_lotus","rank":[1,2],"spec":0,"grp":1},{"s":null,"t":"계단 끝 문지기가 내 손목의 매듭을 보자마자 허리를 숙였다. 문지기가 안쪽에 대고 「{등급}께서 오셨습니다」 하고 외치자, 장부고 사람들이 일손을 멈추고 나를 돌아보았다.","fac":"black_lotus","rank":[3,4],"spec":0,"grp":1},{"s":null,"t":"계단 끝 문지기가 나를 보자 아무 말 없이 무릎을 꿇었다. 안쪽의 장부지기들도 하나둘 붓을 내려놓았다.","fac":"black_lotus","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"맨 안쪽 방 침상에 월하가 누워 있었다. 늘 엽전을 굴리던 왼손이 이불 밖으로 축 늘어져 있었다."},{"s":null,"t":"그 새끼손가락 끝이 잿빛이었다. 잿빛은 첫마디를 지나 둘째 마디로 기어오르고 있었다."},{"s":null,"t":"눈을 떼지 않아야 겨우 알아볼 만큼 느렸지만, 잿빛은 한순간도 멈추지 않았다."},{"s":null,"t":"잿빛이 지나간 살갗은 녹은 초처럼 물러져 있었다. 손톱이 반쯤 투명해져 그 밑으로 이불 무늬가 비쳤다."},{"s":null,"t":"침상 머리맡에 다온이 웅크리고 앉아 접힌 쪽지를 꼭 쥐고 있었다. 묵창 나루에서 월하가 맡겨 둔 봉함 쪽지였다."},{"s":null,"t":"나를 알아본 다온이 벌떡 일어나다 침상 다리에 무릎을 쿵 찧었다. 아픈 줄도 모르는 얼굴이었다."},{"s":"q:mk_daon","t":"{이름} 님! {이름} 님, 아저씨 손가락이 자꾸 색이 없어져요! 아무리 문질러도 안 돌아와요. 어젯밤부터 계속요!"},{"s":null,"t":"다온이 내 소매를 붙잡고 매달렸다. 작은 손이 바들바들 떨렸다."},{"s":"q:mk_daon","t":"장부지기 누나가 그러는데요, 그림자 없는 사람들이 와서 아저씨 이름을 맡겨 둔 장을 찢어 갔대요. 그래서 이름이 자꾸 빠져나가는 거래요. 저 어떡해요?"},{"s":null,"t":"월하가 눈을 반쯤 뜨고 나를 보며 입꼬리를 비틀어 올렸다. 웃음 모양은 늘 같았지만 받쳐 줄 힘이 없었다."},{"s":"q:mk_wolha","t":"조사원이네. 오는 데 꽤 걸렸네요. 내가 녹는 거 구경 오셨어요? 입장료라도 받을걸.","fac_not":"black_lotus","spec":2,"grp":2},{"s":"q:mk_wolha","t":"우리 회원님이 오셨네. 오는 데 꽤 걸렸네요. 회원끼리는 공짜니까, 내가 녹는 건 그냥 구경하세요.","fac":"black_lotus","spec":1,"grp":2},{"s":null,"t":"다온이 쪽지를 월하 쪽으로 내밀며 엄지손톱으로 귀퉁이를 들추었다. 펴서 그 안의 이름을 부르려는 손이었다."},{"s":null,"t":"순간 월하의 오른손이 다온의 손등을 탁 덮었다. 누워만 있던 사람이라고 믿기 어려울 만큼 빨랐다."},{"s":"q:mk_wolha","t":"펴지 마."},{"s":null,"t":"다온의 눈이 휘둥그레졌다. 월하가 손등을 덮은 채 목소리를 누그러뜨렸다."},{"s":"q:mk_wolha","t":"그건 펴는 게 아니라고 했잖아, 꼬맹이. 펴지 마. 쥐고만 불러. 지금은 나 여기 있잖아."},{"s":null,"t":"나는 월하에게 지금 고집을 부릴 때냐고 했다. 월하가 나를 흘겨보았다."},{"s":"q:mk_wolha","t":"조사원은 몰라요. 남의 이름에 값을 매기며 산 사람이 제 이름까지 남의 입에 맡기면… 그건 장사꾼으로서 끝이에요."},{"s":null,"t":"다온의 눈에 눈물이 그렁그렁 고였다. 그사이 잿빛이 둘째 마디를 넘었다."},{"s":null,"t":"손가락 끝이 흐물흐물 녹아내렸다. 똑. 검은 방울 하나가 하얀 이불 위로 떨어져 먹 얼룩으로 번졌다."},{"s":null,"t":"다온이 쪽지를 펴지 않은 채 가슴에 끌어안았다. 숨이 넘어갈 듯 월하를 불렀다."},{"s":"q:mk_daon","t":"아저씨! 아저씨! 아저씨이!"},{"s":null,"t":"그때 처음 보는 일이 벌어졌다. 아이가 부르짖을 때마다 입김이 하얗게 흩어지지 않았다."},{"s":null,"t":"입김이 가는 금빛 실로 엉겨 붙었다. 실은 반짝반짝 빛나며 공중을 건너 월하의 가슴께에 가 닿았다."},{"s":null,"t":"실이 닿은 자리에서 온기가 번졌다. 멀찍이 선 내 손등까지 그 따스함이 느껴졌다."},{"s":null,"t":"둘째 마디를 넘던 잿빛이 그 자리에서 딱 멈췄지만, 손가락 끝 두 마디는 이미 사라진 뒤였다."},{"s":null,"t":"다온이 울음을 그치고 금빛 실을 멍하니 보다가 나를 돌아보았다."},{"s":"q:mk_daon","t":"…{이름} 님, 이거 봤어요? 제가 부르니까 빛이 나와요. 아저씨한테 닿아요!"},{"s":null,"t":"월하가 녹아 없어진 손가락 자리를 오래 내려다보았다. 이불의 먹 얼룩으로 눈을 옮겼다가 다시 손을 보았다."},{"s":"q:mk_wolha","t":"…엽전은 이제 오른손으로 튕겨야겠네."},{"s":null,"t":"월하가 다온의 머리에 오른손을 얹었다. 그 손이 조금 떨렸다."},{"s":"q:mk_wolha","t":"잘했어, 꼬맹이. 그 쪽지는 끝까지 펴지 마. …조사원, 오늘 밤 이 애 좀 같이 봐줘요. 혼자 밤새 부르다간 목이 남아나질 않겠어."}],"reward":{"xp":2468}},{"quest_id":"mdq_2","step":2,"title":"번갈아 부른 밤","goal":"흑련 장부고에서 쉬며 다온 곁에서 밤을 지킨다","need":{"at":["ledger_cellar"],"tasks":[{"t":"rest","r":["ledger_cellar"],"n":1}]},"lines":[{"s":null,"t":"그날 밤 장부고에는 바람 소리 하나 없었고, 등잔 셋의 심지가 지지직 타는 소리만 들렸다."},{"s":null,"t":"다온은 쪽지를 쥔 채 꾸벅꾸벅 졸았다. 졸다가 화들짝 깨면 「아저씨」를 불렀다."},{"s":null,"t":"그때마다 금빛 실이 건너가 잿빛을 손가락 쪽으로 밀어냈지만, 아이가 다시 잠들면 잿빛은 스멀스멀 기어올랐다."},{"s":null,"t":"자정 무렵 다온의 목소리가 쉬어 갔다. 「아저씨」가 「아저…」에서 갈라졌다."},{"s":null,"t":"나는 다온의 어깨를 두드렸다. 이번엔 내가 부를 테니 눈을 붙이라고 했다."},{"s":"q:mk_daon","t":"안 돼요. {이름} 님은 아저씨를 잘 모르잖아요. 아저씨가 무슨 엽전을 제일 좋아하는지도 모르잖아요."},{"s":null,"t":"나는 그러면 가르쳐 달라고 했다. 다온이 쉰 목으로 킁 코를 훌쩍였다."},{"s":"q:mk_daon","t":"…상평통보요. 귀퉁이 이 빠진 거요. 그거 튕길 때 제일 많이 웃어요. 그리고 생선 가시 바르는 걸 싫어해요. 그래서 제가 발라 줘요."},{"s":null,"t":"묵창 나루에서는 내 소매만 붙잡고 다니던 아이였다. 그 아이가 이제 월하가 어느 엽전에 웃는지, 생선 가시를 누가 발라 주는지까지 알고 있었다."},{"s":null,"t":"나는 그 이야기를 떠올리며 월하를 불렀다. 내 입김도 금빛 실이 되었지만 다온의 것보다 훨씬 가늘었다."},{"s":null,"t":"가는 실도 월하의 가슴에 닿기는 닿았다. 잿빛이 멈칫하더니 아주 조금 물러났다."},{"s":"q:mk_daon","t":"어! {이름} 님 것도 나왔어요! 근데 실이 쪼끄매요."},{"s":null,"t":"다온이 처음으로 키득 웃었다. 내가 둘이 번갈아 부르자고 하자 다온이 고개를 끄덕였다."},{"s":null,"t":"우리는 번갈아 불렀다. 다온이 「아저씨」를 부르면, 내가 「월하」를 불렀다. 다온이 졸면 내가 부르고, 내 목이 잠기면 다온이 불렀다."},{"s":null,"t":"새벽녘 다온이 내 어깨에 머리를 기댄 채 잠들었지만, 쪽지는 끝까지 손에서 놓지 않았다."},{"s":null,"t":"월하가 실눈을 뜨고 그 모습을 보았다. 목소리가 바람 소리처럼 가늘었다."},{"s":"q:mk_wolha","t":"…조사원 목소리는 영 내 취향이 아니던데. 그래도 덕분에 손바닥까지는 안 갔네. 외상으로 달아 둬요."},{"s":null,"t":"문이 끼익 열렸다. 머리를 단단히 틀어 올린 장부지기 구슬이 주판을 옆구리에 끼고 들어왔다."},{"s":null,"t":"구슬은 월하의 손을 보며 혀를 차면서도 자기 겉옷을 벗어 잠든 다온의 어깨에 덮어 주었다."},{"s":"black_lotus:guseul","t":"조사원님, 이름 없는 종 일 때는 덤이나 얹어 드렸는데, 오늘은 셈할 것도 없이 신세만 지네요. 밤새 이 애 곁에 계셨다고 들었어요. 장부고 사람들은 다 다른 회원들 곁에 붙어 있느라 와 보지도 못했어요."},{"s":null,"t":"나는 밤새 본 금빛 실이 무엇이냐고 물었다. 구슬이 주판알을 하나 탁 올렸다."},{"s":"black_lotus:guseul","t":"처음 보셨나 봐요. 이름을 부르는 소리가 사람한테 닿으면 그렇게 보여요. 낮에는 잘 안 보이고 밤에, 그것도 이름이 빠져나가는 사람 곁에서나 보이죠. 장부고 사람들은 다 알아요. 이름이 흔들리는 회원 곁에서 밤새 불러 주는 게 장부지기 일이거든요.","fac_not":"black_lotus","spec":2,"grp":1},{"s":"black_lotus:guseul","t":"회원이시니 말로는 들어 보셨을 텐데, 눈으로 보신 건 처음이죠? 이름을 부르는 소리가 사람한테 닿으면 그렇게 보여요. 그래서 이름이 흔들리는 회원 곁에서 밤새 불러 주는 게 장부지기 일이에요.","fac":"black_lotus","rank":[1,2],"spec":0,"grp":1},{"s":"black_lotus:guseul","t":"{등급}께서 굳이 물으시는 걸 보니, 금빛이 이렇게 짙게 이는 건 처음 보셨나 봐요. 저도 장부고에서 스무 해를 지냈지만 아이 목소리가 저만큼 닿는 건 처음 봤어요.","fac":"black_lotus","rank":[3,5],"spec":0,"grp":1},{"s":null,"t":"구슬이 주판알 두 개를 탁, 탁 올렸다."},{"s":"black_lotus:guseul","t":"실이 굵고 가는 건 부르는 사람이 그 이름을 얼마나 아느냐에 달렸어요. 셈으로 치면 조사원님은 어젯밤 아이 몫의 삼 할쯤 버신 거예요. 처음치고는 후하게 쳐 드린 거고요."},{"s":null,"t":"구슬이 잠든 다온을 내려다보았다. 차갑던 얼굴이 조금 풀렸다."},{"s":"black_lotus:guseul","t":"보름 전에 월하 씨가 정청 서당에 이 애를 보러 갔다가 돌아오는데, 이 애가 소매를 붙잡고 따라나섰대요. 서당엔 안 간다고 고집을 부려서요. 월하 씨가 하는 수 없이 데려와서는, 밤마다 등잔 밑에서 장부 글씨를 가르쳤어요. 묵창 나루에서 빌려준 노잣돈 이자를 글로 받는다나요."},{"s":"black_lotus:guseul","t":"월하 씨가 누운 뒤로는 서당으로 돌려보내려 해도 꼼짝을 안 해요. 저 자리에서 한 번도 안 떠났어요."},{"s":"black_lotus:guseul","t":"그런데 이 애가 어제부터 아무것도 안 먹었어요. 장부고 부엌은 그 일로 문을 닫았고요. 조사원님, 국 한 그릇만 끓여 주실래요? 이 애가 쓰러지면 월하 씨를 부를 사람이 없어요."},{"s":null,"t":"월하가 눈을 감은 채 한마디를 보탰다."},{"s":"q:mk_wolha","t":"단 것도 하나 사 줘요. 그 애는 단 거 하나면 사흘을 버텨요. 내가 늘 그렇게 키웠거든."},{"s":null,"t":"장부고 둘레에는 엿장수가 들지 않았고 단 것이라고는 동무 먹이 가게에서 파는 꿀 약과뿐이어서, 나는 그것을 두 개 사기로 했다."}],"reward":{"xp":2468}},{"quest_id":"mdq_2","step":3,"title":"약과 두 개","goal":"물고기를 2번 낚아 어죽 2그릇을 쑤고, 꿀 약과 2개와 함께 흑련 장부고의 다온에게 넘긴다","need":{"at":["ledger_cellar"],"tasks":[{"t":"fish","n":2},{"t":"craft","items":["fish_porridge"],"n":2}],"give":{"treat_honey":2,"fish_porridge":2}},"lines":[{"s":null,"t":"다온은 어죽을 한 숟갈 뜨고 월하를 한 번 보았다. 또 한 숟갈 뜨고 또 한 번 보았다."},{"s":null,"t":"내가 꿀 약과 두 개를 내밀자 다온의 숟가락이 멈췄다."},{"s":"q:mk_daon","t":"약과예요? 진짜요? 묵창 나루에서 아저씨가 사 준 거랑 똑같다!"},{"s":null,"t":"다온이 약과 하나를 입에 물고, 나머지 하나는 손수건에 조심조심 쌌다."},{"s":"q:mk_daon","t":"이건 아저씨 거예요. 아저씨 일어나면 줄 거예요. 지금은 손이 아파서 못 드시니까요."},{"s":null,"t":"다온이 손수건을 쪽지와 함께 품에 넣었다. 약과를 오도독 깨물더니 나를 올려다보았다."},{"s":"q:mk_daon","t":"{이름} 님, 근데요. 아저씨 이름을 찢어 간 사람들을 잡을 거죠? 잡으면 저도 한 대 때릴래요."},{"s":null,"t":"나는 그 사람들을 보았냐고 물었다. 다온이 약과 씹던 입을 멈추고 몸을 움츠렸다."},{"s":"q:mk_daon","t":"봤어요. 아저씨 옆에서 자다가 깼는데요, 문 앞으로 지나갔어요. 등잔 밑으로 지나가는데 그림자가 흐릿했어요. 물에 번진 것처럼요."},{"s":"q:mk_daon","t":"아무 말도 안 했어요. 발소리만 철벅철벅 났어요. 손끝이 숯 만진 것처럼 까맸고요. …무서워서 이불 속에 숨었어요."},{"s":null,"t":"다온이 고개를 푹 숙였다. 나는 다온의 머리를 쓰다듬으며 숨은 게 잘한 거라고 했다."},{"s":null,"t":"나는 잡으면 다온 몫까지 꼭 남겨 두겠다고 했다. 다온이 새끼손가락을 쑥 내밀었다."},{"s":"q:mk_daon","t":"약속이에요. 이 손가락은 아저씨 손가락 대신이에요."},{"s":null,"t":"내가 손가락을 걸자 다온이 엄지로 도장까지 꾹 찍었다. 침상에서 월하가 쿡 웃었다."},{"s":"q:mk_wolha","t":"꼬맹이가 조사원한테 외상 장부를 다 쓰네. 그 도장은 흑련에서도 받아 주는 도장이에요."},{"s":null,"t":"구슬이 주판을 탁 내려놓고 일어섰다."},{"s":"black_lotus:guseul","t":"이제 금고를 보셔야겠어요. 회주님이 조사원님을 기다리세요. 그 전에 하나만요. 금고로 내려가는 아래층 계단에 먹을 뒤집어쓴 것들이 웅크리고 있어요. 그날 밤 그자들이 지나간 자리로 기어 나온 것들이에요."},{"s":null,"t":"나는 장부고 사람들은 왜 못 치웠냐고 물었다. 구슬이 주판알을 하나씩 내렸다."},{"s":"black_lotus:guseul","t":"장부지기 열둘 가운데 여섯은 밤새 회원들 이름을 부르느라 목이 쉬었고, 넷은 그것들한테 손을 물렸어요. 남은 둘 가운데 하나가 저예요. 셈이 안 맞죠?"},{"s":null,"t":"다온이 약과를 문 채 내 소매를 잡아당겼다."},{"s":"q:mk_daon","t":"{이름} 님, 다치지 말고 와요. 다치면 제가 {이름} 님도 불러야 하잖아요. 저 목 아파요."}],"reward":{"xp":2468}},{"quest_id":"mdq_2","step":4,"title":"빈 칸","goal":"흑련 장부고 금고 계단에서 부르다 굳은 넋을 3번 풀어 보낸다","need":{"at":["ledger_cellar"],"tasks":[{"t":"win","n":3,"m":["dd_yamen_1"],"r":["ledger_cellar"]}]},"lines":[{"s":null,"t":"금고 계단의 마지막 것을 쓰러뜨렸다. 그 몸에서 먹이 주르륵 흘러 돌 틈으로 스며들었다."},{"s":null,"t":"쓰러진 것들은 장부고에 늘 숨어 살던 요괴가 아니었다. 살갗이 바랜 종이처럼 하얗고 누군가를 부르듯 입을 크게 벌린 채 굳어 있었는데, 벌린 입에서는 소리가 한 걸음 밖으로도 나오지 않았다. 그것들이 웅크렸던 계단 끝에서 젖은 먹 발자국이 배수 우물로 이어졌고, 우물 안에서는 미지근한 먹물이 느리게 출렁였다."},{"s":"black_lotus:guseul","t":"장부고에는 저런 게 없었어요. 그자들이 우물로 드나든 뒤로 저 아래 먹물을 타고 올라온 거예요. 어디서 온 것들인지는 어느 장부에도 안 적혀 있어요."},{"s":null,"t":"구슬을 따라 가장 깊은 금고 앞에 섰다. 사람 키 두 배는 되는 돌문이 활짝 열려 있었다."},{"s":null,"t":"문짝 안쪽에 손가락이 길고 가는 먹 손자국이 찍혀 있었다. 크기가 다른 손자국이 다섯 쌍이나 되었다."},{"s":null,"t":"금고 맨 윗칸은 먼지 위에 긴 네모 자국만 남긴 채 비어 있었다. 그 옆으로 끊어진 검은 끈 한 가닥이 늘어져 있었다."},{"s":null,"t":"구슬이 끈을 집어 들었다. 손가락에 감았다 풀었다 하며 한참을 말이 없었다."},{"s":"black_lotus:guseul","t":"그날 밤 문지기 둘이 그자들을 봤어요. 다섯이었대요. 등잔 아래 섰는데 그림자가 반밖에 없고, 손끝이 먹처럼 까맸대요. 칼을 들이대도 한마디도 안 했대요. 지나간 자리에선 썩은 먹 냄새가 났고요."},{"s":null,"t":"나는 장서각 서고에서 본 뒷모습을 떠올리고, 정청 서고에서도 같은 사람을 보았다고 했다. 구슬의 주판이 차르륵 소리를 냈다."},{"s":"black_lotus:guseul","t":"그럼 한 패네요. 셈이 맞아요."},{"s":null,"t":"구슬이 끊어진 끈을 등잔 가까이 들어 올렸다. 끈 끝에 먹이 엉겨 붙어 있었다."},{"s":"black_lotus:guseul","t":"조사원님, 월하 씨 맡김 자리를 옮기러 오셨던 날 기억나세요? 그때 옮긴 장이 하필 이 칸에 있었어요."},{"s":null,"t":"나는 원장의 맡김 칸을 오려 먹으로 봉하던 그날 밤을 떠올렸다. 구슬이 등잔을 들어 빈 칸을 비췄다."},{"s":"black_lotus:guseul","t":"회주님 장부예요. 검은 끈으로 묶어 이 칸에 두셨죠. 그 안에 월하 씨 옮김 장이 끼워져 있었어요. 맡김 칸을 오려 봉한 자리라, 다온이 쥔 쪽지하고 그 장은 한 끈으로 이어져 있고요."},{"s":"black_lotus:guseul","t":"그자들은 장부를 통째로 들고 가면서, 나가는 길에 그 한 장만 찢어 젖은 바닥에 버렸어요. 다온이 밤새 부르지 않았으면 월하 씨는 벌써 다 풀렸을 거예요."},{"s":null,"t":"구슬이 등잔을 기울여 가리킨 바닥이 검게 젖어 있었다. 찢긴 종이는 이미 먹물로 풀려 돌 틈으로 스며든 뒤였다."},{"s":null,"t":"나는 그 자리에 쪼그려 앉았다. 돌 틈에서 차가운 기운이 스멀스멀 올라와 손등을 핥았다."},{"s":null,"t":"젖은 바닥 가장자리, 돌 틈에 종잇조각 하나가 끼어 있었다. 나는 손끝으로 조심스레 빼냈다. 먹물에 반쯤 젖은 명부 한 줄이었다."},{"s":null,"t":"「곽두칠」이라는 이름 하나가 적혀 있었다. 그 이름 위에 붉은 줄이 그어지다 만 채 반에서 뚝 끊겨 있었다."},{"s":null,"t":"내가 조각을 내밀자 곁에서 주판을 쥐고 있던 구슬이 얼른 받아 들더니 눈이 커졌다."},{"s":"black_lotus:guseul","t":"곽두칠…? 이 사람, 열 해 전에 흑련에 빚을 지고 사라진 사람이에요. 빚 장부엔 지금도 이름이 있어요. 다들 죽은 줄 알았는데요."},{"s":null,"t":"나는 붉은 줄이 왜 반만 그어져 있냐고 물었다. 구슬이 조각을 등잔에 비춰 보며 고개를 저었다."},{"s":"black_lotus:guseul","t":"모르겠어요. 흑련 장부에선 이렇게 긋다 마는 줄이 없어요. 갚았으면 다 긋고, 못 갚았으면 안 긋죠. 반만 그은 건… 셈이 아직 안 끝났다는 건데요."},{"s":"black_lotus:guseul","t":"그날 밤 그자들이 떨어뜨린 거라면, 그 가운데 이 사람이 있었을지도 몰라요. 죽은 사람이 금고를 털러 왔다는 셈이 되네요."},{"s":null,"t":"구슬이 말을 맺으며 주판알 하나를 탁 튕겼다."},{"s":"black_lotus:guseul","t":"그 한 장을 찢어 버린 것도 일부러 그런 거예요. 장부만 들고 가면 될 것을, 흑련 사람들 보라고 그 한 장만 찢었어요. 빚 받으러 온 사람이 하는 짓이에요. 「너희가 뭘 쥐고 있는지 다 안다」 하는 거죠."},{"s":null,"t":"그때 금고 안쪽 어둠에서 목소리가 울렸다. 벽 너머 같기도 하고, 장부 더미 사이 같기도 했다."},{"s":null,"t":"구슬이 주판을 내려놓고 허리를 깊이 숙였다. 나도 모르게 등줄기가 서늘해졌다."},{"s":"black_lotus:mumyeong","t":"정청에서 온 사람이구려.","fac_not":"black_lotus","spec":2,"grp":1},{"s":"black_lotus:mumyeong","t":"정청 표식을 달고도 우리 매듭을 찬 사람이구려. 오늘은 그 두 가지가 다 쓸모가 있겠소.","fac":"black_lotus","rank":[1,2],"spec":0,"grp":1},{"s":"black_lotus:mumyeong","t":"{등급}, 그대가 왔구려. 장부고의 일을 정청 사람에게 털어놓는 줄 알았더니, 우리 사람에게 털어놓게 되었으니 다행이오.","fac":"black_lotus","rank":[3,4],"spec":0,"grp":1},{"s":"black_lotus:mumyeong","t":"내 말을 대신 전하던 그대에게, 오늘은 내가 직접 청할 일이 생겼소.","fac":"black_lotus","rank":[5,5],"spec":0,"grp":1},{"s":"black_lotus:mumyeong","t":"그 장부에는 흑련이 맡아 둔 이름들보다 오래된 것이 하나 들어 있었소. 칠십 년 전 첫 회주가 품고 나온 종이 한 장이오. 흑련의 뿌리가 거기 적혀 있소."},{"s":"black_lotus:mumyeong","t":"정청 서가에서도 그 밤에 종이 한 장이 탔다고 들었소. 우리 장부의 종이와 같은 맹약에서 나온 낱장이오. 장은 다르되 뿌리는 하나요. 그대 품의 반쪽이 그것이오."},{"s":null,"t":"품속 종이 위의 흰 불꽃이 한 번 크게 흔들렸다. 목소리가 잠시 끊겼다가 더 낮아졌다."},{"s":"black_lotus:mumyeong","t":"흑련은 칠십 년 동안 정청에 이름을 맡기지 않았소. 그런 흑련이 정청 사람에게 손을 빌려 달라 청하게 되었구려. 장부를 찾아 주시오, 조사원."},{"s":null,"t":"나는 왜 하필 나냐고 물었다. 어둠이 잠시 조용했다."},{"s":"black_lotus:mumyeong","t":"붉은 인장 때 그대는 흑련 회원들의 이름을 여럿 보았소. 그러고도 그 이름을 한 줄도 정청에 넘기지 않았지. 흑련 장부에는 그대 이름 옆에 갚을 빚이 적혀 있소. 흑련이 그대에게 진 빚이오."},{"s":null,"t":"구슬이 끊어진 끈을 내 손에 쥐여 주었다."},{"s":"black_lotus:guseul","t":"손자국 먹에서 장부고 아래 지맥 갱도의 물길 냄새가 나요. 그자들은 그 물길로 왔다 갔을 거예요. 흔적이 남았는지 봐 주세요. 요즘 그 아래에 먹을 뒤집어쓴 우두머리가 돌아다녀서, 장부고 사람들은 내려가지도 못해요."}],"reward":{"xp":2468}},{"quest_id":"mdq_2","step":5,"title":"공문을 든 손님","goal":"지맥의 뿌리에 도착해 물길을 막은 현판 아래 문지기를 쓰러뜨리고, 2번 탐색하며 실마리를 찾아 흑련 장부고로 돌아간다","need":{"at":["ledger_cellar"],"tasks":[{"t":"travel","r":["under_root"],"n":1},{"t":"win","n":1,"m":["dd_yamen_5"],"r":["under_root"]},{"t":"clue","r":["under_root"],"n":2}]},"lines":[{"s":null,"t":"지맥 갱도의 물길은 정청 쪽으로 흐르고 있었다. 바닥에 가라앉은 먹이 검은 띠를 이루었다."},{"s":null,"t":"띠를 거슬러 오르다 마주친 우두머리도 같은 먹을 뒤집어쓰고 있었다. 쓰러뜨리자 그 몸에서 먹이 흘러나왔다. 물길이 꿀꺽 그 먹을 삼켰다."},{"s":null,"t":"우두머리는 금고 계단의 것들처럼 살갗이 하얗게 바랬고, 제 키만 한 나무 현판을 등에 진 채 물길 한가운데를 막아서 있었다. 그것도 물길 바닥의 먹물을 타고 올라온 것 같았다."},{"s":null,"t":"물가 진흙에는 젖은 먹 발자국이 정청 쪽으로 줄지어 찍혀 있었다. 다섯 사람의 발자국이었다."},{"s":null,"t":"장부고로 돌아오자 입구가 시끌시끌했다. 문지기들이 칼을 반쯤 뽑은 채 한 사람을 둘러싸고 있었다."},{"s":null,"t":"칼날 한가운데 정리관 경현이 서 있었다. 손에 든 것은 공문 한 장뿐이었다. 칼끝이 턱밑에 와 있는데도 숨결이 고요했다."},{"s":"q:md_gyeonghyeon","t":"칼은 넣어 두시오. 다투러 온 게 아니오. 정청 일로 장부를 거둔 것을 알리러 왔소. 알리지 않고 거두면 도둑이니까."},{"s":null,"t":"구슬이 주판을 꽉 움켜쥐었다. 주판알이 차르륵 한쪽으로 쏠렸다."},{"s":"black_lotus:guseul","t":"도둑이 아니면 뭔데요! 그림자 흐린 사람들이 남의 금고 문을 먹 손으로 열고, 회원 이름이 적힌 장을 찢어 바닥에 버리고 갔어요! 그게 정청 일이에요?"},{"s":null,"t":"경현이 공문을 펼쳐 보였다. 정청 인장이 또렷했고, 결재 칸에는 「정리관」이라고만 적혀 있었다."},{"s":"q:md_gyeonghyeon","t":"그 장부에는 정청 문서가 한 장 섞여 있었소. 칠십 년 전에 정청 손을 떠난 문서요. 어떤 길로 흑련 금고에 들어갔든 정청 것은 정청이 거두는 법이라, 장부째 정청이 맡았소."},{"s":"q:md_gyeonghyeon","t":"그림자 흐린 사람이라니, 문지기들 눈이 많이 피곤했던 모양이오. 찢긴 장은 안타깝구려."},{"s":"q:md_gyeonghyeon","t":"다만 이 공문은 내 이름으로 낸 것이오. 누가 시켜서 낸 게 아니니, 따질 일이 있으면 나한테 따지시오."},{"s":null,"t":"경현의 눈길이 안쪽 방으로 향했다. 열린 문 너머로 월하의 늘어진 손이 보였다."},{"s":null,"t":"경현이 말을 멈추고 한참 그 손을 보았다. 공문을 쥔 손가락에 힘이 들어가 종이가 바스락 구겨졌다."},{"s":null,"t":"다온이 침상 앞으로 뛰어나왔다. 두 팔을 활짝 벌려 월하를 가렸다."},{"s":"q:mk_daon","t":"오지 마세요! 아저씨 이름을 찢어 간 사람들 대장이죠! 저 다 들었어요!"},{"s":null,"t":"경현이 천천히 무릎을 굽혀 다온과 눈높이를 맞췄다. 품에서 곶감 하나를 꺼내 내밀었다."},{"s":"q:md_gyeonghyeon","t":"다온이라고 했던가. 묵창 나루 명부에 적힌 이름이구나. 이건 먹어도 되는 곶감이다. 독은 없어."},{"s":null,"t":"다온은 곶감과 경현을 번갈아 보기만 하고 받지 않자, 경현은 곶감을 다온 발치의 문턱에 가만히 내려놓았다."},{"s":null,"t":"경현이 일어서며 나를 보았다. 눈길이 밤새 갈라진 내 입술에 잠깐 머물렀다."},{"s":"q:md_gyeonghyeon","t":"조사원, 또 뵙소. 밤새 이 사람 이름을 불러 주셨다지요. 입술이 다 튼 걸 보니 알겠소."},{"s":"q:md_gyeonghyeon","t":"이름을 부르는 게 늘 좋은 일이라 생각하오? 나는 부르는 소리에 사람이 죽는 걸 봤소. 한 사람을 살리려고 부르다가, 부르던 사람이 먼저 먹으로 풀려 버리기도 하오."},{"s":null,"t":"나는 장부를 돌려 달라고 했다. 경현이 공문의 오른쪽 위 모서리를 반듯하게 접었다."},{"s":"q:md_gyeonghyeon","t":"장부를 돌려줄지는 정청이 정하오. 정청에 와서 물으시오. 오시면 나는 언제든 차를 내겠소."},{"s":null,"t":"경현이 공문을 구슬에게 건네고 돌아섰다. 칼을 든 문지기들 사이를 지나며 한 사람씩 눈을 맞췄다."},{"s":"q:md_gyeonghyeon","t":"수고하오, 막쇠. 칼끝이 떨리는구려, 두례. 막동이는 어머니 병이 좀 나으셨소?"},{"s":null,"t":"문지기들이 움찔하며 칼을 내렸다. 아무도 그에게 이름을 말한 적이 없었다. 경현의 발소리가 계단 위로 천천히 멀어졌다."},{"s":null,"t":"침상의 월하가 구슬에게 손짓했다. 월하가 공문을 받아 코에 대고 길게 냄새를 맡았다. 얼굴에서 웃음기가 싹 가셨다."},{"s":"q:mk_wolha","t":"우리 장부 찢어 간 손이랑 같은 먹 냄새네요. 오래 고여서 썩은 먹이요. 거둠꾼은 이 냄새를 못 잊어요. 처음 이름을 거둔 날 맡은 냄새라서."},{"s":null,"t":"다온이 문턱의 곶감을 내려다보다 발끝으로 멀리 밀어냈다. 월하가 그걸 보고 피식 웃었다."},{"s":"q:mk_wolha","t":"잘했어. 공짜 곶감이 제일 비싼 법이야. …조사원, 그 장부를 꼭 찾아와요. 내 이름값은 그걸로 치죠."},{"s":null,"t":"구슬이 공문을 접어 들고 나를 보았다."},{"s":"black_lotus:guseul","t":"정청 일이라니, 정청 감찰관께 이 공문을 보여 드려야겠어요. 심부름꾼은 벌써 보냈어요. 감찰관께서 오실 때까지 그 물길이 어디서 끝나는지 끝까지 따라가 봐 주세요. 그걸 알아야 따질 데가 생기니까요."}],"reward":{"xp":2468}},{"quest_id":"mdq_2","step":6,"title":"두 통의 서신","goal":"지맥의 뿌리로 원정을 한 번 끝까지 다녀와 먹 물길이 끝나는 곳을 살핀다","need":{"at":["ledger_cellar"],"tasks":[{"t":"expedition","r":["under_root"],"n":1}]},"lines":[{"s":null,"t":"원정에서 돌아오니 장부고 입구에 한설이 서 있었다. 문지기들이 칼을 반쯤 뽑은 채 어쩔 줄을 몰랐다."},{"s":null,"t":"한설의 손에 봉투 두 개가 들려 있었다. 하나는 정청 인장, 하나는 작은 개인 인장이 찍힌 봉투였다."},{"s":"night_office:han","t":"늦었다. 정청 출입 장부를 뒤지느라. 그날 밤 서고 줄이 칼로 오려져 있더구나."},{"s":"night_office:han","t":"칼질이 서툴러서 아랫줄까지 반쯤 베였더라. 장부를 다뤄 본 손이 아니야. 정청 서리라면 그렇게 오리지 않는다."},{"s":"night_office:han","t":"하나 더 있다. 지난달에 정리관이 묵창 나루 희수 서리를 불러들였다더라. 왜 다온이라는 아이 이름 옆에 칸을 그었는지, 누가 시켰는지 반나절을 캐물었대. 희수는 아무도 안 시켰다고만 했고."},{"s":null,"t":"다온이 희수의 이름을 듣고 고개를 번쩍 들었다."},{"s":"q:mk_daon","t":"서리님이요? 서리님 혼났어요? 서리님은 제 이름 지켜 준 건데요!"},{"s":null,"t":"한설이 다온을 내려다보았다. 굳은 얼굴이 조금 풀렸다."},{"s":"night_office:han","t":"혼나지 않았다. 희수 서리는 고집이 세더구나. …조사원, 물길은 어디까지 가더냐."},{"s":null,"t":"나는 먹 물길이 정청 쪽으로 이어지다가 장서각 아래에서 끊겼다고 했다. 한설이 눈을 감았다 떴다."},{"s":"night_office:han","t":"그럼 됐다. 장서각 불도, 흑련 장부도 정청 안에서 났다는 거지."},{"s":null,"t":"구슬이 경현이 두고 간 공문을 내밀었다. 한설이 공문을 읽고 접힌 모서리를 엄지로 쓸었다. 엄지가 그 자리에서 오래 머물렀다."},{"s":"night_office:han","t":"…정리관 공문이다. 장부를 거둔 건 정청 일이라고 적혀 있군. 명부 일에는 정리관이 정청 인장을 쓸 수 있게 됐으니, 틀린 말은 아니야."},{"s":null,"t":"한설이 공문을 내려놓고 정청 인장이 찍힌 봉투를 열었다."},{"s":"night_office:han","t":"열흘 남짓 전에 정청에서 이게 나갔다. 정리관이 몸소 들고 나가서, 북령부터 적월, 수향, 남명, 천명 순으로 돈다더라. 나는 오늘 아침에야 서리방에 남은 사본을 봤다."},{"s":null,"t":"구슬의 주판 소리가 뚝 멎었다."},{"s":"black_lotus:guseul","t":"그럼 흑련은 빠졌어요?"},{"s":null,"t":"한설이 공문 쪽으로 턱을 들었다."},{"s":"night_office:han","t":"흑련에는 안 온다. 흑련 장은 그 사람이 벌써 가져갔으니까. 읽어 주마."},{"s":"night_office:han","t":"「삼백 년 전 맹약 낱장을 동지 전까지 정청에 모두 반납하라. 반납하지 않는 세력은 정청이 맡은 명부 일을 멈춘다.」 …정청 인장에 결재는 정리관. 판관 회의 도장은 하나도 없다. 그분 혼자 낸 거야."},{"s":null,"t":"구슬의 주판알이 차르르 흘러내렸다. 구슬이 주판을 꽉 붙잡았다."},{"s":"black_lotus:guseul","t":"명부 일을 멈춘다는 건… 그 세력 사람 이름을 정청이 지켜 주지 않겠다는 거잖아요. 장사로 치면 빚 대신 목을 내놓으라는 소리예요."},{"s":null,"t":"한설이 고개를 끄덕이고 두 번째 봉투를 꺼내 내 손에 쥐여 주었다."},{"s":"night_office:han","t":"이건 내가 쓴 편지다. 사본은 안 만들었다. 서리방을 거치면 정리관 귀에 먼저 들어가니까. 네가 들고 다니면서 수장마다 보여라."},{"s":"night_office:han","t":"「반납하지 마십시오. 장서각 불은 정청 안에서 났고, 흑련 장부를 가져간 손도 정청 안으로 드나드는 손이었습니다. 저는 아직 누가 왜 그러는지 모릅니다. 낱장을 꺼내야 한다면 이 편지를 든 조사원에게 들려 보내시고, 못 믿으시겠거든 믿을 사람을 붙여 함께 보내 주십시오.」"},{"s":null,"t":"나는 편지에서 고개를 들어 한설에게 왜 나냐고 물었다. 편지를 든 조사원이 바로 나였다."},{"s":null,"t":"한설이 손가락을 하나 폈다."},{"s":"night_office:han","t":"첫째, 기록관한테 들었다. 묵창 나루 서리가 네 이름을 칸에 적은 밤에 그 장이 흔들렸다지. 장이 네 이름에 대답한 거다. 장이 대답하는 사람이 장을 들고 다녀야지."},{"s":null,"t":"한설이 손가락을 하나 더 폈다."},{"s":"night_office:han","t":"둘째, 일곱 세력이 다 너한테 빚이 있다. 붉은 인장 때도, 묵창 나루 때도 그랬지. 내 편지는 안 믿어도 네 얼굴은 믿을 거다."},{"s":"night_office:han","t":"셋째, 정청 사람을 보내면 정리관 귀에 들어간다. 너는 정청 조사원이지만 정청 관리는 아니야. 네가 어디로 가는지 결재할 사람이 없다."},{"s":null,"t":"한설의 목소리가 조금 낮아졌다. 한설이 공문의 접힌 모서리를 내려다보았다."},{"s":"night_office:han","t":"…그리고 넷째는 장부에 안 적을 거다."},{"s":null,"t":"한설이 붓을 쥔 손가락을 하나씩 접었다 폈다. 한참 만에 다시 입을 열었다."},{"s":"night_office:han","t":"몇 해 전 동지에, 나랑 한 조로 일하던 감찰 동료 셋이 그해 먹 거두기 명부에 올라 한 밤에 없어졌다. 셋 다 마지막 보고서가 고쳐져 있었어. 고친 자리마다 먹이 두 번 앉아 있었다. 누가 고쳤는지는 아직 못 찾았다. …그래서 나는 지금 정청 안에서 누구를 믿어야 할지 모르겠다."},{"s":null,"t":"침상의 월하가 웃으려다 말고 기침을 했다. 기침이 잦아들자 월하가 천장을 보며 중얼거렸다."},{"s":"q:mk_wolha","t":"감찰관님이 흑련 장부고에서 속을 다 털어놓으시네. 이거 장부에 적어 둬야 해요, 구슬 씨. 정청 사람이 흑련한테 속을 턴 날이라고."},{"s":null,"t":"구슬이 주판알을 하나 탁 올리며 대꾸했다."},{"s":"black_lotus:guseul","t":"벌써 적었어요."},{"s":null,"t":"한설은 대꾸 대신 붓을 꺼내 소매로 천천히 닦았다. 아까 공문의 접힌 모서리를 쓸던 엄지보다 붓을 닦는 손길이 한결 차분했다."},{"s":"night_office:han","t":"명령서는 그 사람이 한 걸음 앞서 들고 간다. 내 편지는 네 손으로 직접 보여라. 다섯 곳을 다 돌거든 봉인고로 와라. 압수물 함에 백 년 전 서식이 있다. 그걸 보면 정청이 그 장으로 뭘 하려는지 실마리가 나올 거다."},{"s":"night_office:han","t":"우리가 할 일은 하나다. 정리관보다 먼저 장을 찾는 거."},{"s":null,"t":"나는 어디부터 가냐고 물었다. 한설이 북쪽으로 턱을 들었다."},{"s":"night_office:han","t":"북쪽부터다. 철벽 고찰은 명령서를 받고도 대답이 없다. 북령은 원래 대답 대신 사람을 보내는 곳이야. 길이 멀고 눈이 깊으니 건량부터 넉넉히 챙겨라."}],"reward":{"xp":2468}},{"quest_id":"mdq_2","step":7,"title":"엽전 하나","goal":"먼 길 채비로 노정 건량 4개를 만들어 흑련 장부고에서 넘긴다","need":{"at":["ledger_cellar"],"tasks":[{"t":"craft","items":["travel_ration"],"n":4}],"give":{"travel_ration":4}},"lines":[{"s":null,"t":"떠나는 아침, 다온이 계단 끝까지 따라 나왔다. 쪽지와 약과 싼 손수건이 품에서 볼록했다."},{"s":"q:mk_daon","t":"{이름} 님, 편지 쓸게요. 아저씨 얘기 날마다 쓸게요. 저 글씨 잘 써요. 아저씨가 장부 글씨로 가르쳐 줬어요."},{"s":null,"t":"나는 내가 어디 있을 줄 알고 편지를 보내냐고 물었다. 다온이 구슬을 돌아보았다."},{"s":null,"t":"구슬이 주판을 옆구리에 끼고 어깨를 으쓱했다."},{"s":"black_lotus:guseul","t":"흑련 심부름꾼은 빚진 사람이 어디 있든 찾아내요. 조사원님 하나쯤이야."},{"s":null,"t":"구슬이 말을 맺으며 옆구리의 주판알 하나를 탁 튕겼다."},{"s":null,"t":"침상에서 월하가 나를 불렀다. 다가가자 월하가 오른손으로 엽전 하나를 집어 들었다. 귀퉁이가 이 빠진 상평통보였다."},{"s":"q:mk_wolha","t":"이거 가져가요. 길에서 일이 안 풀리면 튕겨 봐요. 앞면이면 가고, 뒷면이면… 그래도 가고."},{"s":null,"t":"월하가 엽전을 튕기려 했지만, 오른손이 서툴러 엽전이 이불 위로 툭 떨어졌다."},{"s":null,"t":"월하가 떨어진 엽전을 한참 보았다. 다온이 얼른 엽전을 주워 내 손에 꼭 쥐여 주었다."},{"s":"q:mk_wolha","t":"…봐요, 오른손은 아직 수습이라니까. 조사원이 대신 튕겨 줘요. 돌아오면 돌려주고. 이자는 안 받을게."},{"s":null,"t":"나는 엽전을 품속 종이 옆에 넣었다. 흰 불꽃이 엽전을 비추며 가만히 떠 있었다."},{"s":null,"t":"다온이 갑자기 내 허리를 와락 끌어안았다. 작은 몸이 떨렸다."},{"s":"q:mk_daon","t":"빨리 와요. 아저씨 이름을 꼭 찾아와요. 저는 그동안 쪽지를 안 펴고 아저씨를 부르고 있을게요. 약속했으니까요."},{"s":null,"t":"계단을 오르다 돌아보니 다온이 손을 흔들고 있었다. 그 뒤 어둠 속에서 무명의 목소리가 한 번 더 울렸다."},{"s":"black_lotus:mumyeong","t":"조사원. 북쪽 사람들은 이름을 묻어 두는 버릇이 있소. 묻은 것을 억지로 파내지 마시오. 그들이 스스로 꺼내게 두시오."}],"reward":{"xp":2468,"gil":470,"items":{"ledger_tab":2,"moonlight_essence":2}}},{"quest_id":"mdq_3","step":1,"title":"무너지는 눈","goal":"철벽 고찰에 도착해 무너지는 눈 소리를 듣는다","need":{"at":["iron_monastery"],"tasks":[{"t":"travel","r":["iron_monastery"],"n":1}]},"lines":[{"s":null,"t":"철벽 고찰로 오르는 길은 반나절째 눈보라였다. 휘이잉, 바람이 눈발을 옆으로 몰아 뺨을 할퀴었다."},{"s":null,"t":"속눈썹에 맺힌 얼음이 눈을 깜빡일 때마다 서걱거렸다. 품속 엽전이 차갑게 가슴을 눌렀다."},{"s":null,"t":"고갯마루 아래 썰매 넷과 사람 열둘이 멈춰 있었다. 사람들이 발을 동동 구르며 웅성거렸다."},{"s":null,"t":"행렬 맨 앞에서 회색 털 망토를 두른 여자 하나만 움직이지 않았다. 허리에 찬 칼자루 끝에서 붉은 술이 바람에 파르르 날렸다."},{"s":null,"t":"여자는 그 붉은 술이 날리는 쪽을 노려보고 있었는데, 옆으로 날리던 술이 갑자기 아래로 축 꺾였다."},{"s":null,"t":"여자가 고개를 홱 들었다. 쩌렁쩌렁한 목소리가 눈보라를 갈랐다."},{"s":"north_league:yeo","t":"서른 걸음 물리시오! 지금 당장!"},{"s":null,"t":"호송대가 허겁지겁 썰매를 돌렸다. 마지막 썰매가 물러서자마자 고갯마루 위에서 우르르릉, 낮은 소리가 났다."},{"s":null,"t":"비탈의 눈이 통째로 미끄러져 내렸다. 쏴아아, 하얀 파도가 방금까지 호송대가 서 있던 자리를 덮쳤다."},{"s":null,"t":"눈가루가 자욱하게 피어올랐다. 나는 소매로 입을 막고 쿨럭쿨럭 기침을 했다."},{"s":null,"t":"그 쩌렁쩌렁한 목소리를 나는 알았다. 얼음 인장이 녹던 해, 철벽 고찰 산문 앞에서 내 감발을 다시 쳐 주고 옥문 협로 길을 일러 주던 북령 호송대장 여운비였다."},{"s":null,"t":"눈가루가 가라앉자 여운비가 장갑을 다시 끼고 그제야 나를 보았다. 내 얼굴을 알아본 눈이 가늘어지더니, 곧장 내 발로 내려갔다."},{"s":"north_league:yeo","t":"…당신이었구려. 옥문 협로 가던 날 감발도 제대로 못 치던 정청 사람. 하마터면 눈 밑에서 다시 인사할 뻔했소.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:yeo","t":"또 보는구려. 이번엔 정청 표식에 적월 붉은 실까지 달았소. 이 고개에서 그 실을 보고도 칼을 안 뽑는 건 맹주님 명 때문이오. 잊지 마시오.","fac":"red_moon_cult","spec":1,"grp":1},{"s":"north_league:yeo","t":"옥문 협로에서 감발을 쳐 준 그 정청 사람이 산문 패까지 찼구려. 맹주님이 오늘 올 사람이 있다 하셨는데, 당신일 줄은 몰랐소.","fac":"north_league","rank":[1,2],"spec":0,"grp":1},{"s":"north_league:yeo","t":"{등급}이셨구려. 눈보라 속이라 얼른 못 알아봤소. 감발을 쳐 드린 게 엊그제 같은데. 맹주님이 정청 사람이 온다 하셨는데, 당신이었을 줄은 몰랐소.","fac":"north_league","rank":[3,4],"spec":0,"grp":1},{"s":"north_league:yeo","t":"장로님. 이 눈보라에 몸소 걸어 올라오시다니요. 옥문 협로 때처럼 감발 하나 믿고 오셨소? 호송대를 내려보낼 것을 그랬소.","fac":"north_league","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 눈이 무너질 걸 어떻게 알았냐고 물었다. 여운비가 칼자루의 붉은 술을 손가락으로 툭 쳤다."},{"s":"north_league:yeo","t":"이게 먼저 아오. 산바람이 갑자기 아래로 꺾이면 위에서 눈이 무너질 참이란 뜻이오. 북령 호송대는 다 이걸 달고 다니오."},{"s":"north_league:yeo","t":"맹주님이 정청 사람이 오면 고찰로 모시라 하셨소. 그게 당신일 줄은 몰랐지만. 따라오시오. 이번엔 발밑 보고.","fac_not":"north_league","spec":2,"grp":2},{"s":"north_league:yeo","t":"고찰까지는 내가 앞장서겠소. 맹주님이 화로 앞에서 기다리시오.","fac":"north_league","spec":1,"grp":2},{"s":null,"t":"고찰 대웅전 처마 아래, 맹주 석진악이 화로 앞에 앉아 있었다. 등이 바위처럼 넓은 노인이었다. 곁에서 수좌 혜각이 염주를 굴리며 빙그레 웃고 있었다."},{"s":null,"t":"내가 한설의 편지를 내밀자 석진악은 손으로 받기 전에 코부터 갖다 댄 뒤에야 봉투에서 편지를 꺼내 천천히 읽었다."},{"s":"north_league:seok","t":"…자네로구먼. 얼음 인장이 녹던 해, 빙혼곡에서 봉인 조각을 주워 온 그 조사원. 그 인장 아래 무엇이 잠들어 있었는지 본 사람이지. 감찰관 편지로군. 열흘 전에 온 명령서와는 먹 냄새부터 다르구먼.","fac_not":"north_league","spec":2,"grp":3},{"s":"north_league:seok","t":"…맹약을 외운 지 얼마 안 된 아이가 정청 편지를 들고 왔구먼. 열흘 전에 온 명령서와는 먹 냄새부터 다르네.","fac":"north_league","rank":[1,2],"spec":0,"grp":3},{"s":"north_league:seok","t":"…{등급}이 이 편지를 들고 올 줄은 알았네. 열흘 전에 온 명령서와는 먹 냄새부터 다르구먼.","fac":"north_league","rank":[3,4],"spec":0,"grp":3},{"s":"north_league:seok","t":"…장로가 정청 편지를 들고 오다니, 세상 많이 바뀌었구먼. 이건 자네와 내가 함께 정할 일일세.","fac":"north_league","rank":[5,5],"spec":0,"grp":3},{"s":"north_league:seok","t":"그 명령서를 들고 온 사람이 열흘 전 여기 화로 앞에 앉았다 갔네. 정리관이라더군. 공손하더구먼. 차를 세 잔이나 비우고, 솔내 이야기를 하더군."},{"s":null,"t":"혜각의 염주 굴리던 손이 멈췄다. 여운비의 어깨가 아주 조금 굳었다."},{"s":null,"t":"나는 솔내가 무엇이냐고 물었다. 석진악이 부지깽이로 숯을 하나 뒤집었다.","fac_not":"north_league","spec":2,"grp":4},{"s":null,"t":"솔내라는 이름은 나도 산문에서 들었다. 하룻밤에 사라진 고을이라는 것까지만 들었고, 그 이상은 아무도 말해 주지 않았다. 나는 그 고을에 무슨 일이 있었느냐고 물었다. 석진악이 부지깽이로 숯을 하나 뒤집었다.","fac":"north_league","spec":1,"grp":4},{"s":"north_league:seok","t":"백 년도 더 전에 하룻밤에 사라진 북령 고을일세. 북령 사람이면 다 아는 이름이고, 아무도 입에 담지 않는 이름이지. 그 사람이 그걸 제 집 얘기처럼 하더군.","fac_not":"north_league","spec":2,"grp":4},{"s":"north_league:seok","t":"산문에서 거기까지는 들었겠지. 그 뒤는 북령 사람 누구도 입에 담지 않네. 나도 지금은 못 하네. 그런데 그 사람이 그걸 제 집 얘기처럼 하더군.","fac":"north_league","spec":1,"grp":4},{"s":"north_league:seok","t":"그러고는 얼음 속의 장 얘기를 꺼냈네. 이 고찰에서 나와 혜각 말고는 아무도 모르는 얘기를 말이야."},{"s":null,"t":"석진악이 편지를 접어 내 손에 도로 쥐여 주었다. 그 손등의 핏줄이 불거져 있었다."},{"s":"north_league:seok","t":"정청 말을 따르고 싶은 마음은 있네. 북령은 솔내 일로 백 년 전에 누구보다 먼저 서명한 집이야. 「다시는」이라는 맹세로 말이지. …허나 남의 집 안방 얘기를 다 아는 손님은 반갑지가 않아."},{"s":null,"t":"석진악이 혜각을 보았다. 혜각이 허허 웃었다."},{"s":"north_league:hyegak","t":"맹주님 마음이 둘이니 소승이 하나를 맡지요. 정청 말을 따르면 몸은 편합니다. 다만 맹주님 잠자리가 편치 않으시겠지요."},{"s":null,"t":"석진악이 코웃음을 쳤다. 나를 오래 보다가 화로에 장작을 던져 넣었다."},{"s":"north_league:seok","t":"하룻밤 생각하겠네. 그동안 자네가 할 일이 있어. 설피골에서 올라오던 보급 썰매가 눈에 갇혔네. 고찰 겨울 양식일세. 운비야, 이 사람을 데리고 가거라."},{"s":null,"t":"여운비가 나를 흘끗 보았다. 내키지 않는 얼굴이었다."},{"s":"north_league:yeo","t":"맹주님, 감발도 혼자 못 치던 정청 사람을 썰매 길에 데려가란 말씀입니까. 짐이 될 겁니다.","fac_not":"north_league","spec":2,"grp":5},{"s":"north_league:yeo","t":"맹주님, 산문 패를 찼어도 감발도 혼자 못 치던 사람입니다. 썰매 길은 처음일 테니 짐이 될 겁니다.","fac":"north_league","rank":[1,4],"spec":0,"grp":5},{"s":"north_league:yeo","t":"맹주님, 장로님을 썰매 길에 모시라니요. 눈길에서 다치시기라도 하면 호송대가 무슨 낯으로 고찰에 돌아옵니까.","fac":"north_league","rank":[5,5],"spec":0,"grp":5},{"s":null,"t":"석진악이 부지깽이로 화로 가장자리를 탁 쳤다."},{"s":"north_league:seok","t":"짐이 되는지 안 되는지 길에서 보거라. 사람 됨됨이는 길에서 드러나는 법이다."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":2,"title":"등을 맞댄 눈보라","goal":"설피골에 도착해 썰매 길을 막은 바랜 등롱 나방을 4번 쫓아낸다","need":{"at":["snow_hollow"],"tasks":[{"t":"travel","r":["snow_hollow"],"n":1},{"t":"win","n":4,"m":["dd_yamen_2"],"r":["snow_hollow"]}]},"lines":[{"s":null,"t":"설피골은 온통 하얬다. 눈이 허리까지 쌓여 썰매 자국이 금세 지워졌다."},{"s":null,"t":"보급 썰매 넷은 골짜기 어귀에 반쯤 파묻혀 있었다. 썰매꾼들이 언 손을 호호 불었다."},{"s":null,"t":"썰매 길을 막은 것은 눈보다 하얀 나방 떼였다. 나방이 날개를 털 때마다 바랜 글자 가루가 흩날렸고, 떼가 날아오른 자리에는 젖은 먹 자국이 골짜기 우물가까지 줄지어 남아 있었다. 나는 흑련 장부고 계단에서 본 하얀 것들을 떠올렸다."},{"s":null,"t":"썰매 길을 막은 것들을 쫓아내자 눈보라가 다시 거세졌다. 휘이잉, 쏴아. 한 걸음 앞도 보이지 않았다."},{"s":null,"t":"눈 속에서 그르릉, 낮은 소리가 울렸다. 하나가 아니었다. 사방에서 번들거리는 눈알이 다가왔다."},{"s":null,"t":"여운비가 칼을 뽑으며 내 쪽으로 몸을 돌렸다."},{"s":"north_league:yeo","t":"등 뒤를 조심하시오! 놈들은 늘 뒤에서 물어뜯소!"},{"s":null,"t":"나는 여운비 쪽으로 물러섰다. 쿵, 등과 등이 맞닿았다. 망토 너머로 여운비의 등이 단단했다."},{"s":null,"t":"놈들이 한꺼번에 덤벼들었다. 내 {직업:호위=방패가/월궁=화살이/퇴마=방울 소리가/의무=부채가/봉인=금강령이/암영=단도가/조련=화살과 동무가/*=무기가} 앞을 막는 사이, 여운비의 칼이 내 옆구리 쪽을 휙 스쳐 지나갔다."},{"s":null,"t":"깨갱, 비명과 함께 한 마리가 눈 위를 나뒹굴었다. 다른 한 마리가 내 머리 위로 뛰어올랐다."},{"s":null,"t":"여운비가 내 어깨를 짚고 몸을 틀었다. 칼날이 허공에서 번쩍했다. 놈이 털썩 눈 속에 처박혔다."},{"s":null,"t":"한참을 그렇게 싸웠다. 마지막 놈이 낑낑대며 눈 속으로 달아났다."},{"s":null,"t":"여운비가 숨을 몰아쉬며 칼을 털었다. 칼날의 피가 눈 위에 점점이 박혔다."},{"s":"north_league:yeo","t":"…등은 안 뚫렸구려."},{"s":null,"t":"여운비가 한 말은 그게 다였다. 여운비가 썰매 쪽으로 걸어가 버리자 나는 웃음이 새어 나왔다."},{"s":null,"t":"해가 지자 썰매꾼들이 눈 굴을 파고 모닥불을 피웠고, 여운비는 불가에서 칼을 닦았다."},{"s":null,"t":"여운비가 품에서 육포 하나를 꺼내더니 반으로 뚝 잘라 한쪽을 내게 내밀었다."},{"s":"north_league:yeo","t":"드시오. 고찰 육포요. 질기니 오래 씹으시오."},{"s":null,"t":"나는 고맙다며 육포를 받았다. 정말 질겨서 턱이 아프도록 씹고 있는데, 여운비가 먼저 입을 열었다."},{"s":"north_league:yeo","t":"옥문 협로 때보다 눈 위에서 발을 잘 딛는구려. 그때는 당신이 잔도에서 미끄러질까 봐 내가 화롯가에서 밤새 바람 소리만 들었소."},{"s":null,"t":"나는 그 뒤로 북쪽 길을 몇 번 더 다녔다고 했다. 그날 받아 마신 보리 미숫가루 맛도 아직 기억난다고 했다. 여운비가 육포를 씹다 말고 불을 보았다."},{"s":"north_league:yeo","t":"그날 얼굴이 하얗게 질려 돌아왔을 때, 다시는 이 길로 안 올 줄 알았소. 살아 왔으면 됐다 하고 보냈는데 또 왔구려. …맹주님이 날 붙인 까닭을 알겠소. 시험받는 건 당신만이 아니오."},{"s":null,"t":"나는 무슨 뜻이냐고 물었다. 여운비가 불 속에 장작을 툭 던졌다."},{"s":"north_league:yeo","t":"나는 사람을 잘 안 믿소. 길에서 믿을 건 바람뿐이라고 배웠으니. 맹주님은 내가 누굴 믿는 걸 한 번쯤 보고 싶어 하시오."},{"s":null,"t":"모닥불이 탁 튀었다. 여운비가 칼자루의 붉은 술을 매만졌다."},{"s":"north_league:yeo","t":"내일 새벽 눈이 그치면 썰매를 고개 너머로 끌어 올리오. 비탈이 가팔라 썰매꾼 손이 모자라오. 당신이 줄 하나를 맡아 주시오."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":3,"title":"놓지 않은 줄","goal":"설피골에서 눈 굴 야영으로 쉬고, 설피골 원정을 끝까지 다녀와 철벽 고찰에 도착한다","need":{"at":["iron_monastery"],"tasks":[{"t":"rest","r":["snow_hollow"],"n":1},{"t":"expedition","r":["snow_hollow"],"n":1},{"t":"travel","r":["iron_monastery"],"n":1}]},"lines":[{"s":null,"t":"고개 비탈은 생각보다 가팔랐다. 썰매 넷을 줄로 묶어 썰매꾼들과 한 발 한 발 끌어 올렸다."},{"s":null,"t":"셋째 썰매가 얼음판에서 미끄러졌다. 끼이익, 썰매가 벼랑 쪽으로 미끄러지며 줄이 팽팽하게 당겨졌다."},{"s":null,"t":"썰매꾼 하나가 새된 비명을 질렀다."},{"s":"q:md_sledder","t":"줄! 줄이 끊긴다! 놔, 놔! 같이 떨어져!"},{"s":null,"t":"줄을 쥔 썰매꾼 둘이 끌려가며 넘어지자 나는 줄을 손목에 감고 눈 속에 발을 박았다."},{"s":null,"t":"손바닥이 쓸리며 화끈거렸다. 줄이 손목을 파고들었다. 썰매는 벼랑 끝에서 반쯤 허공에 걸린 채 대롱거렸다."},{"s":null,"t":"앞에서 여운비가 돌아섰다. 붉은 술이 휙 날렸다."},{"s":"north_league:yeo","t":"놓지 마시오! 조금만 버티시오!"},{"s":null,"t":"여운비가 눈밭을 미끄러지듯 달려와 내 뒤에서 줄을 함께 잡았다. 둘이 한꺼번에 힘을 주었다."},{"s":null,"t":"끄으응. 썰매가 덜컹 소리를 내며 비탈 위로 올라왔다."},{"s":null,"t":"썰매꾼들이 와아 소리를 질렀다. 나는 눈밭에 털썩 주저앉았다. 손바닥이 벌겋게 벗겨져 있었다."},{"s":null,"t":"여운비가 내 손을 펴 보았다. 얼굴을 찡그리더니 제 목도리를 풀어 내 손에 둘둘 감았다."},{"s":"north_league:yeo","t":"손목에 줄을 감는 건 하수나 하는 짓이오. 썰매에 딸려 같이 떨어질 뻔했소."},{"s":null,"t":"나는 그래도 썰매는 안 떨어지지 않았냐고 했다. 여운비가 한참 나를 보는데, 입꼬리가 아주 조금 움직였다."},{"s":"north_league:yeo","t":"…나쁘지 않소."},{"s":null,"t":"썰매꾼 하나가 눈을 동그랗게 뜨고 옆 사람 옆구리를 쿡 찔렀다."},{"s":"q:md_sledder","t":"대장님이 칭찬했어. 방금 칭찬한 거 맞지? 나 오 년 동안 한 번도 못 들었는데!"},{"s":null,"t":"여운비가 썰매꾼을 노려보았다. 썰매꾼이 헛기침을 하며 썰매 줄을 잡으러 달아났다."},{"s":null,"t":"해 질 녘 썰매는 무사히 고찰 마당에 닿았는데, 썰매를 부리던 여운비가 우물가에서 걸음을 멈췄다."},{"s":null,"t":"우물 둘레 눈 위에 검은 발자국이 여럿 찍혀 있었다. 젖은 먹을 밟고 다닌 자국이었는데, 우물 아가리에서 뚝 끊겨 있었다."},{"s":null,"t":"여운비가 쪼그려 앉아 자국을 손가락으로 훑었다. 손끝이 까맣게 묻어났다."},{"s":"north_league:yeo","t":"어젯밤에 생긴 거요. 눈이 덮이지 않았소. 그런데 산문으로 들어온 발자국은 없소. 우물에서 나와서 우물로 들어간 셈이오."},{"s":null,"t":"나는 장서각 서고 배수 우물에서도 이런 발자국을 보았다고 했다. 여운비가 나를 똑바로 보았다."},{"s":"north_league:yeo","t":"…정청 일이 이 산까지 따라 올라왔다는 말이구려."},{"s":null,"t":"혜각이 웃으며 마중을 나왔다. 발자국을 내려다보더니 웃음을 거두지 않은 채 염주를 한 알 넘겼다."},{"s":"north_league:hyegak","t":"허허, 겨울 양식이 왔군요. 그 자국은 소승이 아침에 맹주님께 아뢰지요. 저녁 공양부터 드시고 쉬세요. 오늘 밤은 맹주님이 화로 앞에 사람을 부르신답니다."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":4,"title":"화로 앞의 회의","goal":"철벽 고찰에서 저녁 공양을 들고 쉰다","need":{"at":["iron_monastery"],"tasks":[{"t":"rest","r":["iron_monastery"],"n":1}]},"lines":[{"s":null,"t":"저녁 공양이 끝나자 대웅전 화로 둘레에 넷이 앉았다. 석진악과 혜각과 여운비, 그리고 내가 앉았다."},{"s":null,"t":"바깥바람이 문풍지를 부르르 떨게 했다. 화로 속 숯이 빨갛게 숨을 쉬었다."},{"s":null,"t":"석진악이 부지깽이를 내려놓고 여운비를 보았다."},{"s":"north_league:seok","t":"운비야, 길에서 본 대로 말해 보거라."},{"s":null,"t":"여운비가 무릎 위에 손을 모았다. 목도리를 감은 내 손을 흘끗 보았다."},{"s":"north_league:yeo","t":"줄을 손목에 감는 하수였습니다. 그래도 끝까지 안 놓았습니다. 그 덕에 썰매꾼 둘이 살았습니다."},{"s":null,"t":"석진악이 고개를 끄덕였다. 혜각이 염주를 굴리며 끼어들었다."},{"s":"north_league:hyegak","t":"그럼 정하셔야지요. 명령서대로 낱장을 정청에 보내시렵니까, 감찰관 편지대로 이 조사원에게 들려 보내시렵니까?"},{"s":null,"t":"석진악이 화로를 오래 보았다. 숯 하나가 툭 무너졌다."},{"s":"north_league:seok","t":"둘 다 안 하네."},{"s":null,"t":"여운비가 고개를 들었다. 혜각은 그럴 줄 알았다는 듯이 웃었다."},{"s":"north_league:seok","t":"얼음 속의 장은 꺼낼 수가 없네. 얼음 인장 아래 이름 하나와 함께 얼어 있으니. 그 이름을 불러야 얼음이 풀리는데… 북령은 그 이름을 부르지 않기로 한 집이야."},{"s":null,"t":"나는 누구의 이름이냐고 물었지만 석진악은 대답하지 않았다. 여운비의 손이 칼자루로 갔다가 멈췄다."},{"s":"north_league:seok","t":"그 정리관은 그 얘기까지 알고 있었네. 아무에게도 한 적 없는 얘기를. 그러니 나는 정청을 따를 수도, 자네를 믿고 장을 들려 보낼 수도 없어."},{"s":"north_league:seok","t":"대신 이렇게 하세. 정청이 그 장으로 무엇을 하려는지 자네가 직접 보고 오게. 옳은 일이라면 그때 내가 얼음을 깨 주지."},{"s":"north_league:seok","t":"운비야, 이 사람을 따라가거라. 이 사람이 무엇을 보고 무엇을 거두는지 다 보고 와서 내게 말해 다오."},{"s":null,"t":"여운비는 바로 대답하지 않고 무릎 위에서 주먹을 쥐었다 폈다."},{"s":"north_league:yeo","t":"따르겠습니다. …다만 하나만 여쭙겠습니다. 그 정리관이 솔내 얘기를 할 때, 우리 집안 얘기도 했습니까?"},{"s":null,"t":"화로 둘레가 조용해지고 혜각의 염주 소리도 멎었다. 석진악이 한참 뒤에야 입을 열었다."},{"s":"north_league:seok","t":"…길에서 알게 될 게다. 내 입으로 할 말이 아니야."},{"s":null,"t":"여운비가 고개를 숙이고 더 묻지 않았다."},{"s":null,"t":"혜각이 일어나 대웅전 구석의 방명록을 가져왔다. 혜각이 한 장을 펼쳐 내 앞에 내밀었다."},{"s":"north_league:hyegak","t":"조사원, 하나 보여 드리지요. 열흘 전 그 손님이 남긴 줄입니다. 「정청 정리관 다녀감. 차가 좋았소.」 글씨가 참 반듯하지요? 그런데 이 장 모서리를 보세요."},{"s":null,"t":"방명록 그 장의 오른쪽 위 모서리가 반듯하게 접혀 있었다. 우물에서 본 사본과 똑같은 너비였다."},{"s":"north_league:hyegak","t":"남의 방명록 모서리를 접어 놓고 가는 손님은 처음 봤습니다. 다음에 또 와서 펼쳐 보겠다는 뜻이겠지요. 허허."},{"s":null,"t":"석진악이 장작을 하나 더 넣었다. 불꽃이 확 솟았다."},{"s":"north_league:seok","t":"그 사람, 정청에 한 번 들렀다가 서쪽 백골 장터로 간다더군. 적월에도 같은 걸 들고 간다고 했네. …자네가 서두르면 길에서 마주칠지도 모르겠어."},{"s":null,"t":"백골 장터라는 말에 여운비의 눈썹 한쪽이 올라갔다. 칼자루를 쥔 손에 힘이 들어갔다. 여운비가 나를 돌아보았다."},{"s":"north_league:yeo","t":"…적월이로군. 거기서 내가 칼을 뽑아도 말리지 마시오."},{"s":null,"t":"석진악이 여운비를 보며 낮게 웃었다. 처음 듣는 웃음이었다."},{"s":"north_league:seok","t":"칼은 뽑되, 이 사람 등 뒤에서는 뽑지 말거라. 등을 맞댄 사람끼리는 그러는 게 아니다."},{"s":null,"t":"여운비가 대답 대신 고개를 숙였다. 고개를 든 여운비가 나를 보았다."},{"s":"north_league:yeo","t":"서쪽 길은 사흘이오. 고찰 양식은 겨울 몫이라 손댈 수 없으니, 내려가는 길에 설피골에서 약초와 땔감을 챙겨 가야 하오. 황무지에는 불 피울 나무가 없소."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":5,"title":"고쳐 맨 신 끈","goal":"설피골에서 6번 채집하고 적사 황무지에 도착해 야영으로 쉰다","need":{"at":["red_plain"],"tasks":[{"t":"gather","n":6,"r":["snow_hollow"]},{"t":"travel","r":["red_plain"],"n":1},{"t":"rest","r":["red_plain"],"n":1}]},"lines":[{"s":null,"t":"눈길을 내려와 서쪽으로 사흘을 걷는 동안 땅이 점점 붉어졌다. 적사 황무지의 모래가 바람에 사르륵사르륵 흘렀다."},{"s":null,"t":"해가 지자 모래 언덕 아래 바위틈에 불을 피웠다. 낮의 열기가 빠지자 금세 추워졌다."},{"s":null,"t":"여운비가 불 앞에 앉자마자 내 발을 보았다. 미간이 좁아졌다."},{"s":"north_league:yeo","t":"또 그 꼴이오? 옥문 협로에서 감발 다시 쳐 준 게 언젠데, 신 끈이 그게 뭐요. 다 풀렸구려. 그렇게 걷다간 내일 발목을 접지르오."},{"s":null,"t":"나는 끈을 고쳐 매려 했지만, 언 손가락이 말을 듣지 않았다. 썰매 줄에 쓸린 손바닥도 아직 쓰라렸다."},{"s":null,"t":"여운비가 한숨을 푹 쉬더니 내 발을 자기 무릎으로 끌어당겼다."},{"s":"north_league:yeo","t":"가만있으시오. 이번이 두 번째요. 호송대 막내들도 두 번 가르치면 알아듣소."},{"s":null,"t":"여운비의 손이 빨랐다. 끈을 두 번 엇갈려 발목에 감고, 매듭을 안쪽으로 감췄다."},{"s":"north_league:yeo","t":"북령 매듭이오. 그때 감발에 맨 것과 같은 매듭이니 이번엔 눈여겨보시오. 매듭을 바깥에 두면 덤불에 걸리니 꼭 안쪽에 두시오."},{"s":null,"t":"나는 고맙다고 했다. 여운비는 그때처럼 대꾸 없이 내 발을 툭 내려놓았다."},{"s":null,"t":"불이 타닥타닥 튀었다. 한참 뒤 여운비가 불을 보며 말했다."},{"s":"north_league:yeo","t":"맹주님 앞에선 따르겠다 했지만, 나도 내 몫이 있어서 따라온 것이오."},{"s":null,"t":"나는 그 몫이 무엇이냐고 물었다. 여운비가 칼자루의 붉은 술을 만지작거렸다."},{"s":"north_league:yeo","t":"우리 집안에는 아무도 이름을 입에 올리지 않는 어른이 한 분 계시오. 어릴 적에 한 번 물었다가 크게 혼났소. 그 정리관이 솔내까지 안다면, 그 까닭도 알고 있을지 모르오."},{"s":"north_league:yeo","t":"맹주님은 우리 장이 어떻게 되는지 보고 오라 하셨소. 나는 그 길에 그 어른 일도 알아 올 생각이오. 이번에 못 물으면 평생 못 물을 것 같소."},{"s":null,"t":"나는 적월은 왜 그렇게 싫어하냐고 물었다. 여운비의 눈이 차가워졌다."},{"s":"north_league:yeo","t":"적월은 이름을 사고파는 집이오. 지워진 이름을 사다가 서약에 쓰지. 북령은 이름을 지키려고 칼을 차는 집이고. …장터에서 그 사람들 웃는 얼굴을 보면 당신도 알게 될 것이오."},{"s":null,"t":"그때 모래 언덕 너머에서 말방울 소리가 딸랑딸랑 다가왔다. 정청 깃발을 단 파발꾼이었다."},{"s":null,"t":"파발꾼이 말에서 내려 내게 봉투 하나를 내밀었다. 한설의 개인 인장이 찍혀 있었다."},{"s":"q:md_courier","t":"감찰관님 서신입니다. 북쪽 길로 가셨다기에 사흘을 따라왔습니다. 답장은 안 받아 오셔도 된다고 하셨습니다."},{"s":null,"t":"나는 불빛에 서신을 펼쳤다. 한설의 짧은 글씨가 줄줄이 박혀 있었다."},{"s":"night_office:han","t":"「조사원, 보아라. 서고에서 찍어 둔 먹을 정청 명부 먹과 견주어 보았다. 같은 그을음, 같은 아교다. 명부를 쓰는 먹이 틀림없다.」"},{"s":"night_office:han","t":"「장부고에서 주웠다는 조각의 이름도 찾았다. 곽두칠. 열 해 전 정리 명부에 올라 있었다. 명부에 오른 사람은 그해 안에 모두 없어져야 하는데, 이 사람은 없어진 기록이 없다. 정청 명부에 올랐는데 사라지지 않은 사람이다. 나도 처음 보는 일이다.」"},{"s":"night_office:han","t":"「먹 발자국이 보이거든 우물부터 살펴라. 서고 것도 우물로 이어졌다. 그리고 몸 조심해라. 이건 적지 않는다.」"},{"s":null,"t":"여운비가 서신 너머로 고개를 기울였다. 마지막 줄에서 여운비가 코웃음을 쳤다."},{"s":"north_league:yeo","t":"「이건 적지 않는다」라니. 감찰관이란 사람이 꽤 정이 많구려. …고찰 우물가 발자국도 그렇고, 명부에 올랐는데 안 사라진 사람이라. 우물로 다니는 놈들이 있다는 말이오?"},{"s":null,"t":"나는 모르겠다고 했다. 여운비가 망토를 끌어 덮고 등을 돌려 눕더니, 잠시 뒤 등 너머로 말했다."},{"s":"north_league:yeo","t":"불은 내가 새벽에 보겠소. 먼저 자시오. 길잡이 몫이오. …아까부터 바위 너머에서 먹 낀 것들이 어슬렁거리오. 날이 밝으면 장터 가는 길목부터 치우고 갑시다."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":6,"title":"액막이 무녀","goal":"적사 황무지 새벽 길목에서 부르다 굳은 넋을 3번 풀어 보내고 백골 장터에 도착한다","need":{"at":["bone_market"],"tasks":[{"t":"win","n":3,"m":["dd_yamen_1"],"r":["red_plain"]},{"t":"travel","r":["bone_market"],"n":1}]},"lines":[{"s":null,"t":"새벽 길목에서 쫓아낸 것들도 입을 벌린 채 굳은 하얀 넋이었는데, 쓰러지자 먹물로 풀려 바위틈 마른 우물 속으로 스며들었다."},{"s":null,"t":"백골 장터는 대낮인데도 붉었다. 천막마다 붉은 천이 늘어지고 향 연기가 낮게 깔렸다."},{"s":null,"t":"짐승 뼈로 엮은 풍경이 바람에 달그락달그락 부딪혔다. 눈길에 얼었던 볼이 후끈 달아올랐다."},{"s":null,"t":"장터 큰길 끝에서 정청 깃발을 단 가마 하나가 막 떠나고 있었다. 가마꾼 넷이 발을 맞춰 영차영차 걸었다."},{"s":null,"t":"가마가 우리 곁을 지날 때 발이 걷혔다. 안에 정리관 경현이 장부를 무릎에 펴고 앉아 있었다."},{"s":"q:md_gyeonghyeon","t":"또 뵙소, 조사원. 길이 겹치는구려. 북령 호송대장까지 데리고 오셨군. 여운비, 맞지요? 여씨 집안 셋째 딸."},{"s":null,"t":"여운비가 칼자루를 확 움켜쥐었지만, 경현은 눈길 하나 주지 않고 장부 모서리를 접었다."},{"s":"q:md_gyeonghyeon","t":"한발 늦으셨소. 교주는 내가 먼저 만나 차를 얻어 마셨소. 다음 거점에는 당신이 먼저 닿길 바라오. 늘 한 걸음씩 늦으면, 물을 것은 내가 다 묻고 간 뒤일 테니."},{"s":null,"t":"발이 내려지고 가마가 멀어졌다. 여운비가 이를 악물었다."},{"s":"north_league:yeo","t":"…저 사람이 정리관이오? 내 이름을 어떻게 아는 거요. 셋째 딸이란 건 또 어떻게."},{"s":null,"t":"나는 한설에게 들은 대로 정리관은 한 번 들은 이름을 잊지 않는다고 했다. 여운비가 고개를 저었다."},{"s":"north_league:yeo","t":"나는 저 사람한테 이름을 말한 적이 없소. 들은 적이 없는 이름을 어떻게 안다는 거요."},{"s":null,"t":"나는 대답할 말을 찾지 못했다. 그때 장터 한가운데서 짤랑짤랑 방울 소리가 울렸고, 여운비와 나는 동시에 그쪽으로 고개를 돌렸다."},{"s":null,"t":"공터에 아이들이 둥글게 모여 있었다. 그 가운데서 붉은 무복을 입은 젊은 여자가 방울을 흔들고 있었다."},{"s":null,"t":"방울이 울릴 때마다 아이들 이마에 붙은 종이 부적이 한 장씩 하얗게 타서 사라졌다. 부적이 사라진 아이는 꺄르르 웃으며 뛰어나갔다."},{"s":null,"t":"마지막 아이까지 마치자 여자가 품에서 엿을 꺼내 아이 손에 쥐여 주었다. 자기 입에도 하나 쏙 넣었다."},{"s":null,"t":"내 뒤에서 철컥, 쇳소리가 났다. 여운비가 칼자루에 손을 얹은 소리였다."},{"s":null,"t":"여자가 고개를 돌렸다. 웃음은 그대로인데 눈은 웃지 않았다."},{"s":null,"t":"그 얼굴을 나는 알았다. 붉은 인장 일 때 이 장터 붉은 등 아래서 나를 「장부 손님」이라 부르며 사탕을 내밀던 주홍 무녀 단비였다."},{"s":"red_moon_cult:danbi","t":"어머, 북령 호송대장님이시죠? 썰매 끄는 분. 장터 한가운데서 칼을 뽑으시면 저는 소리를 지를 거예요. 이 장터에 제 편은 반쯤이지만, 북령 편은 한 명도 없을걸요?"},{"s":null,"t":"여운비의 턱에 힘이 들어갔지만, 칼을 뽑지는 않았다."},{"s":"north_league:yeo","t":"썰매는 썰매꾼이 끄오. 아이들한테 무엇을 한 거요?"},{"s":null,"t":"단비가 엿을 오도독 깨물었다. 대수롭지 않다는 얼굴이었다."},{"s":"red_moon_cult:danbi","t":"액막이요. 요즘 애들 이마에 먹 같은 게 껴요. 그냥 두면 이름이 흐려지거든요. 적월 축문으로 태우면 깨끗해지고요. 북령에서는 이런 거 안 해 주나 봐요?"},{"s":null,"t":"여운비가 대꾸할 말을 못 찾고 입을 다물었다. 단비가 그 얼굴을 재미있다는 듯 보다가 내 쪽으로 몸을 돌렸다."},{"s":"red_moon_cult:danbi","t":"장부 손님, 또 오셨네요. 정청 먹 냄새는 여전하시고요. 교주님이 기다리세요. 아니, 기다리시는 건 아니고 오면 데려오라셨어요. 비슷한 말이죠, 뭐.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:danbi","t":"장부 손님, 또 오셨네요. 어머, 이번엔 북령 패까지 차셨네. 북령 분이 둘이나 오시다니, 오늘 장터가 시끄럽겠어요. 교주님이 오면 데려오라셨으니 칼은 천막 밖에 두고 가세요.","fac":"north_league","spec":1,"grp":1},{"s":"red_moon_cult:danbi","t":"장부 손님, 또 오셨네요. 그때는 정청 손님으로 모셨는데, 이번엔 교도님으로 모시네요. 교주님이 오면 데려오라셨어요.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"어머, 장부 손님이 이제 {등급}님이시네. 장터에 오시면 미리 기별을 주시지 그러셨어요. 교주님이 오늘 올 정청 사람을 데려오라셨는데, 그게 {등급}님이었네요.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"장로님! 아니, 장부 손님이라고 불러야 반가워하시려나. 장터 한가운데로 북령 칼을 데리고 다니시다니, 역시 겁이 없으세요. 교주님이 기다리세요.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"그때 그 사탕은 드셨어요?"},{"s":null,"t":"나는 아직 정청 서랍에 있다고 했다. 단비가 입을 가리고 깔깔 웃었다."},{"s":"red_moon_cult:danbi","t":"조심성은 여전하시네. 아까 정리관 나리 가마 보셨죠? 교주님이 오늘 손님 복이 터지셨어요."},{"s":null,"t":"단비가 공터 뒤를 돌아보았다. 아직 이마에 부적을 붙인 아이들이 길게 줄을 서 있었다."},{"s":"red_moon_cult:danbi","t":"근데 교주님은 해 질 녘까지 의식 중이세요. 그동안 저 좀 도와주실래요? 아직 줄 선 애들이 서른이 넘는데 부적이 다 떨어졌거든요. 정화 부적을 접어 주시면 제가 태울게요."},{"s":null,"t":"단비가 여운비 쪽으로 고개를 돌렸다."},{"s":"red_moon_cult:danbi","t":"대장님도요. 칼만 쥐고 서 계시면 손이 심심하잖아요?"},{"s":null,"t":"여운비가 기가 막힌다는 얼굴로 나를 보았다. 나는 이미 소매를 걷고 있었다."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":7,"title":"면사포 너머","goal":"정화 부적 4장을 만들어 백골 장터의 단비에게 넘긴다","need":{"at":["bone_market"],"tasks":[{"t":"craft","items":["ward_talisman"],"n":4}],"give":{"ward_talisman":4}},"lines":[{"s":null,"t":"해 질 녘까지 아이 서른둘의 이마가 깨끗해졌다. 여운비도 마지못해 부적 다섯 장을 접었다. 모서리가 칼로 벤 듯 반듯했다."},{"s":null,"t":"단비가 여운비의 부적을 들어 해에 비춰 보았다. 감탄하는 척 눈을 크게 떴다."},{"s":"red_moon_cult:danbi","t":"어머, 대장님 부적 접는 솜씨 좀 봐요. 칼 대신 이걸로 먹고사셔도 되겠어요."},{"s":null,"t":"여운비가 부적을 홱 빼앗아 단비 손에 탁 쥐여 주었다."},{"s":"north_league:yeo","t":"…그만 놀리시오. 그리고 대장이라고 부르지 마시오."},{"s":null,"t":"단비가 눈을 동그랗게 떴다. 일부러 지어 보이는 얼굴이었다."},{"s":"red_moon_cult:danbi","t":"그럼 뭐라고 불러 드릴까요, 대장님?"},{"s":null,"t":"여운비가 고개를 홱 돌려 버렸다. 단비가 웃으며 엿을 하나 더 입에 넣었다."},{"s":null,"t":"교주의 천막은 장터 맨 안쪽에 있었다. 문 앞을 지키던 거한, 대호법 사마겸이 우리 앞을 막아섰다."},{"s":"red_moon_cult:sama","t":"월식성에서 살아 나간 정청 개가 북령 칼을 하나 달고 왔군. 흥, 교주님이 오늘은 귀찮은 손님만 받으시는군.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:sama","t":"교도가 북령 칼을 달고 다니는구나. 흥, 교주님 손님이니 들어가라. 칼은 두고.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"{등급}께서 북령 칼을 데리고 오셨군. 흥, 교주님이 기다리시니 들어가시오. 칼은 두고.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"장로님. 북령 칼까지 거두어 오실 줄은 몰랐습니다. 교주님이 기다리십니다.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"단비가 사마겸의 팔뚝을 손가락으로 톡 밀었다. 거한이 못마땅한 얼굴로 비켜섰다."},{"s":null,"t":"붉은 면사포 너머에 교주 월화가 앉아 있었다. 얼굴은 보이지 않았지만, 면사포 아래로 드러난 손등이 반쯤 잿빛이었다."},{"s":null,"t":"월화가 한설의 편지를 받아 들고 오래 읽었다. 그동안 다른 손으로 가슴께를 꾹 누르고 있었다."},{"s":"red_moon_cult:wolhwa","t":"월식성의 거울 앞에 섰던 조사원이로구나. 달이 먹히던 밤에 우리 성채를 지나 물 밑의 문을 보고 간 사람. 적월은 그 밤을 잊지 않았다."},{"s":"red_moon_cult:wolhwa","t":"정청 감찰관은 반납하지 말라 하고, 정리관은 반납하라 하는구나. 정청 사람 둘이 서로 다른 말을 하니, 적월은 어느 쪽 차를 마셔야 하느냐."},{"s":null,"t":"나는 장을 정청에 내지 말아 달라고 했다. 월화가 면사포 너머로 고개를 기울였다."},{"s":"red_moon_cult:wolhwa","t":"그대 이름이 무엇이라 했지?"},{"s":null,"t":"나는 이름을 말했다. 월화가 천천히 따라 읊었다."},{"s":"red_moon_cult:wolhwa","t":"{이름}. …{이름}이라. 좋은 이름이구나. 잘 불리겠어."},{"s":null,"t":"월화가 다시 가슴을 눌렀다. 면사포 아래로 숨소리가 거칠어졌다가 가라앉았다."},{"s":"red_moon_cult:wolhwa","t":"낱장은 정청에 내지 않으마. 대신 우리 무녀를 하나 붙여 주지. 그대가 무엇을 보든 적월도 함께 보아야겠으니."},{"s":null,"t":"사마겸이 문 앞에서 콧김을 내뿜었다."},{"s":"red_moon_cult:sama","t":"교주님, 우리 무녀를 정청 개한테 딸려 보내시다니요. 북령 칼까지 붙어 있는 길에요.","fac_not":"red_moon_cult","spec":2,"grp":2},{"s":"red_moon_cult:sama","t":"교주님, 우리 무녀를 갓 들어온 교도한테 딸려 보내시다니요. 북령 칼까지 붙어 있는 길에요.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":2},{"s":"red_moon_cult:sama","t":"교주님, {등급}께서 가시는 길이라도 북령 칼까지 붙어 있습니다. 무녀까지 내주실 일은 아닙니다.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":2},{"s":"red_moon_cult:sama","t":"교주님, 장로님 혼자로도 넉넉한 길입니다. 북령 칼이 붙은 길에 무녀까지 내주실 일은 아닙니다.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":2},{"s":null,"t":"월화는 대답 대신 단비를 보았다. 단비가 엿을 우물거리다 꿀꺽 삼켰다."},{"s":"red_moon_cult:danbi","t":"교주님, 그럼 제가 가도 돼요? 교주님이 시키신 일 중에 처음으로 재밌어 보여요. 대장님 놀리는 것도 재밌고요."},{"s":null,"t":"사마겸이 성큼 나섰다. 단비 앞에 그림자가 산처럼 드리웠다."},{"s":"red_moon_cult:sama","t":"주홍 무녀가 무슨 먼 길을 간다고. 의식 말고는 할 줄 아는 게 없으면서. 저 정청 개가 너를 지켜 줄 것 같으냐?","fac_not":"red_moon_cult","spec":2,"grp":3},{"s":"red_moon_cult:sama","t":"주홍 무녀가 무슨 먼 길을 간다고. 의식 말고는 할 줄 아는 게 없으면서. 정청 일에 끼어 다니는 사람이 너까지 지켜 줄 것 같으냐?","fac":"red_moon_cult","rank":[1,4],"spec":0,"grp":3},{"s":"red_moon_cult:sama","t":"주홍 무녀가 무슨 먼 길을 간다고. 의식 말고는 할 줄 아는 게 없으면서. 장로님께 짐만 될 거다.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":3},{"s":null,"t":"단비가 웃으며 고개를 갸웃했다."},{"s":"red_moon_cult:danbi","t":"그럼 대호법님, 저랑 내기하실래요? 이 조사원이 제 시험을 통과하면 제가 가는 거고, 못 하면 대호법님이 이 사람을 장터 밖으로 던지시는 거예요."},{"s":null,"t":"사마겸이 껄껄 웃으며 주먹을 우두둑 꺾었다. 나는 시험이 무엇이냐고 물었다. 단비가 장터 바깥쪽을 가리켰다."},{"s":"red_moon_cult:danbi","t":"황무지 어귀에 작은 사당이 있는데요, 요 며칠 먹 낀 것들이 사당에 들러붙어서 아이들이 무서워해요. 그것들을 다 쫓아내고 오세요. 첫째 시험이에요. 둘째는 돌아오시면 알려 드릴게요."}],"reward":{"xp":2160}},{"quest_id":"mdq_3","step":8,"title":"엿 내기","goal":"적사 황무지 사당에 들러붙은 서식 긁는 손톱귀를 4번 쫓아내고 백골 장터에 도착한다","need":{"at":["bone_market"],"tasks":[{"t":"win","n":4,"m":["dd_yamen_3"],"r":["red_plain"]},{"t":"travel","r":["bone_market"],"n":1}]},"lines":[{"s":null,"t":"사당의 먹 낀 것들을 다 쫓아내고 돌아오자 단비가 장터 어귀에서 기다리고 있었다. 사마겸이 팔짱을 끼고 그 뒤에 버티고 섰다."},{"s":null,"t":"사당 처마 그늘에 들러붙어 손톱으로 기둥을 긁던 것들도 살갗이 종이처럼 바래 있었고, 사당 뒤 우물에서는 장부고 계단에서 맡은 먹 냄새가 올라왔다."},{"s":"red_moon_cult:danbi","t":"잘하셨어요! 사당 처마에 까마귀가 다시 앉았대요. 까마귀가 앉으면 깨끗해진 거예요. 자, 둘째 시험이에요."},{"s":null,"t":"단비가 등 뒤로 두 손을 감췄다가 주먹 쥔 채 내밀었다."},{"s":"red_moon_cult:danbi","t":"사월이 찾기 내기는 손님이 이기셨죠. 오늘은 제가 이길 차례예요. 엿이 어느 손에 있게요? 맞히시면 그 엿은 드릴게요. 틀리시면 제가 먹고요."},{"s":null,"t":"나는 오른손을 골랐다. 단비가 편 오른손은 텅 비어 있었고, 엿은 왼손에 있었다. 단비가 그 엿을 냉큼 입에 넣었다."},{"s":"red_moon_cult:danbi","t":"어머, 아쉬워라. 그럼 진짜 시험이에요. 눈을 가리고 방울 소리를 맞히시는 거예요. 셋 중에 하나가 제 방울이에요."},{"s":null,"t":"단비가 내 눈을 붉은 천으로 가렸다. 짤랑, 짤그랑, 딸랑. 방울 셋이 차례로 울렸다. 소리가 다 비슷했다."},{"s":null,"t":"내가 망설이는 사이 바람이 살짝 불었다. 곁에서 여운비의 칼자루 술이 사락, 한쪽으로 날리는 소리가 났다."},{"s":null,"t":"여운비가 헛기침을 두 번 했는데, 두 번째 방울이 울린 쪽이었다. 나는 두 번째라고 했다."},{"s":null,"t":"눈가리개를 풀자 단비가 두 손을 허리에 얹고 여운비를 노려보고 있었다."},{"s":"red_moon_cult:danbi","t":"대장님! 지금 헛기침한 거 반칙이죠? 북령은 원래 이렇게 반칙을 해요?"},{"s":null,"t":"여운비가 고개를 돌렸다. 귀 끝이 빨갰다."},{"s":"north_league:yeo","t":"…목이 칼칼했을 뿐이오. 사막 모래가 목에 들어가서."},{"s":null,"t":"단비가 깔깔 웃음을 터뜨렸다. 웃음을 그친 단비가 사마겸을 돌아보았다."},{"s":"red_moon_cult:danbi","t":"대호법님, 맞혔으니까 제가 가는 거예요. 보셨죠? 대장님이 벌써 이 조사원 편을 드세요. 길에서도 그러실 거예요."},{"s":null,"t":"사마겸이 이를 갈며 단비 머리 위로 큰 손을 들었다가 그대로 내렸다."},{"s":"red_moon_cult:sama","t":"흥. 길에서 울고 돌아오면 그땐 내가 직접 장터 밖으로 던져 주마. 너도, 저 정청 개도.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:sama","t":"흥. 길에서 울고 돌아오면 그땐 내가 직접 장터 밖으로 던져 주마. 너도, 너를 데려간 사람도.","fac":"red_moon_cult","rank":[1,4],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"흥. 길에서 울고 돌아오면 그땐 내가 직접 장터 밖으로 던져 주마. …장로님, 저 아이를 부탁드립니다.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"그때 천막 안에서 월화가 단비를 불렀다. 단비가 들어가자 면사포 너머로 월화의 목소리가 새어 나왔다."},{"s":"red_moon_cult:wolhwa","t":"단비야. 그 사람 곁을 떠나지 마라. 무슨 일이 있어도. …그 사람 이름이 {이름}이라 했지?"},{"s":null,"t":"월화가 내 이름을 다시 묻고 있었다. 단비의 대답은 들리지 않았고, 나와 여운비는 서로 얼굴을 보았다."},{"s":null,"t":"장터를 나서는 길에 단비는 내 옆에 바짝 붙어 걸었고, 여운비는 일부러 두 걸음 앞서 걸었다."},{"s":null,"t":"나는 단비에게 교주가 왜 내 이름을 두 번 묻느냐고 물었다. 단비가 엿을 굴리며 어깨를 으쓱했다."},{"s":"red_moon_cult:danbi","t":"교주님은 원래 이름을 좋아하세요. 적월이 이름 덕에 사는 집이니까요. 저야 교주님이 시켜서 따라가는 거고요."},{"s":null,"t":"앞에서 여운비가 돌아보지도 않고 말을 던졌다."},{"s":"north_league:yeo","t":"이름 덕에 사는 게 아니라 남의 이름을 사서 사는 거겠지."},{"s":null,"t":"단비가 웃는 얼굴 그대로 받아쳤다."},{"s":"red_moon_cult:danbi","t":"그럼 북령은 제 집 이름도 묻어 두고 사는 집이잖아요? 고찰 사당에 깎아 낸 위패가 있다던데요. 장터엔 소문이 다 돌아요, 대장님."},{"s":null,"t":"여운비의 걸음이 뚝 멈췄다. 칼자루를 쥔 손이 하얗게 질렸다. 나는 두 사람 사이에 들어섰다."},{"s":null,"t":"나는 싸움은 장을 찾은 뒤에 해도 늦지 않다고 했다. 정리관이 저만치 앞서가는데 여기서 칼을 뽑으면 좋아할 사람은 그쪽뿐이라고 했다."},{"s":null,"t":"한참 뒤 여운비가 다시 걷기 시작했다. 단비가 엿 하나를 꺼내 여운비의 등에 대고 흔들었다."},{"s":"red_moon_cult:danbi","t":"대장님, 화해의 엿이에요. 단 거 좋아하세요?"},{"s":null,"t":"여운비는 대답하지 않았다. 단비가 엿을 내 손에 쥐여 주었다. 여운비가 앞에서 칼자루 술이 날리는 쪽을 보더니 짧게 말했다."},{"s":"north_league:yeo","t":"…바람이 동쪽으로 부오. 남은 거점 가운데 수향 구름나루가 가장 가깝소. 사흘 길이오. 엿은 조사원이 드시오."}],"reward":{"xp":2160,"gil":470,"items":{"heavenly_dew":1,"ward_talisman":4}}},{"quest_id":"mdq_4","step":1,"title":"물 위의 장부방","goal":"구름나루에 도착해 물 위의 장부방을 찾는다","need":{"at":["river_ferry"],"tasks":[{"t":"travel","r":["river_ferry"],"n":1}]},"lines":[{"s":null,"t":"구름나루에 닿았을 때는 해가 기울어 강물이 구릿빛으로 물들어 있었다. 선창 나무판이 발밑에서 삐걱삐걱 울었다."},{"s":null,"t":"선창 끝에서 늙은 뱃사공 하나가 노를 손질하다 고개를 들었다. 주름진 눈이 나를 보자 휘어졌다."},{"s":"river_alliance:nodeul","t":"허허, 그 얼굴. 용잠 수궁 물길을 묻던 조사원 아닌가. 연화 거북은 잘 있나? 그놈이 자네를 따라간 뒤로 늪 연꽃이 덜 핀다고 다들 섭섭해하더군."},{"s":null,"t":"나는 거북은 잘 있다고 했다. 노들 영감이 껄껄 웃으며 여운비와 단비를 번갈아 보았다."},{"s":"river_alliance:nodeul","t":"북령 칼에 적월 방울이라. 이 나루 오십 년에 둘이 한 배를 타는 건 처음 보네. 도방님은 장부방에 계시네. 오늘은 셈이 잘 안 맞는지 아까부터 주판 소리가 시끄럽더군."},{"s":null,"t":"선창 장부방 안은 주판 소리로 시끌시끌했다. 탁탁탁탁. 탁자 하나를 사이에 두고 두 여인이 마주 앉아 있었다."},{"s":null,"t":"웃는 얼굴로 찻잔을 든 쪽이 도방 진소랑이었다. 맞은편에서 장부를 넘기며 주판을 튕기는 쪽은 장부 행수 매향이었다."},{"s":"river_alliance:jin","t":"어머, 정청 조사원님. 용잠 수궁 문을 열고 연화 거북까지 데려가신 분이죠? 수향은 그런 손님을 잊지 않아요. 앉으세요. 마침 셈이 안 맞던 참이거든요.","fac_not":"river_alliance","spec":2,"grp":1},{"s":"river_alliance:jin","t":"우리 연맹 사람이 정청 일을 들고 오셨네요. 용잠 수궁 일 때도 그러셨죠. 앉으세요. 마침 셈이 안 맞던 참이에요.","fac":"river_alliance","rank":[1,4],"spec":0,"grp":1},{"s":"river_alliance:jin","t":"도방끼리 이렇게 마주 앉는 건 연맹 장부에도 없는 일인데요. 앉으세요. 셈이 안 맞던 참이에요.","fac":"river_alliance","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 한설의 편지를 탁자에 올렸다. 매향이 편지를 집어 읽고는 정청 명령서 옆에 나란히 놓았다."},{"s":"river_alliance:maehyang","t":"마침 잘 오셨어요. 그저께 정리관이 이 명령서를 몸소 들고 와서 차 한 잔 마시고 갔어요. 어제는 답신을 서두르라는 쪽지가 사람 편에 왔고요. 모서리를 반듯하게 접어서요."},{"s":null,"t":"매향이 주판을 내 쪽으로 돌려 보였다. 알이 몇 줄 올라가 있었다."},{"s":"river_alliance:maehyang","t":"반납하면 잃는 걸 셈해 봤어요. 장을 내주는 것 자체는 공짜예요. 그런데 장 얘기가 나오면 장이 왜 수향에 있는지 얘기가 나오고, 그러면 백 년 전 뱃길 장부가 나와요. 그 장부가 나오면 연맹 배 서른 척이 묶여요."},{"s":"river_alliance:maehyang","t":"반대로 안 내면, 정청이 수향 사람 이름을 안 지켜 준대요. 수향 뱃사람이 이천인데, 그 이천이 다 셈에 들어가요. 어느 쪽이든 셈이 안 맞아요."},{"s":null,"t":"진소랑이 찻잔을 내려놓았다. 웃는 얼굴이 그대로였지만 손가락이 탁자를 톡톡 두드렸다."},{"s":"river_alliance:jin","t":"그 정리관이 우리 뱃길 장부를 알고 하는 요구인지, 모르고 하는 요구인지 그게 궁금하네요. 알고 하는 거라면 이건 반납 명령이 아니라 흥정이에요."},{"s":null,"t":"나는 그럼 어떻게 하겠냐고 물었다. 진소랑이 매향의 주판을 끌어다 알을 탁 내렸다."},{"s":"river_alliance:jin","t":"매향, 답신은 이렇게 써. 「장이 어디 있는지 연맹도 모릅니다. 찾는 대로 아뢰겠습니다.」 동지 전까지 시간을 버는 거야."},{"s":"river_alliance:jin","t":"그리고 조사원님께는 사람을 하나 빌려 드릴게요. 물건은 안 빌려줘도 사람은 빌려줘요. 사람은 돌아오니까."},{"s":null,"t":"단비가 엿을 굴리며 고개를 갸웃했다. 사람을 고르는 진소랑을 재미있다는 듯이 보았다."},{"s":"red_moon_cult:danbi","t":"도방님, 누굴 빌려주시는데요? 물에 강한 사람이면 좋겠어요. 대장님은 물에 빠지면 칼 무게로 가라앉으실 테니까."},{"s":null,"t":"여운비가 단비를 흘겨보았다. 진소랑이 웃으며 창밖 강물을 가리켰다."},{"s":"river_alliance:jin","t":"지금 저 물 밑에 있는 애요. 과부댁 아들 문패를 건지러 들어갔어요. 그런데 오늘은 줄 잡아 줄 사람이 없어요. 노들 영감님 허리가 시원찮아서요."},{"s":"river_alliance:jin","t":"조사원님, 그 애 줄 좀 잡아 주시겠어요? 그 애랑 같이 다니실 거면, 물속에서 그 애가 당기는 줄부터 알아 두셔야 하거든요."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":2,"title":"물 밑의 줄","goal":"구름나루에서 3번 낚시하며 물 밑 청파의 줄을 잡아 준다","need":{"at":["river_ferry"],"tasks":[{"t":"fish","n":3,"r":["river_ferry"]}]},"lines":[{"s":null,"t":"선창 끝에 굵은 밧줄 하나가 강물 속으로 늘어져 있었다. 나는 노들 영감이 가르쳐 준 대로 밧줄을 허리에 한 번 감고 두 손으로 쥐었다."},{"s":"river_alliance:nodeul","t":"한 번 당기면 괜찮다는 거고, 두 번은 더 내려간다는 거고, 세 번이면 당장 끌어 올리라는 거네. 놓치면 안 되네."},{"s":null,"t":"줄이 한 번 툭 당겨졌다. 한참 뒤에 두 번 툭툭 당겨졌다. 줄이 스르르 더 풀려 나갔다."},{"s":null,"t":"강물은 물거품 하나 올라오지 않을 만큼 고요했다. 단비가 엿 씹던 입을 멈췄다."},{"s":null,"t":"갑자기 줄이 세 번 휙휙휙 당겨졌다. 손바닥에 줄이 확 감기며 몸이 앞으로 쏠렸다."},{"s":null,"t":"나는 선창 기둥에 발을 걸고 힘껏 당겼지만, 줄은 물 밑에서 무언가에 걸린 것처럼 꿈쩍도 하지 않았다."},{"s":null,"t":"여운비가 뒤에서 줄을 같이 잡았다. 단비도 엿을 입에 문 채 달려와 매달렸다."},{"s":"north_league:yeo","t":"하나, 둘에 당기시오! 하나, 둘!"},{"s":null,"t":"끄응, 줄이 쑥 풀려 올라왔다. 강물 한가운데가 부글부글 끓더니, 열예닐곱쯤 된 소년의 머리가 푸하 하고 솟아올랐다."},{"s":null,"t":"입술이 새파랗게 질린 소년이 한 손에 작은 나무 패를 높이 쳐들었다. 소년은 선창까지 헤엄쳐 와 기어오르더니 털썩 엎어졌다."},{"s":null,"t":"여운비가 망토를 벗어 소년의 어깨에 덮어 주었다. 소년의 이가 딱딱딱 부딪혔다."},{"s":null,"t":"단비가 소년 앞에 쪼그려 앉아 그 손의 나무 패를 들여다보았다."},{"s":"red_moon_cult:danbi","t":"괜찮아요? 줄이 왜 그렇게 무거웠어요? 그리고 그 나무패는 뭐예요?"},{"s":null,"t":"소년이 덜덜 떨며 나무 패를 가슴에 안았다. 반쯤 바랜 글자가 적힌 문패였다."},{"s":"q:sn_cheongpa","t":"수초에 발이 감겨서요. 줄을 당겨 주셔서 살았어요. 이건… 문패예요. 저기 아주머니 아들이 사흘 전에 배에서 떨어졌거든요. 몸은 못 찾았는데, 문패라도 건지면 이름은 남잖아요."},{"s":null,"t":"선창 저편에서 아이를 업은 아낙이 달려왔다. 아낙이 문패를 받아 들고 가슴에 꼭 끌어안았다."},{"s":"q:md_plate_wife","t":"고맙다, 청파야. 고맙다… 이제 우리 애 이름을 문 위에 다시 걸 수 있겠구나."},{"s":null,"t":"아낙이 흐느끼며 돌아갔다. 소년은 그 등을 한참 보다가 젖은 머리를 강아지처럼 털었다. 물방울이 사방으로 튀자 여운비가 한 걸음 물러섰다."},{"s":"q:sn_cheongpa","t":"줄을 잡아 주신 분이 정청 조사원 {이름} 님이시죠? 도방님이 오늘 오신다고 했어요! 와, 누님 방울 진짜 예쁘다. 저쪽 누님은 칼이 엄청 크네요. 그거 무거워요? 한번 들어 봐도 돼요?","fac_not":"river_alliance","spec":2,"grp":1},{"s":"q:sn_cheongpa","t":"어, {이름} 님은 우리 나루 패를 차셨네요! 정청 조사원이 온다더니 우리 연맹 분이셨구나. 와, 누님 방울 진짜 예쁘다. 저쪽 누님은 칼이 엄청 크네요!","fac":"river_alliance","rank":[1,2],"spec":0,"grp":1},{"s":"q:sn_cheongpa","t":"어, {등급}님이시다! 장부방에서 {등급}님 얘기를 맨날 들었거든요. 줄을 {등급}님이 잡아 주셨구나. 와, 누님 방울 진짜 예쁘다. 저쪽 누님은 칼이 엄청 크네요!","fac":"river_alliance","rank":[3,4],"spec":0,"grp":1},{"s":"q:sn_cheongpa","t":"도, 도방님? 연맹 도방님이 제 줄을 잡아 주셨다고요? 와… 저 오늘 일 년 치 운을 다 썼어요.","fac":"river_alliance","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"여운비가 대답 대신 칼집을 소년에게서 멀찍이 돌렸다. 단비가 웃음을 참지 못하고 엿 하나를 소년 입에 쏙 넣어 주었다."},{"s":null,"t":"소년이 볼이 불룩해진 채로 가슴을 폈다. 엿 때문에 말이 조금 뭉개졌다."},{"s":"q:sn_cheongpa","t":"청파예요! 수향 잠수꾼 청파. 막내예요. 이 나루에서 제일 오래 숨을 참아요."},{"s":null,"t":"장부방 문이 열리고 나온 진소랑이 청파의 젖은 머리를 수건으로 북북 문질렀다."},{"s":"river_alliance:jin","t":"청파야, 너 이분들 따라가거라. 정청이 그 장으로 뭘 하려는지 다 보고 와서 나한테 말해 줘야 해."},{"s":null,"t":"청파가 입을 딱 벌렸다가 이내 주먹을 불끈 쥐었다."},{"s":"q:sn_cheongpa","t":"진짜요? 저 수향 밖으로 이렇게 멀리 나가 보는 거 처음이에요!"},{"s":null,"t":"진소랑이 나를 따로 선창 끝으로 불러내더니 강물을 보며 목소리를 낮췄다."},{"s":"river_alliance:jin","t":"저 애를 고른 까닭이요? 저 애는 거짓말을 못 해요. 정청이 뭘 하는지 본 그대로 말할 거예요. 우리 연맹 사람들은 다 셈을 해서 말하거든요. 저 하나만 빼고요."},{"s":"river_alliance:jin","t":"그리고 하나만요. 저 애 증조할아버지 배 얘기는, 저 애가 먼저 꺼내기 전에는 하지 말아 주세요. 수향이 오래 묻어 둔 얘기라서요."},{"s":null,"t":"선창으로 돌아오자 청파가 덜 마른 손으로 낚싯대를 쥐여 주었다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 오늘 저녁은 제가 구울게요! 줄을 잡아 주신 값이에요. 대신 생선은 같이 낚아요. 누님들 몫까지 넷이 먹으려면 꽤 많이 낚아야 하거든요."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":3,"title":"뱃전의 생선구이","goal":"구름나루에서 3번 낚시하고 생선구이 4마리를 구워 청파에게 넘긴다","need":{"at":["river_ferry"],"tasks":[{"t":"fish","n":3,"r":["river_ferry"]},{"t":"craft","items":["grilled_fish"],"n":4}],"give":{"grilled_fish":4}},"lines":[{"s":null,"t":"해가 지자 노들 영감이 우리를 배에 태웠다. 잔불촌으로 가려면 강을 따라 남쪽으로 내려가는 게 빨랐다."},{"s":null,"t":"뱃전에 화로를 걸고 청파가 생선을 구웠다. 지글지글, 기름이 숯에 떨어질 때마다 치익 연기가 올랐다."},{"s":null,"t":"청파가 제일 잘 익은 생선을 내 앞에 놓았다. 다음 것은 여운비 앞, 그다음은 단비 앞이었다. 노들 영감 몫까지 다 놓고 나서야 제 몫을 집었다."},{"s":"q:sn_cheongpa","t":"드세요, 드세요! 수향 생선은 껍질이 맛있어요. 껍질부터 드셔야 돼요."},{"s":null,"t":"여운비가 껍질을 한 입 베어 물고, 아무 말 없이 한 입 더 먹었다. 청파가 눈을 반짝이며 여운비를 보았다."},{"s":"q:sn_cheongpa","t":"어때요, 누님? 맛있죠?"},{"s":null,"t":"여운비가 생선 가시를 발라내며 짧게 대답했다."},{"s":"north_league:yeo","t":"…나쁘지 않소."},{"s":null,"t":"단비가 손뼉을 짝 쳤다. 깔깔 웃으며 청파의 어깨를 쳤다."},{"s":"red_moon_cult:danbi","t":"청파 씨, 방금 대장님 최고 칭찬을 들은 거예요! 썰매꾼은 오 년 걸렸대요."},{"s":null,"t":"청파가 무슨 소린지 모르는 얼굴로 웃었다. 여운비는 단비를 노려보다 생선을 마저 먹었다."},{"s":null,"t":"배가 강굽이를 돌았다. 청파가 생선 뼈를 강물에 던지며 우리를 둘러보았다."},{"s":"q:sn_cheongpa","t":"근데요, 다들 왜 같이 다녀요? 북령이랑 적월은 사이 엄청 나쁘다던데. 노들 영감님이 그랬어요."},{"s":null,"t":"단비가 먼저 엿을 꺼내 들었다."},{"s":"red_moon_cult:danbi","t":"저는 교주님 심부름이요. 교주님이 이 사람 곁을 떠나지 말래요. 무슨 일이 있어도요."},{"s":null,"t":"단비가 엿을 입에 넣으며 웃었지만, 그 말을 할 때만은 눈이 웃지 않았다."},{"s":null,"t":"여운비가 칼자루의 붉은 술을 손가락에 감았다."},{"s":"north_league:yeo","t":"맹주님 명이오. …그리고 이 사람 신 끈은 아직도 내가 매 줘야 하오. 혼자 매면 하루를 못 가서 풀리오."},{"s":null,"t":"청파가 고개를 끄덕이다가 나를 보았다. 나는 품속 반쪽 종이를 손바닥으로 눌러 보이며, 이 종이가 가자는 데로 가는 중이라고 했다."},{"s":"q:sn_cheongpa","t":"그럼 저는 도방님이 보고 오래서요! …근데 이렇게 한 배에 둘러앉아서 생선 뜯고 있으니까, 꼭 원래부터 같이 다니던 사람들 같아요."},{"s":null,"t":"여운비와 단비가 동시에 청파를 보았다. 둘 다 무어라 하려다가 입을 다물었다. 단비가 생선 꼬리를 뜯어 청파 그릇에 얹고, 남은 반쪽은 슬그머니 여운비 그릇에 놓았다. 여운비는 그것을 밀어내지 않았다."},{"s":null,"t":"노들 영감이 노를 저으며 허허 웃었다."},{"s":"river_alliance:nodeul","t":"오십 년 노를 저었어도 북령 그릇에 적월 생선이 올라가는 건 처음 보네. 나루에 돌아가면 소문 하나는 실컷 내겠구먼."},{"s":null,"t":"밤이 깊자 청파가 뱃전에 턱을 괴고 검은 강물을 오래 보았다. 아까까지 떠들던 아이가 아무 말도 하지 않았다."},{"s":null,"t":"나는 청파 곁에 앉아 무엇을 보냐고 물었다. 청파가 물에서 눈을 떼지 않았다."},{"s":"q:sn_cheongpa","t":"그냥요. 물에 들어가면 조용해서 좋아요. 물속에선 다들 이름이 하나씩만 들려요. 위에서처럼 시끄럽지 않고요."},{"s":null,"t":"새벽녘 강 건너로 잔불촌의 화로 불빛이 보이기 시작했다. 뱃머리에 선 여운비가 그 위로 피어오르는 연기를 보고 칼자루 술을 쥐었다."},{"s":"north_league:yeo","t":"남명은 정청 사람을 반기지 않는 곳이오. 북령이나 적월은 더하고. 들어가기 전에 어귀부터 살펴봅시다."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":4,"title":"닫힌 화로","goal":"잔불촌에 도착하고, 불씨 고개를 2번 탐색해 마을 어귀를 살핀다","need":{"at":["ember_village"],"tasks":[{"t":"travel","r":["ember_village"],"n":1},{"t":"search","r":["ember_pass"],"n":2}]},"lines":[{"s":null,"t":"잔불촌 어귀부터 공기에 쇠 냄새와 숯 냄새가 섞여 들었다. 마을 한가운데 커다란 화로가 사방을 붉게 비추었다."},{"s":null,"t":"마을 어귀를 살피던 청파가 걸음을 멈췄다. 화로 뒤로 흐르는 도랑가를 손가락으로 가리켰다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 저거 보세요. 발자국이 시커매요. 도랑에서 나와서 도랑으로 들어갔어요."},{"s":null,"t":"젖은 먹 발자국이었다. 고찰 우물가에서 본 것과 똑같았다. 여운비가 쪼그려 앉아 발자국 너비를 손가락으로 재었다."},{"s":"north_league:yeo","t":"같은 놈들이오. 우물이든 도랑이든 물만 있으면 다니는 모양이오."},{"s":null,"t":"단비가 발자국을 내려다보며 처음으로 엿을 꺼내지 않았다."},{"s":"red_moon_cult:danbi","t":"물로 다니는 사람이라니… 적월 축문에도 그런 건 없어요."},{"s":null,"t":"마을 입구 돌담에 그을린 가죽옷을 입은 여자 하나가 팔짱을 끼고 기대 서 있었다. 남명 정찰대장 갈매였다. 재의 바다 일 때 재의 해안을 함께 뒤지다, 난파선 선창에서 미끄러진 내 뒷덜미를 낚아채 끌어올려 준 사람이었다."},{"s":null,"t":"갈매가 우리를 하나하나 훑어보았다. 북령 망토를 보고는 입꼬리가 내려갔다. 적월 무복을 보고는 눈썹을 찌푸렸다. 내 얼굴에서 잠깐 멈췄던 눈이 옷깃의 정청 표식으로 내려가더니, 갈매는 아예 고개를 돌려 버렸다."},{"s":null,"t":"내가 이름을 부르며 인사를 건넸지만 갈매는 대꾸하지 않았다. 한설의 편지를 내밀어도 받지 않았다. 나를 모를 리 없는 사람이 일부러 모르는 척하고 있었다. 갈매는 대신 청파 쪽으로 턱짓을 했다.","fac_not":"southern_remnant","spec":2,"grp":1},{"s":null,"t":"재의 해안 일 뒤로도 세력 일로 여러 번 얼굴을 본 사이였다. 내 손목의 불씨 끈과 옷깃의 정청 표식을 번갈아 본 갈매의 눈이 잠깐 커졌다가 도로 가늘어졌다. 내가 인사를 건넸지만 갈매는 못 들은 척하고 청파 쪽으로 턱짓을 했다.","fac":"southern_remnant","spec":1,"grp":1},{"s":"southern_remnant:galmae","t":"야, 꼬맹이. 너 수향이지? 정청 끄나풀 따라다니면서 뭘 얻어먹냐?","fac_not":"southern_remnant","spec":2,"grp":1},{"s":"southern_remnant:galmae","t":"야, 꼬맹이. 너 수향이지? 남의 땅까지 따라와서 뭘 얻어먹냐?","fac":"southern_remnant","spec":1,"grp":1},{"s":null,"t":"청파가 눈을 끔뻑이며 손에 쥔 엿 조각을 내려다보았다. 무엇이 잘못됐는지 모르겠다는 얼굴이었다."},{"s":"q:sn_cheongpa","t":"어… 엿이요?"},{"s":null,"t":"단비가 웃음을 터뜨렸지만 갈매는 웃지 않았다. 갈매가 돌담에서 등을 떼고 마을 안쪽으로 걸어갔다. 따라오라는 말도, 따라오지 말라는 말도 없었다."},{"s":null,"t":"화로 앞에는 한 팔이 없는 노장 장무현이 앉아 남은 팔로 부지깽이를 쥐고 있었다. 곁에서 무녀 소이가 낮게 노래를 흥얼거렸다."},{"s":"southern_remnant:jang","t":"갈매야, 정청 사람이 이 마을에 온 건 이틀 사이에 둘째구나. …자네는 구등대 마지막 등대지기가 불씨를 노리개에 담아 건넨 그 조사원이지. 재의 바다 등대를 다 돌아본 사람.","fac_not":"southern_remnant","spec":2,"grp":2},{"s":"southern_remnant:jang","t":"갈매야, 저 사람은 불씨 끈을 받아 간 사람이다. 재의 바다 등대를 다 돌아본 사람이기도 하고. 그런데 오늘은 정청 일로 왔구나.","fac":"southern_remnant","rank":[1,2],"spec":0,"grp":2},{"s":"southern_remnant:jang","t":"갈매야, {등급}께 인사해라. 이 마을 화로에 장작을 대 준 사람이고, 구등대 마지막 등대지기의 불씨를 받아 간 사람이다. 그런 사람이 오늘은 정청 일로 왔구나.","fac":"southern_remnant","rank":[3,4],"spec":0,"grp":2},{"s":"southern_remnant:jang","t":"갈매야, 수호장께서 오셨다. 수호장께서 정청 표식을 다시 다셨다면, 그만한 일이 있다는 뜻이겠지.","fac":"southern_remnant","rank":[5,5],"spec":0,"grp":2},{"s":null,"t":"갈매가 화로 건너편에 털썩 주저앉으며 팔짱을 다시 꼈다."},{"s":"southern_remnant:galmae","t":"정청 놈이 오면 문을 닫으라고 한 게 할배잖아. 어제 그 정리관인가 하는 놈은 문밖에 세워 두고 돌려보냈으면서.","fac_not":"southern_remnant","spec":2,"grp":3},{"s":"southern_remnant:galmae","t":"남명 끈을 찼으면 남명 사람으로 오든가. 정청 표식은 왜 또 달고 와? 어제 그 정리관이란 놈은 문밖에 세워 두고 돌려보냈으면서, 정청 표식 단 건 똑같은데 이건 왜 들여.","fac":"southern_remnant","rank":[1,4],"spec":0,"grp":3},{"s":"southern_remnant:galmae","t":"수호장이 정청 표식을 달고 오면 우린 어느 쪽으로 대해야 돼? 어제 그 정리관이란 놈은 문밖에 세워 두고 돌려보냈으면서.","fac":"southern_remnant","rank":[5,5],"spec":0,"grp":3},{"s":null,"t":"장무현이 부지깽이 끝으로 갈매 쪽 땅을 톡 두드렸다."},{"s":"southern_remnant:jang","t":"갈매야. 재의 해안을 같이 뒤진 사람을 모르는 척하는 건 남명 예법이 아니다."},{"s":null,"t":"갈매가 팔짱을 낀 채 고개를 홱 돌렸다. 나를 쳐다보지도 않고 쏘아붙였다."},{"s":"southern_remnant:galmae","t":"알아. 아는데, 정청 표식 달고 오면 모르는 사람이야. 그때 그 불, 이번엔 꺼뜨리러 왔는지 켜러 왔는지 누가 알아."},{"s":null,"t":"갈매가 그 말을 하며 내 허리춤을 흘끗 보았다. 구등대 마지막 등대지기에게 받은 등롱 노리개가 거기 매달려 있었다. 불씨는 아직 꺼지지 않았다."},{"s":null,"t":"장무현이 부지깽이로 화로 속 숯 하나를 뒤집었다. 숯 밑에서 하얗게 빛나는 불씨 하나가 드러났다."},{"s":null,"t":"다른 불과 빛깔이 달랐다. 흔들리지 않았고, 연기도 나지 않았다. 내 품속 반쪽 종이 위의 흰 불꽃과 같은 빛이었다."},{"s":null,"t":"품속에서 불꽃이 저절로 흔들렸다. 장무현의 눈길이 내 품으로 향했다. 장무현이 부지깽이로 숯을 끌어다 그 불씨를 도로 덮었다."},{"s":null,"t":"나는 한설의 편지를 장무현 앞에 내밀었지만, 장무현은 받지 않았다."},{"s":"southern_remnant:jang","t":"그것도 정청 종이고, 어제 온 것도 정청 종이야. 종이 빛깔이 다르다고 먹이 다른 건 아니지. 남명은 백 년 전 정청 서식에 서명하지 않은 나라다. 반납할 것도, 들려 보낼 것도 없네."},{"s":null,"t":"소이가 노래를 멈추고 장무현을 흘끗 보았지만, 장무현은 그 눈길을 모른 척했다."},{"s":null,"t":"그때 마을 바깥에서 뿔나팔 소리가 길게 울렸다. 부우우웅. 화로 둘레의 남명 사람들이 벌떡 일어섰다."},{"s":null,"t":"숨을 헐떡이며 뛰어온 파수꾼이 장무현 앞에 무릎을 꿇었다."},{"s":"q:md_south_watch","t":"장군님! 불씨 고개로 먹 낀 짐승 떼가 넘어옵니다! 스물은 넘습니다!"},{"s":null,"t":"갈매가 칼을 뽑아 들고 일어섰다. 장무현이 부지깽이를 내려놓고 나를 보았다."},{"s":"southern_remnant:jang","t":"돌아갈 거면 불씨 고개 길로 돌아가게. 마침 갈매가 국경 정찰을 나가니. 정청 사람이 남명 땅에서 등을 보이는지 안 보이는지, 나도 한번 봐야겠어."},{"s":null,"t":"갈매가 기가 막힌다는 듯 장무현을 돌아보았다."},{"s":"southern_remnant:galmae","t":"할배! 저 정청 끄나풀을 데려가라고? 짐이야!","fac_not":"southern_remnant","spec":2,"grp":4},{"s":"southern_remnant:galmae","t":"할배! 정청 표식 달고 온 걸 정찰에 데려가라고? 짐이야!","fac":"southern_remnant","rank":[1,4],"spec":0,"grp":4},{"s":"southern_remnant:galmae","t":"할배! 수호장을 정찰에 끌고 가라고? 다치기라도 하면 다 내 탓이잖아!","fac":"southern_remnant","rank":[5,5],"spec":0,"grp":4},{"s":null,"t":"여운비가 칼을 뽑으며 갈매 옆에 섰다. 단비가 방울을 쥐었고, 청파가 허둥지둥 신을 고쳐 신었다."},{"s":"north_league:yeo","t":"짐인지 아닌지는 길에서 보면 되오. 북령에서도 그렇게 하오."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":5,"title":"등 뒤의 칼","goal":"불씨 고개에 도착해 갈매와 국경을 정찰하며 종소리 먹은 늑대를 5번 쓰러뜨린다","need":{"at":["ember_pass"],"tasks":[{"t":"travel","r":["ember_pass"],"n":1},{"t":"win","n":5,"m":["dd_martial_4"],"r":["ember_pass"]}]},"lines":[{"s":null,"t":"불씨 고개는 숯처럼 검은 바위투성이였다. 달빛 아래 먹 낀 짐승들의 눈이 번들번들 빛났다."},{"s":null,"t":"갈매가 맨 앞에서 뛰어들었다. 휙, 칼날이 바람을 갈랐다. 한 마리가 깨갱 소리를 내며 굴러떨어졌다."},{"s":null,"t":"여운비가 갈매의 왼쪽을 막았다. 단비의 방울이 짤랑짤랑 울릴 때마다 짐승들이 움찔 물러섰다."},{"s":null,"t":"짐승들은 털빛이 하얗게 바랜 늑대였는데, 칼날이 바람을 가르는 소리를 삼켰다가 그대로 되울려 냈다. 고개 아래 마른 우물 둘레에는 설피골과 같은 젖은 먹 발자국이 어지러웠다."},{"s":null,"t":"청파는 바위 뒤에서 돌을 던졌다. 퍽, 퍽. 생각보다 잘 맞았다."},{"s":"q:sn_cheongpa","t":"누님! 오른쪽이요! 오른쪽에 세 마리 더 와요!"},{"s":null,"t":"갈매가 오른쪽으로 몸을 틀었다. 그 순간 갈매의 등 뒤 바위에서 커다란 놈 하나가 소리 없이 솟구쳤다."},{"s":null,"t":"갈매는 보지 못했다. 나는 몸을 던졌다. 쾅! 놈의 발톱이 내 {직업:호위=방패를/월궁=활대를/퇴마=방울 자루를/의무=부채를/봉인=금강령을/암영=단도를/조련=활대를/*=무기를} 긁으며 불똥을 튀겼다."},{"s":null,"t":"팔이 저릿했다. 나는 이를 악물고 버텼다. 놈의 이빨이 내 얼굴 앞에서 딱딱 부딪혔다."},{"s":null,"t":"갈매가 돌아서다 눈을 크게 떴다. 갈매의 칼이 내 어깨 위로 쑥 지나가 놈의 목에 박혔다."},{"s":null,"t":"놈이 털썩 쓰러졌다. 갈매가 숨을 몰아쉬며 나를 내려다보았다. 칼끝이 바들바들 떨렸다."},{"s":"southern_remnant:galmae","t":"…{이름}."},{"s":null,"t":"갈매가 내 이름을 불렀다. 처음이었다. 갈매는 제가 무슨 말을 했는지 깨달은 얼굴로 입을 꾹 다물었다."},{"s":null,"t":"단비가 달려와 내 팔을 붙잡고 살폈다. 웃음기 하나 없는 얼굴이었다."},{"s":"red_moon_cult:danbi","t":"괜찮아요? 피 나요? 바보같이 왜 맨몸으로 막아요!"},{"s":null,"t":"나는 괜찮다고 했다. 여운비가 짐승의 시체를 발로 밀어내며 갈매를 보았다."},{"s":"north_league:yeo","t":"남명 정찰대장이 등을 비웠소. 오늘은 이 사람이 막았으니 다행이오."},{"s":null,"t":"갈매는 여운비를 노려보기만 할 뿐 반박하지 않고, 칼을 털어 칼집에 넣었다."},{"s":null,"t":"짐승 떼가 다 물러간 뒤 우리는 고개 바위틈에서 불을 피웠다. 청파가 화로에서 얻어 온 숯을 불었다. 단비가 내 팔에 붕대를 감았다."},{"s":null,"t":"갈매는 불에서 조금 떨어져 앉아 있다가, 한참 뒤 제 물주머니를 내 쪽으로 툭 던졌다."},{"s":"southern_remnant:galmae","t":"마셔. 그거 마시고 내일 할배한테 가서 남명 땅에서 등 안 보였다고 해. 그 말만 하고 가."},{"s":null,"t":"나는 물을 마시고 고맙다고 했다. 갈매가 혀를 찼다."},{"s":"southern_remnant:galmae","t":"고맙긴 뭐가 고마워. 재의 해안에서 네 뒷덜미 잡아 준 걸로 셈이 끝난 줄 알았더니, 도로 내가 빚졌잖아. 남명은 빚지고는 못 살아."},{"s":null,"t":"청파가 불 너머에서 갈매를 빤히 보았다. 갈매가 왜 보냐는 듯 눈을 부릅떴다."},{"s":"q:sn_cheongpa","t":"누님, 아까 {이름} 님 이름 부를 때 목소리 엄청 작았어요. 다시 한번 크게 불러 봐요."},{"s":null,"t":"갈매가 돌멩이를 집어 청파에게 던지는 시늉을 했다. 청파가 꺅 소리를 지르며 단비 뒤로 숨었다. 단비가 깔깔 웃었다. 여운비마저 고개를 돌려 입꼬리를 감추었다."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":6,"title":"마지막 아이","goal":"불씨 고개에서 야영으로 쉬고 잔불촌에 도착한다","need":{"at":["ember_village"],"tasks":[{"t":"rest","r":["ember_pass"],"n":1},{"t":"travel","r":["ember_village"],"n":1}]},"lines":[{"s":null,"t":"새벽에 잔불촌으로 돌아왔다. 장무현은 밤새 화로 앞에 앉아 있었던 듯 어제와 같은 자리에 있었다."},{"s":null,"t":"갈매가 화로 앞에 서서 팔짱을 꼈다. 장무현을 보지 않고 말했다."},{"s":"southern_remnant:galmae","t":"할배. 저 정청 끄나풀, 등 안 보였어. 오히려 내 등을 막았어. 그거면 됐지?","fac_not":"southern_remnant","spec":2,"grp":1},{"s":"southern_remnant:galmae","t":"할배. 정청 표식은 달았어도 등은 안 보였어. 오히려 내 등을 막았어. 그거면 됐지?","fac":"southern_remnant","spec":1,"grp":1},{"s":null,"t":"장무현이 부지깽이를 내려놓고 나를 한참 보았다. 주름진 얼굴에 불빛이 그늘을 드리웠다."},{"s":"southern_remnant:jang","t":"마음을 바꾸겠네. 정청 사람이라서가 아니라, 어젯밤 우리 아이 등을 막은 사람이라서."},{"s":"southern_remnant:jang","t":"남명은 장을 내주지도, 들려 보내지도 않네. 대신 자네가 가서 정청이 무엇을 태우려는지 보게. 그리고 그걸 증거로 들고 오게. 그때 남명이 할 일을 정하겠네."},{"s":null,"t":"나는 왜 정청이 무엇을 태우려 한다고 생각하냐고 물었다. 장무현이 화로 속 숯을 오래 내려다보았다."},{"s":"southern_remnant:jang","t":"정청은 늘 무언가를 태웠네. 백 년 전 정청 서식에 남명만 서명하지 않았지. 그 뒤로 칠십 년 동안, 해마다 정청 정리 명부 맨 앞줄에 남명 백성 이름이 올랐네. 해마다, 맨 앞에."},{"s":null,"t":"화로 둘레가 조용해졌다. 소이가 노래를 멈췄고, 단비의 엿 씹는 소리도 멎었다."},{"s":"southern_remnant:jang","t":"남명이 망한 건 칼에 져서가 아니야. 이름을 거둬 가서였지. 나는 그걸 칠십 년 동안 이 화로 앞에서 세었네."},{"s":null,"t":"장무현이 갈매를 보았다. 무거운 목소리였다."},{"s":"southern_remnant:jang","t":"갈매야, 이 사람을 따라가거라. 남명 눈으로 보고 오너라."},{"s":null,"t":"갈매는 고개도 들지 않고 받아쳤다. 생각해 볼 것도 없다는 투였다."},{"s":"southern_remnant:galmae","t":"싫어."},{"s":null,"t":"장무현이 화로 속을 내려다보았다. 노인의 목소리가 숯불처럼 낮게 가라앉았다."},{"s":"southern_remnant:jang","t":"마지막 아이가 마지막까지 고집을 부리는구나."},{"s":null,"t":"갈매의 얼굴이 순식간에 붉어졌다. 화로 불빛 때문이 아니었다. 주먹 쥔 손등에 핏줄이 불거졌다."},{"s":"southern_remnant:galmae","t":"그 말 하지 말라고 했지! 하지 말라고 했잖아!"},{"s":null,"t":"갈매가 화로 옆 장작더미를 걷어찼다. 와르르, 장작이 쏟아졌다. 청파가 깜짝 놀라 펄쩍 뛰었다."},{"s":null,"t":"장무현은 아무 말 없이 다시 부지깽이를 들어 숯을 골랐다. 갈매가 그 옆얼굴을 노려보다 휙 돌아서서 마을 밖으로 뛰어나갔다."},{"s":null,"t":"아무도 움직이지 못했다. 소이가 흩어진 장작을 하나씩 주워 쌓으며 혼잣말처럼 흘렸다."},{"s":"southern_remnant:soi","t":"그 말씀은 장군님만은 쓰시면 아니 되옵는데… 저 아이가 그 말을 들으면 누구를 떠올리는지, 장군님이 제일 잘 아시면서."},{"s":null,"t":"장무현의 부지깽이가 멈췄지만, 장무현은 끝내 대답하지 않았다."},{"s":null,"t":"나는 갈매를 찾으러 마을 어귀로 나갔다. 단비가 따라나서려 하자 여운비가 단비의 소매를 붙잡았다."},{"s":"north_league:yeo","t":"둘이 가면 저 사람은 더 도망치오. 한 사람만 가시오."},{"s":null,"t":"갈매는 어귀 돌담 위에 앉아 불씨 고개 쪽을 보고 있었다. 내가 돌담 아래에 서자 갈매가 고개를 돌리지 않고 말했다."},{"s":"southern_remnant:galmae","t":"묻지 마. 왜 화났는지 묻지 마. 나도 몰라. 그냥 그 말이 싫어."},{"s":null,"t":"나는 묻지 않고 돌담 아래에 앉아 같이 불씨 고개를 보았다. 해가 고개 위로 다 올라올 때까지 둘 다 아무 말도 하지 않았다."},{"s":null,"t":"갈매가 돌담에서 훌쩍 뛰어내렸다. 칼집을 고쳐 차며 퉁명스럽게 말했다."},{"s":"southern_remnant:galmae","t":"착각하지 마. 길이 겹치는 것뿐이야. 할배가 증거를 들고 오래서, 가는 데가 너희랑 같을 뿐이라고. 정청 놈들이 남명 이름을 또 태우려는지 내 눈으로 봐야겠어."},{"s":"southern_remnant:galmae","t":"다음은 어디야?"},{"s":null,"t":"나는 천명원의 무극 관성대라고 했다. 갈매가 코를 찡그리며 바위산 쪽을 올려다보았다."},{"s":"southern_remnant:galmae","t":"천명원? 그놈들은 별 보는 척하면서 맨날 잠만 잔다던데. …관성대 가는 길은 바위산이라 나무 한 그루 없어. 땔감은 여기서 챙겨 가."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":7,"title":"석판의 세 글자","goal":"불씨 고개에서 4번 채집해 땔감을 챙기고 무극 관성대에 도착한다","need":{"at":["star_observatory"],"tasks":[{"t":"gather","n":4,"r":["ember_pass"]},{"t":"travel","r":["star_observatory"],"n":1}]},"lines":[{"s":null,"t":"무극 관성대는 하늘과 가장 가까운 곳이었다. 계단을 다 오르자 내쉬는 숨이 하얗게 흩어졌다. 별이 손에 닿을 듯 가까웠다."},{"s":null,"t":"우리 다섯이 그 별을 올려다보는 동안 아무도 입을 열지 않았다. 늘 떠들던 청파마저 입을 벌린 채 조용했다."},{"s":null,"t":"관성대 지붕 위 혼천의 옆에 누군가 누워 있었다. 남빛 관복을 입은 그 사람은 두루마리 여럿을 이불처럼 덮고 가늘게 코를 골았다."},{"s":null,"t":"우리 발소리에 그 사람이 꿈틀했다. 두루마리 하나가 데구루루 굴러떨어지며 별 기록이 바닥에 펼쳐졌다."},{"s":null,"t":"눈을 반쯤 뜬 그 사람이 우리를 하나씩 훑어보았다. 북령, 적월, 수향, 남명, 그리고 정청까지 본 뒤에 느릿하게 하품을 했다."},{"s":"q:r71_seoharam","t":"아… 오셨어요. 별이 너무 맑아서요… 기다리다가 별을 좀 보느라고요. 천명원 관측관 서하람이에요.","fac_not":"mandate_court","spec":2,"grp":1},{"s":"q:r71_seoharam","t":"아… 관측생 패네요. 우리 관성대 사람이 정청 일을 들고 올 줄은 몰랐어요… 기다리다가 별을 좀 보느라고요.","fac":"mandate_court","rank":[1,2],"spec":0,"grp":1},{"s":"q:r71_seoharam","t":"아… {등급}님이셨구나. 제가 쓴 별 기록을 검토해 주신 분이죠? 기다리다가 별이 너무 맑아서 그만…","fac":"mandate_court","rank":[3,4],"spec":0,"grp":1},{"s":"q:r71_seoharam","t":"아, 영대 감정께서… 몸소 계단을 오르셨네요. 누워 있어서 죄송해요… 별이 너무 맑아서요.","fac":"mandate_court","rank":[5,5],"spec":0,"grp":1},{"s":"q:r71_seoharam","t":"미리 말씀드리는데요, 저는 예언은 안 해요. 관측만 해요."},{"s":null,"t":"갈매가 코웃음을 쳤다. 정청 사람을 대할 때와는 또 다른, 대놓고 비웃는 코웃음이었다."},{"s":"southern_remnant:galmae","t":"천명원 놈들은 다 저렇게 잠꾸러기냐?"},{"s":null,"t":"서하람이 두루마리를 끌어안은 채 눈을 한 번 감았다 떴다. 화를 내기에는 너무 졸린 얼굴이었다."},{"s":"q:r71_seoharam","t":"아… 저희는 낮에 자고 밤에 별을 보는 거예요… 그쪽이 낮에 깨어 있는 거고요."},{"s":null,"t":"갈매가 무어라 받아치려다 입을 다물었다. 청파가 킥킥 웃다가 갈매의 눈총을 받고 입을 막았다."},{"s":null,"t":"관성대 안쪽 방에서 수석 관측관 서이연이 우리를 맞았다. 서하람만큼이나 졸린 얼굴이었지만 눈빛만은 또렷했다."},{"s":"mandate_court:seo","t":"정청 조사원이시군요. 오랜만에 뵈어요.","fac_not":"mandate_court","spec":2,"grp":2},{"s":"mandate_court:seo","t":"{등급}님, 수련장 말고 이 방에서 뵙는 건 오랜만이네요. 오늘은 정청 일로 오셨다고요.","fac":"mandate_court","spec":1,"grp":2},{"s":"mandate_court:seo","t":"구중 봉연 일 때 태사령께서 조사원님 앞에서 십 년 만에 처음 입을 여셨죠. 「붉은 인장은 제자리에 있을 때 빛난다. 손에 쥔 자에게서는 빛나지 않는다.」 …그 뒤로 다시 입을 닫으셨어요."},{"s":null,"t":"안쪽 탁자 앞에 태사령 하후정이 앉아 있었다. 노인 앞에는 석판 하나가 놓여 있었는데, 이미 분필 글씨가 적혀 있었다.","fac_not":"mandate_court","spec":2,"grp":3},{"s":null,"t":"안쪽 탁자 앞에 태사령 하후정이 앉아 있었다. 노인은 내 손목의 천명 패를 한참 보더니 고개를 한 번 끄덕였다. 노인 앞의 석판에는 이미 분필 글씨가 적혀 있었다.","fac":"mandate_court","spec":1,"grp":3},{"s":null,"t":"석판에는 「정리관 다녀감」이라고 적혀 있었는데, 글씨 끝이 거칠게 긁혀 있었다."},{"s":"mandate_court:seo","t":"어제 저녁에 왔어요. 정청 명령서를 직접 들고요. 태사령께서는 한마디도 안 하셨고, 그 사람은 혼자 차를 마시고 갔어요. 그런데 가면서 서하람 이름을 묻더라고요. 저 애가 어디서 났는지."},{"s":null,"t":"서이연의 손이 탁자 모서리를 꽉 잡았는데, 서하람은 문가에 기대 꾸벅꾸벅 졸고 있었다."},{"s":"mandate_court:seo","t":"우리 장은 지워진 땅의 첫 관상대에 있다고만 전해져요. 그게 어딘지 아무도 몰라요. 그러니 반납할 수도 없고, 들려 보낼 수도 없죠."},{"s":null,"t":"하후정이 분필을 들었다. 석판의 글씨를 소매로 쓱 지우고 천천히 「보내라」 세 글자를 적었다."},{"s":null,"t":"서이연의 얼굴이 하얘졌다. 서이연이 석판을 확 뒤집어 엎었다. 탁! 소리에 졸던 서하람이 눈을 번쩍 떴다."},{"s":"mandate_court:seo","t":"안 돼요, 태사령. 다른 애를 보내세요. 저 애는 안 돼요. 첫 관상대가 어딘지도 모르는 데를 저 애가 왜 가요!"},{"s":null,"t":"하후정은 대답하지 않고, 엎어진 석판 위에 손을 얹고 서이연을 볼 뿐이었다."},{"s":null,"t":"단비가 엿을 굴리던 입을 멈추고 내 소매를 살짝 당겼다. 문가의 여운비는 팔짱을 낀 채 노인의 손만 보고 있었다."},{"s":null,"t":"서하람이 문가에서 몸을 일으켰다. 두루마리를 옆구리에 끼고 하품을 하며 다가왔다."},{"s":"q:r71_seoharam","t":"아… 저 갈래요. 지워진 땅의 관상대라니, 관측하러 가야죠. 그런 데 별은 아무도 안 적어 봤을 거예요."},{"s":null,"t":"서이연이 서하람의 팔을 붙잡았다. 서하람이 그 손을 가만히 내려다보다가 서이연의 손등을 토닥였다."},{"s":"q:r71_seoharam","t":"관측만 하고 올게요. 예언은 안 하고요. 약속해요."},{"s":null,"t":"서이연이 한참 서하람을 보다가 손을 놓았다. 서이연은 나를 문밖으로 따로 불러냈는데, 졸린 눈에 물기가 고여 있었다."},{"s":"mandate_court:seo","t":"조사원님, 부탁이 하나 있어요. 저 애 이름을 자주 불러 주세요. 자주요. 까닭은… 지금은 말 못 해요. 그냥 자주 불러 주세요."},{"s":null,"t":"내가 그러겠다고 하자 서이연이 고개를 숙였다. 그때 관성대 지붕 위에서 서하람이 우리를 불렀다."},{"s":"q:r71_seoharam","t":"저기요… 떠나기 전에 오늘 밤 별 좀 같이 적어 주실래요? 오늘 하늘에 하나가 비어요. 혼자 적기엔 별이 너무 많아서요."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":8,"title":"받아 적은 별","goal":"자율 활동 「자료 조사」를 1시간 넘게 끝까지 하며 서하람과 별을 받아 적는다","need":{"at":["star_observatory"],"tasks":[{"t":"idle","k":"research","min":60,"n":1}]},"lines":[{"s":null,"t":"그날 밤 우리 여섯이 관성대 지붕에 나란히 누웠다. 기와가 낮의 온기를 품고 있어 등이 따뜻했다."},{"s":null,"t":"서하람이 손가락으로 별을 하나씩 짚으며 불렀고, 나는 그 곁에서 붓을 들고 받아 적었다."},{"s":"q:r71_seoharam","t":"저건 큰 국자 손잡이 끝이에요… 그 옆에 흐린 건 관측생들이 「졸음별」이라고 불러요. 저를 닮았대요… 적어 주세요."},{"s":null,"t":"내가 「졸음별」이라고 적자 청파가 쿡쿡 웃으며 하늘을 가리켰다."},{"s":"q:sn_cheongpa","t":"하람 형님, 저 반짝이는 건요? 물에 비친 것처럼 깜빡거려요."},{"s":null,"t":"서하람이 눈을 가늘게 뜨고 그쪽을 보았다."},{"s":"q:r71_seoharam","t":"아… 그건 별이 아니라 비금이에요. 날아가는 거요. 적지 마세요."},{"s":null,"t":"갈매가 코웃음을 쳤다. 코웃음을 치면서도 팔베개를 하고 하늘을 오래 올려다보았다."},{"s":"southern_remnant:galmae","t":"남명에선 별을 안 세. 셀 시간에 칼을 갈지. …근데 저기 하나 빈 데 있다. 저건 뭐야?"},{"s":null,"t":"서하람이 졸린 눈을 크게 뜨고 갈매가 가리킨 자리를 한참 보았다."},{"s":"q:r71_seoharam","t":"잘 보셨네요… 거기가 오늘 비는 자리예요. 일흔 해 전부터 거기엔 아무것도 비치지 않아요. 하늘이 아니라 땅에 구멍이 나 있는 거예요. 별빛이 비치는 땅에요."},{"s":null,"t":"서하람이 손가락을 펴 빈자리와 지평선 사이를 재었다. 손가락 끝이 남쪽을 가리켰다."},{"s":"q:r71_seoharam","t":"짚어 보면… 정청 봉인고 아래쯤이에요. 관측한 거예요. 예언이 아니라요."},{"s":null,"t":"단비가 엿을 깨물다 말고 서하람을 보았다. 감찰관이 봉인고로 오라 한 말이 떠올랐는지 나를 돌아보았다."},{"s":"red_moon_cult:danbi","t":"봉인고면 감찰관님이 오라는 데잖아요. 별까지 그리로 오라네요. 재밌다."},{"s":null,"t":"여운비가 손을 들어 칼자루 술을 보았다. 바람 한 점 없는 밤이었는데 붉은 술이 남쪽으로 살랑 기울었다."},{"s":"north_league:yeo","t":"…바람도 그쪽이오."},{"s":null,"t":"한동안 아무도 말이 없었다. 여섯이 같은 빈자리를 올려다보았다."},{"s":null,"t":"새벽녘 관성대 계단으로 흑련 매듭을 단 심부름꾼이 숨을 헐떡이며 올라왔다. 심부름꾼이 서툰 글씨의 서신 한 통을 내밀었다."},{"s":"q:md_lotus_runner","t":"장부고 다온이 보낸 겁니다. 꼭 조사원님 손에 드리라고 해서요. 회주님 말씀도 하나 받아 적었답니다."},{"s":null,"t":"서신에는 장부 글씨를 흉내 낸 큼직한 글자가 꾹꾹 눌려 있었다."},{"s":"q:mk_daon","t":"「{이름} 님, 다온이에요. 아저씨는 잘 있어요. 잿빛은 팔꿈치에서 멈췄어요. 제가 날마다 부르니까요. 쪽지는 안 폈어요.」"},{"s":"q:mk_daon","t":"「어젯밤엔 아저씨가 잠꼬대로 엽전을 셌어요. 하나, 둘, 셋… 아홉에서 멈췄어요. 손가락이 아홉 개라서요. 그래서 제가 열 해 줬어요. 아저씨가 자면서 웃었어요.」"},{"s":"q:mk_daon","t":"「회주님이 말씀하셨어요. 첫 회주님이 칠십 년 전에 빠져나온 옛 물길이 있대요. 봉인고 아래에서 시작한대요. 거기로 가면 장부를 가져간 사람들이 어디서 왔는지 알 수 있을 거래요. 구슬 누나가 받아 적는 거 도와줬어요.」"},{"s":"q:mk_daon","t":"「서리님한테도 편지 썼어요. {이름} 님, 밥 잘 챙겨 먹어요. 엿을 다 먹었으면 또 사 먹어요.」"},{"s":null,"t":"청파가 내 어깨너머로 서신을 읽다가 코를 훌쩍였다. 단비가 서신을 받아 들고 끝까지 읽더니 품에서 엿 하나를 꺼내 들고 한참 보았다."},{"s":"red_moon_cult:danbi","t":"이 애한테 엿을 보내 줘야겠어요. 적월 엿이 제일 달거든요."},{"s":null,"t":"갈매가 서신을 흘끗 보았다. 퉁명스럽게 말했지만 목소리가 낮았다."},{"s":"southern_remnant:galmae","t":"…봉인고 아래 물길이래. 별이랑 바람이랑 흑련까지 다 그리로 가라잖아. 정리관보다 먼저 가자. 그놈한테 또 한 걸음 뒤질 순 없잖아."},{"s":null,"t":"서하람이 두루마리를 둘둘 말았다. 서이연이 계단 아래에서 우리를 올려다보고 있었다. 서하람이 그쪽으로 손을 흔들었다."}],"reward":{"xp":1920}},{"quest_id":"mdq_4","step":9,"title":"봉인고 앞의 차","goal":"봉인고에 도착해 2번 탐색하며 압수물 창고를 찾는다","need":{"at":["seal_vault"],"tasks":[{"t":"travel","r":["seal_vault"],"n":1},{"t":"search","r":["seal_vault"],"n":2}]},"lines":[{"s":null,"t":"봉인고 압수물 창고는 맨 안쪽에 있었다. 녹슨 쇠문 앞 돌마당에 작은 찻상 하나가 놓여 있었다."},{"s":null,"t":"찻상 앞에 정리관 경현이 혼자 앉아 있었다. 따르는 이도, 지키는 이도 없었다. 찻주전자에서 김이 모락모락 올랐다."},{"s":null,"t":"경현이 우리를 보고 빙그레 웃었다. 찻잔 다섯을 가지런히 놓고 쪼르륵쪼르륵 하나씩 차를 따랐다."},{"s":"q:md_gyeonghyeon","t":"오셨구려. 이번엔 내가 먼저 왔으니, 차는 내가 내겠소. 앉으시오, 모두들."},{"s":null,"t":"아무도 앉지 않았지만, 경현은 개의치 않고 찻잔 하나를 들어 여운비 쪽으로 밀었다."},{"s":"q:md_gyeonghyeon","t":"여운비. 여씨 집안 셋째 딸. 당신 집안 이야기는 내 장부 이백십일 쪽에 있소. 종 이야기요. 맹주께서는 아직 당신한테 안 하셨겠지만."},{"s":null,"t":"여운비의 얼굴에서 핏기가 가셨다. 경현은 둘째 잔을 단비 쪽으로 밀었다."},{"s":"q:md_gyeonghyeon","t":"단비. 열네 살에 첫 서약을 치렀지. 그날 태운 이름이 누구 것이었고 어디서 왔는지 아시오? 그것도 내 장부에 있소."},{"s":null,"t":"단비의 엿 씹던 입이 멈췄다. 웃음이 얼굴에 그대로 굳었다. 경현은 셋째 잔을 청파 앞에 놓았다."},{"s":"q:md_gyeonghyeon","t":"청파. 수향 잠수꾼, 막내. 당신 증조할아버님 배가 소등 전날 무엇을 싣고 나갔는지 나는 아오. 도방께서는 그 얘기를 당신한테 하지 말라 하셨겠지."},{"s":null,"t":"청파가 무슨 소린지 모르는 얼굴로 눈을 끔뻑이며 나를 보았다. 나는 청파의 어깨를 잡았다."},{"s":null,"t":"경현이 넷째 잔을 갈매 쪽으로 밀었다. 찻잔이 상 끝에서 멈췄다."},{"s":"q:md_gyeonghyeon","t":"갈매. 잔불촌 정찰대장. 장군께서 당신을 뭐라고 부르시는지, 나는 그 까닭까지 아오."},{"s":null,"t":"갈매가 칼을 확 뽑았다. 쉬익, 칼날이 경현의 목 앞까지 날아들었다."},{"s":"southern_remnant:galmae","t":"한 마디만 더 해 봐. 그 입 찢어 버린다!"},{"s":null,"t":"여운비가 갈매의 팔목을 붙잡았다. 칼끝이 경현의 목에서 한 치 앞에 멈췄다. 경현은 눈도 깜빡이지 않았다."},{"s":"north_league:yeo","t":"넣으시오. 정청 사람을 여기서 베면, 정청은 남명에 칼을 들 핑계를 얻소. 저 사람이 바라는 게 그거요."},{"s":null,"t":"갈매가 이를 갈며 칼을 거두었다. 경현이 다섯째 잔을 서하람 앞에 놓았다."},{"s":"q:md_gyeonghyeon","t":"서하람. 당신 별은 내 장부에 없소. 백 년 동안 모든 명부를 읽었는데, 당신 이름만 없었소. 그게 이상하지 않소?"},{"s":null,"t":"서하람이 졸린 눈을 천천히 들었지만 대답하지 않았다. 두루마리를 쥔 손가락만 꽉 오므라들었다."},{"s":null,"t":"경현이 마지막으로 나를 보았다. 찻잔 대신 접힌 장부 한 권을 상 위에 올렸다."},{"s":"q:md_gyeonghyeon","t":"조사원. 일곱 장을 모아 오시오. 모아 오면 정청이 지키겠소. 당신은 장을 찾아내는 데 재주가 있으니."},{"s":null,"t":"나는 장을 정청에 맡기지 않겠다고 했다. 정청이 그걸로 무엇을 하려는지 알기 전에는 아무에게도 내주지 않겠다고 했다."},{"s":null,"t":"경현은 화를 내지 않고 고개를 끄덕이더니 찻잔을 들어 한 모금 마셨다."},{"s":"q:md_gyeonghyeon","t":"옳은 말이오. 나라도 그랬겠지. 그럼 내가 왜 장을 거두려는지, 까닭 하나만 들려 드리리다."},{"s":"q:md_gyeonghyeon","t":"정청 명부는 한 사람이 한 줄이오. 이름, 태어난 해, 사는 고을. 맨 끝에 손바닥만 한 빈 네모가 하나 있었소. 그 이름을 불러 줄 사람이 제 이름을 적고 엄지 도장을 꾹 찍는 칸이오. 도장이 찍힌 줄은 거둘 수가 없었지."},{"s":"q:md_gyeonghyeon","t":"장날이면 장터 한쪽에 부름꾼이 명부 사본을 펴 놓고 앉았소. 쌀 두 섬을 내면 아무 줄에나 제 이름을 적고 도장을 찍어 주었지. 한 해에 수백 줄을. 그 이름들을 실제로 불러 준 적은 한 번도 없었소."},{"s":"q:md_gyeonghyeon","t":"돈 있는 집 줄은 칸이 다 찼소. 쌀이 없는 화전민 고을, 글을 모르는 산골 줄은 칸이 비었소. 해마다 거둘 수는 정해져 있으니, 빈 칸이 남은 그 고을에서 다 거두었소. 그것도 모자라던 해에는… 그 고을 우물에서 검은 물이 솟았소."},{"s":null,"t":"경현이 찻잔을 내려놓았다. 처음으로 목소리가 아주 조금 낮아졌다."},{"s":"q:md_gyeonghyeon","t":"칸이 돌아오면 다음 장날에 부름꾼이 다시 앉소. 당신은 쌀 두 섬이 없는 고을을 본 적이 있소? 나는 보았소. 한 고을이 하룻밤 새 옷과 신만 남았소."},{"s":null,"t":"아무도 말하지 못했다. 청파가 내 소매를 꼭 붙잡았다. 단비의 손에서 엿이 툭 떨어졌다."},{"s":null,"t":"경현이 일어서서 찻상 옆의 낡은 압수물 함을 열어 보였다. 함 속은 텅 비어 있었다."},{"s":"q:md_gyeonghyeon","t":"감찰관이 말한 백 년 전 서식은 내가 거두었소. 정청 문서이니 정청이 맡소. 누가 시킨 게 아니오. 정리관이 할 일이오."},{"s":null,"t":"갈매가 다시 칼자루를 쥐자 여운비가 그 손등을 꾹 눌렀다."},{"s":"southern_remnant:galmae","t":"증거를 먼저 치웠다 이거지. 비겁한 늙은이."},{"s":null,"t":"경현이 갈매를 보며 웃었다. 비웃음이 아니라 지친 사람의 웃음이었다."},{"s":"q:md_gyeonghyeon","t":"비겁한 것과 셈을 아는 것은 다르오. 증거를 숨긴 게 아니라, 정청 문서를 제자리에 거둔 거요."},{"s":"q:md_gyeonghyeon","t":"기한은 동지 전까지요. 그때까지 당신들이 장을 모아 정청에 맡기든지, 내가 거두든지 둘 중 하나요."},{"s":null,"t":"경현이 찻잔 다섯을 그대로 두고 돌아섰다. 혼자 봉인고 문 쪽으로 걸어가는 걸음이 처음 장서각 마당에서 본 것처럼 느긋했다."},{"s":null,"t":"경현의 발소리가 사라지자 청파가 털썩 주저앉아 그제야 숨을 몰아쉬었다."},{"s":"q:sn_cheongpa","t":"저 사람… 우리 증조할아버지 배를 어떻게 알아요? 무슨 배요? {이름} 님은 알아요?"},{"s":null,"t":"나는 모른다고 했다. 진소랑과의 약속이 목에 걸렸다. 여운비가 청파의 머리를 손바닥으로 가볍게 눌렀다."},{"s":"north_league:yeo","t":"저 사람 장부에 무엇이 적혀 있든, 우리가 직접 찾아서 보면 되오. 남의 장부로 제 집 일을 듣는 건 북령 방식이 아니오."},{"s":null,"t":"단비가 떨어진 엿을 주워 들고 먼지를 털었다. 다시 웃었지만 아까보다 얇은 웃음이었다."},{"s":"red_moon_cult:danbi","t":"다들 저 사람 장부에 한 쪽씩 있네요. 기분 나빠라. …제 서약 이름이 어디서 왔는지는 교주님께 직접 여쭐 거예요. 저 사람 입으로 듣는 건 엿을 뺏기는 것보다 억울하거든요."},{"s":null,"t":"갈매가 칼을 칼집에 탁 넣었다. 아까 칼을 붙잡았던 여운비 쪽은 보지 않고 말했다."},{"s":"southern_remnant:galmae","t":"저 늙은이가 할배 얘기를 한 번만 더 꺼내면, 그땐 북령이 팔목을 붙잡아도 안 놔."},{"s":null,"t":"여운비가 대답 대신 갈매 옆으로 가 섰다. 갈매는 비키지 않았다."},{"s":null,"t":"서하람이 빈 압수물 함 안을 들여다보다가 바닥의 틈새를 가리켰다. 창고 맨 안쪽 갈라진 바닥 끝에서 돌계단 하나가 어둠 속으로 내려가고 있었다."},{"s":"q:r71_seoharam","t":"아… 여기예요. 어젯밤 빈 별 자리요. 이 아래예요."},{"s":null,"t":"여운비가 칼자루를 들어 붉은 술을 보았다. 술이 계단 쪽에서 위로 살랑 날렸다."},{"s":"north_league:yeo","t":"바람이 아래에서 올라오오. 이 땅 밑에 커다란 빈 곳이 있는 모양이오."},{"s":null,"t":"청파가 계단 끝에 귀를 대고 엎드렸다가 한참 뒤 고개를 들었다. 들떠 있던 얼굴이 조용히 가라앉아 있었다."},{"s":"q:sn_cheongpa","t":"물소리가 나요. 아주 깊은 데서요. 다온이 말한 옛 물길이에요. …오늘은 내려가지 마요. 물이 어떤 물인지 모르면 들어가면 안 돼요. 날 밝으면 제가 먼저 볼게요."},{"s":null,"t":"그날 밤 우리 여섯은 봉인고 창고 한쪽에 불을 피우고 처음으로 한자리에 누웠다. 여운비는 칼을 무릎에 두고 앉아 계단 쪽을 지켰다."},{"s":null,"t":"단비가 엿을 하나씩 나눠 주었다. 갈매는 받지 않았다가, 모두 잠든 줄 알았을 때 슬쩍 집어 입에 넣었다. 나는 그걸 보았지만 모르는 척했다."}],"reward":{"xp":1920,"gil":470,"items":{"grand_pill":1,"spirit_core":2}}},{"quest_id":"mdq_5","step":1,"title":"식은 찻잔","goal":"봉인고에서 다섯이 함께 첫 밤을 쉬고 식은 찻잔을 앞에 둔다","need":{"at":["seal_vault"],"tasks":[{"t":"rest","r":["seal_vault"],"n":1}]},"lines":[{"s":null,"t":"봉인고 창고에서 맞은 아침은 눅눅했다. 압수물 창고 쇠문 앞 돌마당에는 경현이 두고 간 찻잔 다섯이 밤새 그대로 놓여 있었다."},{"s":null,"t":"찻잔마다 식은 차가 반쯤 남아 있었다. 아무도 그 잔에 손을 대지 않았다."},{"s":null,"t":"맨 먼저 일어난 것은 갈매였다. 갈매가 찻상 앞으로 성큼성큼 걸어가 칼집째 쥔 칼로 찻상을 쾅 내리쳤다. 찻잔 하나가 굴러떨어져 쨍그랑 깨졌다."},{"s":"southern_remnant:galmae","t":"어제 왜 막았어, 북령. 그 늙은이가 우리 할배 얘기까지 꺼냈잖아!"},{"s":null,"t":"여운비는 깨진 찻잔 조각을 내려다보았다. 칼자루 끝에 매단 붉은 술이 계단 쪽에서 올라오는 바람에 살랑 흔들렸다."},{"s":"north_league:yeo","t":"봉인고 문 앞에서 정청 관리를 베면 우리는 한 걸음도 더 못 가오. 그자가 바란 게 그거였을지도 모르오."},{"s":"southern_remnant:galmae","t":"그래서 차나 홀짝이고 있으라고?"},{"s":"north_league:yeo","t":"아니오. 그자보다 먼저 가자는 거요."},{"s":null,"t":"단비가 깨지지 않은 찻잔 하나를 집어 냄새를 맡더니 남은 차를 땅에 쪼르르 쏟아 버렸다. 웃는 얼굴이었지만 손끝이 조금 떨렸다."},{"s":"red_moon_cult:danbi","t":"저는 한 모금도 안 마셨어요. 그 사람, 제가 열네 살에 쓴 이름이 어디서 왔는지 안다잖아요. 그 이름을 누구한테 샀는지는 저도 알아요. 근데 그 목록이 처음 어디서 나왔는지는 저도 모르는 걸요. 기분 나빠라."},{"s":null,"t":"청파는 대꾸 없이 깨진 찻잔 조각을 하나씩 주워 손수건에 쌌다. 서하람은 빈 압수물 함 옆에 쪼그려 앉아 두루마리에 무언가를 적고 있었다."},{"s":"q:r71_seoharam","t":"아… 그 사람이 그랬잖아요. 백 년 동안 명부를 다 읽었는데 제 이름만 없었다고요. 그것도 적어 둘게요. 왜 없는지는… 아직 몰라요."},{"s":null,"t":"그때 봉인고 문지기 하나가 서신을 들고 창고로 뛰어 들어왔다. 문지기는 숨을 몰아쉬며 서신을 두 손으로 내밀었다."},{"s":"q:md_vault_guard","t":"조사원님 앞으로 온 서신입니다. 오늘 새벽 정청에서 왔습니다. 감찰관님 개인 인장이 찍혀 있어서, 다른 사람 손 안 타게 곧장 들고 왔습니다."},{"s":null,"t":"서신을 펴자 한설의 각진 글씨가 나왔다. 나는 일행이 들을 수 있게 소리 내어 읽었다."},{"s":"night_office:han","t":"조사원. 정리관께서 봉인고로 가셨다는 걸 들었다. 그분이 너희를 막지 않았다면, 막을 까닭이 아직 없어서다. 그걸 잊지 마라."},{"s":"night_office:han","t":"내 동료 셋의 보고서를 고친 손을 쫓고 있다. 먹에서 장서각 아래 냄새가 난다. 아직은 거기까지다. 다섯을 다 데려갔으면, 다섯 다 데리고 돌아와라."},{"s":null,"t":"청파가 서신을 들여다보며 코를 훌쩍였다."},{"s":"q:sn_cheongpa","t":"다섯 다 데리고 돌아오래요. 우리 이름은 하나도 안 적으셨는데, 그래도 우리를 세셨네요."},{"s":null,"t":"갈매가 콧방귀를 뀌었지만 더 따지지는 않았다. 나는 서신을 품에 넣고 어젯밤 서하람이 찾아낸 돌계단 앞에 섰다."},{"s":"q:sn_cheongpa","t":"어제 제가 먼저 본다고 했잖아요. {이름} 님, 제가 앞에 설게요. 물은 수향 사람이 먼저 만져 봐야 해요."},{"s":null,"t":"청파가 등잔을 받아 들고 앞장섰다. 계단을 내려갈수록 공기가 축축해졌다. 똑, 똑, 물 떨어지는 소리가 커지더니 맨 아래에 물에 잠긴 수로가 나타났다."},{"s":null,"t":"수로 벽의 이끼를 손바닥으로 문지르자 글씨 한 줄이 드러났다. 「등도 남문 물길. 칠십 년 전 동짓밤, 여든둘이 이 길로 나왔다」라고 새겨져 있었다."},{"s":"red_moon_cult:danbi","t":"다온이 편지에 쓴 옛 물길이 여기네요. 흑련 첫 회주님이 빠져나왔다는 길이요."},{"s":null,"t":"청파가 무릎을 꿇고 수로 물에 손을 담갔다. 다음 순간 청파가 「앗!」 하고 손을 홱 빼냈다."},{"s":null,"t":"손등이 잿빛으로 바래 있었다. 핏기가 싹 빠진 손이 바들바들 떨렸다."},{"s":"red_moon_cult:danbi","t":"막내야! 손 이리 줘 봐요, 얼른!"},{"s":null,"t":"단비가 청파의 손목을 잡아 제 무복 소매로 박박 문질렀다. 여운비는 청파의 뒷덜미를 잡아 물가에서 한 걸음 끌어냈다."},{"s":"southern_remnant:galmae","t":"뭐 하는 거야, 꼬맹이! 아무 물에나 손을 넣냐?"},{"s":"q:sn_cheongpa","t":"물이 어떤지 보려고요… 수향에서는 물부터 만져 보거든요."},{"s":null,"t":"한참을 문지르자 청파의 손등에 겨우 핏기가 돌아왔다. 청파가 젖은 손을 다른 손으로 감싸 쥐었다. 늘 들떠 있던 얼굴이 굳어 있었다."},{"s":"q:sn_cheongpa","t":"이건 그냥 물이 아니에요. 맨발로 들어가면 안 돼요. 배로 가야 해요."},{"s":null,"t":"청파가 계단 옆 기둥을 가리켰다. 거룻배 한 척이 밧줄에 묶인 채 반쯤 가라앉아 있었다."},{"s":"q:sn_cheongpa","t":"판자가 세 장 썩었어요. 나무만 있으면 제가 덧댈 수 있어요. 봉인고 뒷산에 부적목이 있던데, 그걸 가공 부적목으로 다듬으면 이 물에도 오래 버텨요."},{"s":null,"t":"청파의 말로는 생나무를 그대로 대면 먹물을 머금어 금세 뒤틀리지만, 수지에 재운 가공 부적목은 물을 먹을수록 단단해진다고 했다."},{"s":null,"t":"서하람이 수로 끝 어둠을 들여다보며 하품을 참았다."},{"s":"q:r71_seoharam","t":"아… 별 기록에서 비어 있던 땅이 이 물길 끝이에요. 정리관이 우리보다 먼저 가 있을지도 몰라요."},{"s":"north_league:yeo","t":"그럼 판자부터 구합시다. 우리가 찻잔 앞에서 다투는 동안에도 그자는 걷고 있었을 거요."}],"reward":{"xp":2468}},{"quest_id":"mdq_5","step":2,"title":"판자를 덧대는 법","goal":"부적목 6개를 모아 가공 부적목 3개를 만들고 봉인고에서 청파에게 넘긴다","need":{"at":["seal_vault"],"tasks":[{"t":"gather","n":6,"items":["wood"]},{"t":"craft","items":["lumber"],"n":3}],"give":{"lumber":3}},"lines":[{"s":null,"t":"가공 부적목 세 장을 들고 수로로 내려가자, 청파가 벌써 거룻배를 계단 위로 끌어 올려 뒤집어 두고 있었다. 썩은 판자를 뜯어낸 자리가 이 빠진 것처럼 휑했다."},{"s":"q:sn_cheongpa","t":"와, 결이 곧네요! {이름} 님, 이거 직접 깎으셨어요? 수향 목수들도 이렇게는 잘 못 깎아요."},{"s":null,"t":"청파는 판자를 손바닥으로 쓸어 보고 코에 대 냄새까지 맡았다. 청파가 일행을 돌아보며 손뼉을 짝 쳤다."},{"s":"q:sn_cheongpa","t":"자, 다들 한 장씩 맡아 주세요. 혼자 하면 반나절이고, 다 같이 하면 한 식경이에요."},{"s":null,"t":"여운비가 말없이 판자 한쪽 끝을 들어 배 옆구리에 댔다. 청파가 반대쪽 끝을 맞추며 고개를 끄덕였다."},{"s":"q:sn_cheongpa","t":"대장 누님은 그대로 꽉 잡고 계세요. 갈매 누님, 거기 나무못 박아 주세요. 세게요!"},{"s":null,"t":"갈매가 망치를 들어 나무못을 내리쳤다. 쾅, 쾅, 두 번은 못을 맞혔다. 세 번째는 제 엄지를 맞혔다."},{"s":"southern_remnant:galmae","t":"아악! 이 썩을…!"},{"s":null,"t":"갈매가 엄지를 입에 물고 펄쩍펄쩍 뛰었다. 단비가 손뼉을 치며 웃었다. 여운비는 판자를 잡은 채 고개를 돌렸는데, 입꼬리가 아주 조금 움찔했다."},{"s":"red_moon_cult:danbi","t":"대장님, 지금 웃으셨죠? 봤어요. 제가 봤어요."},{"s":"north_league:yeo","t":"…판자가 미끄러져서 그렇소."},{"s":"southern_remnant:galmae","t":"웃지 마! 이 망치 누가 만든 거야, 대가리가 덜렁거리잖아!"},{"s":null,"t":"나는 갈매에게서 망치를 받아 자루와 쇠머리 사이에 쐐기를 하나 박아 주었다. 갈매는 고맙다는 말 대신 망치를 휙 낚아채 갔다. 이번에는 못이 엄지를 비켜 갔다."},{"s":null,"t":"서하람은 등잔을 들고 서 있는 일을 맡았다. 서하람의 고개가 꾸벅 떨어지는 순간 등잔 불빛이 크게 흔들렸다."},{"s":"q:sn_cheongpa","t":"하람 형님! 불 떨어져요, 불!"},{"s":"q:r71_seoharam","t":"아… 안 잤어요. 눈을 감고 판자 결을 관측했어요."},{"s":null,"t":"마지막으로 남은 일은 판자 틈을 메우는 것이었다. 청파가 송진과 삼 부스러기를 섞어 내 손에 한 줌 덜어 주었다."},{"s":"q:sn_cheongpa","t":"이렇게 엄지로 밀면서 꾹, 꾹이요. 아버지가 제일 처음 가르쳐 준 게 이거예요. 판자는 물을 먹어야 붙고, 틈은 사람 손으로 막아야 한대요."},{"s":null,"t":"내가 따라 하자 청파가 내 손등 위에 제 손을 겹쳐 힘을 더 주게 했다. 수로 물에 바랬던 그 손은 아직 조금 차가웠다."},{"s":null,"t":"나는 청파의 손을 잠깐 쥐어 주었다. 청파가 헤헤 웃으며 제 손을 바지에 쓱쓱 비볐다."},{"s":null,"t":"일을 마친 뒤 다 같이 배를 물에 띄웠다. 거룻배가 철썩 소리를 내며 물 위에 앉았다. 청파가 배 밑창에 엎드려 귀를 대 보았다."},{"s":null,"t":"물 새는 소리가 들리지 않자 청파가 벌떡 일어나 두 팔을 번쩍 들었다."},{"s":"q:sn_cheongpa","t":"안 새요! 하나도 안 새요!"},{"s":null,"t":"단비가 청파의 등을 팡팡 두드렸다. 갈매는 퉁퉁 부은 엄지를 감싸 쥔 채로 콧방귀를 뀌었는데, 그 콧방귀가 평소보다 짧았다."},{"s":null,"t":"여운비가 배에 먼저 올라 칼자루의 붉은 술을 들여다보았다. 술 끝이 물길 깊은 쪽에서 이쪽으로 살랑 날렸다."},{"s":"north_league:yeo","t":"바람이 저 안에서 불어오오. 끝이 트여 있다는 얘기요. 노는 청파가 잡고, 뱃머리에는 내가 서겠소."},{"s":"q:sn_cheongpa","t":"다들 배 가운데 앉으세요. 물에는 절대 손 넣지 마세요. 절대요!"},{"s":null,"t":"서하람이 배 가운데에 앉으며 두루마리를 무릎에 폈다. 관성대 지붕에서 받아 적은 빈 별 자리가 그려져 있었다."},{"s":"q:r71_seoharam","t":"내리면 먼저 둘레를 둘러봐요. 빈 별 자리 바로 밑이 어떤 땅인지 모르고 걸으면 길을 잃어요."}],"reward":{"xp":2468}},{"quest_id":"mdq_5","step":3,"title":"흰 밤","goal":"꺼진 관아 터에 도착해 3번 탐색한다","need":{"at":["dark_yamen"],"tasks":[{"t":"travel","r":["dark_yamen"],"n":1},{"t":"search","r":["dark_yamen"],"n":3}]},"lines":[{"s":null,"t":"거룻배는 반나절 동안 수로를 거슬러 올랐다. 청파가 노를 저을 때마다 찰박, 찰박 소리가 돌벽에 부딪혀 여러 겹으로 울렸다."},{"s":null,"t":"어느 순간 그 소리가 뚝 끊겼다. 노는 여전히 물을 가르는데, 노 끝에서 아무 소리도 나지 않았다."},{"s":null,"t":"수로 끝 돌계단을 올라서자 눈앞이 하얗게 트였다."},{"s":null,"t":"하늘이 희었다. 해도 달도 구름도 없었다. 동트기 직전 같은 흰빛만 하늘 끝에서 끝까지 고르게 깔려 있었다."},{"s":null,"t":"흰 하늘 아래 기와지붕이 끝없이 이어져 있었다. 집도 담장도 길도 오래 볕에 둔 종이처럼 색이 빠져 있었다."},{"s":null,"t":"춥지도 덥지도 않았다. 숨을 깊이 들이쉬었는데 아무 냄새도 나지 않았다."},{"s":null,"t":"발밑을 내려다보았다. 그림자가 없었다. 나에게도, 일행 누구에게도 그림자가 생기지 않았다."},{"s":null,"t":"처마 끝에서 물방울 하나가 떨어지다 말고 허공에 멈춰 있었다. 손가락으로 건드리자 물방울은 떨어지지 않고 손끝에 차갑게 들러붙었다."},{"s":null,"t":"처마마다 종이 등롱이 셀 수 없이 걸려 있었다. 등롱마다 이름 적은 종이가 붙어 있었지만, 글자가 모두 하얗게 바래 한 자도 읽히지 않았다. 불이 켜진 등롱은 하나도 없었다."},{"s":null,"t":"갈매가 몇 걸음 앞으로 나가 돌아서서 무어라 소리쳤다. 입은 크게 움직이는데 소리가 들리지 않았다."},{"s":null,"t":"갈매가 성큼성큼 되돌아와 세 걸음 앞에 섰다. 그제야 목소리가 귀에 닿았다."},{"s":"southern_remnant:galmae","t":"…들려? 이제 들리냐고! 뭐야, 이거. 소리가 안 가잖아!"},{"s":"q:sn_cheongpa","t":"누님 입만 뻐끔뻐끔했어요. 붕어 같았어요."},{"s":null,"t":"갈매가 청파를 노려보았다. 청파는 갈매의 소매 끝을 꼭 쥐고 놓지 않았다. 청파의 손도 덜덜 떨리고 있었다."},{"s":null,"t":"여운비가 칼자루를 들어 붉은 술을 눈높이로 올렸다. 술은 실 한 올 흔들리지 않고 곧게 아래로 늘어져 있었다."},{"s":"north_league:yeo","t":"바람이 없소. 바람이 멈춘 땅이라니… 북령 끝까지 가 봐도 이런 데는 없소."},{"s":null,"t":"단비가 방울을 꺼내 한 번 흔들었다. 딸랑, 하는 소리가 방울 둘레에서만 맴돌다가 손바닥 안으로 꺼지듯 사라졌다."},{"s":"red_moon_cult:danbi","t":"축문이 안 퍼져요. 여기서는 소리가 다 제자리에서 죽네요."},{"s":null,"t":"서하람은 졸음기가 싹 가신 눈으로 하늘을 한 바퀴 둘러보았다. 두루마리를 펴 무언가를 적는 손이 멈추지 않았다."},{"s":"q:r71_seoharam","t":"해가 없는데 밝아요. 별이 없는데 밤 같아요. 이건… 관측 기록에 이름이 없는 하늘이에요."},{"s":null,"t":"우리는 세 걸음 넘게 떨어지지 않도록 서로 붙어서 흰 거리를 살폈다. 무너진 담장 셋을 지나자 높은 돌계단 위에 관아 터가 나왔다."},{"s":null,"t":"대문은 쓰러져 있었고, 현판 하나만 기둥에 비스듬히 매달려 있었다. 다른 것은 다 바랬는데 현판 글씨만은 또렷했다."},{"s":null,"t":"현판에는 「등도 관아, 도제조 백운서 쓰다」라고 적혀 있었다. 그 옆에 새겨진 날짜는 삼백 년 전이었다."},{"s":"q:sn_cheongpa","t":"백운서요? 정청 도제조님 이름이랑 똑같네요. 와, 삼백 년 전에도 그런 이름이 있었구나."},{"s":"red_moon_cult:danbi","t":"이름 같은 사람이 어디 한둘이에요. 적월에도 월화가 셋인걸요."},{"s":null,"t":"나는 품에서 반쯤 탄 첫째 장을 꺼냈다. 종이 위에 뜬 흰 불꽃 아래로 반쯤 남은 붉은 인장이 보였다."},{"s":null,"t":"현판 귀퉁이에 새겨진 인장도 같은 모양이었다. 나는 아무 말 없이 종이를 다시 품에 넣었다."},{"s":null,"t":"여운비가 관아 안마당을 둘러보고 내 쪽으로 돌아섰다."},{"s":"north_league:yeo","t":"해가 안 움직이니 몸이 시간을 잊소. 몸이 잊어도 다리는 기억하오. 오늘은 여기서 불을 피웁시다."},{"s":"southern_remnant:galmae","t":"불은 뭘로 피워. 여기 있는 건 다 색이 빠졌는데."},{"s":"north_league:yeo","t":"마른 서까래는 색이 없어도 탈 거요. 땔감을 모으는 동안 누가 저녁을 맡으시오."},{"s":null,"t":"단비가 나를 보며 생긋 웃었다. 청파도 서하람도 갈매도 모두 나를 보았다."},{"s":"red_moon_cult:danbi","t":"{이름} 님이 국을 끓여 주세요. 정청 사람이 끓인 국은 무슨 맛인지 궁금했거든요."},{"s":null,"t":"짐에 든 것이라고는 약재뿐이라, 나는 영맥 수피와 빙정염을 우려 영맥 약선탕을 끓이기로 했다."}],"reward":{"xp":2468}},{"quest_id":"mdq_5","step":4,"title":"누룽지와 금빛 실","goal":"꺼진 관아 터에서 4번 채집하고 영맥 약선탕 1그릇을 끓여 첫 저녁으로 넘긴다","need":{"at":["dark_yamen"],"tasks":[{"t":"gather","n":4,"r":["dark_yamen"]},{"t":"craft","items":["bark_stew"],"n":1}],"give":{"bark_stew":1}},"lines":[{"s":null,"t":"내가 국 냄비를 들고 안마당으로 돌아왔을 때, 불가에서 시커먼 연기가 피어오르고 있었다. 냄새 없던 땅에 처음으로 탄내가 번졌다."},{"s":null,"t":"밥솥 앞에 서하람이 쪼그려 앉아 있었다. 두루마리를 무릎에 펼친 채 꾸벅꾸벅 졸던 서하람의 머리 위로 갈매의 고함이 떨어졌다."},{"s":"southern_remnant:galmae","t":"야, 잠꾸러기! 밥 타잖아! 밥 보라니까 별을 보고 있었어?"},{"s":"q:r71_seoharam","t":"아… 여기 별은 없어요. 그래서 밥을 관측하고 있었는데… 밥이 먼저 타 버렸네요."},{"s":null,"t":"청파가 솥뚜껑을 열었다. 솥 바닥이 새까맸다. 청파는 실망하기는커녕 눈을 반짝이며 주걱으로 바닥을 박박 긁었다."},{"s":"q:sn_cheongpa","t":"누룽지다! 이게 제일 맛있는 데예요. 수향에선 누룽지 차지하려고 형제끼리 싸워요."},{"s":null,"t":"청파가 덜 탄 쪽을 골라 맨 먼저 서하람에게 내밀었다. 서하람이 멋쩍은 얼굴로 그것을 받아 오독오독 씹었다."},{"s":null,"t":"내가 국을 한 그릇씩 떠 돌렸다. 다섯 사람은 처음으로 한 불을 둘러싸고 같은 밥을 먹었다."},{"s":null,"t":"앉은 자리는 아직 멀었다. 여운비와 단비 사이가 가장 멀었고, 갈매는 등을 반쯤 돌리고 앉았다."},{"s":"north_league:yeo","t":"…국이 나쁘지 않소."},{"s":"red_moon_cult:danbi","t":"어머, 대장님이 칭찬을 다 하시네. 저한테도 한 번만 해 주세요."},{"s":"north_league:yeo","t":"무녀가 국을 끓이면 그때 하겠소."},{"s":null,"t":"그릇을 다 비웠을 무렵 청파가 무릎을 끌어안고 몸을 떨기 시작했다. 이가 딱딱 부딪쳤다."},{"s":null,"t":"청파의 손등이 다시 잿빛으로 바래 있었다. 낮에 수로 물에 닿았던 그 손이었다. 잿빛이 손목 쪽으로 천천히 번지고 있었다."},{"s":"red_moon_cult:danbi","t":"막내야, 왜 이래요? 손이 얼음이잖아요!"},{"s":"southern_remnant:galmae","t":"아까 그 물이야. 그 물이 아직 안 빠진 거야!"},{"s":null,"t":"나는 청파 곁으로 가 손을 잡았다. 손끝에서 맥이 아주 희미하게 잡혔다."},{"s":null,"t":"장부고에서 다온이 밤새 「아저씨」를 부르던 일이 떠올랐다. 나는 청파의 눈을 들여다보며 청파의 이름을 불렀다."},{"s":null,"t":"내 입에서 나온 숨이 흩어지지 않았다. 숨은 금빛을 띤 가는 실로 엉겨 허공을 건너가더니, 청파의 가슴께에 가 닿았다."},{"s":null,"t":"장부고 등잔 아래에서는 입김처럼 흐리던 빛이었는데, 흰 하늘 아래에서는 실 한 올 한 올이 또렷하게 보였다."},{"s":null,"t":"실이 닿은 자리에 손바닥을 대자 미지근한 온기가 올라왔다. 손목으로 번지던 잿빛이 멈칫했다."},{"s":"q:sn_cheongpa","t":"…어? 따뜻해요. 여기가, 가슴이 따뜻해요."},{"s":null,"t":"일행 모두가 그 금빛을 보았다. 단비가 맨 먼저 청파의 다른 손을 붙잡았다."},{"s":"red_moon_cult:danbi","t":"청파야. 청파야, 눈 떠 봐요."},{"s":null,"t":"금빛 실이 하나 더 닿았다. 잿빛이 손등 쪽으로 한 뼘 밀려났다."},{"s":null,"t":"서하람이 두루마리를 내던지고 청파 앞에 무릎을 꿇었다."},{"s":"q:r71_seoharam","t":"청파. 청파 씨. …이름을 부르니까 빛이 닿아요. 이건, 이건 꼭 적어 둬야 해요."},{"s":null,"t":"갈매가 혀를 차며 일어섰다. 갈매는 청파 앞에 쪼그려 앉아 손바닥으로 청파의 이마를 꾹 짚었다."},{"s":"southern_remnant:galmae","t":"청파. 정신 차려, 이 꼬맹아."},{"s":null,"t":"넷째 실이 닿자 청파가 눈을 끔뻑이며 기운 없이 웃었다."},{"s":"q:sn_cheongpa","t":"누님 목소리는 빛도 무섭게 나오네요…"},{"s":null,"t":"여운비는 불 건너편에서 칼자루를 쥔 채 이쪽을 보고 있었다. 한참 만에 여운비가 일어나 다가왔다."},{"s":"north_league:yeo","t":"…청파. 일어나시오. 돌아갈 때 노는 당신이 저어야 하오."},{"s":null,"t":"다섯째 실이 닿자 잿빛이 손등에서 사라졌다. 청파가 제 손을 들여다보다가 히히 웃었다."},{"s":null,"t":"단비가 갑자기 손뼉을 쳤다."},{"s":"red_moon_cult:danbi","t":"우리, 서로 한 번씩 불러 봐요. 여기선 세 걸음만 떨어져도 소리가 안 가잖아요. 누가 쓰러지면 바로 불러 줄 수 있게 연습해 둬요."},{"s":"southern_remnant:galmae","t":"유치하게 무슨…"},{"s":"red_moon_cult:danbi","t":"그럼 갈매 씨는 쓰러져도 아무도 안 불러 줄게요."},{"s":null,"t":"갈매가 입을 다물었다. 단비는 웃으며 여운비를 똑바로 보았다."},{"s":"red_moon_cult:danbi","t":"여운비."},{"s":null,"t":"금빛 실이 여운비의 가슴에 닿았다. 여운비가 움찔하며 제 가슴을 내려다보았다. 한참 망설이던 여운비의 입술이 열렸다."},{"s":"north_league:yeo","t":"…무녀."},{"s":null,"t":"아무 빛도 나오지 않자 단비가 깔깔 웃었다."},{"s":"red_moon_cult:danbi","t":"거 봐요, 이름을 불러야 한다니까요. 대장님은 숙제예요."},{"s":null,"t":"그날 밤 다섯 사람은 돌아가며 서로의 이름을 불렀다. 청파가 갈매를, 서하람이 청파를, 갈매가 서하람을 불렀다. 금빛 실이 불 위로 이리저리 엇갈렸다."},{"s":null,"t":"마지막에 갈매가 나를 보았다. 갈매는 한참 입을 우물거리다가 고개를 홱 돌리며 내뱉었다."},{"s":"southern_remnant:galmae","t":"…{이름}."},{"s":null,"t":"따뜻한 것이 가슴에 닿았다. 나도 갈매의 이름을 불러 주었다. 갈매는 대답 없이 장작 하나를 불 속에 던졌다."},{"s":null,"t":"청파가 처마 끝을 올려다보다가 벌떡 일어섰다. 청파는 바랜 등롱 몇 개를 처마에서 떼어 와 불가에 내려놓았다."},{"s":"q:sn_cheongpa","t":"우리 이름도 여기 걸어 둬요. 수향에선 배 띄우는 날 배 이름을 등에 써서 달거든요. 그래야 물이 그 배를 기억한대요."},{"s":null,"t":"청파가 바랜 종이를 떼어 내고 새 종이를 붙였다. 다섯 사람은 돌아가며 서로의 이름을 적어 주었다. 갈매는 붓을 쥐더니 서하람의 이름을 삐뚤빼뚤하게 적었다."},{"s":"q:r71_seoharam","t":"아… 획이 하나 빠졌어요, 갈매 씨."},{"s":"southern_remnant:galmae","t":"읽히면 됐지."},{"s":null,"t":"청파가 등잔불을 옮겨 붙인 등롱을 관아 처마 끝에 하나씩 매달았다. 맨 끝에 단 등롱이 한쪽으로 삐뚤게 기울었지만, 청파는 그것만은 고치지 않았다."},{"s":null,"t":"불이 켜진 등롱 둘레에서 바랜 기둥에 붉은 칠 빛이 아주 조금 돌아왔지만, 등롱 한 뼘 밖은 여전히 희었다."},{"s":"q:r71_seoharam","t":"등 둘레만 색이 돌아와요. 이것도 적어 둘게요."}],"reward":{"xp":2468}},{"quest_id":"mdq_5","step":5,"title":"백 년 전 서식","goal":"꺼진 관아 터에서 첫 야영으로 쉰다","need":{"at":["dark_yamen"],"tasks":[{"t":"rest","r":["dark_yamen"],"n":1}]},"lines":[{"s":null,"t":"쉬고 일어났지만 하늘은 그대로였다. 아침이 오지 않았다는 것을 알면서도 몸은 아침인 줄 알았다."},{"s":null,"t":"우리는 관아 안채를 뒤졌다. 방마다 먼지가 쌓여 있었지만, 발을 디뎌도 먼지 한 톨 떠오르지 않았다."},{"s":null,"t":"맨 안쪽 방에서 청파가 무어라 외쳤지만, 세 걸음 밖이라 들리지 않았다. 청파가 문간까지 뛰어나와 팔을 휘저었다."},{"s":null,"t":"방 벽에 종이 한 장이 못에 박혀 있었다. 다른 종이는 다 바랬는데, 그 종이의 글자만은 먹빛이 짙었다."},{"s":null,"t":"그 종이는 정청 명부의 서식이었다. 칸 머리에 「이름」「난 곳」「거둘 해」가 차례로 적혀 있었다."},{"s":null,"t":"그 오른쪽에 칸이 하나 더 있던 자리는 칼로 박박 긁혀 있었다. 긁힌 자리에 「부르는」 두 글자만 희미하게 남아 있었다."},{"s":null,"t":"서식 맨 아래에 서명이 있었다. 「정리소 서리 경현, 백 년 전 동지」라고 적혀 있었다."},{"s":null,"t":"한동안 아무도 말을 하지 못했다. 맨 먼저 입을 연 것은 청파였다."},{"s":"q:sn_cheongpa","t":"경현이면… 봉인고에서 차 따라 준 그 정리관이잖아요? 같은 사람이라면, 백스무 살이 넘었다는 거잖아요!"},{"s":null,"t":"서식 바로 옆에 종이 한 장이 더 박혀 있었다. 칸마다 숫자가 빼곡했다. 서하람이 그 앞에 바짝 다가서서 손가락으로 줄을 짚어 내려갔다."},{"s":"q:r71_seoharam","t":"이건 셈표예요. 왼쪽 칸은 「봉연 수위」… 석 자 한 치, 석 자 두 치, 석 자 넷 치. 오른쪽 칸은 「거둘 수」예요. 열둘, 열다섯, 열아홉."},{"s":"q:r71_seoharam","t":"물이 한 치 오를 때마다 거둘 사람이 몇씩 늘어요. 물 높이를 재서, 그만큼 사람을 거두면 문이 안 흔들린다는 표예요."},{"s":null,"t":"셈표 맨 아래에 작은 글씨가 있었다. 「가늠 저울 셈. 짠 이 — 서리 경현」이라고 적혀 있었다."},{"s":null,"t":"셈표 아래쪽에 칸이 하나 더 있었다. 칸 머리에 「미룸」이라고 적혀 있었다."},{"s":null,"t":"그 칸에는 이름 여섯이 나란히 적혀 있었다. 이름마다 붉은 줄이 반만 그어지다 멈춰 있었다. 멈춘 자리마다 「서리」라는 작은 도장이 꾹 찍혀 있었다."},{"s":"q:r71_seoharam","t":"미룸… 붉은 줄을 미룰 수도 있다는 거네요. 긋다가 멈추는 손이 따로 있었다는 거예요. 그 손이 「서리」고요."},{"s":null,"t":"나는 흑련 장부고 금고 앞에서 주운 명부 조각을 떠올렸다. 「곽두칠」이라는 이름 위에도 붉은 줄이 반만 그어져 있었다. 나는 조각을 꺼내 미룸 칸 옆에 대 보았다."},{"s":null,"t":"줄을 긋다 멈춘 모양이 똑같았지만, 조각에는 도장이 없었다. 도장이 찍혔을 자리가 찢겨 나가 있었다."},{"s":null,"t":"나는 일행에게 조각을 주운 내력을 말했다. 흑련 금고를 턴 그림자 흐린 이들이 지나간 자리에서 주웠다고 했다. 한설의 서신에 적혀 있던 말도 덧붙였다. 조각에 적힌 곽두칠은 열 해 전 정리 명부에 올랐는데도 사라지지 않은 사람이었다."},{"s":"red_moon_cult:danbi","t":"그럼 그 사람들이 떨어뜨린 거예요? 그 사람들도… 줄이 미뤄진 사람들이에요?"},{"s":null,"t":"아무도 대답하지 못했다. 서하람이 셈표의 서명을 다시 짚었다. 손끝이 떨렸다."},{"s":"q:r71_seoharam","t":"서명만 한 게 아니에요. 이 셈을 짠 게 그 사람이에요. 해마다 몇 명을 거둘지를, 그 사람이 정했어요."},{"s":"red_moon_cult:danbi","t":"동명이인이겠죠. 적월에도… 아니, 이번엔 그 말 못 하겠네요."},{"s":null,"t":"단비가 손끝으로 서명을 짚었다. 손끝을 떼자 먹이 묻어 나올 것처럼 반들거렸다."},{"s":"red_moon_cult:danbi","t":"이 먹은 엊그제 쓴 것처럼 반들반들해요. 백 년 된 먹이 이럴 리가 없어요. 누가 이 종이를 얼마 전에 만지고 간 것 같아요."},{"s":null,"t":"여운비가 서명을 오래 들여다보았다. 칼자루를 쥔 손에 힘이 들어갔다."},{"s":"north_league:yeo","t":"그자는 봉인고에서 우리 집안 종 이야기가 제 장부 몇 쪽에 있는지까지 댔소. 맹주께서도 내게 안 하신 이야기를 말이오. 백 년 동안 장부를 읽었다면… 그럴 수도 있겠구려."},{"s":null,"t":"서식을 들여다보던 갈매의 얼굴이 하얗게 굳었다. 갈매가 서식 한 귀퉁이를 움켜쥐었다가 손을 멈추었다. 손끝이 떨리고 있었다."},{"s":"southern_remnant:galmae","t":"야, 정청. 너는 이게 뭔지 알아?","fac_not":"southern_remnant","spec":2,"grp":1},{"s":"southern_remnant:galmae","t":"야, 정청 끄나풀. 남명 끈까지 찼으면서 이게 뭔지 알아?","fac":"southern_remnant","rank":[1,2],"spec":0,"grp":1},{"s":"southern_remnant:galmae","t":"{등급}이라며. 남명 끈 찬 지 오래됐으면 이게 뭔지 알 거 아니야.","fac":"southern_remnant","rank":[3,4],"spec":0,"grp":1},{"s":"southern_remnant:galmae","t":"수호장이면 할배한테 들은 게 있을 거 아니야. 이게 뭔지 알아?","fac":"southern_remnant","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 모른다고 했다. 갈매가 서식에서 손을 떼고 벽을 주먹으로 쿵 쳤다."},{"s":"southern_remnant:galmae","t":"할배가 잔불촌에서 그랬잖아. 백 년 전 정청 서식에 남명만 서명을 안 했고, 그 뒤로 해마다 남명 백성 이름이 맨 앞줄에 올랐다고. 그 서식이 이거야?"},{"s":"southern_remnant:galmae","t":"칸이 하나 긁혀 있잖아. 그 칸이 남아 있었으면, 우리 사람들은 안 거둬졌을 거라는 거야?"},{"s":null,"t":"아무도 대답하지 못했다. 서하람이 서식의 날짜를 짚으며 중얼거렸다."},{"s":"q:r71_seoharam","t":"백 년 전 동지… 천명원 별 기록이 처음으로 비는 해예요."},{"s":null,"t":"갈매가 홱 돌아보았다. 관성대에서 서하람을 비웃던 눈빛이 아니었다. 서하람도 졸린 척하지 않고 그 눈을 마주 보았다."},{"s":"southern_remnant:galmae","t":"너네 별이 빈 해에, 우리 사람들이 거둬지기 시작했다고?"},{"s":"q:r71_seoharam","t":"…관측한 대로 말하는 거예요. 저도 왜 그런지는 몰라요. 정말이에요."},{"s":null,"t":"나는 반쪽 첫째 장을 꺼내 서식 옆에 대 보았다. 흰 불꽃이 긁힌 칸을 들여다보려는 듯이 서식 쪽으로 기울었다."},{"s":"q:r71_seoharam","t":"불꽃이… 긁힌 칸 쪽으로 기울어요. 장이 저 칸을 알아보는 것 같아요."},{"s":null,"t":"여운비가 칼자루에서 손을 내리고 벽에서 셈표를 조심스럽게 떼어 서하람에게 내밀었다."},{"s":"north_league:yeo","t":"관측관, 이걸 그대로 옮겨 적어 주시오. 숫자 하나 빠뜨리지 말고. 맹주께 보여 드려야 하오."},{"s":null,"t":"갈매가 서식 귀퉁이를 놓고, 긁힌 칸을 엄지손톱으로 한 번 쓸었다."},{"s":"southern_remnant:galmae","t":"서식도 베껴. 할배한테 이 긁힌 칸을 보여 줄 거야. 백 년 동안 누가 우리 사람들을 맨 앞줄에 올렸는지, 이 서명 들고 가서 따질 거야."},{"s":null,"t":"단비가 서하람 곁에 쪼그려 앉아 두루마리 끝을 잡아 주었다. 바로 뒤에 선 여운비와 어깨가 닿았지만 둘 다 비키지 않았다."},{"s":"red_moon_cult:danbi","t":"저도 한 장 더 베껴 주세요, 관측관님. 교주님께 가져갈 거예요. 제 말만으로는 안 믿으실 거거든요."},{"s":null,"t":"그때 안마당 쪽에서 철퍽, 하고 젖은 것이 돌바닥을 치는 소리가 났다. 소리가 들렸다는 것은 이미 세 걸음 안이라는 뜻이었다."},{"s":"southern_remnant:galmae","t":"엎드려!"}],"reward":{"xp":2468}},{"quest_id":"mdq_5","step":6,"title":"부르다 굳은 것","goal":"꺼진 관아 터에서 부르다 굳은 넋을 5번 풀어 보낸다","need":{"at":["dark_yamen"],"tasks":[{"t":"win","n":5,"m":["dd_yamen_1"]}]},"lines":[{"s":null,"t":"안마당에 먹을 뒤집어쓴 것들이 엉금엉금 기어들어 와 있었다. 사람 모양 같기도 하고 등롱 모양 같기도 했다."},{"s":null,"t":"그것들은 하얗게 바랜 얼굴로 입을 크게 벌렸다. 누군가를 부르는 입 모양이었다. 소리는 나오지 않고, 입만 같은 모양으로 열렸다 닫혔다."},{"s":null,"t":"흑련 장부고 계단과 적사 황무지 길목에서 쓰러뜨린 하얀 넋과 똑같은 얼굴이었다. 바깥 고을 우물마다 먹물을 타고 기어 나오던 것들이 이 흰 밤의 땅에서 왔다는 것을, 나는 그제야 알았다."},{"s":null,"t":"맨 앞의 것이 갈매에게 휘익 달려들었다. 갈매가 칼을 휘둘러 쳐 냈다. 먹이 철퍽 튀어 갈매의 뺨에 묻었다."},{"s":null,"t":"또 하나가 서하람의 등 뒤로 기어들었다. 갈매가 몸을 날려 서하람의 어깨를 움켜쥐고 제 뒤로 확 잡아끌었다."},{"s":"southern_remnant:galmae","t":"잠꾸러기는 뒤에 있어! 거기서 졸면 진짜 죽는다!"},{"s":"q:r71_seoharam","t":"안 졸아요! 왼쪽이요, 왼쪽에 둘 더!"},{"s":null,"t":"여운비와 단비가 저도 모르게 등을 맞대고 섰다. 여운비의 칼이 앞을 베는 사이 단비의 방울이 뒤를 쫓았다. 방울 소리가 세 걸음 안에서만 쨍쨍 울렸다."},{"s":null,"t":"나는 {직업:호위=방패를 들어 청파 앞을 막고 달려드는 것을 밀어냈다/월궁=시위를 당겨 청파를 노리던 것의 이마를 꿰뚫었다/퇴마=부적을 날려 청파에게 덤비던 것을 태웠다/의무=청파를 끌어당기며 부채로 그것의 손을 후려쳤다/봉인=봉인 부적을 바닥에 붙여 청파 앞을 가로막았다/암영=그림자처럼 파고들어 청파를 노리던 것의 등을 베었다/조련=휘파람을 불어 동무를 앞세우고 청파를 노리던 것에 화살을 박았다/*=청파를 노리던 것을 막아 쓰러뜨렸다}. 청파가 숨을 헉 들이켰다."},{"s":"q:sn_cheongpa","t":"고, 고마워요! {이름} 님 없었으면 저 지금쯤 먹 됐어요!"},{"s":null,"t":"쓰러진 것들은 몸에서 먹을 흘렸다. 먹은 돌바닥 틈으로 스르르 스며들었고, 먹이 빠진 자리마다 바랜 등롱 종이가 한 장씩 남았다."},{"s":null,"t":"단비가 방울을 내렸다. 장터에서 아이들 부적을 태워 줄 때와는 전혀 다른 얼굴이었다."},{"s":"red_moon_cult:danbi","t":"저건 요괴가 아니에요. 적월 축문으로도 안 잡혀요. 누군가를 부르다가 끝까지 못 부르고, 그대로 굳어 버린 거예요."},{"s":"southern_remnant:galmae","t":"사람이었다는 거야? 저게?"},{"s":"red_moon_cult:danbi","t":"네. 차라리 쓰러뜨려 주는 게 나아요. 그대로 두면 영영 그 입 모양으로 서 있을 테니까요."},{"s":null,"t":"갈매가 칼끝을 내렸다. 뺨에 묻은 먹을 손등으로 닦던 갈매가 그 손등을 한참 내려다보았다."},{"s":null,"t":"청파가 아무 말 없이 바닥의 종이를 한 장씩 주웠다. 다 모은 종이는 기름종이로 싸서 품에 넣었다."},{"s":"q:sn_cheongpa","t":"나중에는 읽을 수 있게 될지도 모르잖아요. 그때까지 제가 갖고 있을게요. 문패 건질 때도 그렇게 해요. 이름은 젖으면 안 되니까."},{"s":null,"t":"서하람이 청파의 품을 가만히 보다가 두루마리 끝에 종이 장수를 적었다. 「열한 장」이라고 적은 글씨가 조금 떨렸다."},{"s":null,"t":"여운비는 안마당 끝 돌계단에 올라 북쪽을 보고 있었다. 흰 도성 너머 북쪽 구역에 높은 종루 하나가 솟아 있었다."},{"s":"north_league:yeo","t":"저 종루는 북령 고찰 종루와 생김새가 같소. 북령 무관들이 살던 구역일 거요."},{"s":"north_league:yeo","t":"먹 묻은 것들도 그쪽에서 내려왔소. 다 같이 가기 전에 내가 먼저 길을 보고 오겠소. 길잡이는 내 일이오."},{"s":"red_moon_cult:danbi","t":"혼자요? 세 걸음만 떨어져도 소리가 안 가는데요?"},{"s":"north_league:yeo","t":"…그럼 누가 같이 가 주시오."},{"s":null,"t":"여운비가 그렇게 말하며 나를 보았다. 내가 고개를 끄덕이자 여운비가 짧게 숨을 내쉬었다."}],"reward":{"xp":2468}},{"quest_id":"mdq_5","step":7,"title":"다섯의 저녁","goal":"꺼진 관아 터로 원정을 한 번 끝까지 다녀와 북쪽 길을 살핀다","need":{"at":["dark_yamen"],"tasks":[{"t":"expedition","r":["dark_yamen"],"n":1}]},"lines":[{"s":null,"t":"북쪽 길은 끝없이 하얬다. 해가 움직이지 않으니, 얼마나 걸었는지는 발바닥이 욱신거리는 것으로만 헤아렸다."},{"s":null,"t":"무너진 다리 하나를 건널 때였다. 앞서 건너간 여운비가 돌아서서 내게 손을 내밀었다."},{"s":"north_league:yeo","t":"잡으시오. 여기서 떨어지면 소리를 질러도 아무도 못 듣소."},{"s":null,"t":"나는 그 손을 잡고 건넜다. 여운비의 손은 굳은살이 단단했다. 다 건넌 뒤에도 여운비는 손을 바로 놓지 않았다."},{"s":"north_league:yeo","t":"…손이 차구려. 이 땅에선 손을 자주 비비시오."},{"s":null,"t":"관아로 돌아오자 안마당에 불이 피어 있었다. 불가에 둘러앉은 거리가 어젯밤보다 한 뼘씩 가까웠다."},{"s":null,"t":"서하람이 하품을 하다 말고 단비의 엿 꾸러미로 손을 뻗었다. 단비가 웃으며 꾸러미를 내밀었다."},{"s":"red_moon_cult:danbi","t":"하나에 축문 한 줄이에요, 관측관님."},{"s":"q:r71_seoharam","t":"아… 그럼 외상으로 할게요… 별이 생기면 갚을게요."},{"s":"red_moon_cult:danbi","t":"여기 별 없잖아요. 영영 안 갚겠다는 거죠?"},{"s":null,"t":"서하람은 대답 대신 엿을 하나 더 집었다. 단비가 깔깔 웃으며 꾸러미를 서하람 무릎에 통째로 올려 주었다."},{"s":null,"t":"갈매는 여전히 내 쪽을 잘 보지 않았지만, 나무 그릇에 국을 떠서 말없이 내 앞에 내려놓았다."},{"s":null,"t":"갈매가 내려놓은 국에서는 김이 오르지 않았다. 그래도 그릇을 쥐자 손바닥이 따뜻했다."},{"s":"southern_remnant:galmae","t":"…먹어. 여기 국은 안 식는다지만."},{"s":"q:sn_cheongpa","t":"갈매 누님이 국 떠 주는 거 처음 봐요. 저도 떠 주세요."},{"s":"southern_remnant:galmae","t":"넌 네가 떠."},{"s":null,"t":"청파는 투덜대면서도 갈매 옆에 바짝 붙어 앉았다. 갈매는 밀어내지 않았다."},{"s":null,"t":"서하람이 엿을 오물거리다 말고 나를 보았다. 무릎 위 두루마리에는 낮에 본 먹 묻은 것들의 입 모양이 그려져 있었다."},{"s":"q:r71_seoharam","t":"{이름} 님은 묵창 나루에 있었다면서요. 거기서도 저런 걸 봤어요? 먹 뒤집어쓰고, 누구를 부르는 것 같은 거요."},{"s":null,"t":"나는 묵창 나루의 먹귀 이야기를 했다. 거둬진 사람을 마지막까지 붙든 기억이 먹을 뒤집어쓰고 떠돌던 것이라고 했다."},{"s":null,"t":"아홉 칸 뜰의 봉인진 이야기도 했다. 나는 그 진 안에서 먹귀들을 풀어 보냈고, 풀어 보낸 이들의 기억을 잃었다고 했다."},{"s":"red_moon_cult:danbi","t":"잃었어요? {이름} 님이 그 사람들을 기억 못 한다는 거예요?"},{"s":null,"t":"나는 고개를 끄덕였다. 정청 기록에는 내가 「빈 고리」로 적혀 있다는 것도 말했다. 이름을 한 번 잃었다가 다시 묶인 사람을 그렇게 적는다고 했다. 단비가 엿 꾸러미를 꼭 쥐었다."},{"s":"q:r71_seoharam","t":"관성대에서 들었어요. 귀허의 주인을 쓰러뜨린 조사원이 정청에 있다고요. 그게 {이름} 님이죠? 그 소용돌이 안에서 도는 것들도… 어디로도 못 가고 걸린 이름이라고 들었어요. 먹귀도, 저 먹 묻은 것들도, 다 같은 데서 온 걸까요?"},{"s":null,"t":"나는 귀허의 주인과 싸우던 밤을 떠올렸다. 소용돌이 속에서 돌던 것들도 누군가를 부르는 입 모양이었다. 나는 서하람에게 그럴지도 모른다고 했다."},{"s":"q:r71_seoharam","t":"…관측만 할게요. 아직은 예언 안 해요. 근데 다 같은 데로 흘러가다 걸린 것 같아요."},{"s":"southern_remnant:galmae","t":"귀허 주인을 네가 쓰러뜨렸다고? 그 섬 놈을?"},{"s":null,"t":"갈매가 나를 위아래로 다시 훑어보았다. 재의 해안에서 내 허리춤 정청 패를 노려보던 눈이 아니었다. 갈매는 한참 만에 콧방귀를 뀌고 돌아앉았다."},{"s":"southern_remnant:galmae","t":"…정청치고는 쓸 만하네."},{"s":null,"t":"불 건너편에서 여운비가 칼을 닦고 있었다. 다 닦은 칼을 무릎에 눕힌 여운비가 붉은 술을 손가락으로 털어 보았다. 술은 털린 모양 그대로 멈췄다가 천천히 늘어졌다."},{"s":null,"t":"내가 곁으로 가 앉았다. 여운비는 내가 자리를 잡을 때까지 기다렸다가 입을 열었다."},{"s":"north_league:yeo","t":"오늘 본 종루는 북령 종루와 똑같았소. 북령에서는 종루를 아무나 못 오르오. 우리 집안이 대대로 그 열쇠를 지켜 왔소.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:yeo","t":"당신도 북령 사람이니 고찰 종루를 보았겠지. 오늘 본 종루가 그것과 똑같았소. 그 종루 열쇠를 대대로 지켜 온 게 우리 집안이오.","fac":"north_league","spec":1,"grp":1},{"s":"north_league:yeo","t":"장로님도 고찰 종루를 아시지요. 오늘 본 종루가 그것과 똑같았소. 그 종루 열쇠를 대대로 지켜 온 게 우리 집안이오.","fac":"north_league","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 왜 그 열쇠를 지키는지 물었다. 여운비가 칼날을 흰 하늘에 비추어 보았다. 바람이 없으니 칼날은 조금도 떨리지 않았다."},{"s":"north_league:yeo","t":"그건 나도 모르오. 아무도 가르쳐 주지 않았소. …내일 저기 가 보면 알게 될 것 같소."},{"s":"north_league:yeo","t":"앞장은 내가 서겠소. 조사원은 내 뒤에서 세 걸음 안에만 있으시오. 그래야 내 말이 들리니."}],"reward":{"xp":2468,"gil":470,"items":{"century_form_scrap":2,"bleached_lantern_paper":2}}},{"quest_id":"mdq_6","step":1,"title":"늘어진 술","goal":"꺼진 관아 터에서 쉬고 무관 거리에 도착해 늘어진 술을 본다","need":{"at":["martial_row"],"tasks":[{"t":"rest","r":["dark_yamen"],"n":1},{"t":"travel","r":["martial_row"],"n":1}]},"lines":[{"s":null,"t":"관아 터에서 북쪽으로 반나절을 걸었다. 앞장선 여운비는 갈림길이 나올 때마다 멈춰 서서 칼자루를 들어 올렸다."},{"s":null,"t":"붉은 술은 매번 곧게 아래로 늘어져 있었다. 바람이 없다는 것을 알면서도 여운비는 그 버릇을 끊지 못했다."},{"s":null,"t":"세 번째 갈림길에서 단비가 여운비 옆으로 쪼르르 다가갔다."},{"s":"red_moon_cult:danbi","t":"대장님, 술이 오늘도 낮잠 자네요. 제가 후 불어 드릴까요?"},{"s":"north_league:yeo","t":"…필요 없소."},{"s":null,"t":"단비가 정말로 볼을 부풀려 술에 후, 하고 입김을 불었다. 술 끝이 살랑 흔들렸다. 여운비가 술과 단비를 번갈아 보았다."},{"s":"red_moon_cult:danbi","t":"거 봐요, 바람 났네. 이쪽이래요."},{"s":null,"t":"여운비는 대꾸하지 않고 단비가 가리킨 반대쪽으로 걸었다. 단비가 킥킥 웃으며 그 뒤를 따랐다."},{"s":null,"t":"네 번째 갈림길에서 여운비는 칼자루를 들어 올리려다 말고, 술을 주먹에 꽉 쥐어 버렸다."},{"s":null,"t":"무관 거리 어귀에 들어서자 발밑부터 달라졌다. 돌바닥 틈마다 서리가 하얗게 끼어 있었다."},{"s":null,"t":"공기는 조금도 차갑지 않은데 서리는 녹을 기미가 없었다. 청파가 쪼그려 앉아 서리를 손톱으로 긁어 보았다. 서리는 돌처럼 단단했다."},{"s":"q:sn_cheongpa","t":"안 녹아요. 손을 대고 있어도 안 녹아요."},{"s":"q:r71_seoharam","t":"그날 밤 추위가… 그대로 땅에 붙어 있는 거예요. 시간이 안 흘렀으니까요."},{"s":null,"t":"거리 한가운데에 넓은 연무장이 있었다. 마당에는 짚으로 엮은 목인이 줄지어 서 있었고, 목인마다 화살이 한 대씩 꽂혀 있었다."},{"s":null,"t":"그중 몇 대는 꽂혀 있지 않았다. 목인 가슴께에서 한 뼘 앞, 허공에 멈춰 있었다."},{"s":null,"t":"나는 가장 가까운 화살 앞으로 다가갔다. 화살은 시위를 떠난 그대로 살짝 기울어 있었다. 깃은 날아가던 모양으로 눌린 채 한 올도 떨리지 않았다."},{"s":null,"t":"촉 끝에는 서리가 하얗게 앉아 있었다. 화살 아래 돌바닥에는 그림자가 없었다."},{"s":null,"t":"갈매가 화살대를 손바닥으로 밀어 보았는데, 꿈쩍도 하지 않았다. 갈매가 이를 악물고 어깨로 밀었지만, 화살은 바위에 박힌 쇠말뚝 같았다."},{"s":"southern_remnant:galmae","t":"뭐야, 이거. 허공에 박혔어."},{"s":null,"t":"청파가 호기심을 못 이기고 손가락으로 촉 끝을 톡 건드렸다. 다음 순간 청파가 「앗, 차가워!」 하고 손을 홱 뺐다."},{"s":null,"t":"청파의 손끝이 하얗게 바래 있었다. 손끝이 저린지 청파가 손을 덜덜 털었다."},{"s":"red_moon_cult:danbi","t":"막내는 왜 자꾸 아무거나 만져요! 손 이리 줘요."},{"s":null,"t":"단비가 청파의 손끝을 제 손바닥으로 감싸고 호호 불었다. 하얗게 바랬던 손끝에 천천히 핏기가 돌아왔다."},{"s":"q:sn_cheongpa","t":"일흔 해 동안 날아가는 중인 화살이라니… 무서운데, 좀 멋있어요."},{"s":null,"t":"여운비가 멈춘 화살 하나 앞에 서서 화살대를 잡으려고 손을 뻗었지만, 손은 화살 한 치 앞에서 멈췄다. 여운비는 손을 거두고 목인 가슴께의 글씨를 엄지로 문질렀다."},{"s":null,"t":"목인마다 무언가 새겨져 있었는데, 하나같이 하얗게 바래 읽을 수 없었다."},{"s":"red_moon_cult:danbi","t":"대장님, 그게 뭐예요? 목인에다 글씨를 왜 새겨요?"},{"s":"north_league:yeo","t":"북령 무관은 처음 활을 잡는 날 연무장 목인에 제 이름을 새기오. 쏘는 화살이 제 이름을 꿰뚫지 않게 하라는 뜻이오.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:yeo","t":"당신도 고찰 연무장에서 목인에 이름을 새겼겠지. 여기 무관들도 그랬던 거요. 쏘는 화살이 제 이름을 꿰뚫지 않게.","fac":"north_league","spec":1,"grp":1},{"s":"north_league:yeo","t":"장로님도 처음 활을 잡던 날 목인에 이름을 새기셨겠지요. 여기 무관들도 그랬던 거요. 쏘는 화살이 제 이름을 꿰뚫지 않게.","fac":"north_league","rank":[5,5],"spec":0,"grp":1},{"s":"north_league:yeo","t":"우리 집안 목인 줄에는 이름 없는 목인이 하나 끼어 있소. 어릴 때는 새로 깎아 두고 아직 안 새긴 건 줄 알았소."},{"s":null,"t":"여운비가 말을 멈추고 목인들을 둘러보았다. 이름이 바랜 목인이 서른 개가 넘었다."},{"s":null,"t":"갈매가 연무장 구석 우물 쪽을 보고 걸음을 멈췄다. 우물 돌테 둘레에 젖은 발자국이 찍혀 있었다. 발자국마다 먹이 고여 번들거렸다."},{"s":"southern_remnant:galmae","t":"야. 이거 봐. 잔불촌 화로 뒤 도랑에 찍혀 있던 거랑 똑같아. 젖은 먹 발자국."},{"s":"q:sn_cheongpa","t":"여긴 비도 안 오는데 젖어 있어요… 방금 지나간 거예요."},{"s":"north_league:yeo","t":"우리 말고 누가 이 거리에 있다는 얘기요. 거리를 끝까지 훑어서 그자를 찾읍시다."},{"s":null,"t":"흰 거리 곳곳에서 먹 묻은 것들이 기어 나올 터였다. 우리는 칼과 방울을 손에 쥔 채 연무장을 나섰다."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":2,"title":"우물가의 그림자","goal":"무관 거리를 4번 탐색하고 요괴를 3번 쓰러뜨린다","need":{"at":["martial_row"],"tasks":[{"t":"search","r":["martial_row"],"n":4},{"t":"win","n":3,"r":["martial_row"]}]},"lines":[{"s":null,"t":"거리를 세 번째로 훑을 때였다. 무너진 담장 위에서 누군가 우리를 내려다보고 있었다. 세 걸음 밖이라 발소리는 들리지 않았다."},{"s":null,"t":"그는 회색 두건을 쓴 사람이었다. 흰 땅에서는 아무에게도 그림자가 없었는데, 그 사람 발밑에만 먹물 같은 얼룩이 반쯤 흐릿하게 고여 있었다."},{"s":null,"t":"내가 손을 들어 가리키자 그 사람이 담장 뒤로 홱 사라졌다."},{"s":"southern_remnant:galmae","t":"저놈이다! 서!"},{"s":null,"t":"갈매가 먼저 튀어 나갔다. 여운비가 그 뒤를 바짝 쫓았다. 나도 세 걸음을 넘지 않으려고 이를 악물고 달렸다."},{"s":null,"t":"두건 쓴 사람은 연무장 우물 쪽으로 달렸다. 갈매가 몸을 날려 그 사람의 허리를 덮쳤다. 둘이 엉켜 우물 돌테에 쿵 부딪혔다."},{"s":null,"t":"그 사람의 몸이 먹물처럼 미끄러졌다. 갈매의 팔 사이로 쑥 빠져나간 몸이 반쯤 우물 속으로 꺼져 들어갔다."},{"s":"southern_remnant:galmae","t":"이게 왜 미끄러워! 잡아! 누가 좀 잡아!"},{"s":null,"t":"여운비가 그 사람의 팔목을 움켜쥐었지만, 팔목도 손안에서 주르륵 빠져나갔다."},{"s":null,"t":"뒤따라온 청파가 허리에 감고 다니던 밧줄을 휙 던졌다. 밧줄이 그 사람의 어깨에 칭칭 감겼다. 청파가 밧줄 끝을 제 팔뚝에 감고 뒤로 버텼다."},{"s":"q:sn_cheongpa","t":"잡았어요! 물에 빠진 사람 건질 때 이렇게 해요! 다들 줄 잡아요!"},{"s":null,"t":"단비와 서하람이 달려와 청파 뒤에서 밧줄을 함께 붙들었다. 나는 우물 돌테에 발을 걸고 그 사람의 옷깃을 움켜잡았다."},{"s":null,"t":"끌려 올라온 그 사람은 돌바닥에 엎드려 덜덜 떨었다. 손끝이 먹빛이었다. 몸에서 젖은 먹 냄새가 났다."},{"s":"southern_remnant:galmae","t":"누가 보냈어. 우리 뒤를 왜 밟아!"},{"s":null,"t":"그 사람은 대답 대신 두 손을 모아 싹싹 빌었다. 목소리가 쉬어 있었다."},{"s":"q:md_hooded","t":"놓아 주세요. 제발 놓아 주세요. 제가 돌아가지 않으면… 그분이 제 줄을 마저 그으세요. 그러면 저는 사흘이면 죽습니다."},{"s":"q:r71_seoharam","t":"줄이요? 붉은 줄이요? 관아 셈표의 미룸 칸처럼요?"},{"s":null,"t":"그 사람이 흠칫 서하람을 올려다보았지만, 대답하지 않고 입술만 바들바들 떨었다."},{"s":"north_league:yeo","t":"누구의 줄이오. 그 줄을 쥔 사람의 이름을 대시오."},{"s":"q:md_hooded","t":"못 합니다. 그 이름을 대면 저는 사흘도 안 걸립니다. 그 자리에서 풀립니다."},{"s":null,"t":"단비가 그 사람 앞에 쪼그려 앉았다. 웃지 않는 얼굴이었다."},{"s":"red_moon_cult:danbi","t":"이름이 뭐예요? 당신 이름이요. 우리가 불러 줄게요. 그럼 덜 무섭잖아요."},{"s":null,"t":"그 사람이 단비를 한참 보았다. 눈에 물기가 고였다. 입이 열렸다가 다시 닫혔다."},{"s":"q:md_hooded","t":"…제 이름은, 이제 제 것이 아니에요."},{"s":null,"t":"그 말과 함께 그 사람의 몸이 다시 먹물처럼 녹았다. 밧줄이 텅 빈 옷 사이로 스르르 빠졌다. 그 사람은 우물 돌테 틈으로 주르륵 흘러내려 사라졌다."},{"s":null,"t":"밧줄 끝에는 겉옷 한 자락만 걸려 있었다. 내가 그것을 뒤집어 보았다. 소매 안감이 짙은 남빛 비단이었다."},{"s":null,"t":"그 남빛 비단은 정청 관복 안감에 쓰는 천이었다. 내 옷깃 안쪽에 덧댄 천과 결까지 같았다."},{"s":"southern_remnant:galmae","t":"정청 놈이야. 정청 놈이 우물로 다녀."},{"s":"q:sn_cheongpa","t":"아까 그 사람… 엄청 무서워하던데요. 우리 말고, 다른 누구를요."},{"s":null,"t":"여운비가 우물 속을 한참 내려다보았다. 우물 바닥에서 먹물 흐르는 소리가 아주 멀리 졸졸 들렸다."},{"s":"north_league:yeo","t":"우물 밑으로 길이 있는 모양이오. 따라 내려갈 수는 없소. 이 거리를 마저 봅시다. 무기고가 있을 거요. 북령 무관 거리면 연무장 곁에 늘 무기고를 두니까."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":3,"title":"시위를 메기는 법","goal":"무관 거리를 3번 탐색해 무기고를 찾는다","need":{"at":["martial_row"],"tasks":[{"t":"search","r":["martial_row"],"n":3}]},"lines":[{"s":null,"t":"연무장 뒤편에서 무너진 무기고를 찾았다. 선반 위에 활 여러 자루가 시위가 풀린 채 누워 있었다."},{"s":null,"t":"여운비가 그중 하나를 집어 들었다. 그것은 물소 뿔과 나무를 겹겹이 붙인 북령 뿔활이었다. 색은 바랬지만 활채는 조금도 상하지 않았다."},{"s":"north_league:yeo","t":"시위를 걸어 둔 채로 일흔 해를 뒀으면 부러졌을 거요. 풀어 둔 걸 보니, 여기 사람들은 돌아올 생각이었던 모양이오."},{"s":null,"t":"여운비가 활을 내게 내밀었다."},{"s":"north_league:yeo","t":"{직업:월궁=당신 활 솜씨는 아오. 그래도 북령 뿔활은 다르오. 거꾸로 휘어 있어서 혼자서는 못 메기오/조련=당신도 활을 쓰는 건 아오. 그래도 북령 뿔활은 다르오. 거꾸로 휘어 있어서 혼자서는 못 메기오/*=한번 메겨 보시오. 북령 뿔활은 거꾸로 휘어 있어서, 메기는 법을 모르면 혼자서는 못 하오}."},{"s":null,"t":"나는 활채를 무릎에 걸고 힘을 주었다. 활이 내 손을 튕겨 내며 휙 원래 모양으로 돌아갔다."},{"s":null,"t":"갈매가 풉 하고 웃음을 터뜨렸다."},{"s":"southern_remnant:galmae","t":"정청이 활한테 졌다."},{"s":"north_league:yeo","t":"무릎이 아니오. 발이오. 발로 아래 고자를 밟고, 등으로 위를 눌러야 하오."},{"s":null,"t":"여운비가 내 뒤로 와서 내 발 자리를 제 발로 툭툭 고쳐 주고는, 내 손 위에 제 손을 얹어 활채를 함께 눌렀다."},{"s":"north_league:yeo","t":"숨을 내쉬면서. 지금이오. 시위 고리를 고자에 거시오."},{"s":null,"t":"찰칵, 하고 고리가 걸렸다. 시위가 팽팽해지자 활이 손안에서 웅, 하고 낮게 울었다."},{"s":"red_moon_cult:danbi","t":"대장님, 가르칠 때는 목소리가 한 뼘 내려가네요. 저도 가르쳐 주세요. 저도 그 목소리로요."},{"s":"north_league:yeo","t":"무녀는 방울이나 흔드시오."},{"s":"red_moon_cult:danbi","t":"방울도 메기는 법이 있는데. 제가 대장님한테 가르쳐 드릴까요?"},{"s":null,"t":"여운비가 귀 끝까지 빨개진 채 홱 돌아섰다. 청파가 그 틈에 바닥에 떨어진 화살들을 한 아름 주워 왔다. 멈춘 화살이 아니라 땅에 떨어져 있던 것들이었다."},{"s":"q:sn_cheongpa","t":"이것들은 멀쩡해요! 촉도 안 녹슬었어요. {이름} 님 짐에 넣어 드릴까요? 혹시 모르잖아요."},{"s":null,"t":"갈매는 다른 뿔활을 집어 혼자 메겨 보려다 활채에 손등을 철썩 맞았다. 갈매가 이를 갈며 활을 선반에 내던졌다."},{"s":"southern_remnant:galmae","t":"남명은 칼이면 돼. 이딴 건 안 써."},{"s":"q:sn_cheongpa","t":"누님, 손등 빨개졌어요. 호 해 드릴까요?"},{"s":"southern_remnant:galmae","t":"꺼져, 꼬맹이."},{"s":"red_moon_cult:danbi","t":"어머, 막내 둘이 또 싸우네요."},{"s":null,"t":"갈매가 홱 고개를 돌렸다. 눈빛이 이상하게 날카로웠다. 잔불촌에서 장무현이 갈매를 「마지막 아이」라고 불렀을 때와 같은 눈빛이었다."},{"s":"southern_remnant:galmae","t":"누가 막내야. 나 막내 아니야. 그런 말 하지 마."},{"s":null,"t":"단비가 눈을 끔뻑이다가 두 손을 들어 보였다. 갈매는 그 뒤로 한참 말이 없었다. 청파가 갈매 눈치를 보며 화살을 조용히 내 짐에 넣었다."},{"s":null,"t":"그사이 서하람은 무기고 밖에서 종루를 올려다보고 있었다. 서하람은 실 끝에 돌을 매달아 눈앞에 늘어뜨리고, 손가락 마디로 종루 꼭대기까지를 재었다."},{"s":"q:r71_seoharam","t":"그림자가 없어서 그림자로는 못 재요. 그래서 각도로 쟀어요. 꼭대기까지 열네 길쯤이에요. 다른 집보다 두 길 높아요."},{"s":null,"t":"여운비가 종루로 걸어가 문을 밀었다. 안쪽 계단이 중간에서 뚝 끊겨 있었다. 디딤판 몇 장이 썩어 내려앉아 위로 가는 길이 휑하게 비어 있었다."},{"s":null,"t":"일흔 해 서리를 맞은 계단이라 여느 나무로는 버티지 못할 것 같았고, 청파는 영사 실로 결을 묶은 강화 부적목이라야 디딤판으로 쓸 수 있다고 했다."},{"s":"red_moon_cult:danbi","t":"대장님, 꼭 올라가야 해요? 저 위에 뭐가 있는데요?"},{"s":"north_league:yeo","t":"북령 종지기는 종을 치기 전에 마지막 말을 종 들보에 끼워 두오. 그게 북령 종루의 법이오. 여기서 종이 울렸다면, 친 사람의 말이 저 위에 남아 있을 거요."},{"s":"north_league:yeo","t":"우리 집안이 왜 종루 열쇠를 지켜 왔는지, 그걸 보면 알 것 같소."},{"s":"q:sn_cheongpa","t":"계단은 제가 고칠 수 있어요. 거룻배보다 쉬워요. 나무랑 밧줄만 있으면요."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":4,"title":"녹아내린 종채","goal":"무관 거리에서 5번 채집하고 강화 부적목 4개를 만들어 계단 디딤판으로 청파에게 넘긴다","need":{"at":["martial_row"],"tasks":[{"t":"gather","n":5,"r":["martial_row"]},{"t":"craft","items":["reinforced_lumber"],"n":4}],"give":{"reinforced_lumber":4}},"lines":[{"s":null,"t":"강화 부적목으로 짠 디딤판을 끼우자 계단이 다시 이어졌다. 청파가 한 칸씩 밟아 보며 「됐어요!」 하고 엄지를 세웠다."},{"s":null,"t":"계단은 좁고 가팔랐다. 디딤판을 밟을 때마다 끼익 소리가 났지만, 그 소리는 발밑에서만 맴돌았다."},{"s":null,"t":"우리는 세 걸음 넘게 떨어지지 않으려고 줄지어 올랐다. 여운비가 맨 앞, 내가 그 뒤였다."},{"s":null,"t":"중간쯤에서 서하람의 발이 미끄러졌다. 바로 뒤에 있던 갈매가 서하람의 허리띠를 콱 움켜잡았다."},{"s":"southern_remnant:galmae","t":"졸지 말라고 했지!"},{"s":"q:r71_seoharam","t":"안 졸았어요… 다리가 짧아서 그래요."},{"s":null,"t":"꼭대기에 종은 없었고, 종을 매달던 굵은 들보만 텅 빈 채 걸려 있었다."},{"s":null,"t":"나는 텅 빈 들보를 올려다보았다. 홍인사 때 소이 무녀가 들려준 옛이야기가 떠올랐다. 이름 없는 종을 처음 울린 자는 북쪽에서 내려온 관리였다는 이야기였다."},{"s":null,"t":"소등 뒤 정청은 그 종을 남녘 주혈 광산 깊은 갱도에 매달았다. 종은 그 뒤 구중 봉연 첫 문 앞까지 끌려갔다. 나는 그 끌린 자국을 따라 땅 밑까지 쫓아간 적이 있었다."},{"s":null,"t":"여운비가 발돋움을 해 들보 아래쪽을 손으로 더듬었다. 들보 가운데에 손가락 두 마디 깊이의 홈이 파여 있었다."},{"s":null,"t":"홈 안은 비어 있었고, 삭은 끈 매듭 하나만 홈 가장자리에 걸려 대롱거렸다."},{"s":"north_league:yeo","t":"…없소. 마지막 말을 끼워 두는 자리요. 여기 무언가 있었는데, 누가 빼 갔소."},{"s":"q:r71_seoharam","t":"홈 둘레에 먼지가 고르게 앉았어요. 엊그제 빼 간 게 아니에요. 아주 오래전에… 끈을 풀고 조심스럽게 빼 간 거예요."},{"s":null,"t":"여운비가 빈 홈에서 손을 떼지 못했다. 단비가 그 등 뒤에서 무어라 말하려다 입을 다물었다."},{"s":null,"t":"들보 아래 바닥에는 검은 얼룩이 크게 번져 있었다. 얼룩 한가운데에 손바닥 자국 둘이 찍혀 있었다."},{"s":null,"t":"자국 속 손가락은 안쪽으로 오그라들어 있었다. 뜨거운 무언가를 끝까지 놓지 않고 움켜쥔 손이 바닥에 눌어붙었다 떨어진 자국이었다."},{"s":null,"t":"여운비가 그 자리에 무릎을 꿇었다. 여운비는 손바닥 자국 위에 제 손을 가만히 겹쳐 보았다. 여운비의 손이 자국보다 조금 작았다."},{"s":"red_moon_cult:danbi","t":"…종채는요? 종을 친 사람이 손에 쥐고 있었을 거잖아요."},{"s":null,"t":"단비의 말에 모두가 바닥을 살폈지만, 종채 나무 자루는 흔적도 없었다."},{"s":"q:sn_cheongpa","t":"종채가 다 녹았나 봐요. 쥔 손까지 데면서… 여기 손 녹은 자국이 있잖아요."},{"s":"q:r71_seoharam","t":"쇠는 안 녹아요. 종채 끝에는 쇠머리가 달려 있었을 거예요. 이 높이에서 떨어졌으면… 저쪽으로 굴렀을 거예요."},{"s":null,"t":"서하람이 바닥 기울기를 손바닥으로 재더니 들보 기둥 쪽을 가리켰다. 기둥과 바닥 사이에 손바닥 하나 들어갈 틈이 벌어져 있었다."},{"s":null,"t":"갈매가 틈에 팔을 넣어 보았지만 어깨가 걸렸다. 청파가 「제 팔이 가늘어요!」 하며 엎드렸다."},{"s":"southern_remnant:galmae","t":"빠지면 안 된다. 내가 발목 잡고 있을게."},{"s":null,"t":"갈매가 청파의 발목을 두 손으로 꽉 잡았다. 청파가 틈 속으로 팔을 어깨까지 밀어 넣었다. 단비가 그 옆에 엎드려 등잔 불빛을 틈 안으로 비춰 주었다."},{"s":"q:sn_cheongpa","t":"뭐가 걸려요… 딱딱하고, 차가운 게… 잡았다!"},{"s":null,"t":"청파가 끄집어낸 것은 주먹만 한 쇠붙이, 종채 끝에 달려 있던 쇠머리였다. 둘레에 먹이 엉겨 돌처럼 굳어 있었다."},{"s":null,"t":"나는 쇠머리를 받아 여운비 손에 쥐여 주었다. 여운비가 그것을 두 손으로 감싸 쥐었다. 손가락이 하얘지도록 쥐고 있었다."},{"s":null,"t":"갈매가 여운비 손안의 쇠머리를 들여다보았다. 먹 껍질 아래로 무언가 긁힌 자국이 비쳤다."},{"s":"southern_remnant:galmae","t":"이 밑에 뭐가 새겨져 있어. 근데 먹이 쇠처럼 굳었어. 칼로 긁다간 글씨까지 다 날아가겠다."},{"s":"north_league:yeo","t":"…벗겨 봐야겠소. 마지막 말이 들보에 없으면, 여기 있을지도 모르오."},{"s":"q:r71_seoharam","t":"먹을 녹이는 풀물이랑 가는 끌이 있으면 돼요. 관성대에서 옛 석판 닦을 때 그렇게 해요."},{"s":"southern_remnant:galmae","t":"끌은 정청이 만들어. 손재주는 정청이 낫잖아. 긁는 건 내가 할게. 칼 쥐는 손이 제일 안 떨려."},{"s":null,"t":"대장간 장비 수리 도구 꾸러미에는 쇠붙이 녹을 긁어내는 가는 끌이 들어 있었으니, 그것을 지으면 쇠머리에 앉은 먹 껍질도 벗겨 낼 수 있을 것이었다."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":5,"title":"셋을 울린다","goal":"무관 거리에서 4번 채집하고 장비 수리 도구 1개를 만들어 먹 벗기는 끌로 갈매에게 넘긴다","need":{"at":["martial_row"],"tasks":[{"t":"gather","n":4,"r":["martial_row"]},{"t":"craft","items":["repair_kit"],"n":1}],"give":{"repair_kit":1}},"lines":[{"s":null,"t":"내가 지은 장비 수리 도구에서 가는 끌을 꺼내 갈매에게 건넸다. 갈매는 끌을 이리저리 돌려 보더니 말없이 고개를 한 번 까딱했다."},{"s":null,"t":"갈매가 쇠머리를 무릎 사이에 끼우고 먹 껍질을 끌로 한 꺼풀씩 벗겨 냈다. 사각, 사각 소리가 종루 꼭대기에서만 맴돌았다."},{"s":"southern_remnant:galmae","t":"숨 쉬지 마, 다들. 손 떨려."},{"s":"q:sn_cheongpa","t":"숨은 쉬어야죠, 누님…"},{"s":null,"t":"마지막 꺼풀이 떨어지자 쇠머리 둘레에 바늘로 긁은 듯한 글씨가 드러났다. 서하람이 쪼그려 앉아 손가락으로 획을 하나하나 따라 그었다."},{"s":"q:r71_seoharam","t":"「동짓밤 삼경. 셋을 울린다. 첫째에 등이 꺼지고, 둘째에 이름이 흐려지고, 셋째에 내가 간다.」"},{"s":null,"t":"서하람의 손가락이 마지막 획 앞에서 멈췄다. 쇠머리 아래쪽에 글씨가 한 줄 더 있었다. 서하람이 고개를 들어 여운비를 보았다."},{"s":"q:r71_seoharam","t":"이름이 있어요. 「북령 종지기 여사온.」"},{"s":null,"t":"여운비의 눈길이 「여」라는 첫 글자에 붙박였다. 아무도 숨소리를 내지 않았다."},{"s":"north_league:yeo","t":"…여씨요. 우리 집안 성이오."},{"s":null,"t":"여운비가 쇠머리를 들여다보았다. 쇠머리를 쥔 손이 바들바들 떨렸다."},{"s":null,"t":"단비가 무언가 말하려고 입을 열었다가 다물었다. 품에서 엿을 꺼냈다가 도로 집어넣었다."},{"s":null,"t":"단비가 계단 어귀로 물러나 등을 기댔다. 여운비가 내려갈 길을 막지 않을 만큼 한쪽으로 비켜선 자리였다."},{"s":"q:r71_seoharam","t":"천명원 별 기록이 빈 날이 하나 더 있어요. 관아에서 본 백 년 전 동지 말고, 그보다 서른 해 뒤의 동지요. 이분이 종을 친 날이 그날이에요."},{"s":null,"t":"갈매는 종루 난간에 팔을 걸치고 흰 도성을 내려다보았다. 그 눈길이 남쪽 어딘가에 한참 머물러 있다가 이쪽으로 돌아왔다."},{"s":"southern_remnant:galmae","t":"셋째에 내가 간다… 제가 어떻게 될 줄 알고 친 거네. 누가 시켰는데. 혼자서 이런 걸 정했을 리 없잖아."},{"s":null,"t":"아무도 대답하지 못했다. 홍인사 때 소이 무녀가 덧붙인 말이 떠올랐다. 종을 울린 관리가 이름 잃은 사람들을 모아 어디론가 떠났다는 말이었다."},{"s":null,"t":"흑련 장부고에서 구슬이 덤이라며 한 말도 떠올랐다. 흑련회를 처음 세운 사람도 그 종을 울려 이름을 잃은 북쪽 관리였다는 말이었다."},{"s":null,"t":"나는 그 생각을 입 밖에 내지 않았다. 「셋째에 내가 간다」고 새긴 사람이 정말로 살아서 그 길을 떠났는지, 아직은 알 길이 없었다."},{"s":"red_moon_cult:danbi","t":"첫째에 등이 꺼지고… 대장님, 그날 이 도성 등이 다 꺼졌다는 거예요? 기름도 없이요?"},{"s":null,"t":"단비의 목소리가 평소보다 작았다. 단비는 거리 처마에 걸린 등롱들을 내려다보고 있었다. 등롱마다 기름 넣는 입구가 바싹 말라 있었다."},{"s":null,"t":"여운비가 쇠머리를 천으로 싸서 가슴 안쪽에 넣고 일어서서 계단 쪽으로 돌아섰다."},{"s":"north_league:yeo","t":"내려갑시다. 오늘은 여기서 밤을 보내야겠소. 멀리 가기엔 다리가 다 풀렸소."},{"s":null,"t":"여운비가 다리가 풀렸다고 말하는 것은 처음 들었다. 여운비의 무릎이 계단 첫 칸에서 아주 조금 꺾였다."},{"s":null,"t":"나는 여운비의 팔을 잡아 주었다. 여운비는 그 손을 뿌리치지 않았다."},{"s":"q:sn_cheongpa","t":"대장 누님, 계단은 제가 고친 거라 튼튼해요. 천천히 내려가요. 제가 맨 뒤에서 갈게요."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":6,"title":"세 걸음 앞의 손님","goal":"무관 거리 연무장 처마 아래에서 야영으로 쉰다","need":{"at":["martial_row"],"tasks":[{"t":"rest","r":["martial_row"],"n":1}]},"lines":[{"s":null,"t":"연무장 처마 아래에 불을 피웠다. 청파는 주워 온 화살을 하나씩 닦아 가지런히 놓았다. 단비는 엿을 구워 보겠다며 꼬챙이에 꿰어 불에 대고 있었다."},{"s":"red_moon_cult:danbi","t":"북령에서는 엿을 구워 먹는대요. 그쵸, 대장님?"},{"s":"north_league:yeo","t":"그런 적 없소."},{"s":"red_moon_cult:danbi","t":"그럼 오늘부터 생긴 거예요."},{"s":null,"t":"갈매가 불가에 엎드려 구운 엿 냄새를 맡다가, 갑자기 고개를 번쩍 들었다. 갈매가 칼을 뽑았다. 스릉, 하는 소리가 처마 아래에서만 울렸다."},{"s":null,"t":"불빛 가장자리, 딱 세 걸음 밖에 사람 하나가 서 있었는데, 발소리는 들리지 않았다. 세 걸음 안으로 들어서는 순간에야 옷자락 스치는 소리가 귀에 닿았다."},{"s":null,"t":"그 사람은 정리관 경현이었다. 등롱도 짐도 없는 빈손이었다. 봉인고에서 보았을 때처럼 관복 자락 끝이 축축했다."},{"s":"q:md_gyeonghyeon","t":"칼은 넣어 두시오, 남명 정찰대장. 차 한 잔 얻어 마시러 왔소. 오늘은 내가 차를 못 가져왔으니."},{"s":"southern_remnant:galmae","t":"누가 너한테 차를 줘? 여기까지 어떻게 왔어!"},{"s":"q:md_gyeonghyeon","t":"길은 하나가 아니오. 당신들은 흑련이 일러 준 물길로 왔고, 나는 내가 아는 길로 왔소."},{"s":null,"t":"청파가 내 소매를 꽉 쥐었다. 손이 덜덜 떨리고 있었다."},{"s":"southern_remnant:galmae","t":"낮에 그 두건 쓴 놈, 네가 보냈지. 우물로 다니는 놈."},{"s":"q:md_gyeonghyeon","t":"나를 보낼 사람도 없고, 나는 누구를 보내 놓고 숨는 사람도 아니오. 궁금한 게 있으면 이렇게 직접 찾아오오."},{"s":null,"t":"경현은 그 물음에는 끝내 그렇다 아니다를 말하지 않았다. 여운비가 칼을 뽑지 않은 채 칼자루를 쥐었다. 그 손등에 핏줄이 불거졌다."},{"s":"north_league:yeo","t":"무슨 볼일이오."},{"s":"q:md_gyeonghyeon","t":"북령 사람이 북령 종루에 올랐다기에, 무엇을 보았는지 궁금했소. 들보에 종은 없었을 테고, 녹아내린 종채 쇠머리를 찾았겠지요. 여사온이 거기 무엇을 새겼는지 나는 아오."},{"s":null,"t":"여운비의 어깨가 굳었다. 단비가 꼬챙이를 내려놓았다."},{"s":"north_league:yeo","t":"…그 이름을 어떻게 아시오."},{"s":"q:md_gyeonghyeon","t":"정청 장부는 이름을 깎지 않소. 집안이 깎은 이름도 장부에는 남아 있지요. 나는 그 장부를 백 년 동안 읽었소."},{"s":"q:sn_cheongpa","t":"그럼 진짜 백스무 살이에요? 관아 벽에 있던 서명이랑 셈표, 그거 아저씨 맞아요?"},{"s":null,"t":"경현이 청파를 내려다보며 빙그레 웃었다."},{"s":"q:md_gyeonghyeon","t":"수향 잠수꾼 청파. 맞소. 관아 벽의 서명도, 셈표도 내가 쓴 것이오. 백 년 동안 먹만 만지다 보니 몸이 늙는 걸 잊었소. 좋은 일은 아니오."},{"s":null,"t":"경현은 앉으라는 말도 듣지 않고 불가에 앉았다. 갈매의 칼끝이 그의 목 한 뼘 앞에 멈춰 있었는데도, 그는 손을 불 쪽으로 내밀어 쬐었다."},{"s":"q:md_gyeonghyeon","t":"여사온이 왜 종을 쳤는지 말하려면 솔내부터 꺼내야 하오. 솔내라는 고을을 아시오? 북령 산골이었소. 화전 일구는 집이 마흔두 채. 글을 아는 사람은 훈장 하나였소."},{"s":"q:md_gyeonghyeon","t":"봉인고에서 부름꾼 이야기를 했지요. 쌀 두 섬을 내면 명부 맨 끝 네모에 도장을 찍어 주던 사람들 말이오. 솔내는 그 쌀 두 섬이 없던 고을이오."},{"s":"q:r71_seoharam","t":"그 네모가… 관아 서식에서 긁혀 있던 칸이에요?"},{"s":"q:md_gyeonghyeon","t":"천명 관측관 서하람. 눈이 밝구려. 그 칸이오."},{"s":"q:md_gyeonghyeon","t":"그해 장날에도 부름꾼이 솔내까지 올라왔소. 쌀 두 섬을 낼 집은 한 집도 없었소."},{"s":"q:md_gyeonghyeon","t":"훈장이 마흔두 집을 다 불러 주겠다고 나섰소. 한 사람이 정말로 불러 줄 수 있는 이름은 몇 줄뿐이오. 부름꾼이 한 해에 수백 줄씩 찍는 도장은 다 거짓이고. 훈장 하나로는 마흔두 집 칸을 다 채우지 못했소."},{"s":"q:md_gyeonghyeon","t":"동짓밤에 우물마다 검은 물이 솟았소. 물은 마당을 덮고 문지방을 넘었소. 물에 닿은 사람은 그 자리에서 먹으로 풀렸소. 아침에 남은 건 옷과 신뿐이었소."},{"s":null,"t":"경현이 불 속을 들여다보았다. 불빛이 얼굴에 닿았는데, 얼굴 아래 그림자는 생기지 않았다."},{"s":"q:md_gyeonghyeon","t":"칸이 있던 시절에 솔내가 먹혔소. 칸을 긁은 뒤로 셈대로 거둔 해에는 우물이 고을을 덮은 적이 한 번도 없소. 관측관이 별 기록을 펴 놓고 해마다 맞춰 봐도 같을 거요."},{"s":"q:md_gyeonghyeon","t":"여사온은 그걸 알았소. 솔내를 다시 겪지 않으려고 종을 쳤소. 북령에서 가장 용기 있는 사람이었소. 그런 사람을 집안은 깎아 냈지요."},{"s":"north_league:yeo","t":"당신이 그분을 입에 올리지 마시오."},{"s":"q:md_gyeonghyeon","t":"나는 깎은 쪽이 아니오, 호송대장. 나는 기억하는 쪽이오."},{"s":null,"t":"여운비의 입술이 하얗게 다물렸다. 단비가 여운비의 소매를 살짝 잡았다. 여운비는 그 손을 털어 내지 않았다."},{"s":null,"t":"그때 거리 저편 흰빛 속에서 철퍽, 철퍽 젖은 것들이 기어 오는 소리가 났다. 소리가 들린다는 것은 이미 세 걸음 안이라는 뜻이었다."},{"s":"q:md_gyeonghyeon","t":"불을 너무 크게 피웠구려. 저것들은 불빛 쪽으로 오오. 등을 찾는 거요."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":7,"title":"누가 당신을 불렀소","goal":"불빛으로 모여든 무관 거리의 요괴를 3번 쓰러뜨린다","need":{"at":["martial_row"],"tasks":[{"t":"win","n":3,"r":["martial_row"]}]},"lines":[{"s":null,"t":"먹 묻은 것들이 처마 아래로 몰려들었다. 갈매와 여운비가 앞을 막았다. 단비가 방울을 흔들었고, 청파는 서하람을 등 뒤로 감쌌다."},{"s":null,"t":"나는 {직업:호위=방패를 들어 불 앞을 막고 밀려드는 것들을 쳐 냈다/월궁=청파가 주워 온 북령 화살을 메겨 하나씩 쏘아 넘겼다/퇴마=부적을 날려 처마 밑으로 기어드는 것들을 태웠다/의무=쓰러진 것들 사이로 다니며 일행 다친 데를 싸매고 부채를 휘둘렀다/봉인=봉인 부적을 처마 기둥에 붙여 그것들의 발을 묶었다/암영=그림자 없는 흰빛 속을 파고들어 그것들의 등을 베었다/조련=동무를 불 앞에 세우고 처마 밑으로 기어드는 것들에 화살을 날렸다/*=불 앞을 지키며 그것들을 하나씩 쓰러뜨렸다}."},{"s":null,"t":"경현은 불가에 앉은 채 꼼짝하지 않았다. 마지막 하나가 경현 바로 앞까지 기어 왔다. 그것이 하얗게 바랜 얼굴로 입을 쩍 벌렸다."},{"s":null,"t":"경현이 그것을 올려다보며 이름 하나를 불렀다. 낯선 이름이었다. 등도 사람의 이름 같았다."},{"s":null,"t":"그것이 벌린 입을 천천히 다물었다. 먹이 사르르 녹아 돌바닥에 스몄고, 그 자리에 바랜 종이 한 장이 내려앉았다. 금빛은 나오지 않았다."},{"s":"q:sn_cheongpa","t":"방금… 이름을 불렀어요? 저게 누군지 알아요?"},{"s":"q:md_gyeonghyeon","t":"동문 밖 두부집 둘째 아들이오. 열아홉이었소. 등도 사람 삼천여를 나는 하나도 빠짐없이 외우오. 그 밤 그들을 거둔 손이 내 손이었으니까."},{"s":null,"t":"청파의 얼굴이 하얗게 질렸다. 갈매가 칼을 고쳐 쥐었다. 단비는 방울을 꽉 움켜쥐었다. 서하람은 그 종이를 줍지 못하고 내려다보기만 했다."},{"s":"q:r71_seoharam","t":"금빛이… 안 나왔어요. 불렀는데도."},{"s":"q:md_gyeonghyeon","t":"불러 줄 사람이 이미 없는 이름이니 그렇소, 관측관. 나는 부르는 사람이 아니오. 읽는 사람이지."},{"s":null,"t":"경현이 종이를 주워 청파에게 내밀었다. 청파는 한참 망설이다가 그것을 받아 기름종이 꾸러미에 넣었다. 경현이 그 꾸러미를 보고 아주 조금 고개를 끄덕였다."},{"s":"q:md_gyeonghyeon","t":"이제 다들 주무시오. 나는 조사원과 잠깐 이야기를 하고 가겠소."},{"s":"southern_remnant:galmae","t":"누가 너 혼자 두고 잔대?"},{"s":"north_league:yeo","t":"나는 안 자겠소. 이야기는 하시오. 나는 여기 있겠소."},{"s":null,"t":"여운비가 칼을 무릎에 눕히고 불 건너편에 앉았다. 갈매도 칼을 끌어안은 채 벽에 등을 기댔다. 단비와 청파는 서로 어깨를 붙이고 누웠지만 눈은 감지 않았다. 서하람은 두루마리를 베고 누워 경현 쪽을 보고 있었다."},{"s":null,"t":"불이 한 번 타닥 튀었다. 경현이 장부 한 권을 꺼내 무릎에 올렸다. 장부 모서리가 여러 장 접혀 있었다."},{"s":"q:md_gyeonghyeon","t":"묵창 나루 명부에 새 칸이 그어지고 거기 당신 이름이 적혔다지요. 그날 밤 정리소 촛불 일곱이 한꺼번에 흔들렸소. 나는 그 촛불 앞에 앉아 있었소."},{"s":null,"t":"경현이 장부 모서리 하나를 손끝으로 접었다 폈다."},{"s":"q:md_gyeonghyeon","t":"하나 물어봅시다. 당신은 누가 당신 이름을 불러 줬소?"},{"s":null,"t":"나는 묵창 나루의 밤을 말했다. 희수가 명부에 새 칸을 긋고, 그 칸에 내 이름을 적어 주던 밤이었다."},{"s":null,"t":"관아 터에서 다섯 사람이 돌아가며 내 이름을 불러 준 이야기도 했다. 금빛 실이 불 위로 엇갈리던 이야기였다."},{"s":null,"t":"경현은 중간에 끼어들지 않고 내 이야기를 끝까지 들었다."},{"s":"q:md_gyeonghyeon","t":"다섯이라. 다섯은 많지요. 솔내에서 나를 부른 사람은 하나였소."},{"s":null,"t":"나는 그 하나가 누구였는지 물었다. 경현은 대답 대신 장부를 덮었다."},{"s":"q:md_gyeonghyeon","t":"죽은 사람이 아직도 내 이름을 부르는 소리를 들어 본 적 있소? 나는 해마다 동짓밤이면 그 소리를 듣소."},{"s":null,"t":"경현의 눈이 우물 쪽 흰빛에 가 있었다. 나는 아무 대답도 하지 못했다. 경현은 그 눈길을 거두고 웃었다. 늘 짓던 느긋한 웃음이었다."},{"s":"q:md_gyeonghyeon","t":"그 이야기는 다음에 하리다. 오늘은 여사온 이야기만으로도 북령 호송대장이 밤을 새울 테니."},{"s":null,"t":"경현이 불 건너편의 여운비를 보았다. 여운비는 칼자루를 쥔 채 경현을 마주 보았다."},{"s":"q:md_gyeonghyeon","t":"철벽 고찰에 가거든 얼음 인장을 보시오. 그 아래 얼음은 누가 이름을 불러 줘야만 녹소. 북령은 일흔 해 동안 여사온의 이름을 한 번도 부르지 않은 집안이오."},{"s":"q:md_gyeonghyeon","t":"그 얼음 속에는 장 말고 다른 것도 묻혀 있소. 북령 사람 가운데 누가 먼저 그 이름을 부를지, 나는 궁금하구려."},{"s":null,"t":"경현이 일어섰다. 젖은 관복 자락이 돌바닥을 쓸었다. 세 걸음 밖으로 나서자 그의 발소리도 옷자락 소리도 흰빛 속으로 사라졌다."},{"s":null,"t":"그가 앉았던 자리에 장부 한 장이 떨어져 있었다. 모서리가 반듯하게 접힌 빈 장이었다."},{"s":"q:r71_seoharam","t":"모서리를 접는 버릇이 있네요. 봉인고 찻상에 올려놓은 장부도 모서리가 접혀 있었어요. 적어 둘게요."},{"s":"north_league:yeo","t":"장작을 더 모아 옵시다. 오늘 밤은 불을 크게 지키겠소. 먹 묻은 것들이 오면 베면 되오. 불이 꺼져서 그자가 세 걸음 안에 오는 걸 모르는 것보다 낫소."}],"reward":{"xp":2249}},{"quest_id":"mdq_6","step":8,"title":"바람 없는 밤","goal":"무관 거리에서 3번 채집해 밤새 불을 지킬 땔감을 모은다","need":{"at":["martial_row"],"tasks":[{"t":"gather","n":3,"r":["martial_row"]}]},"lines":[{"s":null,"t":"장작을 쌓아 두자 일행은 하나둘 잠이 들었다. 청파가 맨 먼저 갈매의 어깨에 기대 잠들었다. 갈매는 청파를 밀어내지 않은 채 칼을 끌어안고 꾸벅꾸벅 졸았다."},{"s":null,"t":"서하람은 두루마리를 베고 누워 가늘게 코를 골았다. 단비는 불 가까이 몸을 웅크리고 누웠지만 눈은 뜨고 있었다."},{"s":null,"t":"여운비만 칼을 무릎에 눕힌 채 깨어 있었다. 여운비는 멈춘 화살들 쪽을 보고 있었다."},{"s":null,"t":"내가 장작을 하나 넣고 곁에 앉았다. 장작이 타닥 튀는 소리가 우리 둘 사이에서만 울렸다."},{"s":"north_league:yeo","t":"북령에서는 어릴 때 맹세 하나를 외우게 하오. 「다시는 잃지 않는다.」 무엇을 다시는 잃지 않는지는 아무도 안 가르쳐 주오.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:yeo","t":"당신도 그 맹세를 외웠겠지. 「다시는 잃지 않는다.」 무엇을 다시는 잃지 않는지, 누가 당신에게 가르쳐 준 적이 있소?","fac":"north_league","spec":1,"grp":1},{"s":"north_league:yeo","t":"장로님도 그 맹세를 외우셨겠지요. 「다시는 잃지 않는다.」 무엇을 다시는 잃지 않는지, 누가 장로님께 가르쳐 드린 적이 있소?","fac":"north_league","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 오늘에서야 그 답을 들은 것 같다고 했다. 쌀 두 섬이 없던 산골, 솔내였다. 여운비가 고개를 끄덕였다."},{"s":"north_league:yeo","t":"그것도 저 정리관한테서 들었소. 북령 사람이 아니라 정청 사람한테서. 그게 분하오."},{"s":null,"t":"여운비가 칼날에 엄지를 대고 천천히 밀었다. 피가 배어 나오지 않을 만큼만 힘을 준 손이었다."},{"s":"north_league:yeo","t":"쇠머리에 새긴 이름이 여씨였소. 같은 성이오. …지금은 그것뿐이오. 그 이상은 맹주께 여쭤야 하오."},{"s":null,"t":"여운비가 품속 쇠머리를 옷 위로 한 번 눌렀다. 나는 고찰까지 함께 가겠다고 했다. 여운비가 나를 보았다."},{"s":"north_league:yeo","t":"맹주께서는 길에서 당신 됨됨이를 보라 하셨소. …그런데 보다 보니 엉뚱한 것까지 보이오."},{"s":null,"t":"여운비가 눈길을 돌린 불 건너편에 단비가 등을 돌린 채 누워 있었다."},{"s":"north_league:yeo","t":"저 무녀, 저녁에 제 몫 엿을 청파한테 몽땅 줍디다. 화살 줍느라 저녁을 놓친 걸 보고. 장터에서는 그런 사람인 줄 몰랐소."},{"s":null,"t":"단비의 등이 조금 움찔했다. 단비가 등을 돌린 채로 말했다. 목소리가 졸린 척 늘어졌다."},{"s":"red_moon_cult:danbi","t":"…그건 비밀이었는데요. 대장님은 입이 무거운 줄 알았더니."},{"s":"north_league:yeo","t":"…자는 줄 알았소."},{"s":"red_moon_cult:danbi","t":"대장님 목소리가 커서 깼어요."},{"s":null,"t":"여운비는 대답 대신 불가에 놓인 구운 엿 꼬챙이를 집어 한 입 베어 물었다. 단비가 등을 돌린 채로 킥 웃었다."},{"s":"north_league:yeo","t":"…바람이라도 불면 생각이 덜 날 텐데. 이 땅은 바람이 없어서 생각이 너무 많이 나오."},{"s":"north_league:yeo","t":"일어나면 고찰로 갑시다. 맹주께 이 쇠머리를 보여 드리고 여쭐 것이 있소. 얼음 속 이름이 누구 이름인지도."},{"s":null,"t":"여운비가 불빛에 내 발을 흘끗 보았다. 옥문 협로에서는 감발을, 적사 황무지에서는 신 끈을 여운비가 고쳐 매 주었다. 그 신 끈이 아직 그대로였다."},{"s":"north_league:yeo","t":"…매듭이 아직 안 풀렸구려. 안쪽에 잘 두었소. 내일 고갯길은 미끄러우니 자기 전에 한 번 더 조이시오."}],"reward":{"xp":2249,"gil":480,"items":{"frozen_arrow_shaft":2,"frost_bell_iron":1}}},{"quest_id":"mdq_7","step":1,"title":"북쪽 바람","goal":"무관 거리에서 쉬고 철벽 고찰에 도착해 북쪽 바람을 맞는다","need":{"at":["iron_monastery"],"tasks":[{"t":"rest","r":["martial_row"],"n":1},{"t":"travel","r":["iron_monastery"],"n":1}]},"lines":[{"s":null,"t":"거룻배를 타고 수로를 내려와 봉인고 돌계단을 올라섰다. 흰빛이 등 뒤로 멀어지고, 눅눅한 봉인고 냄새가 코를 찔렀다."},{"s":"q:sn_cheongpa","t":"냄새다! 살았다! 곰팡내가 이렇게 반가울 줄은 몰랐어요!"},{"s":null,"t":"북쪽으로 길을 잡아 철벽 고찰 고개에 닿았을 때였다. 산허리를 타고 내려온 바람이 휘잉 하고 일행의 볼을 때렸다."},{"s":null,"t":"여운비의 칼자루 끝에서 붉은 술이 펄럭 솟아올랐다. 술이 북쪽으로 쭉 뻗어 파르르 떨었다."},{"s":null,"t":"여운비가 걸음을 멈췄다. 여운비는 눈을 감고 바람 속에 한동안 서 있었다. 아무도 여운비를 재촉하지 않았다."},{"s":"red_moon_cult:danbi","t":"대장님 술이 깼어요. 낮잠 다 잤나 봐요."},{"s":null,"t":"단비는 놀리듯 말했지만 목소리가 따뜻했다. 여운비가 눈을 뜨고 단비를 흘겨보았다. 그 눈가가 조금 젖어 있었다."},{"s":"southern_remnant:galmae","t":"남명 사람한테 이게 반가워? 이빨 다 부러지겠다."},{"s":null,"t":"갈매가 이를 딱딱 부딪치며 가죽옷 깃을 세웠다. 서하람이 제 목도리를 풀어 갈매 목에 휙 둘러 주었다."},{"s":"q:r71_seoharam","t":"저는 밤새 별 볼 때 이거보다 추운 데서 자요… 그쪽이 더 필요해 보여요."},{"s":"southern_remnant:galmae","t":"…누가 달래."},{"s":null,"t":"갈매는 투덜대면서도 목도리를 풀지 않았다. 목도리에 코끝까지 묻은 갈매를 보고 청파가 킥킥 웃었다."},{"s":null,"t":"산문 앞에서 덩치 큰 승려 하나가 빗자루로 눈을 쓸고 있었다. 승려가 우리를 보고 빗자루를 어깨에 걸치며 껄껄 웃었다."},{"s":"north_league:hyegak","t":"허허, 호송대장이 손님을 다섯이나 달고 돌아왔군요. 정청 손님은 또 뵙습니다. 다른 분들은 처음 뵙지요? 고찰 수좌 혜각입니다.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:hyegak","t":"허허, 우리 고찰 산문 패를 찬 분이 손님을 넷이나 달고 돌아왔군요. 그쪽은 손님이 아니라 식구지요. 다른 분들은 처음 뵙지요? 고찰 수좌 혜각입니다.","fac":"north_league","spec":1,"grp":1},{"s":"north_league:hyegak","t":"허허, 장로께서 손님을 넷이나 달고 돌아오셨군요. 다른 분들은 처음 뵙지요? 고찰 수좌 혜각입니다.","fac":"north_league","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"여운비가 혜각 앞에 고개를 숙였다."},{"s":"north_league:yeo","t":"수좌님. 맹주께 급히 여쭐 것이 있습니다."},{"s":"north_league:hyegak","t":"맹주님은 사흘째 사당에서 안 나오십니다. 정리관이라는 손님이 또 다녀간 뒤로요."},{"s":null,"t":"여운비의 얼굴이 굳었다. 갈매가 칼자루를 움켜쥐었다."},{"s":"southern_remnant:galmae","t":"그놈이 여기도 왔어? 등도에서 우리 불가에 앉았다 간 놈이?"},{"s":"north_league:hyegak","t":"석굴 문 앞까지 왔다가 그냥 돌아갔습니다. 맹주님이 직접 나가 맞으셨고요. 무슨 말이 오갔는지는 소승도 모릅니다."},{"s":null,"t":"혜각이 빗자루로 산문 안쪽을 가리켰다. 처마 밑 장작 더미가 거의 바닥나 있었다."},{"s":"north_league:hyegak","t":"맹주님을 뵙기 전에 고찰 법부터 지키셔야지요. 산문 넘은 분은 먼저 일을 하고 밥을 드십니다. 겨울 장작이 모자라요. 약초도 좀 캐 와 주시고요."},{"s":null,"t":"혜각의 말로는 고찰 아궁이에는 연기가 적어 위패에 그을음이 앉지 않는 부적목만 땐다고 했다."},{"s":"red_moon_cult:danbi","t":"손님한테 일을 시키는 절은 처음 봐요."},{"s":"north_league:hyegak","t":"허허, 일 안 하는 손님은 소승이 땅에 눕혀 드립니다. 웃으면서요."},{"s":null,"t":"혜각이 정말로 웃었다. 단비가 슬그머니 내 뒤로 반 걸음 물러섰다."}],"reward":{"xp":2570}},{"quest_id":"mdq_7","step":2,"title":"고찰 부엌","goal":"서리솔 고개에서 6번 채집하고 부적목 3개를 겨울 장작으로 철벽 고찰에 넘긴다","need":{"at":["iron_monastery"],"tasks":[{"t":"gather","n":6,"r":["frost_pine_pass"]}],"give":{"wood":3}},"lines":[{"s":null,"t":"장작을 다 쌓자 혜각이 우리를 부엌으로 몰아넣었다. 커다란 가마솥 셋이 아궁이 위에 걸려 있었다."},{"s":"north_league:hyegak","t":"고찰 밥은 먹는 사람이 짓습니다. 쌀은 저기, 나물은 여기, 불은 알아서들 피우시고요."},{"s":null,"t":"일행이 저마다 자리를 잡았다. 여운비는 말없이 도마 앞에 서서 무를 썰었다. 탁, 탁, 탁, 칼 소리가 고르게 이어졌다."},{"s":null,"t":"단비는 나물 무침을 맡았다. 단비가 조청을 한 국자 듬뿍 붓자 혜각의 눈썹이 꿈틀했다."},{"s":"north_league:hyegak","t":"무녀님, 그건 나물입니다. 엿이 아니라요."},{"s":"red_moon_cult:danbi","t":"단 게 들어가야 맛있어요. 대장님도 좋아하실걸요."},{"s":"north_league:yeo","t":"안 좋아하오."},{"s":null,"t":"갈매는 아궁이 앞에 쪼그려 앉아 불을 맡았다. 갈매가 장작을 툭툭 밀어 넣자 불길이 화르륵 고르게 피어올랐다."},{"s":"north_league:hyegak","t":"허, 불을 잘 다루시네요."},{"s":"southern_remnant:galmae","t":"남명 애들은 불 붙이는 것부터 배워. 잔불촌 화로는 꺼지면 안 되거든."},{"s":null,"t":"서하람은 쌀을 씻다 말고 쌀알을 세고 있었다. 청파는 우물에서 물을 길어 오다가 부엌 문턱에 걸려 물동이를 와르르 엎었다."},{"s":"q:sn_cheongpa","t":"으악, 죄송해요! 다시 떠 올게요!"},{"s":null,"t":"혜각이 웃으며 젖은 바닥을 걸레로 훔쳤다. 그사이 갈매가 부뚜막 위 누룽지 한 조각을 몰래 집어 입에 넣으려 했다."},{"s":null,"t":"혜각의 손이 번개처럼 움직였다. 다음 순간 갈매가 부엌 바닥에 벌렁 누워 있었다. 혜각은 웃는 얼굴 그대로였다."},{"s":"north_league:hyegak","t":"허허, 밥 먹기 전에 누룽지부터 집으면 이렇게 됩니다."},{"s":"southern_remnant:galmae","t":"…뭐야, 언제 넘어간 거야, 나?"},{"s":null,"t":"일행이 와르르 웃음을 터뜨렸다. 여운비마저 칼을 내려놓고 고개를 돌려 웃었다. 갈매가 바닥에 누운 채 천장을 노려보다가 저도 모르게 픽 웃었다."},{"s":null,"t":"나는 여운비 옆에서 무를 함께 썰었다. 내 무는 두께가 들쭉날쭉하자 여운비가 내 칼질을 보다가 제 칼을 내려놓았다."},{"s":"north_league:yeo","t":"칼등을 손가락 마디에 대시오. 이렇게. 손끝을 안으로 말고."},{"s":null,"t":"여운비가 내 왼손 손가락을 하나씩 접어 준 뒤 다시 썰자, 이번에는 두께가 고르게 나왔다."},{"s":"north_league:yeo","t":"…나쁘지 않소."},{"s":"red_moon_cult:danbi","t":"어머, 오늘은 {이름} 님이 칭찬 받았네. 저는 언제 받아요?"},{"s":"north_league:yeo","t":"나물에서 조청을 빼면."},{"s":null,"t":"밥상을 다 차렸을 때 혜각이 여운비 곁으로 왔다. 혜각이 웃음기를 거두었다."},{"s":"north_league:hyegak","t":"맹주님이 호송대장을 기다리시는 것 같습니다. 서두르지는 마세요. 사흘을 사당에 계셨으니 반나절쯤 더 계셔도 됩니다."},{"s":"north_league:hyegak","t":"기다리는 동안 몸을 놀리면 생각이 많아지지요. 밥 먹고 연무장에서 땀을 좀 흘리세요. 소승이 봐 드리겠습니다."}],"reward":{"xp":2570}},{"quest_id":"mdq_7","step":3,"title":"깎인 위패","goal":"자율 활동 「자율 수련」을 1시간 넘게 끝까지 한다","need":{"at":["iron_monastery"],"tasks":[{"t":"idle","k":"training","min":60,"n":1}]},"lines":[{"s":null,"t":"수련을 마치고 땀이 식을 즈음, 사당 문이 끼익 열렸다. 맹주 석진악이 문간에 서 있었다."},{"s":null,"t":"바람이 사당 처마를 훑고 지나가며 웅웅 낮게 울었다. 노인은 우리를 보고도 한참 말이 없었다. 사흘 사이에 노인의 볼이 쑥 꺼져 있었다."},{"s":"north_league:seok","t":"…자네 왔구먼. 운비를 데리고 돌아왔어. 길에서 무엇을 보았는지 들어 보세.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:seok","t":"…자네 왔구먼. 북령 패를 찬 사람이 운비를 데리고 돌아왔어. 길에서 무엇을 보았는지 들어 보세.","fac":"north_league","spec":1,"grp":1},{"s":"north_league:seok","t":"…장로, 자네가 운비를 데리고 돌아왔구먼. 길에서 무엇을 보았는지 들어 보세.","fac":"north_league","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"여운비가 노인 앞에 무릎을 꿇고 가슴에서 천에 싼 쇠머리를 꺼내 두 손으로 받쳐 올렸다."},{"s":"north_league:yeo","t":"맹주님. 등도 종루에서 찾은 종채 쇠머리입니다. 여기 「여사온」이라고 새겨져 있습니다. 이분이 누구입니까? 우리 집안 사당의 깎인 위패가 이분입니까?"},{"s":null,"t":"석진악은 쇠머리를 받아 들지 않았다. 노인의 눈은 끝에 새긴 이름부터 찾아 읽었다. 바위 같던 넓은 어깨가 한 번 꺼졌다가 천천히 올라왔다."},{"s":"north_league:seok","t":"…들어오너라. 다들."},{"s":null,"t":"사당 안쪽 벽에 위패 열둘이 나란히 놓여 있었다. 열한 개에는 이름이 또렷했다. 가운데 하나만은 이름 자리가 칼로 깊게 깎여 하얀 나뭇결이 드러나 있었다."},{"s":null,"t":"석진악이 깎인 위패 앞에 섰다. 노인이 손을 들어 위패를 쓰다듬으려다가 거두었다."},{"s":"north_league:seok","t":"운비야. 이분은 자네 작은증조할아버지시네. 자네 증조할아버지의 아우님이시지."},{"s":null,"t":"여운비의 숨이 멎었다. 단비가 여운비의 등 뒤로 반 걸음 다가섰다."},{"s":"north_league:seok","t":"백십 년 전에 솔내라는 고을이 하룻밤 새 사라졌네. 우물마다 검은 물이 솟았고, 아침엔 옷가지만 남았지. 그 옷가지를 거둔 사람이 자네 증조할아버지셨네."},{"s":"north_league:seok","t":"그분은 돌아가실 때까지 그 냄새를 못 잊으셨다더군. 젖은 먹 냄새였다고."},{"s":"north_league:seok","t":"그로부터 마흔 해 뒤에 정청이 종을 칠 사람을 찾았네. 그때 아우님이 제 발로 가셨지. 「솔내 같은 일은 다시는 없게 하겠습니다」 하고."},{"s":"north_league:seok","t":"나는 그때 열다섯이었네. 이 산문에서 그분이 내려가시는 걸 봤어. 뒤를 한 번도 안 돌아보시더군."},{"s":null,"t":"여운비가 무언가 물으려고 입을 열자 석진악이 손을 들어 그 말을 막았다."},{"s":"north_league:seok","t":"정청은 그 종이 무엇을 지웠는지 말해 주지 않았네. 나중에야 알았지. 도성 하나였어. 사람이 삼천이었고."},{"s":"north_league:seok","t":"북령은 솔내를 다시 겪지 않으려다가, 솔내 같은 일을 남에게 겪게 한 걸세. 그래서 집안이 그 이름을 깎았네. 부끄러워서."},{"s":null,"t":"아무도 움직이지 않았다. 단비는 고개를 떨구고 제 손을 내려다보았다. 청파는 입술을 꾹 깨물었다. 서하람은 두루마리를 끌어안은 팔에 힘을 주었다."},{"s":"north_league:seok","t":"그날 밤 등을 끈 손이 북령 하나뿐이었겠나. 다들 제 몫이 있었네. 그건 자네들 어른께 여쭈게. 나는 북령 몫만 말하겠네."},{"s":null,"t":"갈매가 이를 악물고 사당 기둥을 노려보았다. 주먹 쥔 손등에 핏줄이 불거졌다."},{"s":"north_league:seok","t":"사흘 전에 정리관이 다시 찾아와 그 일을 내게 들려주더군. 솔내를 기억하느냐고. 장을 정청에 내기만 하면 솔내는 다시 없을 거라고.","fac_not":"north_league","spec":2,"grp":2},{"s":"north_league:seok","t":"자네도 북령 사람이니 들어 두게. 사흘 전에 정리관이 다시 찾아와 그 일을 내게 들려주더군. 솔내를 기억하느냐고. 장을 정청에 내기만 하면 솔내는 다시 없을 거라고.","fac":"north_league","spec":1,"grp":2},{"s":"north_league:seok","t":"그때 이상한 걸 봤네. 그자는 혼자 왔어. 따라온 이가 아무도 없었지. 그런데 그자가 간 뒤 산문 밖 우물가에 젖은 발자국이 여럿이었네. 운비가 썰매를 끌고 왔던 날 본 것과 똑같은 자국이었지."},{"s":null,"t":"갈매가 고개를 홱 들었다. 청파가 내 소매를 잡아당겼다."},{"s":"q:sn_cheongpa","t":"무관 거리 우물가에도 있었어요! 그 두건 쓴 사람이 우물로 빠져나갔고요!"},{"s":"north_league:yeo","t":"혼자 온 사람 뒤에 발자국이 여럿이라… 그자가 데리고 다니는 자들이 우물로 다닌다는 말씀입니까?"},{"s":"north_league:seok","t":"나도 모르네. 본 것만 말하는 걸세. 그자는 석굴 문 앞까지 가서 얼음을 보고 웃더군. 「부를 사람이 오면 녹겠지요」 하고."},{"s":"north_league:seok","t":"그러고는 서쪽으로 내려갔네. 이틀 뒤 고찰에 들른 흑련 심부름꾼한테 들었지. 그자가 백골 장터로 들어가 교주 천막에서 반나절을 있다 나왔다더군. 흑련은 빚진 사람 뒤만 밟는 줄 알았더니, 정청 사람 뒤도 밟더군."},{"s":null,"t":"단비가 고개를 번쩍 들었다."},{"s":"red_moon_cult:danbi","t":"교주님 천막에요? 반나절이나요?"},{"s":"north_league:seok","t":"흑련 심부름꾼이 그렇다더군. 무슨 말이 오갔는지는 나도 모르네."},{"s":null,"t":"단비가 입술을 깨물었다. 웃음기가 하나도 없는 얼굴이었다."},{"s":null,"t":"석진악이 깎인 위패에서 눈을 떼고 여운비를 내려다보았다. 노인의 눈 속에서 무언가 흔들렸다."},{"s":"north_league:seok","t":"운비야. 내가 길에서 보고 오라 했지. 정청이 그 장으로 무엇을 하려는지. 무엇을 보았느냐."},{"s":"north_league:yeo","t":"등도 관아 벽에서 백 년 전 서식을 보았습니다. 「부르는 이」 칸이 긁혀 있었고, 해마다 몇 사람을 거둘지 정하는 셈표가 붙어 있었습니다. 그 셈을 짠 사람이 정리관입니다."},{"s":"north_league:yeo","t":"정청이 장을 모으는 건 지키려는 게 아닌 것 같습니다. 장서각 불도 정청 안에서 났습니다."},{"s":null,"t":"석진악이 오래 눈을 감았다. 지팡이를 쥔 손이 바르르 떨렸다."},{"s":"north_league:seok","t":"나는 백 년 동안 그 셈이 옳다고 믿은 집의 맹주일세. 솔내를 막아 준 셈이라고. …자네들 말을 들으니 이제 모르겠네."},{"s":"north_league:seok","t":"모르는 채로 얼음 속에 두는 것보다, 꺼내서 이 사람이 지니게 하는 편이 낫겠지. 정리관 손에 들어가는 것보다는."},{"s":"north_league:seok","t":"석굴로 가자. …그 전에 다들 뱃속을 데우게. 석굴 추위는 사람 속까지 얼리네."},{"s":"north_league:hyegak","t":"설피골 얼음 못에 빙어가 오를 철입니다. 빙어국을 먹고 내려가시면 덜 추우실 거예요. 다들 낚싯대는 있으시지요?"},{"s":null,"t":"설피골 빙어는 잘아서 국거리로는 모자랐으므로, 나는 손질한 살을 모아 야령초를 듬뿍 넣고 매운탕으로 끓이기로 했다."},{"s":"q:sn_cheongpa","t":"낚시요? 그건 제가 제일 잘해요! 얼음 낚시는 처음이지만요!"}],"reward":{"xp":2570}},{"quest_id":"mdq_7","step":4,"title":"얼음 인장","goal":"설피골에 도착해 3번 낚시하고 매운탕 2그릇을 끓여 석굴 앞에서 넘긴다","need":{"at":["iron_monastery"],"tasks":[{"t":"travel","r":["snow_hollow"],"n":1},{"t":"fish","n":3,"r":["snow_hollow"]},{"t":"craft","items":["spicy_stew"],"n":2}],"give":{"spicy_stew":2}},"lines":[{"s":null,"t":"설피골 얼음 못에서 청파는 얼음 구멍 앞에 엎드려 한 번도 고개를 들지 않았다. 물 앞에 서자 청파는 말수가 줄었다. 빙어가 올라올 때마다 청파는 소리 없이 씩 웃기만 했다."},{"s":null,"t":"끓인 빙어 매운탕을 들고 석굴 앞으로 돌아왔다. 석진악이 그릇을 받아 후후 불어 한 모금 마시고, 그릇을 여운비에게 넘겼다."},{"s":"north_league:seok","t":"맛이 나쁘지 않구나. …자네 집안 입버릇이 옮았네."},{"s":null,"t":"여운비가 그릇을 받으며 아주 조금 웃었다."},{"s":null,"t":"석굴 계단을 내려갈수록 내쉬는 숨이 얼어 눈썹에 서리가 맺혔다. 흰 밤의 멈춘 서리와는 달랐다. 살갗을 물어뜯는 진짜 추위였다."},{"s":null,"t":"석굴 한가운데에 사람 키보다 큰 얼음덩이가 놓여 있었다. 홍인사 때 내가 종의 뚜껑임을 알아낸 그 얼음 인장이었다."},{"s":null,"t":"얼음 속에 두꺼운 닥종이 한 장이 갇혀 있었다. 두꺼운 얼음 너머로 종이 위의 흰 불꽃이 보였다. 불꽃은 얼음에 갇혀서도 꺼지지 않았다."},{"s":null,"t":"종이에는 「남북의 종은 짝으로 문을 누른다. 종을 울리는 자는 제 이름을 건다」라고 적혀 있었다. 그 아래 증인 칸에 「여사온」이라는 이름이 붙은 채 함께 얼어 있었다."},{"s":null,"t":"장 바로 뒤에 접힌 종이가 한 장 더 얼어 있었다. 그 종이는 장보다 작고 얇아 편지처럼 보였다."},{"s":"q:r71_seoharam","t":"맹주님, 장 뒤에 하나 더 있어요. 저건 뭐예요?"},{"s":"north_league:seok","t":"그분 편지일세. 소등이 있던 이듬해 겨울, 사내 하나가 밤에 산문을 두드리고 이걸 놓고 갔네. 나는 그 사람 얼굴을 보았는데… 지금도 떠올리지 못하네. 아무리 애를 써도 얼굴 자리가 하얗게 비어 있어."},{"s":"north_league:seok","t":"그때 맹주님과 여씨 집안 어른들은 편지를 읽고도 태우지 못하셨네. 그래서 장과 함께 얼음 속에 넣으셨지. 부르지 않을 이름을 한자리에 묻은 걸세."},{"s":null,"t":"품속의 첫째 장이 저절로 떨렸다. 얼음 안의 불꽃과 내 품의 불꽃이 서로를 향해 기울었다."},{"s":"north_league:seok","t":"그분 이름이 증인 칸에 붙어서 같이 얼었네. 그 이름을 누가 불러 주지 않으면 얼음은 안 풀려. 일흔 해 동안 아무도 안 불렀지."},{"s":"north_league:seok","t":"북령은 그 이름을 부르지 않기로 한 집이었네. 나도 맹주가 된 뒤로 한 번도 못 불렀어. 부를 자격이 없다고 여겼지."},{"s":null,"t":"석진악이 여운비를 돌아보았다. 얼음 앞에 선 여운비의 입술이 추위에 하얗게 갈라져 있었다. 여운비가 한 번 입을 열었다가 소리를 내지 못하고 다물었다."},{"s":null,"t":"일행 누구도 대신 부르겠다고 나서지 않았다. 이 이름만은 여운비가 불러야 한다는 것을 모두가 알았다."},{"s":null,"t":"청파가 숨을 참았다. 갈매는 목도리를 꽉 움켜쥐었다. 서하람은 눈을 깜빡이지도 않았다."},{"s":null,"t":"단비가 여운비 등 뒤로 다가갔다. 단비는 말없이 여운비의 망토 자락을 한 줌 쥐었다. 떨어지지 않게 붙잡아 주는 손이었다."},{"s":null,"t":"나는 여운비 옆에 섰다. 세 걸음보다 훨씬 가까운 자리였다."},{"s":"north_league:yeo","t":"…여사온."},{"s":null,"t":"갈라진 목소리였지만, 금빛 실 한 가닥이 얼음에 닿았다. 찌직, 하고 얼음 표면에 가느다란 금이 하나 그어졌다."},{"s":"north_league:yeo","t":"여사온. 북령 종지기 여사온. …우리 집안의 어른."},{"s":null,"t":"얼음이 안쪽에서부터 울었다. 쩌엉, 하는 소리와 함께 금이 사방으로 번져 나갔다."},{"s":null,"t":"얼음 조각이 우수수 떨어져 바닥에서 녹기 시작했다. 녹아 흐르는 물은 처음에는 먹처럼 검었지만, 바닥에 닿는 순간 맑은 물로 바뀌었다."},{"s":null,"t":"마지막 조각이 떨어져 나가자 장과 편지가 여운비의 두 손 위로 사르르 내려앉았다. 여운비가 그것을 받아 든 채 무릎을 꿇었다."},{"s":null,"t":"우는 소리는 나지 않았지만, 어깨가 아주 조금 떨렸다. 단비는 그 망토 자락을 끝까지 놓지 않았다."},{"s":null,"t":"석진악이 얼음 녹은 자리를 보며 처음으로 그 이름을 소리 내어 불렀다. 노인의 입에서도 금빛 실이 나와 종이 위에 닿았다."},{"s":"north_league:seok","t":"여사온 어르신. …늦었습니다."},{"s":null,"t":"여운비가 떨리는 손으로 편지를 펼쳤다. 편지는 북령 무관 특유의 각진 글씨로 적혀 있었다. 일흔 해를 얼음 속에 있었는데도 먹이 조금도 번지지 않았다."},{"s":"north_league:yeo","t":"「백 공께. 저는 울리겠습니다. 솔내에서 북령이 잃은 것을 생각하면 이 셈이 맞다는 것을 압니다. 다만 이 셈이 언젠가 끝나게 해 주십시오. — 북령 종지기 여사온.」"},{"s":"southern_remnant:galmae","t":"백 공은 또 누구야. 종을 치라고 시킨 놈이야?"},{"s":null,"t":"아무도 대답하지 못했다. 나는 등도 관아 현판의 「도제조 백운서」를 떠올렸다. 그 사람도 성이 백이었다. 나는 그 생각을 입 밖에 내지 않았다."},{"s":null,"t":"단비가 여운비 곁에 쪼그려 앉아 편지를 같이 들여다보았다. 단비가 「언젠가 끝나게」라는 대목을 손끝으로 가만히 짚었다."},{"s":"red_moon_cult:danbi","t":"대장님네 어른, 「언젠가」 앞에서 붓이 한참 멈췄어요. 여기 먹이 동그랗게 고였잖아요. 끝나길 바라면서 치신 거예요."},{"s":null,"t":"녹은 물은 석굴 바닥 틈으로 졸졸 흘러내려 갔다. 물이 내려가는 쪽에서 무언가 끄르륵 울었다. 혜각이 석굴 입구에서 지팡이를 고쳐 쥐었다."},{"s":"north_league:hyegak","t":"일흔 해 묵은 물길이 열렸습니다. 저 아래 먹 낀 것들이 고여 있었던 모양이에요. 물길을 따라 내려가 치워 주지 않으면 고찰 우물까지 올라오겠습니다."}],"reward":{"xp":2570}},{"quest_id":"mdq_7","step":5,"title":"이을 이","goal":"설피골로 원정을 한 번 끝까지 다녀와 얼음 녹은 물길을 따라 석굴 아래를 살핀다","need":{"at":["iron_monastery"],"tasks":[{"t":"expedition","r":["snow_hollow"],"n":1}]},"lines":[{"s":null,"t":"물길은 고찰 밖 계곡까지 이어져 있었다. 물길 끝에서 먹 낀 짐승들을 몰아내고 돌아오니, 사당 앞마당에서 석진악과 여운비가 기다리고 있었다."},{"s":null,"t":"여운비가 둘째 장을 내게 내밀었다. 종이 맨 아래 끝줄에 칸 하나가 비어 있었다. 그 칸 머리에 작은 글씨로 「이을 이」라고 적혀 있었다."},{"s":"q:r71_seoharam","t":"이을 이… 관아 서식에서 본 칸이랑 달라요. 「부르는 이」가 아니라 「이을 이」예요."},{"s":null,"t":"석진악이 붓 한 자루를 내밀었다. 그 붓은 손때가 배어 손잡이가 검게 반들거렸다."},{"s":"north_league:seok","t":"맹약에 그렇게 적혀 있네. 장마다 끝줄을 비워 두었다고. 장을 이을 사람이 거기 제 이름을 쓰는 걸세. 누가 될지는 맹약이 알아서 정한다고 했지."},{"s":"red_moon_cult:danbi","t":"맹약이 알아서 정하면, 아무나 쓰면 안 되는 거예요?"},{"s":"north_league:seok","t":"아무나 쓰면 먹이 안 앉네. 내가 젊을 때 몰래 써 봤지. 먹이 물처럼 흘러내리더군."},{"s":null,"t":"일행의 눈이 모두 나에게로 왔다. 나는 붓을 받아 「이을 이」 칸에 이름을 적었다."},{"s":null,"t":"먹이 종이에 스며드는 순간 흰 불꽃이 금빛으로 바뀌었다. 손바닥만 하던 불꽃이 한 번 화르르 커졌다가 가라앉았다. 종이를 쥔 손끝이 따뜻해졌다."},{"s":"q:sn_cheongpa","t":"금빛이에요! {이름} 님 이름이 앉았어요!"},{"s":null,"t":"나는 품속 첫째 장 반쪽의 끝줄도 살폈다. 탄 종이 끝에 같은 칸이 남아 있었다. 붓을 대 보았지만 먹이 스미지 않고 주르르 흘러내렸다."},{"s":"q:r71_seoharam","t":"앞부분이 타서 그래요. 장이 온전해야 이을 수 있나 봐요. 그 반쪽은… 나중에 다시 살려야겠네요."},{"s":"north_league:seok","t":"맹약 끝줄에 이런 말이 있네. 「일곱 장의 끝줄이 다 이어지는 날, 맹약 마당에서 진을 거둔다.」 우리 집안 어른들은 노래처럼 외우셨지. 아무도 그날이 올 거라 믿지 않았고."},{"s":null,"t":"마당이 조용해졌다. 단비가 손가락을 하나씩 접으며 셌다."},{"s":"red_moon_cult:danbi","t":"그러니까… 일곱 장마다 이 칸이 있고, {이름} 님이 일곱 장을 다 이어야 하고, 그래야 맹약 마당에서 진을 풀 수 있다는 거예요?"},{"s":"southern_remnant:galmae","t":"근데 정리관 그놈은 장을 모아 오면 정청이 지켜 주겠다고 했잖아. 지켜 준다는 놈이 왜 장서각에 불을 질러."},{"s":"north_league:yeo","t":"장서각 불은 정청 안에서 났소. 조사원이 그 서고에서 그림자 흐린 자의 뒷모습을 봤다 하지 않았소."},{"s":"q:r71_seoharam","t":"장 하나라도 타면… 이을 수가 없어요. 첫째 장 반쪽에 먹이 안 앉는 것처럼요. 지키려고 장을 모으는 사람이, 장이 있는 서고에 불이 나게 둘까요? …관측한 것만 말할게요. 그 사람 가까이에서 장이 탔어요. 아직은 그게 다예요."},{"s":null,"t":"서하람의 목소리가 끝으로 갈수록 떨렸다. 아무도 그 말을 아니라고 하지 못했다. 다만 누구도 그렇다고 못 박지도 않았다."},{"s":"q:sn_cheongpa","t":"그럼 우리가 할 일은… {이름} 님이 일곱 장을 다 잇게 하는 거네요. 그 사람이 태우기 전에. 하나 찾았어요. 여섯 남았어요."},{"s":"southern_remnant:galmae","t":"일곱 장이 일곱 세력한테 하나씩 숨겨져 있으면, 우리 다섯 중에 하나만 빠져도 그 집 문은 안 열리겠네. …칼은 내가 들 테니까, 넌 붓이나 잃어버리지 마, 정청."},{"s":null,"t":"석진악이 금빛 장을 오래 바라보았다. 노인의 눈가가 젖어 있었다."},{"s":"north_league:seok","t":"…장은 이 사람이 지니게. 운비야, 너는 이 사람을 끝까지 따라가거라. 이번에는 돌아와서 내게 말하지 않아도 된다.","fac_not":"north_league","spec":2,"grp":1},{"s":"north_league:seok","t":"…장은 자네가 지니게. 북령의 장을 북령 사람이 잇게 되었으니, 그분도 덜 외로우시겠지. 운비야, 너는 이 사람을 끝까지 따라가거라. 이번에는 돌아와서 내게 말하지 않아도 된다.","fac":"north_league","spec":1,"grp":1},{"s":"north_league:yeo","t":"…따르겠습니다."},{"s":null,"t":"그때 산문 쪽에서 종이 땡땡 울렸다. 산문 지기 하나가 숨을 헐떡이며 뛰어왔다."},{"s":"q:md_gatekeeper","t":"맹주님! 산문 밖에 먹 낀 짐승들이 몰려듭니다! 장에서 금빛이 나자마자 고개 너머에서 줄줄이 내려옵니다!"},{"s":"north_league:hyegak","t":"허허, 금빛 냄새를 맡았나 봅니다. 손님들, 밥값을 마저 하셔야지요."}],"reward":{"xp":2570}},{"quest_id":"mdq_7","step":6,"title":"아궁이 앞","goal":"서리솔 고개에서 금빛을 보고 몰려온 종소리 먹은 늑대를 4번 쓰러뜨린다","need":{"at":["iron_monastery"],"tasks":[{"t":"win","n":4,"m":["dd_martial_4"],"r":["frost_pine_pass"]}]},"lines":[{"s":null,"t":"산문 밖에 몰려든 짐승들은 무관 거리에서 본 종소리 먹은 늑대였고, 정리관이 다녀간 뒤 젖은 발자국이 찍혔다던 산문 밖 우물가에서 먹물을 뒤집어쓴 채 올라오고 있었다."},{"s":null,"t":"짐승들을 고개 너머로 몰아내고 돌아왔을 때는 해가 산 뒤로 넘어간 뒤였다. 등도에서 나온 지 며칠이 지났지만, 길을 재촉하고 고찰 일을 하느라 밤하늘을 올려다볼 틈이 없었다."},{"s":null,"t":"청파가 하늘을 가리키며 펄쩍펄쩍 뛰었다. 고찰 위로 별이 가득 떠 있었다."},{"s":"q:sn_cheongpa","t":"별이다! 하람 형님, 별 좀 보세요! 흰 하늘만 보다 와서 그런가, 별이 이렇게 많은 줄 몰랐어요!"},{"s":"q:r71_seoharam","t":"…응. 별이네요. 이렇게 오래 올려다보는 건 오랜만이에요. 안녕."},{"s":null,"t":"서하람이 별을 향해 손을 흔들었다. 갈매가 그 꼴을 보고 혀를 차더니, 저도 곧 고개를 들어 한참 별을 보았다."},{"s":null,"t":"그 밤 산문 지기 하나가 서신 한 통을 가져왔다. 정청에서 북령 역참을 거쳐 온 한설의 서신이었다."},{"s":"night_office:han","t":"조사원. 등도에 들어갔다는 걸 봉인고 문지기에게 들었다. 살아서 나왔으면 이 서신을 받을 거다."},{"s":"night_office:han","t":"열 해 전 명부에 올랐는데 사라지지 않은 그 사람을 찾고 있다. 찢긴 도장 자리를 맞춰 볼 원본 명부가 어디 있는지 아직 모른다."},{"s":"night_office:han","t":"고친 보고서 셋도 다 찾았다. 셋 다 같은 손이고, 고친 글씨에는 먹이 두 번 앉아 있다. 그걸 알아보는 법은 내가 첫 보고서를 쓰던 날 배웠다."},{"s":"night_office:han","t":"그날 그 말을 해 준 분일 리는 없다. 그분은 남의 글씨에 손대는 걸 누구보다 싫어하셨다. …그런데 두 번 앉은 먹 자국이 그분이 내게 쥐여 준 붓 자국과 닮았다. 그래서 자꾸 다시 본다. 틀렸으면 좋겠다."},{"s":"night_office:han","t":"장은 몸에서 떼지 마라. 다섯 다 데리고 다녀라."},{"s":null,"t":"서신을 다 읽자 갈매가 콧방귀를 뀌었다."},{"s":"southern_remnant:galmae","t":"틀렸으면 좋겠대. 감찰관도 짚이는 데가 있는 거야."},{"s":"red_moon_cult:danbi","t":"알아도 말하기 싫은 사람이 있잖아요. 저도 그래요."},{"s":null,"t":"단비는 그 말을 하고 별을 올려다보았다. 교주님 천막 이야기를 들은 뒤로 단비는 엿을 하나도 먹지 않았다."},{"s":null,"t":"다들 잠자리에 든 뒤, 여운비가 아궁이 앞에 혼자 앉아 있었다. 사당 쪽 창호지에 등잔 불빛이 어른거렸다."},{"s":null,"t":"내가 곁에 앉자 여운비가 부지깽이로 불씨를 뒤적였다. 한참 만에 여운비가 입을 열었다."},{"s":"north_league:yeo","t":"어릴 때 사당 위패 하나가 비어 있는 걸 보고 아버지께 여쭸소. 누구 자리냐고. 대답 대신 뺨을 맞았소."},{"s":"north_league:yeo","t":"그 뒤로는 안 물었소. 대신 집안 어른들이 그 자리 앞을 지날 때마다 고개를 돌리는 걸 봤소. 아무도 그 앞에 향을 안 피웠소."},{"s":null,"t":"나는 그래서 호송대장이 되었냐고 물었다. 여운비가 부지깽이를 멈추었다."},{"s":"north_league:yeo","t":"그건 아니오. …아니, 그럴지도 모르겠소. 남의 길을 봐 주는 일은 묻지 않아도 되오. 바람만 보면 되오."},{"s":null,"t":"여운비가 칼자루 끝의 붉은 술을 손가락에 감았다. 아궁이 바람에 술 끝이 살랑 흔들렸다."},{"s":"north_league:yeo","t":"이 술은 아버지가 달아 주신 거요. 처음 호송을 나가던 날. 「사람은 보지 말고 바람을 봐라」 하시면서."},{"s":"north_league:yeo","t":"사람을 보면 묻고 싶어진다는 뜻이었을 거요. 묻지 말라는 뜻이었소."},{"s":null,"t":"나는 여운비에게 오늘은 물었고, 대답도 들었다고 했다. 여운비가 나를 보았다."},{"s":"north_league:yeo","t":"…그렇소. 당신 덕이오. 당신이 종루까지 따라 올라오지 않았으면, 나는 그 쇠머리를 혼자 보고 혼자 묻었을 거요. 얼음 앞에서도 그 이름을 못 불렀을 거요."},{"s":null,"t":"여운비가 일어서더니 허리춤에서 작은 칼을 뽑아 손바닥에 올려 보였다. 그것은 나무를 깎을 때 쓰는 날이었다."},{"s":"north_league:yeo","t":"사당에 다녀오겠소. 할 일이 하나 남았소. …문밖에서 기다려 주겠소? 혼자 들어가면 못 나올 것 같소."}],"reward":{"xp":2570}},{"quest_id":"mdq_7","step":7,"title":"새긴 이름","goal":"철벽 고찰 사당 문밖에서 기다리며 쉰다","need":{"at":["iron_monastery"],"tasks":[{"t":"rest","r":["iron_monastery"],"n":1}]},"lines":[{"s":null,"t":"사당 문밖에서 기다리는 동안 안에서 칼끝으로 나무를 긁는 소리가 들려왔다. 사각, 사각, 한 획 한 획을 아주 느리게 긋는 소리였다."},{"s":null,"t":"새벽녘에 사당을 나온 여운비의 손에는 나무 부스러기가 묻어 있었다. 열린 문틈으로 안을 보니, 깎여 있던 위패 자리에 「여사온」 세 글자가 새로 새겨져 있었다."},{"s":null,"t":"칼로 새긴 글씨는 삐뚤삐뚤했지만 깊었다. 위패 앞에는 향 한 대가 꽂혀 연기를 올리고 있었다."},{"s":null,"t":"어느새 석진악이 사당 앞에 서 있었다. 노인은 새로 새긴 글씨를 보고, 이어서 여운비를 보았다."},{"s":null,"t":"노인이 아무 말 없이 큰 손을 여운비의 어깨에 얹었다. 그 손은 오래도록 떨어지지 않았다."},{"s":"north_league:seok","t":"…잘했다. 내가 못 한 일을 네가 했구나."},{"s":null,"t":"고찰을 떠나는 아침이었다. 산문 앞에서 혜각이 일행마다 주먹밥 하나씩을 쥐여 주었다. 갈매 몫은 두 개였다."},{"s":"north_league:hyegak","t":"허허, 남명 정찰대장은 누룽지를 못 드셨으니 하나 더."},{"s":"southern_remnant:galmae","t":"…다음엔 안 넘어갈 거야."},{"s":"north_league:hyegak","t":"다음에도 넘어가실 겁니다. 웃으면서요."},{"s":null,"t":"단비가 여운비 곁으로 다가갔다. 장난스러운 얼굴이 아니었다. 단비가 품에서 엿 하나를 꺼내 여운비 손바닥에 올려놓았다."},{"s":"red_moon_cult:danbi","t":"단 걸 먹으면 생각이 좀 덜 나요. 바람 대신이에요."},{"s":null,"t":"여운비가 엿을 내려다보았다. 돌려주려고 손을 내밀다가 그 손을 도로 거두었다. 여운비는 엿을 입에 넣고 한동안 말없이 오물거렸다."},{"s":"north_league:yeo","t":"…나쁘지 않소."},{"s":null,"t":"단비가 눈을 동그랗게 뜨더니, 이내 소리 내어 웃음을 터뜨렸다. 북쪽 바람이 그 웃음소리를 멀리까지 실어 갔다."},{"s":"q:sn_cheongpa","t":"대장 누님이 단비 누님한테 칭찬했어요! 하람 형님, 이거 적어 두세요!"},{"s":"q:r71_seoharam","t":"벌써 적었어요… 「북령, 적월에게 나쁘지 않음」."},{"s":null,"t":"단비가 웃음을 그치고 산문 밖 서쪽 길을 바라보았다. 웃음기가 천천히 가셨다."},{"s":"red_moon_cult:danbi","t":"다음은 우리 적월 장이에요. 근데 저도 그게 어디 있는지 몰라요. 교주님은 늘 「반쯤 달에 먹혔다」고만 하시고요."},{"s":"red_moon_cult:danbi","t":"정리관이 교주님 천막에 반나절이나 있었다잖아요. 이대로 가 봤자 교주님은 저한테 아무 말도 안 해 주실 거예요. 저는 무녀일 뿐이니까요."},{"s":"north_league:yeo","t":"그럼 어떻게 하겠소."},{"s":"red_moon_cult:danbi","t":"등도에 북령 구역이 있었으니까 적월 구역도 있었을 거예요. 옛날 적월이 맹약 때 뭘 맡았는지 거기 적혀 있겠죠. 그걸 들고 가야 교주님이 입을 여실 거예요."},{"s":"q:r71_seoharam","t":"별 기록으로 보면… 등도 서쪽이에요. 무관 거리에서 해 지는 쪽이요."},{"s":"north_league:seok","t":"서쪽이라. 정리관도 서쪽으로 갔네. 조심들 하게. 그자는 늘 한 걸음 앞에 있어."}],"reward":{"xp":2570,"gil":480,"items":{"white_night_frost":3,"ember_ash_pill":2}}},{"quest_id":"mdq_8","step":1,"title":"거꾸로 건 등","goal":"붉은 사당 골목에 도착해 거꾸로 건 등을 본다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"travel","r":["red_shrine_lane"],"n":1}]},"lines":[{"s":null,"t":"붉은 사당 골목은 흰 도성 안에서도 유난히 이상한 곳이었다. 다른 구역은 모두 빛깔이 빠졌는데, 이 골목 담벼락에만 붉은 칠이 희미하게 남아 있었다. 핏자국이 마르다 만 것 같은 빛깔이었다."},{"s":null,"t":"처마마다 등롱이 거꾸로 걸려 있었다. 불 넣는 입구가 모두 땅을 향해 있었다."},{"s":null,"t":"등롱 아래 돌바닥마다 기름 얼룩이 둥글게 번져 있었다. 냄새 없던 이 땅에서 처음으로 오래 묵은 기름 냄새가 코끝을 맴돌았다."},{"s":null,"t":"청파가 에취, 하고 재채기를 했다."},{"s":"q:sn_cheongpa","t":"냄새가 나요! 등도 안에서 냄새 맡은 거 처음이에요!"},{"s":null,"t":"골목 어귀에서 단비가 걸음을 멈췄다. 단비의 얼굴에서 웃음이 사라졌다. 단비가 올려다본 등롱 옆구리에 붉은 초승달 문양이 찍혀 있었다."},{"s":"red_moon_cult:danbi","t":"이건 적월 문양이에요. 근데 지금 쓰는 거랑 달라요. 보세요, 달이 거꾸로 누워 있잖아요. 옛날 축문책 맨 앞장에서나 본 모양이에요.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:danbi","t":"교도님도 보이시죠? 우리 문양이에요. 근데 교도님 손목에 찬 거랑 달라요. 달이 거꾸로 누워 있잖아요. 옛날 축문책 맨 앞장에서나 본 모양이에요.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"{등급}님도 보이시죠? 우리 문양이에요. 근데 {등급}님 손목에 찬 거랑 달라요. 달이 거꾸로 누워 있잖아요. {등급}님은 옛날 축문책에서 이런 거 보신 적 있으세요?","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"장로님, 이거 보세요. 우리 문양인데 달이 거꾸로 누워 있어요. 옛날 축문책 맨 앞장에서나 본 모양이에요. 장로님은 이런 거 보신 적 있으세요?","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"단비가 거꾸로 매달린 등롱 하나를 두 손으로 받쳐 바로 세웠다. 등롱 바닥에서 말라붙은 기름 찌꺼기가 툭 떨어졌다."},{"s":null,"t":"단비가 그것을 손가락으로 비벼 냄새를 맡더니 얼굴이 하얗게 질렸다."},{"s":"red_moon_cult:danbi","t":"등에 넣는 기름이에요. 지금 적월 사당에서 쓰는 거랑 냄새가 똑같아요. 여기 사람들은… 도성 등에 기름을 대던 사람들이었나 봐요. 적월 사람들이요."},{"s":"north_league:yeo","t":"등을 거꾸로 건 건 무슨 뜻이오?"},{"s":"red_moon_cult:danbi","t":"적월에서는 상을 당한 집이 등을 거꾸로 걸어요. 불을 안 켜겠다는 뜻으로요."},{"s":null,"t":"단비의 목소리가 조금 떨렸다. 여운비가 단비 쪽으로 한 걸음 다가섰다. 단비는 웃어 보이려다 그만두었다."},{"s":null,"t":"갈매가 바닥에 굴러다니는 등롱 하나를 발로 툭 찼다. 등롱이 데굴데굴 굴러가 담벼락에 부딪혔다. 갈매가 그것을 다시 주워 처마 밑에 세워 놓았다."},{"s":"southern_remnant:galmae","t":"…괜히 찼다. 상갓집이라며."},{"s":null,"t":"서하람은 골목을 따라 걸으며 등롱 수를 셌다. 한참 세던 서하람이 손가락을 내렸다."},{"s":"q:r71_seoharam","t":"거꾸로 건 등이 이백 하고도 열넷이에요. 이 골목 집 수랑 같아요. 집집마다 하나씩, 다 상을 당한 거예요."},{"s":null,"t":"단비가 골목 안쪽을 바라보았다. 골목 끝에 붉은 지붕이 하나 보였다."},{"s":"red_moon_cult:danbi","t":"저 끝에 사당이 있을 거예요. 적월 골목엔 늘 끝에 사당이 있어요. 거기 가면 옛날 서약이 적혀 있을 거예요. 근데 길이 기름 범벅이라… 먹 묻은 것들도 득실거리고요."},{"s":"north_league:yeo","t":"길부터 트고 갑시다. 무녀는 내 뒤에 서시오."},{"s":"red_moon_cult:danbi","t":"어머, 대장님이 저를 지켜 주시는 거예요?"},{"s":"north_league:yeo","t":"앞에 서면 방울 소리에 귀가 아프오."}],"reward":{"xp":3120}},{"quest_id":"mdq_8","step":2,"title":"엿 다섯 개","goal":"붉은 사당 골목을 4번 탐색하고 요괴를 3번 쓰러뜨린다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"search","r":["red_shrine_lane"],"n":4},{"t":"win","n":3,"r":["red_shrine_lane"]}]},"lines":[{"s":null,"t":"길을 트고 나니 골목 끝 사당 앞에 닿았다. 사당 문짝은 반쯤 떨어져 나가 있었다. 안을 들여다보자 사방 벽이 시커멓게 번들거렸다."},{"s":null,"t":"벽마다 기름때가 두껍게 앉아 있었다. 손톱으로 긁자 기름때 아래에 붉은 글씨가 언뜻 비쳤다."},{"s":"red_moon_cult:danbi","t":"축문이에요. 벽 전체가 축문이에요. 근데 기름때 때문에 하나도 안 보여요."},{"s":"q:sn_cheongpa","t":"수향에선 배 밑창 기름때를 잿물로 닦아요. 잿물이랑 짚 수세미만 있으면 다 벗겨져요!"},{"s":null,"t":"서하람은 기름때에 먹이 배어 있어 잿물만으로는 안 벗겨질 거라며, 영유리를 녹여 거른 청정수에 재를 풀자고 했다."},{"s":null,"t":"청파가 신이 나서 소매를 걷어붙였다. 단비가 그런 청파를 보다가 품에서 엿 꾸러미를 꺼냈다."},{"s":"red_moon_cult:danbi","t":"청소하기 전에 기운 내야죠. 하나씩 나눠 드릴게요. 대신 제가 붙여 드리는 별명을 받으셔야 해요."},{"s":"southern_remnant:galmae","t":"별명은 무슨…"},{"s":null,"t":"단비는 대꾸할 틈도 주지 않고 엿을 하나씩 내밀었다. 맨 처음은 청파였다."},{"s":"red_moon_cult:danbi","t":"막내는 「물강아지」. 물만 보면 꼬리를 흔드니까."},{"s":"q:sn_cheongpa","t":"물강아지! 좋아요, 저 그거 할래요!"},{"s":"red_moon_cult:danbi","t":"관측관님은 「외상 별님」. 아직 엿값 안 갚으셨으니까요."},{"s":"q:r71_seoharam","t":"아… 철벽 고찰에서 별 봤으니까, 갚을게요. 이따가요."},{"s":null,"t":"단비가 갈매 앞에 섰다. 갈매가 팔짱을 낀 채 노려보았다."},{"s":"red_moon_cult:danbi","t":"갈매 씨는 「밤송이」. 겉은 가시투성이인데 속은 고소하니까요."},{"s":"southern_remnant:galmae","t":"누가 고소해! 확 그냥…"},{"s":null,"t":"갈매가 엿을 홱 낚아채 입에 넣었다. 볼이 불룩해져서 더는 따지지 못했다. 청파가 킥킥 웃다가 갈매에게 꿀밤을 맞았다."},{"s":null,"t":"단비가 여운비 앞에서는 엿을 두 손으로 내밀었다."},{"s":"red_moon_cult:danbi","t":"대장님은 「바람개비」. 바람만 찾아다니시잖아요."},{"s":"north_league:yeo","t":"…바람개비는 바람이 없으면 못 도오."},{"s":"red_moon_cult:danbi","t":"그러니까 제가 후 불어 드린다고요."},{"s":null,"t":"여운비가 엿을 받아 쥐고 고개를 돌렸다. 귀 끝이 빨갰다."},{"s":null,"t":"마지막으로 단비가 내 앞에 섰다. 단비가 엿을 내 손에 쥐여 주며 한참 내 얼굴을 보았다."},{"s":"red_moon_cult:danbi","t":"{이름} 님은 이제 「장부 손님」 말고 「등잔」이요. 다들 {이름} 님 쪽으로 모이니까요. 불 켜진 데로 사람이 모이잖아요."},{"s":null,"t":"단비는 그 말을 하고 얼른 돌아서 버렸다. 단비가 제 입에도 엿을 하나 넣고 사당 쪽을 보았다."},{"s":"red_moon_cult:danbi","t":"자, 이제 닦아요. 저 벽에 뭐가 적혀 있든 읽는 건 제가 할게요. 적월 글이니까요."}],"reward":{"xp":3120}},{"quest_id":"mdq_8","step":3,"title":"벽에 적힌 구절","goal":"붉은 사당 골목에서 5번 채집하고 청정수 3개를 만들어 벽을 닦을 물로 단비에게 넘긴다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"gather","n":5,"r":["red_shrine_lane"]},{"t":"craft","items":["purify_water"],"n":3}],"give":{"purify_water":3}},"lines":[{"s":null,"t":"청정수에 재를 푼 동이를 사당에 들여놓자 다 같이 벽에 달라붙었다."},{"s":null,"t":"갈매는 짚 수세미로 벽을 박박 문질렀다. 너무 세게 문질러 수세미가 금세 닳았다. 청파는 우물과 사당을 오가며 물동이를 날랐다."},{"s":null,"t":"여운비는 사다리 아래를 붙잡았다. 단비가 그 사다리에 올라 높은 데를 닦았다. 사다리가 기우뚱할 때마다 여운비가 두 손으로 꽉 붙들었다."},{"s":"red_moon_cult:danbi","t":"대장님, 흔들지 마세요!"},{"s":"north_league:yeo","t":"무녀가 흔드는 거요. 가만히 좀 계시오."},{"s":null,"t":"서하람은 벽 앞에 두루마리를 펴고 드러나는 글자를 한 자씩 옮겨 적었다. 나는 서하람이 적는 손을 따라가며 기름때를 닦아 냈다."},{"s":null,"t":"기름때가 벗겨지자 붉은 축문이 벽 가득 드러났다. 단비가 사다리에서 내려와 벽 앞에 섰다."},{"s":null,"t":"단비가 축문을 소리 내어 읽기 시작했다. 적월 무녀라면 누구나 외우는 대목이라 처음 몇 줄은 막힘없었다."},{"s":null,"t":"몇 줄을 더 읽자 단비의 목소리가 눈에 띄게 느려졌다. 축문이 단비가 알던 것과 거꾸로 흘러가고 있었다."},{"s":"red_moon_cult:danbi","t":"이상해요. 우리 서약은 「거둔 이름을 받아 힘으로 삼는다」로 끝나거든요. 근데 여기는 거꾸로예요. 「거둔 이름은 달빛 아래 보내되, 그 이름으로 힘을 삼지 않는다.」","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:danbi","t":"교도님도 입교할 때 외우셨죠? 「거둔 이름을 받아 힘으로 삼는다.」 근데 여기는 거꾸로예요. 「거둔 이름은 달빛 아래 보내되, 그 이름으로 힘을 삼지 않는다.」","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"{등급}님도 입교할 때 외우셨죠? 「거둔 이름을 받아 힘으로 삼는다.」 근데 여기는 거꾸로예요. 「거둔 이름은 달빛 아래 보내되, 그 이름으로 힘을 삼지 않는다.」","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"장로님, 우리 서약 끝 구절 아시죠? 「거둔 이름을 받아 힘으로 삼는다.」 근데 여기는 거꾸로예요. 「거둔 이름은 달빛 아래 보내되, 그 이름으로 힘을 삼지 않는다.」","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"마지막 구절까지 읽고도 단비는 벽에서 눈을 떼지 못했다. 「삼지 않는다」 네 글자 위에 얹은 손가락이 바들바들 떨렸다."},{"s":"red_moon_cult:danbi","t":"…우리가 거꾸로 외운 거예요. 이게 원래 서약이었어요."},{"s":null,"t":"여운비가 사다리를 놓고 다가와 단비 곁에 섰다. 벽과 단비 사이를 막아 주려는 듯한 자리였다. 여운비는 아무 말도 하지 않았다."},{"s":null,"t":"청파가 물동이를 든 채로 굳어 있었다. 갈매가 수세미를 내려놓았다."},{"s":"southern_remnant:galmae","t":"너네 서약이 거꾸로면… 너네가 지금까지 태운 이름들은 다 뭐야."},{"s":null,"t":"단비는 대답하지 못했다. 갈매가 무어라 더 쏘아붙이려다, 단비의 얼굴을 보고는 입을 다물었다."},{"s":null,"t":"나는 홍인사 때 월식성 제단을 떠올렸다. 붉은 실 이백세 가닥이 이름을 묶고 떠올라 있던 밤이었다. 그 이름들도 이 거꾸로 된 축문으로 바쳐졌을 것이었다."},{"s":null,"t":"제단 아래 돌 궤짝이 하나 놓여 있었다. 내가 무거운 뚜껑을 밀어내자 끈으로 묶은 종이 다발이 나왔다."},{"s":null,"t":"맨 위 장에 「서약에 쓸 이름」이라고 적혀 있었다. 이름 아래마다 날짜와 값이 붙어 있었다."},{"s":null,"t":"마지막 장에는 붉은 인장이 찍혀 있었다. 인장 테두리에 「정리소 서리」라는 글자가 둘러져 있었다. 그 장의 오른쪽 위 모서리가 반듯하게 접혀 있었다."},{"s":"q:r71_seoharam","t":"정리소 서리… 관아 셈표를 짠 그 사람이에요. 모서리 접는 것도 똑같아요."},{"s":null,"t":"단비가 다발을 받아 들었다. 접힌 모서리를 손끝으로 펴 보다가 단비의 손이 멈추었다."},{"s":"red_moon_cult:danbi","t":"…이거 본 적 있어요. 교주님 천막에서요. 해마다 동지 무렵이면 이렇게 모서리 접힌 종이 묶음이 들어와요. 교주님이 저희한텐 안 보여 주셨지만요."},{"s":"north_league:yeo","t":"그자가 백 년 동안 적월에 이름을 대 왔다는 얘기요?"},{"s":"red_moon_cult:danbi","t":"모르겠어요. 모르겠어요, 대장님."},{"s":null,"t":"그때 궤짝 바닥에서 사르륵 종이 넘어가는 소리가 났다. 다발 밑에 깔려 있던 장부들이 저절로 한 장씩 넘어가고 있었다."},{"s":null,"t":"장부 낱장이 바람도 없는데 궤짝 밖으로 펄럭펄럭 날아올랐다. 사당 마룻바닥 틈에서도 누렇게 바랜 장부가 줄줄이 기어 나왔다. 낱장마다 이름 하나, 그 아래 붉은 엄지 도장과 값이 하나씩 적혀 있었다."},{"s":"q:sn_cheongpa","t":"바닥 밑이 다 장부예요! 사당 밑이 곳간이었나 봐요!"},{"s":null,"t":"날아오른 낱장들이 철썩철썩 서로 들러붙었다. 금세 사람 키를 두 배는 넘는 덩어리가 사당 한가운데 우뚝 섰다. 비늘처럼 겹친 낱장 사이로 주판알이 이빨처럼 박힌 입이 쩍 벌어졌다."},{"s":null,"t":"덩어리가 입을 열 때마다 주판알이 딸깍딸깍 부딪쳤다. 그 소리 사이로 쉰 목소리가 같은 말을 되풀이했다."},{"s":null,"t":"「한 줄에 쌀 두 섬. 한 줄에 쌀 두 섬. 값을 치르면 도장을 찍어 주지.」"},{"s":"southern_remnant:galmae","t":"장부가 일어섰어… 저게 뭐야!"},{"s":"red_moon_cult:danbi","t":"이름을 사고판 장부들이에요. 적월이 백 년 동안 사들인 이름이 다 저기 적혀 있어요. 저게… 값을 먹고 컸나 봐요."},{"s":"red_moon_cult:danbi","t":"교에서 겁줄 때 하던 얘기가 있어요. 값만 매기고 이름은 잊은 장부는 언젠가 일어나 걷는다고요. 「값귀」라고 불렀어요. 진짜 있을 줄은 몰랐어요."},{"s":null,"t":"덩어리의 비늘 한 장이 툭 떨어져 내 발치에 내려앉았다. 낱장에는 「흑련 거둠꾼에게서 · 아이 이름 하나 · 쌀 세 섬」이라고 적혀 있었다. 날짜는 단비가 열네 살이던 해였다."},{"s":null,"t":"단비가 그 낱장을 보았다. 방울을 쥔 단비의 손이 하얗게 질렸다."},{"s":"north_league:yeo","t":"무녀, 뒤로 물러서시오. 다발은 관측관한테 맡기고."},{"s":null,"t":"단비가 종이 다발을 서하람에게 휙 던졌다. 서하람이 그것을 받아 품에 꼭 안았다."},{"s":"q:r71_seoharam","t":"받았어요! 그리고… 저거 머리 위 보세요. 우리 머리 위에도 숫자가 떴어요. 「쌀 여섯 섬」, 「쌀 세 섬」… 저게 우리 값을 매기고 있어요."},{"s":null,"t":"고개를 들자 정말로 저마다의 머리 위에 희미한 먹 글씨가 떠 있었다. 내가 한 걸음 내디디자 내 머리 위 글씨가 「쌀 일곱 섬」에서 「쌀 여덟 섬」으로 바뀌었다."},{"s":"q:r71_seoharam","t":"움직일 때마다 값이 바뀌어요. 저게 「짝수는 거둔다」 같은 걸 외치면 그때 값을 피해야 해요. 제가 셈을 불러 드릴게요!"},{"s":"southern_remnant:galmae","t":"셈은 네가 해. 나는 벤다. 다들 문 말고 저놈부터 둘러싸!"}],"reward":{"xp":3120}},{"quest_id":"mdq_8","step":4,"title":"값을 치른 장부","goal":"붉은 사당 골목에서 값귀를 쓰러뜨린다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"gg","mode":"story","n":1}]},"lines":[{"s":null,"t":"값귀가 마지막으로 「한 줄에 쌀 두…」 하다가 말을 잇지 못했다. 덩어리가 철퍼덕 무너지며 낱장이 눈보라처럼 사당 안에 흩날렸다."},{"s":null,"t":"흩날린 낱장이 바닥에 닿자 먹 글씨가 하얗게 바랬다. 이름도 값도 도장도 지워진 빈 종이만 남았다. 머리 위의 「섬」 글씨도 함께 사라졌다."},{"s":null,"t":"다들 숨을 헐떡이며 바닥에 주저앉았다. 갈매와 단비는 아직 등을 맞댄 채였다. 싸우는 내내 둘은 그 자리에서 앞뒤를 나눠 맡았다."},{"s":"southern_remnant:galmae","t":"등 붙이지 마, 끈적거려."},{"s":"red_moon_cult:danbi","t":"네. 근데 아까부터 안 떼시던데요."},{"s":null,"t":"갈매가 대꾸 없이 칼을 닦았다. 단비가 그런 갈매를 보며 웃었다. 오늘 들어 처음으로 눈까지 웃는 얼굴이었다."},{"s":null,"t":"청파가 빈 물동이를 엎어 놓고 그 위에 털썩 앉았다. 청파의 머리카락에 낱장 한 장이 붙어 있었다."},{"s":"q:sn_cheongpa","t":"「짝수는 거둔다」 할 때 저 진짜 죽는 줄 알았어요. 하람 형님이 「방어! 방어하면 일곱!」 안 외쳤으면요."},{"s":"q:r71_seoharam","t":"셈은… 원래 잘해요. 관측관이니까요. …근데 다음엔 청파가 먼저 세 봐."},{"s":null,"t":"여운비가 바닥의 빈 종이 한 장을 주워 들었다. 아까 내 발치에 떨어졌던 그 낱장이었다. 글씨는 다 바랬고 쌀 세 섬이라는 값만 희미하게 남아 있었다."},{"s":null,"t":"여운비가 그 종이를 말없이 접어 단비 손에 쥐여 주었다. 단비가 종이를 받아 들고 오래 내려다보았다."},{"s":"red_moon_cult:danbi","t":"…태운 이름은 안 떠오른다고 했잖아요. 근데 값은 남아 있네요. 이름은 잊고 값만 기억하는 장부라니. 우리가 딱 그랬어요."},{"s":"north_league:yeo","t":"오늘은 여기서 밤을 보냅시다. 축문을 다 옮겨 적으려면 관측관 손이 하루는 걸리겠소. 무녀도 좀 쉬어야 하고."},{"s":"q:r71_seoharam","t":"하루로는… 아, 아니에요. 하루면 돼요. 할게요."}],"reward":{"xp":3120}},{"quest_id":"mdq_8","step":5,"title":"열네 살의 서약","goal":"붉은 사당 골목 사당 처마 아래에서 야영으로 쉰다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"rest","r":["red_shrine_lane"],"n":1}]},"lines":[{"s":null,"t":"그 밤 사당 처마 아래에 불을 피웠다. 단비는 엿 꾸러미를 무릎에 올려놓았지만 하나도 꺼내 먹지 않았다."},{"s":null,"t":"다른 일행이 하나둘 누운 뒤에도 불 건너편의 여운비는 칼을 닦으며 깨어 있었다. 갈매는 벽을 향해 누워 있었다."},{"s":null,"t":"내가 곁에 앉았는데도 단비는 나를 보지 않았다. 단비는 거꾸로 매달린 등롱을 올려다보고 있었다."},{"s":"red_moon_cult:danbi","t":"{이름} 님. 아까 제가 별명 붙여 드렸잖아요. 「등잔」. 그거 사실은… 부러워서 붙인 거예요."},{"s":null,"t":"나는 무엇이 부러웠냐고 물었다. 단비가 무릎을 끌어안았다."},{"s":"red_moon_cult:danbi","t":"열네 살 때 처음 서약을 했어요. 무녀가 되려면 서약을 한 번 치러야 하거든요. 그러려면 이름이 하나 있어야 해요. 남의 이름이요. 그 이름을 태워야 축문이 처음 들려요.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:danbi","t":"교도님은 입교할 때 축문만 외우셨죠? 무녀는 달라요. 열네 살 때 처음 서약을 했는데, 무녀가 되려면 이름이 하나 있어야 해요. 남의 이름이요. 그 이름을 태워야 축문이 처음 들려요.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"{등급}님은 아시죠? 무녀는 교도랑 달라요. 열네 살 때 처음 서약을 했는데, 무녀가 되려면 이름이 하나 있어야 해요. 남의 이름이요. 그 이름을 태워야 축문이 처음 들려요.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"장로님은 다 아시겠지만… 열네 살 때 처음 서약을 했어요. 무녀가 되려면 이름이 하나 있어야 해요. 남의 이름이요. 그 이름을 태워야 축문이 처음 들려요.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"아까 그 낱장 보셨죠? 쌀 세 섬. 그게 제 열네 살이에요."},{"s":"red_moon_cult:danbi","t":"그 이름은 흑련에서 샀어요. 거둠꾼한테서요. 어느 아이 이름이었어요. 거둠꾼이 쪽지를 건네면서 손을 떨더라고요."},{"s":"red_moon_cult:danbi","t":"이상한 사람이라고 생각했어요. 이름을 팔면서 손을 떠는 거둠꾼은 처음 봤거든요."},{"s":null,"t":"단비가 오래 입을 열지 않았다. 불이 한 번 타닥 튀었다."},{"s":"red_moon_cult:danbi","t":"그 거둠꾼 이름이 월하예요. 장부고에서 손가락이 녹았다는 그 사람이요. 다온이 「아저씨」라고 부르는 사람."},{"s":null,"t":"나는 숨을 삼켰다. 장부고 침상에 누운 월하의 잿빛 손이 떠올랐다."},{"s":"red_moon_cult:danbi","t":"그 아이 이름은 기억이 안 나요. 태웠으니까요. 태운 이름은 다시는 안 떠올라요. 웃기죠. 그 이름 덕에 무녀가 됐는데, 정작 그 이름은 하나도 몰라요."},{"s":"red_moon_cult:danbi","t":"{이름} 님은 이름을 불러서 사람을 데워 주잖아요. 저는 이름을 태워서 무녀가 됐어요. 그래서 부러웠어요."},{"s":null,"t":"단비가 늘 그랬듯이 입꼬리를 올려 웃었지만, 이번에는 눈이 웃지 않았다. 입꼬리도 끝까지 올라가지 못했다."},{"s":null,"t":"나는 단비에게 열네 살이 고를 수 있는 일이 아니었다고 했다. 단비가 고개를 저으려 할 때였다."},{"s":null,"t":"벽을 보고 누워 있던 갈매가 벌떡 일어나 앉았다. 갈매는 자는 척을 하고 있었다."},{"s":"southern_remnant:galmae","t":"맞아. 열네 살이 뭘 알아. 시킨 놈들이 나쁜 거지."},{"s":"red_moon_cult:danbi","t":"…갈매 씨, 안 잤어요?"},{"s":"southern_remnant:galmae","t":"시끄러워서 깼어. 남명에선 열네 살이면 칼 쥐고 국경에 나가. 그거 내가 골랐냐? 아니야. 어른들이 정한 거야."},{"s":null,"t":"갈매가 엿 꾸러미를 휙 집어 단비 무릎에 도로 올려놓았다."},{"s":"southern_remnant:galmae","t":"그러니까 그거나 먹어. 너 엿 안 먹으니까 이상해. 소름 끼쳐."},{"s":null,"t":"단비가 엿 꾸러미를 내려다보았다. 한참 만에 단비가 엿 하나를 꺼내 입에 넣었다. 단비의 볼을 타고 눈물이 주르륵 흘렀다."},{"s":"red_moon_cult:danbi","t":"…밤송이 맞네요. 속이 고소해요."},{"s":"southern_remnant:galmae","t":"시끄러."},{"s":null,"t":"불 건너편에서 칼을 닦던 여운비가 손을 멈추고, 칼을 칼집에 넣은 뒤 말없이 일어났다."},{"s":null,"t":"여운비가 단비 등 뒤로 와서 제 망토를 벗어 단비 어깨에 덮어 주었다. 깜짝 놀란 단비가 돌아보았을 때, 여운비는 벌써 제자리로 돌아가 앉아 있었다."},{"s":null,"t":"단비가 망토 깃을 손으로 꼭 여몄다. 아무도 더 말하지 않았고, 청파가 자는 척하며 훌쩍이는 소리만 났다."},{"s":null,"t":"한참 뒤에 서하람이 두루마리를 들고 일어나 앉았다. 서하람은 자지 않고 축문 끝줄을 옮겨 적고 있었다."},{"s":"q:r71_seoharam","t":"단비 씨. 축문 끝에 한 줄 더 있어요. 「서약을 바로 돌릴 때는 골목 끝 곳간의 첫 기름으로 등을 켠다.」"},{"s":"red_moon_cult:danbi","t":"첫 기름이요? …그게 남아 있으면 교주님께 가져가야 해요. 원래 서약대로 하려면요."},{"s":"north_league:yeo","t":"곳간이 어디 있는지 아시오?"},{"s":"q:r71_seoharam","t":"골목 끝에서 더 서쪽이래요. 축문엔 「해 지는 쪽 담장 너머」라고만…"},{"s":"north_league:yeo","t":"먼 길이겠구려. 일어나면 다녀옵시다."}],"reward":{"xp":3120}},{"quest_id":"mdq_8","step":6,"title":"첫 기름","goal":"붉은 사당 골목으로 원정을 한 번 끝까지 다녀와 해 지는 쪽 담장 너머 기름 곳간을 찾는다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"expedition","r":["red_shrine_lane"],"n":1}]},"lines":[{"s":null,"t":"기름 곳간은 무너진 담장 너머에 반쯤 묻혀 있었다. 항아리 백여 개가 줄지어 있었는데, 거의 다 깨져 바닥에 기름 자국만 남아 있었다."},{"s":null,"t":"맨 안쪽 구석에 항아리 하나만 금 없이 남아 있었다. 뚜껑에 붉은 초승달이 거꾸로 찍혀 있었다. 단비가 뚜껑을 열자 맑은 기름이 찰랑였다."},{"s":null,"t":"단비는 항아리를 끌어안고 한동안 일어나지 않았다. 기름 냄새가 곳간 가득 퍼졌다."},{"s":"red_moon_cult:danbi","t":"이 골목 사람들이 끊은 기름이에요. 그날 밤에요. 그래서 도성 등이 하나씩 낮아졌을 거예요. 근데 이 항아리 하나는… 누가 끝까지 안 깨고 남겨 뒀어요."},{"s":"q:sn_cheongpa","t":"언젠가 다시 켜려고요?"},{"s":"red_moon_cult:danbi","t":"…그랬으면 좋겠어요."},{"s":null,"t":"항아리를 들고 사당 골목으로 돌아왔을 때였다. 골목 어귀에 두 사람이 서 있었다."},{"s":null,"t":"하나는 붉은 무복을 입은 적월 심부름꾼이었다. 하얗게 바랜 땅 위에서 붉은 무복 한 벌이 핏방울처럼 도드라져 보였다."},{"s":null,"t":"다른 하나는 검은 두건을 쓴 사내였다. 사내가 우리를 보고 손가락 여섯 개를 펴 보였다. 그 사내는 흑련 채무 추적자 여섯째였다."},{"s":"black_lotus:six","t":"서신 하나. 다온. 길 안내 하나. 적월 사람. 수로 셋째 갈림에서 헤매고 있었음."},{"s":null,"t":"여섯째가 서신을 내게 내밀었다. 서신은 삐뚤빼뚤한 아이 글씨로 적혀 있었다. 나는 소리 내어 읽었다."},{"s":"q:mk_daon","t":"{이름} 님. 아저씨는 아직 안 깼어요. 그래도 잿빛이 팔꿈치에서 안 올라와요. 아침마다 제가 「아저씨」 하고 불러요. 구슬 누나도 같이 불러 줘요."},{"s":"q:mk_daon","t":"어젯밤엔 아저씨가 잠꼬대로 「꼬맹이, 엿 사 와」 했어요. 그래서 엿을 사 왔는데 아저씨가 못 먹어서 제가 먹었어요. 구슬 누나가 셈으로 치면 반은 아저씨 거래요. 그래서 반은 남겨 뒀어요."},{"s":"q:mk_daon","t":"곶감 준 정리관 아저씨가 장부고 앞까지 왔다가 그냥 갔어요. 구슬 누나가 문을 안 열어 줬어요. 그 아저씨 신발이 젖어 있었어요. 비도 안 왔는데요."},{"s":"q:mk_daon","t":"{이름} 님, 글자 연습 많이 했어요. 묵창 나루에서 아저씨가 노잣돈 주면서 이자는 글 배워서 갚으라고 했잖아요. 아저씨 깨면 이자 다 갚은 거 보여 줄 거예요. 이 편지 다 제가 썼어요. 안 까먹으려고 {이름} 님 이름도 맨 위에 썼어요."},{"s":null,"t":"청파가 코를 훌쩍였다. 단비는 「아저씨」라는 말이 나올 때마다 눈을 감았다."},{"s":"red_moon_cult:danbi","t":"…월하 씨요. 손가락이 녹았다는 그 손으로, 열네 살 저한테 쪽지를 건넸어요. 그 사람이 지금 저렇게 누워 있네요."},{"s":null,"t":"적월 심부름꾼이 단비 앞에 나와 섰다. 등도까지 내려오느라 기진한 얼굴이었다."},{"s":"q:md_red_runner","t":"주홍 무녀님. 봉인고 문지기한테 물어 물길로 따라왔습니다. 교주님께서 무녀님과 정청 조사원을 함께 부르십니다. 급히요.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"q:md_red_runner","t":"주홍 무녀님, 교도님도 계셨군요. 봉인고 문지기한테 물어 물길로 따라왔습니다. 교주님께서 무녀님과 정청 일을 맡은 교도님을 함께 부르십니다. 급히요.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"q:md_red_runner","t":"주홍 무녀님, {등급}님까지 계셨군요. 봉인고 문지기한테 물어 물길로 따라왔습니다. 교주님께서 무녀님과 {등급}님을 함께 부르십니다. 급히요.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"q:md_red_runner","t":"주홍 무녀님, 장로님까지 계셨군요. 봉인고 문지기한테 물어 물길로 따라왔습니다. 교주님께서 무녀님과 장로님을 함께 부르십니다. 급히요.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":"red_moon_cult:danbi","t":"교주님이 왜 갑자기… 무슨 일이 있어요?"},{"s":"q:md_red_runner","t":"교주님 손등의 잿빛이 손목을 넘었습니다. 대호법께서 교주님 곁을 한시도 안 떠나십니다. 그 이상은 저도 모릅니다."},{"s":null,"t":"단비의 얼굴에서 핏기가 가셨다. 단비가 기름 항아리를 꼭 끌어안았다."},{"s":"red_moon_cult:danbi","t":"교주님 몸 안에 무언가 있어요. 무녀들끼리는 다 알아요. 「반쯤 달에 먹혔다」는 게 그냥 하는 말이 아니에요. 그게… 우리 장인 것 같아요."},{"s":"red_moon_cult:danbi","t":"이 축문이랑 첫 기름이랑 「서약에 쓸 이름」 다발이랑, 다 들고 가요. 우리가 백 년 동안 거꾸로 외웠다고, 교주님께 말씀드려야 해요."},{"s":"q:sn_cheongpa","t":"그럼 둘째로 이을 장이네요. 손가락 일곱 개 다 접을 때까지 제가 셀게요."},{"s":null,"t":"여운비가 칼을 허리에 차며 일어섰다. 단비 쪽은 보지 않은 채였다."},{"s":"north_league:yeo","t":"같이 가겠소. 대호법이 또 칼을 두고 들어오라 하겠지만."},{"s":"southern_remnant:galmae","t":"나도 가. 그 정리관이 교주 천막에 반나절 있었다며. 무슨 수작인지 봐야지."},{"s":"red_moon_cult:danbi","t":"의식에는 붉은 실이 있어야 해요. 원래 서약대로 하려면 축문 실을 새로 꼬아야 하고요. {이름} 님, 도와주실래요?"},{"s":null,"t":"적월 축문 실은 부적실을 붉은 사당 옻에 물들여 꼬는 것이라, 나는 부적실부터 지어 단비에게 건네기로 했다."}],"reward":{"xp":3120,"gil":490,"items":{"severed_lamp_oil":2,"red_shrine_lacquer":2}}},{"quest_id":"mdq_9","step":1,"title":"면사포","goal":"의식에 쓸 부적실 3개를 지어 단비에게 넘기고 백골 장터에 도착한다","need":{"at":["bone_market"],"tasks":[{"t":"craft","items":["talisman_thread"],"n":3},{"t":"travel","r":["bone_market"],"n":1}],"give":{"talisman_thread":3}},"lines":[{"s":null,"t":"백골 장터는 밤인데도 붉었다. 천막마다 붉은 천이 늘어졌고, 그 사이로 향 연기가 낮게 흘렀다. 짐승 뼈를 엮은 풍경이 달그락달그락 울었다."},{"s":null,"t":"교주의 방은 장터 맨 안쪽에 있었다. 붉은 천막을 몇 겹이나 지나야 닿았다. 천을 하나 걷을 때마다 향 연기가 짙어져, 마지막 천막에 들어섰을 때는 눈이 따끔거렸다."},{"s":null,"t":"마지막 천막 앞에서 누군가 막 나오고 있었다. 그 사람은 회색 두건을 쓰고 빈 보따리를 들고 있었다. 붉은 등불 아래인데도 그 사람의 그림자만 반쯤 흐릿했다."},{"s":null,"t":"그 사람이 우리를 보고 고개를 푹 숙인 채 옆으로 비켜 지나갔다. 지나간 자리에 젖은 먹 냄새가 남았다."},{"s":null,"t":"단비가 그 뒷모습을 보다가 내 팔을 꽉 잡았다. 단비의 손가락이 차가웠다."},{"s":"red_moon_cult:danbi","t":"저 사람… 저 사람들이에요. 해마다 동지 무렵에 그 접힌 종이 묶음을 들고 오던 사람들이요. 늘 그림자가 흐리고, 늘 장터 우물 쪽으로 사라졌어요."},{"s":"southern_remnant:galmae","t":"무관 거리 우물에서 빠져나간 놈이랑 같은 놈들이야. 쫓아갈까?"},{"s":"north_league:yeo","t":"지금은 안 되오. 교주를 먼저 만나야 하오."},{"s":null,"t":"갈매가 이를 갈며 돌아섰지만, 그 사람은 벌써 천막 사이로 사라지고 없었다."},{"s":null,"t":"천막 입구를 거한 하나가 막아섰다. 거한은 대호법 사마겸이었다. 사마겸이 단비를 내려다보고, 이어서 나를 오래 보았다."},{"s":"red_moon_cult:sama","t":"살아 돌아왔구나, 단비. 그리고 너. 월식성에서 파계장을 눕히던 그 조사원이로군. 강한 자는 그런 데서 죽기 아깝다고 내보내 줬더니, 이번엔 제 발로 교주님 천막을 찾아왔어.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:sama","t":"살아 돌아왔구나, 단비. 그리고 교도. 정청 일을 들고 등도까지 다녀왔다지. 강한 자는 어디서든 강하구나.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"살아 돌아왔구나, 단비. {등급}께서도 무사하셨군. 등도까지 다녀오셨다니, 역시 강한 분이오.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"살아 돌아왔구나, 단비. 장로님도 무사히 돌아오셨군요. 등도까지 다녀오셨다니 역시 장로님이십니다.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"교주님 앞에선 칼을 풀어라. 북령 칼도, 남명 칼도."},{"s":"southern_remnant:galmae","t":"싫은데."},{"s":"red_moon_cult:sama","t":"그럼 들어오지 마라. 약한 개는 짖고, 강한 개는 칼을 풀고 들어오는 법이다."},{"s":null,"t":"갈매가 이를 갈았다. 여운비가 먼저 칼을 풀어 사마겸 앞에 내려놓았다. 갈매가 한참 노려보다가 제 칼을 그 옆에 쾅 내려놓았다."},{"s":null,"t":"월화는 붉은 면사포를 쓴 채 앉아 있었다. 방 안의 촛불이 모두 월화 쪽으로 기울어 있었다. 바람 때문이 아니었다. 월화의 가슴께에서 무언가가 불꽃들을 끌어당기고 있었다."},{"s":null,"t":"단비가 무릎을 꿇었다. 단비는 사당 축문을 옮겨 적은 두루마리와 첫 기름 항아리, 「서약에 쓸 이름」 다발을 차례로 내밀었다."},{"s":null,"t":"월화는 축문부터 받아 오래 읽었다. 면사포 아래에서 숨소리만 들려왔다. 「서약에 쓸 이름」 다발에 손이 닿았을 때 월화의 손끝이 멈칫했다."},{"s":null,"t":"월화가 다발을 재빨리 무릎 아래로 거두었다. 접힌 모서리가 면사포 자락에 가려졌다."},{"s":null,"t":"단비가 마지막으로 꺼낸 것은 관아 벽에서 서하람이 한 장 더 베껴 준 서식 사본이었다."},{"s":"red_moon_cult:danbi","t":"교주님. 등도 관아에 붙어 있던 백 년 전 서식이에요. 여기 긁힌 칸 보세요. 「부르는」 두 글자만 남았어요."},{"s":null,"t":"월화는 서식 사본을 받아 긁힌 칸에 손끝을 얹었다. 그 손끝이 한동안 움직이지 않았다."},{"s":null,"t":"이윽고 월화가 손을 들어 면사포를 걷었다. 면사포 아래는 처음 보는 교주의 얼굴이었다."},{"s":null,"t":"왼쪽 절반은 젊은 여인의 얼굴이었다. 오른쪽 절반은 잿빛으로 바래 금이 가 있었고, 그 금 사이로 흰빛이 새어 나왔다."},{"s":null,"t":"청파가 저도 모르게 헉 소리를 내고는 두 손으로 입을 틀어막았다. 서하람이 청파의 등을 가만히 짚어 주었다."},{"s":null,"t":"교주의 맨얼굴을 본 사람은 교 안에서도 손에 꼽았다. 나는 저도 모르게 고개를 숙였다. 월화는 그런 나를 보며 입꼬리를 아주 조금 올렸다.","fac":"red_moon_cult","spec":1,"grp":2},{"s":"red_moon_cult:wolhwa","t":"월식성에서 보았지. 이백세 이름을 바치던 밤에. 너는 뇌명봉 바위에 남은 그 이름 자국을 하나하나 다 세었다더구나. 겸이 그러더라."},{"s":"red_moon_cult:wolhwa","t":"월식성에서 내가 그랬지. 버리는 쪽은 따로 있는데 줍는 우리만 늘 욕을 먹는다고. 오늘은 그 버리는 쪽 이야기를 해 주마."},{"s":"red_moon_cult:wolhwa","t":"백 년 전 우리 교 어른들이 정청과 맺은 셈이 있다. 거둔 이름을 흘려보내는 일을 적월이 도맡는 대신, 칸을 긁는 데 서명했지. 그 셈 덕에 적월은 강해졌다. 거둔 이름을 힘으로 삼아서.","fac_not":"red_moon_cult","spec":2,"grp":3},{"s":"red_moon_cult:wolhwa","t":"고개를 들어라. 우리 교도라면 언젠가 들어야 할 얘기다. 백 년 전 우리 교 어른들이 정청과 맺은 셈이 있다. 거둔 이름을 흘려보내는 일을 적월이 도맡는 대신, 칸을 긁는 데 서명했지. 네가 입교할 때 외운 축문도 그 셈에서 나왔다.","fac":"red_moon_cult","spec":1,"grp":3},{"s":"red_moon_cult:wolhwa","t":"고개를 들게, 장로. 장로들에게도 다 말하지 못한 셈이 있다. 백 년 전 우리 교 어른들이 정청과 맺은 셈이다. 거둔 이름을 흘려보내는 일을 적월이 도맡는 대신, 칸을 긁는 데 서명했지. 장로들이 지켜 온 교법도 그 셈에서 나왔다.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":3},{"s":"red_moon_cult:wolhwa","t":"그 맹약의 장이 내 가슴 안에 있다. 교주는 대대로 이 장을 품는다. 품는 동안 장은 교주의 이름을 반쪽씩 땔감으로 삼지. 나는 이제 반쪽이 남았다."},{"s":null,"t":"단비가 숨을 들이켰다. 단비의 어깨가 바들바들 떨렸다."},{"s":"red_moon_cult:danbi","t":"교주님… 그래서 「반쯤 달에 먹혔다」고 하신 거예요? 왜 저희한테 한 번도…"},{"s":"red_moon_cult:wolhwa","t":"무녀에게 교주의 반쪽 얼굴을 보여 줄 까닭이 없었다. 오늘은 있구나."},{"s":null,"t":"월화의 눈이 단비를 지나 나에게 와서 멎었다."},{"s":"red_moon_cult:wolhwa","t":"{이름}이라 했지. 내 앞에서 네 입으로 한 번 더 말해 보아라."},{"s":null,"t":"나는 이름을 말했다. 월화는 고개를 끄덕이고 한참 나를 보았다."},{"s":"red_moon_cult:wolhwa","t":"다시 말해 보아라. 또렷하게."},{"s":null,"t":"나는 한 번 더 이름을 말했다. 월화가 그 이름을 입속으로 굴리듯 따라 읊조렸다. 서하람이 두루마리를 쥔 손에 힘을 주었다."},{"s":"red_moon_cult:wolhwa","t":"이 장을 꺼낼 길은 하나다. 서약을 거꾸로 돌려 장을 몸 밖으로 불러내는 것. 거꾸로 도는 서약은 이름 하나를 값으로 받는다. 내 이름은 이미 땔감이 되어 값으로 쳐 주지 않는다."},{"s":"southern_remnant:galmae","t":"그럼 누구 이름으로 치를 건데?"},{"s":"red_moon_cult:wolhwa","t":"값은 내가 정한다. 너희가 걱정할 일이 아니다."},{"s":null,"t":"방 안이 조용해졌다. 촛불 심지가 지글거리는 소리만 남았다. 사마겸이 천막 기둥 옆에서 팔짱을 끼고 교주를 바라보았다."},{"s":"red_moon_cult:wolhwa","t":"의식은 사흘 뒤 삼경에 한다. 향초와 붉은 흙이 있어야 한다. 장터 둘레를 노리는 먹 낀 것들도 치워야 하고. 단비, 네 일행에게 시켜라."},{"s":null,"t":"월화가 면사포를 내렸다. 면사포 아래에서 낮은 웃음 같은 숨이 새어 나왔다."},{"s":"red_moon_cult:wolhwa","t":"삼백 년 전 그 붓쟁이가 아직도 등잔 아래 앉아 있더냐. 정청에 가거든 안부나 전해라."},{"s":null,"t":"아무도 그 말뜻을 알아듣지 못했다. 단비가 고개를 숙여 물러났다."}],"reward":{"xp":3120}},{"quest_id":"mdq_9","step":2,"title":"값을 정하는 밤","goal":"적사 황무지에서 6번 채집하고 의식 자리를 노리는 기름 핥는 쥐떼를 4번 쫓아낸다","need":{"at":["bone_market"],"tasks":[{"t":"gather","n":6,"r":["red_plain"]},{"t":"win","n":4,"m":["dd_shrine_2"],"r":["red_plain"]}]},"lines":[{"s":null,"t":"장터 둘레를 노리던 것들은 붉은 사당 골목에서 본 기름 핥는 쥐떼였는데, 쥐떼가 지나간 기름 자국은 장터 바깥 마른 우물 속으로 이어져 있었다."},{"s":null,"t":"향초와 붉은 흙을 공터에 부려 놓았을 때는 장터의 붉은 등이 하나씩 꺼지고 있었다. 일행은 장터 끝 공터에 둘러앉았다."},{"s":null,"t":"장터 아이 하나가 쪼르르 달려와 서신을 내밀었다. 정청에서 역참을 거쳐 온 한설의 서신이었다."},{"s":"night_office:han","t":"조사원. 적월 의식 얘기를 문수에게 들었다. 이름 하나를 값으로 받는다고."},{"s":"night_office:han","t":"값은 네가 정하지 마라. 정해진 값을 꼭 먼저 봐라. 셈하는 사람은 값을 미리 정해 두는 법이다. 내가 배운 게 그거다."},{"s":null,"t":"서신을 다 읽자 아무도 말이 없었다. 서하람이 두루마리를 펴 무언가를 짚었다."},{"s":"q:r71_seoharam","t":"…관측한 걸 말할게요. 교주님은 {이름} 님 이름을 이미 아시는데도 두 번이나 말하게 하셨어요. 두 번째엔 따라 읊으셨고요. 이름을 외우려는 사람처럼요."},{"s":"red_moon_cult:danbi","t":"교주님은 원래 사람 이름을 잘 안 외우세요. 그래서 다시 들어 보신 거예요."},{"s":"q:r71_seoharam","t":"그리고 그 다발을 무릎 밑에 숨기셨어요. 모서리 접힌 거요. 천막에서 나오던 그림자 흐린 사람은 빈 보따리를 들고 있었고요."},{"s":"red_moon_cult:danbi","t":"…관측관님. 교주님이에요. 저를 키워 주신 분이에요."},{"s":null,"t":"단비의 목소리가 날카로워졌다가 이내 가라앉았다. 서하람은 더 말하지 않고 두루마리를 말았다."},{"s":null,"t":"서하람이 미안하다는 듯이 단비 쪽으로 엿 꾸러미를 밀어 주었다. 관아 터에서 단비가 통째로 준 그 꾸러미였다."},{"s":null,"t":"먼저 일어선 것은 갈매였다. 갈매가 무릎을 털며 퉁명스럽게 내뱉었다."},{"s":"southern_remnant:galmae","t":"이름 하나가 값이라며. 교주가 누구 걸 고르든, 남명 사람 이름은 백 년 동안 맨 먼저 거둬졌어. 하나 더 거둬 간다고 티도 안 나. 내 걸로 하라고 해."},{"s":null,"t":"청파가 갈매의 소매를 붙잡았다. 갈매가 털어 냈지만 청파는 다시 붙잡았다."},{"s":"q:sn_cheongpa","t":"누님, 그런 말 하지 마요. 누님 이름은 티가 나요. 관아에서 누님이 불러 줬을 때 제 가슴이 얼마나 따뜻했는데요. 저는 알아요."},{"s":null,"t":"갈매가 청파를 내려다보며 입을 열었다가 아무 말도 못 하고 다물고는, 털썩 다시 주저앉았다."},{"s":null,"t":"여운비는 내내 단비의 옆얼굴을 보고 있었지만, 단비는 고개를 숙인 채 붉은 실을 손가락에 감았다 풀기만 했다."},{"s":"red_moon_cult:danbi","t":"이건 적월 일이에요. 적월이 거꾸로 외운 서약이고, 적월이 받아 온 값이에요. 또 다른 사람 이름을 태우면, 백 년 전이랑 뭐가 달라요?"},{"s":null,"t":"단비는 무엇을 하겠다는 말은 하지 않았다. 나는 일행에게, 값이 무엇인지 먼저 보고 정하자고 했다. 한설의 말대로였다. 여운비가 고개를 끄덕였다."},{"s":"north_league:yeo","t":"셋째 장은 꼭 꺼내야 하오. 그래야 조사원이 끝줄을 이을 수 있소."},{"s":"north_league:yeo","t":"그날 밤 북령은 종을 쳤고 적월은 기름을 끊었소. 그 값은 한 집이 치른 게 아니었소. …그러니 이번에도 누구도 혼자 값을 치르지 않소. 그건 정합시다."},{"s":null,"t":"아무도 대답하지 않았다. 다섯 사람이 모두 여운비를 보고 있었다."},{"s":"q:sn_cheongpa","t":"그럼… 다친 사람이 생길지도 모르잖아요. 약부터 챙겨 둬요. 수향에선 깊은 물에 들어가기 전에 약부터 배에 실어요, 대장 누님."},{"s":"north_league:yeo","t":"…그렇소. 청심환과 영초 차를 넉넉히 만들어 둡시다."}],"reward":{"xp":3120}},{"quest_id":"mdq_9","step":3,"title":"면사포 장난","goal":"의식에 대비해 청심환 2개와 영초 차 2개를 만든다","need":{"at":["bone_market"],"tasks":[{"t":"craft","items":["tonic"],"n":2},{"t":"craft","items":["spirit_tea"],"n":2}]},"lines":[{"s":null,"t":"약을 다 만들어 꾸러미에 넣었을 때는 의식 전날 밤이었다. 단비가 어디선가 붉은 면사포 하나를 들고 와 팔락팔락 흔들었다."},{"s":"red_moon_cult:danbi","t":"대장님, 잠깐만 가만히 계세요."},{"s":"north_league:yeo","t":"무엇이오, 그건."},{"s":null,"t":"여운비가 대답을 듣기도 전에 단비가 면사포를 여운비 머리 위에 휙 씌웠다. 여운비가 그 자리에 돌처럼 굳었다."},{"s":"q:sn_cheongpa","t":"우와… 대장 누님, 예뻐요! 진짜 교주님 같아요!"},{"s":null,"t":"갈매가 참지 못하고 푸하하 웃음을 터뜨렸다. 갈매가 그렇게 소리 내어 웃는 것은 처음이었다. 갈매가 배를 잡고 땅을 데굴데굴 굴렀다."},{"s":"southern_remnant:galmae","t":"북령 칼잡이가 면사포! 남명 애들한테 말해 줘야지!"},{"s":"q:r71_seoharam","t":"관측 기록에 남길게요… 「북령 호송대장, 면사포 씀, 의외로 어울림」."},{"s":"north_league:yeo","t":"…벗기시오."},{"s":"red_moon_cult:danbi","t":"싫어요. 잘 어울리는데."},{"s":null,"t":"여운비가 면사포 자락을 잡았지만, 그대로 벗지는 않았다. 여운비가 면사포 너머로 단비를 노려보았는데, 붉은 천 너머라 하나도 무섭지 않았다."},{"s":null,"t":"단비가 여운비 앞에 쪼그려 앉아 면사포 아래를 들여다보며 웃었다."},{"s":"red_moon_cult:danbi","t":"적월에서는 서약하는 날 이걸 써요. 저도 열네 살 때 썼어요. 그날은 하나도 안 즐거웠는데… 오늘은 즐겁네요."},{"s":null,"t":"여운비가 면사포 자락을 쥔 손에 힘을 풀고, 면사포를 벗어 단비 머리 위에 도로 씌워 주었다."},{"s":"north_league:yeo","t":"무녀한테 더 어울리오."},{"s":"red_moon_cult:danbi","t":"…어머."},{"s":null,"t":"단비가 면사포 아래에서 한참 말을 잃었다. 청파가 「또 칭찬했다!」 하고 외치다가 갈매에게 입을 틀어막혔다."},{"s":null,"t":"다들 잠든 뒤에 단비가 면사포를 벗어 무릎에 올려놓고 여운비 곁에 앉았다. 나는 불 건너편에서 그 모습을 보았다."},{"s":"red_moon_cult:danbi","t":"대장님. 내일 의식 때요… 제 뒤에 서 주세요. 방울 흔들 때 뒤에 누가 있으면 덜 무서워요."},{"s":"north_league:yeo","t":"나는 조사원 앞에 서겠소. 실이 어디로 갈지 모르니."},{"s":"red_moon_cult:danbi","t":"그럼… 제가 대장님 앞에 설게요."},{"s":"north_league:yeo","t":"무슨 소리요. 무녀는 방울이나 흔드시오."},{"s":null,"t":"단비는 웃기만 하고 대답은 하지 않았다."},{"s":null,"t":"그때 공터 바깥에서 자갈 밟는 소리가 났다. 고개를 돌리자 사마겸이 서 있었다. 사마겸이 우리 쪽을 한참 보다가 내게 손짓을 했다. 내가 다가가자 사마겸이 목소리를 낮췄다."},{"s":"red_moon_cult:sama","t":"정청 조사원. 교주님께서 의식 값을 정하셨다는구나. 무녀들한테도, 나한테도 말씀을 안 하신다. 나는 단비가 너희를 따라가는 걸 반대했다. 약한 것들 틈에 끼면 약해진다고. …지금 보니 저 아이가 웃는 얼굴이 더 강해졌구나. 내일 저 아이 곁에 있어라.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:sama","t":"교도. 교주님께서 의식 값을 정하셨다는구나. 무녀들한테도, 나한테도 말씀을 안 하신다. 나는 단비가 따라나서는 걸 반대했다. 약한 것들 틈에 끼면 약해진다고. …지금 보니 저 아이가 웃는 얼굴이 더 강해졌구나. 내일 저 아이 곁에 있어라.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"{등급}. 교주님께서 의식 값을 정하셨다 하오. 무녀들한테도, 나한테도 말씀을 안 하시오. 나는 단비가 따라나서는 걸 반대했소. 약한 것들 틈에 끼면 약해진다고. …지금 보니 저 아이 웃는 얼굴이 더 강해졌소. 내일 저 아이 곁에 있어 주시오.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"장로님. 교주님께서 의식 값을 정하셨답니다. 무녀들한테도, 저한테도 말씀을 안 하십니다. 저는 단비가 따라나서는 걸 반대했습니다. 약한 것들 틈에 끼면 약해진다고요. …지금 보니 저 아이 웃는 얼굴이 더 강해졌습니다. 내일 저 아이 곁에 있어 주십시오.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"사마겸은 그 말만 남기고 천막 쪽으로 돌아갔다. 나는 그날 밤 잠을 거의 자지 못했다."}],"reward":{"xp":3120}},{"quest_id":"mdq_9","step":4,"title":"거꾸로 도는 서약","goal":"백골 장터에서 의식 전날 밤을 쉰다","need":{"at":["bone_market"],"tasks":[{"t":"rest","r":["bone_market"],"n":1}]},"lines":[{"s":null,"t":"의식은 삼경에 시작되었다. 공터 한가운데에 월화가 앉았다. 그 둘레에 붉은 실 일곱 가닥이 둥글게 깔렸다."},{"s":null,"t":"실 둘레 일곱 자리에 첫 기름을 부은 등잔이 놓였다. 단비가 등잔마다 불을 붙였다. 일흔 해 만에 타는 기름이 치익, 하고 맑은 불꽃을 올렸다."},{"s":null,"t":"단비는 실 바깥에서 방울을 들었다. 나머지 일행은 실 밖에 둘러섰다. 여운비는 내 바로 앞, 실과 가장 가까운 자리를 골라 섰다."},{"s":null,"t":"단비가 방울을 딸랑딸랑 흔들며 사당 벽의 원래 축문을 읊기 시작했다. 방울 소리가 공기를 한 겹씩 찢을 때마다 장터 등불들이 일제히 낮아졌다."},{"s":null,"t":"월화의 가슴께에서 흰빛이 새어 나왔다. 빛이 밝아질수록 월화의 몸이 활처럼 뒤로 휘었다. 월화가 이를 악물고 신음을 삼켰다."},{"s":null,"t":"땅에 깔린 붉은 실 일곱 가닥이 꿈틀했다. 실이 뱀처럼 고개를 쳐들고 일어섰다."},{"s":null,"t":"실 끝들이 값을 찾는 손가락처럼 허공을 더듬었다. 일곱 가닥이 한꺼번에 방향을 틀었다."},{"s":null,"t":"실은 나를 향하고 있었다."},{"s":"q:r71_seoharam","t":"실이… 실이 {이름} 님 쪽으로 가요! {이름} 님!"},{"s":null,"t":"휘이익 소리와 함께 일곱 가닥이 시위를 떠난 화살처럼 나에게 쏘아져 왔다."},{"s":"red_moon_cult:danbi","t":"교주님! 지금 뭘 하시는 거예요!"},{"s":null,"t":"단비가 방울을 쥔 채 비명을 질렀지만, 월화는 대답하지 않았다. 활처럼 휜 몸으로 눈을 질끈 감고 있었다."},{"s":null,"t":"갈매가 사마겸 발치에 풀어 둔 칼을 스릉 낚아챘다. 갈매가 실 쪽으로 몸을 날리며 고함쳤다."},{"s":"southern_remnant:galmae","t":"이 미친 교주가…! 처음부터 노린 거야!"},{"s":null,"t":"청파가 뒤에서 내 허리를 와락 끌어안고 잡아당겼다. 내 발이 땅에서 질질 끌렸다."},{"s":"q:sn_cheongpa","t":"비켜요, {이름} 님! 비켜요오!"},{"s":null,"t":"실이 코앞까지 왔다. 그 순간 여운비가 몸을 돌려 두 팔로 나를 힘껏 밀쳤다."},{"s":"north_league:yeo","t":"물러서시오!"},{"s":null,"t":"나와 청파가 함께 뒤로 나동그라졌다. 내가 서 있던 자리로 여운비가 들어섰다."},{"s":null,"t":"실 일곱 가닥이 여운비를 감았다. 나를 밀쳐 낸 오른팔부터 허리, 발목까지 순식간이었다."},{"s":null,"t":"칼은 사마겸 발치에 풀어 둔 채였다. 여운비가 맨손으로 실 한 가닥을 움켜쥐고 확 잡아 뜯었다. 실은 끊어지지 않고 여운비의 손바닥을 파고들며 조여들었다."},{"s":null,"t":"실이 닿은 자리부터 여운비의 망토 빛깔이 빠지기 시작했다. 여운비가 이를 악물었다. 무릎이 덜덜 떨렸다."},{"s":"southern_remnant:galmae","t":"놔! 놓으라고, 이 실!"},{"s":null,"t":"갈매가 실을 베고 또 베었다. 칼날이 실에 튕길 때마다 불꽃이 튀었다."},{"s":null,"t":"서하람이 바닥을 기어 실 끝을 맨손으로 잡아당겼다. 손바닥이 실에 쓸려 피가 배었다."},{"s":"q:r71_seoharam","t":"안 끊겨요… 안 끊겨요, 이거! 운비 씨를 먹고 있어요!"},{"s":null,"t":"나는 일어나 여운비에게 달려가며 이름을 불렀다. 금빛 실이 여운비 가슴에 닿았지만, 붉은 실이 그 금빛마저 감아 들었다."},{"s":null,"t":"그 순간 방울 소리가 뚝 멈추었다."},{"s":null,"t":"단비가 방울을 내던지고 붉은 실 안으로 뛰어들었다."},{"s":"north_league:yeo","t":"무녀! 오지 마시오!"},{"s":null,"t":"단비가 여운비 앞을 가로막고 두 팔을 활짝 벌렸다. 여운비를 감던 실 일곱 가닥이 방향을 잃은 듯 허공에서 멈칫했다."},{"s":"red_moon_cult:danbi","t":"교주님! 값은 제 걸로 내요! 이번엔 제 거로요!"},{"s":"red_moon_cult:danbi","t":"남의 이름 말고… 제 이름이요! 단비! 적월 주홍 무녀 단비예요!"},{"s":null,"t":"실 일곱 가닥이 여운비를 놓았다. 실이 쉬이익 소리를 내며 단비의 몸을 감아 들었다."},{"s":null,"t":"왼쪽 어깨에서 시작해 왼팔, 왼쪽 옆구리, 왼쪽 다리까지 감겼다. 실이 닿는 자리마다 붉은 무복의 빛깔이 빠졌다. 그 아래 살갗이 잿빛으로 바랬다."},{"s":null,"t":"단비의 발밑을 내려다보았다. 그림자가 반쪽만 남아 있었다. 왼쪽 그림자가 감쪽같이 사라져 있었다."},{"s":null,"t":"같은 때 월화의 가슴에서 두꺼운 닥종이 한 장이 빛을 끌고 빠져나왔다. 종이가 팔랑팔랑 내려와 땅에 떨어졌다. 월화가 앞으로 털썩 쓰러졌다."},{"s":null,"t":"단비가 무릎을 꿇었다. 오른손으로 땅을 짚어 겨우 버텼지만, 왼손은 들어 올리지 못했다."},{"s":null,"t":"단비가 고개를 들어 여운비를 올려다보았다. 웃어 보이려 했지만 오른쪽 입꼬리만 겨우 올라갔다."},{"s":"red_moon_cult:danbi","t":"대장님… 안 다쳤죠…"},{"s":null,"t":"단비가 옆으로 털썩 기울었다. 여운비가 실에 쓸려 피투성이가 된 손으로 단비를 받아 안았다. 단비의 왼쪽 몸이 얼음처럼 차가웠다."},{"s":"north_league:yeo","t":"무녀! 눈 뜨시오! 무녀!"},{"s":"southern_remnant:galmae","t":"단비! 야, 단비! 정신 차려!"},{"s":"q:sn_cheongpa","t":"단비 누님! 누님, 누님…!"},{"s":"q:r71_seoharam","t":"맥이… 맥이 있어요! 약해요, 근데 있어요! 숨도 쉬어요, 하나, 둘… 느려요, 너무 느려요!"},{"s":null,"t":"서하람이 피 묻은 손으로 단비의 손목을 짚고 숨을 셌다. 졸음기라고는 하나도 없는 얼굴이었다. 숨을 세는 목소리가 덜덜 떨렸다."},{"s":null,"t":"나는 꾸러미에서 청심환과 영초 차를 꺼냈다. 의식 전에 만들어 둔 것이었다. 사마겸이 쿵쿵 달려오며 장터가 떠나가라 고함쳤다."},{"s":"red_moon_cult:sama","t":"의원을 불러라! 당장! 적월 의원은 다 이리로!"}],"reward":{"xp":3120}},{"quest_id":"mdq_9","step":5,"title":"반쪽 얼굴의 고백","goal":"백골 장터에서 청심환 2개와 영초 차 2개를 단비에게 넘긴다","need":{"at":["bone_market"],"give":{"tonic":2,"spirit_tea":2}},"lines":[{"s":null,"t":"적월 의원이 단비의 맥을 짚고 청심환을 녹여 입에 흘려 넣었다. 의원이 한참 만에 고개를 저었다."},{"s":"q:md_red_doctor","t":"약으로는 몸을 데우는 것밖에 못 합니다. 서약이 가져간 반쪽은 약이 닿지 않는 데에 있어요."},{"s":"southern_remnant:galmae","t":"그럼 어떻게 해! 그냥 보고만 있으라고?"},{"s":"q:md_red_doctor","t":"…저도 모릅니다. 거꾸로 돈 서약에 먹힌 사람을 살린 일은 적월 기록에 없습니다."},{"s":null,"t":"쓰러져 있던 월화가 몸을 일으켰다. 오른쪽 얼굴의 금은 더 벌어지지 않았다. 가슴께의 흰빛이 사라져 있었다. 월화가 단비를 보았다."},{"s":null,"t":"갈매가 칼을 들고 월화에게 성큼성큼 다가갔다. 칼끝이 월화의 목에 닿기 직전이었다."},{"s":"southern_remnant:galmae","t":"너. 처음부터 {이름} 이름을 값으로 정해 놨지. 이름을 두 번이나 말하게 한 게 그거였지!"},{"s":null,"t":"사마겸이 갈매 앞을 막아서지 않았다. 사마겸은 그 자리에 선 채 교주를 내려다보고 있었다."},{"s":null,"t":"나는 갈매의 칼끝을 손바닥으로 눌러 내렸다. 갈매가 나를 보았다. 갈매의 눈에서 눈물이 뚝뚝 떨어지고 있었다."},{"s":"southern_remnant:galmae","t":"왜 막아! 저게 너를 죽이려고 했어!"},{"s":null,"t":"나는 갈매에게, 교주의 입으로 까닭을 들어야 한다고 했다. 단비가 깨어나면 그걸 물을 거라고도 했다. 갈매가 칼을 내렸다. 칼끝이 바르르 떨렸다."},{"s":null,"t":"월화의 입술이 달싹였다. 처음으로 교주의 목소리가 무너졌다."},{"s":"red_moon_cult:wolhwa","t":"…정리관이, 장을 아프지 않게 꺼내 준다 했다. 값은 그 조사원 이름 하나면 된다고."},{"s":null,"t":"단비 곁에 무릎 꿇은 여운비가 고개를 들었다. 여운비의 눈이 붉게 충혈되어 있었다."},{"s":"north_league:yeo","t":"정리관이 시킨 거요? 교주가 그자 말 한마디에 사람 이름을 걸었소?"},{"s":"red_moon_cult:wolhwa","t":"말 한마디가 아니다. 내가 교주가 된 해부터다. 해마다 동지 무렵이면 그 사람이 「서약에 쓸 이름」을 보내왔다. 그림자 흐린 심부름꾼들 손에 들려서."},{"s":"red_moon_cult:wolhwa","t":"그 이름이 없으면 적월은 무녀를 세우지 못한다. 축문도 안 들리고, 교도들 손목 실도 힘을 잃는다. 적월이 강한 건 다 그 목록 덕이었다. 그 목록이 끊기면 적월은 한 해도 못 버틴다."},{"s":"red_moon_cult:wolhwa","t":"그 사람은 내 반쪽 얼굴도 알았다. 장이 내 이름을 다 먹으면 다음 교주가 이 장을 품어야 한다는 것도. 「장을 꺼내 주겠소. 다음 교주는 아프지 않아도 되오.」 그 말에 나는… 고개를 끄덕였다."},{"s":"red_moon_cult:wolhwa","t":"단비가 열네 살에 태운 이름도… 그 목록에 있던 이름이다. 그해 목록에 오른 아이 이름 하나를 흑련 거둠꾼이 맡아 두고 있어서, 값을 치르고 사 왔지."},{"s":null,"t":"단비 곁에 앉아 있던 청파가 숨을 헉 들이켰다. 서하람이 두루마리를 떨어뜨렸다."},{"s":"north_league:yeo","t":"그래서 무녀를 붙여 보낸 거요? 조사원 곁에 두려고?"},{"s":"red_moon_cult:wolhwa","t":"「그 사람 곁을 떠나지 마라.」 내가 단비에게 그렇게 말했다. 이런 뜻이 아니었는데… 단비가 그 사람 앞에 설 줄은…"},{"s":null,"t":"사마겸이 처음으로 교주 앞에 한 걸음 나섰다. 거한의 그림자가 월화를 덮었다."},{"s":"red_moon_cult:sama","t":"교주님. 저는 평생 강한 것을 섬겼습니다. 교주님이 강하다고 믿어서 섬겼습니다."},{"s":"red_moon_cult:sama","t":"남이 대 주는 이름으로 교를 세우고, 남의 이름으로 제 반쪽을 사려는 것은 강한 것이 아닙니다. 오늘 이 장터에서 가장 강한 것은 저 아이였습니다. 교주님이 아니라."},{"s":null,"t":"월화가 고개를 떨구었다. 아무도 사마겸을 말리지 않았다."},{"s":null,"t":"월화가 무릎으로 기어 단비에게 다가갔다. 여운비가 몸을 굳혔지만 월화를 밀어내지는 않았다. 월화가 단비의 잿빛 왼손을 두 손으로 감싸 쥐었다."},{"s":"red_moon_cult:wolhwa","t":"단비야… 단비야. 내가 너를 열네 살에 실 안에 세웠지. 오늘은 네가 제 발로 들어갔구나. 내가 못 한 걸 네가…"},{"s":null,"t":"교주가 단비를 끌어안고 울었다. 면사포를 벗은 반쪽 얼굴로 소리 내어 울었다. 장터 사람들이 멀찍이서 그 모습을 지켜보았지만, 아무도 다가오지 못했다."},{"s":null,"t":"땅에 떨어진 셋째 장은 첫 기름 등잔 곁에 놓여 있었다. 종이 위에 「거둔 이름은 달빛 아래 보내되, 그 이름으로 힘을 삼지 않는다」라는 구절이 또렷했다. 끝줄의 「이을 이」 칸이 비어 있었다."},{"s":null,"t":"나는 그 칸에 이름을 적었다. 손이 떨려 획이 삐뚤어졌다. 흰 불꽃이 금빛으로 바뀌었다. 품속 둘째 장과 금빛 실로 이어졌다."},{"s":null,"t":"청파가 금빛 실을 보다가 손가락 두 개를 폈다. 목소리가 젖어 있었다."},{"s":"q:sn_cheongpa","t":"…둘이에요. 다섯 남았어요. 단비 누님이 꺼내 준 거예요. 단비 누님이…"},{"s":"north_league:yeo","t":"밤새 무녀 곁에 있겠소. 다들… 이름을 불러 주시오. 그게 지금 할 수 있는 거라면."}],"reward":{"xp":3120}},{"quest_id":"mdq_9","step":6,"title":"부르지 않는 사람","goal":"백골 장터에서 단비 곁을 지키며 쉰다","need":{"at":["bone_market"],"tasks":[{"t":"rest","r":["bone_market"],"n":1}]},"lines":[{"s":null,"t":"그 밤 우리는 단비 곁에 둘러앉았다. 단비의 왼쪽 어깨에 앉은 잿빛이 목 쪽으로 스멀스멀 번져 오르고 있었다."},{"s":null,"t":"내가 먼저 단비의 이름을 불렀다. 금빛 실이 단비 가슴에 닿았다. 번지던 잿빛이 멈칫했다."},{"s":null,"t":"청파가 뒤따라 불렀다. 목이 메어 두 번 만에야 소리가 났다. 갈매가 불렀고, 서하람이 불렀다. 서하람의 목소리는 졸린 기색 없이 또렷했다."},{"s":"q:r71_seoharam","t":"단비 씨. 엿값 갚을게요. 별 생기면 갚는다고 했잖아요. 별 있어요, 오늘. 저기 있어요. 그러니까 일어나요."},{"s":null,"t":"금빛 실이 하나씩 늘어날 때마다 잿빛이 조금씩 물러났지만, 끝내 다 물러나지는 않았다. 잿빛은 어깨 언저리에서 멈춰 버티었다."},{"s":null,"t":"여운비는 단비의 오른손을 붙잡고 있었다. 단비가 쓰러진 뒤로 한 번도 놓지 않은 손이었다. 여운비는 이름을 부르지 않았다."},{"s":"north_league:yeo","t":"무녀. …무녀, 일어나시오. 내 앞에 서라고 한 적 없소."},{"s":null,"t":"여운비의 입에서는 금빛이 나오지 않았다. 무녀는 이름이 아니었다. 여운비의 입술이 몇 번 달싹였다가 그대로 닫혔다."},{"s":null,"t":"갈매가 그런 여운비를 노려보았다."},{"s":"southern_remnant:galmae","t":"야, 북령. 단비가 너 대신 저렇게 된 거잖아. 이름이라도 불러. 숙제라며! 관아에서 단비가 숙제라고 했잖아!"},{"s":null,"t":"고개를 든 여운비의 얼굴이 하얗게 질려 있었다. 눈가가 붉었다. 여운비의 입에서 나온 말은 갈매가 기다리던 말이 아니었다."},{"s":"north_league:yeo","t":"…무녀는 내가 지키겠소. 이름은 당신들이 불러 주시오."},{"s":null,"t":"갈매가 이를 악물고 일어나 공터 밖으로 나가 버렸다. 청파가 그 뒤를 쫓아 나갔다. 여운비는 단비의 손을 놓지 않은 채 다시 고개를 떨구었다."},{"s":null,"t":"나는 여운비에게 왜 부르지 못하는지 묻지 않았다. 그 대신 여운비 몫까지 단비의 이름을 한 번 더 불렀다. 여운비의 어깨가 아주 조금 떨렸다."},{"s":null,"t":"새벽녘에 사마겸이 종이 한 장을 들고 왔다. 거한의 손에서 종이가 구겨져 있었다."},{"s":"red_moon_cult:sama","t":"장터 우물 돌테에 끼워져 있었다. 젖어 있더군. 모서리도 접혀 있고. 너희 앞으로 온 거다."},{"s":null,"t":"나는 종이를 폈다. 종이에는 반듯하고 느긋한 글씨가 적혀 있었다."},{"s":"q:md_gyeonghyeon","t":"무녀가 쓰러진 일은 내 셈에 없던 것이오. 셋째 장은 잘 지니시오. 동지까지는 아직 날이 있소. — 정리관"},{"s":null,"t":"다 읽고 나자 서하람이 종이를 빼앗듯 가져가 들여다보았다. 서하람의 손이 덜덜 떨렸다."},{"s":"q:r71_seoharam","t":"셈에 없던 거래요. 그럼 셈에 있던 건… {이름} 님 이름이었다는 거잖아요. 그 사람은, 그 사람은 미안하다는 말도 안 해요."},{"s":null,"t":"돌아온 갈매가 그 종이를 낚아채 박박 찢었다. 찢긴 조각이 장터 바닥에 흩어졌다."},{"s":null,"t":"청파가 그 조각을 줍지 않고 발로 밀어냈다. 청파가 무엇을 줍지 않은 것은 처음이었다."},{"s":null,"t":"날이 밝을 무렵 월화가 단비 곁에 와 앉았다. 면사포를 다시 쓰지 않은 채였다."},{"s":null,"t":"월화가 단비의 잿빛 손등을 쓸었다. 목소리는 쉬어 있었지만 또렷했다."},{"s":"red_moon_cult:wolhwa","t":"거꾸로 돈 서약에 먹힌 반쪽은 몸에서 조금씩 빠져나간다. 붙들려면 물이 있어야 한다. 수향 깊은 물, 이름을 실어 나르던 물이다."},{"s":"north_league:yeo","t":"그 물이 어디 있소."},{"s":"red_moon_cult:wolhwa","t":"등도 동쪽에 수향 무리가 살던 나루가 있었다. 물길은 말랐다지만 바닥 깊은 데에 그 물이 고여 있을 게다. 거기서 부르면 잿빛이 덜 번질 게다."},{"s":"red_moon_cult:wolhwa","t":"하나 더 있다. 교주가 교주에게만 물려주는 말이다. 입에서 입으로 건너온 말이라 흐릿하다."},{"s":"red_moon_cult:wolhwa","t":"소등 전날 밤, 수향 배 한 척이 그 나루를 드나들었다고 한다. 그 배가 끝내 나루 깊은 물 밑으로 가라앉았다고. 누가 왜 가라앉혔는지는 전하는 말마다 다르다. 그 배 밑창에 맹약의 넷째 장이 실려 있었다는 것만은 같다. 그 밤 기름을 끊으러 나간 우리 달 지기들이 그 배를 보았다고 하더구나."},{"s":null,"t":"청파가 숨을 헉 들이켰다. 봉인고에서 경현이 했던 말이 떠오른 얼굴이었다."},{"s":"q:sn_cheongpa","t":"가라앉은 배요…? 정리관 아저씨가 우리 증조할아버지 배가 소등 전날 뭘 싣고 나갔는지 안다고 했는데… 그 배예요?"},{"s":"red_moon_cult:wolhwa","t":"그것까지는 모른다. 배 이름은 물려받지 못했다."},{"s":null,"t":"청파가 입술을 꾹 깨물었다. 한참 만에 청파가 벌떡 일어났다. 눈물 자국이 아직 마르지 않은 얼굴이었다."},{"s":"q:sn_cheongpa","t":"그럼… 물길은 제가 알아요. 단비 누님 붙들 물도, 넷째 장도 거기 있잖아요. 제가 앞장설게요!"},{"s":"north_league:yeo","t":"앞장은 내가 서오. 청파는 물길을 읽으시오. 무녀는… 내가 메겠소."},{"s":null,"t":"갈매와 청파가 장터 천막 장대와 판자를 엮어 들것을 만들었다. 우리는 단비를 들것에 눕혔다. 여운비가 말없이 들것 앞쪽을 잡았다."},{"s":null,"t":"단비의 잿빛 왼팔이 들것 밖으로 힘없이 흘러내렸다. 갈매가 그 팔을 끈으로 들것 틀에 묶어 주었다. 흘러내리지 않게 두 번 감았다."},{"s":"southern_remnant:galmae","t":"…떨어뜨리면 죽는다, 북령."},{"s":"north_league:yeo","t":"안 떨어뜨리오."},{"s":null,"t":"서하람이 바닥에 떨어진 단비의 방울을 주웠다. 서하람은 방울을 천으로 닦아 단비의 품에 조심스럽게 넣어 주었다."},{"s":"q:r71_seoharam","t":"깨어나면 바로 흔들 수 있게요. 엿값은 따로 갚을게요."},{"s":null,"t":"사마겸이 장터 어귀까지 따라 나왔다. 거한이 단비의 잿빛 손을 내려다보다가 내게 고개를 한 번 숙였다."},{"s":"red_moon_cult:sama","t":"저 아이를 데려가 줘서… 아니, 지켜 줘서 고맙다. 교주님은 내가 지키겠다. 다시는 그 목록을 받지 않게.","fac_not":"red_moon_cult","spec":2,"grp":1},{"s":"red_moon_cult:sama","t":"교도. 저 아이를 데려가 줘서… 아니, 지켜 줘서 고맙다. 교주님은 내가 지키겠다. 다시는 그 목록을 받지 않게.","fac":"red_moon_cult","rank":[1,2],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"{등급}, 저 아이를 데려가 줘서… 아니, 지켜 줘서 고맙소. 교주님은 내가 지키겠소. 다시는 그 목록을 받지 않으시게.","fac":"red_moon_cult","rank":[3,4],"spec":0,"grp":1},{"s":"red_moon_cult:sama","t":"장로님, 저 아이를 데려가 주셔서… 아니, 지켜 주셔서 고맙습니다. 교주님은 제가 지키겠습니다. 다시는 그 목록을 받지 않으시게.","fac":"red_moon_cult","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 금빛으로 이어진 장 둘을 품에 넣었다. 단비가 꺼내 준 셋째 장이 가슴께에서 따뜻했다. 우리는 들것을 메고 흰 밤으로 돌아가는 수로를 향해 걸었다."},{"s":"north_league:yeo","t":"장 둘을 이었소. 다음 넷째 장은 수향 물 밑이오. 무녀를 붙들 물도 거기 있고. …가는 길이 하나라 다행이오."}],"reward":{"xp":3120,"gil":490,"items":{"night_tea":3,"revival_charm":2}}},{"quest_id":"mdq_10","step":1,"title":"물 없는 나루","goal":"단비를 들것에 싣고 옛 나루 저자에 도착한다","need":{"at":["old_ferry_market"],"tasks":[{"t":"travel","r":["old_ferry_market"],"n":1}]},"lines":[{"s":null,"t":"백골 장터에서 천막 장대로 엮은 들것은 첫 수로 둑을 내려가다 장대가 부러졌다. 그 뒤로 단비는 줄곧 여운비의 등에 업혀 있었다. 갈매가 묶어 준 끈이 여운비의 어깨를 깊이 파고들었다."},{"s":null,"t":"쉬어 가자는 말이 나올 때마다 여운비는 고개를 저었다. 수로 둑을 오를 때는 무릎이 후들후들 떨렸지만, 걸음을 멈추지 않았다."},{"s":"southern_remnant:galmae","t":"북령, 다리 떨리는 거 다 보여. 이리 내. 내가 업을게."},{"s":"north_league:yeo","t":"괜찮소."},{"s":"southern_remnant:galmae","t":"안 괜찮으니까 하는 말이야! 무녀를 떨어뜨리면 네가 책임질 거야?"},{"s":"q:sn_cheongpa","t":"그럼 들것 만들어요! 수로 가에 부러진 노가 널렸어요. 노 두 자루에 망토만 걸면 돼요. 그럼 넷이 번갈아 들 수 있잖아요."},{"s":null,"t":"청파와 나는 둑 아래에서 부러진 노 두 자루를 주워 왔다. 여운비가 제 망토를 벗어 노 사이에 팽팽하게 묶었다. 사당 골목에서 단비 어깨에 덮어 주었던 그 망토였다."},{"s":null,"t":"여운비는 단비를 들것에 눕히고서야 어깨의 끈을 풀었다. 갈매가 들것 앞쪽을 잡았다. 빈손이 된 여운비는 들것 옆에 붙어 걸으며 단비의 이마에 흘러내린 머리칼을 쓸어 넘겼다."},{"s":null,"t":"단비의 왼쪽 얼굴은 귀밑부터 잿빛이었다. 잿빛은 비 맞은 먹처럼 목을 타고 어깨 쪽으로 번져 있었다. 숨을 쉴 때마다 오른쪽 가슴만 오르내렸다."},{"s":null,"t":"서하람은 들것 곁을 떠나지 않았다. 적월 의식이 있던 그 밤 뒤로 서하람의 얼굴에서 졸린 기색이 싹 가셨다. 몇 걸음마다 단비의 코끝에 손등을 대 보고서야 다시 걸었다."},{"s":"q:r71_seoharam","t":"숨은… 고르게 쉬어요. 아까보다 조금 느려졌지만요."},{"s":null,"t":"옛 나루 저자에 들어서자 발밑에서 바스락바스락 소리가 났다. 물길이었던 자리는 진흙이 거북 등처럼 쩍쩍 갈라져 있었다. 갈라진 틈마다 하얗게 바랜 물풀이 바스러져 있었다."},{"s":null,"t":"마른 물길 위에는 크고 작은 배 수십 척이 비스듬히 얹혀 있었다. 돛은 흰 밤 빛깔로 바래 있었다. 뱃전마다 매달린 나무패가 바람도 없는데 달각달각 서로 부딪쳤다."},{"s":null,"t":"청파는 저자 어귀에서 걸음을 멈췄다. 늘 쉬지 않던 입이 꾹 다물려 있었다. 청파는 가장 가까운 배의 뱃전을 손바닥으로 쓸어 보다가, 그 손을 가슴께로 가져가 꽉 쥐었다."},{"s":"southern_remnant:galmae","t":"야, 꼬맹이. 왜 그래. 배 처음 봐?"},{"s":"q:sn_cheongpa","t":"…배가 땅에 앉아 있잖아요. 수향 사람들은 그게 제일 무서워요. 배가 물에 못 뜨면, 그 배에 이름을 맡긴 사람도 못 뜬다고 하거든요."},{"s":null,"t":"갈매는 들것을 내려놓고 마른 바닥을 발로 툭 찼다. 흙덩이가 부서지며 흰 먼지가 풀썩 피어올랐다."},{"s":"southern_remnant:galmae","t":"교주가 그랬잖아. 수향 나루 바닥에 이름을 실어 나르던 물이 고여 있을 거라고. 이 바닥 어디에 물이 있다는 거야."},{"s":null,"t":"청파는 대답 대신 엎드려 마른 바닥에 귀를 댔다. 우리는 모두 숨을 죽였다. 한참 뒤에 청파의 눈이 천천히 커졌다."},{"s":"q:sn_cheongpa","t":"물소리가 나요. 저 밑에서, 아주 멀리요. 물길이 마른 게 아니에요. 물이 밑으로 내려간 거예요."},{"s":"north_league:yeo","t":"어디로 가면 그 물에 닿소."},{"s":"q:sn_cheongpa","t":"수향 나루에는 다 우물이 하나씩 있어요. 저자 한복판에요. 근데 배들이 이렇게 엉켜 있으니까 길부터 찾아야 해요."},{"s":null,"t":"나는 들것 옆에 짐을 내려놓고 배들 사이로 난 틈을 살폈다. 뒤집힌 거룻배 그늘 아래에서 무언가가 사각사각 긁는 소리가 들렸다."},{"s":"southern_remnant:galmae","t":"들었지? 저기 뭐 있어. 무녀는 북령이 지키고, 나랑 {이름}이(가) 앞에 서. 잠꾸러기는 우물 자리를 봐."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":2,"title":"붙드는 물","goal":"옛 나루 저자에서 요괴를 3번 쓰러뜨리고 4번 탐색해 우물 자리를 찾는다","need":{"at":["old_ferry_market"],"tasks":[{"t":"win","n":3,"r":["old_ferry_market"]},{"t":"search","r":["old_ferry_market"],"n":4}]},"lines":[{"s":null,"t":"배 그늘에 숨어 있던 것들은 물풀처럼 축축 늘어진 몸으로 우리 발목을 노렸다. 갈매의 칼이 휘익 지나가자 그것들은 먹물이 되어 갈라진 틈으로 스며들었다."},{"s":null,"t":"우물은 저자 한가운데에 있었다. 돌로 테를 둘렀고, 두레박 줄을 감는 나무틀은 반쯤 썩어 있었다. 서하람이 기울어진 돛대 셋을 손가락으로 이어 그 자리를 짚었다."},{"s":"q:r71_seoharam","t":"여기예요… 나루 지도에서 우물은 늘 돛대 셋이 만나는 자리에 그렸대요. 할머니한테 들었어요."},{"s":null,"t":"우물 테 둘레의 마른 흙에 젖은 발자국이 몇 개 찍혀 있었다. 발자국마다 먹물이 고여 번들거렸다. 발끝은 모두 우물 쪽을 향해 있었다."},{"s":"southern_remnant:galmae","t":"또야. 우물로 다니는 놈들. 철벽 고찰에도, 우리 화로 뒤 도랑에도 이런 게 있었어."},{"s":"north_league:yeo","t":"먹이 아직 안 말랐소. 우리보다 한나절쯤 먼저 왔소."},{"s":"q:r71_seoharam","t":"무관 거리 우물로 빠져나간 그 사람 같은 사람들이요… 그림자 흐린 사람들. 여기까지 따라왔나 봐요."},{"s":null,"t":"나는 발자국 하나에 손끝을 대 보았다. 차갑고 미끈했다. 장서각 불탄 바닥에서 맡았던 묵은 그을음 냄새가 났다."},{"s":null,"t":"청파가 두레박을 내렸다. 줄이 끝도 없이 풀려 나가자 청파 혼자서는 감는 틀을 붙들 수가 없었다. 나는 틀의 다른 쪽 손잡이를 잡았다."},{"s":null,"t":"한참 만에 아득히 퐁, 하는 소리가 올라왔다. 둘이서 줄을 감는 동안 청파는 박자에 맞춰 작게 중얼거렸다."},{"s":"q:sn_cheongpa","t":"영차… 영차… {이름} 님, 손 안 아파요? 이 줄 엄청 무거워요."},{"s":null,"t":"끌어 올린 물은 맑았다. 정청 우물처럼 검지 않았다. 손을 담그자 뼈가 시릴 만큼 차가워 나도 모르게 손을 뺐다."},{"s":null,"t":"청파가 그 물을 손바닥에 받았다. 단비의 왼손 등에 똑, 똑 떨어뜨리자 물방울이 닿은 자리에서 잿빛이 실처럼 풀려 물방울 속으로 빨려 들어갔다."},{"s":null,"t":"물방울은 굴러떨어지기 전에 먹빛으로 흐려졌다. 잿빛이 물러난 자리는 손톱만 했지만, 그 자리에 분명히 사람의 살빛이 돌아와 있었다."},{"s":"q:r71_seoharam","t":"돌아왔어요… 손 대 봐요, 따뜻해요!"},{"s":null,"t":"여운비가 손톱만 한 자리에 손끝을 댔다가 떼었다. 숨을 내쉬는 어깨가 떨렸다."},{"s":"north_league:yeo","t":"더 길어 오시오. 물이 닿는 만큼 돌아온다면 우물이 마를 때까지라도 길어 오겠소."},{"s":"q:sn_cheongpa","t":"대장님, 이 물은 많이 못 길어요. 수향 사람들이 「붙드는 물」이라고 부르는 물이에요. 물에 빠진 사람 이름이 흩어지지 않게 붙들어 두는 물인데, 하루에 한 동이만 길어야 맑대요."},{"s":null,"t":"여운비는 대꾸하지 않고 두레박 줄을 손수 감아 한 동이를 더 길어 올렸다."},{"s":null,"t":"두 번째 물은 흙탕물처럼 누렇게 흐려 있었다. 여운비는 두레박을 오래 내려다보다가 우물가에 조용히 내려놓았다."},{"s":"southern_remnant:galmae","t":"…봐. 꼬맹이 말 들으라니까."},{"s":null,"t":"말은 거칠었지만 갈매는 흐린 물이 담긴 두레박을 여운비 발밑에서 슬쩍 치워 주었다."},{"s":"q:sn_cheongpa","t":"그리고요, 이 물은 쇠 그릇에 담으면 금방 흐려져요. 나무 동이나 질그릇이어야 해요. 우리가 가진 건 다 쇠 냄비뿐이라…."},{"s":null,"t":"나는 배들 사이에 널린 판자와 진흙을 둘러보았다. 일흔 해를 견딘 뱃판이라면 동이를 짜기에 넉넉해 보였다."},{"s":"southern_remnant:galmae","t":"판자는 내가 뜯을게. 칼질은 남명이 제일이야. 하람이 너는 진흙이나 이겨."},{"s":"q:r71_seoharam","t":"…네. 진흙은 별 기록판 메우던 거랑 비슷해요. 할 수 있어요."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":3,"title":"적월 무녀","goal":"옛 나루 저자에서 5번 채집하고 뱃판 물동이 2개를 짜서 청파에게 넘긴다","need":{"at":["old_ferry_market"],"tasks":[{"t":"gather","n":5,"r":["old_ferry_market"]},{"t":"craft","items":["plank_water_jar"],"n":2}],"give":{"plank_water_jar":2}},"lines":[{"s":null,"t":"동이 두 개는 해 질 무렵에 다 짰다. 해라고 해도 등도의 하늘은 늘 흰 새벽빛이었다. 그림자는 길어지지도 짧아지지도 않았다."},{"s":null,"t":"청파가 동이를 손바닥으로 두드려 보았다. 통, 통 맑은 소리가 났다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 이음새를 이렇게 맞춘 거 진짜 잘했어요. 거룻배 고칠 때보다 훨씬 늘었어요."},{"s":null,"t":"그 밤 우리는 단비를 가운데 눕히고 둘러앉았다. 모닥불은 피우지 않았다. 바싹 마른 배들이 저자를 가득 메우고 있어서, 불티 하나만 튀어도 저자가 통째로 탈 것 같았다."},{"s":null,"t":"내가 먼저 단비의 이름을 불렀다. 입김이 금빛 실로 맺혀 단비의 가슴께에 닿았다. 목까지 오르던 잿빛이 멈칫했다."},{"s":null,"t":"청파가 따라 불렀다. 갈매가 불렀다. 서하람이 또박또박 불렀다. 실이 하나씩 늘 때마다 잿빛은 조금씩 물러났지만 어깨에서 더 내려가지 않았다."},{"s":null,"t":"여운비는 단비의 오른손을 쥐고 있었다. 장터에서 쓰러진 뒤로 한 번도 놓지 않은 손이었다."},{"s":"north_league:yeo","t":"…무녀. 일어나시오."},{"s":null,"t":"금빛 실은 맺히지 않았다. 여운비의 입김은 흰 밤 속으로 그냥 흩어졌다."},{"s":"southern_remnant:galmae","t":"야. 너 또 그런다. 이름을 부르라고, 이름을. 무녀가 이름이야?"},{"s":"north_league:yeo","t":"…부르고 있소."},{"s":"southern_remnant:galmae","t":"안 부르고 있잖아! 실이 안 나가는 거 안 보여? 쟤가 누구 대신 저렇게 됐는데!"},{"s":null,"t":"청파가 갈매의 팔을 붙들었다. 갈매는 팔을 홱 뿌리쳤지만 더 소리치지는 않았다."},{"s":null,"t":"그때 단비의 오른손 손가락이 꼼지락 움직였다. 여운비의 손을 쥐는 힘이었다. 우리는 모두 숨을 멈췄다."},{"s":"red_moon_cult:danbi","t":"…대장님… 엿… 반은 제 거예요…."},{"s":null,"t":"잠꼬대였다. 단비의 눈은 감긴 채였고, 오른쪽 입꼬리만 아주 조금 올라가 있었다."},{"s":"q:sn_cheongpa","t":"엿 얘기 하는 거 보니까 단비 누님 맞네요. 진짜 누님이에요…."},{"s":null,"t":"청파는 웃다가 울먹였다. 품에서 종이에 싼 엿 하나를 꺼내 단비의 머리맡에 놓았다. 붉은 사당 골목에서 단비가 「물강아지」라는 별명과 함께 쥐여 준 엿이었다."},{"s":"q:sn_cheongpa","t":"이거, 안 먹고 아껴 둔 거예요. 깨면 돌려줄 거예요. 그때까지 안 먹을 거예요."},{"s":null,"t":"갈매는 고개를 돌렸다. 여운비는 여전히 단비의 손을 쥐고 있었다. 입술이 몇 번 달싹였다가 그대로 닫혔다."},{"s":"q:r71_seoharam","t":"오늘은… 아무도 장 얘기를 안 했어요. 다들 단비 씨 숨만 셌어요. 저도요."},{"s":"north_league:yeo","t":"장은 둘이오. 다섯 남았소. 무녀가 일어나야 나머지도 찾소. 사람을 길에 두고 가는 호송대는 없소."},{"s":null,"t":"나는 그 말에 고개를 끄덕였다. 붙드는 물이 왜 이 나루에 있었는지 알면 단비를 깨울 다른 길도 보일 것 같았다. 그래서 내일은 배 무덤 안쪽 배들을 한 척씩 뒤져 보자고 했다."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":4,"title":"장부의 빈칸","goal":"옛 나루 저자에서 단비 곁을 지키며 쉬고, 원정을 한 번 끝까지 다녀와 배 무덤 안쪽을 살핀다","need":{"at":["old_ferry_market"],"tasks":[{"t":"rest","r":["old_ferry_market"],"n":1},{"t":"expedition","r":["old_ferry_market"],"n":1}]},"lines":[{"s":null,"t":"배 무덤 안쪽의 배들은 바깥 배보다 더 하얗게 바래 있었다. 선실 문을 열 때마다 끼이익 소리와 함께 마른 소금 냄새가 쏟아졌다."},{"s":null,"t":"가장 큰 배의 선실 바닥 밑에서 기름 먹인 상자 하나가 나왔다. 갈매가 칼끝으로 자물쇠를 비틀자 철컥 소리와 함께 뚜껑이 열렸다."},{"s":"southern_remnant:galmae","t":"남명 정찰대는 이런 거 잘 따. 칭찬 안 해도 돼."},{"s":null,"t":"상자 안에는 수향 뱃길 장부 한 권이 젖지 않은 채 들어 있었다. 청파가 장부를 펼쳤다. 줄을 따라 내려가던 청파의 손가락이 점점 느려졌다."},{"s":"q:r71_seoharam","t":"뭐라고 적혀 있어요?"},{"s":"q:sn_cheongpa","t":"「부름꾼 두 사람 태움, 뱃삯 은 닷 냥」, 「돌아오는 길, 도장 찍은 줄 이백」… 그 옆에 고을 이름이 적혀 있어요."},{"s":"southern_remnant:galmae","t":"부름꾼이면… 봉인고에서 그 늙은이가 말한 거잖아. 쌀 두 섬 받고 아무 줄에나 도장 찍어 준다던 놈들."},{"s":"q:sn_cheongpa","t":"네. 이 배가 그 사람들을 고을마다 실어 날랐어요. 도장 찍은 줄 수만큼 뱃삯을 받았고요. 그리고 여기… 「쌀 없는 고을, 들르지 않음」이라고 적혀 있어요."},{"s":null,"t":"갈매의 얼굴이 굳었다. 갈매는 장부에서 눈을 떼지 않은 채 주먹을 쥐었다."},{"s":"southern_remnant:galmae","t":"가난하면 부를 사람도 못 산다는 거네. 그러다 칸째 긁혔고. 그다음에 맨 먼저 거둬진 건 남명 백성이었어."},{"s":null,"t":"장부 뒤쪽에는 한 장이 통째로 비어 있었다. 날짜만 적혔고 줄은 하나도 채워지지 않았다. 서하람이 그 날짜를 손끝으로 짚었다."},{"s":"q:r71_seoharam","t":"백 년 전 동지예요. 관아 터에서 본 서식이랑 같은 날이요. 칸이 긁힌 날 사고팔 칸도 없어졌으니까… 장부도 여기서 멈춘 거예요."},{"s":null,"t":"청파는 장부를 덮지 못했다. 맨 앞장의 주인 칸 위에 엄지를 얹어 글자를 가리고 있었다."},{"s":"north_league:yeo","t":"청파. 그 칸에 뭐라고 적혀 있소."},{"s":"q:sn_cheongpa","t":"…몰라요. 글자가 바래서 안 보여요."},{"s":null,"t":"청파의 엄지가 떨리고 있었다. 나는 더 묻지 않고 청파의 어깨에 손을 얹었다가 내렸다."},{"s":null,"t":"그 밤에도 우리는 단비 곁에서 차례로 이름을 불렀다. 청파는 한 번도 부르지 않았다. 동이 곁에 웅크린 채 장부를 품에 안고 흰 하늘 쪽만 보았다."},{"s":null,"t":"단비의 머리맡에는 청파가 놓아 둔 엿이 그대로 있었다. 여운비는 그날 밤에도 「무녀」라고만 불렀다."},{"s":null,"t":"새벽 무렵 갈매가 제 겉옷을 벗어 청파의 등에 휙 덮었다. 청파가 고개를 들자 갈매는 등을 돌려 버렸다."},{"s":"southern_remnant:galmae","t":"추워 보여서 그런 거 아니야. 이 딱딱 부딪는 소리가 시끄러워서 그래."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":5,"title":"다온의 서신","goal":"옛 나루 저자에서 청파 곁에서 쉰다","need":{"at":["old_ferry_market"],"tasks":[{"t":"rest","r":["old_ferry_market"],"n":1}]},"lines":[{"s":null,"t":"이튿날 아침, 저자 어귀에서 휘파람 소리가 났다. 흑련의 심부름꾼이 옛 수로 쪽에서 걸어와 접힌 종이 한 장을 내밀었다."},{"s":"q:md_lotus_runner","t":"장부고에서 왔습니다. 다온이라는 아이가 꼭 {이름} 님 손에 드리라고 했습니다."},{"s":null,"t":"종이에는 삐뚤삐뚤한 글씨가 가득했다. 나는 모두가 들을 수 있게 소리 내어 읽었다."},{"s":"q:mk_daon","t":"{이름} 님, 단비 누나 얘기 들었어요. 흑련 심부름꾼이 장터에서 듣고 왔대요. 저 그날 밤에 잠을 못 잤어요."},{"s":"q:mk_daon","t":"어젯밤에는 아저씨가 잠결에 「꼬맹이」 하고 불렀어요. 제 이름은 아니지만 저 부른 거 맞아요. 구슬 누나도 들었어요."},{"s":"q:mk_daon","t":"아저씨는 아직 안 깼어요. 잿빛은 팔꿈치에서 멈춰 있어요. 쪽지는 안 펴고 쥐고만 있어요. 아저씨가 펴지 말랬으니까요. 대신 아침마다 「아저씨」 하고 불러요. 그러면 아저씨 눈썹이 꼭 한 번 움찔해요."},{"s":"q:mk_daon","t":"명부 탑에서 제가 막 뛰어가려고 할 때 아저씨가 저를 붙잡고 끝까지 안 놨잖아요. 그러니까 이번엔 제가 안 놓을 거예요."},{"s":"q:mk_daon","t":"그러니까 단비 누나도 아침마다 불러 주세요. 눈썹이 움찔하는지 꼭 보세요. 저도 여기서 같이 부를게요. 멀어서 안 들려도요."},{"s":null,"t":"내가 서신을 다 읽자 모두 하던 일을 멈췄다. 갈매는 칼 갈던 손을 멈추고 고개를 돌렸다. 서하람은 서신을 받아 들고 「멀어서 안 들려도요」라는 줄을 손끝으로 쓸었다."},{"s":"q:r71_seoharam","t":"이 애는… 값을 하나도 안 받고 불러요. 아침마다요."},{"s":null,"t":"그 말에 청파가 고개를 들었다. 이틀 만에 처음 우리 쪽을 보는 얼굴이었다. 청파는 품에서 장부를 꺼내 내게 내밀었다. 손이 떨리고 있었다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 이 장부 주인 칸 좀 읽어 주세요. 저는… 못 읽겠어요."},{"s":null,"t":"나는 장부를 받아 바랜 글자를 손끝으로 더듬었다. 글자는 미지근했다. 「청씨 선단」이라고 적혀 있었다."},{"s":null,"t":"내가 소리 내어 읽자 청파는 고개를 끄덕였다. 이미 알고 있던 얼굴이었다. 나는 구름나루 선창 끝에서 진소랑이 한 부탁을 떠올렸다. 청파가 먼저 꺼내기 전에는 그 배 이야기를 하지 말아 달라던 부탁이었다."},{"s":"q:sn_cheongpa","t":"…우리 집이에요. 봉인고에서 정리관이 그랬잖아요. 우리 증조할아버지 배가 소등 전날 무엇을 싣고 나갔는지 안다고요. 도방님도 그 배 얘기만 나오면 주판을 딱 멈췄어요. 저는 그게 무슨 뜻인지 몰랐어요. 이거였나 봐요."},{"s":"southern_remnant:galmae","t":"그럼 네 증조할배가 부름꾼 장사를 했다는 거야?"},{"s":"q:sn_cheongpa","t":"몰라요! 그러니까 물어보러 갈 거예요. 구름나루에요. 도방님한테요."},{"s":null,"t":"청파의 목소리가 처음으로 갈라졌다. 갈매는 더 묻지 않았다."},{"s":"north_league:yeo","t":"그럼 같이 가오. 무녀를 여기 두고 갈 수는 없소. 물은 하루 한 동이뿐이니, 데리고 가서 수향 의원에게 보이시오. 붙드는 물도 한 동이 들고 가오."},{"s":"q:r71_seoharam","t":"구름나루에는 강이 있으니까… 의원님이 다른 길을 알지도 몰라요."},{"s":null,"t":"나는 들것의 앞쪽을 들었다. 이번에는 여운비가 뒤쪽을 들었다. 청파는 물동이를 등에 졌다. 출렁 소리가 날 때마다 청파는 걸음을 늦췄다."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":6,"title":"쉰 목소리","goal":"구름나루에 도착해 붙드는 물을 담은 뱃판 물동이 1개를 수향 의원에게 넘긴다","need":{"at":["river_ferry"],"tasks":[{"t":"travel","r":["river_ferry"],"n":1}],"give":{"plank_water_jar":1}},"lines":[{"s":null,"t":"구름나루 선창에 닿은 것은 저녁이었다. 등도를 나와 처음 보는 붉은 해가 강물 위에 낮게 깔려 있었다. 우리 발밑에 그림자가 길게 늘어났다."},{"s":null,"t":"청파가 제 그림자를 내려다보며 한참 서 있었다. 갈매가 청파의 뒤통수를 툭 쳤다."},{"s":"southern_remnant:galmae","t":"그림자 처음 봐? 가자. 무녀 무거워."},{"s":null,"t":"수향 의원은 선창 뒤 약방의 영감이었다. 영감은 단비의 왼손을 들춰 보고 혀를 쯧쯧 찼다. 붙드는 물 동이를 받아 들고는 고개를 끄덕였다."},{"s":"q:md_river_doctor","t":"이 물을 용케 길어 왔구먼. 이걸로 몸은 붙들어 두겠네. 하지만 깨우는 건 물이 못 해. 부르는 목소리가 해야지."},{"s":null,"t":"의원이 우리를 둘러보더니 다시 혀를 찼다."},{"s":"q:md_river_doctor","t":"그런데 다들 목소리가 그게 뭔가. 쇳소리가 나는구먼. 그런 목으로 며칠 더 부르면 아주 잠기네."},{"s":null,"t":"맞는 말이었다. 갈매의 목은 갈라져 있었고, 서하람은 말할 때마다 콜록콜록 기침을 했다. 여운비는 아예 입을 다물고 있었다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 장터에서 꿀 좀 구해 와 주실래요? 저는 야령초랑 갈대를 뜯어 올게요. 수향에서는 목 쉰 뱃사람한테 영초 차에 꿀을 타서 먹이거든요."},{"s":null,"t":"영초 차는 야령초와 수향 갈대를 함께 우리는 차라 쉰 목을 틔워 주고, 꿀을 타면 아이도 쓰다 하지 않고 마신다고 했다."},{"s":null,"t":"나는 선창 장터로 갔다. 꿀 단지를 파는 가게 앞에 먼저 와 선 사람이 있었다. 단정한 정청 옷에 얇은 장부를 옆구리에 낀 사내였다."},{"s":null,"t":"경현이었다. 경현은 꿀 단지 두 개를 값 치르고 받아 들더니, 돌아서며 그중 하나를 내게 내밀었다."},{"s":"q:md_gyeonghyeon","t":"목이 다 쉬었겠구려. 밤마다 무녀 이름을 부르느라."},{"s":null,"t":"나는 단지를 받지 않고 어떻게 알았느냐고 물었다."},{"s":"q:md_gyeonghyeon","t":"약방 영감이 혀 차는 소리가 선창 끝까지 들렸소. 쇳소리 나는 목이 넷이라고."},{"s":null,"t":"경현은 내 눈길이 단지 주둥이에 머문 것을 보고 단지를 조금 더 내밀었다."},{"s":"q:md_gyeonghyeon","t":"독은 안 탔소. 내가 사람을 해치려 들었다면 독보다 붓이 빠르오. 명부에 붉은 줄 하나면 되니까."},{"s":"q:md_gyeonghyeon","t":"무녀가 쓰러진 일은 내 셈에 없던 것이오. 우물 돌테에 끼운 서신에도 적었지만, 얼굴을 보고 한 번은 직접 말하고 싶었소."},{"s":null,"t":"나는 그러면 누가 그 셈에 있었느냐고 물었다."},{"s":"q:md_gyeonghyeon","t":"당신이었소. 교주와 내가 정한 값은 당신 이름 하나였지."},{"s":"q:md_gyeonghyeon","t":"그 값이면 셋째 장은 교주 몸에서 아프지 않게 빠져나오고, 교주는 남은 반쪽 이름을 지켰을 거요. 무녀가 대신 뛰어들 줄은 나도 몰랐소."},{"s":null,"t":"경현은 장부를 펴 한 장의 모서리를 꾹 접었다. 접는 손끝이 아주 잠깐 멈췄다."},{"s":"q:md_gyeonghyeon","t":"청씨 선단 장부를 건지셨다지. 도방께 가져가 보시오. 그 사람이 주판을 내려놓는 걸 보게 될 거요. 셈을 그만두는 사람의 얼굴이지. 나는 그런 얼굴을 백 년 전에도 한 번 봤소."},{"s":null,"t":"경현은 단지를 가게 문턱에 내려놓고 사람들 사이로 사라졌다. 나는 그 단지를 한참 내려다보았다."},{"s":null,"t":"받지 않으면 정청 사람 하나에게 지지 않은 셈이었다. 받으면 오늘 밤 넷의 목이 덜 아플 터였다. 나는 단지를 들었다."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":7,"title":"헤엄","goal":"천엽 연화늪에서 4번 채집하고 영초 차 4잔을 우려 일행에게 넘긴다","need":{"at":["river_ferry"],"tasks":[{"t":"gather","n":4,"r":["lotus_marsh"]},{"t":"craft","items":["spirit_tea"],"n":4}],"give":{"spirit_tea":4}},"lines":[{"s":null,"t":"꿀을 탄 영초 차가 끓자 약방 마당에 단내가 퍼졌다. 내가 꿀 단지를 어디서 얻었는지 말하자 갈매가 그릇을 탁 내려놓았다."},{"s":"southern_remnant:galmae","t":"정청 놈이 준 걸 마시라고? 그 자식이 단비를 저렇게 만든 셈을 했다며!"},{"s":"north_league:yeo","t":"내가 먼저 마시겠소."},{"s":null,"t":"여운비가 그릇을 들어 한 모금 넘겼다. 모두 여운비의 얼굴을 지켜보았다. 여운비는 한참 뒤에 그릇을 내려놓았다."},{"s":"north_league:yeo","t":"…나쁘지 않소. 독이 있었다면 내가 먼저 맞았을 거요. 그러니 마시시오. 오늘 밤에도 불러야 하오."},{"s":"q:r71_seoharam","t":"운비 씨, 그런 거 하지 마세요… 진짜 독이었으면 어쩌려고요."},{"s":"north_league:yeo","t":"호송대장은 길에서 물을 먼저 마시는 사람이오."},{"s":null,"t":"갈매는 투덜대면서도 그릇을 비웠다. 다 마시고 나서 혀를 쯧 찼다."},{"s":"southern_remnant:galmae","t":"…달긴 되게 다네."},{"s":null,"t":"청파만 그릇에 손을 대지 않았다. 청파는 마당 끝에서 강물만 보고 있었다. 장부방은 선창 바로 건너편이었지만 청파는 그쪽을 한 번도 보지 않았다."},{"s":"q:sn_cheongpa","t":"저, 도방님 뵙기 전에요. 다들 헤엄 배워 둬요. 물속 일이 생길지도 모르잖아요. 뜨는 법만 알아도 덜 무서워요."},{"s":"southern_remnant:galmae","t":"지금? 해 다 졌는데?"},{"s":"q:sn_cheongpa","t":"지금요. 얕은 데서요. 금방 해요."},{"s":null,"t":"청파가 그렇게 서두르는 까닭을 우리 모두 알았지만, 아무도 그 까닭을 입에 올리지 않았다. 나는 신을 벗고 먼저 물에 들어갔다."},{"s":null,"t":"선창 아래 얕은 물은 허리까지 왔다. 청파는 물에 들자 딴사람처럼 조용해졌다. 손바닥으로 물을 누르는 법을 천천히 보여 주었다."},{"s":"q:sn_cheongpa","t":"숨을 크게 들이쉬고 몸에 힘을 빼요. 물은 힘주는 사람을 싫어해요. {이름} 님, 잘하네요!"},{"s":null,"t":"서하람은 발목까지만 담그고 섰다. 여운비는 칼을 풀어 단비의 들것 곁에 세워 두고 들어왔다. 갈매는 맨 나중에 팔짱을 낀 채 들어왔다."},{"s":"southern_remnant:galmae","t":"이런 거 안 배워도 돼. 남명 정찰대는 강을 걸어서 건너."},{"s":null,"t":"갈매가 그 말을 끝내기도 전에 미끈한 돌을 밟았다. 갈매의 몸이 뒤로 기울더니 철퍼덕 소리와 함께 물속으로 사라졌다."},{"s":"q:r71_seoharam","t":"갈매 씨! 갈매 씨가 안 올라와요!"},{"s":null,"t":"물 위로 팔 하나가 허우적허우적 솟았다. 청파가 물살을 가르고 달려갔고, 나는 반대쪽 팔을 붙들었다. 둘이서 끌어 올리자 갈매가 콜록콜록 물을 토했다."},{"s":"southern_remnant:galmae","t":"놔! 놔, 안 빠졌어! 일부러 들어간 거야!"},{"s":null,"t":"선창 위에서 노를 손질하던 노들 영감이 껄껄 웃었다. 영감은 노를 내려놓고 나를 한참 들여다보았다."},{"s":"river_alliance:nodeul","t":"허허, 용잠 수궁 물길을 묻던 조사원이 이번엔 사람을 물에 빠뜨리고 다니는구먼. 연화 거북은 아직 잘 있나?"},{"s":"q:sn_cheongpa","t":"네? 연화 거북이요? 늪에서 거북 데려간 사람이 {이름} 님이었어요? 나루 애들이 한동안 그 얘기만 했는데!"},{"s":null,"t":"나는 거북은 잘 있다고만 했다. 청파가 입을 딱 벌렸다. 그사이 영감의 눈길이 아직 콜록거리는 갈매에게로 옮겨 갔다."},{"s":"river_alliance:nodeul","t":"아이고, 아기씨가 강물을 다 마셔 버리겠네. 우리 막내보다 더 막내로구먼."},{"s":null,"t":"갈매의 얼굴이 순식간에 붉어졌다. 물에 빠진 탓이 아니었다. 갈매는 젖은 머리를 털다 말고 영감을 노려보았다."},{"s":"southern_remnant:galmae","t":"…막내 아니야. 그렇게 부르지 마."},{"s":null,"t":"웃음이 뚝 그쳤다. 영감은 영문을 모르는 얼굴로 눈을 끔뻑였다. 청파가 얼른 갈매 앞을 가로막았다."},{"s":"q:sn_cheongpa","t":"영감님, 이 누님이 남명 정찰대장이에요! 막내는 저 하나로 충분해요. 그렇죠, 누님?"},{"s":null,"t":"갈매는 대답하지 않고, 청파의 어깨를 젖은 손으로 한 번 꽉 쥐었다가 놓았다. 청파는 그 손을 내려다보다가 강물 쪽으로 돌아섰다."},{"s":"q:sn_cheongpa","t":"…다들 알죠. 제가 시간 끄는 거요. 무서워서 그래요. 도방님이 「그래, 네 집이 그랬다」고 하면, 그다음에 뭘 해야 할지 모르겠어요."},{"s":"north_league:yeo","t":"그 말을 듣고 나서 정하면 되오. 듣기 전에 정할 일은 없소."},{"s":"q:sn_cheongpa","t":"…그럼 낚시 조금만 하고 갈게요. 물을 보고 있으면 할 말이 정리돼요. {이름} 님, 옆에 있어 줄래요?"}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":8,"title":"주판을 내려놓은 사람","goal":"구름나루에서 청파와 나란히 3번 낚시한다","need":{"at":["river_ferry"],"tasks":[{"t":"fish","n":3,"r":["river_ferry"]}]},"lines":[{"s":null,"t":"청파는 세 번 낚싯대를 던졌지만, 세 번 다 입질이 없었다. 마지막 낚싯줄을 감아올린 청파가 일어섰다."},{"s":"q:sn_cheongpa","t":"가요. 이제 할 말 생겼어요."},{"s":null,"t":"장부방 문지기는 청파를 보고 반색하다가, 청파가 품에서 꺼낸 장부를 보더니 얼굴이 굳었다.","fac_not":"river_alliance","spec":2,"grp":1},{"s":null,"t":"장부방 문지기는 내 연맹 패를 확인하는 시늉만 하고 문을 열어 주었다. 문고리를 쥔 손이, 청파가 품에서 꺼낸 장부를 보자 멈췄다.","fac":"river_alliance","spec":1,"grp":1},{"s":null,"t":"장부방 안에서는 주판알이 타닥타닥 튀고 있었다. 도방 진소랑이 주판을 튕겼고, 그 곁에서 행수 매향이 장부를 셈하고 있었다."},{"s":null,"t":"청파가 장부를 탁자 위에 탁 내려놓았다. 주판 소리가 멈췄다. 진소랑은 주인 칸을 내려다보더니 주판을 옆으로 밀어 놓았다. 그 손이 주판을 놓는 것을 나는 처음 보았다."},{"s":"river_alliance:maehyang","t":"도방님, 이건…"},{"s":"river_alliance:jin","t":"행수, 문을 닫아요. 오늘은 장부에 안 적을 얘기예요."},{"s":"river_alliance:jin","t":"…결국 건져 오셨네요. 등도까지 다녀오신 분께 거짓말로 값을 매길 수는 없겠어요.","fac_not":"river_alliance","spec":2,"grp":2},{"s":"river_alliance:jin","t":"…우리 연맹 사람이 이걸 들고 왔네요. 연맹 장부에 없는 얘기라서, 오늘은 도방이 아니라 수향 사람으로 말할게요.","fac":"river_alliance","rank":[1,4],"spec":0,"grp":2},{"s":"river_alliance:jin","t":"…도방이 도방 앞에서 이걸 보게 됐네요. 같은 자리에 앉은 분이니 숨길 수도 없죠.","fac":"river_alliance","rank":[5,5],"spec":0,"grp":2},{"s":"river_alliance:jin","t":"용잠 수궁 문을 열어 주신 분 앞에서 이 장부를 펴게 되네요. 그때는 수향이 빚을 졌는데, 오늘은 제가 값을 치를 차례예요."},{"s":"q:sn_cheongpa","t":"말해 주세요, 도방님. 우리 집이 뭘 했어요."},{"s":null,"t":"진소랑이 청파를 똑바로 보았다. 웃음기 하나 없는 얼굴이었다."},{"s":"river_alliance:jin","t":"부름 장사의 큰 손이 청씨 선단이었어. 네 증조할아버지. 부름꾼을 뱃길로 실어 나르고 값을 받았지. 백 년 전 정청이 칸을 긁을 때, 수향은 그 장사를 덮어 주는 값으로 서명했어."},{"s":"river_alliance:jin","t":"그리고 소등 전날, 청씨 선단의 배가 등도에서 아이들을 실어 나왔어. 값을 치른 집 아이들만. 값을 못 치른 집 아이들은 선창에 두고."},{"s":null,"t":"청파의 얼굴에서 핏기가 싹 가셨다. 갈매가 반걸음 앞으로 나섰다가 멈췄다."},{"s":"southern_remnant:galmae","t":"두고 왔다고? 애들을? 그 밤에?"},{"s":"river_alliance:jin","t":"끝까지 들어요. 청파야, 네 증조할아버지는 그 아이들을 등도 밖 물가에 내려놓고, 그날 해 지기 전에 빈 배로 다시 나루에 들어갔어. 선창에 남은 아이들을 태우러."},{"s":"river_alliance:jin","t":"값을 안 치른 아이를 한 번 태우면, 그다음부터는 아무도 값을 안 내요. 뱃길 장사가 통째로 무너지죠. 수향 어른들은 그렇게 셈했어요. 그래서 그 배를 나루에서 붙잡았어. 아이들이 오르기 전에 나루 가장 깊은 물로 끌고 가 가라앉혔어. 밑창 궤짝에 맹약의 넷째 장이 실려 있었는데도."},{"s":"river_alliance:maehyang","t":"장부방에 남은 건 그 배가 다닌 뱃길뿐이에요. 무엇을 실었는지 적은 장부는 그 배를 가라앉힌 날 어른들이 모두 태웠어요. 오늘 이 장부가 아니었으면 아무도 셈을 못 했을 거예요."},{"s":"q:r71_seoharam","t":"넷째 장이요? 장이 실린 걸 알면서… 왜 장째로요?"},{"s":"river_alliance:jin","t":"넷째 장은 증인 명부예요. 맹약에 서명한 이들 이름이 다 적혀 있고, 맨 앞줄에 수향 조상 이름이 있어요. 그 이름 밑에서 아이들을 선창에 둔 거예요. 부끄러워서 건지지 않고 장째로 물에 묻었어요."},{"s":null,"t":"진소랑은 장부 옆에 붓 한 자루를 내려놓고, 처음으로 웃지 않는 얼굴로 나를 보았다."},{"s":"river_alliance:jin","t":"정리관이 사흘 전에 이 방에 앉아 있었어요. 그 배가 어디 가라앉았는지 묻더군요. 모른다고 했어요. 거짓말이었죠."},{"s":"river_alliance:jin","t":"그 물까지 내려갈 수 있는 사람은 수향에서도 청파 하나예요. 거짓말을 못 하는 애라서 보낸 것도 맞아요. 하지만 그게 다가 아니었어요. 값을 못 매긴다고 한 건 제가 이 값을 치를 자신이 없어서였어요."},{"s":null,"t":"청파는 아무 말도 하지 않고, 장부도 집어 들지 않은 채 돌아서서 장부방을 나갔다. 쾅, 문이 닫히는 소리가 선창까지 울렸다."},{"s":"north_league:yeo","t":"내가 가 보겠소."},{"s":"river_alliance:maehyang","t":"지금은 혼자 두세요. 저 애는 화나면 물가로 가요. 물가에선 안 다쳐요."},{"s":null,"t":"여운비는 문고리를 잡은 채 섰다가 손을 놓았다. 밖에서 개 짖는 소리가 났다. 선창 둘레에 먹 낀 것들이 어슬렁거린다는 뱃사람들의 외침이 뒤따랐다."},{"s":"southern_remnant:galmae","t":"마침 잘됐네. 뭐라도 베고 싶었어. {이름}, 따라와."}],"reward":{"xp":2163}},{"quest_id":"mdq_10","step":9,"title":"가지 마시오","goal":"천엽 연화늪에서 선창으로 기어 나온 문패 문 물귀를 4번 쓰러뜨리고 구름나루에서 쉰다","need":{"at":["river_ferry"],"tasks":[{"t":"win","n":4,"m":["dd_ferry_2"],"r":["lotus_marsh"]},{"t":"rest","r":["river_ferry"],"n":1}]},"lines":[{"s":null,"t":"선창 둘레를 어슬렁거리던 것들은 옛 나루 저자에서 본 문패 문 물귀였다. 물귀들은 선창 아래 우물 구멍에서 먹물을 뚝뚝 흘리며 기어 나왔고, 갈매가 마지막 하나를 베자 먹물로 풀려 우물 속으로 되돌아갔다."},{"s":null,"t":"그 밤 청파는 선창 끝에 짐을 꾸려 놓고 앉아 있었다. 등에 멘 보따리 위에 장부가 묶여 있었다. 청파는 강물을 내려다보며 젖은 신을 만지작거렸다."},{"s":null,"t":"나는 꿀 탄 영초 차 한 그릇을 들고 가 청파 곁에 앉았다. 청파는 그릇을 받았지만 마시지 않았다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 저 여기 남을게요. 같이 못 가겠어요."},{"s":"q:sn_cheongpa","t":"우리 집이 값 받은 애들만 먼저 태웠대요. 남은 애들은 끝내 못 태웠고요. 그런 집 사람이 누구 이름을 부르겠다고 따라다니는 게 우습잖아요."},{"s":null,"t":"나는 우습지 않다고 했다. 청파는 고개를 저었다."},{"s":"q:sn_cheongpa","t":"{이름} 님은 착해서 그래요. 다른 사람들은 다 그렇게 생각할걸요. 갈매 누님네는 그 칸 때문에 나라가 망했잖아요."},{"s":null,"t":"등 뒤에서 발소리가 났다. 돌아보니 여운비가 서 있었다. 여운비는 청파의 보따리 끈을 내려다보다가 청파 곁에 털썩 앉았다."},{"s":null,"t":"여운비가 먼저 누군가의 곁에 앉는 것은 처음이었다."},{"s":"north_league:yeo","t":"우리 집안은 종을 쳐서 도성 하나를 지웠소. 그 집 사람이 지금 적월 무녀를 지키겠다고 들것을 메고 다니오. 그것도 우습소?"},{"s":"q:sn_cheongpa","t":"…아니요."},{"s":"north_league:yeo","t":"적월은 그 밤에 기름을 끊었소. 남명은 그 셈의 값을 맨 먼저 치렀고. 남명 사람이 우리를 미워할 까닭은 넘치오."},{"s":"north_league:yeo","t":"그런데 옛 나루에서, 그 남명 사람이 새벽에 제 겉옷을 벗어 당신 등에 덮었소. 나도 봤소. 미워하는 집 아이한테 겉옷을 벗어 주는 사람은 없소."},{"s":null,"t":"여운비가 칼을 들어 칼자루 끝을 세웠다. 칼자루 끝에 매단 붉은 술이 강바람에 하늘하늘 날렸다. 여운비는 술이 날리는 쪽을 한참 보았다."},{"s":"north_league:yeo","t":"바람은 남쪽에서 오오. 내일 물길이 순하겠소. …가지 마시오. 물속 일은 당신밖에 못 하오."},{"s":null,"t":"청파는 한참 아무 말도 하지 않았다. 강물이 선창 기둥에 찰싹찰싹 부딪는 소리만 들렸다."},{"s":null,"t":"이윽고 청파가 보따리 끈을 천천히 풀었다. 장부가 무릎 위로 툭 떨어졌다. 청파는 식은 영초 차를 한 번에 들이켜다 콜록 사레가 들렸다. 나는 청파의 등을 두드려 주었다."},{"s":"q:sn_cheongpa","t":"대장님이 저한테 「가지 마시오」 한 거요. 나중에 단비 누님 깨면 꼭 얘기할 거예요."},{"s":"north_league:yeo","t":"…하지 마시오."},{"s":"q:sn_cheongpa","t":"할 거예요. 엿 돌려줄 때 같이요."},{"s":null,"t":"여운비는 대꾸하지 않고 일어나 선창을 걸어 나갔다. 그 걸음이 평소보다 조금 빨랐다."},{"s":null,"t":"약방 쪽에서 갈매와 서하람의 목소리가 들려왔다. 단비를 부르는 목소리였다. 꿀 덕분인지 쇳소리가 조금 가셔 있었다."},{"s":"q:sn_cheongpa","t":"{이름} 님. 저 그 배까지 내려갈게요. 증조할아버지가 두고 온 게 장만은 아닐 것 같아요. 도방님이 말 안 한 게 하나 더 있는 얼굴이었어요."},{"s":null,"t":"나는 그때도 줄을 잡겠다고 했다. 문패를 건지던 날처럼 끝까지 잡겠다고 했다. 청파가 그날 처음으로 웃었다."}],"reward":{"xp":2163,"gil":500,"items":{"waterlogged_plank":2,"cheong_carp_steam":2}}},{"quest_id":"mdq_11","step":1,"title":"물굴","goal":"옛 나루 저자에 도착해 우물 밑 물굴을 내려다본다","need":{"at":["old_ferry_market"],"tasks":[{"t":"travel","r":["old_ferry_market"],"n":1}]},"lines":[{"s":null,"t":"단비는 구름나루 약방에 두고 왔다. 떠나는 아침, 진소랑이 약방 문 앞에서 소매를 걷어붙였다."},{"s":"river_alliance:jin","t":"제가 하루 세 번 부를게요. 아침, 낮, 밤이요. 장부에 적어 두고 한 번도 안 빼먹을게요. 그러니 다녀와요. 청파 좀… 꼭 데리고 돌아와요."},{"s":null,"t":"여운비는 약방 문턱에서 두 번 돌아보았다. 세 번째로 돌아보려 할 때 갈매가 여운비의 등을 떠밀었다."},{"s":"southern_remnant:galmae","t":"돌아보면 길이 늘어. 북령이 그것도 몰라?"},{"s":null,"t":"옛 나루 저자의 우물 밑으로 내려가는 길은 안쪽 벽에 박힌 쇠 손잡이뿐이었다. 손잡이를 하나씩 디디며 내려가는 동안 위쪽의 흰빛이 점점 작아졌다. 마침내 엽전만 한 구멍으로 남았다."},{"s":null,"t":"발밑에서 물소리가 점점 커졌다. 철썩, 철썩, 등도에 들어온 뒤 처음 듣는 물결 소리였다."},{"s":null,"t":"우물 맨 밑은 커다란 물굴로 이어져 있었다. 칠흑 같은 물이 굴 천장 가까이까지 차 있었다. 우리가 들고 내려간 등잔 불빛이 물 위에서 흔들렸다."},{"s":"q:r71_seoharam","t":"여기는… 어두워요. 등도에서 처음으로 어두워요. 흰 밤이 여기까지는 못 내려왔나 봐요."},{"s":null,"t":"서하람의 말대로였다. 등잔 아래 우리 그림자가 진하게 드리워 있었다. 청파가 제 그림자를 내려다보며 숨을 길게 내쉬었다."},{"s":"q:sn_cheongpa","t":"물이 이름을 붙들어서 그래요. 붙드는 물은 빛도 붙들어요. 그러니까 저 밑 배도… 그대로 있을 거예요."},{"s":"southern_remnant:galmae","t":"얼마나 깊은데."},{"s":"q:sn_cheongpa","t":"몰라요. 근데 우리가 가져온 줄로는 모자라요. 수향 잠수 줄은 삼 껍질을 세 겹으로 꼬아요. 물에 젖으면 더 질겨지거든요."},{"s":null,"t":"돛줄 삼 껍질만으로는 물굴 깊이를 다 버티지 못할 것 같아, 나는 질긴 영사 실타래를 자아 세 겹 가운데 한 겹으로 꼬아 넣기로 했다."},{"s":"north_league:yeo","t":"무엇이 있으면 되오."},{"s":"q:sn_cheongpa","t":"저자 배들 돛줄이요. 다 삼이에요. 풀어서 다시 꼬면 돼요."},{"s":null,"t":"나는 쇠 손잡이를 다시 잡았다. 올라가서 돛줄을 걷어 오겠다고 했다. 갈매가 내 뒤를 따라 손잡이를 잡았다."},{"s":"southern_remnant:galmae","t":"혼자 가면 또 배 그늘에서 뭐가 튀어나와. 같이 가."},{"s":"q:r71_seoharam","t":"저는 여기 남아서 물살을 볼게요… 청파가 어디로 내려가야 하는지 물결이 알려 줄 거예요."}],"reward":{"xp":2781}},{"quest_id":"mdq_11","step":2,"title":"다 같이 묶는 매듭","goal":"옛 나루 저자에서 5번 채집하고 영사 실타래 1개를 자아 잠수 줄로 청파에게 넘긴다","need":{"at":["old_ferry_market"],"tasks":[{"t":"gather","n":5,"r":["old_ferry_market"]},{"t":"craft","items":["spirit_thread"],"n":1}],"give":{"spirit_thread":1}},"lines":[{"s":null,"t":"우리가 걷어 온 돛줄과 영사 실타래를 청파는 물굴 바닥에 길게 펼쳤다. 세 가닥을 꼬는 법을 보여 주자 모두 한 가닥씩 맡았다. 다섯이 달라붙으니 줄은 금방 길어졌다."},{"s":null,"t":"여운비는 줄을 너무 세게 꼬다가 청파에게 혼이 났다. 서하람은 꼰 길이를 손뼘으로 재며 숫자를 중얼거렸다."},{"s":"q:sn_cheongpa","t":"대장님, 그렇게 세게 하면 줄이 울어요. 살살요. 사람 손 잡듯이요."},{"s":"north_league:yeo","t":"…사람 손을 이렇게 잡지는 않소."},{"s":"q:r71_seoharam","t":"서른두 뼘… 서른세 뼘. 이 정도면 우물보다 길어요. 물살은 서쪽 벽 밑으로 빨려 들어가요. 배는 거기 있을 거예요."},{"s":null,"t":"줄이 다 꼬이자 청파가 허리띠를 풀었다. 줄 끝을 제 허리에 감으려던 청파가 손을 멈췄다."},{"s":"q:sn_cheongpa","t":"…저기요. 매듭 한 번씩 묶어 주실래요? 수향에서는 처음 들어가는 잠수꾼 줄에 식구들이 매듭을 하나씩 지어 줘요. 꼭 돌아오라고요."},{"s":null,"t":"갈매가 먼저 다가왔다. 갈매는 투덜대며 줄을 청파의 허리에 감고, 남명 정찰대가 벼랑을 탈 때 쓰는 매듭을 지었다. 매듭을 두 번 당겨 보고서야 손을 뗐다."},{"s":"southern_remnant:galmae","t":"이건 절대 안 풀려. 풀리면 내가 물에 들어가서 너 패 줄 거야."},{"s":null,"t":"서하람은 갈매의 매듭 옆에 작은 고리 매듭을 지었다. 그 고리에 두루마리 끈에서 뜯은 흰 실 한 가닥을 매달았다."},{"s":"q:r71_seoharam","t":"별 기록 묶을 때 쓰는 매듭이에요… 흰 실은 물속에서도 잘 보이라고요."},{"s":null,"t":"여운비는 한참 줄을 들고 있다가 북령 호송대가 짐 썰매에 거는 매듭을 지었다. 단단하고 투박한 매듭이었다."},{"s":"north_league:yeo","t":"썰매 짐은 이걸로 묶으면 절벽에서 굴러도 안 떨어지오."},{"s":"q:sn_cheongpa","t":"저 짐이에요? 대장님?"},{"s":"north_league:yeo","t":"짐보다 귀하오."},{"s":null,"t":"청파가 입을 딱 벌렸다. 갈매가 푸흡 웃음을 터뜨렸다. 마지막 매듭은 내 차례였다. 나는 청파의 허리에 줄을 한 번 더 감아 꼭 묶고, 줄의 다른 끝을 내 손목에 감았다."},{"s":"q:sn_cheongpa","t":"{이름} 님이 그때처럼 잡아 주는 거죠? 문패 건지던 날처럼요."},{"s":null,"t":"나는 그렇다고 했다. 여운비가 내 뒤에서 줄을 받아 손목에 세 번 감고, 팔꿈치에도 한 번 더 감았다."},{"s":"north_league:yeo","t":"두 번 당기면 끌어올리겠소. 한 번 당기면 기다리겠소. 아무 소리가 없으면… 그래도 기다리겠소."},{"s":"q:sn_cheongpa","t":"그거 잠수꾼 말로 「끝까지 안 놓는다」는 뜻이에요. 대장님, 수향 사람 다 됐네."},{"s":null,"t":"청파는 숨을 세 번 깊이 들이쉬고 소리도 없이 물속으로 미끄러져 들어갔다. 물이 한 번 출렁이고 나자, 물굴 안에는 줄이 스르륵스르륵 풀려 나가는 소리만 남았다."},{"s":"q:r71_seoharam","t":"하나… 둘… 숨을 셀게요. 수향 잠수꾼은 백 숨까지 버틴댔어요."}],"reward":{"xp":2781}},{"quest_id":"mdq_11","step":3,"title":"넷째 장","goal":"옛 나루 저자 물굴에서 청파를 기다리며 쉰다","need":{"at":["old_ferry_market"],"tasks":[{"t":"rest","r":["old_ferry_market"],"n":1}]},"lines":[{"s":null,"t":"줄이 두 번 당겨진 것은 서하람이 아흔여섯을 셌을 때였다. 탁, 탁, 내 손목에 짧은 떨림이 두 번 왔다."},{"s":"q:r71_seoharam","t":"당겼어요! 두 번이요!"},{"s":null,"t":"여운비와 내가 줄을 끌었다. 갈매가 달려들어 함께 끌었다. 물이 부글부글 끓더니 청파가 푸하 하고 솟아올랐다."},{"s":null,"t":"청파의 입술은 새파랬다. 한 팔에 기름 먹인 궤짝 하나를 끌어안고 있었다. 갈매가 청파의 뒷덜미를 잡아 바닥으로 끌어 올렸다."},{"s":"southern_remnant:galmae","t":"아흔여섯 숨이 뭐야, 아흔여섯이! 백 숨이라며!"},{"s":"q:sn_cheongpa","t":"…아흔여섯이면… 백보다 적잖아요…."},{"s":null,"t":"궤짝 안에는 두꺼운 닥종이 한 장이 들어 있었다. 일흔 해를 물속에 있었는데도 종이는 젖지 않았다. 그 위에 손바닥만 한 흰 불꽃 하나가 떠 있었다."},{"s":null,"t":"종이에는 일곱 조상과 증인 스물한 사람의 이름이 적혀 있었다. 끝줄에는 「이 맹약에 서명한 이들의 이름을 해마다 부른다」는 구절이 있었고, 그 아래 「이을 이」 칸이 비어 있었다."},{"s":null,"t":"증인 명부 맨 윗줄의 서명을 읽던 서하람이 손을 멈추었다."},{"s":"q:r71_seoharam","t":"「백운서」… 또 이 이름이에요. 관아 터 현판에도 있었잖아요. 그것도 삼백 년 전이었고요. 정청 도제조님이랑 같은 이름이에요."},{"s":"southern_remnant:galmae","t":"동명이인이겠지. 정청 놈들은 이름도 돌려 써?"},{"s":null,"t":"갈매는 코웃음을 치려다 그만두었다. 나는 그 서명을 오래 보았다. 현판과 편지의 「백 공」, 그리고 이 서명을 이어 붙이면 무엇이 나올지 떠올리는 것만으로 등골이 서늘했다."},{"s":null,"t":"그사이 청파는 궤짝을 다시 열어 보고 있었다. 장이 있던 자리 아래에 기름종이로 싼 종이 다발이 하나 더 있었다. 그것을 편 청파의 얼굴이 하얗게 굳었다."},{"s":"q:sn_cheongpa","t":"이건… 「이번 배에 태우지 못한 아이들」. 증조할아버지 글씨예요. 이름이… 이름이 다 적혀 있어요."},{"s":"q:sn_cheongpa","t":"근데 반밖에 없어요. 나머지 반은 궤짝 밑에 붙어서 안 떨어졌어요. 물속에서 당겨 봤는데 찢어질 것 같아서…."},{"s":null,"t":"청파의 몸이 덜덜 떨렸다. 이가 딱딱 부딪는 소리가 물굴에 울렸다. 갈매가 제 겉옷을 벗어 청파에게 둘렀다."},{"s":"southern_remnant:galmae","t":"일단 올라가. 몸부터 녹여. 입술이 퍼래, 꼬맹이. 그 꼴로는 아무것도 못 해."},{"s":"q:r71_seoharam","t":"위에서 불 피우고… 뜨거운 걸 먹여야 해요. 이 물굴 물에 고기가 살아요. 아까 등잔 밑으로 은빛이 지나갔어요."},{"s":null,"t":"물굴에 사는 고기는 청씨 선단 뱃사람들이 우물에 놓아 길렀다는 잉어의 후손이라, 나는 그 청씨 잉어를 낚아 쪄서 청파에게 먹이기로 했다."}],"reward":{"xp":2781}},{"quest_id":"mdq_11","step":4,"title":"두 번째 잠수","goal":"옛 나루 저자에서 4번 채집하고 물굴에서 2번 낚시해 청씨 잉어찜 1그릇을 쪄 청파에게 넘긴다","need":{"at":["old_ferry_market"],"tasks":[{"t":"gather","n":4,"r":["old_ferry_market"]},{"t":"fish","n":2,"r":["old_ferry_market"]},{"t":"craft","items":["cheong_carp_steam"],"n":1}],"give":{"cheong_carp_steam":1}},"lines":[{"s":null,"t":"청씨 잉어찜 한 그릇을 다 비우고서야 청파의 입술에 핏기가 돌았다. 그 밤 청파는 궤짝에서 꺼낸 반쪽 명단을 무릎에 펴 놓고 잠들지 않았다."},{"s":null,"t":"이튿날 아침, 우물 위로 흑련 심부름꾼이 서신을 들고 왔다. 한설 개인 인장이 찍힌 서신이었다. 나는 모두 앞에서 서신을 펼쳤다."},{"s":"night_office:han","t":"조사원. 곽두칠 줄을 아직 쫓고 있다. 네 조각은 도장 자리가 찢겨 나갔다지. 그래서 서고에 남은 열 해 전 정리 명부 원본에서 그 줄을 찾는 중이다. 원본에는 도장이 남아 있을 거다."},{"s":"night_office:han","t":"정리관이 수향 도방을 찾아갔다고 들었다. 그 사람은 늘 한 장 앞에 있다. 장을 건지거든 몸에 지니고 혼자 다니지 마라. 지금 몇 장이냐. 답은 짧게 해라."},{"s":"q:r71_seoharam","t":"답은… 셋이라고 하면 돼요? 넷째 장을 건졌으니까요."},{"s":"southern_remnant:galmae","t":"아직 이을 이 칸을 안 채웠잖아. 둘 반이야."},{"s":null,"t":"나는 답장에 「둘, 그리고 물에서 하나」라고 적었다. 한설이라면 그것으로 알아들을 터였다."},{"s":null,"t":"답장을 심부름꾼에게 건네고 돌아섰을 때, 청파가 허리에 줄을 다시 감고 있었다."},{"s":"north_league:yeo","t":"무엇을 하는 거요."},{"s":"q:sn_cheongpa","t":"나머지 반 건지러 가요."},{"s":"southern_remnant:galmae","t":"미쳤어? 장은 건졌잖아! 너 어제 아흔여섯 숨에 입술이 새파랬어!"},{"s":"q:sn_cheongpa","t":"그 애들은 일흔 해 전에 선창에서 배를 기다렸어요. 증조할아버지 배가 태우러 돌아갔는데, 수향이 그 배를 여기 가라앉혔어요. 이번에도 제가 안 데려오면, 그 애들은 또 선창에 남는 거예요."},{"s":"q:r71_seoharam","t":"이름은 반이라도 부를 수 있어요. 반만 가져와도…"},{"s":"q:sn_cheongpa","t":"반만 부르면 나머지 반은요? 그 애들이 또 「값을 못 낸 쪽」이 되는 거잖아요."},{"s":null,"t":"아무도 대답하지 못했다. 나는 청파 앞에 섰다. 위험하면 바로 줄을 당기라고 했다. 한 번이라도 당기면 끌어올리겠다고 했다."},{"s":"q:sn_cheongpa","t":"네. 약속해요. {이름} 님 손목에 감긴 거, 저도 다 느껴요."},{"s":null,"t":"여운비가 무언가 말하려다 입을 다물고, 줄을 다시 손목에 감았다. 이번에는 네 번을 감았다."},{"s":null,"t":"청파가 물속으로 들어갔다. 서하람이 숨을 세기 시작했다. 백을 넘고 백오십을 넘어도 줄은 당겨지지 않았다."},{"s":"q:r71_seoharam","t":"백칠십… 백칠십하나… 너무 길어요, 너무 길어요…!"},{"s":null,"t":"이백 번째 숨에서 줄이 갑자기 팽팽하게 당겨졌다. 내 손목이 물 쪽으로 홱 끌려갔다. 다음 순간 줄이 툭, 늘어졌다."},{"s":"north_league:yeo","t":"청파! 청파아!"},{"s":null,"t":"여운비가 소리를 지르며 줄을 끌었다. 나도 끌었다. 갈매가 달려들어 셋이 함께 끌었지만, 줄은 물속 무언가에 걸린 듯 꿈쩍도 하지 않았다."},{"s":"southern_remnant:galmae","t":"걸렸어! 이 빌어먹을 배에 걸렸다고!"},{"s":null,"t":"줄이 여운비의 손목을 파고들었다. 붉은 피가 줄을 타고 똑똑 떨어졌다. 여운비는 손을 놓지 않았다."},{"s":"q:r71_seoharam","t":"제가 들어갈게요! 줄 타고 따라 내려가면…"},{"s":"southern_remnant:galmae","t":"넌 헤엄도 못 치잖아! 가만있어!"},{"s":null,"t":"그때 물굴 안쪽 어둠에서 등불 서너 개가 다가왔다. 작은 배 한 척이 소리도 없이 물을 가르고 있었다. 뱃머리에 정청 표식이 달려 있었다."},{"s":null,"t":"노를 젓는 사람이 넷이었다. 등불이 바로 머리 위에서 흔들리는데도, 그들의 그림자는 물 위에 반쯤만 드리워 있었다. 노를 쥔 손끝은 먹에 담갔다 뺀 것처럼 까맸다."},{"s":null,"t":"넷 가운데 하나가 물속으로 긴 갈고리를 내렸다. 철컥, 무언가에 걸리는 소리가 났다. 그들이 끌어 올린 것은 청파였다."},{"s":null,"t":"배에 실린 청파의 몸은 축 늘어져 있었다. 가슴이 움직이지 않았다. 품에는 궤짝 밑에서 떼어 낸 나머지 명단이 꼭 끌어안겨 있었다."},{"s":"q:r71_seoharam","t":"숨을 안 쉬어요… 청파가 숨을 안 쉬어요! 누구 청심환! 청심환 있어요?!"}],"reward":{"xp":2781}},{"quest_id":"mdq_11","step":5,"title":"숨","goal":"옛 나루 저자에서 청심환 1개와 영초 차 1개를 청파에게 넘긴다","need":{"at":["old_ferry_market"],"give":{"tonic":1,"spirit_tea":1}},"lines":[{"s":null,"t":"배가 물굴 바닥에 닿기도 전에 갈매가 뛰어올라 청파를 받아 안았다. 갈매는 청파를 돌바닥에 눕히고 그 가슴에 두 손을 포개 얹었다."},{"s":"southern_remnant:galmae","t":"숨 쉬어. 야, 꼬맹이! 숨 쉬라고!"},{"s":null,"t":"갈매가 가슴을 꾹꾹 눌렀다. 서른 번을 누르고 청파의 입에 숨을 두 번 불어넣었다. 그것을 되풀이하는 동안 갈매는 한 번도 고개를 들지 않았다."},{"s":null,"t":"{직업:의무=나는 청파의 목에 손가락을 대고 맥을 찾으며 갈매에게 누르는 박자를 셌다/*=나는 청파 곁에 무릎을 꿇고 얼음처럼 언 손을 두 손으로 비볐다}. 서하람이 청파의 다른 손목을 쥐었다."},{"s":"q:r71_seoharam","t":"맥이… 없어요. 아니, 있어요! 아주 약하게… 아주 약하게 있어요!"},{"s":"southern_remnant:galmae","t":"이 꼬맹이 새끼가! 엿 돌려준다며! 단비한테 돌려준다며! 눈 떠!"},{"s":null,"t":"여운비가 피투성이 손으로 청파의 손을 잡았다. 여운비의 손이 덜덜 떨렸다."},{"s":"north_league:yeo","t":"청파. 돌아오시오. 줄은 아직 내가 쥐고 있소."},{"s":null,"t":"나는 청파의 이름을 불렀다. 금빛 실이 청파의 가슴께에 닿았다. 서하람이 부르고, 여운비가 불렀다. 갈매는 숨을 불어넣는 사이사이 이를 악물고 불렀다."},{"s":null,"t":"실이 넷으로 늘어 청파의 가슴 위에서 엉켰다. 다섯 번째로 숨을 불어넣었을 때 청파가 컥, 하고 물을 토해 냈다."},{"s":null,"t":"청파는 기침을 하며 몸을 비틀었다. 눈을 뜨자마자 품부터 더듬었다."},{"s":"q:sn_cheongpa","t":"명… 명단…"},{"s":"q:r71_seoharam","t":"있어요! 품에 그대로 있어요! 하나도 안 젖었어요!"},{"s":null,"t":"청파는 그제야 다시 눈을 감았다. 갈매가 털썩 주저앉아 젖은 소매로 눈가를 거칠게 훔쳤다."},{"s":"southern_remnant:galmae","t":"…다시 이러면 진짜 패 버릴 거야."},{"s":null,"t":"고개를 든 갈매의 눈이 배 위에 멎었다. 노를 쥔 넷이 등불 아래 그대로 서 있었다. 반쯤만 드리운 그림자, 먹빛 손끝이 등불에 또렷했다. 갈매가 칼자루를 움켜쥐고 벌떡 일어섰다."},{"s":"southern_remnant:galmae","t":"저것들이야! 무관 거리 우물에서 놓친 놈이랑 똑같아! 장서각에 불 지르고 흑련 장부 털어 간 놈들!"},{"s":null,"t":"여운비의 칼이 스르릉 뽑혔다. 서하람은 청파를 감싸 안은 채 뒷걸음쳤다. 나는 청파와 배 사이를 막고 섰다."},{"s":"q:r71_seoharam","t":"그림자가… 등불이 바로 위에 있는데 그림자가 반밖에 없어요…."},{"s":null,"t":"넷은 칼끝 앞에서도 아무 말이 없었다. 눈길도 피하지 않았다. 등불 아래 그들의 얼굴은 하나같이 희미해서, 눈코입이 있는데도 기억에 남지 않았다."},{"s":null,"t":"그들 뒤 뱃머리에서 한 사람이 일어섰다. 장터에서 꿀 단지를 내밀던 그 사내였다. 사내는 장부 모서리를 엄지로 접었다 폈다 하며 우리를 둘러보았다."},{"s":"q:md_gyeonghyeon","t":"칼은 넣어 두시오, 여씨 집안 호송대장. 내 일꾼들이오. 이 아이를 건진 손도 저 손이고."},{"s":"southern_remnant:galmae","t":"일꾼? 장서각에 불을 지른 게 네 일꾼이라고?"},{"s":"q:md_gyeonghyeon","t":"불은 미안하게 됐소. 기록관의 두 손까지 상할 줄은 몰랐지."},{"s":null,"t":"경현은 그것이 사과의 전부라는 듯 입을 닫았다. 왜 불을 놓았는지는 말하지 않았다. 갈매가 이를 악물고 한 걸음 내딛자 여운비가 칼등으로 갈매의 앞을 막았다."},{"s":"north_league:yeo","t":"지금은 안 되오. 청파가 먼저요."},{"s":"southern_remnant:galmae","t":"저 자식이 우리 다 속였잖아! 서가 불도, 장부도, 다!"},{"s":"q:md_gyeonghyeon","t":"속인 적은 없소. 묻지 않았을 뿐이지. 당신은 묻기 전에 칼부터 뽑지 않소, 남명 정찰대장."},{"s":"southern_remnant:galmae","t":"안 물었다고? 흑련 장부고에서는 「문지기들 눈이 피곤했던 모양」이라며? {이름}이(가) 다 말해 줬어. 무관 거리에선 내가 대놓고 물었지. 두건 쓴 놈 네가 보냈냐고. 그랬더니 「나를 보낼 사람도 없고」래. 저기 노 젓는 놈들은 그럼 누가 보냈는데!"},{"s":null,"t":"경현은 노 젓는 넷을 한 번 돌아보았다. 넷은 고개를 숙인 채 꼼짝도 하지 않았다."},{"s":"q:md_gyeonghyeon","t":"저들은 내가 보낸 게 아니라 나를 따라온 거요. 말장난이라 하면 할 말은 없소."},{"s":null,"t":"경현이 배를 가리켰다."},{"s":"q:md_gyeonghyeon","t":"그 아이를 저 쇠 손잡이로 업고 올라갈 셈이오? 타시오. 물굴 끝에 정리소 배가 대는 돌 나루가 있소. 거기 계단이 넓소. 장을 모아 와야 내가 거두지. 그러니 당신들은 살아야 하오."},{"s":null,"t":"갈매가 이를 갈았다. 여운비는 청파의 얼굴을 내려다보았다. 청파의 입술은 아직 파랬다. 나는 청파를 업고 배에 올랐다. 다른 이들이 칼을 쥔 채 내 뒤를 따랐다."}],"reward":{"xp":2781}},{"quest_id":"mdq_11","step":6,"title":"배 위에서","goal":"옛 나루 저자 정리소 배 위에서 청파를 데우며 쉰다","need":{"at":["old_ferry_market"],"tasks":[{"t":"rest","r":["old_ferry_market"],"n":1}]},"lines":[{"s":null,"t":"정리소 배는 소리 없이 미끄러졌다. 노를 젓는 넷은 한마디도 하지 않았다. 가까이 앉으니 그들에게서 오래 묵은 먹 냄새가 났다."},{"s":null,"t":"청파는 내 무릎을 베고 누워 있었다. 갈매가 청파의 발을 제 품에 넣어 녹였다. 서하람은 청파의 손목을 놓지 않고 맥을 셌다. 여운비는 칼을 무릎에 놓고 노 젓는 이들의 등만 보았다."},{"s":null,"t":"경현은 뱃머리에 앉아 있었다. 장부를 펴 놓았지만 넘기지 않았다. 경현은 뱃전 너머 검은 물 밑을 오래 내려다보았다. 무언가 들리는 사람처럼 고개를 조금 기울이고 있었다."},{"s":"q:r71_seoharam","t":"…뭘 보세요? 물밖에 없는데요."},{"s":"q:md_gyeonghyeon","t":"물만 있는 게 아니오. 붙드는 물은 몸에서 빠져나간 이름을 흩어지지 않게 붙들어 두오. 그래서 이 밑에는 일흔 해 묵은 등도 이름이 많이 가라앉아 있지."},{"s":null,"t":"경현은 그 말을 하고도 한참 물에서 눈을 떼지 않았다. 이윽고 장부를 넘기며 고개도 들지 않고 말했다."},{"s":"q:md_gyeonghyeon","t":"청씨 선단의 막내 증손이 증조부의 배에서 명단을 건져 냈구려. 그 노인은 그 명단을 쓰고 사흘 뒤에 목을 맸소. 장부에는 안 적혔지만."},{"s":null,"t":"청파의 눈꺼풀이 떨렸다. 나는 청파의 귀를 손바닥으로 덮었다. 경현에게는 그만하라고 했다."},{"s":"q:md_gyeonghyeon","t":"미안하오. 버릇이오. 사람 이름을 들으면 그 집 장부가 먼저 펼쳐지오."},{"s":null,"t":"장부를 덮은 경현이 나를 보았다."},{"s":"q:md_gyeonghyeon","t":"당신은 왜 이 아이를 내려보냈소? 장은 이미 건졌는데."},{"s":null,"t":"나는 내가 보낸 것이 아니라 청파가 간 것이라고 했다. 나는 줄을 잡았을 뿐이라고 했다."},{"s":"q:md_gyeonghyeon","t":"줄을 잡았을 뿐. 좋은 말이오. 나도 백 년 동안 그렇게 말했소. 나는 붓을 잡았을 뿐이라고. 붉은 줄을 긋는 손은 늘 내 손이었는데도."},{"s":"q:md_gyeonghyeon","t":"반쪽 명단 두 장에 적힌 그 아이들 이름을 저 아이 혼자 다 부를 수 있을 것 같소? 일흔 해 전 이름이오. 불러 줄 사람이 하나도 안 남은 이름이지. 내 장부의 만삼천 이름도 다 그렇소."},{"s":null,"t":"나는 혼자서는 못 부른다고 했다. 그래서 다 같이 부를 거라고 했다. 경현이 나를 보며 아주 천천히 장부 모서리를 접었다."},{"s":"q:md_gyeonghyeon","t":"…다 같이. 솔내에서도 다 같이 불렀소. 마흔두 집이 다. 아무도 남지 않았지."},{"s":null,"t":"아무도 대꾸하지 못했다. 노가 물을 가르는 소리만 찰박찰박 이어졌다."},{"s":null,"t":"배가 물굴 끝의 돌 나루에 닿았다. 갈매가 먼저 뛰어내리며 경현 쪽으로 침을 퉤 뱉었다. 노 젓는 이들은 그것을 보고도 눈 하나 깜빡이지 않았다."},{"s":"q:md_gyeonghyeon","t":"남명 정찰대장. 화로 앞의 노장께 안부를 전해 주시오. 그분 이름은 오래전부터 내 장부에 있소. 줄을 반만 그어 접어 둔 채로."},{"s":null,"t":"갈매가 홱 돌아섰다. 경현은 이미 배를 밀어내고 있었다. 배가 어둠 속으로 멀어지는 동안 경현의 목소리가 물굴 벽에 부딪혀 여러 번 울렸다."},{"s":"q:md_gyeonghyeon","t":"조사원, 도제조께도 안부를 전하시오. 그분 등잔 심지가 얼마나 남았는지 나도 궁금하다고."},{"s":"southern_remnant:galmae","t":"저 자식이 할배 이름을 어떻게 알아? 접어 둔 채로라니, 그게 무슨 소리야!"},{"s":null,"t":"갈매의 주먹이 바들바들 떨렸다. 여운비가 갈매의 어깨를 잡았다. 갈매는 뿌리치지 않았다."},{"s":"north_league:yeo","t":"서가에 불을 놓은 손도, 장부를 턴 손도 저 사람 손이었소. 감찰관이 그자는 늘 한 장 앞에 있다더니, 그 말이 맞소. 그러니 우리가 장을 먼저 이어야 하오. 둘째 장은 북령 땅에서, 셋째 장은 적월 장터에서 이었소. 넷째 장은 수향 도방 앞에서 잇읍시다."},{"s":"q:r71_seoharam","t":"도방님께 가요. 단비 씨도 거기 있고요."},{"s":null,"t":"나는 청파를 다시 업었다. 청파가 내 등에서 작게 웅얼거렸다. 명단은 그때도 청파의 품 안에 있었다."}],"reward":{"xp":2781}},{"quest_id":"mdq_11","step":7,"title":"이을 이, 그리고 단비","goal":"구름나루에 도착해 진소랑 앞에서 넷째 장 「이을 이」 칸을 채운다","need":{"at":["river_ferry"],"tasks":[{"t":"travel","r":["river_ferry"],"n":1}]},"lines":[{"s":null,"t":"진소랑은 넷째 장을 받아 들고 오래 읽었다. 맨 앞줄 수향 조상의 이름을 손끝으로 쓸어 보았다. 그 곁에 청파가 반쪽씩 건진 명단 두 장을 나란히 펴 놓았다."},{"s":null,"t":"진소랑의 손이 명단 위에서 멈췄다. 진소랑은 이름 하나하나를 손끝으로 짚어 내려갔다. 매향이 곁에서 소리 없이 그 이름들을 새 장부에 옮겨 적었다."},{"s":"river_alliance:jin","t":"일흔 해 동안 물에 묻어 둔 이름들이에요. 이제 그 이름들을 해마다 부르겠다는 약속을 수향이 지킬게요. 끝줄은 당신이 채워 주세요.","fac_not":"river_alliance","spec":2,"grp":1},{"s":"river_alliance:jin","t":"연맹이 일흔 해 동안 물에 묻어 둔 장부예요. 연맹 사람 손으로 건져 왔으니 연맹 사람 손으로 이어 주세요. 끝줄은 당신 몫이에요.","fac":"river_alliance","spec":1,"grp":1},{"s":"river_alliance:jin","t":"청파야."},{"s":"q:sn_cheongpa","t":"…네."},{"s":"river_alliance:jin","t":"이 아이들 이름, 첫 해에는 네가 불러. 그다음 해부터는 수향이 다 같이 부를게. 매향이 장부에 적어 둘 거야. 값은 안 적고."},{"s":null,"t":"청파는 쉰 목소리로 대답하다가 콜록콜록 기침을 했다. 기침 끝에 쇳소리가 났다. 수향 의원이 청파의 등을 짚어 보더니 고개를 저었다."},{"s":"q:md_river_doctor","t":"숨통이 상했네. 물 밑에 너무 오래 있었어. 이제 깊은 물은 못 들어가."},{"s":null,"t":"청파의 얼굴이 잠깐 굳었다가, 이윽고 웃었다. 늘 들뜨던 웃음보다 조금 조용한 웃음이었다."},{"s":"q:sn_cheongpa","t":"그럼 배 몰래요. 노들 영감님처럼요. 사람 실어 나르는 거, 이번엔 값 안 받고요."},{"s":null,"t":"진소랑이 붓을 내밀었다. 내가 「이을 이」 칸에 이름을 적자 흰 불꽃이 금빛으로 바뀌었다. 품속의 두 장과 금빛 실로 이어지자, 실은 손가락만큼 굵어졌다."},{"s":"q:sn_cheongpa","t":"셋이에요. 이제 넷 남았어요. {이름} 님이 일곱 장을 다 이으면 맹약 마당에서 진을 풀 수 있는 거죠. 그럼 이 애들 같은 이름이 또 안 생기고요."},{"s":null,"t":"그날 저녁 나는 매향에게 종이를 얻어 한설에게 서신을 썼다. 물굴의 정리소 배와 그림자가 반만 드리운 넷, 그리고 뱃머리에 선 정리관을 적었다. 이번에는 짧게 쓰지 못했다."},{"s":null,"t":"그날 밤 우리는 약방 단비 곁에 둘러앉았다. 청파도 이불을 두르고 나와 앉았다. 진소랑은 장부를 펴 들고 문간에 섰다. 장부의 「밤」 칸에 동그라미를 칠 참이었다."},{"s":null,"t":"단비의 잿빛은 어깨에서 멈춘 채 물러나지 않았다. 차례로 이름을 부르는 동안 여운비는 늘 그랬듯 단비의 오른손을 쥐고만 있었다."},{"s":null,"t":"그날 밤에는 여운비의 손목에 피 묻은 붕대가 감겨 있었다. 청파를 붙들었던 손이었다. 붕대 끝이 단비의 손등 위에 가만히 얹혀 있었다."},{"s":null,"t":"한참 뒤에 여운비가 입을 열었다. 아주 작은 목소리였다."},{"s":"north_league:yeo","t":"…단비."},{"s":null,"t":"금빛 실 하나가 단비의 가슴께에 닿았다. 지금까지 닿은 어떤 실보다 굵고 밝았다. 방 안이 등잔을 하나 더 켠 것처럼 환해졌다."},{"s":null,"t":"어깨에서 버티던 잿빛이 사르르 물러났다. 잿빛은 팔꿈치를 지나 손목까지 내려갔다. 단비의 입술이 아주 조금 달싹였다."},{"s":"red_moon_cult:danbi","t":"…네에…."},{"s":null,"t":"대답이었다. 모두가 여운비를 바라보았다. 여운비는 고개를 돌리지 않고 단비의 얼굴만 보았다."},{"s":"north_league:yeo","t":"…빚지고는 못 사는 성미라서 그렇소."},{"s":null,"t":"이불을 두른 청파가 기침 섞인 웃음을 터뜨렸다. 갈매도 고개를 숙인 채 어깨를 들썩였다. 서하람은 소매로 눈을 꾹 눌렀다."},{"s":"southern_remnant:galmae","t":"진작 좀 부르지. 북령은 꼭 누가 물에 빠져야 말을 해."},{"s":"north_league:yeo","t":"…두고 가지 않소. 다음 장으로 갈 때도 데려가오. 부를 사람이 곁에 있어야 하오."},{"s":"q:r71_seoharam","t":"다음은 천명 장이에요. 지워진 땅의 첫 관상대요. 저희 집 장이니까… 제가 앞장설게요."},{"s":null,"t":"서하람이 먼저 앞장서겠다고 한 것은 처음이었다. 그 눈에는 졸음이 조금도 없었다."}],"reward":{"xp":2781,"gil":500,"items":{"burrow_scale":3,"lamp_wick_core":1}}},{"quest_id":"mdq_12","step":1,"title":"업힌 관측관","goal":"첫 관상대에 도착해 업힌 관측관을 본다","need":{"at":["first_observatory"],"tasks":[{"t":"travel","r":["first_observatory"],"n":1}]},"lines":[{"s":null,"t":"첫 관상대는 등도에서 가장 높은 언덕 위에 있었다. 돌계단이 언덕 허리를 휘감고 끝없이 올라갔다. 계단마다 흰 이끼가 바스러져 있었다."},{"s":null,"t":"단비의 들것은 여운비와 내가 들었다. 청파는 물동이를 지고 뒤따랐다. 계단 몇 개마다 청파의 숨이 쌕쌕 끊겼다. 나는 그때마다 걸음을 늦췄다."},{"s":"q:sn_cheongpa","t":"괜찮아요… 숨이 좀 짧아진 것뿐이에요. 노 저을 땐 숨 안 길어도 돼요."},{"s":null,"t":"맨 앞의 서하람이 계단 중턱에서 휘청했다. 두루마리를 끌어안은 채 무릎이 꺾였다. 바로 뒤의 갈매가 서하람의 팔을 낚아챘다."},{"s":"southern_remnant:galmae","t":"야, 잠꾸러기! 왜 그래!"},{"s":"q:r71_seoharam","t":"…괜찮아요. 발이 좀… 말을 안 들어서요."},{"s":"southern_remnant:galmae","t":"너 며칠째 안 잤어. 단비 부르느라 밤마다 깨 있었잖아. 내가 다 봤어."},{"s":null,"t":"갈매는 대답을 기다리지 않고 서하람 앞에 등을 대고 쭈그려 앉았다."},{"s":"southern_remnant:galmae","t":"업혀."},{"s":"q:r71_seoharam","t":"…관측관이 업혀서 관상대에 오르면 안 되는데요."},{"s":"southern_remnant:galmae","t":"안 되는 거 누가 정했어. 천명원? 업혀."},{"s":null,"t":"서하람이 갈매의 등에 업혔다. 갈매는 끙 소리를 한 번 내고 성큼성큼 계단을 올랐다. 서하람은 갈매의 어깨에 이마를 댄 채 열 계단쯤 가다가 작게 웃었다."},{"s":"q:r71_seoharam","t":"갈매 씨 등에서 숯 냄새가 나요. 잔불촌 화로 냄새요. …따뜻해요."},{"s":"southern_remnant:galmae","t":"냄새 맡지 마. 떨어뜨린다."},{"s":null,"t":"꼭대기에 오르자 녹슨 혼천의가 멈춰 서 있었다. 그 위 하늘은 별 하나 없이 희기만 했다. 서하람이 갈매의 등에서 내려와 혼천의를 오래 올려다보았다."},{"s":"q:r71_seoharam","t":"천명원 사람들이 처음 별을 읽은 자리예요. 「첫 눈」이라고 불러요. 별을 처음 본 눈이라서요. …근데 별이 하나도 없네요."},{"s":null,"t":"관상대 안쪽 벽에 두꺼운 돌판 하나가 박혀 있었다. 가운데에 자물쇠가 달렸고, 열쇠 구멍 둘레에 오래된 먹 자국이 남아 있었다. 돌판 틈으로 흰 불꽃의 빛이 아주 희미하게 새어 나왔다."},{"s":"north_league:yeo","t":"장이 저 안에 있소?"},{"s":"q:r71_seoharam","t":"네. 별 기록판이에요. 이건 태사령님만 열 수 있어요. 열쇠를 가지고 계시거든요."},{"s":"red_moon_cult:danbi","t":"…음… 열쇠…."},{"s":null,"t":"들것 위의 단비가 잠결에 중얼거렸다. 여운비가 단비의 이마를 짚어 보고 고개를 저었다. 아직 깨어난 것은 아니었다."},{"s":"southern_remnant:galmae","t":"그 영감 말도 안 하잖아. 석판에 세 글자 쓰고 끝이었지."},{"s":"q:r71_seoharam","t":"말은 안 하셔도… 열쇠는 주실지도 몰라요. 관성대로 가요."},{"s":null,"t":"돌판 아래 그늘에서 사그락 소리가 났다. 먹 낀 것들이 혼천의 다리를 타고 기어 내려오고 있었다."},{"s":"southern_remnant:galmae","t":"잠꾸러기는 무녀 옆에 붙어 있어. 오늘은 내가 다 벤다."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":2,"title":"다시 연 입","goal":"첫 관상대에 도착해 녹슨 혼천의 바퀴를 3번 쓰러뜨리고 무극 관성대에 도착한다","need":{"at":["star_observatory"],"tasks":[{"t":"travel","r":["first_observatory"],"n":1},{"t":"win","n":3,"m":["dd_obs_2"]},{"t":"travel","r":["star_observatory"],"n":1}]},"lines":[{"s":null,"t":"무극 관성대로 가는 길에 서하람은 한마디도 하지 않았다. 관성대 문간에 흑련 심부름꾼이 서신 한 통을 들고 기다리고 있었다. 한설 개인 인장이 찍혀 있었다."},{"s":"night_office:han","t":"조사원. 네 서신 받았다. 서고 원본 명부에서 곽두칠 줄을 찾았다. 반만 그은 붉은 줄 끝에 도장이 남아 있었다. 「정리소 서리」."},{"s":"night_office:han","t":"서리방 명단을 백 년 치 뒤졌다. 정리소 서리 자리에 앉은 사람은 백 년 동안 하나뿐이었다. 그 사람이 지금 정리관 직함을 달고 있다. 줄을 긋다 멈추게 한 손이 정리관이라는 얘기다. 확인될 때까지 아무에게도 말하지 마라. 판관 회의에도."},{"s":null,"t":"서하람이 두루마리를 펼쳐 관아 터에서 베껴 둔 미룸 칸을 짚었다. 「서리」 도장의 테두리 모양이 한설이 서신 끝에 그려 보낸 도장과 똑같았다. 「정리소 서리 경현」이라는 서명도 그 장에 함께 베껴져 있었다."},{"s":null,"t":"그 서명을 보자 갈매가 주먹으로 문기둥을 쾅 쳤다."},{"s":"southern_remnant:galmae","t":"줄을 미뤄 줘? 그럼 그놈들 목숨줄을 그 자식이 쥐고 있다는 거잖아. 그래서 말을 안 하는 거고!"},{"s":"north_league:yeo","t":"무관 거리 그자가 그랬소. 줄을 마저 그으면 사흘이면 죽는다고."},{"s":null,"t":"관성대 안쪽 방에서 태사령 하후정은 석판 앞에 앉아 있었다. 서이연이 엎어 버렸던 석판은 바로 세워져 있었다. 「정리관 다녀감」을 지우고 하후정이 다시 적은 「보내라」 세 글자가 그대로 남아 있었다."},{"s":null,"t":"나는 그 노인이 입을 여는 것을 한 번 본 적이 있었다. 구중 봉연으로 가는 길을 별모래로 그리던 날이었다. 「붉은 인장은 제자리에 있을 때 빛난다」 한마디를 한 뒤로, 하후정은 다시 입을 닫았다."},{"s":"q:r71_seoharam","t":"태사령님. 첫 관상대 기록판을 열어야 해요. 열쇠를 주세요."},{"s":null,"t":"하후정의 손이 멈췄다. 분필을 쥔 손등에 핏줄이 섰다. 하후정은 오래도록 아무것도 쓰지 않았다."},{"s":"mandate_court:seo","t":"안 됩니다, 태사령님."},{"s":null,"t":"문간에 수석 관측관 서이연이 서 있었다. 늘 졸린 얼굴이던 노관측관의 눈이 오늘은 또렷했다. 서이연은 성큼 들어와 석판을 손바닥으로 덮었다."},{"s":"mandate_court:seo","t":"람이를 거기 보내지 말자고 말씀드렸잖아요. 그 판을 열면…"},{"s":"q:r71_seoharam","t":"할머니. 그 판을 열면 뭐요?"},{"s":null,"t":"서이연은 대답하지 못한 채 눈길을 나에게로 옮겼다."},{"s":"mandate_court:seo","t":"…조사원님. 별모래 담아 오셨던 날에도, 지난번 이 방에서도 이 아이 얘기는 못 했어요. 오늘은 해야겠네요."},{"s":null,"t":"하후정이 서랍에서 녹슨 열쇠 하나를 꺼냈다. 열쇠가 탁자 위에 놓이며 탁, 작은 소리가 방 안에 크게 울렸다.","fac_not":"mandate_court","spec":2,"grp":1},{"s":null,"t":"하후정이 서랍에서 녹슨 열쇠 하나를 꺼냈다. 열쇠는 서하람이 아니라 내 손바닥 위에 놓였다. 천명 사람에게 맡기는 열쇠였다.","fac":"mandate_court","spec":1,"grp":1},{"s":null,"t":"하후정의 입술이 움직였다. 처음에는 소리가 나지 않았다. 마른 나뭇가지가 부러지는 듯한 소리가 두어 번 새어 나오고서야 말이 되었다."},{"s":null,"t":"그 목소리가 나오자 처마 끝의 풍경이 바람도 없이 땡그랑 울렸다. 서이연이 숨을 들이켰다. 청파는 엉겁결에 제 입을 막았다. 여운비마저 칼자루에서 손을 뗐다."},{"s":"mandate_court:hahu","t":"…봉연 길을 그리던 날, 나는 인장 얘기만 했다. 하지 않은 말이 있다."},{"s":"mandate_court:hahu","t":"백 년 전… 그 별 기록을 처음 잘못 읽은 것은 내 스승의 스승이었다. 나는 십 년 전에 그것을 알았다. 알고 나서 입을 닫았다. 천명원의 말 한마디가 칸을 긁었으니, 다시는 천명원의 말로 세상을 움직이지 않겠다고."},{"s":"southern_remnant:galmae","t":"칸을 긁은 게… 천명원 말이었다고?"},{"s":"mandate_court:hahu","t":"그렇다, 남명 아이야. 네 나라를 무너뜨린 말이 이 집에서 나갔다."},{"s":null,"t":"갈매의 얼굴이 하얗게 질렸다. 갈매는 서하람을 보았지만, 서하람은 갈매를 보지 못하고 고개를 숙였다."},{"s":"mandate_court:hahu","t":"그 기록판을 열면 하람이 알게 될 것이 하나 더 있다. 이연이 그 안에 넣어 둔 것이다. …이연아. 네가 먼저 말해 주어라. 내가 십 년을 닫았듯, 너는 스무 해를 닫았다."},{"s":null,"t":"서이연이 석판에서 뗀 손이 떨리고 있었다."},{"s":"mandate_court:seo","t":"…오늘 밤에요. 별이 뜨면요. 별 아래서 말할게요. 람아, 그때까지 할머니 약 좀 달여 줄래? 눈이 침침해서 별이 안 보이면 말을 못 하겠다."},{"s":"q:r71_seoharam","t":"…네. {이름} 님, 같이 약초 뜯어 줄래요? 저 혼자서는 손이 떨려서 못 할 것 같아요."},{"s":null,"t":"서이연의 눈은 마음이 흔들릴 때마다 더 흐려진다고 했고, 서하람은 약초를 약제 바탕과 함께 달여 마음을 가라앉히는 안신탕을 올리자고 했다."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":3,"title":"그날 밤 온 아기","goal":"백옥 천문탑에서 5번 채집하고 안신탕 1그릇을 달여 서이연에게 넘긴다","need":{"at":["star_observatory"],"tasks":[{"t":"gather","n":5,"r":["white_tower"]},{"t":"craft","items":["calm_brew"],"n":1}],"give":{"calm_brew":1}},"lines":[{"s":null,"t":"별이 뜨자 관성대 지붕 위가 은가루를 뿌린 듯 반짝였다. 등도의 흰 하늘을 보고 온 눈에는 별 하나하나가 따가울 만큼 밝았다."},{"s":null,"t":"서이연은 지붕 끝 관측 자리에 앉아 안신탕을 한 모금 마셨다. 서하람이 그 곁에 앉자, 서이연이 손을 더듬어 서하람의 얼굴을 쓸었다."},{"s":"mandate_court:seo","t":"람아. 결국 그 판을 열겠구나."},{"s":"q:r71_seoharam","t":"할머니가 말해 주면요."},{"s":null,"t":"우리는 조금 떨어져 앉았다. 갈매는 지붕 끝 기와에 걸터앉았다. 여운비는 단비의 들것을 바람 없는 쪽으로 돌려 놓았다. 청파는 무릎을 끌어안았다."},{"s":"mandate_court:seo","t":"스무 해 전 동지에, 정리 명부 사본에 갓난아기 이름 하나가 올라왔단다. 부모가 둘 다 거둬진 집 아기였지. 줄 끝의 「부르는 이」 칸은 백 년 전에 긁혀 없어졌고, 그 아기를 불러 줄 사람도 하나도 없었어."},{"s":"mandate_court:seo","t":"나는 그 아기를 빼낼 길이 없었다. 사람의 명부에 있는 한 정리소가 거둬 가니까. 그래서 그 이름을 사람의 명부가 아니라 첫 관상대 별 기록 안에, 별 하나로 적어 넣었다. 별은 정리 명부에 없으니 거둘 수 없잖니."},{"s":null,"t":"서하람은 숨도 쉬지 않는 것 같았다. 서이연의 손이 서하람의 뺨 위에서 멈췄다."},{"s":"mandate_court:seo","t":"그 아기가 너다, 람아. 네 졸린 얼굴이 나를 닮았다고들 하지. 아니다. 너는 밤마다 별 하나에 묶여 있어서, 밤이 되면 넋이 그 별 쪽으로 끌려가 졸렸던 거다."},{"s":"q:r71_seoharam","t":"…그럼 제가 예언은 안 하고 관측만 한다고 한 건요. 그것도 할머니가 가르친 거잖아요."},{"s":"mandate_court:seo","t":"그래. 예언하는 사람은 별을 바꾸고 싶어지니까. 네 별은 바뀌면 안 됐으니까."},{"s":"mandate_court:seo","t":"그 별 기록판이 맹약의 여섯째 장이란다. 장을 풀면 그 안의 별도 함께 탄다."},{"s":"q:r71_seoharam","t":"…별이 타면요. 그럼 저는요?"},{"s":null,"t":"서이연은 대답하기 전에 숨을 한 번 골랐는데, 서하람의 뺨에 얹은 손이 떨렸다."},{"s":"mandate_court:seo","t":"별이 탈 때 누가 네 이름을 불러 주면, 명줄은 별에서 사람한테로 옮겨 묶인다. 넋은 남는다는 얘기다. 그건 부르는 사람들한테 달렸지."},{"s":"mandate_court:seo","t":"눈은 다르다. 그 눈은 스무 해 동안 그 별 하나를 보던 눈이야. 별이 타면 그 별을 보던 눈도 함께 갈 수 있다. 기록판 맨 아래에도 그렇게 적혀 있을 거다."},{"s":null,"t":"지붕 끝에 앉아 있던 갈매가 벌떡 일어섰다. 발밑에서 기와 한 장이 달각 미끄러졌다."},{"s":"southern_remnant:galmae","t":"눈? 눈을 잃는다고요? 그걸 왜 이제야 말해요!"},{"s":"mandate_court:seo","t":"미안하구나, 남명 아이야. 스무 해를 입에 물고 있던 말이라, 오늘에야 나왔다."},{"s":null,"t":"서하람이 무릎 위에 올려놓은 제 두 손을 내려다보았는데, 손가락이 바들바들 떨리고 있었다."},{"s":"q:r71_seoharam","t":"…무서워요, 할머니. 별을 못 보면 저는 관측관도 아니잖아요."},{"s":"mandate_court:seo","t":"그래서 네가 정하라는 거다. 그 장을 내놓을지 말지. 나는 스무 해 전에 한 번 정했으니, 이번엔 네 차례다."},{"s":null,"t":"서하람은 한참 아무 말도 하지 않았다. 졸린 척하지도, 말끝을 흐리지도 않고 서이연의 얼굴만 바라보았다."},{"s":"q:r71_seoharam","t":"…그래도 관측은 할래요. 제 별이 어떻게 타는지 끝까지 제 눈으로 볼래요. 그게 마지막으로 보는 거라도요."},{"s":null,"t":"서이연이 서하람을 끌어안았다. 노관측관의 어깨가 소리 없이 들썩였다."},{"s":null,"t":"한참 뒤 서하람이 일어나 지붕을 내려갔다. 아무도 따라가지 못했다. 나는 잠깐 기다렸다가 뒤따라 내려갔다. 계단참에 서하람이 걸터앉아 있었다."},{"s":null,"t":"갈매가 내 뒤에서 내려왔다. 갈매는 서하람 곁에 섰지만 「잠꾸러기」라고 부르지 않았다. 손을 뻗었다가 그만뒀다."},{"s":"southern_remnant:galmae","t":"…내일 아침에 첫 관상대 다시 가는 거지."},{"s":"q:r71_seoharam","t":"네."},{"s":"southern_remnant:galmae","t":"그럼 또 업혀 갈 거야?"},{"s":"q:r71_seoharam","t":"…안 졸려요. 이제는 졸리지가 않아요. 이상하죠."},{"s":null,"t":"갈매는 대답하지 않고, 서하람의 두루마리를 대신 집어 들고 계단을 먼저 내려갔다."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":4,"title":"잠 못 드는 밤","goal":"첫 관상대에 도착해 야영으로 쉰다","need":{"at":["first_observatory"],"tasks":[{"t":"travel","r":["first_observatory"],"n":1},{"t":"rest","r":["first_observatory"],"n":1}]},"lines":[{"s":null,"t":"첫 관상대 아래 야영 자리에서는 아무도 쉽게 잠들지 못했다. 청파는 단비의 머리맡 엿을 손끝으로 톡톡 건드렸다. 여운비는 칼날을 닦았다. 갈매는 모닥불에서 가장 먼 자리에 누워 등을 돌리고 있었다."},{"s":null,"t":"그 밤에도 여운비가 단비를 불렀다. 이제 여운비는 「무녀」라 부르지 않았다. 금빛 실은 그날 밤에도 가장 굵었지만, 잿빛은 손목 아래로 더 내려가지 않았다."},{"s":null,"t":"서하람은 혼자 관상대 계단 아래 앉아 흰 하늘을 올려다보고 있었다. 나는 담요 한 장을 들고 가 그 곁에 앉았다. 서하람이 담요 한쪽을 끌어 내 무릎에도 덮었다."},{"s":"q:r71_seoharam","t":"{이름} 님. 사람은 별이 안 보이면 어떻게 잠들어요?"},{"s":null,"t":"나는 잠이 안 오면 누가 내 이름을 불러 주던 때를 떠올린다고 했다."},{"s":"q:r71_seoharam","t":"그거 좋네요. 할머니는 저를 늘 「람아」 하고 불렀어요. 하람 말고 람이요. 한 글자요. 별 이름은 다 한 글자거든요. 그래서였나 봐요."},{"s":"q:r71_seoharam","t":"제가 별이면요. 진을 풀 때 저도 같이 타면요. {이름} 님은 제 이름 기억해 줄 거예요?"},{"s":null,"t":"나는 그 물음에 바로 대답하지 않고 서하람의 손을 잡았다. 차가운 손이었다. 나는 「하람」 하고 불렀다. 금빛 실이 서하람의 가슴께에 닿았다."},{"s":"q:r71_seoharam","t":"…따뜻해요. 아, 이래서 다들 부르는구나. 받아 보니까 알겠어요."},{"s":null,"t":"서하람은 담요 속에서 무릎을 끌어안았다. 처음으로 그 얼굴이 어려 보였다."},{"s":null,"t":"계단 위쪽에서 휘파람 소리가 났다. 흑련 심부름꾼이 서신을 들고 내려오고 있었다. 이번에는 다온의 글씨였다. 나는 서신을 서하람에게 건넸다. 서하람이 작은 소리로 읽었다."},{"s":"q:mk_daon","t":"{이름} 님. 오늘 구슬 누나가 아저씨 손에 엽전을 쥐여 줬어요. 아저씨가 그걸 꼭 쥐었어요. 구슬 누나가 울었어요. 저는 안 울었어요."},{"s":"q:mk_daon","t":"저는 아저씨 손톱을 깎아 드렸어요. 장부고에서 아저씨가 저한테 장부 글씨 가르쳐 줄 때 손톱이 길어서 종이가 자꾸 긁혔거든요."},{"s":"q:mk_daon","t":"쪽지는 오늘도 안 펴고 쥐고만 불렀어요. 「아저씨」를 백 번 불렀어요. 목이 쉬어서 구슬 누나가 꿀물을 줬어요. 거기도 다들 꿀물 마셔요?"},{"s":"q:mk_daon","t":"장 몇 개 모았어요? 다 모으면 아저씨 장부도 찾아 주실 거죠? 기다릴게요."},{"s":null,"t":"서하람이 「거기도 다들 꿀물 마셔요?」라는 줄에서 풋 하고 웃다가, 눈물을 툭 떨어뜨렸다."},{"s":"q:r71_seoharam","t":"셋이라고 써 줘요. 넷은… 아직 몰라요. 그리고 꿀물 마신다고요. 정리관이 준 꿀로요. 이건 쓰지 말까요?"},{"s":null,"t":"나는 그것도 쓰자고 했다. 다온이라면 웃을 것 같았다."},{"s":null,"t":"새벽녘 청파가 기침을 하며 일어났다. 청파는 모닥불 곁에 앉은 나를 보더니 냄비를 끌어당겼다."},{"s":"q:sn_cheongpa","t":"내일 열쇠 돌리기 전에 다들 뭘 좀 먹어야 해요. 제가 국 끓일게요. 아, 숨차니까 {이름} 님이 저어 줘요."},{"s":null,"t":"청파가 끓이겠다는 국은 손질한 생선에 노정 건량과 영초 차를 넣고 푹 끓이는 영기 국밥이었는데, 수향 뱃사람들이 큰일을 앞두고 먹는 국이라고 했다."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":5,"title":"기록판","goal":"첫 관상대에서 쉬고 영기 국밥 1그릇을 끓여 아침국으로 일행에게 넘긴다","need":{"at":["first_observatory"],"tasks":[{"t":"rest","r":["first_observatory"],"n":1},{"t":"craft","items":["spirit_gukbap"],"n":1}],"give":{"spirit_gukbap":1}},"lines":[{"s":null,"t":"서하람과 나는 관성대에서 받아 온 녹슨 열쇠를 함께 쥐고 돌렸다. 끼이익, 소리가 관상대 안에 길게 울리더니 덜컥 돌판이 열렸다."},{"s":null,"t":"안에 두꺼운 닥종이 한 장이 끼워져 있었다. 그 위에 흰 불꽃이 떠 있었다. 종이에는 「거둠은 해마다 가장 긴 밤에 한다. 별이 그 수를 정하지 않는다」라는 구절이 적혀 있었다."},{"s":null,"t":"종이 아래에는 오래된 별 기록이 빼곡했다. 서하람의 손가락이 기록을 짚어 내려가다 한 줄에서 멈췄다. 「심지 — 진의 가운데에 사람 하나가 묶였다」라는 줄이었다."},{"s":"north_league:yeo","t":"사람 하나가 묶였다니, 무슨 말이오."},{"s":"q:r71_seoharam","t":"몰라요… 진 가운데에 사람을 심지로 묶었다는 것 같아요. 삼백 년 전에요."},{"s":null,"t":"그 아래 별자리 그림 한가운데에, 다른 별보다 조금 작은 별 하나가 그려져 있었다. 별 옆에 「하람」 두 글자와 붉은 인장 하나가 찍혀 있었다."},{"s":null,"t":"서하람은 그 두 글자를 한참 내려다보다가 손끝을 댔다. 글자는 사람 이름 글자처럼 미지근했다."},{"s":"q:r71_seoharam","t":"…미지근해요. 제 이름이 여기 있었네요. 스무 해 동안요."},{"s":null,"t":"별 그림 바로 아래에 작은 글씨 한 줄이 더 적혀 있었다. 「이 별이 꺼지는 날, 이 별을 보던 눈도 함께 꺼진다.」"},{"s":null,"t":"청파가 그 줄을 읽다가 입을 꾹 다물었다. 갈매는 서하람의 얼굴을 보지 않고 그 글씨만 노려보았다."},{"s":"q:r71_seoharam","t":"할머니 말씀 그대로네요. 관측관은 기록을 믿어야죠. …믿기 싫어도요."},{"s":"q:sn_cheongpa","t":"그 도장… 관아 현판에 있던 거랑 같은 거 아니에요?"},{"s":"q:r71_seoharam","t":"맞아요. 도제조님 인장이에요. 할머니 혼자 한 일이 아니었어요. 도제조님이 알고 허락하신 거예요."},{"s":"southern_remnant:galmae","t":"정청 꼭대기 영감이 너를 살렸다고? 우리 임금은 거두고?"},{"s":null,"t":"아무도 대답하지 못했다. 기록판 옆 벽에 관상대 출입 장부가 걸려 있었는데, 바람도 없이 장부가 팔락 넘어갔다."},{"s":null,"t":"맨 마지막 줄의 먹이 아직 번들거렸다. 「정리관」이라는 직함 아래 「이 별은 거둘 수 없소」라는 짧은 글이 적혀 있었다. 그 장 모서리가 접혀 있었다."},{"s":"north_league:yeo","t":"먹이 안 말랐소. 오늘 적은 거요."},{"s":null,"t":"그 순간 관상대 안쪽 계단에서 또각또각 발소리가 났다. 갈매가 칼을 뽑았다. 계단에서 내려온 사람은 경현이었다. 경현의 옷자락 끝이 젖어 있었다."},{"s":"q:md_gyeonghyeon","t":"아, 오늘이었구려. 태사령께서 열쇠를 내주셨나 보오. 열 해 동안 다문 입도 한 번 더 여셨겠군."},{"s":"southern_remnant:galmae","t":"이 자식이 왜 여기…!"},{"s":null,"t":"여운비가 갈매의 칼끝을 손등으로 눌러 내렸다. 경현은 그 칼끝을 한 번 보고 서하람 쪽으로 걸어왔다. 서하람은 물러서지 않았다."},{"s":"q:r71_seoharam","t":"정리관님. 「이 별은 거둘 수 없소」, 이거 쓰신 거죠."},{"s":"q:md_gyeonghyeon","t":"내 글씨요."},{"s":"q:r71_seoharam","t":"왜 제 별은 안 거두셨어요? 정리 명부에 있던 이름이잖아요. 거둘 수 없다고 쓰셨지만… 정리관님은 거둘 수 있었잖아요. 별 기록판째로 태우면 되니까요."},{"s":null,"t":"경현은 대답하지 않고 장부를 펴 모서리를 접으려다 손을 멈췄다. 잠깐 그 얼굴에서 웃음이 지워졌다."},{"s":"q:md_gyeonghyeon","t":"…스무 해 전 그 밤, 나는 천명원 문밖에 서 있었소. 그 별을 숨긴 사람의 손이 떨렸던 걸 봤소. 붓이 세 번이나 미끄러졌지."},{"s":"q:md_gyeonghyeon","t":"거둘 수 없는 이름도 있소. 내 장부에 몇 줄 안 되지만, 그 줄에는 끝내 붉은 줄을 긋지 않을 거요."},{"s":"q:r71_seoharam","t":"그럼 오늘은요?"},{"s":"q:md_gyeonghyeon","t":"오늘 내가 거두러 온 것은 별이 아니라 장이오. 그런데 당신들이 먼저 기록판을 열었구려."},{"s":null,"t":"경현은 열린 기록판을 보고 뒤로 한 걸음 물러서더니 우리 쪽으로 손을 펴 보였다. 빈손이었다."},{"s":"q:md_gyeonghyeon","t":"그럼 마저 모아 오시오. 일곱 장이 다 모이면 그때 한꺼번에 받겠소. 관측관, 할머님께 안부를 전해 주시오. 스무 해 전 그 밤처럼 아직도 손이 떨리시는지."},{"s":null,"t":"경현이 계단을 내려갔다. 관상대 아래 우물 쪽에서 첨벙, 물 소리가 한 번 났다. 그 뒤로 아무 소리도 나지 않았다. 서하람의 손이 덜덜 떨리고 있었다. 나는 그 손을 잡았다."},{"s":"north_league:yeo","t":"정리관이 우물로 다닌다면, 둘레에 다른 것도 두고 갔을지 모르오. 살펴야겠소."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":6,"title":"잘못 읽은 별","goal":"첫 관상대를 탐색해 기록판 뒷장의 실마리를 2번 찾고, 원정을 한 번 끝까지 다녀와 관상대 둘레 우물을 살핀다","need":{"at":["first_observatory"],"tasks":[{"t":"clue","r":["first_observatory"],"n":2},{"t":"expedition","r":["first_observatory"],"n":1}]},"lines":[{"s":null,"t":"관상대 둘레 우물가마다 젖은 먹 발자국이 있었지만, 사람은 아무도 없었다. 기록판 맨 끝에서 백 년 전의 별 기록이 한 장 더 나왔다."},{"s":null,"t":"「칸을 두면 아홉 해마다 고을 하나가 먹힌다」라는 글 위에 누군가 붉은 먹으로 줄을 그어 놓았다. 그 옆에 「잘못 읽었다. 부름 장사만 막았으면 먹히는 고을은 없었다」라고 적혀 있었다."},{"s":null,"t":"서하람이 그 글을 소리 내어 읽었다. 읽는 목소리가 점점 작아졌다. 갈매가 서하람을 돌아보았다."},{"s":"southern_remnant:galmae","t":"다시 읽어 봐."},{"s":"q:r71_seoharam","t":"…잘못 읽었다. 부름 장사만 막았으면…"},{"s":"southern_remnant:galmae","t":"그러니까 이 별 하나 때문에 다섯이 서명했다는 거지. 그 서명 때문에 우리 임금 이름이 거둬졌고. 남명 사람들이 백 년 동안 맨 먼저 거둬진 게, 천명원이 별을 잘못 읽어서였다는 거잖아!"},{"s":null,"t":"갈매의 목소리가 관상대 돌벽에 쩌렁쩌렁 울렸다. 청파가 움찔했다. 여운비가 단비의 들것 쪽으로 몸을 기울였다."},{"s":"q:r71_seoharam","t":"…네."},{"s":"southern_remnant:galmae","t":"네? 그게 다야? 변명이라도 해 봐! 그때 나는 없었다, 할머니도 없었다, 뭐라도!"},{"s":"q:r71_seoharam","t":"변명 안 할게요. 천명원은 그 뒤로 예언을 안 해요. 저도 그래서 관측만 한다고 말하는 거고요. 그 말이 아무것도 되돌리지는 못하지만요."},{"s":null,"t":"갈매가 무언가 말하려다 이를 악물고는, 홱 돌아서서 계단을 내려가 버렸다. 쿵쿵쿵, 계단을 밟는 소리가 멀어졌다."},{"s":"q:sn_cheongpa","t":"누님! 갈매 누님!"},{"s":"north_league:yeo","t":"두시오. 지금 따라가면 당신이 맞소."},{"s":null,"t":"그 밤 갈매는 모닥불에서 가장 먼 바위에 앉았다. 서하람이 엿 하나를 들고 다가갔다. 단비가 나눠 준 엿이었다. 갈매는 고개를 돌렸다."},{"s":null,"t":"서하람은 엿을 쥔 손을 한참 내밀고 있다가 조용히 거두었다. 돌아오는 서하람의 걸음이 비틀거렸다. 나는 일어나 그 팔을 잡아 주었다."},{"s":"q:r71_seoharam","t":"괜찮아요. 맞는 말이니까요. …갈매 씨 등, 따뜻했는데."},{"s":null,"t":"나는 갈매에게 가서 말없이 곁에 앉았다. 한참 뒤에 갈매가 먼저 입을 열었다."},{"s":"southern_remnant:galmae","t":"…알아. 걔 잘못 아닌 거. 백 년 전 일이잖아. 근데 화가 안 꺼져. 할배가 그랬어. 남명 사람 화는 화로처럼 안 꺼진다고."},{"s":null,"t":"나는 남명에서는 꺼지지 않는 불이 사람을 지키는 불 아니냐고 했다. 갈매는 나를 한 번 쳐다보기만 하고 대답은 하지 않았다."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":7,"title":"반만 들리는 목소리","goal":"첫 관상대에서 단비 곁을 지키며 야영으로 쉰다","need":{"at":["first_observatory"],"tasks":[{"t":"rest","r":["first_observatory"],"n":1}]},"lines":[{"s":null,"t":"그 밤 단비가 눈을 떴다. 여운비가 단비의 이름을 처음 부른 지 이레째 되는 밤이었다."},{"s":null,"t":"단비는 흰 하늘을 한참 올려다보다가 고개를 돌렸다. 오른쪽에 앉은 여운비를 보자 단비가 웃으려 했다. 이번에는 양쪽 입꼬리가 다 올라갔다."},{"s":null,"t":"왼손은 이불 밖으로 나오지 않았다. 손끝이 먹빛으로 굳어 있었다."},{"s":"north_league:yeo","t":"…나쁘지 않소. 일어나시오."},{"s":null,"t":"여운비의 목소리가 떨렸다. 여운비는 단비의 손을 놓지 않았다. 놓지 않은 지 열흘도 더 된 손이었다."},{"s":null,"t":"단비가 고개를 갸웃하더니 오른쪽 귀를 여운비 쪽으로 기울였다. 그러고는 웃음을 터뜨렸다."},{"s":"red_moon_cult:danbi","t":"대장님 목소리가 반만 들려요. 왼쪽 귀가 안 들리나 봐요. 그래도 좋네요. 반만 들리니까 덜 무서워요."},{"s":null,"t":"청파가 벌떡 일어나다 물동이를 걷어찼다. 쏴아, 물이 쏟아졌다. 청파는 그것도 모르고 무릎걸음으로 단비 곁에 달려왔다."},{"s":"q:sn_cheongpa","t":"단비 누님! 누님! 이거, 엿이요! 안 먹고 아껴 둔 거예요! 돌려준다고 했잖아요!"},{"s":"red_moon_cult:danbi","t":"…어머, 청파. 목소리가 왜 그래요. 쇳소리 나요."},{"s":"q:sn_cheongpa","t":"물에 빠졌었어요! 숨도 끊겼었대요! 근데 대장님이 「가지 마시오」 했어요! 제가 꼭 얘기한다고 했거든요!"},{"s":"north_league:yeo","t":"…하지 말라고 했소."},{"s":"red_moon_cult:danbi","t":"대장님이요? 「가지 마시오」? 진짜요? 아, 왼쪽 귀로도 듣고 싶다…."},{"s":null,"t":"바위 쪽에서 쿵쿵 발소리가 났다. 갈매가 달려오고 있었다. 갈매는 들것 곁에 와서 우뚝 멈춰 섰다. 무어라 말하려다 입술만 깨물었다."},{"s":"red_moon_cult:danbi","t":"밤송이 얼굴이 왜 그래요. 화났어요? 또 누가 막내라고 했어요?"},{"s":"southern_remnant:galmae","t":"…아무도 안 그랬어. 잘 잤냐, 무녀."},{"s":null,"t":"갈매의 목소리는 갈라져 있었다. 서하람은 들것 발치에 선 채 두 손으로 입을 막고 있었다. 그 눈에서 눈물이 뚝뚝 떨어졌다."},{"s":"red_moon_cult:danbi","t":"외상 별님은 왜 안 졸려요? 이상하다. 제가 오래 잤나 봐요."},{"s":null,"t":"서하람은 대답 대신 단비의 품에서 방울을 꺼냈다. 백골 장터 바닥에서 주워 천으로 닦아 넣어 둔 단비의 방울이었다. 서하람이 그것을 두 손으로 단비의 오른손에 쥐여 주었다."},{"s":"q:r71_seoharam","t":"깨면 바로 흔들라고 넣어 뒀어요. 엿값은… 아직이에요. 별 뜨면 갚을게요."},{"s":null,"t":"단비가 방울을 흔들었다. 딸랑, 맑은 소리가 났다. 단비의 얼굴에서 웃음이 아주 잠깐 멈췄다."},{"s":null,"t":"방울 소리는 들렸지만, 그 소리 뒤에 늘 따라 들리던 축문은 들리지 않았다."},{"s":"red_moon_cult:danbi","t":"…축문이 안 들려요. 이제 저는 무녀가 아니네요."},{"s":null,"t":"아무도 말하지 못했다. 단비는 방울을 한 번 더 흔들었다. 그러고는 다시 웃었다."},{"s":"red_moon_cult:danbi","t":"그럼 이제 뭐 하지. 아, 엿 장수 할까요? 대장님, 동업해요."},{"s":"north_league:yeo","t":"…안 하오."},{"s":null,"t":"모두가 웃었다. 갈매도 웃었다. 웃다가 서하람과 눈이 마주치자 고개를 돌렸다. 나는 단비에게 무엇이 먹고 싶으냐고 물었다."},{"s":"red_moon_cult:danbi","t":"따뜻한 거요. 아주 따뜻한 거요. 왼쪽이 계속 추워요."},{"s":null,"t":"따뜻한 국물이라면 관상대 우물 물고기로 끓이는 매운탕이 나을 것 같아, 나는 단비 몫에는 고춧가루를 거의 넣지 않고 야령초를 듬뿍 넣기로 했다."}],"reward":{"xp":2528}},{"quest_id":"mdq_12","step":8,"title":"우리","goal":"물고기를 1번 낚고 매운탕 2그릇을 끓여 첫 관상대에서 단비에게 넘긴다","need":{"at":["first_observatory"],"tasks":[{"t":"fish","n":1},{"t":"craft","items":["spicy_stew"],"n":2}],"give":{"spicy_stew":2}},"lines":[{"s":null,"t":"이튿날 아침, 단비는 내가 끓인 매운탕을 두 그릇이나 비웠다. 오른손으로 숟가락을 쥐는 일이 서툴러 국물을 흘렸다. 여운비가 말없이 수건으로 단비의 턱을 닦았다."},{"s":"red_moon_cult:danbi","t":"대장님, 저 아기 아니에요."},{"s":"north_league:yeo","t":"아기는 국을 덜 흘리오."},{"s":null,"t":"서하람이 여섯째 장을 기록판에서 꺼내 들고 모두 앞에 섰다. 졸린 기색은 하나도 없었다."},{"s":"q:r71_seoharam","t":"이 장을 내놓을게요. 이걸 풀면 제 별도 타고, 제 눈도 같이 갈 거래요. 그래도 내놓을게요."},{"s":"q:r71_seoharam","t":"천명원이 잘못 읽은 별 때문에 칸이 긁혔으니까, 이번엔 천명원 사람이 제 별로 그 칸을 다시 채우는 데 쓰여야죠. 이건 예언이 아니에요. 제가 정한 거예요."},{"s":null,"t":"갈매가 먼저 입을 열었다. 어젯밤부터 처음 하는 말이었다."},{"s":"southern_remnant:galmae","t":"…바보 같은 소리 하지 마. 할머니 말 들었잖아. 기록판에도 적혀 있었고. 별이 타면 네 눈도 간다고!"},{"s":"q:r71_seoharam","t":"들었어요. 눈은 아마 못 쓰게 되겠죠. 그다음은 몰라요. 관측해 본 적이 없어서요."},{"s":"southern_remnant:galmae","t":"그러니까 바보라는 거야!"},{"s":null,"t":"서하람이 대답하기 전에 단비가 오른손으로 서하람의 소매를 붙잡았다."},{"s":"red_moon_cult:danbi","t":"그럼 그때는 우리가 부르면 되잖아요. 저도 그렇게 살아났는데요. 대장님은 제 이름 한 번 부르는 데 한참 걸리셨지만요."},{"s":null,"t":"여운비가 귀 끝까지 빨개진 채 고개를 돌렸다."},{"s":"north_league:yeo","t":"…그건 세지 마시오."},{"s":"red_moon_cult:danbi","t":"세고 있었어요?"},{"s":null,"t":"청파가 쉰 목소리로 「저도요! 저도 부를 거예요!」 하며 손을 번쩍 들었다. 여운비가 짧게 고개를 끄덕였다. 갈매는 한참 서하람을 노려보다가 혀를 찼다."},{"s":"southern_remnant:galmae","t":"…내가 제일 크게 불러 줄 거야. 듣기 싫어도 들어. 그리고 어제 그 엿, 이리 내."},{"s":null,"t":"서하람이 품에서 엿을 꺼냈다. 갈매가 그것을 낚아채 반으로 뚝 잘라, 반쪽을 서하람의 입에 쑥 넣었다."},{"s":"southern_remnant:galmae","t":"반은 네 거. 반은 내 거. 됐지."},{"s":null,"t":"서하람이 엿을 문 채 웃었다. 볼이 불룩해서 말을 못 했다. 단비가 「어머, 내 엿인데」 하며 웃었다."},{"s":null,"t":"나는 여섯째 장의 「이을 이」 칸에 이름을 적었다. 흰 불꽃이 금빛으로 바뀌며 품속 세 장과 금빛 실로 이어졌다. 그 금빛 아래 다섯 사람이 처음으로 한자리에 바짝 붙어 서 있었다."},{"s":"q:sn_cheongpa","t":"넷이에요. 이제 셋 남았어요."},{"s":"red_moon_cult:danbi","t":"셋이요? 제가 자는 동안 그렇게 많이 했어요? 남은 건 뭐예요?"},{"s":"north_league:yeo","t":"정청의 첫째 장 반쪽, 남명 장, 흑련의 장부요. 일곱을 다 이어야 저 조사원이 맹약 마당에서 진을 풀 수 있소. 정리관은 다 모이면 한꺼번에 태우려 하고."},{"s":"red_moon_cult:danbi","t":"그럼 우리가 먼저 다 모아야죠. 대장님네는 종, 우리는 기름, 청파네는 배, 하람 씨네는 별. 다들 하나씩 갚을 걸 들고 다니네요. 갈매 씨네만 억울하네요."},{"s":"southern_remnant:galmae","t":"알면 잘해."},{"s":null,"t":"서하람이 두루마리를 펼쳤다. 관아 터에서 현판 글씨와 귀퉁이 인장을 베껴 둔 장이 나왔다. 여운비가 품에서 여사온의 편지를 꺼내 그 옆에 놓았다. 청파가 넷째 장을, 서하람이 별 옆 인장 그림을 나란히 놓자 모두 말이 없어졌다."},{"s":"q:r71_seoharam","t":"현판은 삼백 년 전이고, 「백 공」은 칠십 년 전이고, 인장은 스무 해 전이에요. 같은 사람이면… 삼백 년을 산 거예요. 진의 심지로 묶인 사람이요."},{"s":"red_moon_cult:danbi","t":"정청 꼭대기 그 할아버지요? 도제조님?"},{"s":"southern_remnant:galmae","t":"가서 물어보면 되잖아. 그 영감한테. 우리 임금 이름은 왜 거뒀냐고."},{"s":null,"t":"아무도 반대하지 않았다. 첫째 장 반쪽을 이으려면 어차피 정청으로 가야 했다. 나는 들것을 접었다. 단비가 처음으로 제 발로 일어섰다. 여운비가 그 오른팔을 잡았고, 청파가 왼쪽을 받쳤다."}],"reward":{"xp":2528,"gil":510,"items":{"faded_star_glass":2,"star_record_plate":1}}},{"quest_id":"mdq_13","step":1,"title":"문이 열린 방","goal":"본부 정청에 도착해 안쪽 방의 열린 문 앞에 선다","need":{"at":["hq_yard"],"tasks":[{"t":"travel","r":["hq_yard"],"n":1}]},"lines":[{"s":null,"t":"정청 대문을 들어서자 서리 문수가 마당 끝에서 종종걸음으로 달려왔다. 장부를 가슴에 안고 숨을 몰아쉬었다."},{"s":"q:dh_munsu","t":"조사원 님! 오셨어요? 다들 오셨어요? 아이고, 무녀님이 걸으시네요! 소식 듣고 얼마나 걱정했는지 몰라요. 진짜거든요.","fac_not":"night_office","spec":2,"grp":1},{"s":"q:dh_munsu","t":"{등급}님! 우리 정청 사람이 이렇게 큰일을 하고 다니시는 거, 서리방에서 다들 자랑하거든요. 무녀님도 걸으시네요! 다행이다.","fac":"night_office","spec":1,"grp":1},{"s":"southern_remnant:galmae","t":"시끄러워. 도제조 영감 어디 있어."},{"s":"q:dh_munsu","t":"아, 그게요… 안쪽 방에 계세요. 그 방은 원래 도제조님 등잔만 두는 방이에요. 예전엔 대청에 나와 일을 보시고 판관 회의에도 들어가셨거든요. 근데 묵창 나루 일 있고 나서부터 그 등잔 곁을 못 떠나셨어요. 불 난 밤에도 못 나오셨잖아요."},{"s":"q:dh_munsu","t":"그래도 문은 늘 닫아 두셨는데, 조사원 님 떠나시고 얼마 안 돼서 열렸어요. 그 뒤로는 문을 안 닫으세요. 거기서 꼼짝도 안 하시고요."},{"s":"q:dh_munsu","t":"그리고요, 입으로는 하루에 한 번, 몇 마디뿐이세요. 등잔 심지가 밝아질 때만요. 나머지는 붓으로 쓰세요. 쓰시는 동안에도 심지가 닳으니까, 물으실 거 잘 골라 오세요. 심지가 낮아지면 숨을 쉬시는지도 모르게 가만히 계세요."},{"s":null,"t":"대청 안쪽 방의 문은 정말로 열려 있었다. 장서각에 불이 났던 밤에는 문틈으로 불빛만 새어 나오던 방이었다. 방 한가운데 등잔 하나가 고요하게 타고 있었고, 그 아래 도제조 백운서가 앉아 있었다."},{"s":null,"t":"등잔불이 그 얼굴을 환하게 비추었다. 등잔도, 탁자도, 문틀도 저마다 바닥에 그림자를 드리웠다. 백운서의 몸 아래 마룻바닥에만 그림자가 없었다."},{"s":null,"t":"청파가 제 발밑 그림자를 내려다보고, 다시 백운서의 발밑을 보았다. 단비는 오른손으로 여운비의 소매를 꽉 쥐었다. 서하람이 등잔 쪽으로 반걸음 다가가 심지를 들여다보았다."},{"s":"q:r71_seoharam","t":"심지가… 짧아요. 손톱만큼 남았어요. 기름은 그대로인데요."},{"s":null,"t":"백운서의 왼손 약지에 번진 먹 자국이 등잔불에 비쳐 검게 빛났다. 백운서가 아주 천천히 고개를 들었다. 나는 그 얼굴을 기억했다. 구중 봉연에서 돌아온 날, 「올해 먹 거두기는 하지 않는다」고 말하던 얼굴이었다."},{"s":"night_office:baek","t":"장을 넷이나 모아 왔구먼. 앉게.","fac_not":"night_office","spec":2,"grp":2},{"s":"night_office:baek","t":"우리 정청 사람이 장을 넷이나 모아 왔구먼. 앉게.","fac":"night_office","rank":[1,4],"spec":0,"grp":2},{"s":"night_office:baek","t":"판관, 장을 넷이나 모아 왔구먼. 그게 자네라서 다행이네. 앉게.","fac":"night_office","rank":[5,5],"spec":0,"grp":2},{"s":null,"t":"우리는 서로를 보다가 방바닥에 둘러앉았다. 방이 좁아 무릎이 서로 닿았다. 백운서는 입을 열었다가 닫았다. 등잔 심지가 사르르 낮아지더니, 눈꺼풀이 내려앉은 뒤로는 손가락 하나 움직이지 않았다."},{"s":"southern_remnant:galmae","t":"야. 영감. 앉으라고만 하고 끝이야? 야!"},{"s":"q:dh_munsu","t":"쉿, 쉿! 오늘 몫은 끝났어요. 내일 이맘때요. 진짜예요. 그동안 객사에서 진지라도 드세요. 상 차려 놓으라고 할게요."},{"s":null,"t":"객사 부엌 아주머니가 상을 차려 내왔다. 흰 쌀밥에 된장국, 고등어구이, 나물 세 가지였다. 우리는 상 앞에서 한참 움직이지 않았다. 백골 장터를 떠난 뒤로 상다리가 있는 밥상은 처음이었다."},{"s":"q:sn_cheongpa","t":"…이거 다 먹어도 돼요? 진짜로요?"},{"s":null,"t":"청파는 밥 세 그릇을 비우고 네 번째 그릇을 내밀다가 사레가 들렸다. 갈매가 콜록거리는 청파의 등을 퍽퍽 쳤다."},{"s":"southern_remnant:galmae","t":"천천히 먹어, 꼬맹이. 누가 뺏어 먹냐."},{"s":null,"t":"단비는 오른손으로 젓가락질을 하다가 고등어 살을 자꾸 떨어뜨렸다. 여운비가 말없이 단비의 접시를 끌어와 고등어 가시를 하나하나 발라 다시 밀어 주었다."},{"s":"red_moon_cult:danbi","t":"대장님, 이것도 호송대장 일이에요?"},{"s":"north_league:yeo","t":"…가시는 길을 막는 짐이오."},{"s":"red_moon_cult:danbi","t":"어머. 바람개비가 오늘 말 잘하네."},{"s":null,"t":"서하람은 밥을 먹다 말고 꾸벅 졸았다. 별 때문이 아니라 정말로 지쳐서 조는 것이었다. 갈매가 서하람의 밥그릇이 기울지 않게 슬쩍 받치고, 그 위에 제 고등어 반쪽을 얹어 두었다."},{"s":null,"t":"문간으로 기록관 모가람이 들어왔다. 두 손에 하얀 붕대가 두툼하게 감겨 있었다. 모가람은 식은 보리차 주전자를 팔꿈치에 끼고 있었다."},{"s":"night_office:mo","t":"다들 무사하시네요. 아니, 무사한 건 아니구나. 그래도 다 같이 오셨네요. 보리차 드실래요? 식었어요. 늘 식어 있죠, 제 보리차는."},{"s":null,"t":"모가람이 주전자를 기울이다 붕대 감은 손이 미끄러졌다. 나는 일어나 주전자를 받아 들었다. 첫 잔을 따라 모가람의 입에 대 주었다."},{"s":"night_office:mo","t":"…또 이렇게 받네요. 떠나실 때 제가 한 잔 따라 달라고 했죠. 진짜로 따라 주시네."},{"s":null,"t":"모가람은 웃었지만, 붕대 위로 손끝이 아주 조금 떨렸다. 모가람이 안쪽 방 쪽을 돌아보았다."},{"s":"night_office:mo","t":"도제조님 뵙고 오셨죠? 내일 들어가실 때 차를 한 잔 올려 보세요. 옛 장부에 그분이 송화 넣은 차를 좋아하셨다고 적혀 있었어요. 기운이 조금이라도 나시면 한마디라도 더 하실지 몰라요."},{"s":"red_moon_cult:danbi","t":"송화요? 정청 뒷산에 소나무 많던데요. 내일 아침에 따러 가요. 저 오른손으로도 딸 수 있어요."},{"s":null,"t":"송화만 우리면 맛이 엷다고 모가람이 일러 주어, 나는 등도에서 가져온 끊긴 등 기름에 송화와 찻잎을 덖어 밤빛 차로 우리기로 했다."},{"s":"southern_remnant:galmae","t":"넘어지면 내가 안 잡아 준다."},{"s":"red_moon_cult:danbi","t":"잡아 줄 거면서."},{"s":null,"t":"웃음소리가 객사 처마 밑까지 퍼졌다. 그 웃음이 가라앉자 청파가 숟가락을 내려놓았다."},{"s":"q:sn_cheongpa","t":"근데요. 처음 만났을 때는 이 사람들 한 상에 앉히면 상다리가 부러질 줄 알았거든요."},{"s":null,"t":"청파가 숟가락 끝으로 상 위를 가리켰다. 단비의 접시에는 가시를 바른 고등어가 놓여 있었고, 졸고 있는 서하람의 밥그릇에는 갈매의 고등어 반쪽이 얹혀 있었다."},{"s":"southern_remnant:galmae","t":"…뭘 봐. 남길 것 같아서 준 거야. 정청 밥은 짜."},{"s":null,"t":"졸던 서하람이 그 말에 눈을 떴다. 제 밥그릇 위의 고등어를 내려다보다가, 아무 말 없이 한 점 떼어 입에 넣었다."},{"s":"north_league:yeo","t":"장은 넷이고 셋 남았소. 저 방 어르신이 하루 한 번만 말을 한다면 물음을 골라 두시오. 가장 먼저 물을 것부터."},{"s":"southern_remnant:galmae","t":"내가 먼저야. 잠꾸러기가 베껴 둔 현판. 정청이 우리한테 무슨 짓을 했는지부터 들을 거야."}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":2,"title":"현판","goal":"잿빛 들녘에서 4번 채집하고 밤빛 차 1잔을 우려 본부 정청의 도제조에게 넘긴다","need":{"at":["hq_yard"],"tasks":[{"t":"gather","n":4,"r":["field_outskirts"]},{"t":"craft","items":["night_tea"],"n":1}],"give":{"night_tea":1}},"lines":[{"s":null,"t":"이튿날 심지가 밝아진 것은 해가 기울 무렵이었다. 문수가 객사로 달려와 우리를 불렀다. 우리는 송화를 넣은 밤빛 차를 들고 안쪽 방에 들어갔다."},{"s":null,"t":"문수가 먼저 들어가 백운서 무릎 앞에 벼루와 붓, 종이 한 묶음을 가지런히 놓았다. 날마다 그렇게 차려 두는 손놀림이었다."},{"s":null,"t":"백운서는 어제와 똑같은 자리에 똑같은 모습으로 앉아 있었다. 내가 밤빛 차를 올리자 백운서의 코끝이 아주 조금 움직였다."},{"s":"night_office:baek","t":"송화차로구먼."},{"s":null,"t":"백운서는 그 한마디만 하고 입을 닫았다. 먹 자국이 번진 왼손으로 오른 손목을 받치고 붓을 들었다. 붓끝이 종이에 닿기까지 한참이 걸렸다. 「누가 알려 주던가」라는 다섯 글자가 비뚤게 적혔다."},{"s":null,"t":"나는 모가람이 옛 장부에서 읽었다고 했다. 백운서의 입가에 주름 하나가 깊어졌다. 웃음인지 아닌지 알 수 없었다."},{"s":null,"t":"갈매가 서하람이 베껴 둔 현판 그림을 백운서 앞 바닥에 탁 펼쳤다. 「도제조 백운서」라는 글자 옆 날짜는 삼백 년 전이었다."},{"s":"southern_remnant:galmae","t":"이거 당신이야? 아니면 할배의 할배의 할배쯤 되는 동명이인이야?"},{"s":"night_office:baek","t":"모두 나일세. 현판에 이름을 쓴 이도, 지금 자네들 앞에 앉은 이도 같은 사람일세."},{"s":null,"t":"청파가 숨을 헉 들이켰다. 백운서는 다시 붓을 들었다. 한 줄을 쓰고 숨을 고르고, 또 한 줄을 썼다. 다 쓴 종이를 서하람 쪽으로 밀었다. 서하람이 종이를 받아 소리 내어 읽었다."},{"s":"q:r71_seoharam","t":"「관아 현판도, 증인 명부도, 별 옆 인장도 나일세. 삼백 년 전 요기의 밤에 일곱 무리가 등도에 모여 서로를 불렀네. 그 부름으로 버티고 나서 맹약을 맺었지. 일곱 장으로 진을 짜고, 그 가운데 심지로 내 이름을 묶었네.」"},{"s":"q:r71_seoharam","t":"「진이 타는 동안 나는 죽지 않네. 저 등잔이 그 심지일세.」 …「심지 — 진의 가운데에 사람 하나가 묶였다」… 그게 도제조님이었어요."},{"s":"southern_remnant:galmae","t":"삼백 년을 살았다고? 그럼 백 년 전 칸 긁은 것도 당신이잖아. 우리 임금 이름 거둔 것도! 남명 사람들 백 년 동안 맨 앞에 세운 것도!"},{"s":null,"t":"갈매가 무릎걸음으로 다가앉으며 주먹으로 마룻바닥을 쾅 내리쳤다. 등잔불이 흔들렸다. 문수가 「아이고」 하며 문틀을 붙잡았다."},{"s":"southern_remnant:galmae","t":"대답해! 종이 말고 입으로! 하루에 한 번이라며! 그 한 번 나한테 써!"},{"s":"night_office:baek","t":"그래. 칸을 긁는 서식에 서명한 사람은 나일세."},{"s":null,"t":"그 말을 하고 백운서는 오래 숨을 몰아쉬었다. 붓이 다시 움직였다. 이번에는 갈매가 종이를 낚아채듯 받아 들었다. 읽어 내려가는 갈매의 목소리가 점점 낮아졌다."},{"s":"southern_remnant:galmae","t":"「솔내가 먹히던 무렵, 명부 칸은 쌀 두 섬에 산 거짓 도장으로 가득 찼네. 진에 내줄 이름이 모자라 문이 흔들렸지. 모두를 지킬 수 없다면 적게 잃는 쪽을 고르자고, 나는 그렇게 마음먹었네.」"},{"s":"southern_remnant:galmae","t":"「남명 임금은 그 셈에 맞서신 분이었네. 내 백성은 내가 부른다고 하셨지. 나는 그분의 이름을 거뒀네.」"},{"s":null,"t":"종이를 쥔 갈매의 주먹이 바들바들 떨렸다. 여운비가 갈매의 등에 손을 얹었다. 갈매는 그 손을 털어 내지 않았다."},{"s":"southern_remnant:galmae","t":"…사과도 안 해?"},{"s":null,"t":"백운서의 붓이 한참 종이 위에서 머뭇거렸다. 갈매가 두 번째 종이를 받아 읽었다."},{"s":"southern_remnant:galmae","t":"「사과는 그 이름을 불러 줄 사람이 남아 있어야 받을 수 있네. 그분 이름을 아직 부르는 이가 있나.」 …있어. 우리 할배. 화로 앞에서 날마다 불러."},{"s":null,"t":"백운서는 고개를 아주 조금 끄덕이고 다음 종이에 썼다. 「그럼 그분께 하겠네. 내 등잔이 꺼지기 전에.」 갈매는 그 종이를 읽고 아무 말도 하지 않았다."},{"s":null,"t":"심지가 낮아지기 시작했다. 백운서의 붓놀림이 급해졌다. 글씨가 줄을 벗어나 종이 끝으로 흘러내렸다. 종이를 받아 든 서하람이 띄엄띄엄 읽었다."},{"s":"q:r71_seoharam","t":"「내 등잔이 꺼지기 전에 셋을 찾아다 주게. 정리소 문을 여는 열쇠패, 감찰관이 쫓는 고친 보고서, 그리고 첫째 장의 타 버린 앞부분일세.」 「열쇠패는 봉인 서가 맨 아래 칸에 있네. 앞부분은 모가람이 외우고 있을 걸세.」"},{"s":null,"t":"등잔 심지가 사르르 낮아졌다. 붓을 쥔 백운서의 손이 그대로 굳었다. 문수가 조용히 붓을 빼내고 그 손을 무릎 위로 내려 주었다. 바닥에 쌓인 종이는 넉 장이었다."},{"s":"red_moon_cult:danbi","t":"봉인 서가요? 그거 불탄 데잖아요."},{"s":"q:r71_seoharam","t":"잿더미 밑이요. 맨 아래 칸은… 불이 덜 닿았을지도 몰라요."},{"s":"southern_remnant:galmae","t":"가. 지금 가. 저 영감 등잔 꺼지면 아무것도 못 물어."}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":3,"title":"받아쓰기","goal":"장서각 지하서고에 도착해 4번 탐색하며 봉인 서가 잿더미를 헤치고, 우물에서 기어 나온 먹 도랑 검은 손을 3번 쓰러뜨려 본부 객사로 간다","need":{"at":["hq_dorm"],"tasks":[{"t":"travel","r":["hq_archive"],"n":1},{"t":"search","r":["hq_archive"],"n":4},{"t":"win","n":3,"m":["dd_vault_1"],"r":["hq_archive"]}]},"lines":[{"s":null,"t":"불탄 장서각에는 아직 매캐한 냄새가 배어 있었다. 무너진 서가가 숯덩이로 엉켜 있었고, 발을 디딜 때마다 바삭바삭 재가 부서졌다."},{"s":null,"t":"서고 끝 배수 우물에서는 먹물을 뒤집어쓴 검은 손들이 손목까지 내민 채 기어 나와 있었다. 불이 난 밤에 본 젖은 먹 발자국도 그 우물로 이어져 있었다."},{"s":null,"t":"맨 아래 칸을 찾은 것은 청파였다. 숨이 차 자주 쉬면서도 청파는 재를 손으로 헤집었다. 물속에서 문패를 더듬던 손놀림이었다."},{"s":"q:sn_cheongpa","t":"여기요! 뭐가 걸려요. 쇠예요!"},{"s":null,"t":"재 속에서 손바닥만 한 쇠패가 나왔다. 검게 그을렸지만 모양은 멀쩡했다. 앞면에 「정리」 두 글자가, 뒷면에 열쇠 이빨 같은 홈이 새겨져 있었다."},{"s":null,"t":"쇠패를 꺼내는 순간 장서각 안쪽 우물에서 철벅 소리가 났다. 먹 낀 것들이 우물 테를 넘어 기어 나왔다. 단비가 나를 홱 돌아보았다."},{"s":"red_moon_cult:danbi","t":"{이름} 님, 뒤!"},{"s":null,"t":"나는 몸을 틀어 {직업:호위=방패로 그것을 밀쳐 냈다/월궁=시위를 당겨 그것의 머리를 꿰뚫었다/퇴마=부적을 날려 그것을 태웠다/*=그것을 쳐 냈다}. 여운비의 칼이 다른 하나를 갈랐다."},{"s":null,"t":"단비는 오른손으로 방울을 흔들었다. 딸랑, 축문은 안 들려도 그것들은 방울 소리에 움찔 물러났다."},{"s":"red_moon_cult:danbi","t":"어? 아직 무서워하네요. 무녀 아니어도요. 잘됐다."},{"s":null,"t":"열쇠패를 품에 넣고 객사로 돌아오자 모가람이 기다리고 있었다. 모가람은 붕대 감은 두 손을 무릎 위에 얹고 앉아 있었다."},{"s":"night_office:mo","t":"도제조님이 제가 외우고 있을 거라고 하셨다고요? …네. 외워요. 서른 해 동안 해마다 그 서가에 정리 명부 사본을 정서해 꽂았으니까요. 첫째 장 앞부분도 몇 번이나 옮겨 적었어요."},{"s":"night_office:mo","t":"근데 이제 손이 이래서 못 써요. …{이름} 님이 받아써 주실래요? 제가 불러 드릴게요."},{"s":null,"t":"나는 붓을 들었다. 모가람이 한 글자씩 불렀다. 나는 그 소리를 따라 썼다. 모가람의 목소리는 한 번도 끊기지 않았다."},{"s":"night_office:mo","t":"부를… 이… 없는… 이름만… 거둔다."},{"s":"night_office:mo","t":"불 난 이튿날에도 조사원님이 제 말을 받아 적어 주셨죠. 그날은 불 이야기였는데, 오늘은 첫째 장이네요."},{"s":null,"t":"모가람의 눈에 물기가 차올랐지만, 모가람은 웃으며 고개를 돌렸다. 곤란할 때마다 말을 돌리던 그 웃음이었다."},{"s":"night_office:mo","t":"이건 연습 종이예요. 제대로 된 사본은 정청 종이에 정청 먹으로 써야 해요. 그래야 정리소 서식이랑 견줄 수 있어요. 뒤뜰 닥나무 껍질이랑 그을음을 좀 모아 오셔야겠어요."},{"s":null,"t":"모가람이 말한 정청 종이는 황지를 칠액과 수향 갈대로 다시 떠 낸 정제 황지였고, 그 종이를 떠 오면 모가람이 외운 서식을 불러 사본을 받아 적게 하겠다고 했다."},{"s":"southern_remnant:galmae","t":"그을음은 내가 긁어 올게. 불탄 데는 널렸잖아."},{"s":"q:r71_seoharam","t":"닥나무는 제가 알아요… 관성대 뒤에도 있었거든요."}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":4,"title":"「백 공」","goal":"잿빛 들녘에서 4번 채집하고 정제 황지 1장을 떠 서식 사본으로 모가람에게 넘긴다","need":{"at":["hq_yard"],"tasks":[{"t":"gather","n":4,"r":["field_outskirts"]},{"t":"craft","items":["fine_paper"],"n":1}],"give":{"fine_paper":1}},"lines":[{"s":null,"t":"그다음 날 심지가 밝아진 것은 한밤이었다. 문수가 객사 문을 쿵쿵 두드렸다. 이번에는 여운비가 먼저 일어섰다."},{"s":null,"t":"여운비는 안쪽 방에 들어서자마자 무릎을 꿇었다. 품에서 낡은 편지 한 장을 꺼내 백운서 앞에 펼쳤다. 철벽 고찰 얼음 속, 둘째 장 뒤에서 나온 여사온의 편지였다."},{"s":"north_league:yeo","t":"「백 공께. 저는 울리겠습니다. 솔내에서 북령이 잃은 것을 생각하면 이 셈이 맞다는 것을 압니다. 다만 이 셈이 언젠가 끝나게 해 주십시오.」 「북령 종지기 여사온.」"},{"s":"north_league:yeo","t":"…제 작은증조할아버지의 글씨입니다. 백 공이 도제조님이십니까."},{"s":"night_office:baek","t":"그렇네. 그 편지의 「백 공」은 날세."},{"s":"north_league:yeo","t":"제 작은증조할아버지께 무슨 약속을 하셨습니까. 그리고… 북령은 왜 그 밤 종을 쳐야 했습니까. 집안 어른들은 그 까닭을 한 번도 입에 올리지 않았습니다."},{"s":null,"t":"백운서는 입을 열지 않고 왼손으로 오른 손목을 받치고 붓을 들었다. 등잔 심지가 지글, 하고 작게 울었다. 한 장을 쓰고 숨을 고르고, 또 한 장을 썼다. 여운비가 첫 장을 두 손으로 받아 읽었다."},{"s":"north_league:yeo","t":"「칸을 긁은 뒤에도 등도의 명등지기들은 거둔 이름을 밤마다 다시 불렀네. 맹약을 맺은 일곱 무리 가운데 일곱째, 이름을 불러 주는 이들이 그들이었네. 칸을 긁는 서명에 끝내 붓을 대지 않은 두 무리 가운데 하나였지.」"},{"s":"north_league:yeo","t":"「꺼진 이름이 밤마다 다시 켜지니, 진에 땔감으로 내줄 이름이 모자랐네. 그래서 문이 해마다 더 흔들렸네. 그들은 우리가 부르는 이름은 꺼진 이름이 아니라며 끝내 따르지 않았네. 정청과 등도는 서른 해를 그렇게 다퉜네.」"},{"s":"q:r71_seoharam","t":"명등지기요… 등도가 등의 도성이었던 게 그래서였구나. 이름 부르는 사람들이 살던 데라서요."},{"s":null,"t":"여운비가 다음 장을 받았다. 읽어 내려가던 여운비의 목소리가 한 번 걸렸다. 여운비는 그 종이를 갈매 쪽으로 내밀었다."},{"s":"north_league:yeo","t":"…이 장은 남명 사람이 읽는 게 맞겠소."},{"s":null,"t":"갈매가 미심쩍은 얼굴로 종이를 받았다. 갈매의 눈이 첫 줄에서 멎었다."},{"s":"southern_remnant:galmae","t":"「칠십 년 전 가을, 문이 크게 흔들렸네. 남명 국경 마을 둘이 하룻밤에 먹혔네. 정청 회의는 등도를 명부째 거두기로 정했네. 나는 그 회의의 윗자리에 있었고, 반대하지 않았네.」"},{"s":"southern_remnant:galmae","t":"…국경 마을 둘? 남명 마을이 먹혀서, 그래서 등도를 지웠다고? 남명 핑계를 대고?"},{"s":null,"t":"백운서는 고개를 저었다. 붓이 한 줄을 더 썼다. 갈매가 종이를 끌어다 소리 내어 읽었다."},{"s":"southern_remnant:galmae","t":"「핑계가 아니었네. 다음 해에는 넷, 그다음 해에는 여덟이 먹힐 셈이었네. 그 셈을 믿은 것이 내 죄일세.」"},{"s":null,"t":"갈매는 종이를 바닥에 내려놓았다. 주먹을 쥐었다가 폈다. 무어라 말하려다 입을 다물고 여운비를 보았다. 여운비가 마지막 장을 받아 읽었다."},{"s":"north_league:yeo","t":"「정청이 종 칠 사람을 찾을 때, 북령 젊은이 하나가 제 발로 왔네. 그 젊은이가 종루에 오르기 전에 나를 찾아와, 이 셈이 끝나게 해 달라고 하더군. 나는 그러마 했네. 그 밤 등도 사람들 이름을 정리 명부에 옮겨 적은 것도 나일세.」"},{"s":"north_league:yeo","t":"「약속은 아직 못 지켰네. 칠십 년이 지났는데도.」"},{"s":null,"t":"마지막 글자를 읽은 여운비의 손이 칼자루로 갔다. 칼집에서 칼날이 한 치쯤 스르릉 빠져나왔다. 단비가 오른손으로 여운비의 손목을 붙잡았다."},{"s":"red_moon_cult:danbi","t":"대장님."},{"s":null,"t":"여운비는 칼을 뽑지 않고, 칼날을 도로 밀어 넣은 뒤 손을 무릎 위에 내렸다. 여운비의 어깨가 떨리고 있었다."},{"s":"north_league:yeo","t":"…그 약속, 이번에는 지키십시오. 저희가 장을 다 모으겠습니다."},{"s":"night_office:baek","t":"끝내는 건 내가 아닐세. 저 조사원일세."},{"s":null,"t":"모두의 눈이 나에게 쏠렸다. 백운서의 눈도 나를 보고 있었다. 그 눈에 삼백 년의 피로가 고여 있었다. 백운서는 그 뒤로 한동안 붓으로만 답했다."},{"s":"red_moon_cult:danbi","t":"그럼 저도 여쭐게요. 그 밤 적월은 등도에 대던 기름을 끊었죠. 그것도 정청이 시킨 거예요? 그리고 적월이 백 년 동안 사들인 이름들이요. 서약에 쓴 이름들. 그거 누가 판 거예요?"},{"s":null,"t":"붓이 떨리며 움직였다. 획이 자꾸 옆으로 미끄러졌다. 단비는 왼손이 굳어, 오른손으로 종이를 바짝 끌어다 놓고 읽었다."},{"s":"red_moon_cult:danbi","t":"「정청이 청했네. 등불이 낮아져야 종소리가 이름에 닿는다고 했지. 그 밤 적월의 달 지기들이 등도로 가는 기름 입구를 닫았네.」"},{"s":"red_moon_cult:danbi","t":"「적월이 사들인 이름은 정리소에서 나갔네. 정리소는 거둔 이름을 적월로 흘려보내고, 그 대가로 적월의 서명을 받았지. 이름 목록은 해마다 정리소가 건넸네. 나는 알면서도 막지 않았네.」"},{"s":"red_moon_cult:danbi","t":"제가 열네 살에 처음 쓴 이름도요? 월하 씨가 손을 떨면서 건넨 그 쪽지요. 교주님은 그것도 목록에서 나왔다고 하셨어요."},{"s":null,"t":"백운서는 이번에는 한 줄만 썼다. 단비가 그 줄을 읽었다."},{"s":"red_moon_cult:danbi","t":"「자네가 열네 살에 쓴 이름도 그해 정리소 목록에서 나갔을 걸세.」"},{"s":null,"t":"단비의 웃음이 사라졌다. 단비는 먹빛으로 굳은 왼손을 오른손으로 감싸 쥐었다. 한참 뒤 단비가 다시 웃었다. 울음에 가까운 웃음이었다."},{"s":"red_moon_cult:danbi","t":"그럼 저도 갚을 거 있네요. 판 사람도 있고, 산 사람도 있고, 쓴 사람도 있는 거니까요."},{"s":null,"t":"청파가 단비 뒤에서 넷째 장을 펼쳤다. 증인 명부 맨 윗줄 「백운서」를 손가락으로 짚었다."},{"s":"q:sn_cheongpa","t":"저도요. 소등 전날 우리 증조할아버지 배가 남은 애들 태우러 돌아갔다가 수향 손에 가라앉은 거요. 알고 계셨어요?"},{"s":null,"t":"백운서의 붓이 종이에 닿았다가 한 번 멈췄다. 청파가 그 종이를 받아 쉰 목소리로 읽었다."},{"s":"q:sn_cheongpa","t":"「알았네. 그 배가 떠나는 날을 정한 것이 정청일세. 값을 치른 아이만 싣는 것도 못 본 척했네. 막았으면 그 배는 아예 떠나지도 못했을 테니.」"},{"s":"q:sn_cheongpa","t":"「배가 아이들을 마저 태우러 나루로 돌아간 것도, 수향이 그 배를 붙잡은 것도 알았네. 그 밤 등도의 문을 닫는 것이 내 셈이었네. 틀린 셈이었네.」"},{"s":"q:sn_cheongpa","t":"…그 애들 이름, 한 번만 불러 주세요. 하나만이라도요. 일흔 해 동안 아무도 안 불렀어요."},{"s":null,"t":"백운서는 고개를 저었다. 붓이 다시 움직였다. 청파가 다음 종이를 읽다가 입술을 깨물었다."},{"s":"q:sn_cheongpa","t":"「지금은 못 부르네. 심지에 묶인 내 입으로 부르면 그 이름까지 진에 묶이네. 진이 꺼지는 날 그 이름들을 부르겠네. 약속하지.」 …또 약속이요? 대장님네 작은증조할아버지한테 한 것도 아직 못 지켰다면서요."},{"s":null,"t":"백운서는 종이 끝에 짧게 덧붙였다. 청파가 그 줄을 소리 내어 읽었다. 「그러니 두 약속을 같은 날 지키겠네.」"},{"s":null,"t":"서하람이 마지막으로 별 기록 사본을 펼쳤다. 「하람」 두 글자 옆 붉은 인장을 짚었다. 백운서 무릎 곁에는 벌써 종이가 열 장 넘게 쌓여 있었다."},{"s":"q:r71_seoharam","t":"하나는 제 집 거예요. 왜 하필 그해 동짓밤이었어요? 종도, 기름도, 배도 다 그 밤에 맞췄잖아요."},{"s":null,"t":"백운서의 붓이 짧게 움직였다. 서하람은 그 종이를 읽고 한참 말이 없었다. 이윽고 작은 목소리로 읽었다."},{"s":"q:r71_seoharam","t":"「날짜는 천명원이 별을 읽어 골랐네. 그해 가장 긴 밤으로. 밤이 길어야 거둔 이름이 새벽 전에 다 가라앉는다고 했네.」 …또 천명원이네요. 칸을 긁은 말도, 등도가 지워진 날짜도요."},{"s":null,"t":"갈매가 서하람을 돌아보았다. 서하람은 고개를 숙이지 않고 별 기록 사본을 다시 백운서 앞으로 밀었다."},{"s":"q:r71_seoharam","t":"그런데 할머니가 제 이름을 별로 숨길 때는 허락하셨죠. 왜요? 별 기록판은 진의 일부잖아요. 진이 다칠 수도 있었는데요."},{"s":null,"t":"이번 붓은 유난히 오래 걸렸다. 몇 번이나 붓을 뗐다가 다시 댔다. 글씨는 끝으로 갈수록 크고 흐트러졌다. 서하람이 종이를 받아 읽었다."},{"s":"q:r71_seoharam","t":"「그 밤 이연이 울면서 찾아왔네. 나는 별 하나쯤은 진이 견딘다고 셈을 했네. 아닐세. 셈이 아니었네. 그 아기가 울었네. 나는 그 울음소리를 거둘 수가 없었네.」"},{"s":null,"t":"서하람은 종이를 무릎에 내려놓고 고개를 숙였다. 한참 뒤에 아주 작게 「고맙습니다」 하고 말했다. 문간의 갈매가 고개를 돌렸다."},{"s":null,"t":"심지가 다시 낮아졌다. 붓을 쥘 힘도 남지 않았는지, 백운서가 마지막으로 입을 달싹였다."},{"s":"night_office:baek","t":"감찰관이 정청으로 오고 있네. 혼자 오는 게 아닐세. 오는 길목에 먹 낀 것들이 있으니, 마중 나가게."}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":5,"title":"묵창 나루의 서리","goal":"감찰관이 올 잿빛 들녘 길목에서 종소리 먹은 늑대를 3번 쓰러뜨리고 본부 정청에서 쉰다","need":{"at":["hq_yard"],"tasks":[{"t":"win","n":3,"m":["dd_martial_4"],"r":["field_outskirts"]},{"t":"rest","r":["hq_yard"],"n":1}]},"lines":[{"s":null,"t":"정청 길목의 짐승들도 무관 거리에서 본 종소리 먹은 늑대였고, 정청 바깥 우물에서 먹물을 털며 올라온 것들이었다."},{"s":null,"t":"길목에서 먹 낀 짐승들을 몰아낸 새벽, 정청 대문 쪽에서 다그닥다그닥 말발굽 소리가 다가왔다. 말에서 먼저 내린 것은 감찰관 한설이었다."},{"s":null,"t":"한설의 뒤에서 한 사람이 더 내렸다. 정청 서리 옷을 입은 여자였다. 품에 낡은 장부 한 권을 꼭 안고 있었다. 나는 그 얼굴을 알았다. 묵창 나루의 출납 서리 희수였다."},{"s":"q:mk_hisu","t":"조사원. …오랜만입니다."},{"s":null,"t":"희수는 그 말만 하고 장부를 더 꼭 안았다. 눈 밑이 거뭇했다. 한설이 흙투성이 옷자락을 털며 우리를 하나하나 훑어보았다. 걸어 다니는 단비에게서 눈길이 잠깐 멈췄다."},{"s":"night_office:han","t":"무녀가 일어났구나. 다행이다."},{"s":"red_moon_cult:danbi","t":"감찰관님이 다행이라고 하니까 이상하네요. 웃는 거 처음 봐요."},{"s":"night_office:han","t":"안 웃었다. …조사원. 답장에 「둘, 그리고 물에서 하나」라고 썼지. 지금은."},{"s":null,"t":"나는 넷이라고 했다. 한설이 고개를 한 번 끄덕였다."},{"s":"night_office:han","t":"잘했다. 정리관이 묵창 나루까지 사람을 보내 이 서리를 데려가려 했다. 내가 먼저 데려왔다. 이 서리가 도제조님 앞에서 할 말이 있다."},{"s":null,"t":"그날 해 질 녘 심지가 밝아졌다. 희수가 안쪽 방 문지방을 넘어 백운서 앞에 무릎을 꿇었다. 장부를 펼쳐 한 줄을 짚었다. 다온의 이름 옆에, 붓으로 그은 작은 네모 칸이 있었다."},{"s":"q:mk_hisu","t":"그 밤에 제가 그은 칸입니다. 「불러 주는 이」. 그리고 조사원의 이름을 적었습니다. 이번에는 마지막 획까지 똑바로요."},{"s":"q:mk_hisu","t":"적고 나서… 장부가 따뜻해졌습니다. 손바닥에 닿는 종이가요. 나루 등잔들이 한꺼번에 한 번 흔들렸습니다. 저는 바람인 줄 알았어요."},{"s":"night_office:baek","t":"바람이 아니었네. 자네가 그 칸을 긋던 밤, 이 등잔이 삼백 년 만에 처음 깜빡였네."},{"s":"q:mk_hisu","t":"그 밤이 지나고 한 달쯤 뒤에 정리관님이 저를 부르셨습니다. 정청 위층 빈방이었어요. 그 칸을 누가 시켰느냐고 반나절을 물으셨어요. 그리고… 칼로 긁어 지우면 된다고. 칼을 탁자에 올려놓으셨어요."},{"s":null,"t":"희수의 목소리가 거기서 끊겼다. 장부를 쥔 손가락 마디가 하얘졌다. 한설이 희수의 어깨에 손을 얹었다."},{"s":"q:mk_hisu","t":"안 지웠습니다. 저는… 서율 님 이름도 끝까지 못 적었던 사람이라. 이번 칸까지 지우면, 저는…."},{"s":"red_moon_cult:danbi","t":"잘했어요. 진짜 잘했어요."},{"s":null,"t":"백운서가 붓을 들었다. 왼손으로 받친 오른 손목이 떨렸다. 다 쓴 종이를 희수가 받아 읽었다."},{"s":"q:mk_hisu","t":"「묵창 나루에 칸을 허락한 건 나일세. 칸이 다시 적혀야 진을 풀 수 있으니. 그 칸에 처음 적힌 이름이 자네일세, 조사원. 그래서 경현이 자네 이름을 노리는 걸세.」"},{"s":null,"t":"희수가 「경현」이라는 이름을 읽자 한설이 숨을 멈췄다. 백운서가 그 이름을 적은 것은 처음이었다. 백운서는 한설을 보지 않고 다음 종이에 붓을 댔다. 그러고는 다 쓴 종이를 한설 앞으로 밀었다."},{"s":null,"t":"한설은 한참 그 종이를 내려다보았다. 이윽고 종이를 집어 들고 읽기 시작했다. 감찰관이 문서를 읽는 목소리였다."},{"s":"night_office:han","t":"「백 년 전 서명은 내가 했네. 하지만 셈을 짠 아이는 경현이었네.」"},{"s":"night_office:han","t":"「솔내에서 건져 온 열 살 아이를 정청이 길렀지. 스무 살에 셈방에서 일하던 그 아이가 봉연 수위 표석 눈금과 해마다 거둔 이름 수를 맞춰 저울을 만들어 왔네. 이만큼 거두면 문이 안 흔들립니다, 하더군.」"},{"s":null,"t":"「솔내에서 건져 온 열 살 아이」에서 한설의 목소리가 한 번 걸렸다. 한설은 헛기침을 하고 다음 줄로 넘어갔다."},{"s":"night_office:han","t":"「나는 그 저울을 보고 칸을 긁기로 정했네. 정리소를 연 것도, 먹 도랑을 판 것도 그 아이일세. 백 년 동안 명부를 닫은 것도.」"},{"s":"southern_remnant:galmae","t":"관아 셈표에 그 자식 이름이 있긴 했어. 근데 당신이 시킨 거 아니었어? 그 자식 혼자 다 짰다고?"},{"s":null,"t":"백운서의 붓이 다시 움직였다. 한설은 종이가 바닥에 닿기도 전에 받아 들었다."},{"s":"night_office:han","t":"「내가 시킨 것이 아닐세. 시킬 필요도 없었네. 그때는 그 아이 셈이 옳았으니까. 칸을 두면 부름 장사가 돌고, 쌀 없는 고을부터 먹혔지. 솔내처럼.」"},{"s":"night_office:han","t":"「그런데 그 셈이 틀렸다는 것을 이제는 아네. 거둔 이름은 땅 밑의 것을 키우고, 커진 그것은 해마다 더 많은 이름을 달라고 하네. 백 년 전엔 한 해 열다섯이었는데 올해는 삼백을 넘었네.」"},{"s":"night_office:han","t":"「자네도 보았지, 조사원. 봉연에서 돌아온 날 내가 올해 먹 거두기는 하지 않는다고 했던 것을. 그해 겨울 구룡 폐수로 둘레 우물이 검어졌네.」"},{"s":null,"t":"한설이 종이에서 고개를 들었다. 한설의 얼굴이 굳어 있었다."},{"s":"night_office:han","t":"열한 사람입니다. 하룻밤에요."},{"s":null,"t":"백운서는 대답 대신 한 줄을 더 썼다. 글씨가 줄 밖으로 비스듬히 기울었다. 한설이 그 줄을 읽었다."},{"s":"night_office:han","t":"「진을 풀면 나는 죽네. 그건 괜찮네. 다만 진이 꺼지는 순간 문이 크게 흔들릴 걸세. 그때 무엇이 문틈을 막을지 나도 아직 모르네.」"},{"s":null,"t":"단비가 「죽는다고요?」 하고 되물었다. 백운서는 붓을 내려놓았다. 무릎 곁에 쌓인 종이 더미가 등잔불에 누렇게 비쳤다. 한설이 읽던 종이를 그 위에 얹고, 품에서 보고서 묶음을 꺼내 백운서 앞에 내려놓았다."},{"s":"night_office:han","t":"도제조님. 제 동료 셋의 보고서를 고친 손이 정리소였습니다. 고친 자리마다 먹이 두 번 앉아 있었고, 먹 도랑 냄새가 났고, 모서리가 접혀 있었습니다."},{"s":"night_office:han","t":"고친 글씨는 먹이 두 번 앉는다. …그걸 가르쳐 주신 분이 그분입니다. 정리소 서리는 하나뿐입니다."},{"s":null,"t":"방 안이 조용해졌다. 등잔 심지가 지글거렸다. 백운서는 눈을 감았다. 한참 만에 백운서의 입이 다시 열렸다."},{"s":"night_office:baek","t":"감찰관, 그 아이를 이길 말은… 나한테도 없네."},{"s":null,"t":"심지가 낮아졌다. 한설은 백운서 앞에 오래 서 있다가, 붓을 꺼내 아주 천천히 닦기 시작했다."}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":6,"title":"한설의 술","goal":"본부 객사에서 감찰관과 함께 쉰다","need":{"at":["hq_dorm"],"tasks":[{"t":"rest","r":["hq_dorm"],"n":1}]},"lines":[{"s":null,"t":"그 밤 한설이 객사에 술병을 들고 왔다. 감찰관이 술병을 든 것을 본 사람은 아무도 없었다. 문수가 그 술병을 보고 입을 떡 벌렸다."},{"s":"q:dh_munsu","t":"감찰관님이요? 술이요? 정청 규정 제… 몇 조더라, 근무 중 음주 금지거든요."},{"s":"night_office:han","t":"근무 아니다. 오늘은 내가 나를 감찰하지 않기로 했다."},{"s":null,"t":"한설은 잔 여덟을 늘어놓고 술을 따랐다. 쪼르륵 소리가 났다. 청파의 잔에는 반만 따랐다."},{"s":"q:sn_cheongpa","t":"왜 저만 반이에요!"},{"s":"night_office:han","t":"숨통 상한 사람은 반이다. 규정이다."},{"s":"q:sn_cheongpa","t":"그런 규정 없잖아요!"},{"s":"night_office:han","t":"방금 만들었다."},{"s":null,"t":"갈매가 푸하 웃었다. 단비가 오른손으로 잔을 들다가 흘렸다. 여운비가 잔을 단비 손이 닿는 데로 밀어 놓아 주었다. 희수는 잔을 두 손으로 받아 들고 한 모금에 비웠다."},{"s":"q:mk_hisu","t":"…쓰네요."},{"s":"red_moon_cult:danbi","t":"서리님, 원래 이렇게 잘 마셔요?"},{"s":"q:mk_hisu","t":"아니요. 처음입니다."},{"s":null,"t":"한설은 잔을 비우고 한참 말이 없었다. 우리도 말을 걸지 않았다. 이윽고 한설이 입을 열었다."},{"s":"night_office:han","t":"오늘 낮에 판관 회의를 열려고 했다. 감찰관이 죄를 적은 문서를 들고 서면 회의는 열려야 한다. 그게 규정이다."},{"s":"night_office:han","t":"여섯 판관 가운데 아무도 오지 않았다. 한 분만","fac_not":"night_office","spec":2,"grp":1},{"s":"night_office:han","t":"여섯 판관 가운데 아무도 오지 않았다. 한 분만","fac":"night_office","rank":[1,4],"spec":0,"grp":1},{"s":"night_office:han","t":"판관, 너는 길 위에 있었으니 빼자. 남은 다섯 판관 가운데 아무도 오지 않았다. 한 분만 문간에 와서 그러시더라. 「감찰관, 내 어머니 이름은 그분이 올해 빼 주셨네. 나는 그 회의에 못 앉네.」","fac":"night_office","rank":[5,5],"spec":0,"grp":1},{"s":"southern_remnant:galmae","t":"판관들 어머니 이름을… 그 자식이 빼 줬다고?"},{"s":"night_office:han","t":"백 년 동안. 판관 집안마다 몇 번씩. 다들 그 빚을 안다. 정리관이라는 직함도 그 회의에서 나왔다."},{"s":"night_office:han","t":"구룡 폐수로 열한 사람이 풀린 이튿날이었다. 우물가 물동이 옆에 옷과 신만 남아 있었다. 스승님이 그 옷 열한 벌을 판관 회의 탁자에 하나씩 올려놓았다. 「명부 일을 맡는 정리관을 두고, 명부 일에 한해 정청 인장을 쓰게 해 주십시오.」 아무도 반대하지 못했다. 나도 그 회의 끝자리에 있었다."},{"s":"night_office:han","t":"조사원. 불 난 밤에 네가 정리관이 무슨 자리냐고 물었지. 나는 모른다고 했다. 알았다. 그때 말하지 못했다. 스승님 이름 옆에 「모른다」를 적는 게 그날은 더 쉬웠다."},{"s":"q:r71_seoharam","t":"감찰관님도… 반대 못 하셨어요?"},{"s":"night_office:han","t":"못 했다. 그 옷 열한 벌 앞에서 무슨 말을 하겠나."},{"s":null,"t":"한설이 소매에서 붓 한 자루를 꺼냈다. 붓대 끝이 닳아 반들반들했다."},{"s":"night_office:han","t":"조사원, 장서각 재를 헤치던 날 너한테 말했지. 붓 살 돈이 없던 날 그분이 쓰던 붓을 쥐여 주셨다고. 이게 그 붓이다. 「이름은 한 번 들으면 외우시오.」"},{"s":"night_office:han","t":"그날 저녁 이 붓으로 첫 보고서를 썼다. 그분이 읽어 보시더니 내가 고친 글자 하나를 짚으셨다. 「고친 글씨는 먹이 두 번 앉소.」 그리고 다 쓴 보고서는 모서리를 한 번 접어 두라고 하셨다. 다음 장을 넘기기 전에 한 번 더 보라고. …나는 그게 꼼꼼함인 줄 알았다."},{"s":null,"t":"한설은 붓을 닦았다. 아주 천천히 닦았다. 갈매가 술병을 들어 한설의 빈 잔을 채웠다. 갈매가 정청 사람에게 술을 따르는 것을 나는 처음 보았다."},{"s":"southern_remnant:galmae","t":"정청 놈 중에 그나마 덜 싫은 놈이니까 따라 주는 거야."},{"s":"night_office:han","t":"…고맙다."},{"s":"southern_remnant:galmae","t":"고맙다고 하지 마. 소름 돋아."},{"s":"north_league:yeo","t":"장은 넷이오. 첫째 장 반쪽을 정리소 서식과 견줘 이으면 다섯이오. 그다음이 남명, 그다음이 흑련이오. 정리관은 다 모일 때까지 기다리겠다고 했소. 기다리게 두면 안 되오."},{"s":"night_office:han","t":"그래서 너희를 보냈다. 판관들은 못 움직여도, 너희는 그 사람보다 반 장 앞에 설 수 있으니까. 내일 정리소로 간다. 문은 감찰관이 보고서를 들고 서야 열린다. 그건 진짜 규정이다."},{"s":null,"t":"술병이 비었다. 청파가 꾸벅꾸벅 졸다 서하람의 어깨에 기댔다. 서하람은 이번에는 졸지 않고, 청파가 미끄러지지 않게 어깨를 대 주었다."},{"s":null,"t":"한설이 일어서며 내 어깨를 한 번 짚었다. 무거운 손이었다."},{"s":"night_office:han","t":"조사원. 내일 내가 그분 앞에서 말을 못 하면, 네가 해라. 나는 아마… 말을 못 할 거다."},{"s":null,"t":"나는 그러겠다고 했다. 한설은 고개를 끄덕이고 객사를 나갔다. 문간에서 한 번 멈춰 섰다가 돌아보지 않고 갔다."}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":7,"title":"정리소","goal":"장서각 지하서고에 도착해 탐색하며 정리소로 가는 길의 실마리를 2번 찾는다","need":{"at":["jeongni_vault"],"tasks":[{"t":"travel","r":["hq_archive"],"n":1},{"t":"clue","r":["hq_archive"],"n":2}]},"lines":[{"s":null,"t":"장서각 지하서고 맨 끝에 우물 하나가 있었다. 우물 테에 철문이 덮여 있었고, 문 가운데에 쇠패 모양의 홈이 패어 있었다."},{"s":null,"t":"내가 열쇠패를 홈에 끼웠다. 철컥 소리가 났지만 문은 열리지 않았다. 한설이 보고서 묶음을 문 위에 올려놓자, 그제야 끼이익 철문이 천천히 밀려 열렸다."},{"s":"night_office:han","t":"규정대로구나. …이 문을 만든 사람도 규정을 지키는 사람이었다."},{"s":null,"t":"쇠 손잡이를 따라 끝까지 내려가자 돌로 쌓은 넓은 방이 나왔다. 방 한쪽 벽을 따라 돌 도랑이 길게 뚫려 있었고, 그 도랑에 먹물이 천천히 흘렀다."},{"s":null,"t":"오래 고여 썩은 먹 냄새가 코를 찔렀다. 단비가 오른손으로 코를 막았다. 청파는 콜록 기침을 했다."},{"s":null,"t":"먹물 위로 무언가 떠올랐다 가라앉았다. 글자였다. 사람 이름 글자들이 먹물 속에서 꼬물꼬물 떠올랐다가 흩어졌다. 도랑 가에 쪼그려 앉아 들여다보던 서하람이 손을 홱 뺐다."},{"s":"q:r71_seoharam","t":"이름이에요… 다 이름이에요. 손 대면… 미지근해요. 아직 미지근해요."},{"s":null,"t":"방 한가운데에는 사람 키만 한 저울이 서 있었다. 저울 옆 벽에 「봉연 수위」라는 머리 아래 해마다의 눈금과 그해 거둘 이름의 수가 백 해치 빼곡했다. 맨 아래 줄에 올해의 수 「삼백십이」가 적혀 있었다."},{"s":null,"t":"저울 받침 둘레에는 촛불 일곱이 나란히 타고 있었다. 저울 접시가 조금만 기울어도 일곱 불꽃이 한꺼번에 흔들렸다. 무관 거리 처마 밑 불가에서 경현이 말하던 그 촛불이었다."},{"s":null,"t":"저울 옆에 오래된 서식 한 장이 걸려 있었다. 「가장 오래된 정리 서식」이라는 머리 아래 첫째 장 앞부분이 베껴져 있었다. 「부를 이 없는 이름만 거둔다.」 불에 탄 바로 그 앞부분이었다."},{"s":null,"t":"도랑 끝 책상 앞에 경현이 앉아 있었다. 경현은 장부를 넘기다가 모서리를 접고, 고개를 들어 한설을 보았다."},{"s":"q:md_gyeonghyeon","t":"왔구나, 설아. 손님도 여섯이나 데려오고. 묵창 나루 서리까지.","fac_not":"night_office","spec":2,"grp":1},{"s":"q:md_gyeonghyeon","t":"왔구나, 설아. 정통파 패를 찬 손님까지 데려왔구나. 정청 사람이 제 발로 정리소에 걸어 들어온 건 백 년 만이다.","fac":"night_office","spec":1,"grp":1},{"s":null,"t":"한설은 보고서 묶음을 경현의 책상 위에 내던졌다. 철퍼덕, 보고서가 흩어지며 접힌 모서리들이 드러났다."},{"s":"night_office:han","t":"왜… 고치셨습니까."},{"s":null,"t":"한설의 목소리가 거기서 끊겼다. 한설은 입을 열었다가 닫았다. 붓을 쥔 손이 떨렸다. 나는 한설 곁에 섰다. 한설 대신, 한설의 동료 셋이 왜 그해 정리 명부에 올랐느냐고 물었다."},{"s":"q:md_gyeonghyeon","t":"조사원이 대신 묻는구려. 설아, 말이 안 나오는 건 나를 닮았구나. 나도 화가 나면 말이 줄었다."},{"s":"q:md_gyeonghyeon","t":"그해 저울은 정청 안에서 부를 이 없는 이름 넷을 내놓으라고 했다. 설아, 네 조가 꼭 넷이었지. 넷 다 정청이 거둬 기른 아이라 불러 줄 집이 없었다."},{"s":"q:md_gyeonghyeon","t":"셋의 보고서는 내가 고쳤다. 그해 검은 우물가에 그 셋만 있었던 것처럼. 그래야 명부에 올린 줄이 셈에 맞았다. 처음엔 붉은 줄을 반만 그어 미뤄 두었다. 먹손으로 데려와 내 일을 시킬 셈이었다."},{"s":"q:md_gyeonghyeon","t":"셋 다 먹손이 되기를 마다했다. 감찰관이 될 사람은 먹손이 되지 않는다고, 내가 그렇게 가르쳤으니까. 그래서 사흘 뒤에 줄을 마저 그었다."},{"s":"q:md_gyeonghyeon","t":"너는 처음부터 명부에 올리지 않았다. 네 보고서만은 한 글자도 고치지 않았다. 넷째 자리는 다른 고을 이름으로 채웠다."},{"s":"q:md_gyeonghyeon","t":"…왜 너였는지는 묻지 마라. 내가 쓰던 붓을 네가 쥐고 있었다. 그것뿐이다."},{"s":null,"t":"한설의 얼굴이 하얗게 질렸다. 한설이 흔들리듯 한 걸음 물러섰다. 나는 한설의 등 뒤에 손을 댔다. 한설은 쓰러지지 않았다."},{"s":null,"t":"그사이 서하람은 책상 옆 서가에서 두꺼운 장부 한 권을 빼 들고 있었다. 겉장에 「미룸」 두 글자가 적혀 있었다. 장을 넘기는 서하람의 손이 점점 빨라졌다."},{"s":"q:r71_seoharam","t":"이거… 다 반만 그은 줄이에요. 이름마다 붉은 줄이 반만 그어지고, 옆에 「정리관」 도장이요. 몇백 명이에요. 백 년치요. 그리고 여기… 머리에 「먹손」이라고 적혀 있어요."},{"s":"q:md_gyeonghyeon","t":"줄을 미뤄 준 사람들이오. 그 값으로 내 일을 하지. 손끝이 먹에 절어서 정리소에서는 그렇게 부르오. 먹손."},{"s":null,"t":"단비가 경현의 손을 보았다. 장부를 쥔 경현의 손끝도 먹손들처럼 까맸다."},{"s":"red_moon_cult:danbi","t":"…그래서였구나. 관아 터 서식이요. 백 년 된 서명 먹이 엊그제 쓴 것처럼 반들거렸어요."},{"s":"q:md_gyeonghyeon","t":"지난달 내가 그 서식을 손으로 한 번 쓸어 보았소. 내 손에는 백 년 먹이 배어서, 이 손이 닿으면 마른 먹도 다시 젖소. 오래된 글씨일수록 더 그렇지."},{"s":"southern_remnant:galmae","t":"그럼 무관 거리에서 빌던 그놈도, 배 젓던 놈들도…!"},{"s":"q:md_gyeonghyeon","t":"내가 줄을 마저 그으면 사흘이오. 그러니 그들은 나를 떠나지 않소. 고마워서가 아니라 살고 싶어서. 그게 사람이오."},{"s":"north_league:yeo","t":"장서각에 불을 놓은 것도 그들이오. 왜 그랬소."},{"s":"q:md_gyeonghyeon","t":"첫째 장을 태우려고 그랬소. 일곱 장 가운데 하나라도 없으면 맹약은 영영 풀 수 없소. 그러면 진도 지금 그대로 남지."},{"s":"q:md_gyeonghyeon","t":"그런데 장은 반만 탔소. 기록관이 맨손으로 감싸 안고 나올 줄은 몰랐소. 그 두 손은… 내 셈에 없던 값이오."},{"s":"q:md_gyeonghyeon","t":"그리고 그 밤, 봉연 천장의 불빛 하나가 깜빡였소. 장이 반쪽 타는 동안 문이 한 번 흔들린 거요. 그래서 알았지. 장을 한 장씩 태우는 건 위험하다는 것을."},{"s":null,"t":"경현이 일어서려 했다. 그 순간 도랑의 먹물이 부글부글 끓어올랐다. 먹으로 된 검은 손 여럿이 도랑 위로 기어 올라왔다. 손가락마다 이름 글자가 엉겨 붙어 있었다."},{"s":"q:md_gyeonghyeon","t":"아, 저것들은 내 말도 안 듣소. 거둔 이름들이 뭉친 거라. 낯선 이름 냄새를 맡으면 올라오지. 미안하오."},{"s":"southern_remnant:galmae","t":"미안하면 치워!"},{"s":"q:md_gyeonghyeon","t":"치우는 건 당신들 몫이오. 오늘 나는 정리관이 아니라 스승으로 앉아 있으니까."},{"s":"red_moon_cult:danbi","t":"이 사람 진짜 얄밉다!"},{"s":null,"t":"검은 손 하나가 휘익 단비의 왼쪽을 낚아채려 했다. 단비는 왼쪽을 보지 못했다. 여운비가 몸을 날려 단비를 감싸 안고 굴렀다. 쿵, 둘이 돌바닥에 부딪혔다."},{"s":"north_league:yeo","t":"왼쪽은 내가 보겠소! 당신은 오른쪽만 보시오!"},{"s":"red_moon_cult:danbi","t":"네, 대장님!"},{"s":null,"t":"청파가 도랑 가의 등잔을 들어 검은 손에 휘둘렀다. 손들이 불빛에 움찔 물러났다. 희수가 장부를 품에 안은 채 벽에 등을 붙였다."},{"s":"q:r71_seoharam","t":"불빛을 싫어해요! 등잔을 높이요!"}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":8,"title":"장독","goal":"정리소에서 먹 도랑 검은 손을 4번 쓰러뜨리고 가늠 저울 둘레를 3번 탐색한다","need":{"at":["jeongni_vault"],"tasks":[{"t":"win","n":4,"m":["dd_vault_1"]},{"t":"search","r":["jeongni_vault"],"n":3}]},"lines":[{"s":null,"t":"마지막 검은 손이 철벅 소리를 내며 도랑으로 무너져 내렸다. 우리는 숨을 헐떡였다. 경현은 그동안 한 번도 자리에서 움직이지 않았다."},{"s":null,"t":"경현은 흩어진 보고서를 한 장씩 주워 모서리를 맞추었다. 그 손길은 느리고 정성스러웠다."},{"s":"q:md_gyeonghyeon","t":"저 저울은 내가 만들었소. 스무 살에. 정리소도 내가 열고, 저 도랑도 내가 팠소. 도제조께서 하신 일은 서명 하나였지. 나는 그 서명 하나로 백 년을 굴렸소."},{"s":"southern_remnant:galmae","t":"자랑이냐?"},{"s":"q:md_gyeonghyeon","t":"셈이오. 칸이 무엇인지 아시오, 남명 정찰대장? 명부 한 줄 끝의 손바닥만 한 네모요. 그 사람을 불러 줄 이가 제 이름을 적고 엄지 도장을 꾹 찍지. 도장이 찍힌 줄은 거둘 수 없소."},{"s":"q:md_gyeonghyeon","t":"장날이면 장터 한쪽에 부름꾼이 명부 사본을 펴고 앉았소. 쌀 두 섬이면 아무 줄에나 도장을 찍어 줬지. 한 해에 수백 줄을. 그 이름을 실제로 불러 준 부름꾼은 하나도 없었소."},{"s":"q:md_gyeonghyeon","t":"솔내는 북령 산골 화전민 고을이었소. 마흔두 집. 글을 아는 사람은 훈장 하나였지. 그해 장날에도 부름꾼이 왔소. 솔내에는 쌀이 없었소."},{"s":null,"t":"경현은 장부의 접힌 모서리를 엄지로 누른 채 나를 보았다."},{"s":"q:md_gyeonghyeon","t":"지난번 모닥불 앞에서는 솔내 얘기를 반만 했소. 나머지 반을 해 드리지. 당신은 끝까지 들을 사람 같으니까."},{"s":"q:md_gyeonghyeon","t":"동짓밤, 우물마다 검은 물이 솟았소. 어머니가 나를 빈 장독에 넣고 뚜껑을 덮었소. 그리고 그 뚜껑 위에 앉아서, 새벽까지 내 이름을 불렀소."},{"s":"q:md_gyeonghyeon","t":"장독 안은 캄캄했소. 뚜껑 틈으로 금빛이 새어 들어왔지. 어머니 입김이었소. 그 빛이 가슴에 닿을 때마다 따뜻했소."},{"s":"q:md_gyeonghyeon","t":"검은 물이 장독 둘레까지 차올라 찰랑거렸소. 장독 안의 나는 젖지 않았소. 뚜껑 위에서 부르는 소리는 점점 작아졌소. 어머니는 발끝부터 먹으로 풀려서, 부르는 소리째 물에 섞였소."},{"s":"q:md_gyeonghyeon","t":"새벽에 뚜껑을 열었소. 남은 것은 어머니의 치마 한 벌이었소. 젖지도 않은 채로."},{"s":null,"t":"아무도 말하지 않았다. 도랑의 먹물이 졸졸 흐르는 소리만 났다. 단비가 오른손으로 입을 막았다. 청파는 고개를 숙였다. 희수는 장부를 끌어안은 채 눈을 감았다."},{"s":"q:md_gyeonghyeon","t":"그날 나는 배웠소. 부름은 하나를 살리고 하나를 죽인다는 것을. 칸을 다시 들이면 다음 장날에 부름꾼이 다시 앉소. 당신은 쌀 두 섬이 없는 고을을 본 적이 있소? 문제는 칸이 아니라 돈이오. 돈을 없앨 수 없으니 칸을 없앤 거요."},{"s":"q:md_gyeonghyeon","t":"서른 해 전 기록감찰국 국장은 반쯤 요괴가 된 사람들을 배에 태워 섬으로 보내면 덜 아플 줄 알았소. 그 안이 올라왔을 때 나는 말리지 않았지. 국장은 끝내 제 이름까지 그 명부에 적었소."},{"s":"q:md_gyeonghyeon","t":"그 섬 끝에서 국장을 눕힌 게 당신이라지요. …셈을 잘못하면 그렇게 되오. 나는 내 셈을 틀리지 않으려고 백 년을 셌소."},{"s":"southern_remnant:galmae","t":"그래서 우리 임금을 거뒀어? 가난한 남명 사람들을 맨 앞에 세우고?"},{"s":"q:md_gyeonghyeon","t":"그 말은 맞소, 남명 정찰대장. 그 셈의 값을 남명이 가장 많이 치렀소. 그 값을 누가 대신 치렀는지는… 화로 앞에서 들으시오. 내 입으로 할 얘기가 아니니."},{"s":null,"t":"갈매의 얼굴이 굳었다. 갈매는 무엇을 물어야 할지 몰라 입술만 달싹였다. 경현이 장부를 덮었다. 덮인 장부 모서리마다 접힌 자국이 수없이 겹쳐 있었다."},{"s":"q:md_gyeonghyeon","t":"장부 모서리를 왜 접느냐고 묻는 사람이 많소. 다음 장을 넘기기 싫어서요. 다음 장에는 늘 다음 해의 이름이 있으니까."},{"s":"q:md_gyeonghyeon","t":"동짓밤마다 나는 여기서 그해 이름을 다 읽소. 한 이름도 빼지 않고. 내가 잊지 않는 한 그들은 숫자가 아니오. 다 읽고 나면 저 도랑 끝에 귀를 대고 앉아 있지."},{"s":"q:r71_seoharam","t":"…거기서 뭐가 들려요?"},{"s":"q:md_gyeonghyeon","t":"누가 내 이름을 부르오. 「경현아」 하고. 백 년째. …누군지는 묻지 마시오. 오늘은 거기까지만 하겠소."},{"s":null,"t":"경현의 목소리가 처음으로 흔들렸지만, 아주 잠깐이었다. 경현은 곧 장부를 다시 펴고 모서리를 접었다."},{"s":"night_office:han","t":"…저도 접었습니다. 스승님이 가르치신 대로. 다음 장을 넘기기 싫었던 적은 없었는데."},{"s":"q:md_gyeonghyeon","t":"그래. 너는 넘겨라, 설아. 너는 내가 아니다."},{"s":"q:md_gyeonghyeon","t":"판관 회의를 열어 나를 막으려 하지는 마라. 회의는 열리지 않을 거다. 여섯 집 가운데 다섯 집 어른 이름을 내가 정리 명부에서 뺐으니. 그 다섯이 나를 막는 자리에 앉을 리 없다."},{"s":"q:md_gyeonghyeon","t":"남은 한 집이 판관 당신이오. 당신 집 어른 이름은 내가 빼 줄 일이 없었소. 다만 판관 혼자서는 회의를 못 여오.","fac":"night_office","rank":[5,5],"spec":0,"grp":1},{"s":null,"t":"나는 모가람이 불러 준 사본을 꺼냈다. 저울 옆 「가장 오래된 정리 서식」과 나란히 대어 보았다. 글자 하나하나가 똑같았다. 모가람은 서른 해 동안 한 글자도 틀리지 않았다."},{"s":null,"t":"한설이 그 사본을 첫째 장의 타다 남은 반쪽에 댔다. 탄 가장자리가 저절로 이어지듯 글자가 스르르 번져 나갔다. 「부를 이 없는 이름만 거둔다. 거둔 이름은 지우지 않고 적어 둔다.」"},{"s":null,"t":"두 문장이 처음으로 한 장 위에 나란히 섰다. 반쪽이던 흰 불꽃이 온전한 크기로 떠올랐다. 정리소의 썩은 냄새 속에서 그 불꽃만 맑게 탔다."},{"s":"night_office:han","t":"정청의 장은 정청 사람 앞에서 이어야지. …내가 지켜보마."},{"s":null,"t":"한설이 감찰관의 붓을 내게 내밀었다. 내가 「이을 이」 칸에 이름을 적자 첫째 장의 불꽃이 금빛으로 바뀌었다. 다섯 장이 금빛 실로 이어졌다."},{"s":"q:sn_cheongpa","t":"다섯이에요. 이제 둘 남았어요!"},{"s":"q:md_gyeonghyeon","t":"…다섯이면 거의 다 모았구려. 그래도 오늘은 보내 드리겠소. 일곱째는 아직 내 금고에 있고, 남명 장은 아직 남명 땅에 있으니까. 한 장씩 태우면 문이 흔들리오. 일곱이 한자리에 모였을 때 한꺼번에 태워야 진이 그대로 굳소."},{"s":null,"t":"경현이 손을 내저었다. 도랑의 먹물이 다시 부글부글 끓어올랐다. 검은 손들이 이번에는 우물 쪽 쇠 손잡이를 향해 기어갔다."},{"s":"q:md_gyeonghyeon","t":"서두르시오. 저것들은 내가 말려도 안 듣는다고 했잖소."},{"s":"night_office:han","t":"조사원, 손잡이부터 지켜라! 길이 막히면 못 나간다!"}],"reward":{"xp":2247}},{"quest_id":"mdq_13","step":9,"title":"첫 줄","goal":"정리소 우물 손잡이로 기어오르는 요괴를 2번 쓰러뜨리고 장서각 지하서고로 올라간다","need":{"at":["hq_archive"],"tasks":[{"t":"win","n":2,"r":["jeongni_vault"]}]},"lines":[{"s":null,"t":"손잡이에 들러붙은 마지막 검은 손을 떼어 내자 한설이 내 팔을 잡아끌었다. 우리는 쇠 손잡이를 붙잡고 우물을 기어올랐다."},{"s":null,"t":"맨 뒤의 갈매가 손잡이에 발을 디딜 때, 아래에서 경현의 목소리가 울렸다."},{"s":"q:md_gyeonghyeon","t":"남명 정찰대장. 어제 해 질 녘에 잔불촌에 다녀왔소. 노장께 차를 한 잔 얻어 마셨지. 미리 말해 두리다. 장군 이름에 반만 그어 접어 둔 줄은, 그때 내 손으로 마저 그었소."},{"s":"southern_remnant:galmae","t":"뭐? 할배 이름에 줄을 그었다고? 할배한테 무슨 짓을 했어! 야! 거기 서!"},{"s":null,"t":"갈매가 도로 뛰어내리려 했다. 위에서 여운비가 갈매의 손목을 낚아채 끌어올렸다. 갈매가 이를 갈며 손잡이를 밟았다."},{"s":null,"t":"우물 밖으로 나온 한설은 지하서고 바닥에 털썩 주저앉았다. 처음으로 붓을 닦지 않았다. 붓은 한설의 손에 들린 채 떨리고 있었다."},{"s":"night_office:han","t":"…나는 그분께 붓 잡는 법을 배웠다. 모서리를 접는 버릇도… 그분께 배운 거였구나."},{"s":null,"t":"그때 지하서고 계단 위에서 쿵쿵쿵 다급한 발소리가 내려왔다. 문수가 웬 소년 하나를 데리고 뛰어 내려왔다. 소년의 손목에 남명 불씨 끈이 감겨 있었다. 소년은 숨을 헐떡이며 무릎을 짚었다."},{"s":"q:md_south_runner","t":"갈매 누나! 누나, 큰일 났어! 장군님이…!"},{"s":"southern_remnant:galmae","t":"숨 쉬고 말해! 할배가 뭐!"},{"s":"q:md_south_runner","t":"어제 해 질 녘에 정리관이 마을 우물에서 올라왔어! 장군님 앞에서 장부를 펴더니 붉은 먹으로 한 줄을 긋고 갔어! 장군님 그림자가… 반이 됐어! 소이 누나가 누나 데려오래. 빨리 데려오래!"},{"s":null,"t":"갈매의 얼굴에서 핏기가 싹 가셨다. 갈매는 대답도 하지 않고 계단을 뛰어올랐다. 쾅, 지하서고 문이 벽에 부딪혔다."},{"s":"red_moon_cult:danbi","t":"갈매 씨! 혼자 가면 안 돼요!"},{"s":"north_league:yeo","t":"조사원, 따라가시오! 청파는 단비 왼쪽을 받치시오. 그쪽은 안 보이오!"},{"s":"q:r71_seoharam","t":"잔불촌이요! 지금 가면 밤 되기 전에 닿아요!"},{"s":null,"t":"한설이 바닥에서 일어서며 붓을 소매에 꽂았다."},{"s":"night_office:han","t":"가라, 조사원. 나는 여기 남는다. 그분은 저 도랑으로 드나든다. 감찰관이 이 문을 지키고 서 있어야 금고 장부에 손을 못 댄다. 소식은 날마다 서신으로 보내마."},{"s":"night_office:han","t":"너는 장군 곁에 있어라. 부를 사람이 곁에 있어야 한다."},{"s":"q:mk_hisu","t":"저도 서고에서 남명 줄을 찾아보겠습니다. 칸을… 그을 수 있는지요."},{"s":null,"t":"나는 계단을 뛰어올랐다. 정청 마당 너머로 갈매의 등이 작아지고 있었다. 나는 갈매의 이름을 부르며 그 뒤를 쫓았다."}],"reward":{"xp":2247,"gil":510,"items":{"ledger_tab":3,"balance_weight":1}}},{"quest_id":"mdq_14","step":1,"title":"옅어진 그림자","goal":"잔불촌에 도착해 화로 앞에서 옅어진 그림자를 본다","need":{"at":["ember_village"],"tasks":[{"t":"travel","r":["ember_village"],"n":1}]},"lines":[{"s":null,"t":"정청 마당을 뛰쳐나간 뒤로 갈매는 한 번도 걸음을 늦추지 않았다. 고개 하나를 넘을 때마다 갈매의 등은 우리보다 한 굽이씩 앞에 있었다."},{"s":null,"t":"잔불촌 어귀에 닿았을 때 해가 산등성이에 걸려 있었다. 갈매가 마을 돌길로 뛰어들자 타다닥, 발소리가 멀어졌다."},{"s":null,"t":"청파가 뒤따라 뛰려다 무릎을 짚고 콜록콜록 기침을 쏟았다. 정청에서부터 내내 숨을 참고 달려온 얼굴이 새파랬다."},{"s":"north_league:yeo","t":"뛰지 마시오! 숨이 끊겨서 가면 아무 쓸모가 없소."},{"s":"q:sn_cheongpa","t":"그래도 갈매 누님 혼자 가잖아요!"},{"s":null,"t":"단비가 오른손으로 청파의 손목을 꽉 잡았다. 웃음기 하나 없는 얼굴이었다."},{"s":"red_moon_cult:danbi","t":"혼자 안 둬요. 걸어서 빨리 가요. 제 손 놓지 말고요."},{"s":null,"t":"서하람은 가쁜 숨을 고르며 마을 한가운데를 올려다보았다. 화로 연기가 바람 없는 하늘로 곧게 서 있었다."},{"s":"q:r71_seoharam","t":"연기가 똑바로 서 있어요. 화로가 아직 살아 있다는 거예요. 아직… 늦지 않았어요."},{"s":null,"t":"마을 한가운데 커다란 화로가 붉게 타고 있었다. 장무현은 늘 앉던 낮은 걸상에 앉아 부지깽이로 숯을 고르고 있었다."},{"s":null,"t":"화로 불빛이 노인의 등 뒤로 그림자를 길게 드리웠다. 그림자는 물에 탄 먹처럼 흐릿했다."},{"s":null,"t":"걸상 다리의 그림자는 시커멓고 또렷했다. 노인의 그림자만 땅바닥에서 반쯤 지워져 있었다."},{"s":null,"t":"갈매가 그 앞에 털썩 무릎을 꿇었다. 손바닥으로 그림자를 더듬던 갈매의 손이 딱 멈췄다. 손바닥에 닿는 것은 맨땅의 차가운 감촉뿐이었다."},{"s":"southern_remnant:galmae","t":"할배. 할배, 이게 뭐야. 누가 그랬어? 누가!"},{"s":null,"t":"장무현은 부지깽이를 놓지 않았다. 숯을 뒤집자 그 밑에서 꺼지지 않는 흰 불씨가 반짝 빛났다."},{"s":"southern_remnant:jang","t":"소리 좀 낮춰라. 마을 사람들 다 깨겠다."},{"s":null,"t":"화로 뒤에 서 있던 무녀 소이가 앞으로 나섰다. 눈가가 짓물러 붉었다."},{"s":"southern_remnant:soi","t":"어제 해 질 녘이었사옵니다. 정리관이 마을 우물에서 홀로 올라왔사옵니다. 옷자락이 먹물에 흠뻑 젖어 있었사옵니다."},{"s":"southern_remnant:soi","t":"그 사람이 장군님 앞에 장부를 펴고 붉은 먹으로 한 줄을 그었사옵니다. 인장을 찍고는 도로 우물로 내려갔사옵니다."},{"s":"southern_remnant:soi","t":"오늘 새벽에는 정청 공문이 왔사옵니다. 장군님은 읽어 보시고는 아무 말 없이 화로에 넣으셨사옵니다."},{"s":"southern_remnant:galmae","t":"우물로 내려갔다고? 그럼 그놈, 할배한테 줄 긋고 도로 기어 내려가서 정리소에서 태연하게 우리를 기다린 거야?"},{"s":"north_league:yeo","t":"그랬을 거요. 관상대에서도 우물로 사라졌소. 우리가 고개 셋을 넘는 동안, 그자는 땅 밑 도랑으로 하룻밤 사이에 오간 거요."},{"s":"southern_remnant:galmae","t":"그래서 아무도 안 막았어? 할배는 그걸 보고만 있었고?"},{"s":"southern_remnant:jang","t":"서른 해 미뤄 둔 셈을 받으러 온 사람한테 칼을 들 수야 있나. 차는 한 잔 줬다. 다 마시고 가더구나."},{"s":null,"t":"갈매가 이를 악물었다. 악문 턱이 바들바들 떨렸다."},{"s":null,"t":"나는 갈매 곁에 무릎을 꿇고 그 어깨에 손을 얹었다. 갈매는 내 손을 뿌리치지 않았다."},{"s":"southern_remnant:jang","t":"정청 손님도 왔구먼. 이 꼴을 보이게 돼서 미안하네. 앉게.","fac_not":"southern_remnant","spec":2,"grp":1},{"s":"southern_remnant:jang","t":"우리 사람이 정청 패까지 차고 왔구먼. 남명 사람이 남명 사람 앞에서 이런 꼴을 보이다니. 앉게.","fac":"southern_remnant","spec":1,"grp":1},{"s":null,"t":"서하람이 화로 곁으로 한 걸음 다가섰다. 늘 흐리던 말끝이 이번에는 또렷했다."},{"s":"q:r71_seoharam","t":"장군님, 희수 서리님이 지금 정청 서고에서 장군님 줄을 찾고 있어요. 그 줄 끝에 칸을 그어서 장군님을 부를 사람 이름을 적으면… 묵창 나루에서처럼요. 그럼 안 될까요?"},{"s":"southern_remnant:jang","t":"묵창 나루 칸은 나루 사람들을 적은 나루 명부에 그은 칸이네. 거둘 이름을 적는 명부가 아니지. 내 줄은 정청의 정리 명부에 그어졌네. 그 명부에는 칸 자리부터 긁혀 있으니, 붓을 대도 먹이 앉지 않을 걸세. 칸을 돌려놓으려면 맹약을 풀어야 하네."},{"s":null,"t":"갈매가 품을 뒤져 접힌 종이 한 장을 꺼냈다. 관아 터에서 서하람에게 베껴 달라고 한 서식 사본이었다. 갈매는 그 종이를 노인의 무릎 위에 거칠게 펼쳤다."},{"s":"southern_remnant:galmae","t":"이거 봐, 할배. 관아 터에서 베껴 온 거야. 이 긁힌 칸. 서명은 정청이야. 할배한테 보여 주고 같이 따지러 가려고 들고 왔는데…"},{"s":null,"t":"장무현은 굳은살 박인 엄지로 긁힌 칸을 한 번 쓸었다. 노인은 종이를 반듯하게 접어 갈매의 품에 도로 넣어 주었다."},{"s":"southern_remnant:jang","t":"잘 베껴 왔다. 따지는 건 네가 해라. 나는 이걸 본 것으로 됐다."},{"s":"q:sn_cheongpa","t":"그럼 풀면 되잖아요! 장이 벌써 다섯이에요. 남은 건 둘뿐이고요!"},{"s":null,"t":"장무현의 눈길이 화로 속 흰 불씨에 잠깐 머물렀다. 노인은 아무 말 없이 부지깽이로 숯을 덮었다."},{"s":"southern_remnant:jang","t":"사흘 안에 할 일은 아니다. 그러니 너희는 울 시간에 장작이나 해 오너라. 오늘 밤 마을 사람들이 다 이 화로 곁에 몰려올 거다. 불이 모자라면 남명 체면이 안 선다."},{"s":"southern_remnant:galmae","t":"나 안 가. 여기 있을 거야."},{"s":"southern_remnant:jang","t":"갈매야. {이름}하고 가거라. 네 손이 놀고 있으면 내 속이 더 시끄럽다."},{"s":null,"t":"갈매는 한참 노인을 노려보다가 벌떡 일어섰다. 도끼를 집어 드는 손에 힘이 너무 들어가 있었다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":2,"title":"시간표","goal":"불씨 고개에서 5번 채집해 화로에 넣을 장작을 모은다","need":{"at":["ember_village"],"tasks":[{"t":"gather","n":5,"r":["ember_pass"]}]},"lines":[{"s":null,"t":"산비탈 솔숲에서 장작을 패는 동안 갈매는 한마디도 하지 않았다."},{"s":null,"t":"갈매는 마른 소나무를 찍을 때마다 도끼를 너무 깊이 박았다. 세 번째로 도끼날이 박혀 빠지지 않자, 나는 갈매의 손 위에 내 손을 겹쳐 함께 당겼다."},{"s":null,"t":"도끼날이 쑥 빠지며 우리 둘 다 뒤로 휘청했다. 갈매가 도끼 자루를 쥔 채 나를 보지 않고 입을 열었다."},{"s":"southern_remnant:galmae","t":"…고마워. 아무것도 안 물어봐서."},{"s":"southern_remnant:galmae","t":"재의 해안 뒤질 때도 너는 이랬어. 등대 배 찾는다고 해안을 몇 번이나 같이 돌았는데, 끝까지 아무것도 안 물었지."},{"s":null,"t":"장작을 지고 잔불촌에 돌아왔을 때는 이미 어두웠다. 화로 둘레에는 마을 사람들이 빙 둘러앉아 있었다. 아이들은 어른 무릎에 앉아 꾸벅꾸벅 졸았고, 노인들은 말없이 장무현을 바라보았다."},{"s":null,"t":"소이가 낮은 목소리로 옛 노래를 불렀다. 남명 말이 섞인 노래라 뜻은 다 알아듣지 못했다. 장작이 타닥타닥 튀는 소리가 노래 사이를 메웠다."},{"s":null,"t":"서하람은 화로 곁에 쪼그려 앉아 종이에 무언가를 적고 있었다. 칸을 나누고 이름을 쓰는 손이 빨랐다."},{"s":"red_moon_cult:danbi","t":"하람 씨, 그건 뭐예요?"},{"s":"q:r71_seoharam","t":"시간표요. 한 사람이 한 시진씩 장군님 이름을 불러요. 목이 쉬면 다음 사람한테 넘기고요. 그래야 밤새 끊기지 않아요."},{"s":"q:sn_cheongpa","t":"제가 제일 길게 할게요! 두 시진도 할 수 있어요!"},{"s":"red_moon_cult:danbi","t":"안 돼요. 청파는 숨이 짧잖아요. 반 시진만 해요. 그 대신 두 번 해요."},{"s":"q:sn_cheongpa","t":"반 시진이요? 그건 너무 짧잖아요, 누님!"},{"s":"north_league:yeo","t":"단비 말이 맞소. 반 시진씩 두 번이면 한 시진이오. 셈은 같소."},{"s":null,"t":"청파가 입을 비죽 내밀었다. 여운비는 그런 청파의 머리를 칼자루로 툭 건드리고 화로 반대편으로 걸어갔다."},{"s":null,"t":"여운비는 칼자루 끝의 붉은 술이 어느 쪽으로 날리는지 한참 보았다. 술은 산 쪽에서 마을 쪽으로 사르르 흔들렸다."},{"s":"north_league:yeo","t":"밤바람이 산에서 내려오오. 냄새를 맡고 내려오는 것들이 있을지 모르니, 나는 시간표 밖에서 마을 어귀를 지키겠소."},{"s":null,"t":"장무현이 시간표를 넘겨받아 불빛에 비춰 보았다. 노인의 눈썹이 꿈틀 올라갔다."},{"s":"southern_remnant:jang","t":"내 이름을 시간표에 적어 놓고 부르는 놈들은 처음 본다."},{"s":"q:r71_seoharam","t":"관측관은 다 적어 놔야 마음이 편해서요. 장군님 차례는 없어요. 장군님은 주무시기만 하면 돼요."},{"s":"southern_remnant:jang","t":"…허. 천명 아이가 남명 장군한테 자라고 명을 내리는구먼."},{"s":null,"t":"갈매가 시간표 맨 위 칸에 제 이름이 적힌 것을 보았다. 갈매는 종이를 서하람에게 돌려주지 않고 잠시 쥐고 있었다."},{"s":"q:r71_seoharam","t":"갈매 씨가 첫 차례예요. 관상대에서… 제일 크게 불러 준다고 했잖아요."},{"s":"southern_remnant:galmae","t":"…알아."},{"s":null,"t":"갈매는 서하람을 쳐다보지 않고 종이만 내밀었다. 서하람도 고개를 숙인 채 받았다. 관상대에서 엿을 반으로 나눠 먹은 뒤로도, 둘은 아직 서로의 얼굴을 똑바로 보지 못했다."},{"s":null,"t":"단비가 손뼉을 짝 쳐서 모두의 눈길을 모았다."},{"s":"red_moon_cult:danbi","t":"자, 다들 들었죠? 우리가 장 모으러 다니는 것도 결국 이름 하나라도 안 뺏기려고 하는 일이잖아요. 오늘 밤은 장 대신 장군님 이름을 지키는 거예요."},{"s":null,"t":"단비는 갈매 쪽으로 자리를 옮겨 앉고 성한 오른쪽 귀를 기울였다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":3,"title":"첫 밤이 지나고","goal":"잔불촌에서 한 시진씩 돌아가며 장군의 이름을 부르며 쉰다","need":{"at":["ember_village"],"tasks":[{"t":"rest","r":["ember_village"],"n":1}]},"lines":[{"s":null,"t":"첫 시진은 갈매가 맡았다. 갈매가 「장무현」 하고 부를 때마다 입김이 금빛 실로 맺혀 노인의 가슴께로 날아갔다."},{"s":null,"t":"금빛 실이 닿은 자리에서 그림자가 아주 조금 짙어졌다. 갈매는 그걸 보고 목소리를 더 높였다."},{"s":null,"t":"삼경에 내 차례가 왔다. 장무현은 자는 척 눈을 감고 있다가, 내가 세 번째로 이름을 부르자 한쪽 눈을 떴다."},{"s":"southern_remnant:jang","t":"자네가 정청 끄나풀이라 불린다지. 갈매가 그러더군.","fac_not":"southern_remnant","spec":2,"grp":1},{"s":"southern_remnant:jang","t":"자네는 남명 끈에 정청 패까지 찼으니, 갈매 입에서 끄나풀 소리가 두 배로 나오겠구먼.","fac":"southern_remnant","spec":1,"grp":1},{"s":null,"t":"나는 이제 갈매가 나를 이름으로 부른다고 했다."},{"s":"southern_remnant:jang","t":"그렇겠지. 그 아이는 한번 마음을 주면 끝까지 등을 내주네. 그러니 부탁하세. 그 아이 등을 좀 봐 주게. 내가 없으면 그 등이 비네."},{"s":"southern_remnant:jang","t":"자네한테 이런 부탁을 하는 데는 까닭이 있네. 자네가 주혈 광산에서 생 월철을 캐 왔던 날을 기억하네. 그 쇠로 구등대 쇠틀을 짰지. 군도 끝 도화가 지키던 세 불 가운데 남은 하나는 지금도 안 꺼졌네."},{"s":"southern_remnant:jang","t":"그때 광산 원령들이 「돌려 달라」 했지. 장부에 이름 한 줄 못 남긴 우리 백성들이었네. 자네는 그 소리를 끝까지 들어 준 사람이야."},{"s":null,"t":"나는 갈매가 먼저 내 등을 지켜 줄 거라고 했다. 장무현이 껄껄 웃다가 기침을 했다. 웃음소리가 화로 둘레를 넘어가지 못했다."},{"s":null,"t":"새벽이 오자 노인의 손끝이 잿빛으로 바래 있었다. 손톱 밑부터 빛이 빠진 손이 부지깽이를 쥐려다 미끄러졌다. 부지깽이가 땡그랑 소리를 내며 돌바닥에 떨어졌다."},{"s":null,"t":"청파가 얼른 부지깽이를 주워 드렸다. 장무현의 입이 움직였는데 아무 소리도 들리지 않았다."},{"s":"q:sn_cheongpa","t":"네? 장군님, 뭐라고 하셨어요? 잘 안 들려요!"},{"s":null,"t":"청파가 노인 곁으로 바짝 다가앉았다. 세 걸음 안으로 들어서자 그제야 목소리가 들렸다."},{"s":"southern_remnant:jang","t":"고맙다고 했다. 이놈아, 귀 좀 가까이 대라."},{"s":null,"t":"청파의 얼굴이 하얗게 질렸다. 청파는 그 자리에서 고개를 홱 돌려 여운비를 보았다."},{"s":"q:sn_cheongpa","t":"대장님, 장군님 목소리가 세 걸음 밖으로 안 나가요! 어젯밤엔 화로 건너편에서도 들렸는데!"},{"s":null,"t":"서하람이 노인의 잿빛 손끝을 들여다보며 입술을 깨물었다."},{"s":"q:r71_seoharam","t":"둘째 날이에요. 손끝이 바래고 목소리가 줄어든다고… 관아 터에서 제가 베껴 둔 백 년 전 서식 뒷장에 그렇게 적혀 있었어요."},{"s":null,"t":"마을 어귀를 지키던 여운비가 어느새 화로 곁에 와 서 있었다."},{"s":"north_league:yeo","t":"그렇다면 다들 세 걸음 안으로 모이시오. 장군이 하는 말은 하나도 흘리지 맙시다."},{"s":null,"t":"단비는 화로 곁에 앉은 채 밤새 쥐고 있던 방울을 내려다보았다. 이름을 값으로 치른 뒤로는 그 방울을 흔들어도 축문이 들리지 않았다."},{"s":"red_moon_cult:danbi","t":"제가 아직 무녀였으면 뭐라도 해 드렸을 텐데요. 이제는 이름 부르는 것밖에 못 하네요."},{"s":"southern_remnant:jang","t":"그게 제일 큰 거다, 아가. 남명 임금도 그것밖에 안 했다."},{"s":null,"t":"장무현은 잿빛 손으로 무릎을 짚고 일어섰다. 갈매가 붙잡으려 하자 노인이 손을 들어 막았다."},{"s":"southern_remnant:jang","t":"오늘 아침은 내가 국수를 끓이마. 남명에서는 먼 길 가는 사람에게 국수를 먹인다. 길게 가라고."},{"s":"q:sn_cheongpa","t":"먼 길이요? 누가 먼 길 가는데요?"},{"s":"southern_remnant:jang","t":"너희지, 이놈아. 맹약 마당까지 가야 할 것 아니냐. 가서 메밀이랑 들나물을 뜯어 오너라. 남명 국수는 메밀이 반이다."},{"s":null,"t":"갈매가 무어라 말하려다 입을 다물었다. 노인이 정말로 누구의 먼 길을 말하는지, 갈매도 알고 있었다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":4,"title":"남명 국수","goal":"불씨 고개에서 4번 채집해 국수에 넣을 메밀과 들나물을 모은다","need":{"at":["ember_village"],"tasks":[{"t":"gather","n":4,"r":["ember_pass"]}]},"lines":[{"s":null,"t":"메밀과 들나물을 한 바구니 가득 뜯어 오자 장무현이 화로 곁에 큰 솥을 걸어 두고 있었다. 마을 아낙 둘이 솥에 물을 붓고 있었다."},{"s":null,"t":"한 팔뿐인 장무현이 반죽을 치대기는 어려웠다. 노인이 갈매에게 턱짓하자 갈매가 소매를 걷고 반죽 앞에 앉았다."},{"s":"southern_remnant:jang","t":"손목으로 치대지 말고 손바닥으로 밀어라. 그래야 면발이 안 끊긴다."},{"s":"southern_remnant:galmae","t":"알아. 어릴 때부터 맨날 했잖아."},{"s":"southern_remnant:jang","t":"맨날 끊어 먹었지."},{"s":null,"t":"갈매가 반죽을 퍽퍽 내리치자 메밀가루가 풀썩 날렸다. 맞은편의 서하람이 하얗게 가루를 뒤집어쓰고 재채기를 했다."},{"s":null,"t":"갈매가 그걸 보고 손을 멈췄다. 사과하려는 듯 입술이 달싹였지만, 갈매는 끝내 아무 말도 하지 않고 반죽만 더 세게 밀었다."},{"s":null,"t":"나는 장무현 곁에서 칼을 들고 반죽을 썰었다. 노인이 잿빛 손가락으로 칼 대는 자리를 하나하나 짚어 주었다."},{"s":"southern_remnant:jang","t":"굵게. 더 굵게. 남명 국수는 씹히는 맛이다. 정청 사람이 썬 국수는 실 같아서 못 먹겠더라."},{"s":null,"t":"청파는 솥 밑 불을 맡았다. 장작을 너무 많이 넣어 솥이 부글부글 끓어 넘쳤고, 청파가 「앗 뜨거!」 하며 펄쩍 뛰었다."},{"s":"north_league:yeo","t":"불은 줄이시오. 끓어 넘치면 국물이 다 날아가오."},{"s":"q:sn_cheongpa","t":"대장님이 하시면 되잖아요!"},{"s":"north_league:yeo","t":"나는 칼을 지키는 사람이지 솥을 지키는 사람이 아니오."},{"s":null,"t":"단비가 솥 곁으로 살금살금 다가갔다. 품에서 엿을 꺼내 국물에 넣으려는 손을 소이가 탁 잡았다."},{"s":"southern_remnant:soi","t":"아니 되옵니다. 남명 국수에 엿을 넣는 법은 예부터 없사옵니다."},{"s":"red_moon_cult:danbi","t":"예부터 없었으면 오늘부터 생기면 되죠."},{"s":null,"t":"장무현이 소리 없이 웃었다. 세 걸음 안에 앉은 우리만 노인의 어깨가 들썩이는 것을 보았다."},{"s":null,"t":"국수가 그릇마다 담겼다. 굵은 메밀 면 위에 들나물이 얹혔고, 국물에서 고소한 냄새가 모락모락 피어올랐다."},{"s":null,"t":"우리는 화로를 둘러싸고 후루룩후루룩 국수를 먹었다. 장무현은 제 그릇에 손을 대지 않고 우리가 먹는 것만 보았다."},{"s":"north_league:yeo","t":"…나쁘지 않소."},{"s":"southern_remnant:jang","t":"북령 대장의 그 말이 최고 칭찬이라고 들었네. 남명 국수가 북령 대장을 이겼구먼."},{"s":null,"t":"서하람은 반쯤 먹다가 그릇을 든 채 고개를 꾸벅 떨어뜨렸다. 서하람은 밤새 두 차례나 이름을 부른 터였다. 갈매가 그릇이 엎어지기 전에 받쳐 들었다."},{"s":null,"t":"갈매는 서하람의 그릇을 땅에 내려놓고 제 겉옷을 벗어 서하람의 어깨에 덮었다. 서하람이 눈을 뜨기 전에, 갈매는 얼른 고개를 돌렸다."},{"s":null,"t":"그때 마을 어귀에서 정청 패를 찬 심부름꾼이 비틀비틀 뛰어왔다. 심부름꾼은 화로 앞에 이르자 헉헉 숨을 몰아쉬며 서신을 내밀었다."},{"s":"q:md_runner","t":"감찰관님 서신입니다! 밤새 달려왔습니다. 조사원께 꼭 직접 드리라 하셨습니다."},{"s":null,"t":"내가 서신을 받아 펼쳤다. 단비가 내 어깨 너머로 고개를 들이밀었다."},{"s":"night_office:han","t":"「조사원. 정리관은 너희가 떠난 그날 먹 도랑으로 내려가 아직 정리소에 올라오지 않았다. 그 도랑은 고을마다 우물 밑으로 뻗어 있다. 희수 서리가 서고에서 장군의 줄을 찾아 칸을 그으려 했지만, 칸 자리가 긁혀 있어 먹이 앉지 않는다. 판관 회의는 여전히 열리지 않는다. 장군의 마지막 날에 그 사람이 다시 나타날 거다. 칼은 아껴 두고, 장군 곁을 비우지 마라. 나는 정청에 남아 정리소 문을 지키겠다. 그 사람이 올라오면 내가 먼저 안다. — 한설」"},{"s":null,"t":"갈매의 젓가락이 그릇 위에서 딱 멈췄다. 그때 마을 뒤 산비탈에서 아이 하나가 소리를 지르며 뛰어 내려왔다."},{"s":"q:md_child","t":"먹 낀 것들이 내려와요! 산 밭에 까만 게 우글우글해요!"},{"s":"southern_remnant:soi","t":"장군님 이름이 바래는 냄새를 맡은 것이옵니다. 거둬지는 사람 곁에는 늘 저것들이 꼬이옵니다."},{"s":"southern_remnant:jang","t":"갈매야, 가거라. 마을이 먼저다. 내 곁은 아가들이 지킬 거다."},{"s":null,"t":"갈매가 칼을 뽑아 들고 일어섰다. 나도 그 뒤를 따라 일어섰다. 여운비가 말없이 우리 앞에 섰고, 청파와 단비와 서하람은 장무현 곁으로 바짝 다가앉았다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":5,"title":"마지막 아이","goal":"불씨 고개에서 마을로 내려오는 재 덮인 궁녀 넋을 4번 풀어 보낸다","need":{"at":["ember_village"],"tasks":[{"t":"win","n":4,"m":["dd_palace_1"],"r":["ember_pass"]}]},"lines":[{"s":null,"t":"산비탈의 먹 낀 것들은 갈매가 맨 먼저 베어 넘겼다. 갈매는 한 번도 물러서지 않았다. 칼날이 휘익휘익 공기를 가를 때마다 시커먼 것이 철퍽 쓰러졌다."},{"s":null,"t":"쓰러진 것들은 재를 뒤집어쓴 궁녀의 넋이었는데, 먹물로 풀리면서 마을 뒤 우물 쪽으로 흘러갔다."},{"s":null,"t":"마지막 하나가 갈매의 등 뒤에서 솟구쳤다. 내가 그것을 막아 내자 갈매가 뒤돌아보았다. 갈매는 숨을 헐떡이며 내 어깨를 툭 쳤다."},{"s":"southern_remnant:galmae","t":"할배한테 들었어. 내 등 봐 달라고 했다며. 쓸데없는 소리를."},{"s":null,"t":"갈매는 그렇게 말하고 내 등 뒤로 돌아가 섰다. 남은 길을 내려오는 동안 갈매는 줄곧 내 뒤를 지켰다."},{"s":null,"t":"둘째 밤의 화로는 첫째 밤보다 조용했다. 마을 사람들은 시간표대로 돌아가며 장무현의 이름을 부르다가 하나둘 집으로 돌아갔다."},{"s":null,"t":"장무현의 잿빛은 손목까지 올라와 있었다. 노인은 우리를 화로 둘레로 불러 앉혔다. 갈매는 노인의 바로 곁에 앉아 노인의 소매 끝을 쥐었다."},{"s":"southern_remnant:jang","t":"갈매야. 잔불촌에서 너를 「마지막 아이」라고 처음 부른 게 나였지. 그 말을 할 때마다 네가 화를 냈다."},{"s":"southern_remnant:galmae","t":"…그 얘기 하지 마."},{"s":"southern_remnant:jang","t":"해야 한다. 내가 안 하면 아무도 안 한다. 서른 해 전 동지에, 정리 명부 맨 앞줄에 네 이름이 있었다. 부모가 둘 다 거둬진 갓난아이였지."},{"s":null,"t":"청파가 숨을 헙 들이켰다. 단비가 청파의 손등을 꽉 눌렀다."},{"s":"southern_remnant:jang","t":"남명 아이가 맨 앞줄에 오르는 건 새삼스러운 일이 아니었다. 나는 그 명부를 들고 정청에 갔다. 그리고 빌었다. 그 아이 자리에 내 이름을 대신 올려 달라고."},{"s":"southern_remnant:jang","t":"정청은 받았다. 장군 이름 하나가 아이 열보다 낫다더구나. 그때 정리소 서리가 내 이름을 맨 앞에 두되 줄은 미뤄 두었다. 남명 장군을 거두면 남명 사람들이 일어날 테니까."},{"s":"southern_remnant:jang","t":"그 뒤로 서른 해 동안 남명 아이는 명부에 한 번도 오르지 않았다. 내 이름이 맨 앞줄에 볼모처럼 서 있었으니까. 네가 마지막이었다, 갈매야. 그래서 마지막 아이다."},{"s":null,"t":"갈매의 손이 노인의 소매를 더 세게 움켜쥐었다. 갈매의 목소리가 갈라졌다."},{"s":"southern_remnant:galmae","t":"알았어. 다들 쉬쉬했지만 다 알았어. 그 말 들을 때마다… 할배가 언젠가 나 대신 없어질 거라는 소리로 들렸단 말이야!"},{"s":"southern_remnant:galmae","t":"마지막 아이라는 건, 누가 대신 죽어서 살아남은 아이라는 뜻이잖아. 그 말 듣기 싫어서 화낸 거야. 할배를 미워해서가 아니라!"},{"s":null,"t":"장무현은 남은 한 팔로 갈매의 머리를 끌어당겼다. 노인의 잿빛 손이 갈매의 머리칼 위에서 천천히 움직였다."},{"s":"southern_remnant:jang","t":"안다. 그래서 그 말을 고치려고 했다. 마지막 아이는 남명이 마지막으로 지켜 낸 아이라는 뜻이다. 대신 죽은 게 아니다. 내가 고른 거다."},{"s":null,"t":"갈매가 노인의 소매에 이마를 묻었다. 어깨가 들썩였다. 이번에는 아무도 울지 말라고 하지 않았다."},{"s":null,"t":"청파가 무릎을 끌어안고 훌쩍였다. 청파는 코를 한 번 크게 들이마시고 갈매 쪽으로 고개를 들었다."},{"s":"q:sn_cheongpa","t":"누님, 제가 그동안 꼬맹이라고 놀린 거… 다 취소할게요. 다시는 안 할게요."},{"s":"southern_remnant:galmae","t":"…시끄러, 꼬맹이."},{"s":null,"t":"갈매가 소매에 얼굴을 묻은 채 웅얼거렸다. 청파가 울다 말고 피식 웃었다."},{"s":null,"t":"여운비는 화로 건너편에서 눈을 감고 있었다. 감은 눈가가 불빛에 젖어 반짝였다."},{"s":null,"t":"단비가 화로 위로 몸을 기울여 서하람을 보았다. 서하람은 무릎 위에서 두 손을 꽉 맞쥐고 있었다. 손가락 마디가 하얬다."},{"s":"q:r71_seoharam","t":"…갈매 씨. 장군님 줄도… 결국 천명원이 잘못 읽은 그 별에서…"},{"s":null,"t":"서하람은 말을 끝까지 잇지 못했다. 갈매는 대답하지 않았지만, 노인의 소매를 쥔 반대쪽 손을, 서하람이 앉은 쪽 바닥에 내려놓았다."},{"s":"southern_remnant:jang","t":"자, 그만 울고 부르거라. 오늘 밤만 넘기면 하루를 번다. 너희가 어젯밤 부른 덕에 줄이 더디 먹고 있다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":6,"title":"화로 속의 장","goal":"잔불촌에서 모두 둘러앉아 이름을 부르며 둘째 밤을 쉰다","need":{"at":["ember_village"],"tasks":[{"t":"rest","r":["ember_village"],"n":1}]},"lines":[{"s":null,"t":"셋째 날 새벽이 밝았다. 원래라면 장무현이 먹으로 풀렸을 새벽이었지만, 노인은 화로 앞에 그대로 앉아 있었다."},{"s":null,"t":"잿빛은 팔꿈치까지 올라와 있었지만 더 올라가지 않았다. 화로 둘레에는 밤새 이름을 부르다 쓰러져 잠든 마을 사람들이 여기저기 누워 있었다."},{"s":"q:r71_seoharam","t":"하루를 벌었어요. 금빛 실이 닿은 수를 세어 봤는데, 어젯밤이 그젯밤보다 두 배 많았어요."},{"s":"southern_remnant:jang","t":"그 하루는 길에 쓰겠다. 들어 보거라."},{"s":null,"t":"장무현이 일어섰지만, 다리가 후들후들 떨렸다. 갈매와 청파가 양쪽에서 노인을 부축했다."},{"s":"southern_remnant:jang","t":"남명이 지켜 온 장은 이 화로 안에 있다. 백 년 전 임금께서 서명하지 않으신 자리, 「부를 이 없는 이름은 임금이 부른다」는 구절이 적힌 장이지."},{"s":"q:sn_cheongpa","t":"화로 속에요? 남명 장이 남명에 있다는 건 알았지만, 불 속에 있는 줄은 몰랐어요! 처음 잔불촌에 왔을 때 장군님은 반납할 것도 없다고 하셨잖아요!"},{"s":"southern_remnant:jang","t":"그땐 너희가 정청 일을 하는지, 남명 일을 하는지 몰랐다. 이 불이 꺼지지 않는 동안 장도 타지 않는다. 대신 장을 꺼내려면 누군가 불 속에 손을 넣어야 한다."},{"s":null,"t":"갈매가 소매를 걷어붙이며 화로 앞으로 나섰다. 장무현이 남은 한 팔로 갈매를 밀어냈다. 잿빛으로 바랜 팔이었는데도 힘이 남아 있었다."},{"s":"southern_remnant:jang","t":"이건 내 몫이다. 어차피 내일 아침이면 없어질 손이다."},{"s":"southern_remnant:galmae","t":"할배, 하지 마! 하지 말라고!"},{"s":null,"t":"장무현은 맨손을 흰 불씨 아래로 쑥 밀어 넣었다. 지글지글, 숯이 노인의 손등을 태우는 소리가 났다."},{"s":"red_moon_cult:danbi","t":"장군님! 물! 누가 물 좀 가져와요!"},{"s":"q:r71_seoharam","t":"손등이… 손등이 타고 있어요! 장군님, 빼세요! 빼시라고요!"},{"s":null,"t":"나는 화로 곁에 무릎을 꿇고 노인의 팔꿈치를 받쳐 들었다. 잿빛 팔이 내 손바닥 위에서 바들바들 떨렸다."},{"s":null,"t":"청파가 물동이를 들고 달려왔다. 갈매가 화로 쪽으로 몸을 던지려 하자, 여운비가 뒤에서 갈매의 허리를 끌어안았다."},{"s":"north_league:yeo","t":"놓아 드리시오! 장군이 고르신 일이오!"},{"s":null,"t":"장무현의 얼굴은 한 번도 찡그려지지 않았다. 손을 빼냈을 때, 그 손에 두꺼운 닥종이 한 장이 들려 있었다."},{"s":null,"t":"종이는 불 속에 있었는데도 그을린 데가 없었다. 그 위에 손바닥만 한 흰 불꽃이 하늘하늘 떠 있었다."},{"s":null,"t":"장 아래쪽에는 오래된 글씨 몇 줄이 더 적혀 있었다. 「내 백성은 내가 부른다. 숫자로 내주지 않는다.」 서명 자리는 정청의 먹으로 시커멓게 지워져 있었다."},{"s":null,"t":"청파가 노인의 손에 물을 쏴아 끼얹었다. 손등이 벌겋게 부풀어 있었다. 장무현은 그 손으로 장을 갈매의 손에 쥐여 주고, 갈매의 손을 오래 감싸 쥐었다."},{"s":"southern_remnant:jang","t":"이걸 들고 잿빛 왕궁 터로 가거라. 임금께서 앉으시던 자리에서 이어야 남명의 장이 남명의 장답다."},{"s":"southern_remnant:jang","t":"그리고 나도 데려가 다오. 마지막 날은 그 자리에서 맞고 싶구나."},{"s":null,"t":"갈매는 장을 쥔 채 아무 말도 하지 못했다. 내가 갈매 대신 고개를 끄덕였다. 서하람이 손가락을 꼽으며 길을 셈했다."},{"s":"q:r71_seoharam","t":"왕궁 터는 등도 동쪽 끝이에요. 봉인고 옛 수로를 지나야 하고요. 장군님은 걸어서 못 가세요. 들것이 있어야 해요."},{"s":"southern_remnant:soi","t":"마을 사람들이 길목마다 들소를 바꿔 매어 드릴 것이옵니다. 남명 땅을 벗어날 때까지는 쉬지 않고 달리실 수 있사옵니다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":7,"title":"임금의 자리","goal":"들것 1개를 만들어 장군을 모시고 잿빛 왕궁 터에 도착한다","need":{"at":["ash_palace"],"tasks":[{"t":"craft","items":["md_litter"],"n":1},{"t":"travel","r":["ash_palace"],"n":1}],"give":{"md_litter":1}},"lines":[{"s":null,"t":"우리는 하루 밤낮을 쉬지 않고 달렸다. 들것은 들소 달구지에 실었고, 남명 길목마다 마을 사람들이 새 들소를 바꿔 매어 놓고 기다렸다. 들소 방울이 딸랑딸랑 울릴 때마다 사람들이 길가에 나와 장무현의 이름을 불렀다."},{"s":null,"t":"봉인고 아래 옛 수로에서는 청파가 노를 저었다. 청파는 숨이 차면 노를 멈추고 쌕쌕 숨을 골랐다. 단비가 그 곁에 앉아 청파가 멈출 때마다 대신 「장무현」을 불렀다."},{"s":null,"t":"수로를 벗어난 뒤로는 달구지가 들어갈 수 없어, 들것 앞쪽은 여운비가, 뒤쪽은 내가 들었다. 갈매는 들것 곁을 걸으며 노인의 손을 놓지 않았다."},{"s":null,"t":"서하람이 들것 곁을 따라 걸으며 노인의 팔을 들여다보았다. 원래라면 장무현이 먹으로 풀렸을 아침이 지나 있었다."},{"s":"q:r71_seoharam","t":"잿빛이 하룻밤 사이 한 뼘도 안 올라왔어요. 길가에서 마을 사람들이 불러 준 덕에 하루를 더 번 거예요. 그래도… 내일 새벽이 마지막이에요."},{"s":null,"t":"잿빛 왕궁 터는 등도 동쪽 끝에 있었다. 무너진 궁궐 기둥들이 하얗게 바래 서 있었다. 그 한가운데 돌 단 위에 빈 옥좌 하나가 놓여 있었다."},{"s":null,"t":"옥좌 앞 돌바닥에 둥근 자국 하나가 남아 있었다. 등잔을 오래 올려 두었던 자리였다. 소이가 그 자국 앞에서 절을 올렸다."},{"s":"southern_remnant:soi","t":"임금님의 등이 놓였던 자리이옵니다. 소등 밤에 명등지기 몇 사람이 이 마지막 등을 들고 남쪽으로 빠져나왔사옵니다. 그 불씨가 잔불촌 화로가 되었사옵니다."},{"s":"southern_remnant:soi","t":"나머지 명등지기들은 수로를 따라 빠져나갔다고 들었사옵니다. 여든 남짓이었다 하옵니다. 그 뒤로 그분들 소식은 남명까지 오지 않았사옵니다."},{"s":null,"t":"우리는 장무현을 옥좌 앞 돌바닥에 눕혔다. 노인의 얼굴은 이마까지 잿빛이었다. 목소리는 이제 한 걸음 밖에서도 들리지 않아, 갈매가 노인의 입가에 귀를 댔다."},{"s":"southern_remnant:galmae","t":"…할배가 네가 이으래. {이름}, 네가."},{"s":"southern_remnant:galmae","t":"정청 사람이 우리 임금 자리에서 우리 장을 잇는 거, 할배가 꼭 보고 싶대. 서명 자리를 지운 게 정청이니까, 이번엔 정청 사람이 이어야 한대.","fac_not":"southern_remnant","spec":2,"grp":1},{"s":"southern_remnant:galmae","t":"남명 끈을 찬 정청 사람이니까. 우리 임금 자리에서 우리 장을 잇기에는 너밖에 없대.","fac":"southern_remnant","spec":1,"grp":1},{"s":null,"t":"갈매가 옥좌 앞에 무릎을 꿇고 다섯째 장을 펼쳤다. 장 끝줄에 「이을 이」 칸이 비어 있었다."},{"s":null,"t":"내가 그 칸에 이름을 적자 흰 불꽃이 금빛으로 확 피어올랐다. 품속의 다섯 장과 새 장 사이로 금빛 실이 이어졌다."},{"s":null,"t":"여섯 장이 옥좌 앞에서 한 번 크게 빛났다. 그 빛에 장무현의 잿빛 얼굴이 아주 잠깐 제 빛으로 물들었다."},{"s":"q:sn_cheongpa","t":"여섯이에요. 이제 하나 남았어요. 흑련 장 하나만요."},{"s":"red_moon_cult:danbi","t":"흑련 장은 정리소 금고에 있잖아요. 정리관이 가지고 있는 거요."},{"s":"north_league:yeo","t":"그러니 더 서둘러야 하오. 장을 다 이어 마당에서 진을 풀어야, 장군 같은 사람이 다시는 명부 맨 앞에 서지 않소. 우리가 같이 다니는 까닭이 그거 하나요."},{"s":null,"t":"갈매는 노인의 입가에 귀를 대고 있다가 고개를 들었는데, 그 눈이 젖어 있었다."},{"s":"southern_remnant:galmae","t":"할배가 그러는데, 그 말 처음으로 북령 사람 입에서 듣는다고. 북령은 맨날 「다시는」 소리만 하는 줄 알았대."},{"s":null,"t":"여운비가 고개를 숙였다. 칼자루 끝 붉은 술을 쥔 손에 힘이 들어가 손등이 하얘졌다."},{"s":"north_league:yeo","t":"…가장 먼저 서명한 집이 북령이오. 장군께 그 말을 드릴 낯이 내게는 없었소."},{"s":null,"t":"그때 왕궁 터 기둥 사이로 하얀 것들이 스르르 어른거렸다. 서하람이 갈매의 소매를 잡아당겼다."},{"s":"q:r71_seoharam","t":"흰 밤에 걸린 이름들이에요. 장군님 이름이 바래는 냄새를 맡고 몰려와요."},{"s":"north_league:yeo","t":"마지막 밤까지 저것들이 장군 곁에 못 오게 합시다. 갈매는 장군 곁에. 나머지는 나와 함께 기둥 사이를 치시오."},{"s":"southern_remnant:galmae","t":"…나도 갈게. 할배가 가래. 내 등 봐 줄 사람이 있으니까 괜찮대."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":8,"title":"동틀 녘","goal":"잿빛 왕궁 터를 맴도는 요괴를 3번 쓰러뜨리고 잿빛 왕궁 터에서 마지막 밤을 쉰다","need":{"at":["ash_palace"],"tasks":[{"t":"win","n":3,"m":["dd_palace_1","dd_palace_2"]},{"t":"rest","r":["ash_palace"],"n":1}]},"lines":[{"s":null,"t":"마지막 밤은 길었다. 우리는 장무현을 둘러싸고 앉아 한 사람씩 이름을 불렀다. 금빛 실이 수없이 노인의 가슴께로 날아갔다."},{"s":null,"t":"새벽이 가까워지자 갈매의 목소리가 쉬어 갈라졌다. 갈매는 쉰 목소리로 부르고 또 불렀다. 서하람이 그 곁으로 다가가 갈매의 손을 잡았다."},{"s":"q:r71_seoharam","t":"같이 불러요. 한 목소리보다 둘이 굵어요. 제가 봤어요."},{"s":null,"t":"갈매는 서하람의 손을 뿌리치지 않았다. 관상대 일 뒤로 처음이었다. 두 사람이 한 이름을 함께 부르자 금빛 실이 한 가닥으로 꼬여 굵게 날아갔다."},{"s":null,"t":"동틀 녘이 다가올 무렵 왕궁 터 끝에서 발소리가 났다. 경현이 혼자 걸어오고 있었다. 정리소 사람들도, 등불도 없이 장부 한 권만 들고 있었다."},{"s":null,"t":"갈매가 칼을 뽑으며 튀어 나갔다. 내가 갈매의 팔목을 덥석 잡았다. 갈매의 칼끝이 부르르 떨렸다."},{"s":"southern_remnant:galmae","t":"놔! 저 새끼가 할배를…!"},{"s":null,"t":"장무현이 몸을 일으키려 했다. 단비와 청파가 말렸지만 노인은 갈매의 어깨를 짚고 기어이 일어섰다."},{"s":null,"t":"노인의 발끝은 이미 먹빛으로 젖어 있었다. 걸음마다 돌바닥에 검은 발자국이 찍혔다. 노인은 우리와 경현 사이에 섰다."},{"s":null,"t":"장무현의 입이 움직였다. 세 걸음 안에 선 갈매만 그 말을 들었다."},{"s":"southern_remnant:galmae","t":"…「칼 거둬라. 손님이다.」"},{"s":null,"t":"갈매가 이를 악물고 칼을 내렸다. 내가 잡은 팔목에서 힘이 스르르 빠졌다."},{"s":"q:md_gyeonghyeon","t":"서른 해를 미뤄 드렸소, 장군. 그사이에 남명 아이 하나가 자라 정찰대장이 되었더구려."},{"s":"red_moon_cult:danbi","t":"미뤄 줬다고 생색내시는 거예요? 그 서른 해 동안 장군님 이름을 볼모로 잡고 계셨잖아요!"},{"s":"q:md_gyeonghyeon","t":"그렇소, 무녀. 볼모였소. 장군 이름을 맨 앞줄에 묶어 둔 서른 해 동안, 남명 아이는 하나도 정리 명부에 오르지 않았소. 남명이 칼을 들지 않았으니 셈으로도 남는 장사였지."},{"s":"q:sn_cheongpa","t":"그럼 왜 지금이에요? 왜 하필 지금이냐고요!"},{"s":"q:md_gyeonghyeon","t":"올해 저울이 삼백십이를 가리켰소. 홍인사 해에 거두지 못한 몫까지요. 미뤄 둘 자리가 더는 없었소."},{"s":"southern_remnant:galmae","t":"누가 시켰어? 정청 어느 놈이 너한테 시켰냐고!"},{"s":"q:md_gyeonghyeon","t":"시킨 사람은 없소. 그 저울은 백 년 전 내가 만들었고, 오늘 이 줄도 내가 그었소. 원망할 곳을 찾는다면 나 하나로 충분하오."},{"s":null,"t":"경현의 옷자락 끝에서 먹물이 똑똑 떨어졌다. 왕궁 터 한쪽 마른 우물가에서 경현의 발치까지 젖은 먹 발자국이 이어져 있었다."},{"s":null,"t":"경현이 장부를 펼치고 붓을 꺼냈다. 그때 장무현의 입이 다시 움직였다. 갈매가 노인의 입가에 귀를 댔다."},{"s":"southern_remnant:galmae","t":"…「장은 이 아이들이 가져간다. 자네는 나만 데려가게.」"},{"s":null,"t":"경현은 모서리를 접으려던 손을 멈추고 장부를 그대로 덮었다."},{"s":"q:md_gyeonghyeon","t":"다섯째 장은 가져가시오. 맹약 마당에서 한꺼번에 받겠소. 오늘 내가 받으러 온 것은 장군 한 사람뿐이오."},{"s":null,"t":"흰 하늘이 조금 더 하얘졌다. 등도에서는 그것이 동틀 녘이었다. 장무현의 몸이 발끝부터 천천히 먹물로 풀려 돌바닥에 스며들기 시작했다."},{"s":"southern_remnant:galmae","t":"장무현! 할배! 장무현!"},{"s":null,"t":"우리 모두가 노인의 이름을 불렀다. 단비가 울면서 불렀고, 청파가 기침을 하면서 불렀다. 여운비가 칼을 내려놓고 불렀고, 서하람이 갈매의 손을 쥔 채 불렀다."},{"s":null,"t":"금빛 실이 수없이 노인의 가슴께에 닿았지만, 붉은 줄은 지워지지 않았다. 먹빛이 무릎을 지나 허리로 올라왔다."},{"s":null,"t":"장무현이 마지막으로 갈매를 돌아보았다. 입 모양만 남은 말을 갈매가 귀를 대고 들었다. 갈매는 그 말을 우리에게 옮겨 주었다. 목소리가 덜덜 떨렸다."},{"s":"southern_remnant:galmae","t":"…「화로 불은 꺼뜨리지 마라. 그리고 나를 잊지 마라. 원망하라는 게 아니라, 있었다는 것만.」"},{"s":null,"t":"털썩, 노인이 서 있던 자리에 낡은 가죽 신 한 켤레와 빈 소매가 달린 옷 한 벌이 내려앉았다."},{"s":null,"t":"갈매가 그 옷을 끌어안고 엎드렸다. 짐승이 우는 것 같은 소리가 갈매의 목에서 터져 나왔다."},{"s":null,"t":"청파는 그 자리에 주저앉아 엉엉 울었다. 단비가 오른팔로 청파를 끌어안았다. 단비의 뺨에도 눈물이 줄줄 흘렀다."},{"s":null,"t":"여운비는 내려놓은 칼 앞에 꼿꼿이 서 있었다. 오른손이 칼자루 끝의 붉은 술을 꽉 움켜쥐고 있었다. 눈물이 턱 끝에서 똑똑 떨어졌다."},{"s":null,"t":"서하람은 갈매 곁에 무릎을 꿇고 갈매의 등에 이마를 댔다. 아무 말도 하지 않았다."},{"s":null,"t":"나는 가죽 신을 주워 품에 안았다. 아직 미지근했다."},{"s":null,"t":"경현은 그 모습을 끝까지 지켜보다가, 돌아서려던 참에 나를 보았다."},{"s":"q:md_gyeonghyeon","t":"당신은 오늘 이름 하나를 부르다 놓쳤소. 나는 백 년을 그렇게 살았소. 익숙해지지는 않더구려."},{"s":null,"t":"나는 그 이름을 놓치지 않았다고 했다. 갈매가 기억하는 한, 우리가 부르는 한, 그 이름은 여기 있다고 했다."},{"s":null,"t":"경현은 한참 나를 바라보았다. 장부를 쥔 손가락이 모서리를 찾다가 멈췄다. 경현이 고개를 숙였다. 그 목소리에는 처음으로 비꼬는 기색이 없었다."},{"s":"q:md_gyeonghyeon","t":"…미안하오."},{"s":"southern_remnant:galmae","t":"꺼져. 그 말 할배한테 했어야지. 꺼져!"},{"s":null,"t":"경현은 대꾸하지 않고 돌아섰다. 흰 하늘 아래로 그 등이 천천히 멀어졌다."}],"reward":{"xp":2247}},{"quest_id":"mdq_14","step":9,"title":"화로 곁","goal":"장군의 옷과 신을 모시고 잔불촌에 도착해 장군을 부르며 쉰다","need":{"at":["ember_village"],"tasks":[{"t":"travel","r":["ember_village"],"n":1},{"t":"rest","r":["ember_village"],"n":1}]},"lines":[{"s":null,"t":"잔불촌 사람들은 장무현의 옷을 화로 곁 걸상에 걸었다. 그 아래에 내가 가죽 신을 가지런히 놓았다. 사람들이 밤새 노인의 이름을 불렀다."},{"s":null,"t":"소이가 처음 듣는 노래를 불렀다. 노래가 끝날 때마다 마을 사람들이 「장무현」 하고 한목소리로 이름을 받았다."},{"s":null,"t":"갈매는 화로 앞 노인의 걸상에 앉아 부지깽이로 숯을 골랐다. 노인이 하던 그 손길이었다."},{"s":null,"t":"서하람이 갈매 곁에 앉았다. 서하람은 품에서 엿 하나를 꺼내 갈매 앞 돌 위에 놓았다. 그 엿은 단비가 나눠 준 엿 가운데 서하람이 아껴 둔 마지막 하나였다."},{"s":"q:r71_seoharam","t":"…예언은 안 하는데요. 관측한 걸 말할게요. 어젯밤 갈매 씨가 장군님 이름을 부를 때, 금빛이 제일 굵었어요."},{"s":"q:r71_seoharam","t":"그리고 하나 더요. 천명원이 별을 잘못 읽은 건 맞아요. 그건 제가 다 갚을 수 없어요. 그래도 갈매 씨 옆에서 같이 갚을게요."},{"s":null,"t":"갈매는 엿을 내려다보다가 집어 입에 넣었다. 오도독 깨무는 소리가 났다. 갈매는 부지깽이를 화로에 걸쳐 두고 서하람의 어깨에 머리를 기댔다."},{"s":null,"t":"서하람이 놀라 몸을 굳혔다가, 곧 갈매가 기대기 편하도록 어깨를 조금 낮추었다."},{"s":"southern_remnant:galmae","t":"…천명원이 별을 잘못 읽은 건 네 잘못이 아니야. 할배라면 그렇게 말했을 거야. 할배는 천명 사람이 마을에 오면 늘 국수부터 먹였어."},{"s":null,"t":"화로 건너편에서 그걸 본 청파가 단비의 소매를 잡아당겼다. 단비가 오른쪽 귀를 청파 쪽으로 기울였다."},{"s":"q:sn_cheongpa","t":"누님, 저 둘 화해한 거죠? 그렇죠?"},{"s":"red_moon_cult:danbi","t":"쉿. 크게 말하면 갈매 씨가 도로 머리를 뗄 거예요."},{"s":null,"t":"여운비는 마을 어귀 쪽 돌담에 기대어 서 있었다. 내가 그 곁으로 가자 여운비가 붉은 술을 손가락으로 쓸었다. 바람이 남쪽에서 불어왔다."},{"s":null,"t":"여운비가 품에서 손때 묻은 장부 한 권을 꺼냈다. 북령 호송대가 썰매 수와 짐 수를 적는 호송 장부였다. 여운비는 마지막 장을 펴서 내게 내밀었다."},{"s":null,"t":"그 장에는 짐 대신 이런 줄이 적혀 있었다. 「청파, 숨 짧음, 반 시진씩 두 번.」 「단비, 오른쪽에서 말할 것.」 「갈매, 물러설 줄 모름.」 「서하람, 국수 먹다 졺.」 맨 아래 줄에는 「장무현」 세 글자가 적혀 있었다."},{"s":"north_league:yeo","t":"맹주께 올릴 장부요. 썰매 몇 대에 짐 몇 짐을 적어야 하는데, 언제부턴가 이런 것만 적고 있소. 맹주께서 보시면 호송대장이 실성했다 하실 거요."},{"s":null,"t":"나는 맨 아래 이름 곁에 내 이름을 적어도 되냐고 물었다. 여운비는 대답 대신 붓을 내밀었다."},{"s":"north_league:yeo","t":"장 하나가 남았소. 흑련 장을 찾아 마당까지 가야 하오. 이 장부에서 이름이 하나라도 줄면, 나는 맹주께 장부를 못 올리오."},{"s":null,"t":"내가 「장무현」 곁에 이름을 적자, 여운비는 장부를 덮어 품에 넣고 돌담에서 등을 뗐다."},{"s":null,"t":"밤이 깊었다. 화로의 흰 불씨는 장무현이 없는 밤에도 꺼지지 않았다. 우리는 화로 둘레에 둘러앉아 새벽까지 한 이름을 불렀다."}],"reward":{"xp":2247,"gil":510,"items":{"king_ember_ash":2,"ember_ash_pill":2}}},{"quest_id":"mdq_15","step":1,"title":"남겨 둔 쪽지","goal":"잔불촌에서 쉬고 갈매가 남긴 쪽지를 편다","need":{"at":["ember_village"],"tasks":[{"t":"rest","r":["ember_village"],"n":1}]},"lines":[{"s":null,"t":"이튿날 아침 화로 곁 걸상이 비어 있었다. 걸상에 걸어 두었던 장무현의 옷도 없었다. 걸상 아래에는 가죽 신만 가지런히 남아 있었다."},{"s":null,"t":"걸상 위에 쪽지 한 장이 돌멩이에 눌려 있었다. 「할배 옷은 할배가 태어난 데 묻고 올게. 기다리지 마.」 거칠게 갈겨쓴 글씨였다."},{"s":null,"t":"청파가 쪽지를 낚아채 마을 어귀까지 달려갔다. 콜록콜록 기침을 하며 돌아온 청파의 얼굴이 울상이었다."},{"s":"q:sn_cheongpa","t":"없어요! 어귀에도 없고, 들소 우리에도 없어요! 누님이 기다리지 말래요. 그래도 우리 기다려야 하죠? 그렇죠?"},{"s":null,"t":"단비가 청파 쪽으로 오른쪽 귀를 기울였다. 단비는 쪽지를 받아 들고 글씨를 손가락으로 쓸었다."},{"s":"red_moon_cult:danbi","t":"「기다리지 마」는 「찾으러 와」라는 뜻이에요. 제가 장담해요. 글씨가 이렇게 흔들리잖아요."},{"s":null,"t":"서하람은 쪽지보다 화로를 보고 있었다. 화로 곁에 작은 구리 화로 하나가 놓여 있던 자국이 동그랗게 남아 있었다."},{"s":"q:r71_seoharam","t":"갈매 씨가 화로 불씨를 덜어 갔어요. 작은 화로째로요. 그런데 혼자서는 안 돼요. 혼자 있으면 아무도 이름을 안 불러 줘요."},{"s":"q:r71_seoharam","t":"장군님 일을 겪고 나니까… 저는 그게 제일 무서워요. 아무도 안 부르는 사람이 되는 거요."},{"s":null,"t":"그 말에 모두가 입을 다물었다. 여운비가 칼자루를 들어 올렸다. 칼자루 끝의 붉은 술이 동쪽으로 팔랑 흔들렸다."},{"s":"north_league:yeo","t":"동쪽 고개에서 바람이 내려오오. 장군이 태어난 곳이 어디요?"},{"s":null,"t":"소이가 화로 뒤에서 걸어 나왔다. 밤새 노래를 불러 목이 잠겨 있었다."},{"s":"southern_remnant:soi","t":"불씨 고개 아래 옛 마을이옵니다. 지금은 아무도 살지 않사옵니다. 장군님 어머님 무덤이 고개 소나무 아래 있사옵니다."},{"s":"q:sn_cheongpa","t":"그럼 거기 가요! 지금 가요!"},{"s":null,"t":"나는 걸상 아래 남은 가죽 신을 집어 품에 넣었다. 품의 여섯 장이 손에 닿았다. 금빛 실로 이어진 장들이 따뜻했다."},{"s":null,"t":"나는 흑련 장보다 갈매를 먼저 찾아야 한다고 했다. 마당 일곱 자리에 설 사람이 하나라도 비면 안 된다고 했다."},{"s":"north_league:yeo","t":"맞는 말이오. 우리는 서로 좋아서 모인 사람들이 아니었소. 그래도 이제 한 사람이 빠지면 끝까지 못 가오. 가서 데려옵시다."},{"s":"red_moon_cult:danbi","t":"대장님, 방금 「서로 좋아서 모인 게 아니었다」고 하셨죠? 「아니었다」요. 지난 일처럼요."},{"s":"north_league:yeo","t":"…말꼬리 잡지 마시오."},{"s":null,"t":"고개는 넓었다. 서하람이 지도를 펴고 고개 길을 손가락으로 나누었다. 반나절은 훑어야 할 넓이였다."}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":2,"title":"고개 소나무 아래","goal":"불씨 고개에 도착해 원정을 한 번 끝까지 다녀오며 고개 길에서 갈매를 찾는다","need":{"at":["ember_pass"],"tasks":[{"t":"travel","r":["ember_pass"],"n":1},{"t":"expedition","r":["ember_pass"],"n":1}]},"lines":[{"s":null,"t":"고개 길을 반나절 헤맨 끝에 서하람이 먼저 연기를 보았다. 고갯마루 늙은 소나무 아래에서 가는 연기가 피어오르고 있었다."},{"s":null,"t":"소나무 아래에 작은 봉분 하나가 있었다. 그 곁에 갈매가 흙투성이 손으로 땅을 파고 있었다. 삽도 없이 맨손이었다."},{"s":null,"t":"곁에 놓인 작은 구리 화로에서 흰 불씨가 빛났다. 개켜 둔 장무현의 옷이 그 옆에 있었다."},{"s":null,"t":"우리 발소리에 갈매가 고개를 홱 들었다. 눈이 퉁퉁 부어 있었다."},{"s":"southern_remnant:galmae","t":"왜 왔어. 기다리지 말랬잖아. 가! 다들 가라고!"},{"s":null,"t":"청파가 대답 대신 달려갔다. 청파는 숨을 헐떡이며 갈매의 허리를 와락 끌어안았다."},{"s":"q:sn_cheongpa","t":"싫어요! 누님이 혼자 땅 파는 거 보러 온 거 아니에요. 같이 파러 온 거예요!"},{"s":null,"t":"갈매가 청파를 떼어 내려고 어깨를 밀었지만, 청파는 떨어지지 않았다. 갈매의 손이 청파의 머리 위에서 멈췄다."},{"s":null,"t":"서하람이 말없이 갈매 곁에 무릎을 꿇었다. 서하람도 맨손으로 흙을 파기 시작했다. 손톱 밑이 금세 새카매졌다."},{"s":"southern_remnant:galmae","t":"…너 손 다쳐. 관측관 손은 별 적는 손이라며."},{"s":"q:r71_seoharam","t":"별은 나중에 적어도 돼요. 이건 지금 해야 해요."},{"s":null,"t":"단비가 오른손으로 흙을 퍼냈다. 여운비는 칼을 칼집째 뽑아 칼집 끝으로 단단한 흙을 쾅쾅 깨뜨렸다."},{"s":null,"t":"나는 품에서 가죽 신을 꺼내 갈매 앞에 놓았다. 잔불촌 걸상 아래 남아 있던 신이었다."},{"s":null,"t":"나는 신도 같이 묻어 드려야 한다고 했다. 맨발로 보내 드릴 수는 없다고 했다."},{"s":null,"t":"갈매가 신을 내려다보았다. 갈매의 어깨가 무너지듯 내려앉았다."},{"s":"southern_remnant:galmae","t":"깜깜해서 옷만 챙겼어. 고개를 넘고 나서야 신이 없는 걸 알았어. 할배를… 맨발로 보낼 뻔했잖아…"},{"s":null,"t":"갈매는 신을 두 손으로 받아 가슴에 꼭 안았다. 갈매는 그대로 한참 울었다. 이번에는 짐승 같은 소리가 아니라 아이 같은 울음이었다."},{"s":null,"t":"울음이 잦아들자 갈매가 흙 묻은 손등으로 눈을 문질렀다."},{"s":"southern_remnant:galmae","t":"나 이제 같이 갈 이유가 없어. 남명 장은 이었잖아. 남명이 본다던 건 다 봤어. 정청이 뭘 태우는지도 봤고."},{"s":"north_league:yeo","t":"같이 갈 이유는 처음부터 세력 일이 아니었소. 마당 일곱 자리에 서서 서로를 불러야 진이 풀리오. 그 자리에 남명 사람이 없으면, 장군 이름을 누가 부르겠소."},{"s":"red_moon_cult:danbi","t":"그리고 갈매 씨가 없으면 하람 씨를 누가 업어 줘요. 저는 한 팔밖에 못 쓰고, 청파는 숨이 짧고, 대장님은 칼밖에 못 들어요."},{"s":"north_league:yeo","t":"…칼밖에 못 드는 건 맞소."},{"s":null,"t":"갈매가 픽 웃었다. 웃음이 흙투성이 얼굴 위로 아주 잠깐 지나갔다."},{"s":null,"t":"그때 고갯마루 아래 숲에서 바스락 소리가 났다. 시커먼 것들이 나무 사이로 어슬렁거렸다. 먹이 잔뜩 낀 짐승들이었다."},{"s":"southern_remnant:galmae","t":"할배 옷 냄새를 맡고 온 거야. 묻기 전에 치워야 해. 저것들한테 한 올도 못 줘."}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":3,"title":"묻고 온 밤","goal":"불씨 고개 무덤 둘레를 맴도는 잿불 도마뱀을 3번 쓰러뜨린다","need":{"at":["ember_pass"],"tasks":[{"t":"win","n":3,"m":["dd_palace_4"],"r":["ember_pass"]}]},"lines":[{"s":null,"t":"마지막 짐승이 숲속으로 쓰러지자 고갯마루가 조용해졌다. 우리는 장무현의 옷과 신을 나란히 구덩이에 넣었다."},{"s":null,"t":"쓰러진 짐승은 잿빛 왕궁 터에서 본 잿불 도마뱀이었는데, 몸이 먹물로 풀려 고갯마루 아래 우물로 흘러내렸다."},{"s":null,"t":"흙은 갈매가 맨 처음 한 줌 뿌렸다. 우리가 차례로 흙을 덮었다. 봉분이 작게 솟았다."},{"s":null,"t":"갈매가 봉분 앞에서 「장무현」 하고 불렀다. 금빛 입김이 봉분 위로 날아가 흙 속으로 스며들었다. 묻힌 것은 옷뿐인데도 갈매는 그 자리를 오래 바라보았다."},{"s":null,"t":"해가 지자 우리는 소나무 아래에 불을 피웠다. 갈매가 구리 화로의 흰 불씨를 모닥불에 옮겨 붙였다."},{"s":"southern_remnant:galmae","t":"할배 화로 불씨야. 맹약 마당에도 등이 있어야 할 거 아냐. 잔불촌 불은 소이가 지키고, 이건 내가 들고 갈 거야."},{"s":null,"t":"그때 고갯길 아래에서 방울 소리가 딸랑딸랑 올라왔다. 검은 끈을 손목에 맨 흑련 심부름꾼이 등짐을 지고 숨을 몰아쉬며 다가왔다."},{"s":"q:md_runner","t":"흑련 장부고에서 왔습니다. 구슬 행수님이 이걸 꼭 전하라 하셨습니다. 다온이라는 아이가 한 사람에 한 통씩 썼답니다."},{"s":null,"t":"심부름꾼이 서신 여섯 통을 꺼냈다. 겉봉마다 삐뚤빼뚤한 글씨로 이름이 적혀 있었다. 갈매 몫도 있었다."},{"s":"southern_remnant:galmae","t":"나한테도? 나 그 꼬마 얼굴도 못 봤는데."},{"s":"red_moon_cult:danbi","t":"제가 다온이한테 서신을 보냈거든요. 우리 얘기를 다 써서요. 갈매 씨가 장군님 국수를 끊어 먹었다는 것까지요."},{"s":"southern_remnant:galmae","t":"야!"},{"s":null,"t":"우리는 모닥불 둘레에 앉아 저마다 제 서신을 펼쳤다. 청파가 먼저 소리 내어 읽었다."},{"s":"q:mk_daon","t":"「청파 님. 숨이 짧으면 큰 소리 내지 말고 작게 부르세요. 작게 불러도 들려요. 저는 아저씨한테 맨날 작게 불러요.」"},{"s":"q:mk_daon","t":"「대장님. 단비 누나가 대장님은 칭찬을 한 번밖에 안 한대요. 저는 나쁘지 않다는 말도 좋아요.」"},{"s":null,"t":"여운비가 서신을 접어 품에 넣었다. 여운비는 아무 말도 하지 않았지만 그 귀 끝이 빨갰다."},{"s":"q:mk_daon","t":"「갈매 님. 할아버지 일 들었어요. 저도 아저씨가 쓰러졌을 때 무서웠어요. 그래도 부르면 돼요. 할아버지도 갈매 님이 부르면 들으실 거예요. 있었다는 거 잊지 않으면요.」"},{"s":null,"t":"갈매는 서신을 읽다가 손등으로 코를 훔쳤다. 서신을 접는 손이 조심스러웠다."},{"s":"q:mk_daon","t":"「{이름} 님. 구슬 누나가 금고 여는 길을 찾았대요. 빨리 오세요. 아저씨 잿빛이 팔꿈치에서 안 내려가요. 그리고 곶감 준 아저씨가 나쁜 사람이에요? 구슬 누나가 장부 가져간 사람들이 그 아저씨 일꾼이래요. 그 곶감, 발로 밀어 놓고 아저씨 몰래 주워 먹었어요. 맛있었는데.」"},{"s":null,"t":"나는 그 마지막 줄을 오래 보았다. 장부고가 털리던 날, 경현이 다온의 손에 곶감을 쥐여 주던 손이 떠올랐다."},{"s":"q:r71_seoharam","t":"그 사람은 다온이한테 곶감을 주고, 장군님한테는 줄을 그었어요. 둘 다 같은 손이에요. 그래서 더 무서워요."},{"s":null,"t":"모닥불이 타닥 튀었다. 잠자리에 들기 전, 갈매가 내 곁으로 와 앉았다. 갈매는 불씨를 담은 구리 화로를 무릎 위에 올려 두었다."},{"s":"southern_remnant:galmae","t":"{이름}. 할배가 너한테 내 등 봐 달라고 했다며."},{"s":null,"t":"나는 그랬다고 했다. 대신 나는 갈매가 내 등을 봐 줄 거라고 대답했다고 했다."},{"s":"southern_remnant:galmae","t":"…그 대답 할배 맘에 들었겠다. 할배는 지는 거 싫어했거든. 등은 서로 봐 주는 거지, 한쪽이 봐 주는 게 아니라고."},{"s":null,"t":"갈매는 화로를 끌어안고 내 어깨에 등을 기댔다. 갈매는 금세 잠들었다. 이틀 만에 처음 자는 잠이었다."},{"s":null,"t":"나는 밤새 갈매의 이름을 작게 불렀다. 다온의 서신대로, 작게 불러도 금빛 실은 닿았다."},{"s":null,"t":"이튿날 아침 우리는 흑련 장부고로 길을 잡았다. 다온의 서신대로라면 구슬이 금고로 가는 길을 찾아 두었을 터였다."}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":4,"title":"장부지기의 셈","goal":"흑련 장부고에 도착해 탐색하며 금고 문에 남은 먹 자국의 실마리를 2번 찾는다","need":{"at":["ledger_cellar"],"tasks":[{"t":"travel","r":["ledger_cellar"],"n":1},{"t":"clue","r":["ledger_cellar"],"n":2}]},"lines":[{"s":null,"t":"장부고 문지기들은 이번에는 우리를 막지 않았다. 문지기들은 우리를 보자마자 길을 비키고, 안쪽에 대고 구슬을 불렀다.","fac_not":"black_lotus","spec":2,"grp":1},{"s":null,"t":"장부고 문지기들은 매듭을 찬 내 손목을 보고 고개를 숙였다. 문지기 하나가 안쪽에 대고 구슬을 불렀고, 장부고 사람들이 하던 일을 멈추고 일어섰다.","fac":"black_lotus","spec":1,"grp":1},{"s":null,"t":"금고 앞 침상에 월하가 누워 있었다. 잿빛은 왼팔 팔꿈치에 멈춰 있었다. 다온이 침상 머리맡에서 쪽지를 쥔 채 앉아 있다가 우리를 보고 벌떡 일어섰다."},{"s":"q:mk_daon","t":"{이름} 님! 대장님! 단비 누나!"},{"s":null,"t":"다온은 맨 먼저 내 허리에 매달렸다. 그다음 방울을 단 단비를 단번에 알아보고 그 품으로 뛰어들었다."},{"s":null,"t":"다온은 콜록거리는 청파에게도 매달렸다. 여운비 앞에서는 잠깐 멈칫했다가 그 다리를 꼭 끌어안았다."},{"s":null,"t":"여운비가 어쩔 줄 몰라 두 손을 허공에 든 채 굳었다. 단비가 그걸 보고 킥킥 웃었다."},{"s":null,"t":"다온은 마지막으로 갈매 앞에 섰다. 갈매가 쭈그려 앉아 눈높이를 맞추자 다온이 갈매의 목을 와락 끌어안았다."},{"s":"q:mk_daon","t":"할아버지 일, 미안해요. 제 서신 받았어요?"},{"s":"southern_remnant:galmae","t":"…받았어. 아직 품에 있어."},{"s":null,"t":"인사를 마친 다온은 곧장 월하의 머리맡으로 돌아가 앉았다. 침상 곁 방석이 다온의 몸 모양대로 푹 꺼져 있었다. 다온은 달포 넘게 그 자리를 지켰다."},{"s":null,"t":"장부고 안쪽에서 딸깍딸깍 주판알 소리가 났다. 장부지기 구슬이 주판을 끼고 걸어 나왔다. 구슬 뒤로 한설이 따라 나왔다."},{"s":"night_office:han","t":"왔구나, 조사원. 구슬 행수의 서신을 받고 하루 먼저 왔다. 정리소 문은 문수와 희수 서리에게 맡겼다. 안쪽 길은 내가 안다."},{"s":null,"t":"한설이 갈매를 보았다. 한설은 무언가 말하려다 고개만 깊이 숙였다. 갈매도 정청 사람에게 처음으로 고개를 마주 숙였다."},{"s":null,"t":"구슬이 주판알 하나를 탁 튕기고 우리를 둘러보았다."},{"s":"black_lotus:guseul","t":"손님들, 셈은 끝났어요. 금고 문에 남은 먹 손자국이 정리소 먹이랑 같은 냄새예요. 정리소 우물로 내려가면 정리관이 바로 알 거고요.","fac_not":"black_lotus","spec":2,"grp":2},{"s":"black_lotus:guseul","t":"회원님이시니 셈을 다 말씀드릴게요. 금고 문의 먹 손자국이 정리소 먹이랑 같은 냄새예요. 회주님 허락 없이는 회원에게도 안 알려 주는 길이 하나 있어요.","fac":"black_lotus","spec":1,"grp":2},{"s":"black_lotus:guseul","t":"장부고 밑 지맥 갱도에 먹 도랑이 지나요. 그 도랑을 거슬러 오르면 정리소 금고 바로 밑으로 나와요. 장부지기들이 대대로 입을 다물어 온 길이에요."},{"s":"q:sn_cheongpa","t":"거슬러 올라요? 먹물 속을요?"},{"s":null,"t":"구슬이 손끝으로 제 무릎께를 가리켰다."},{"s":"black_lotus:guseul","t":"무릎까지예요. 대신 금고 앞에 먹손들이 서 있어요. 정리소에서 다 들으셨다면서요."},{"s":"red_moon_cult:danbi","t":"들었어요. 줄을 미뤄 받은 값으로 정리관 일을 하는 사람들이요. 장부고를 턴 것도, 서가에 불을 놓은 것도요."},{"s":null,"t":"구슬이 손끝으로 내 품께를 가리켰다."},{"s":"black_lotus:guseul","t":"그 가운데 하나는 제가 알아요. 장부고 바닥에서 주우셨던 명부 조각 있죠? 붉은 줄이 반만 그어진 이름이요. 곽두칠."},{"s":"black_lotus:guseul","t":"열 해 전 우리 흑련에 빚을 지고 사라진 사람이에요. 죽은 줄 알았는데, 줄을 미뤄 받고 그쪽 일을 하고 있었던 거예요. 빚 중에서도 제일 무서운 빚이죠."},{"s":null,"t":"여운비의 손이 칼자루로 갔다. 붉은 술이 가만히 늘어져 있었다. 장부고 안에는 바람이 없었다."},{"s":null,"t":"그때 금고 안쪽 어둠에서 목소리가 울렸다. 회주 무명이었다."},{"s":"black_lotus:mumyeong","t":"그 길은 내가 허락하겠소. 이번에는 나도 함께 가겠소. 그 장부를 펼 수 있는 손은 내 손뿐이오."},{"s":null,"t":"어둠 속에서 무언가가 움직였다. 검은 천으로 온몸을 감싼 사람 하나가 금고에서 걸어 나왔다. 키가 작고 허리가 굽어 있었다."},{"s":null,"t":"장부고 사람들이 일제히 무릎을 꿇었다. 구슬의 주판이 손에서 미끄러져 와르르 바닥에 쏟아졌다."},{"s":"black_lotus:guseul","t":"회주님이… 금고 밖에…"},{"s":"black_lotus:mumyeong","t":"첫 회주가 들고 나온 장이오. 그 장을 되찾는 날까지 금고에 앉아 있을 수는 없지."},{"s":null,"t":"다온이 월하의 손을 꼭 쥐고 우리를 올려다보았다."},{"s":"q:mk_daon","t":"아저씨 이름 맡겨 둔 장도 그 장부에 있대요. 꼭 찾아와 주세요."},{"s":null,"t":"한설이 장부고 바닥의 쇠 뚜껑을 발끝으로 가리켰다. 뚜껑 틈으로 차가운 먹 냄새가 올라왔다."},{"s":"night_office:han","t":"도랑 어귀에 검은 손들이 고여 있을 거다. 정리소 도랑에서 올라오던 것과 같은 것들이다. 그것부터 치우고 들어가야 길이 열린다."}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":5,"title":"먹물 속 손","goal":"지맥의 뿌리에 도착해 먹 도랑을 지키는 먹 도랑 검은 손을 5번 쓰러뜨린다","need":{"at":["under_root"],"tasks":[{"t":"travel","r":["under_root"],"n":1},{"t":"win","n":5,"m":["dd_vault_1"],"r":["under_root"]}]},"lines":[{"s":null,"t":"지맥 갱도의 먹 도랑은 무릎까지 차는 먹물이었다. 먹물은 차갑고 끈적했다. 발을 뗄 때마다 쩍, 쩍 소리가 나며 신발을 잡아당겼다."},{"s":null,"t":"여운비가 맨 앞에 섰다. 갱도 안에도 바람이 조금 흘렀다. 여운비는 칼자루 끝의 붉은 술을 보며 걸었다."},{"s":"north_league:yeo","t":"술이 앞으로 날리오. 바람이 도랑 위쪽으로 빨려 가는 거요. 이 길이 정리소로 이어진다는 뜻이오."},{"s":null,"t":"무명은 걸음이 느렸다. 먹물에 발이 빠질 때마다 굽은 몸이 휘청거렸다. 나는 무명의 팔을 내 어깨에 걸쳤다."},{"s":"black_lotus:mumyeong","t":"정청 사람 어깨에 기대는 날이 올 줄은 몰랐소. 첫 회주가 알면 웃겠구려.","fac_not":"black_lotus","spec":2,"grp":1},{"s":"black_lotus:mumyeong","t":"매듭 찬 회원 어깨에 기대는 거야 흔한 일이오. 그 어깨에 정청 패까지 달린 건 처음이구려. 첫 회주가 알면 웃겠소.","fac":"black_lotus","spec":1,"grp":1},{"s":null,"t":"우리는 서로 손을 잡고 한 줄로 걸었다. 단비의 왼쪽 귀가 들리지 않아서, 여운비는 뒤를 돌아볼 때마다 단비의 오른쪽 어깨를 두 번 두드렸다. 멈추라는 신호였다."},{"s":null,"t":"갱도가 넓어지는 곳에서 먹물이 부글부글 끓어올랐다. 시커먼 손들이 먹물 위로 솟구쳤다. 손마다 손가락이 길고 손끝에서 먹이 뚝뚝 떨어졌다."},{"s":null,"t":"그 손 하나가 청파의 발목을 휘감았다. 청파가 「어어!」 하며 먹물 속으로 끌려 들어갔다. 철퍽, 청파의 머리까지 먹물에 잠겼다."},{"s":"red_moon_cult:danbi","t":"청파야!"},{"s":null,"t":"갈매가 먹물 속으로 팔을 쑥 집어넣었다. 갈매의 칼이 먹물 아래에서 번쩍 휘둘렸다. 갈매는 청파의 멱살을 움켜쥐고 끌어올렸다."},{"s":null,"t":"청파가 먹물을 토하며 쿨럭쿨럭 기침을 했다. 서하람이 청파의 등을 쳐 주며 맥을 짚었다."},{"s":"q:r71_seoharam","t":"숨은 쉬어요. 맥도 빨라요. 괜찮아요. 괜찮은 거예요."},{"s":"southern_remnant:galmae","t":"헤엄도 잘 치는 놈이 먹물에 빠져? 이 꼬맹이가… 정신 차려!"},{"s":"q:sn_cheongpa","t":"누님… 저 꼬맹이 소리 안 하기로 했잖아요… 누님이 하면 어떡해요…"},{"s":"southern_remnant:galmae","t":"나는 해도 돼. 너는 하지 마."},{"s":null,"t":"청파가 콜록거리다 웃었다. 갈매가 청파를 한쪽 팔로 부축해 일으켰다. 구리 화로를 진 등이 흔들렸지만 흰 불씨는 꺼지지 않았다."},{"s":null,"t":"검은 손을 모두 베어 넘기자 도랑 끝에 돌 틈 하나가 보였다. 틈 위쪽에서 차가운 먹 냄새가 흘러내렸다."},{"s":"night_office:han","t":"이 위가 정리소 금고다. 금고 문 앞을 먹손 셋이 지킨다. 그 사람들은… 사람이다. 베지 말고 지나가라."},{"s":"southern_remnant:galmae","t":"사람이라고? 장부 털어 간 놈들이잖아."},{"s":"night_office:han","t":"줄을 미뤄 받은 사람들이다. 거절하면 그날 풀렸을 거다. 나라도 그 손을 잡았을 거다."},{"s":null,"t":"갈매는 대꾸하지 않고, 칼을 칼집에 넣으며 손잡이 위에 손만 얹었다."}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":6,"title":"금고","goal":"정리소에 도착해 3번 탐색하며 금고와 먹손을 피해 갈 길을 찾는다","need":{"at":["jeongni_vault"],"tasks":[{"t":"travel","r":["jeongni_vault"],"n":1},{"t":"search","r":["jeongni_vault"],"n":3}]},"lines":[{"s":null,"t":"돌 틈으로 기어 오르자 정리소 금고 바닥이 나왔다. 벽을 따라 칸칸이 장부가 꽂혀 있었다. 장부마다 모서리가 접혀 있었다."},{"s":null,"t":"금고 문 앞에 먹손 셋이 서 있었다. 등잔 아래인데도 그림자가 물에 탄 먹처럼 흐렸다. 손끝은 먹에 담갔다 뺀 듯 새카맸다."},{"s":null,"t":"먹손들은 우리를 보고도 움직이지 않았다. 셋 가운데 하나가 무명을 보더니 고개를 푹 숙였다."},{"s":"black_lotus:mumyeong","t":"…곽두칠. 그대였구려. 열 해 전 빚을 지고 사라진 사람이."},{"s":"q:md_gwak_duchil","t":"회주님. 열 해 전 명부에 제 이름이 올랐습니다. 줄을 반만 긋고 미뤄 준다기에… 그 값으로 서가에 불을 놓고, 장부를 들고 왔습니다. 죽고 싶지 않았습니다."},{"s":"q:md_gwak_duchil","t":"정청 서고 출입 장부도 제가 그랬습니다. 그날 밤 줄을 칼로 오려 냈습니다. 누가 내려왔는지 모르게요."},{"s":null,"t":"한설의 턱이 굳었다. 한설은 출입 장부를 뒤지던 그 아침처럼 손가락으로 허공에 줄 하나를 그었다가 내렸다."},{"s":"night_office:han","t":"오린 자리가 반듯하더군. 칼을 쥔 손이 떨지 않았다는 뜻이다. 그 손으로 이제 다른 걸 적어라."},{"s":"southern_remnant:galmae","t":"서가에 불 지른 게 너야? 그 불에 기록관 손이 다 데었어!"},{"s":"q:md_gwak_duchil","t":"…압니다. 그 손을 봤습니다. 그 뒤로 밤마다 그 손이 보입니다."},{"s":null,"t":"무명은 그 먹손을 오래 바라보았다. 검은 천 사이로 한숨 같은 숨이 새어 나왔다."},{"s":"black_lotus:mumyeong","t":"흑련은 이름을 맡아 주는 곳이오. 이름을 판 사람을 벌하는 곳이 아니오. 비켜 주시오. 돌아오고 싶거든 언제든 오시오."},{"s":null,"t":"곽두칠이 비켜서며 금고 안쪽을 가리켰다. 새카만 손끝이 떨렸다."},{"s":"q:md_gwak_duchil","t":"장부는 맨 안쪽 쇠 상자 위에 있습니다. 정리관께서 오늘 오십니다. 서두르십시오. 저는… 아무것도 못 본 겁니다."},{"s":null,"t":"나머지 둘도 서로 눈치를 보다 물러섰다. 우리는 그 사이를 지나 금고 맨 안쪽으로 갔다."},{"s":null,"t":"쇠 상자 위에 검은 끈으로 묶인 장부 한 권이 놓여 있었다. 끊긴 끈을 거칠게 다시 묶어 두었고, 귀퉁이 하나가 검게 그을려 있었다."},{"s":null,"t":"무명이 장부 앞에 섰다. 검은 천 사이로 내민 손은 주름투성이였다. 손등에 가는 먹 줄이 수없이 그어져 있었다."},{"s":"black_lotus:mumyeong","t":"흑련의 회주는 대대로 목소리로만 사람을 만났소. 이 손을 보이면 맡아 둔 이름들이 다 드러나니까."},{"s":null,"t":"무명이 검은 끈을 천천히 풀었다. 갈피마다 이름이 적힌 종잇조각이 촘촘했다. 그 한가운데에 두꺼운 닥종이 한 장이 있었다."},{"s":null,"t":"종이 위의 흰 불꽃이 깜빡깜빡 흔들렸다. 그을린 귀퉁이 탓이었다. 장에는 「부르는 이가 적힌 이름은 거두지 않는다」는 구절과 칸의 원래 모양, 그리고 해제 조항이 적혀 있었다."},{"s":null,"t":"그때 먹 도랑 쪽에서 낮은 목소리가 울려 왔다. 물을 통해 아주 먼 곳에서 들려오는 소리였다."},{"s":"q:m_yun","t":"거기 누구 있습니까. 아홉째 문 위 천장의 일곱 불빛 가운데 하나가 아직도 깜빡입니다. 정청 서가에 불이 났다던 그 밤부터입니다. 그 뒤로 문이 자꾸 흔들립니다."},{"s":null,"t":"한설이 숨을 들이켰다. 홍인사 때 아홉째 문 안쪽에 남은 윤도한의 목소리였다."},{"s":null,"t":"언제 왔는지 금고 입구에 경현이 서 있었다. 발소리는 한 번도 들리지 않았다. 옷자락이 먹물에 젖어 있었다. 손에는 아무것도 들려 있지 않았다."},{"s":null,"t":"갈매가 바람처럼 튀어 나갔다. 칼날이 경현의 목 앞에서 딱 멈췄다. 경현은 한 걸음도 물러서지 않았다."},{"s":"q:md_gyeonghyeon","t":"베시오, 정찰대장. 나를 베어도 가늠 저울은 정리소에 남소. 다음 정리관이 그 저울을 읽고 똑같이 거둘 거요."},{"s":"southern_remnant:galmae","t":"다음 정리관? 저울도 네가 만들었다며! 할배 줄도 네가 그었다며!"},{"s":null,"t":"갈매의 칼끝이 부들부들 떨렸다. 서하람이 갈매의 등 뒤로 다가가 갈매의 칼 든 팔에 손을 얹었다."},{"s":"q:r71_seoharam","t":"갈매 씨. 할아버지가 손님한테 칼 거두라고 하셨잖아요. 이 사람 칼은 마당에서 받아요. 지금은 장부예요."},{"s":null,"t":"갈매가 이를 갈며 칼을 거두었다. 경현은 쇠 상자 위 장부의 그을린 귀퉁이를 턱으로 가리켰다."},{"s":"q:md_gyeonghyeon","t":"그 귀퉁이는 내가 불을 대려다 거둔 자리요. 일곱 장 가운데 하나라도 없으면 맹약은 영영 풀 수 없소. 풀지 못하면 진은 그대로 남지. 그래서 처음엔 하나씩 태우려 했소."},{"s":"q:md_gyeonghyeon","t":"그런데 장서각에서 첫째 장이 반만 탄 밤, 봉연 천장 불빛 하나가 깜빡였소. 방금 들은 그 불빛이오. 장이 하나 탈 때마다 문이 흔들린다는 뜻이지. 한 장씩 태우다 문이 열리면 솔내가 또 오오."},{"s":null,"t":"금고 문 앞의 곽두칠이 경현을 보고 털썩 무릎을 꿇었다. 이마가 돌바닥에 닿았다."},{"s":"q:md_gwak_duchil","t":"정리관님. 제가 길을 열었습니다. 줄을… 마저 그어 주십시오. 그 손이 밤마다 보여서 더는 못 살겠습니다."},{"s":"q:md_gyeonghyeon","t":"일어나시오. 당신 줄을 언제 마저 그을지는 내가 정하오. 오늘은 아니오."},{"s":"night_office:han","t":"그럼 왜 저희를 보내 주십니까. 곽두칠이 길을 연 걸 아시면서도요."},{"s":"q:md_gyeonghyeon","t":"그래서 일곱 장이 한자리에 모이기를 기다리는 거다. 일곱 장을 한데 모아 한꺼번에 태우면, 진은 꺼지지 않고 그대로 굳는다. 문은 흔들릴 틈이 없고, 칸은 영영 돌아오지 못하지. 그게 가장 적게 잃는 길이다, 설아."},{"s":"q:md_gyeonghyeon","t":"그러니 가져가시오. 장을 모아 마당 돌상에 올려놓을 사람은 저 조사원밖에 없소. 그 일은 내 손으로는 못 하니까."},{"s":null,"t":"경현이 나를 바라보았다. 장부 모서리를 접는 손가락이 느렸다."},{"s":"q:md_gyeonghyeon","t":"당신이 일곱을 다 모아 오면, 그다음은 내가 하겠소. 우리는 마당에서 다시 보게 될 거요."},{"s":null,"t":"나는 마당에서 태워지는 것은 장이 아닐 거라고 했다. 경현은 대답하지 않고 웃었다. 웃음 끝이 지쳐 있었다."},{"s":null,"t":"무명이 검은 천 사이로 경현을 바라보았다. 무명은 처음으로 목소리를 낮추지 않았다."},{"s":"black_lotus:mumyeong","t":"당신의 셈은 늘 숫자만 맞추오. 그 숫자 안에 이름이 있다는 것은 당신이 가장 잘 알 텐데."},{"s":"q:md_gyeonghyeon","t":"그래서 다 외우고 있소, 회주. 만삼천사백열둘. 하나도 빼지 않고. 내가 잊지 않는 한 그들은 숫자가 아니오."},{"s":null,"t":"경현이 금고 입구에서 비켜섰다. 그 순간 도랑의 먹물이 부글부글 솟구치며 검은 손 여럿이 기어 올라왔다."},{"s":"q:md_gyeonghyeon","t":"저것들은 내 것이 아니오. 이름을 받아먹지 못해 굶은 도랑에서 제멋대로 올라오는 거요. 알아서 헤쳐 나가시오."}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":7,"title":"아홉 손가락","goal":"정리소에서 먹 도랑 검은 손을 3번 쓰러뜨리고 흑련 장부고에 도착한다","need":{"at":["ledger_cellar"],"tasks":[{"t":"win","n":3,"m":["dd_vault_1"]},{"t":"travel","r":["ledger_cellar"],"n":1}]},"lines":[{"s":null,"t":"장부고에 돌아오자 구슬이 되찾은 장부를 펼쳐 월하의 「옮김」 장 자리를 찾았다. 찢긴 종잇조각은 먹물로 풀려 사라진 뒤였다."},{"s":null,"t":"구슬이 새 종이에 월하의 이름을 옮겨 적어 그 자리에 끼워 넣었다. 구슬은 그동안 주판을 내려놓고 있었다. 월하는 깨어나지 않았고, 잿빛은 팔꿈치에 멈춘 그대로였다."},{"s":"q:sn_cheongpa","t":"왜 안 깨요? 이름 돌려놨잖아요!"},{"s":null,"t":"구슬이 내려놓았던 주판을 도로 집어 들었다. 손가락이 주판알 위에서 머뭇거렸다."},{"s":"black_lotus:guseul","t":"장부에 이름이 돌아와도, 그 이름을 불러 주는 목소리가 있어야 해요. 장부는 이름을 맡아 둘 뿐이에요. 셈은 사람이 해야죠."},{"s":null,"t":"다온이 쪽지를 쥔 손을 가슴에 꼭 끌어안고 월하의 귀에 입을 댔다."},{"s":"q:mk_daon","t":"아저씨가 펴지 말랬어요. 그러니까 안 펴고 부를게요. 아저씨. 아저씨! 아저씨!"},{"s":null,"t":"금빛 실 한 가닥이 월하의 가슴께에 닿았다. 우리가 뒤따라 월하의 이름을 불렀다."},{"s":null,"t":"단비가 오른손으로 월하의 손을 잡고 불렀다. 갈매가 불렀고, 청파가 숨을 아껴 작게 불렀다. 여운비가 불렀고, 서하람이 불렀다. 한설도 불렀다."},{"s":null,"t":"금빛 실이 열 가닥, 스무 가닥으로 늘어나 월하의 가슴 위에서 실타래처럼 엉켰다. 팔꿈치의 잿빛이 손목으로, 손등으로, 손가락 끝으로 스르르 물러났다."},{"s":null,"t":"월하가 눈을 떴다. 월하는 다온을 보고, 우리를 차례로 보고, 마지막으로 제 왼손을 내려다보았다. 새끼손가락 두 마디가 없었다."},{"s":null,"t":"월하는 오른손으로 머리맡의 엽전을 집어 튕겼다. 엽전이 손등에서 미끄러져 쨍그랑 바닥에 떨어졌다."},{"s":null,"t":"다온이 얼른 엽전을 주워 월하의 손에 쥐여 주었다. 월하는 엽전을 내려다보다가 웃었다. 능청스러운 웃음이 아니라 처음 보는 웃음이었다."},{"s":"q:mk_wolha","t":"…오른손으로는 아직 서툴러요. 연습해야겠네. 아홉 손가락으로."},{"s":"q:mk_daon","t":"제가 맨날 주워 드릴게요. 백 번 떨어뜨려도요."},{"s":"q:mk_wolha","t":"백 번이면 엽전값이 다 닳겠다, 꼬맹이."},{"s":null,"t":"월하가 목이 쉰 소리로 웃었다. 그 웃음이 다시 기침으로 바뀌었다. 달포 넘게 누워 있던 몸이라 목소리가 바싹 말라 있었다."},{"s":null,"t":"다온은 엽전을 쥔 월하의 손을 놓지 않았다. 나는 묵창 나루 주막 처마 밑의 일을 떠올렸다."},{"s":null,"t":"그날 월하는 다온의 보따리 매듭에 노잣돈을 끼워 넣으며 「이자는 글 배워서 갚아」라고 했다."},{"s":"q:mk_daon","t":"아저씨, 노잣돈 이자요. 서신은 다 제 손으로 썼어요. 아저씨 누워 있는 동안 날마다 썼어요."},{"s":null,"t":"월하가 다온의 손등을 엄지로 쓸었다. 엽전을 굴리던 손가락이었다."},{"s":"q:mk_wolha","t":"…이자를 너무 많이 받았네. 거둠꾼 체면이 안 서게."},{"s":null,"t":"다온이 품에서 손수건 꾸러미를 꺼내 풀었다. 꿀 약과 하나와 반 토막 엿이 나란히 싸여 있었다. 오래 품고 다녀 모서리가 뭉툭했다."},{"s":"q:mk_daon","t":"이것도 아저씨 거예요. 약과는 {이름} 님이 사 준 거고요, 반 토막 엿은 아저씨가 잠꼬대로 사 오라고 한 거예요. 구슬 누나가 셈으로는 반이 아저씨 거래서 남겨 뒀어요."},{"s":null,"t":"월하가 뭉툭한 약과와 엿을 한참 내려다보았다. 엽전을 쥔 손가락이 그쪽으로 갔다가 멈췄다."},{"s":"q:mk_wolha","t":"…꼬맹이가 외상까지 다 갚네. 이건 속 채우고 나서 후식으로 먹자. 반씩."},{"s":null,"t":"구슬이 월하의 등을 받쳐 일으켜 앉혔다."},{"s":"black_lotus:guseul","t":"속부터 채우셔야 해요. 달포 넘게 물만 드셨으니까요. 빈속에 셈 얘기하면 셈이 틀려요."},{"s":"red_moon_cult:danbi","t":"그럼 어죽 끓여요. 다온이 것도요. 다온이도 아저씨 곁에서 밥을 제대로 안 먹었잖아요."},{"s":"q:mk_daon","t":"저는 먹었어요… 조금…"}],"reward":{"xp":2625}},{"quest_id":"mdq_15","step":8,"title":"값 없이 돌려주는 이름","goal":"어죽 2그릇을 쑤어 흑련 장부고에서 월하와 다온에게 넘긴다","need":{"at":["ledger_cellar"],"tasks":[{"t":"craft","items":["fish_porridge"],"n":2}],"give":{"fish_porridge":2}},"lines":[{"s":null,"t":"어죽 두 그릇이 김을 모락모락 피워 올렸다. 다온은 제 그릇을 반쯤 비우고 나서야 배가 고팠다는 것을 알았는지, 남은 반을 허겁지겁 먹었다."},{"s":null,"t":"월하는 오른손으로 숟가락을 쥐었다. 숟가락이 덜덜 떨려 어죽이 흘렀다. 다온이 숟가락을 빼앗아 월하의 입에 떠 넣었다."},{"s":"q:mk_wolha","t":"거둠꾼이 꼬맹이한테 밥을 얻어먹다니. 장부고 사람들 다 보는데."},{"s":null,"t":"문간에서 구슬이 주판알 하나를 탁 튕겼다."},{"s":"black_lotus:guseul","t":"다 봤어요. 장부에 적어 둘게요."},{"s":null,"t":"어죽을 다 먹은 월하가 단비를 불렀다. 단비가 다가오자 월하의 눈길이 먹빛으로 굳은 단비의 왼손 끝에 머물렀다."},{"s":"q:mk_wolha","t":"…적월 무녀님이네. 열네 살 때 그 손으로 내 쪽지를 받아 가던 애."},{"s":"red_moon_cult:danbi","t":"기억하세요? 저는 그 이름도 다 잊었는데. 아저씨 손이 떨리던 것만 기억나요."},{"s":"q:mk_wolha","t":"판 이름은 장부에서 지우는 게 거둠꾼 규칙이에요. 그런데 그 이름만은 머릿속에서 안 지워지더라고요."},{"s":null,"t":"월하는 다온에게서 붓을 빌려 작은 쪽지에 무언가를 적었다. 아홉 손가락으로 쥔 붓이 몇 번이나 미끄러졌다."},{"s":null,"t":"월하가 쪽지를 접어 단비의 오른손에 쥐여 주었다. 단비의 손이 바르르 떨렸다."},{"s":"q:mk_wolha","t":"동짓밤에 이 이름을 불러 주세요. 판 사람이 부르면 안 될 것 같아서요. 산 사람이 불러 주는 게 맞죠."},{"s":"red_moon_cult:danbi","t":"…제가 그 이름으로 처음 서약을 했어요. 그 아이 얼굴도 몰라요. 그래도 부를게요. 꼭요."},{"s":null,"t":"단비는 쪽지를 펴 보지 않고 가슴에 댔다. 쪽지를 감싼 손 모양이 다온이 월하의 쪽지를 쥐던 모양 그대로였다."},{"s":null,"t":"여운비가 단비의 왼쪽에 섰다. 단비의 들리지 않는 쪽이었다. 여운비는 아무 말 없이 단비의 왼쪽 어깨에 손을 얹었다."},{"s":null,"t":"무명이 장부를 다시 묶고, 일곱째 장만 꺼내 내게 내밀었다. 검은 천 사이로 내민 손이 아주 조금 떨리고 있었다."},{"s":"black_lotus:mumyeong","t":"칠십 년 전 첫 회주가 품고 나온 장이오. 이제 그대가 잇구려. 흑련 회주가 정청 사람 앞에서 이 장을 내놓는 날이 오다니.","fac_not":"black_lotus","spec":2,"grp":1},{"s":"black_lotus:mumyeong","t":"칠십 년 전 첫 회주가 품고 나온 장이오. 흑련의 장을 흑련 매듭을 찬 사람이 잇게 되었으니, 첫 회주도 기뻐할 것이오.","fac":"black_lotus","spec":1,"grp":1},{"s":null,"t":"무명이 장을 쥔 채 여운비 쪽으로 고개를 돌렸다. 검은 천 너머의 눈길이 여운비의 칼자루 끝 붉은 술에 오래 머물렀다."},{"s":"black_lotus:mumyeong","t":"북령 호송대장. 첫 회주는 소등 밤에 종을 울린 사람이었소. 종채가 녹아내리며 그 손을 태웠고, 종소리와 함께 제 이름을 잃었소. 목숨은 잃지 않았소."},{"s":"north_league:yeo","t":"종을 울린… 북령 사람 말이오? 그럼… 우리 집안이 부끄럽다고 위패까지 깎은 그분이…"},{"s":"black_lotus:mumyeong","t":"회주들은 대대로 그 이름을 입에 올리지 않았소. 이 장부 맨 첫 장에만 적혀 있지. 「여사온」."},{"s":null,"t":"여운비의 얼굴에서 핏기가 가셨다. 단비가 여운비의 소매를 꼭 붙잡았다."},{"s":"north_league:yeo","t":"작은증조할아버지께서… 살아서 나오셨구려. 그럼 종루 들보 홈이 비어 있던 것도…"},{"s":"black_lotus:mumyeong","t":"그분이 빼 가셨소. 종을 치기 전에 끼워 둔 마지막 말을, 데인 손으로 도로 꺼내셨지. 부를 이 하나 없는 도성에 그 말을 걸어 둘 수는 없다 하셨다오."},{"s":"black_lotus:mumyeong","t":"그러고는 수로로 내려가셨소. 등도 명등지기 여든 남짓이 그분 뒤를 따랐지. 정청이 거둔 이름을 서른 해 동안 밤마다 불러 되살리던 사람들이오. 맹약 일곱째 자리가 원래 그 사람들 몫이었소. 흑련은 그 자리를 이은 거요."},{"s":"black_lotus:mumyeong","t":"수로 끝에서 한 사람이 돌아섰소. 명등지기 윤슬이었지. 「등을 지킬 사람이 하나는 남아야 한다」며 도성 쪽으로 다시 올라갔다 하오. 그 뒤로 그 사람을 본 이는 없소."},{"s":null,"t":"여운비의 입술이 떨렸다. 여운비는 품에 든 편지께를 손바닥으로 눌렀다."},{"s":"north_league:yeo","t":"…소등 이듬해 겨울, 고찰 산문에 이 편지를 두고 간 사내가 있었소. 맹주께서는 그 얼굴을 지금도 떠올리지 못하시오."},{"s":"black_lotus:mumyeong","t":"첫 장부에 그 겨울 그분이 북쪽에 한 번 다녀오셨다고 적혀 있소. 이름을 잃은 사람은 얼굴도 남의 눈에 남지 않소. 그 사내가 그분이오."},{"s":"north_league:yeo","t":"그분이 이 장을 품고 나올 때… 무슨 말을 남기셨소?"},{"s":"black_lotus:mumyeong","t":"「다시는 정청에 이름을 맡기지 않게.」 그 한마디였소. 그 뒤로 회주는 대대로 제 이름을 버렸소. 그분을 잊지 않으려고."},{"s":null,"t":"여운비가 눈을 감았다. 칼자루 끝의 붉은 술을 쥔 손에 힘이 들어갔다."},{"s":null,"t":"내가 「이을 이」 칸에 이름을 적자, 그을린 귀퉁이에서 깜빡이던 흰 불꽃이 금빛으로 바뀌며 고르게 섰다."},{"s":null,"t":"일곱 장이 금빛 실로 이어져 내 품 안에서 원을 그렸다. 실은 이제 팔뚝만큼 굵었다. 품 안이 화롯가처럼 따뜻했다."},{"s":"q:sn_cheongpa","t":"일곱이에요! 다 모았어요!"},{"s":"q:r71_seoharam","t":"이제 남은 건 마당이에요. 일곱 자리에 서서 서로 부르고, 일곱째 칸을 채우면 돼요. 삼백 년 전 일곱 무리가 했던 것처럼요."},{"s":"southern_remnant:galmae","t":"정리관도 거기 올 거야. 일곱 장 다 모아 오면 지가 한다고 했잖아."},{"s":"night_office:han","t":"그러니 우리가 먼저 간다. 등도로 들어가 관아 터에서 하룻밤 묵고, 동지 전에 마당에 선다. 일곱 장을 이은 사람이 거기 서야 진이 풀린다."},{"s":null,"t":"월하가 엽전을 쥔 오른손을 들어 보였다. 이번에는 엽전을 떨어뜨리지 않았다."},{"s":"q:mk_wolha","t":"다녀와요. 다들 값 치르지 말고 돌아와요. 이제 이 장부고에서 이름값 받는 사람은 없으니까."}],"reward":{"xp":2625,"gil":520,"items":{"balance_weight":2,"lamp_wick_core":1}}},{"quest_id":"mdq_16","step":1,"title":"다시 관아 터","goal":"꺼진 관아 터에 다시 도착한다","need":{"at":["dark_yamen"],"tasks":[{"t":"travel","r":["dark_yamen"],"n":1}]},"lines":[{"s":null,"t":"옛 수로를 지나 돌계단을 오르자 꺼진 관아 터가 보였다. 우리가 처음 등도에 들어와 야영을 했던 곳이었다."},{"s":null,"t":"관아 마당 한쪽에 우리가 매달아 둔 등롱 몇 개가 아직 타고 있었다. 등롱 둘레만 저녁 빛깔이었다. 그 밖은 여전히 흰 새벽빛이었다."},{"s":"q:sn_cheongpa","t":"우리 등이 아직 켜져 있어요! 처음 왔을 때 제가 단 거예요. 저기 삐뚤어진 거요."},{"s":"southern_remnant:galmae","t":"삐뚤어진 거 보니까 네 거 맞네."},{"s":null,"t":"갈매가 구리 화로를 마당 가운데 내려놓았다. 흰 불씨가 화로 안에서 고요히 빛났다. 단비가 그 곁에 앉아 오른손을 불씨 위에 쬐었다."},{"s":null,"t":"한설은 관아 문간에서 걸음을 멈추었다. 처음 보는 흰 하늘을 오래 올려다보았다. 한설의 소매 끝 감찰관 패의 글자가 하얗게 바래기 시작했다."},{"s":"night_office:han","t":"장부 글자가 바랜다더니… 정말이구나. 서른 해 동안 명등지기들이 여기서 이름을 불렀다는 게 이래서였군."},{"s":"q:r71_seoharam","t":"네. 등 둘레만 색이 돌아와요. 등이 꺼지면 다시 바래요."},{"s":null,"t":"서하람이 관상대에서 베껴 온 기록을 펼쳤다. 종이를 넘기는 손이 빨랐다. 어느 한 장에서 손이 멈췄다."},{"s":"q:r71_seoharam","t":"소등 밤 기록이에요. 종이 두 번 울렸을 때, 사람들이 옆 사람 이름을 떠올리지 못했대요. 그래서 못 불렀대요. 부를 사람이 바로 옆에 있는데도요."},{"s":"q:r71_seoharam","t":"마당도 이 땅 한가운데예요. 흰 밤이 가장 짙은 곳이고요. 거기서 싸우면… 우리도 서로 이름을 잊을지 몰라요."},{"s":null,"t":"모두가 입을 다물었다. 청파가 침을 꿀꺽 삼켰다. 여운비가 칼자루를 쥔 손을 펴서 손바닥을 들여다보았다."},{"s":"q:sn_cheongpa","t":"그래도 가야죠. 장군님이 먼 길 가라고 국수까지 끓여 먹여 보내셨잖아요. 여기서 돌아서면 그 국수값도 못 해요."},{"s":null,"t":"단비가 제 팔뚝을 걷어 올리고 손가락으로 톡톡 두드렸다."},{"s":"red_moon_cult:danbi","t":"그럼 써 두면 돼요. 몸에요. 잊어버려도 보면 알게요."},{"s":"southern_remnant:galmae","t":"몸에? 먹으로?"},{"s":"red_moon_cult:danbi","t":"네. 팔에도, 손바닥에도요. 적월에서는 서약할 때 이름을 몸에 써요. 지워지지 않게요. 이번엔 서약 말고, 부르려고 쓰는 거예요."},{"s":"night_office:han","t":"그런데 이 땅에서는 글자가 바랜다. 보통 먹으로 쓰면 하룻밤도 못 간다."},{"s":"q:r71_seoharam","t":"등 둘레에서는 색이 돌아오잖아요. 그러니까 등불 그을음으로 갈면 안 바랠 거예요. 갈매 씨 화로 그을음이면 더 좋고요."},{"s":null,"t":"갈매가 구리 화로를 내려다보았다. 갈매는 화로 뚜껑 안쪽에 앉은 새카만 그을음을 손가락으로 쓱 훑었다. 손끝이 까맣게 물들었다. 갈매의 손끝은 하얗게 바래지 않았다."},{"s":"southern_remnant:galmae","t":"…할배 불씨로 쓰는 거네. 할배가 들으면 좋아하겠다. 이름 부르는 데 쓴다니까."},{"s":"north_league:yeo","t":"그을음만으로는 먹이 안 되오. 아교를 끓일 껍질과 먹을 갈 돌이 있어야 하오. 관아 뒤뜰에 오래된 느티나무가 있었소. 그 껍질을 씁시다."},{"s":null,"t":"서하람은 그을음에 먹정과 요기 결정을 섞어 황지로 거르면 정청 봉인 먹이 되니, 몸에 쓴 글씨도 흰 밤에 바래지 않을 거라고 했다."}],"reward":{"xp":3000}},{"quest_id":"mdq_16","step":2,"title":"몸에 쓴 이름","goal":"꺼진 관아 터에서 3번 채집하고 봉인 먹 1개를 갈아 단비에게 넘긴다","need":{"at":["dark_yamen"],"tasks":[{"t":"gather","n":3,"r":["dark_yamen"]},{"t":"craft","items":["sealing_ink"],"n":1}],"give":{"sealing_ink":1}},"lines":[{"s":null,"t":"먹은 생각보다 진하게 갈렸다. 단비가 벼루에 먹을 찍어 불빛에 비춰 보았다. 그을음을 넣은 봉인 먹은 흰 하늘 아래에서도 새카맸다."},{"s":"red_moon_cult:danbi","t":"됐어요. 자, 팔 걷으세요. 다들요. 대장님부터요."},{"s":"north_league:yeo","t":"…왜 나부터요."},{"s":"red_moon_cult:danbi","t":"제일 싫어하실 것 같아서요."},{"s":null,"t":"여운비가 한숨을 쉬며 왼팔 소매를 걷었다. 단비는 오른손으로 붓을 쥐고 여운비의 팔뚝에 「단비」라고 크게 썼다. 그 옆에 조그맣게 엿 하나를 그려 넣었다."},{"s":"north_league:yeo","t":"그 동그라미는 뭐요?"},{"s":"red_moon_cult:danbi","t":"엿이요. 제 이름 잊어버리시면 엿 보고 떠올리세요."},{"s":null,"t":"여운비가 붓을 빼앗아 단비의 오른팔에 「단비」라고 써 주었다. 획이 칼로 그은 듯 반듯했다. 그 아래에 작게 「여운비」라고 하나 더 썼다."},{"s":"red_moon_cult:danbi","t":"어머, 대장님 이름도 써 주셨네요?"},{"s":"north_league:yeo","t":"내가 불러야 할 이름과 나를 불러 줄 이름이오. 한쪽만 쓰면 셈이 안 맞소."},{"s":null,"t":"갈매는 서하람의 손바닥을 붙잡고 「하람」이라고 큼직하게 썼다. 붓이 손바닥을 간질이자 서하람이 몸을 움찔 비틀었다."},{"s":"q:r71_seoharam","t":"간지러워요! 그리고 이거… 하람이에요, 하랑이에요?"},{"s":"southern_remnant:galmae","t":"하람이야! 읽으면 알잖아!"},{"s":"q:r71_seoharam","t":"읽는 사람이 헷갈리면 관측 기록으로는 못 써요."},{"s":null,"t":"서하람이 붓을 받아 갈매의 팔뚝에 「갈매」라고 또박또박 썼다. 관측 기록처럼 반듯한 글씨였다. 그 아래에 서하람은 「장무현」 세 글자를 한 줄 더 썼다."},{"s":null,"t":"갈매가 그 이름을 내려다보았다. 갈매는 아무 말도 하지 않고 그 팔을 가슴에 끌어당겼다."},{"s":null,"t":"청파는 저고리를 훌렁 벗고 등을 내밀었다."},{"s":"q:sn_cheongpa","t":"저는 여기다 다 써 주세요! 다섯 이름 다요! 아니, 감찰관님 것까지 여섯이요!"},{"s":"southern_remnant:galmae","t":"왜 등이야?"},{"s":"q:sn_cheongpa","t":"팔은 좁잖아요. 그리고 제가 쓰러지면 엎어질 거니까, 등에 써야 다들 보잖아요."},{"s":null,"t":"웃던 단비의 입가가 굳었다. 갈매가 청파의 뒤통수를 탁 쳤다."},{"s":"southern_remnant:galmae","t":"쓰러진다는 소리 하지 마. 재수 없게."},{"s":null,"t":"우리는 청파의 등에 차례로 이름을 썼다. 청파는 붓이 닿을 때마다 「으하하, 간지러!」 하며 몸을 비틀었다. 글씨가 하나같이 삐뚤어졌다."},{"s":null,"t":"내 차례가 오자 다섯이 모두 내 팔을 붙잡았다. 왼팔에 단비와 여운비가, 오른팔에 갈매와 서하람과 청파가 제 이름을 썼다."},{"s":null,"t":"마지막으로 한설이 붓을 들었다. 한설은 한참 망설이다 내 손등에 「한설」이라고 작게 썼다. 감찰관의 정자체였다."},{"s":"night_office:han","t":"…네 이름을 부를 사람은 여기 있다. 잊으면 손등을 봐라."},{"s":null,"t":"나도 붓을 받았다. 나는 다섯의 손목 안쪽에 내 이름을 하나씩 써 주었다. 한설의 손등에도 썼다."},{"s":null,"t":"그 밤 우리는 화로 둘레에 둘러누웠다. 팔이며 손바닥이며 온통 새카만 글씨투성이였다."},{"s":"red_moon_cult:danbi","t":"다들 꼴이 우스워요. 우리 내일 맹약 마당에 가는 사람들 맞아요?"},{"s":"southern_remnant:galmae","t":"너도 웃겨. 팔에 엿 그림이 있잖아."},{"s":"q:sn_cheongpa","t":"삼백 년 전 일곱 무리도 이랬을까요? 서로 이름 써 주고, 낄낄대고요."},{"s":"q:r71_seoharam","t":"기록에는 없어요. 그래도… 그랬을 것 같아요. 그래서 버텼을 것 같아요."},{"s":"north_league:yeo","t":"잡시다. 내일은 이름을 부르러 가는 거요. 목을 아껴 두시오."}],"reward":{"xp":3000}},{"quest_id":"mdq_16","step":3,"title":"불침번","goal":"꺼진 관아 터에서 싸움 전 마지막 밤을 쉰다","need":{"at":["dark_yamen"],"tasks":[{"t":"rest","r":["dark_yamen"],"n":1}]},"lines":[{"s":null,"t":"삼경 무렵 나는 불침번을 섰다. 화로 건너편에 여운비가 앉아 있었다. 여운비는 칼을 무릎에 올려 두고 붉은 술을 손가락으로 빗질하고 있었다."},{"s":"north_league:yeo","t":"못 자겠으면 같이 앉아 있으시오. 혼자 서는 불침번은 졸기 쉽소."},{"s":null,"t":"나는 여운비 곁에 앉았다. 여운비는 한참 술만 빗다가 입을 열었다."},{"s":"north_league:yeo","t":"길잡이가 왜 앞에 서는지 아시오? 길을 잘 알아서가 아니오. 앞에 선 사람이 먼저 맞으니까. 뒤에 선 사람들이 그걸 보고 피하라고."},{"s":null,"t":"나는 내일은 앞장서지 말라고 했다. 여운비가 짧게 소리 내어 웃었다."},{"s":"north_league:yeo","t":"그 말은 내가 당신한테 하려던 말이오. 내일 당신은 앞에 서지 마시오. 일곱 장을 이을 사람은 당신 하나요."},{"s":null,"t":"여운비가 소매를 걷어 단비가 써 준 이름과 엿 그림을 내려다보았다. 입꼬리가 아주 조금 올라갔다."},{"s":null,"t":"화로 저편에서 한설이 일어나 앉았다. 한설도 잠들지 못한 얼굴이었다. 한설은 손등에 쓴 내 이름을 손가락으로 덧그리고 있었다."},{"s":"night_office:han","t":"조사원. 내일 그분이 올 거다. 나는… 아직 그분 이름을 한 번도 불러 본 적이 없다."},{"s":null,"t":"나는 왜 그러냐고 물었다."},{"s":"night_office:han","t":"처음 정청에 들어왔을 때부터 스승님이었다. 붓 살 돈이 없던 나한테 당신이 쓰던 붓을 쥐여 준 분이다. 그 붓으로 첫 보고서를 쓰던 날, 고친 글씨는 먹이 두 번 앉는다고 가르쳐 주셨다. 그 사람 이름을 부르면… 스승이 아니라 정리관이 될 것 같았다."},{"s":"night_office:han","t":"정리소에서 장독 이야기를 들은 뒤로 생각했다. 그분 이름을 마지막으로 부른 사람이 그분 어머니였다면, 백 년 동안 아무도 안 부른 거다."},{"s":null,"t":"한설은 붓을 꺼내 닦았다. 천천히, 아주 오래 닦았다. 화가 날 때의 손길이 아니었다."},{"s":null,"t":"한설이 다시 눕고 얼마 지나지 않아, 서하람이 담요를 두른 채 화로 곁으로 기어 나왔다. 서하람은 무릎을 끌어안고 불빛을 오래 들여다보았다."},{"s":"q:r71_seoharam","t":"{이름} 님도 못 자요? 저도요. 이상하죠, 스무 해 동안 밤만 되면 졸렸는데."},{"s":null,"t":"나는 내일이 무섭냐고 물었다. 서하람은 바로 대답하지 않고 손바닥에 쓰인 「하람」을 엄지로 문질렀다."},{"s":"q:r71_seoharam","t":"내일 여섯째 장이 타면 제 눈부터 갈 거예요. 할머니 말도, 기록판도 그랬으니까요. 그래서 오늘 밤에 실컷 봐 두려고요. 별은 없으니까, 다른 거라도요."},{"s":null,"t":"화로 저편에서 담요가 부스럭거렸다. 자는 줄 알았던 갈매가 일어나 앉아 있었다."},{"s":"southern_remnant:galmae","t":"…다른 거 뭐. 뭘 봐 두는데."},{"s":"q:r71_seoharam","t":"갈매 씨 얼굴이요. 불빛이 어두워서 잘 안 보이네요."},{"s":null,"t":"갈매의 얼굴이 화로 불빛보다 빨개졌다. 갈매는 무어라 쏘아붙이려다 입을 다물고, 성큼성큼 화로를 돌아와 서하람 바로 앞에 털썩 앉았다."},{"s":"southern_remnant:galmae","t":"이러면 보이냐, 잠꾸러기."},{"s":"q:r71_seoharam","t":"…네. 잘 보여요. 코에 그을음 묻었어요."},{"s":"southern_remnant:galmae","t":"그건 닦지 말고 그냥 봐."},{"s":null,"t":"한참 둘 다 말이 없었다. 화로 속 숯이 타닥 튀자 갈매가 먼저 입을 열었다."},{"s":"southern_remnant:galmae","t":"내일 네 눈이 감기면, 내가 제일 먼저 부를 거야. 관상대에서 약속했잖아. 제일 크게."},{"s":"q:r71_seoharam","t":"그 약속, 관측 기록에 적어 둘게요. 제 눈으로 적는 마지막 기록이요."},{"s":"southern_remnant:galmae","t":"마지막이라는 소리 하지 마. 재수 없게. …눈 감겨도 내가 다 읽어 줄 거니까, 기록은 계속 해."},{"s":null,"t":"서하람이 웃으며 갈매의 얼굴을 한 번 더 오래 올려다보았고, 그제야 담요 속으로 들어갔다. 갈매는 그 곁에 등을 대고 누웠다. 나는 화로에 장작을 하나 더 넣었다."},{"s":null,"t":"새벽이 왔다. 흰 하늘이 아주 조금 더 하얘졌다. 우리는 화로를 꺼뜨리지 않게 덮고, 짐을 꾸렸다."},{"s":null,"t":"갈매가 구리 화로를 등에 졌다. 서하람이 갈매의 소매를 붙잡고 걸었고, 청파가 단비의 오른쪽에 섰다. 여운비는 맨 앞에 서려다, 멈칫하고 내 곁으로 물러섰다."},{"s":"q:r71_seoharam","t":"마당에 닿으면 일곱 자리부터 찾아야 해요. 관상대 기록에는 자리가 일곱이라는 것만 있고, 어느 자리가 어느 무리 것인지는 없어요."}],"reward":{"xp":3000}},{"quest_id":"mdq_16","step":4,"title":"흰 밤이 된 사람","goal":"맹약 마당에 도착해 2번 탐색하며 일곱 자리와 돌상을 살핀다","need":{"at":["pact_court"],"tasks":[{"t":"travel","r":["pact_court"],"n":1},{"t":"search","r":["pact_court"],"n":2}]},"lines":[{"s":null,"t":"맹약 마당은 등도에서 가장 하얀 곳이었다. 바닥의 돌도, 둘레의 기둥도, 하늘도 같은 흰빛이었다. 어디가 땅이고 어디가 하늘인지 가늠하기 어려웠다."},{"s":null,"t":"공기에는 아무 냄새도 없었다. 우리가 내쉬는 숨조차 하얗게 흩어지지 않았다. 발소리가 두 걸음 앞에서 뚝 끊겼다."},{"s":null,"t":"마당 한가운데에 둥근 돌상이 놓여 있었다. 돌상 위에 손바닥 두 개만 한 홈 일곱 개가 원을 그리며 파여 있었다."},{"s":null,"t":"돌상 둘레 돌바닥에 일곱 자리가 둥글게 표시되어 있었다. 자리마다 꺼진 종이 등롱이 하나씩 놓여 있었다. 마당 가장자리를 따라 먹 도랑 하나가 시커멓게 감돌았다."},{"s":"q:r71_seoharam","t":"일곱 무리가 저기 하나씩 서서 서로를 불렀대요. 이웃 자리끼리만 목소리가 닿고요. 관상대 기록에 그렇게 적혀 있었어요."},{"s":null,"t":"돌상 곁 먹 도랑 가에 경현이 앉아 있었다. 혼자였다. 경현은 도랑 쪽으로 몸을 기울이고 귀를 대고 있었다."},{"s":null,"t":"우리 발소리에 경현이 천천히 일어섰다. 옷자락에서 먹물이 똑똑 떨어졌다."},{"s":"q:md_gyeonghyeon","t":"일곱 장을 다 모았구려. 고생하셨소. 돌상에 올려놓으시오. 그다음은 내가 하겠소."},{"s":null,"t":"나는 품에서 일곱 장을 꺼냈다. 장을 하나씩 홈에 올려놓을 때마다 금빛 실이 장과 장 사이를 이어 원을 그렸다."},{"s":null,"t":"마지막 일곱째 장을 올려놓고, 나는 일곱째 칸 앞에 섰다. 긁힌 칸의 원래 모양이 비어 있었다."},{"s":null,"t":"경현이 그 모습을 보며 고개를 끄덕였다. 경현은 장부를 펼쳐 들지 않고 먹 도랑을 내려다보았다."},{"s":"q:md_gyeonghyeon","t":"진을 풀기 전에 하나만 들으시오. 칸이 돌아오면 무슨 일이 생기는지."},{"s":"q:md_gyeonghyeon","t":"다음 장날에 부름꾼이 다시 앉소. 장터 한쪽에 명부 사본을 펴 놓고. 쌀 두 섬이면 아무 줄 칸에나 제 이름을 적고 엄지 도장을 꾹 찍어 주지."},{"s":"q:md_gyeonghyeon","t":"부름꾼 하나가 한 해에 수백 줄에 도장을 찍소. 그 이름들을 실제로 불러 주는 일은 없소. 도장만 찍히면 거둘 수 없으니까."},{"s":"q:md_gyeonghyeon","t":"돈 있는 집 줄은 칸이 다 차오. 쌀 두 섬이 없는 고을 줄만 칸이 비지. 당신은 쌀 두 섬이 없는 고을을 본 적이 있소?"},{"s":null,"t":"아무도 대답하지 못했다. 경현은 대답을 기다리지 않았다."},{"s":"q:md_gyeonghyeon","t":"솔내는 북령 산골 화전민 고을이었소. 마흔두 집. 글을 아는 사람이 훈장 하나였지. 그해 장날 부름꾼이 왔는데, 솔내에는 쌀이 없었소."},{"s":"q:md_gyeonghyeon","t":"동짓밤 우물마다 검은 물이 솟았소. 물에 닿은 사람은 그 자리에서 먹으로 풀렸소. 마흔두 집이 하룻밤에."},{"s":"north_league:yeo","t":"…솔내 이야기는 무관 거리 모닥불 앞에서 당신한테 이미 들었소. 그 이야기로 우리를 누르려 하지 마시오."},{"s":"q:md_gyeonghyeon","t":"누르려는 게 아니오, 호송대장. 아직 끝나지 않은 이야기라서 하는 거요."},{"s":null,"t":"경현이 먹 도랑 가에 한쪽 무릎을 꿇었다. 경현은 도랑에 귀를 댔다. 그 얼굴이 처음으로 아이처럼 풀어졌다."},{"s":"q:md_gyeonghyeon","t":"문에 먹힌 이름은 사라지지 않소. 땅 밑의 그것 안에 뭉쳐 있지. 나는 동짓밤마다 이 도랑 끝에 귀를 대고 앉아 있었소. 백 년 동안."},{"s":"q:md_gyeonghyeon","t":"깊은 데서 같은 목소리가 부르오. 「경현아」 하고. 그 뒤로 솔내 사람들이 웅성거리는 소리가 들리오. 훈장 어른이 아이들 글 읽히는 소리도."},{"s":null,"t":"단비의 얼굴이 하얗게 질렸다. 단비가 손으로 입을 막았다."},{"s":"q:md_gyeonghyeon","t":"당신들이 진을 풀고 해마다 모든 이름을 부르면, 꺼진 이름이 더는 생기지 않소. 그러면 그것은 굶어 약해지고, 그 안에 뭉친 이름들도 함께 흩어지지."},{"s":"q:md_gyeonghyeon","t":"당신들이 굶기려는 그것 안에 내 어머니가 있소. 아직 내 이름을 부르고 있단 말이오."},{"s":null,"t":"마당이 고요했다. 청파가 무언가 말하려다 입술만 달싹였다. 서하람이 갈매의 소매를 꽉 쥐었다."},{"s":"q:r71_seoharam","t":"그럼… 그럼 정리관님은 백 년 동안 그 목소리 들으려고 사람들을 거두신 거예요? 해마다 몇백 명씩요?"},{"s":"q:md_gyeonghyeon","t":"그 몇백 명도 다 외우고 있소. 첫해 정리 명부 맨 윗줄의 나무꾼 하나부터, 올해 맨 윗줄의 남명 장군까지."},{"s":"southern_remnant:galmae","t":"웃기지 마! 할배 이름도 외웠겠네! 외우면 다야? 할배는 이제 국수도 못 끓여!"},{"s":null,"t":"갈매가 소리치며 한 걸음 나섰다. 경현은 갈매를 똑바로 보았다."},{"s":"q:md_gyeonghyeon","t":"그렇소, 정찰대장. 외운다고 돌아오지 않소. 그래서 더는 늘리지 않으려는 거요. 내가 진을 맡으면 해마다 거두는 수도 내가 정하오."},{"s":null,"t":"나는 땅 밑의 이름도 부를 수 있다고 했다. 동짓밤마다 모든 고을이 부를 이 없는 이름을 나눠 맡아 부르면, 솔내도 그 안에 들 수 있다고 했다."},{"s":"q:md_gyeonghyeon","t":"위에서 부른다고 무엇이 달라지오? 그것이 굶으면 그 안의 이름은 어차피 흩어지오. 흩어지는 이름에 위에서 소리나 보태 주는 일을, 당신은 어머니를 지키는 일이라 생각하오?"},{"s":null,"t":"그 물음에 나는 바로 대답하지 못했다. 한설이 내 곁으로 나섰다. 한설의 목소리가 떨렸다."},{"s":"night_office:han","t":"스승님. 스승님 어머니는 스승님을 장독에 넣으셨습니다. 땅 밑에 붙들어 두려고 그러신 게 아니잖습니까. 살라고 넣으신 거잖습니까."},{"s":"night_office:han","t":"그분이 지금도 부르신다면, 그건 내려오라는 소리가 아닐 겁니다. 살아 있으라는 소리일 겁니다. 산 사람의 이름을 부르는 소리요."},{"s":null,"t":"경현의 얼굴이 아주 잠깐 일그러졌다. 경현은 눈을 감았다가 떴다. 눈빛이 다시 차가워졌다."},{"s":"q:md_gyeonghyeon","t":"설아. 너는 그 목소리를 들어 본 적이 없다. 나는 백 년을 들었다. 그 소리를 내 귀로 끊을 수는 없다."},{"s":null,"t":"경현이 돌상 쪽을 돌아보았다. 일곱 장 위 금빛이 고르게 타고 있었다."},{"s":"q:md_gyeonghyeon","t":"동트기까지 기다리겠소. 칸을 채우지 말고 장을 내게 넘기시오. 그러면 아무도 다치지 않소. 오늘 밤 저 도랑에 귀를 대 보시오. 나는 거짓말을 하지 않았소."},{"s":null,"t":"경현은 먹 도랑 가에 다시 앉아, 등을 돌린 채 도랑에 귀를 댔다. 우리는 돌상 곁에 모여 앉았다."}],"reward":{"xp":3000}},{"quest_id":"mdq_16","step":5,"title":"도랑에 댄 귀","goal":"맹약 마당에서 동트기 전 마지막 밤을 쉰다","need":{"at":["pact_court"],"tasks":[{"t":"rest","r":["pact_court"],"n":1}]},"lines":[{"s":null,"t":"밤이 깊었다. 청파가 먼저 일어나 먹 도랑 가로 갔다. 경현과 열 걸음 떨어진 자리에 엎드려 도랑에 귀를 댔다."},{"s":null,"t":"한참 뒤 청파가 고개를 들었는데, 얼굴이 하얬다."},{"s":"q:sn_cheongpa","t":"들려요… 진짜 들려요. 아주 멀리서 누가 웅성거려요. 아이 목소리도 있어요. 그 사람 말, 거짓말이 아니에요."},{"s":"q:sn_cheongpa","t":"우리 증조할아버지 배에 못 탄 아이들도 저 밑에 있을까요? 그럼 우리가 진을 풀면… 그 애들도 흩어지는 거예요?"},{"s":null,"t":"아무도 바로 대답하지 못했다. 단비가 오른손으로 가슴께의 쪽지를 꾹 눌렀다. 월하에게 받은, 열네 살 때 판 아이의 이름이었다."},{"s":"red_moon_cult:danbi","t":"저는 남의 이름을 땔감 삼아 서약을 해 왔어요. 그 이름들도 다 저 밑에 있을 거예요. 그런데 그 사람 말대로 하면, 해마다 땔감이 또 들어가요. 저 밑으로요."},{"s":"southern_remnant:galmae","t":"그래. 그게 답이야. 저 밑에 어머니가 있다고 위에 사는 사람을 해마다 밀어 넣어? 할배도 그렇게 들어갔어!"},{"s":null,"t":"갈매는 소리를 낮추지 않았다. 도랑 가의 경현도 그 소리를 들었을 테지만, 경현은 돌아보지 않았다."},{"s":"q:r71_seoharam","t":"그 사람은 저 밑 이름을 부를 사람이 자기 하나라고 믿어요. 그래서 혼자 백 년을 앉아 있었던 거예요. 명등제를 하면… 그 이름들을 부를 사람이 천 명이 돼요. 흩어져도, 불린 이름은 잊히지 않잖아요."},{"s":null,"t":"여운비가 칼을 무릎에 올린 채 오래 말이 없었다. 여운비는 팔뚝에 쓴 단비의 이름을 내려다보았다."},{"s":"north_league:yeo","t":"솔내 이야기를 듣고 북령 사람들이 한 말이 「다시는」이었소. 그 한마디로 종을 쳤고, 도성 하나를 지웠소."},{"s":"north_league:yeo","t":"저 사람도 지금 같은 말을 하고 있소. 다시는. 그 말이 장군을 데려가는 걸 내가 이 눈으로 봤소. 이번에는 산 사람 쪽에 서겠소."},{"s":null,"t":"모두가 나를 보았다. 나는 오래 생각했다. 경현의 말에도 거짓은 없었다."},{"s":null,"t":"나는 칸을 채우겠다고 했다. 땅 밑의 솔내를 버리는 것이 아니라, 해마다 그 이름을 위에서 부르겠다고 했다. 위에 사는 사람이 하나도 더 내려가지 않게 하겠다고 했다."},{"s":"night_office:han","t":"…나도 그쪽이다. 그분 어머니가 장독 뚜껑 위에서 부르신 건, 아들을 위에 두시려는 거였으니까."},{"s":null,"t":"흰 하늘이 아주 조금 더 하얘졌다. 동틀 녘이었다. 도랑 가의 경현이 천천히 일어섰다. 경현은 우리 얼굴만 보고도 대답을 안 것 같았다."},{"s":"q:md_gyeonghyeon","t":"…그렇구려. 당신들은 끝까지 위를 고르는구려."},{"s":null,"t":"경현이 먹 도랑에 두 손을 담갔다. 도랑의 먹물이 부르르 떨더니 경현의 손을 타고 거꾸로 기어오르기 시작했다."},{"s":null,"t":"먹물은 오르면서 점점 하얗게 바랬다. 손목을, 팔꿈치를, 어깨를 덮었다. 경현의 옷이 정리관 옷 모양 그대로 하얗게 물들었다."},{"s":null,"t":"하얀 몸 위로 수없이 많은 이름 글자가 개미 떼처럼 기어 다녔다. 글자들이 꿈틀거릴 때마다 사르륵사르륵 종이 넘기는 소리가 났다."},{"s":null,"t":"경현이 입을 열자 목소리가 여럿 겹쳐 나왔다. 노인과 아이와 여자의 목소리가 한꺼번에 울렸다. 마당 둘레의 꺼진 등롱들이 바스락거리며 더 하얗게 바랬다."},{"s":"q:sn_cheongpa","t":"저게… 저게 다 사람 이름이에요? 저 몸에 붙은 게 전부요?"},{"s":"q:r71_seoharam","t":"정리소 도랑에 고여 있던 먹이에요. 백 년 동안 거둔 이름들이요. 그걸 다 몸에 받으신 거예요."},{"s":"q:md_gyeonghyeon","t":"이제 내가 흰 밤이 되어 진을 지키겠소. 도제조 대신 내가 심지가 되겠소."},{"s":"q:md_gyeonghyeon","t":"장을 태우는 것보다 장을 이을 사람을 거두는 쪽이 확실하더구려. 당신 이름 하나만 거두면 칸을 채울 손이 없으니 해제는 영영 없소. 산 사람도 가장 적게 잃고, 땅 밑의 솔내도 잃지 않소."},{"s":null,"t":"하얀 경현의 손에 붓 한 자루가 들려 있었다. 붓끝이 붉었다. 경현이 허공에 대고 붓을 휘익 그었다."},{"s":null,"t":"붉은 줄 한 가닥이 허공을 가르며 곧장 내 쪽으로 날아왔다. 쉬이익, 바람 가르는 소리가 마당에 울렸다."},{"s":"red_moon_cult:danbi","t":"{이름} 님! 피해요!"},{"s":"southern_remnant:galmae","t":"엎드려! 엎드리라고!"},{"s":null,"t":"청파가 내 옷자락을 잡아당겼다. 나는 일곱째 칸 앞에서 몸을 틀었다. 줄은 이미 코앞이었다."},{"s":null,"t":"그 순간 회색 망토가 내 앞을 가로막았다. 여운비였다. 붉은 줄이 여운비의 오른 눈과 오른 뺨을 가로질러 촤악 그어졌다."},{"s":"red_moon_cult:danbi","t":"대장님! 대장님! 안 돼요!"},{"s":null,"t":"여운비의 오른 눈이 하얗게 바래기 시작했다. 하얀빛이 뺨을 타고 번져 내려갔다. 여운비는 무릎을 꿇으면서도 칼을 놓지 않았다."},{"s":"north_league:yeo","t":"앞장서지 말라 하지 않았소. 길잡이는… 내 일이라고."},{"s":"north_league:yeo","t":"종을 친 우리 집안 사람도 제 이름을 내놓았소. 도성 하나를 지우려고. 나는… 한 사람 지키는 데 내놓아 보고 싶었소."},{"s":null,"t":"단비가 달려와 오른팔로 여운비를 받아 안았다. 여운비의 팔뚝에 쓴 「단비」와 엿 그림 위로 단비의 눈물이 뚝뚝 떨어졌다."},{"s":"red_moon_cult:danbi","t":"대장님, 눈 감지 마세요! 제가 부를게요! 반만 들려도 크게 부를게요! 여운비! 여운비!"},{"s":"southern_remnant:galmae","t":"이 새끼가…! 감히!"},{"s":null,"t":"갈매가 칼을 뽑아 경현에게 달려들었다. 청파는 여운비 곁에 털썩 무릎을 꿇고 쿨럭이며 이름을 불렀다. 서하람이 여운비의 손목을 잡고 맥을 쟀다."},{"s":"q:r71_seoharam","t":"맥은 있어요! 아직 오른쪽만이에요! 계속 부르면 멈춰요! 계속요!"},{"s":"night_office:han","t":"스승님! 그만두십시오! 스승님!"},{"s":null,"t":"한설의 외침은 경현에게 닿지 않았다. 하얀 형체는 고개도 돌리지 않았다. 「스승님」은 경현의 이름이 아니었다."},{"s":null,"t":"나는 이를 악물고 일곱째 칸 앞으로 돌아가 섰다."},{"s":null,"t":"나는 {직업:호위=방패를 치켜들었다/월궁=활시위를 당겼다/퇴마=방울을 움켜쥐었다/의무=약낭을 허리에 단단히 동였다/봉인=부적을 펼쳐 들었다/암영=단도를 거꾸로 쥐었다/*=무기를 고쳐 쥐었다}."},{"s":null,"t":"흰 밤이 된 사람이 일곱 등을 향해 흰 소매를 활짝 펼쳤다."}],"reward":{"xp":3000}},{"quest_id":"mdq_16","step":6,"title":"이름을 떼어 내다","goal":"맹약 마당에서 백야를 쓰러뜨린다","need":{"at":["pact_court"],"tasks":[{"t":"by","mode":"story","n":1}]},"lines":[{"s":null,"t":"싸움은 붓끝에서 시작했다. 경현의 붉은 붓은 한동안 아무도 부르지 않은 사람을 골라 노렸다."},{"s":null,"t":"처음 노린 것은 청파였다. 모두 여운비를 부르는 동안 아무도 청파를 부르지 않았다. 붉은 줄이 청파의 가슴께에 그어지자 청파의 그림자가 반쯤 옅어졌다."},{"s":"red_moon_cult:danbi","t":"청파야! 청파! 등에 쓴 이름 잊으면 안 돼요! 청파!"},{"s":"southern_remnant:galmae","t":"청파! 이 꼬맹이, 정신 차려! 청파!"},{"s":null,"t":"두 사람의 금빛 입김이 한꺼번에 날아가 청파의 가슴에 닿았다. 붉은 줄이 먹물처럼 번지다가 사르르 지워졌다. 청파가 숨을 헐떡이며 고개를 끄덕였다."},{"s":"q:r71_seoharam","t":"저 붓, 오래 안 불린 사람부터 노려요! 돌아가며 불러요! 아무도 오래 안 불린 채로 두면 안 돼요! 시간표처럼요!"},{"s":null,"t":"장무현의 화로 곁에서 짰던 시간표였다. 우리는 그 순서대로 서로를 불렀다. 노릴 사람이 없자 붉은 붓이 머뭇거렸다."},{"s":null,"t":"경현이 흰 소매를 휘둘렀다. 소매가 자리 하나의 등롱 위로 덮쳐 내렸다. 덮이기 직전에 그 등롱이 파르르 깜빡였다."},{"s":"q:r71_seoharam","t":"다음은 셋째 자리예요! 깜빡여요! 예언 아니에요, 관측이에요!"},{"s":null,"t":"내가 셋째 자리로 뛰어가 등롱 앞에 섰다. 흰 소매가 내 몸에 부딪혀 튕겨 나갔다. 등롱은 꺼지지 않았다."},{"s":null,"t":"우리는 번갈아 하얀 몸을 치고 등을 지켰다. 하얀 형체가 조금씩 허물어져 내리더니, 반쯤 무너졌을 때 고개를 뒤로 홱 젖혔다."},{"s":null,"t":"겹친 목소리가 한꺼번에 비명을 질렀다. 끼이이익, 귀를 긁는 소리에 청파가 두 손으로 귀를 막았다."},{"s":null,"t":"마당의 등롱이 모두 퍽 꺼졌다. 마당이 새하얗게 바랬다. 바로 옆 사람의 얼굴도 하얗게 흐려졌다. 이름이 떠오르지 않았다."},{"s":null,"t":"나는 곁에 선 사람을 보았다. 누구인지는 알았지만, 그 사람의 이름만 혀끝에서 맴돌았다. 목소리가 두 걸음 밖으로 나가지 않았다."},{"s":null,"t":"그 사람이 소매를 걷어 내게 팔을 내밀었다. 팔뚝에 「갈매」라는 새카만 글씨가 있었다. 그 아래에 「장무현」이 적혀 있었다."},{"s":null,"t":"나는 그 이름을 소리 내어 읽었다. 갈매가 내 손등을 보고 「한설」을 읽었다. 저편에서 한설이 내 이름을 불렀다. 이웃 자리끼리 목소리가 닿기 시작했다."},{"s":null,"t":"불린 사람이 제 자리 등롱에 손을 얹자 등이 다시 켜졌다. 그 순간 경현의 몸에서 이름 하나가 떨어져 나와 금빛 가루로 흩어졌다."},{"s":"q:r71_seoharam","t":"등이 켜질 때마다 이름이 떨어져요! 저 몸에 붙은 이름을 우리가 불러 주면 떨어져요!"},{"s":null,"t":"갈매가 남명 자리 등롱 앞에 섰다. 갈매는 팔뚝의 둘째 줄을 읽었다. 목이 쉬어 갈라진 소리였다."},{"s":"southern_remnant:galmae","t":"장무현! 할배! 장무현!"},{"s":null,"t":"경현의 가슴께에서 「장무현」 세 글자가 꿈틀했다. 글자가 하얀 몸에서 떨어져 금빛으로 날아올랐다. 남명 자리 등롱이 화르르 켜졌다."},{"s":null,"t":"그 불빛 속에서 장무현을 닮은 낮은 목소리가 들렸다. 「남명이 부른다. 내 백성은 내가 부른다.」 갈매가 그 자리에 주저앉아 엉엉 울었다."},{"s":null,"t":"북령 자리는 여운비의 자리였다. 여운비는 단비의 품에 안긴 채 그 등롱 쪽으로 손을 뻗었다. 오른 얼굴이 반쯤 하얬다."},{"s":"north_league:yeo","t":"단비. 내 망토 안쪽에… 접힌 종이가 있소. 읽어 주시오."},{"s":null,"t":"단비가 망토 안쪽에서 꺼낸 것은 여사온의 편지였다. 단비가 그 끝줄의 이름을 읽어 주자, 여운비가 남은 목소리로 따라 불렀다."},{"s":"north_league:yeo","t":"여사온. 작은증조할아버지. 여사온…"},{"s":null,"t":"하얀 몸의 등줄기에서 「여사온」이 떨어져 나왔다. 북령 자리 등롱이 켜졌다. 「북령이 부른다. 다시는, 이 아니라 이번에는.」 여운비가 그 소리를 듣고 눈을 감았다."},{"s":null,"t":"단비는 월하에게 받은 쪽지를 폈다. 열네 살 때 서약에 쓴 아이의 이름이었다. 단비는 처음 소리 내어 그 이름을 불렀다. 적월 자리 등롱이 켜졌다."},{"s":null,"t":"청파는 등에 쓴 이름들을 다 놔두고 품에서 명단을 꺼냈다. 배 밑창에서 건져 올린 「태우지 못한 아이들」의 명단이었다. 청파는 기침을 하며 한 이름씩 불렀다. 수향 자리 등롱이 켜졌다."},{"s":null,"t":"서하람은 관상대에서 베낀 기록에서 등도 등롱의 이름들을 읽었다. 천명 자리 등롱이 켜지며 「천명이 부른다. 별이 아니라 사람이 정한다」 하는 목소리가 울렸다."},{"s":null,"t":"한설은 정청 자리 앞에 섰다. 한설이 부른 것은 동료 셋의 이름이었다. 고친 보고서 때문에 거둬진 사람들이었다. 정청 자리 등롱이 켜졌다."},{"s":null,"t":"마지막 흑련 자리는 내가 섰다. 일행 가운데 흑련에서 온 사람은 없었다. 경현의 어깨께에 낯익은 두 글자가 기어 다니고 있었다."},{"s":null,"t":"「서하」였다. 묵창 나루에서 다온이 공책에 날마다 적던 이름이었고, 어린 월하가 옆집 형과 함께 돌보던 아이의 이름이었다."},{"s":null,"t":"정청이 거둬 간 그 아이의 이름도 이 먹 속에 있었다. 나는 「서하」 하고 그 이름을 불렀다."},{"s":null,"t":"「서하」가 경현의 어깨에서 떨어져 나왔다. 금빛 가루 속에서 아이 목소리가 「서율 오라버니!」 하고 외쳤다. 아홉 칸 뜰의 기억 조각 속에서 들었던 목소리였다. 흑련 자리 일곱째 등롱이 켜졌다."},{"s":null,"t":"일곱 등이 다 켜지자 마당에 저녁 빛깔이 번졌다. 경현의 하얀 몸에서 이름들이 우수수 떨어졌다. 금빛 가루가 눈처럼 날렸다."},{"s":null,"t":"하얀 몸에는 이름 몇 줄만 남았다. 마흔두 집의 이름이었다. 그 맨 위에 한 사람의 이름이 있었다. 아무도 그 이름들을 몰랐다. 부를 수 있는 사람은 경현 하나뿐이었다."},{"s":null,"t":"경현은 무릎을 꿇었다. 겹친 목소리 사이로 경현 자신의 목소리가 그 이름들을 외고 있었다. 솔내 훈장과 솔내 아이들과, 훈장 댁 막내딸이던 어머니의 이름이었다."},{"s":"q:md_gyeonghyeon","t":"…이것만은 못 내주오. 이것만은. 이게 다 떨어지면… 나를 부르는 사람이 없소."},{"s":null,"t":"한설이 무어라 부르려다 입을 다물었다. 한설의 입에서 나올 말은 또 「스승님」이었다."},{"s":null,"t":"나는 일곱째 칸 앞에서 걸어 나가 경현 앞에 섰다. 백 년 동안 아무도 부르지 않은 이름이 하나 있었다. 장독 밤 뒤로 어머니가 부른 것이 마지막이었다."},{"s":null,"t":"나는 그 이름을 불렀다. 「경현」 하고, 똑똑히 불렀다."},{"s":null,"t":"금빛 입김 한 가닥이 하얀 가슴에 닿았다. 겹쳐 울리던 목소리들이 뚝 멈췄다. 하얀 얼굴 위에 사람의 얼굴이 천천히 떠올랐다."},{"s":null,"t":"경현이 고개를 들었다. 쉰 남짓한 교수관의 얼굴이었다. 그 눈에서 먹물 같은 눈물이 흘러내렸다."},{"s":"q:md_gyeonghyeon","t":"…백 년 만이오. 누가 땅 위에서 내 이름을 불러 준 것은."},{"s":null,"t":"경현이 제 가슴에 남은 이름들을 내려다보았다. 경현은 그 이름을 하나씩 소리 내어 불렀다. 솔내 훈장의 이름, 장독 곁 이웃집 아이들의 이름이었다."},{"s":null,"t":"불릴 때마다 이름 한 줄이 먹 몸에서 떨어졌다. 그 이름들은 금빛으로 날아오르지 않고, 반딧불처럼 깜박이며 먹 도랑 쪽으로 가라앉았다. 땅 밑의 제 고을로 돌아가는 것 같았다."},{"s":null,"t":"마지막 한 줄이 남았다. 경현은 그 이름을 오래 바라보았다. 경현이 그 이름을 부르는 목소리는 열 살 아이처럼 가늘었다. 「연실.」 솔내 훈장 댁 막내딸, 어머니의 이름이었다."},{"s":null,"t":"그 이름도 몸에서 떨어져 도랑으로 가라앉았다. 경현이 손을 뻗었다가 그만뒀다. 하얀빛이 다 걷힌 경현의 몸은 새카만 먹빛이었다."}],"reward":{"xp":3000}},{"quest_id":"mdq_16","step":7,"title":"일곱째 칸","goal":"맹약 마당에서 여운비 곁에 모여 이름을 부르며 쉰다","need":{"at":["pact_court"],"tasks":[{"t":"rest","r":["pact_court"],"n":1}]},"lines":[{"s":null,"t":"단비와 청파와 갈매와 서하람이 여운비를 둘러싸고 그 이름을 불렀다. 금빛 실 넷이 여운비의 가슴께에 닿았다. 하얗게 바래 가던 뺨이 그 자리에서 멈추었다."},{"s":null,"t":"여운비의 오른 눈은 하얗게 굳어 있었다. 여운비는 깊이 잠든 듯 숨만 쉬었다. 단비가 여운비의 왼쪽 귀에 대고 계속 불렀다."},{"s":"red_moon_cult:danbi","t":"대장님 깨면 제가 놀릴 거예요. 붉은 줄 하나 못 피했다고요. 그러니까 깨셔야 해요."},{"s":null,"t":"경현은 먹 도랑 가에 앉아 있었다. 몸은 아직 먹빛이었다. 손끝이 조금씩 도랑 쪽으로 흘러내리고 있었다. 경현은 도랑 깊은 데를 내려다보며 귀를 기울였다."},{"s":null,"t":"한설이 경현 곁에 무릎을 꿇었다. 한설은 아무 말도 하지 못했다. 경현이 한설의 손등에 쓰인 「{이름}」을 보았다."},{"s":"q:md_gyeonghyeon","t":"설아. 저 조사원 이름을 써 두었구나. 잘했다. 잊지 않게."},{"s":"night_office:han","t":"…스승님 이름도 써 둘 걸 그랬습니다."},{"s":"q:md_gyeonghyeon","t":"이제 됐다. 한 번 불렸으니."},{"s":null,"t":"경현이 나를 보았다. 지친 눈이었지만, 원망은 없었다."},{"s":"q:md_gyeonghyeon","t":"칸을 채우시오. 나는 졌소. 다만 하나만 약속해 주시오. 장날에 부름꾼이 다시 앉거든, 쌀 두 섬 없는 고을을 먼저 찾아가 주시오."},{"s":null,"t":"나는 그러겠다고 했다. 동짓밤마다 솔내의 이름도 부르겠다고 했다. 경현은 대답 대신 장부 모서리를 접던 손가락을 오므렸다. 손에는 장부가 없었다."},{"s":null,"t":"나는 돌상 앞에 섰다. 일곱째 장 한가운데 긁힌 칸이 비어 있었고, 칸 머리에 「부르는 이」라고 적혀 있었다."},{"s":null,"t":"나는 붓을 들었다가 멈췄다. 그 칸은 한 사람의 이름으로 채울 칸이 아니었다."},{"s":null,"t":"한설이 내 곁에 와 붓을 받아 들었다. 한설은 칸 한구석에 내 이름을 적었다."},{"s":"night_office:han","t":"네 이름을 부를 사람은 여기 있다. 정청 감찰관이 장부에 적는다."},{"s":null,"t":"한설이 붓을 단비에게 넘겼다. 단비는 오른손으로 여운비의 이름을 적었다. 청파가 단비의 이름을, 갈매가 서하람의 이름을, 서하람이 갈매의 이름을 적었다."},{"s":null,"t":"갈매가 잠든 여운비의 손에 붓을 쥐여 주었다. 갈매가 그 손을 감싸 쥐고 청파의 이름을 함께 썼다. 획이 흔들렸지만 끝까지 이어졌다."},{"s":null,"t":"붓이 내게 돌아왔다. 칸에는 이미 여러 이름이 서로를 부르듯 적혀 있었다. 나는 그 이름들 사이에, 지금까지 나를 불러 준 사람들을 떠올렸다."},{"s":null,"t":"그 순간 아주 먼 곳에서 목소리가 들려왔다. 수많은 곳에서 동시에 들려왔다."},{"s":null,"t":"홍인사 때 만난 사람들이 불렀다. 구등대 군도의 도화가 불렀고, 아홉째 문 안쪽의 윤도한이 불렀다. 귀허도 반요촌의 여울과 단이가 불렀다."},{"s":null,"t":"묵창 나루의 희수가 불렀고, 흑련 장부고의 월하가 불렀다. 아주 먼 데서 서율과 서하의 목소리도 들렸다. 석진악과 월화와 진소랑과 하후정과 서이연이 불렀다. 다온의 목소리가 가장 컸다."},{"s":null,"t":"금빛 실 수백 가닥이 맹약 마당 위로 쏟아져 들어왔다. 실들이 돌상의 원에 닿을 때마다 찌잉, 종이 우는 소리가 났다."},{"s":"q:sn_cheongpa","t":"들려요… 다들 부르는 게 들려요! 소리가 멀리 가요!"},{"s":null,"t":"경현이 고개를 들어 그 실들을 보았다. 경현의 입술이 「어머니」라고 움직였지만, 소리는 나지 않았다."},{"s":null,"t":"나는 칸의 마지막 자리에 「모두」라고 적었다. 그 곁에 「솔내」 두 글자를 작게 더 적었다."}],"reward":{"xp":3000,"gil":520,"items":{"pact_stone_dust":2,"lamp_wick_core":2}}},{"quest_id":"mdq_17","step":1,"title":"재가 되는 일곱 장","goal":"맹약 마당에서 쉬고 일곱 장이 재가 되는 것을 본다","need":{"at":["pact_court"],"tasks":[{"t":"rest","r":["pact_court"],"n":1}]},"lines":[{"s":null,"t":"돌상 위의 일곱 장이 금빛 원으로 이어진 채 하나씩 불꽃이 꺼져 갔다. 첫째 장의 금빛이 꺼지자 종이가 가장자리부터 사르르 재로 바스러졌다."},{"s":null,"t":"둘째, 셋째 장이 뒤를 이었다. 재는 흰빛 속으로 흩어지지 않고, 금빛 가루가 되어 마당 위를 천천히 떠돌았다."},{"s":"q:sn_cheongpa","t":"타요… 장이 타요. 우리가 그렇게 모은 건데…"},{"s":"red_moon_cult:danbi","t":"괜찮아요. 타야 풀리는 거래요. 하람 씨가 그랬잖아요."},{"s":null,"t":"여섯째 장이 타기 시작하자 서하람이 비틀거렸다. 서하람은 두 손으로 눈을 감싸 쥐었고, 손가락 사이로 하얀빛이 새어 나왔다."},{"s":"q:r71_seoharam","t":"아… 아아…!"},{"s":"q:sn_cheongpa","t":"하람 형님, 눈…! 눈이 하얘요! 천명 장이 타서 그래요!"},{"s":"red_moon_cult:danbi","t":"관측관님! 손 떼 봐요, 관측관님!"},{"s":"q:r71_seoharam","t":"…알고 있었어요. 할머니가 그랬잖아요. 별이 타면 보던 눈도 같이 간다고요. 괜찮아요… 괜찮… 아, 뜨거워요…!"},{"s":null,"t":"갈매가 달려들어 서하람을 와락 끌어안았다. 서하람의 몸이 갈매의 품 안에서 바들바들 떨렸다."},{"s":"southern_remnant:galmae","t":"잠꾸러기! 야, 잠꾸러기! 눈 감지 마! …아니, 감아도 돼! 감아도 내가 부를 거니까!"},{"s":"q:r71_seoharam","t":"별이… 제 별이 타요. 갈매 씨, 어젯밤 약속… 기억하죠…"},{"s":"southern_remnant:galmae","t":"서하람! 서하람! 별 따위 없어도 돼! 내가 불러 줄게! 듣기 싫어도 들어! 서하람!"},{"s":null,"t":"갈매는 관상대에서, 그리고 어젯밤 화로 곁에서 약속한 대로 가장 먼저, 가장 크게 불렀다. 단비가 오른손으로 서하람의 손을 잡고 「하람 씨!」 하고 불렀다. 청파가 쿨럭이며 「하람 형님!」 하고 불렀고, 한설도 불렀다. 나도 「하람」 하고 불렀다."},{"s":null,"t":"서하람의 가슴께로 금빛 실이 수없이 날아들었다. 별에 묶여 있던 명줄이 금빛 실을 따라 사람 쪽으로 옮겨 묶이는 것이 보였다."},{"s":null,"t":"별의 하얀빛이 서하람의 가슴께로 내려와 작은 불씨로 바뀌었다. 내가 손끝을 대 보니 따뜻했다."},{"s":null,"t":"서하람이 손을 내렸다. 그 두 눈이 하얗게 바래 있었다. 서하람은 눈을 깜빡이며 갈매 목소리가 나는 쪽으로 얼굴을 돌렸다."},{"s":"q:r71_seoharam","t":"…갈매 씨 목소리가 들려요. 그런데 얼굴이 안 보이네요."},{"s":"southern_remnant:galmae","t":"보여. 내가 여기 있어. 바로 앞에 있어. 손 줘 봐."},{"s":null,"t":"갈매가 서하람의 손을 끌어다 제 뺨에 댔다. 서하람의 손끝이 갈매의 젖은 뺨을 더듬었다."},{"s":"q:r71_seoharam","t":"울고 있네요. 갈매 씨가 우는 건 처음 관측해요. 별은 이제 못 보겠어요. 괜찮아요. 관측은… 이제 갈매 씨가 해 주면 되잖아요."},{"s":null,"t":"갈매는 대답하지 못하고 서하람을 더 세게 끌어안았다. 갈매의 어깨가 덜덜 떨렸다."},{"s":null,"t":"단비가 여운비 쪽을 돌아보았다. 여운비는 여전히 잠들어 있었다. 단비가 그 왼쪽 귀에 대고 속삭였다."},{"s":"red_moon_cult:danbi","t":"대장님, 하람 씨 눈이 멀었어요. 대장님은 한쪽이라도 남겨 오세요. 꼭이요."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":2,"title":"문틈","goal":"맹약 마당에서 서하람과 여운비 곁을 지키며 쉰다","need":{"at":["pact_court"],"tasks":[{"t":"rest","r":["pact_court"],"n":1}]},"lines":[{"s":null,"t":"마지막 일곱째 장이 재가 되어 날리는 순간 땅이 크게 울렸다. 우르르르, 돌바닥이 발밑에서 흔들렸다."},{"s":null,"t":"마당 돌바닥의 틈마다 검은 물이 솟구쳤다. 이번에는 하얗게 바래지 않은 진짜 검은 물이었다. 마당 가장자리 우물에서 물이 콸콸 넘쳐흘렀다."},{"s":"night_office:han","t":"진이 꺼졌다… 굶은 것이 마지막으로 문을 미는 거다. 직할령 우물들도 지금 이럴 거다!"},{"s":"q:sn_cheongpa","t":"그럼 어떡해요? 이대로면… 솔내처럼요?"},{"s":null,"t":"아무도 대답하지 못했다. 그때 먹 도랑 가에 앉아 있던 경현이 일어섰다. 먹빛 몸 끝에서 먹이 뚝뚝 떨어졌다."},{"s":"q:md_gyeonghyeon","t":"큰 꺼진 이름 하나면 문틈은 막히오. 백 년 동안 만삼천 이름을 거둔 내 이름이면 충분하오. 그것도 나 하나를 삼키면 한동안은 배가 부를 거요."},{"s":null,"t":"한설이 달려가 경현의 먹빛 손목을 붙잡았다. 손바닥에 먹이 묻어났지만, 한설은 손을 놓지 않았다."},{"s":"night_office:han","t":"안 됩니다. 이번엔 안 됩니다. 셈은 이제 그만하십시오!"},{"s":"q:md_gyeonghyeon","t":"셈이 아니다, 설아. 이번에는 셈이 아니야."},{"s":null,"t":"경현이 한설의 손등을 가볍게 두드렸다. 처음 붓 잡는 법을 가르치던 손길이었다. 경현은 먹 도랑 깊은 데를 내려다보았다."},{"s":"q:md_gyeonghyeon","t":"저 아래서 아직 부르고 있다. 「경현아」 하고. 백 년을 귀만 대고 있었지. 이제 내가 내려가서 곁에 있겠다."},{"s":"q:md_gyeonghyeon","t":"이번엔 숫자 말고, 이름으로."},{"s":null,"t":"경현이 나를 보았다. 이어서 갈매와 서하람과 청파와 단비를, 마지막으로 잠든 여운비를 한 사람씩 보았다."},{"s":"q:md_gyeonghyeon","t":"정찰대장. 장군께 미안하다고 했던 말은 거두지 않겠소."},{"s":"q:md_gyeonghyeon","t":"관측관. 스무 해 전 당신 별을 숨기던 할머님 손이 떨렸던 걸 나는 봤소. 할머님께 잘해 드리시오."},{"s":"southern_remnant:galmae","t":"…할배는 너 용서 안 했어. 그래도 원망도 안 했어. 나도 그렇게 할게. 그게 다야."},{"s":"q:md_gyeonghyeon","t":"그거면 과분하오."},{"s":"q:md_gyeonghyeon","t":"조사원. 장날에 부름꾼이 다시 앉거든 쌀 두 섬 없는 고을부터 찾아가 달라는 약속, 내려가서도 듣고 있겠소."},{"s":null,"t":"나는 잊지 않겠다고 했다. 경현이 고개를 끄덕였다."},{"s":"q:md_gyeonghyeon","t":"정리소 책상 맨 아래 서랍에 장부 한 권이 있다, 설아. 마지막 장에 솔내 사람들 이름이 있다. 우리 어머니 이름도. 동짓밤에 한 번씩만 읽어 다오."},{"s":null,"t":"경현이 먹 도랑으로 걸어 들어갔다. 한 걸음 내디딜 때마다 발끝부터 먹으로 풀렸다. 풀린 먹이 검은 물 속으로 스며들었다."},{"s":null,"t":"경현의 무릎이 잠기고, 허리가 잠겼다. 한설이 도랑 가에 무릎을 꿇었다. 한설의 입술이 떨렸다."},{"s":"night_office:han","t":"…경현."},{"s":null,"t":"한설이 처음으로 부른 이름이었다. 「스승님」이 아니었다. 금빛 입김 한 가닥이 날아가 가라앉는 경현의 가슴께에 닿았다."},{"s":null,"t":"경현이 걸음을 멈추고 돌아보았다. 먹빛 얼굴에 웃음이 번졌다. 비꼬는 기색이 하나도 없는 웃음이었다."},{"s":"q:md_gyeonghyeon","t":"고친 글씨는 먹이 두 번 앉는다고 했지. 네가 부른 내 이름은… 한 번에 반듯하게 앉는구나."},{"s":null,"t":"경현의 어깨가 잠기고, 마지막으로 머리가 잠겼다. 먹이 문틈으로 흘러 들어가 검은 물을 메웠다. 우물마다 넘치던 물이 천천히 가라앉았다."},{"s":null,"t":"도랑 위에 둥근 물결 하나가 번졌다. 그 물결 아래에서 아주 작게 두 사람의 목소리가 들린 것 같았다. 한 목소리가 「경현아」 하고 불렀고, 다른 목소리가 「예」 하고 대답했다."},{"s":null,"t":"한설은 도랑 가에 엎드려 오래 움직이지 않았다. 내가 그 곁에 앉았다. 한설은 손등에 쓴 내 이름을 손가락으로 꾹 눌렀다."},{"s":null,"t":"단비가 한설의 등 뒤에 쪼그려 앉았다."},{"s":"red_moon_cult:danbi","t":"감찰관님. 저 사람 이름, 우리도 부를게요. 미워도 부를게요. 그 이름 부를 사람이 감찰관님 하나뿐이면 안 되잖아요."},{"s":null,"t":"청파가 콧물을 훌쩍이며 단비 곁에 붙어 앉았다."},{"s":"q:sn_cheongpa","t":"저도요. 옛 나루 저자에서 그 사람 배가 저를 물에서 건져 줬어요. 그건 진짜였으니까요."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":3,"title":"처음 생긴 그림자","goal":"맹약 마당에서 쉬고, 정리소를 1번 탐색해 경현이 남긴 장부를 찾는다","need":{"at":["jeongni_vault"],"tasks":[{"t":"rest","r":["pact_court"],"n":1},{"t":"search","r":["jeongni_vault"],"n":1}]},"lines":[{"s":null,"t":"정리소 책상 맨 아래 서랍에 장부 한 권이 있었다. 모서리가 수없이 접혀 있었다. 한설이 그 장부를 품에 안았다."},{"s":null,"t":"가늠 저울은 멈춰 있었다. 저울 옆 촛불 일곱이 모두 꺼져 있었다. 먹 도랑의 먹물은 더 흐르지 않았다."},{"s":null,"t":"정리소 구석에 먹손들이 모여 앉아 있었다. 발밑에 그림자가 돌아와 있었고, 손끝의 먹빛도 바래 있었다."},{"s":null,"t":"곽두칠도 그 가운데 있었다. 곽두칠은 제 손바닥을 등잔불에 비춰 보고 또 비춰 보았다."},{"s":"q:md_gwak_duchil","t":"줄이… 없어졌습니다. 반만 그어진 줄이 다 지워졌습니다. 그림자가 생겼습니다. 이제… 어디로 가야 합니까."},{"s":"q:r71_seoharam","t":"진이 꺼지면 거둠도 멈춰요. 미뤄 둔 줄을 마저 그을 명부도, 그을 손도 이제 없어요. 그래서 줄이 저절로 지워진 거예요."},{"s":"night_office:han","t":"집으로 가라. 이름을 불러 줄 사람한테로. 없으면 정청으로 와라. 이제 정청이 부르겠다."},{"s":"q:md_gwak_duchil","t":"저는 흑련에 빚이 있습니다. 그리고 기록관님께도요."},{"s":"night_office:han","t":"그럼 둘 다 갚아라. 흑련에는 구슬 행수가 기다린다. 기록관은 객사에 있다. 손이 굳어 붓을 못 쥐니, 네가 받아 적어 드려라."},{"s":null,"t":"우리는 지하서고 우물을 기어 올라 정청으로 갔다. 안쪽 방 등잔이 꺼져 있었다. 삼백 년 동안 기름이 줄지 않던 등잔이었다."},{"s":null,"t":"등잔이 꺼진 방 안, 문틈으로 들어오는 빛 아래 백운서가 앉아 있었다. 그 몸 아래 마룻바닥에 처음으로 그림자가 드리워져 있었다."},{"s":null,"t":"백운서의 머리칼이 하얗게 빠져 마룻바닥에 흩어져 있었다. 손등은 마른 나뭇잎처럼 쭈글쭈글했다. 삼백 년이 한꺼번에 그에게 오고 있었지만, 얼굴은 평온했다."},{"s":"night_office:baek","t":"진이 꺼졌구먼. 경현은 어찌 되었나."},{"s":null,"t":"한설이 고개를 떨군 채 장부를 내밀었다. 백운서가 장부를 펼쳤다. 마지막 장의 솔내 사람들 이름을 오래 읽었다."},{"s":"night_office:baek","t":"솔내에서 건진 그 아이를 정청에 들인 게 나였네. 그 아이가 셈방에서 저울을 처음 만들어 왔을 때, 나는 그 저울이 옳다고 여겨 칸을 긁었네. 그 뒤로 백 년 동안 그 아이 셈을 이길 말이 내게는 없었네."},{"s":"night_office:baek","t":"마지막에는 그 아이가 나보다 나았네. 남의 이름이 아니라 제 이름을 내놓았으니."},{"s":null,"t":"단비가 무릎을 꿇고 백운서의 마른 손을 잡았다. 청파는 꺼진 등잔 심지를 손끝으로 만져 보고는 입술을 깨물었다. 갈매는 문간에 서서 들어오지 않았다. 서하람은 갈매의 소매를 쥔 채 목소리 나는 쪽으로 얼굴을 돌렸다."},{"s":null,"t":"백운서의 눈길이 문간의 갈매에게 가 머물렀다. 마른 입술이 몇 번 달싹인 끝에 소리가 나왔다."},{"s":"night_office:baek","t":"장군께 미안하네. 이제 그분 이름을 부르는 사람이 자네이니, 그 말을 자네한테 하네. 내 등잔이 꺼지기 전에 하겠다고 했는데… 늦었구먼."},{"s":null,"t":"갈매의 손이 문틀을 꽉 움켜쥐었다. 한참 만에 갈매가 고개를 한 번 끄덕였다. 용서한다는 끄덕임은 아니었다. 들었다는 끄덕임이었다."},{"s":"night_office:baek","t":"등도에 가 보고 싶네. 그곳 등이 다시 켜지는 것을 내 눈으로 보고 싶네. 걸어서는 못 가겠지만."},{"s":"southern_remnant:galmae","t":"…들것은 내가 들게. 할배 모실 때도 들었어. 할배라면 들어 드리라고 할 거야."},{"s":null,"t":"갈매의 목소리는 퉁명스러웠다. 백운서는 갈매를 보고 아주 천천히 고개를 숙였다."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":4,"title":"밤이 돌아온다","goal":"들것 1개를 만들어 도제조를 모시고 꺼진 관아 터에 도착한다","need":{"at":["dark_yamen"],"tasks":[{"t":"craft","items":["md_litter"],"n":1},{"t":"travel","r":["dark_yamen"],"n":1}],"give":{"md_litter":1}},"lines":[{"s":null,"t":"우리는 백운서를 들것에 눕혀 옛 수로를 지나 등도로 들어갔다. 들것 앞쪽은 갈매가, 뒤쪽은 청파와 내가 함께 들었다."},{"s":null,"t":"한설은 잠든 여운비를 눕힌 수레를 끌었다. 단비는 수레 곁을 걸으며 오른손으로 여운비의 손을 놓지 않았다."},{"s":null,"t":"서하람은 갈매의 허리띠를 붙잡고 걸었다. 돌계단 앞에서 갈매가 「계단 다섯」 하고 일러 주면, 서하람이 한 칸씩 발로 더듬어 올랐다."},{"s":null,"t":"수로 끝 돌계단을 올라서자 처음 등도에 왔을 때와는 다른 것이 보였다. 하늘이 어두워지고 있었다."},{"s":null,"t":"일흔 해 동안 하얗게 바래 있던 하늘에 푸른 기운이 번졌다. 그 푸른빛이 점점 짙어져 밤하늘이 되었다. 그 밤하늘에 별이 하나, 둘 떠올랐다."},{"s":null,"t":"허공에 멈춰 있던 물방울들이 한꺼번에 떨어졌다. 후두둑, 처마 끝에서 똑, 똑 물 떨어지는 소리가 났다. 소리가 멀리 퍼져 나갔다."},{"s":"q:sn_cheongpa","t":"밤이에요… 진짜 밤이에요! 하람 형님, 별이 떴어요! 하늘에 별이요!"},{"s":"q:r71_seoharam","t":"…몇 개예요?"},{"s":null,"t":"청파가 하늘을 보다 입을 다물었다. 갈매가 서하람의 손을 끌어 북쪽 하늘을 가리키게 했다."},{"s":"southern_remnant:galmae","t":"많아. 셀 수 없을 만큼. 저기 북쪽에 제일 밝은 게 하나 있어."},{"s":null,"t":"처마마다 걸린 등롱이 하나씩 불을 밝혔다. 기름도 없는데, 이름 글자가 바랜 등롱마다 화르르 저절로 불이 켜졌다."},{"s":"night_office:han","t":"등롱마다 이름이 적혀 있다… 일흔 해 전에 거둬진 사람들이다."},{"s":"q:sn_cheongpa","t":"그럼 그분들이 돌아오신 거예요?"},{"s":"night_office:han","t":"아니다. 그 이름을 기억하는 등이 켜진 거다. 사람은… 돌아오지 않는다."},{"s":null,"t":"청파가 품에서 기름종이 꾸러미를 꺼냈다. 무관 거리에서 주워 모은 바랜 등롱 종이 열한 장, 그리고 경현이 주워 건넨 한 장이었다."},{"s":null,"t":"등롱 불빛이 종이에 닿자 하얗게 바랬던 글자에 먹빛이 천천히 돌아왔다. 청파가 종이를 한 장씩 불빛에 비춰 들었다."},{"s":"q:sn_cheongpa","t":"읽혀요… 나중엔 읽을 수 있을 거라고 했잖아요. 진짜 읽혀요."},{"s":null,"t":"청파는 열한 이름을 숨을 아껴 가며 하나씩 불렀다. 남은 한 장은 동문 밖 두부집 둘째 아들의 이름이었다. 경현이 불렀을 때는 금빛이 나오지 않던 이름이었다. 청파가 부르자 금빛 입김 한 가닥이 등롱 쪽으로 날아갔다."},{"s":null,"t":"들것 위의 백운서가 눈을 떴다. 켜지는 등을 하나하나 바라보던 백운서가 입을 열었다. 목소리는 가늘었지만 똑똑히 들렸다."},{"s":"night_office:baek","t":"여사온. 등도의 명등지기 윤슬. 솔내 훈장 댁 막내딸 연실. 그리고 청씨 배에 못 탄 아이들, 그 명단의 첫 줄… 차돌."},{"s":null,"t":"청파가 들것 손잡이를 쥔 채 우뚝 섰다. 청파의 입술이 떨렸다."},{"s":"q:sn_cheongpa","t":"…명단 맨 첫 줄 이름이에요. 진 꺼지는 날 부르신다더니… 진짜 부르셨어요."},{"s":null,"t":"백운서가 부른 이름 넷이 밤하늘 아래 울렸다. 칠십 년 전 여사온에게 한 약속과, 정청 안쪽 방에서 청파에게 한 약속이 같은 밤에 지켜졌다. 백운서는 그 이름들을 부른 뒤 눈을 감았다."},{"s":"night_office:baek","t":"정청에는… 내 이름을 부를 사람이 없네."},{"s":null,"t":"단비가 가장 먼저 백운서의 이름을 불렀다. 우리가 따라 불렀다. 한설이 불렀고, 청파가 불렀고, 갈매가 마지막에 작게 불렀다."},{"s":null,"t":"금빛 입김이 밤하늘 아래 가늘게 피어올라 백운서의 가슴께에 닿았다. 백운서는 눈을 감은 채 그 따뜻함을 느끼며 웃었다. 백운서는 다시 눈을 뜨지 않았다."},{"s":null,"t":"한설이 백운서의 손을 이불 안에 넣어 주었다. 왼손 약지의 먹 자국이 처음으로 옅어져 있었다."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":5,"title":"볼로 읽는 바람","goal":"꺼진 관아 터에서 도제조를 보내는 밤을 쉰다","need":{"at":["dark_yamen"],"tasks":[{"t":"rest","r":["dark_yamen"],"n":1}]},"lines":[{"s":null,"t":"우리는 관아 뒤뜰 느티나무 아래에 백운서를 묻었다. 여운비가 깨어난 것은 그 이튿날이었다. 단비가 사흘 밤낮을 곁에서 이름을 부른 뒤였다."},{"s":null,"t":"여운비의 오른 눈은 하얗게 바래 있었다. 오른 뺨에 흰 줄 같은 자국이 남아 있었다."},{"s":null,"t":"여운비는 일어나 앉자마자 습관처럼 칼을 집어 들었다. 칼자루 끝의 붉은 술을 보려다 고개를 갸웃했다. 오른쪽이 보이지 않았다."},{"s":null,"t":"여운비는 손가락으로 술을 더듬었다. 그러다 손을 내리고 고개를 돌려 오른 뺨을 밤바람 쪽으로 내밀었다. 등도에 처음으로 바람이 불고 있었다."},{"s":"north_league:yeo","t":"…눈으로는 이제 못 보겠소. 그래도 볼로는 읽을 수 있구려. 동쪽에서 부는 바람이오."},{"s":"red_moon_cult:danbi","t":"대장님! 대장님 깼어요! 다들 와요, 대장님 깼어요!"},{"s":null,"t":"갈매가 서하람을 데리고 달려왔다. 청파가 기침을 하며 뛰어왔다. 한설이 장부를 덮고 일어섰다. 나도 여운비 곁에 앉았다."},{"s":"q:sn_cheongpa","t":"대장님! 저 대장님 이름 진짜 많이 불렀어요! 목이 다 쉬었어요!"},{"s":"north_league:yeo","t":"들렸소. 반쯤 쉰 목소리가 계속 들리더이다. 시끄러워서 깬 거요."},{"s":null,"t":"단비가 여운비의 왼쪽에 앉았다. 단비의 성한 오른쪽 귀가 여운비 쪽을 향했고, 여운비의 성한 왼 눈이 단비 쪽을 향했다."},{"s":"red_moon_cult:danbi","t":"대장님, 이제 앞장은 못 서시겠네요. 오른쪽이 안 보이시니까. 붉은 줄 하나 못 피하시고요."},{"s":"north_league:yeo","t":"…그렇소. 길잡이는 내려놓겠소. 대신 옆에서 걷겠소. 당신 오른쪽에서. 당신이 잘 들리는 쪽으로."},{"s":null,"t":"단비가 웃음을 터뜨렸다. 웃음소리가 밤하늘 끝까지 퍼져 나갔다. 등도에서는 이제 소리가 멀리 갔다."},{"s":null,"t":"여운비가 나를 돌아보았다. 남은 왼 눈이 나를 똑바로 보았다."},{"s":"north_league:yeo","t":"조사원. 마당에서 앞에 섰던 거, 사과는 안 하겠소. 다시 그 자리에 서도 또 그럴 거요."},{"s":null,"t":"나는 사과 대신 고맙다고 했다. 다음에는 내가 먼저 앞에 서겠다고 했다."},{"s":"north_league:yeo","t":"그럼 그때는 내가 뒤에 서겠소. 앞에 선 사람이 바람을 못 읽거든, 뒤에서 볼로 읽어 드리리다."},{"s":null,"t":"한설이 품에서 서신 한 통을 꺼냈다. 흑련 심부름꾼이 옛 수로로 가져온 서신이었다. 한설이 서신을 펴 소리 내어 읽었다."},{"s":"q:mk_daon","t":"「{이름} 님. 구중 봉연 문지기 아저씨가 장부고 도랑으로 말을 걸어왔어요. 문이 조용해졌대요. 그래도 누가 와 줬으면 좋겠대요. 문 둘레에 아직 먹 낀 것들이 어슬렁거린대요.」"},{"s":"night_office:han","t":"윤도한이다. 진이 꺼졌으니, 그 사람이 문 안쪽에 남을 까닭이 없다. 데리러 가자."},{"s":null,"t":"여운비가 칼을 허리에 차고 일어섰지만, 걸음이 아직 조금 비틀거렸다."},{"s":"north_league:yeo","t":"가 봅시다. 단비, 내 왼쪽에 서시오. 그래야 내가 당신을 보고, 당신이 내 말을 듣소."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":6,"title":"문지기","goal":"구중 봉연에 도착해 가라앉은 문 둘레에 남은 흰 밤 서리 떼를 3번 쓸어 낸다","need":{"at":["sealed_abyss"],"tasks":[{"t":"travel","r":["sealed_abyss"],"n":1},{"t":"win","n":3,"m":["dd_pact_2"],"r":["sealed_abyss"]}]},"lines":[{"s":null,"t":"아홉째 문 둘레에 남아 있던 것은 흰 밤 서리 떼였다. 서리 떼는 문 아래 가라앉은 검은 물에서 피어올랐다가, 쓸어 낼 때마다 한 겹씩 바래며 흩어졌다."},{"s":null,"t":"구중 봉연의 아홉째 문은 조용했다. 문 위 바위 천장의 일곱 점 불빛은 모두 꺼져 있었다. 문 아래로 솟던 검은 물은 가라앉아 있었다."},{"s":null,"t":"문틈에는 먹이 단단하게 굳어 있었다. 경현이 메운 자리였다. 한설이 그 먹에 손바닥을 댔다. 차갑지 않고 미지근했다."},{"s":"night_office:han","t":"…아직 따뜻하다. 이름 글자에 손을 대면 미지근하다더니."},{"s":null,"t":"한설이 문을 두드렸다. 한참 뒤에 문 안쪽에서 목소리가 들려왔다. 정리소 도랑으로 들었던 그 목소리였다."},{"s":"q:m_yun","t":"조용해졌습니다. 문을 미는 것이 이제 약합니다. 굶고 있는 모양입니다. 그리고 문틈에서… 누가 사람 이름을 부르는 소리가 들립니다. 둘이서 번갈아 가며."},{"s":null,"t":"한설의 어깨가 움찔했다. 한설은 문에 이마를 댔다."},{"s":"night_office:han","t":"진이 없으니 문 안쪽에 남으실 까닭도 없습니다. 나오십시오. 정청에서 이름을 다시 적어 드리겠습니다."},{"s":"q:m_yun","t":"고맙습니다. 그래도 저는 여기 남겠습니다. 굶은 것이 다시 배고파지면 문을 밀 겁니다. 누군가는 문 앞에서 이름을 불러야지요."},{"s":"q:m_yun","t":"해마다 동지에, 문 안쪽에서도 부르는 사람이 하나쯤 있는 게 좋지 않겠습니까. 문틈의 그 두 사람한테도 말벗이 있어야 하고요."},{"s":null,"t":"갈매가 구리 화로 뚜껑을 열고 흰 불씨 한 점을 덜어 냈다. 갈매는 그 불씨를 문 앞 바위 틈 작은 등잔에 옮겨 붙였다. 흰 불빛이 문틈 먹을 비추었다."},{"s":"southern_remnant:galmae","t":"할배 불씨야. 화로는 관아 터에 둘 거고, 여기엔 불씨만 두고 갈게. 동지마다 와서 갈아 줄 거야. 남명이 불 지키는 건 잘해."},{"s":"q:sn_cheongpa","t":"그럼 저는 배를 댈게요. 동지마다 사람들 태워서 여기까지 오게요. 이제 잠수는 못 하지만, 노는 저을 수 있으니까요."},{"s":null,"t":"한설은 경현의 장부를 펼쳤다. 문 안쪽에 들리도록, 솔내 사람들의 이름을 하나씩 소리 내어 읽기 시작했다."},{"s":null,"t":"서하람은 문 앞에 앉아 손을 무릎에 얹고 들었다. 여운비는 약속대로 단비의 오른쪽에 붙어 섰고, 두 사람이 한설의 목소리를 따라 이름을 받았다."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":7,"title":"펴는 쪽지","goal":"구중 봉연에서 쉬고 흑련 장부고에 도착한다","need":{"at":["ledger_cellar"],"tasks":[{"t":"rest","r":["sealed_abyss"],"n":1},{"t":"travel","r":["ledger_cellar"],"n":1}]},"lines":[{"s":null,"t":"흑련 장부고의 금고 문이 활짝 열려 있었다. 무명이 처음으로 장부를 펼쳐 맡아 둔 이름들을 회원들에게 하나씩 돌려주고 있었다."},{"s":null,"t":"회원들은 제 이름이 적힌 종이를 받아 들고 울기도 하고 웃기도 했다. 구슬이 주판을 딸깍딸깍 튕기며 그 이름을 장부에서 하나씩 지웠다. 무명은 자기 이름이 적힌 장만은 끝까지 펴지 않았다."},{"s":"black_lotus:mumyeong","t":"흑련 회주는 무명으로 불리오. 첫 회주를 잊지 않으려고. 그 약속만은 내 대에서 지키겠소."},{"s":null,"t":"여운비가 무명 앞에 섰다. 여운비는 품에서 여사온의 편지를 꺼내 무명에게 건넸다."},{"s":"north_league:yeo","t":"마당에서도 불렀소. 일흔 해 만에 북령이 소리 내어. 이 편지는 흑련 장부에 끼워 두시오. 첫 회주의 이름 곁에."},{"s":null,"t":"무명이 편지를 받아 들었다. 검은 천 사이로 내민 손이 떨렸다. 무명은 오래 아무 말도 하지 못했다."},{"s":null,"t":"그때 안쪽 침상 쪽에서 쨍그랑, 엽전 떨어지는 소리가 났다."},{"s":null,"t":"월하는 침상에 앉아 오른손으로 엽전을 튕기는 연습을 하고 있었다. 다섯 번에 한 번은 떨어뜨렸다. 떨어뜨릴 때마다 다온이 주워 주었다."},{"s":"q:mk_wolha","t":"어서 와요. 다들 값을 좀 치르고 왔네. 눈 하나, 눈 둘, 귀 하나, 숨 반쪽."},{"s":"red_moon_cult:danbi","t":"아저씨 손가락 두 마디도요."},{"s":"q:mk_wolha","t":"그건 치른 게 아니라 떨군 거지. 엽전처럼."},{"s":null,"t":"나는 품에서 귀퉁이 이 빠진 상평통보를 꺼내 월하의 손바닥에 올려놓았다. 장부고를 떠나던 아침 월하가 맡긴 엽전이었다."},{"s":"q:mk_wolha","t":"…돌아오면 돌려 달랬더니, 진짜 돌아와서 돌려주네. 이자는 안 받는다고 했으니 이 셈은 끝."},{"s":null,"t":"월하가 이 빠진 엽전을 오른손으로 튕겼다. 엽전이 핑그르르 돌다가 손등에 반듯하게 내려앉았다. 다온이 손뼉을 짝 쳤다."},{"s":null,"t":"그때 금고 문간에서 누가 헛기침을 했다. 곽두칠이었다. 정리소에서 한설의 말을 듣고 구슬에게 빚을 갚으러 온 길이었다. 손에 낡은 빚 문서가 들려 있었다."},{"s":null,"t":"다온이 곽두칠을 보고 월하 뒤로 몸을 숨겼다. 다온은 곽두칠의 발밑을 오래 내려다보았다. 이제는 또렷한 그림자가 있었다."},{"s":"q:mk_daon","t":"…그날 밤 문 앞으로 지나간 사람이에요. 그림자가 물에 번진 것처럼 흐릿했던 사람이요."},{"s":null,"t":"나는 다온과 새끼손가락을 건 일을 떠올렸다. 나는 곽두칠에게 다온 앞에 서 달라고 했다. 곽두칠은 아무것도 묻지 않고 다온 앞에 무릎을 꿇었다."},{"s":"q:md_gwak_duchil","t":"내가 네 아저씨 이름을 찢어 갔다. 때려라. 몇 대든."},{"s":null,"t":"다온이 주먹을 쥐고 곽두칠의 어깨를 콩 때렸다. 한 대였다. 다온은 주먹을 펴고 월하를 돌아보았다."},{"s":"q:mk_daon","t":"한 대만 할래요. 약속은 한 대였으니까요. 나머지는… 아저씨 이름 도로 적어 놨으니까 안 할래요."},{"s":"q:md_gwak_duchil","t":"…그 한 대, 평생 안 잊으마."},{"s":"q:mk_wolha","t":"꼬맹이 도장 찍힌 외상은 흑련에서도 받아 준다더니, 그 셈 참 싸게 끝났네."},{"s":null,"t":"다온이 월하 앞에 섰다. 손에는 그동안 펴지 않고 쥐고 있던 봉함 쪽지가 들려 있었다."},{"s":"q:mk_daon","t":"아저씨, 이제 펴도 돼요? 아저씨는 이제 안 보이는 데로 안 가잖아요. 그래도 한 번은 아저씨 진짜 이름을 불러 보고 싶어요."},{"s":null,"t":"월하는 엽전을 손바닥에 쥔 채 한참 다온을 내려다보다가 고개를 끄덕였다."},{"s":"q:mk_wolha","t":"…펴. 쥐고만 부르라던 건 내가 안 보이는 데 있을 때 얘기였어. 꼬맹이가 불러 주면, 값은 안 받을게."},{"s":null,"t":"다온이 쪽지를 폈다. 다온은 월하의 귀에 대고 아주 작은 목소리로 그 이름을 불렀다. 그 이름은 월하와 다온 둘만 들었다."},{"s":null,"t":"금빛 실 하나가 월하의 가슴께에 닿았다. 월하는 엽전을 쥔 오른손으로 눈가를 문질렀다."},{"s":"southern_remnant:galmae","t":"…나도 듣고 싶은데. 안 들리게 불렀네."},{"s":"q:mk_daon","t":"안 돼요. 이건 저랑 아저씨 거예요."},{"s":null,"t":"갈매가 픽 웃으며 다온의 머리를 헝클었다. 서하람이 그 웃음소리를 듣고 따라 웃었다."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":8,"title":"말로 남기는 기록","goal":"흑련 장부고에서 쉬고 본부 정청에 도착한다","need":{"at":["hq_yard"],"tasks":[{"t":"rest","r":["ledger_cellar"],"n":1},{"t":"travel","r":["hq_yard"],"n":1}]},"lines":[{"s":null,"t":"정청은 바뀌고 있었다. 안쪽 방 문은 열린 채로 있었고, 대청에는 일곱 세력의 깃발이 나란히 걸려 있었다."},{"s":null,"t":"대청 앞에 공문이 붙어 있었다. 정청을 일곱 무리가 함께 맡는 「명등청」으로 다시 짠다는 공문이었다. 맨 끝줄에는 맹약 낱장을 반납하라던 명령서를 거둔다고 적혀 있었다. 반납하지 않으면 명부 일을 멈춘다던 말도 없던 일이 되었다. 판관들이 그 앞에서 고개를 숙이고 지나갔다."},{"s":null,"t":"대청 앞을 지나는 서리들이 나를 보고 고개를 숙였다. 정청 사람이 아닌 세력 사람들도 대청을 드나들고 있었다.","fac_not":"night_office","spec":2,"grp":1},{"s":null,"t":"대청 앞을 지나는 서리들이 정통파 패를 찬 나를 보고 걸음을 멈추어 고개를 숙였다. 공문 아래에는 정통파가 맡을 일로 「동짓밤 부를 이 없는 이름 나눠 맡기」가 적혀 있었다.","fac":"night_office","spec":1,"grp":1},{"s":null,"t":"우리는 모가람을 보러 객사로 건너갔다. 모가람은 객사 작은 방 창가에 앉아 있었다. 붕대는 풀었지만 두 손은 굳어 마디가 굽지 않았다."},{"s":null,"t":"모가람 앞에서 곽두칠이 붓을 들고 받아 적고 있었다. 곽두칠의 발밑에 그림자가 또렷했다."},{"s":"night_office:mo","t":"「서른 해 동안 봉인 서가를 지킨 기록관 모가람이 아뢴다. 정리소의 일을 알면서도 적지 않았다.」 …거기까지 적었어요? 그럼 다음 줄이요."},{"s":null,"t":"모가람이 우리를 보고 웃었다. 이번에는 입꼬리가 끝까지 올라갔다."},{"s":"night_office:mo","t":"조사원님! 다들! 아이고, 눈이… 귀가… 다들 어디 하나씩 두고 왔네요."},{"s":null,"t":"모가람의 웃음이 잠깐 흔들렸다. 모가람은 굳은 손등으로 눈가를 꾹 눌렀다."},{"s":"night_office:mo","t":"적기만 하던 사람이 이제야 말로 남기네요. 보리차는 두칠 씨가 대신 내 드릴 거예요. 제 손으로는 이제 찻잔을 못 들거든요."},{"s":null,"t":"나는 장서각 불이 나던 밤처럼 찻잔을 들어 모가람의 입에 대 주었다. 모가람이 한 모금 마시고 웃었다."},{"s":"night_office:mo","t":"그날도 이렇게 해 주셨죠. 그날 처음으로 누가 제 손을 대신 들어 줬어요."},{"s":null,"t":"객사 문간에서 발소리가 났다. 묵창 나루의 서리 희수가 서 있었다. 품에 새 명부 한 권을 안고 있었다."},{"s":"q:mk_hisu","t":"조사원. 묵창 나루에서 왔습니다. 명등청이 첫 명부를 새로 엮는다기에, 제가 맡겠다고 했어요."},{"s":"q:mk_hisu","t":"칸은 제가 긋겠습니다. 묵창 나루에서 처음 그었던 것처럼요. 이번에는 명부 모든 줄에."},{"s":null,"t":"희수가 명부를 펼쳐 보였다. 줄마다 끝에 손바닥만 한 빈 네모가 비어 있었다. 아직 아무 칸에도 이름이 없었다."},{"s":"night_office:han","t":"희수 서리. 그 칸에 처음 적힌 이름 덕에 여기까지 왔다. 동짓밤에 관아 터로 와 주겠나. 첫 줄은 거기서 채우고 싶다."},{"s":"q:mk_hisu","t":"…네. 다온이도 데려갈게요. 그 아이가 첫 이름을 꼭 자기가 부르겠다고 해서요."},{"s":null,"t":"그날 저녁 객사에서 우리는 다 같이 밥상 앞에 앉았다. 청파가 생선을 구웠고, 단비가 엿을 후식이라며 상에 올렸다. 갈매가 서하람의 밥그릇에 반찬을 하나씩 얹어 주며 무엇인지 일러 주었다."},{"s":"q:r71_seoharam","t":"이건 냄새로 알아요. 구운 생선이에요. 청파 씨가 또 태웠네요."},{"s":"q:sn_cheongpa","t":"안 태웠어요! 겉만 조금 그을렸다니까요!"},{"s":null,"t":"한설이 술병을 들고 왔다. 한설은 잔마다 술을 따르고 마지막으로 빈 잔 셋을 상 끝에 놓았다. 장무현의 잔, 백운서의 잔, 그리고 경현의 잔이었다."},{"s":null,"t":"한설은 경현의 잔 곁에 반듯하게 갠 수건 한 장을 놓았다. 장서각에 불이 난 밤, 빨아서 돌려드리겠다며 품에 넣었던 수건이었다."},{"s":null,"t":"여운비는 품에서 호송 장부를 꺼내 맨 끝 장에 한 줄을 더 적었다. 「여사온. 수로로 나가 흑련 첫 회주가 되심.」 여운비는 장부를 묶어 객사 문간의 북령 역참 심부름꾼에게 건넸다."},{"s":"north_league:yeo","t":"맹주께 올리시오. 썰매 수도 짐 수도 하나 안 적혔다고 먼저 말씀드리시오. 봄에 고찰로 돌아가면 집안 목인 줄의 이름 없는 목인에 그분 이름을 새기겠다는 말도 전하시오."},{"s":"night_office:han","t":"동지가 사흘 남았다. 명등제에 쓸 등롱이 모자란다. 등도 관아 터에서도 열 거다. 우리가 처음 등을 단 곳이니까."},{"s":"north_league:yeo","t":"그럼 등롱부터 만듭시다. 부를 이름은 저마다 들고 있으니까."},{"s":null,"t":"한설의 말로는 흰 밤이 걷힌 뒤에도 등도에서 이름 글자를 비추는 불은 명등 심지를 넣고 끊긴 등 기름을 부은 명등 등롱뿐이라, 우리는 그 등롱을 짓기로 했다."}],"reward":{"xp":2333}},{"quest_id":"mdq_17","step":9,"title":"첫 명등제","goal":"본부 정청에서 쉬고 명등 등롱 3개를 만들어 꺼진 관아 터의 명등제에 쓴다","need":{"at":["dark_yamen"],"tasks":[{"t":"rest","r":["hq_yard"],"n":1},{"t":"craft","items":["myeongdeung_lamp"],"n":3}],"give":{"myeongdeung_lamp":3}},"lines":[{"s":null,"t":"그해 동짓밤, 첫 명등제가 열렸다. 해가 지자 모든 고을에서 사람들이 등롱을 들고 나왔다. 사람들은 부를 이 없는 이름을 나눠 맡아 불렀다."},{"s":null,"t":"정청에서, 철벽 고찰에서, 백골 장터와 구름나루와 잔불촌과 무극 관성대와 십삼문에서, 저마다 맡은 이름을 부르는 목소리가 밤새 이어졌다."},{"s":null,"t":"등도에서도 명등제가 열렸다. 꺼진 관아 터 마당에 일행 다섯과 한설과 월하와 다온과 희수가 둘러앉았다. 처마 끝 등롱마다 불이 흔들렸다."},{"s":null,"t":"희수가 마당 한가운데에 새 명부를 펼쳤다. 희수는 첫 줄 끝 빈 네모에 붓을 대고 반듯하게 테를 둘렀다. 묵창 나루에서 처음 그었던 그 칸이었다."},{"s":"q:mk_hisu","t":"첫 줄은 장무현 장군입니다. 부르는 이 칸은… 비워 두면 안 되겠죠."},{"s":null,"t":"갈매가 희수 곁에 무릎을 꿇었다. 갈매는 붓을 받아 그 칸에 제 이름을 적고 엄지 도장을 꾹 눌렀다."},{"s":"q:mk_daon","t":"다음 줄은 제가 할래요! 서리님, 서하 누나 줄이요!"},{"s":null,"t":"희수가 다온의 손을 잡고 둘째 줄에 「서하」를 함께 적었다. 다온이 그 칸에 삐뚤빼뚤한 제 이름을 썼다. 셋째 줄은 「서율」이었다. 월하가 아홉 손가락으로 붓을 쥐고 그 칸에 「월하」라고 적었다. 옆집 형의 줄이었다."},{"s":null,"t":"청파가 먼저 일어섰다. 손에 배 밑창에서 건져 올린 명단이 들려 있었다. 청파는 「이번 배에 태우지 못한 아이들」의 이름을 하나씩 불렀다."},{"s":null,"t":"숨이 자주 끊겼지만, 청파는 숨을 고르고 다시 불렀다. 한 이름도 빼놓지 않았다."},{"s":null,"t":"단비가 월하에게 받은 쪽지를 펴서 열네 살 때 서약에 쓴 아이의 이름을 불렀다. 단비는 오른손으로 방울을 한 번 딸랑 흔들었다. 축문은 들리지 않았지만, 방울 소리는 멀리 갔다."},{"s":null,"t":"여운비가 단비의 오른쪽에 서서 북령 종지기 여사온의 이름을 불렀다. 여운비는 오른 뺨을 밤바람에 내밀고 있었다."},{"s":null,"t":"갈매는 구리 화로를 마당 한가운데에 놓고 장무현의 이름을 불렀다. 갈매는 서하람의 손을 잡고 밤하늘을 올려다보았다. 갈매가 별자리를 하나씩 읽어 주었다."},{"s":"southern_remnant:galmae","t":"저기 북쪽에 국자 모양 별이 있어. 그 옆에 밝은 거 하나. 아마 네 별 자리였을 거야. 지금은 아무것도 없는데, 이상하게 빈자리가 예쁘네."},{"s":"q:r71_seoharam","t":"…아, 그건 관측이 아니라 감상이잖아요. 그래도 좋아요. 계속 읽어 주세요."},{"s":null,"t":"서하람이 품에서 종이에 싼 엿 하나를 꺼냈다. 서하람은 방울 소리가 난 쪽으로 엿을 내밀었다."},{"s":"q:r71_seoharam","t":"단비 씨, 엿값이요. 별 뜨면 갚는다고 했잖아요. 오늘 별이 떴대요. 갈매 씨가 관측해 줬어요."},{"s":"red_moon_cult:danbi","t":"…외상 별님이 진짜 갚네요. 아까워서 못 먹겠어요."},{"s":null,"t":"한설은 경현의 장부를 펼쳐 솔내 사람들의 이름을 읽었다. 한설이 밤새 하나하나 펴 둔 덕에, 장부 모서리는 이제 하나도 접혀 있지 않았다."},{"s":null,"t":"한설은 마지막 장의 어머니 이름까지 읽었다. 그다음 맨 끝줄에 제 손으로 적은 이름을 소리 내어 불렀다. 「경현.」 이번에도 스승님이라고 부르지 않았다."},{"s":null,"t":"다온이 월하의 무릎에 앉아 졸다가 깨어 「아저씨」 하고 불렀다. 월하가 아홉 손가락으로 다온의 머리를 쓰다듬었다. 엽전은 떨어뜨리지 않았다."},{"s":null,"t":"자정이 가까워지자 등도의 처마마다 등롱이 하나둘 켜졌다. 일흔 해 동안 흰 밤 속에 있던 도성에 처음으로 진짜 밤이 내려앉았고, 검푸른 하늘에 별이 듬성듬성 돋았다."},{"s":null,"t":"나는 마지막으로 등롱 하나에 불을 붙였다. 그 등롱에는 아무 이름도 적혀 있지 않았다."},{"s":"q:sn_cheongpa","t":"{이름} 님, 그 등은 누구 거예요?"},{"s":null,"t":"나는 아직 모른다고 했다. 내년 동짓밤에 부를 사람이 생기면 그때 적겠다고 했다."},{"s":"night_office:han","t":"내년이면 생길 거다. 땅 밑의 것은 굶었을 뿐 죽지 않았다. 해마다 이 밤에 부를 이 없는 이름이 하나라도 남으면, 문이 또 흔들린다."},{"s":"southern_remnant:galmae","t":"그럼 해마다 부르면 되지. 화로는 내가 들고 올게. 할배 불씨니까."},{"s":"q:sn_cheongpa","t":"배는 제가 몰고요! 이번엔 값 안 받고 다 실어 올 거예요."},{"s":"red_moon_cult:danbi","t":"역시 「등잔」이네요. 불 켜진 데로 사람이 모인다니까요. 그럼 내년에도 그 등 보고 다 같이 와요. 다들요. 약속이에요."},{"s":"north_league:yeo","t":"…나쁘지 않소."},{"s":"southern_remnant:galmae","t":"너 그 말밖에 할 줄 몰라?"},{"s":null,"t":"웃음소리가 등도의 밤하늘로 퍼졌다. 웃음이 잦아들자 단비가 붓을 들어, 이름 없는 등롱 아랫단에 작은 글씨를 적었다. 「내년 동지 · 꺼진 관아 터」였다."},{"s":"red_moon_cult:danbi","t":"날짜는 적어 둬야죠. 잊어버리면 안 되니까요. 이름은 내년에 {이름} 님이 적고요."},{"s":null,"t":"서하람이 등롱 쪽으로 손을 뻗었다. 갈매가 그 손을 끌어다 등롱의 따뜻한 종이에 대 주었다."},{"s":"q:r71_seoharam","t":"따뜻하네요. 내년에도 이만큼 따뜻했으면 좋겠어요. 그때도 갈매 씨가 별 읽어 줘요."},{"s":"southern_remnant:galmae","t":"알았어. 해마다 읽어 줄게. 틀려도 따지지 마."},{"s":null,"t":"우리는 다시 둘러앉아 맡은 이름을 불렀다. 한 사람이 숨을 고르면 옆 사람이 이어 불렀고, 다온이 졸면 월하가, 청파가 기침을 하면 단비가 그 자리를 받았다."},{"s":null,"t":"날이 밝을 무렵 마지막 이름이 끝났다. 처마 끝에서 이름 없는 등롱 하나가 새벽바람에 가만히 흔들렸다. 나는 그 불이 꺼지지 않는 것을 오래 바라보았다."}],"reward":{"xp":2333,"gil":520,"items":{"myeongdeung_lamp":4,"lamp_wick_core":2}}}]$J$::jsonb) as x(quest_id text, step int, title text, goal text, need jsonb, lines jsonb, reward jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
create or replace function pg_temp.yh_patch(p_fn text, p_old text, p_new text, p_n int default 1) returns void
language plpgsql as $$
declare d text; o text; k int;
begin
  d := pg_get_functiondef(p_fn::regprocedure);
  if position(p_new in d) > 0 then return; end if;
  k := (length(d) - length(replace(d, p_old, ''))) / greatest(1, length(p_old));
  if k <> p_n then raise exception '고칠 자리 수가 다름: % (%번 기대, %번)', p_fn, p_n, k; end if;
  o := pg_get_userbyid((select proowner from pg_proc where oid = p_fn::regprocedure));
  if o like 'fn_owner%' and not pg_has_role('postgres', o, 'usage') then execute format('grant %I to postgres with inherit true, set true', o); end if;
  execute replace(d, p_old, p_new);
end $$;

lock table public.world_characters in access exclusive mode;

alter table public.world_gw_members add column if not exists gval smallint;

do $$
begin
  execute format('create or replace function public.world_boss_rules() returns jsonb language sql immutable set search_path = '''' as $f$ select %L::jsonb $f$',
    (public.world_boss_rules() - 'gapgwi') || jsonb_build_object('gapgwi', $j${
  "name": "값귀", "fight": "값을 매기는 장부", "place": "붉은 사당 골목", "arc": "명등기", "region": "red_shrine_lane", "lv": 47,
  "quest": "mdq_7", "quest_name": "외전 「명등기」 7장 「묻은 이름」", "item": "red_shrine_lacquer", "item_name": "붉은 사당 옻", "item_where": "붉은 사당 골목에서 채집해 얻습니다.",
  "min": 18, "hp_min": 8000, "hp_atk": 42, "hp_n": [1.2, 0.8, 0.65, 0.62], "raw_n": [0.6, 0.7, 0.8, 0.85], "raw": [40, 4], "enrage": 0.15,
  "first": {"gil": 2000, "xp": 0.5}, "again": {"gil": 150, "xp": 0.05}, "fail": {"dur": 10, "er": 10, "cd": 30}, "falls": 10, "xp_cap_lv": 50,
  "hard_quest": "mdq_8", "hard_quest_name": "외전 「명등기」 8장 「끊긴 기름」",
  "modes": {"story": "이야기판", "hard": "깊은 장부"},
  "phases": ["판결 망치", "바가지", "장부 맞추기", "장 닫힘"],
  "mech_names": {"judge": "판결 망치", "bargain": "바가지", "ledger": "장부 맞추기", "tether": "외상 줄", "close": "장 닫힘", "basket": "떨이 바구니", "tagm": "값표 맞추기"},
  "story": {"min": 30, "round_s": 60, "hp_min": 2000, "hp_atk": 24, "hp_n": [1, 1, 1, 1], "raw": [12, 2], "first": {"gil": 1000},
    "board": {"mech_mul": 1,
      "basket": {"every": 3, "off": 1, "left": 2, "raw": 12},
      "tagm": {"every": 4, "off": 3, "left": 3, "raw": 8, "hit_pct": 3},
      "seq": [{"at": 100, "m": ["basket"]}, {"at": 66, "m": ["tagm"]}, {"at": 33, "m": ["basket", "tagm"]}]}},
  "board": {
    "start": [0, 4], "delta": {"attack": 1, "coop": 1}, "haggle": -5, "price": 3, "max": 9,
    "mech_mul": 0.45,
    "judge": {"every": 3, "off": 1, "left": 2, "raw": 45, "shift": false},
    "bargain": {"every": 4, "off": 0, "left": 2, "raw": 30, "base": 0.4, "k": 0.09},
    "ledger": {"every": 5, "off": 2, "left": 4, "cells": [2, 2, 3, 3], "raw": 25, "heal_pct": 3, "hit_pct": 4, "broke": 2, "broke_pct": 30},
    "tether": {"every": 5, "off": 4, "left": 3, "dist": 3, "raw": 30},
    "close": {"every": 7, "off": 0, "left": 3, "raw": 20, "max": 4},
    "seq": [{"at": 100, "m": ["judge"]}, {"at": 87.5, "m": ["judge", "bargain"]}, {"at": 75, "m": ["ledger", "judge", "bargain"]},
      {"at": 50, "m": ["ledger", "tether", "judge", "bargain"]}, {"at": 25, "m": ["close", "ledger", "tether", "judge", "bargain"]}],
    "low_pct": 10},
  "solo": {"artificer": {"solo_dmg": -25, "solo_guard": -24}, "scout": {"solo_dmg": -25, "solo_guard": -15}, "exorcist": {"solo_dmg": -26, "solo_guard": -16},
    "medic": {"solo_dmg": 20, "solo_guard": -55}, "sealmaster": {"solo_dmg": -28, "solo_guard": -10}, "analyst": {"solo_dmg": -25, "solo_guard": -36},
    "tamer": {"solo_dmg": -25, "solo_guard": 0}}
}$j$::jsonb));
end $$;

create or replace function public.world_solo_aid(p_job text, p_boss text)
 returns jsonb language sql immutable set search_path = ''
as $f$ select case when public.world_boss_rules() -> p_boss ? 'solo' then coalesce(public.world_boss_rules() -> p_boss -> 'solo' -> p_job, '{}'::jsonb) else public.world_solo_aid(p_job) end $f$;

create or replace function public.world_gg_nb(p_cell integer)
 returns integer[] language sql immutable set search_path = ''
as $f$ select array(select z from (values (p_cell - 5), (p_cell + 5), (case when (p_cell - 1) % 5 > 0 then p_cell - 1 end), (case when (p_cell - 1) % 5 < 4 then p_cell + 1 end)) v(z)
  where z between 1 and 15 order by z) $f$;

create or replace function public.world_gg_col(p_col integer)
 returns integer[] language sql immutable set search_path = ''
as $f$ select array[p_col, p_col + 5, p_col + 10] $f$;

create or replace function public.world_gg_dist(p_a integer, p_b integer)
 returns integer language sql immutable set search_path = ''
as $f$ select case when p_a is null or p_b is null then 9 else abs((p_a - 1) / 5 - (p_b - 1) / 5) + abs((p_a - 1) % 5 - (p_b - 1) % 5) end $f$;

create or replace function public.world_gg_dmg(p_fight uuid, p_uid uuid, p_raw numeric, p_round integer, p_why text, p_guardable boolean)
 returns integer language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare m public.world_gw_members%rowtype; f public.world_gw_fights%rowtype; br jsonb := public.world_boss_fight_rules(p_fight);
begin
  select * into m from public.world_gw_members where fight_id = p_fight and owner_id = p_uid;
  if not found or m.out_rounds > 0 or m.rest then return 0; end if;
  select * into f from public.world_gw_fights where fight_id = p_fight;
  return public.world_gw_hurt(p_fight, p_uid, round(p_raw * coalesce((br -> 'board' ->> 'mech_mul')::numeric, 1) * (1 + coalesce((br ->> 'enrage')::numeric, 0) * f.enrage)
    * case when p_guardable and coalesce(m.act ->> 'a', 'guard') in ('guard', 'brace') then 0.5 else 1 end)::int, p_round, p_why);
end $f$;

create or replace function public.world_gg_hz_cells(p_fight uuid, p_hz jsonb)
 returns integer[] language plpgsql stable security definer set search_path = pg_catalog, public
as $f$
declare a int; b int;
begin
  if p_hz ->> 'k' in ('judge', 'close') then return public.world_gg_col((p_hz ->> 'col')::int); end if;
  if p_hz ->> 'k' = 'ledger' then return array(select jsonb_array_elements_text(p_hz -> 'cells')::int); end if;
  if p_hz ->> 'k' in ('basket', 'tagm') then return array[(p_hz ->> 'c')::int]; end if;
  if p_hz ->> 'k' = 'tether' then
    select pos into a from public.world_gw_members where fight_id = p_fight and owner_id = (p_hz ->> 'a')::uuid;
    select pos into b from public.world_gw_members where fight_id = p_fight and owner_id = (p_hz ->> 'b')::uuid;
    return array_remove(array[a, b], null);
  end if;
  return '{}'::int[];
end $f$;

create or replace function public.world_gg_seq(p_fight uuid, p_hp integer, p_max integer)
 returns jsonb language plpgsql stable security definer set search_path = pg_catalog, public
as $f$
declare rb jsonb := public.world_boss_fight_rules(p_fight) -> 'board'; e jsonb; pick jsonb; i int := -1; k int := 0; pct numeric := p_hp * 100.0 / greatest(1, p_max);
begin
  for e in select * from jsonb_array_elements(rb -> 'seq') loop
    if pct <= (e ->> 'at')::numeric then pick := e; i := k; end if;
    k := k + 1;
  end loop;
  return coalesce(pick, rb -> 'seq' -> 0) || jsonb_build_object('i', greatest(i, 0));
end $f$;

create or replace function public.world_gg_begin(p_fight uuid, p_n integer)
 returns void language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare rb jsonb := public.world_boss_fight_rules(p_fight) -> 'board'; lo int := (rb -> 'start' ->> 0)::int; hi int := (rb -> 'start' ->> 1)::int; x record; k int := 0; tags jsonb := '{}';
begin
  for x in select owner_id from public.world_gw_members where fight_id = p_fight order by joined_at, owner_id loop
    update public.world_gw_members set gval = lo + floor(random() * (hi - lo + 1))::int, pos = 6 + least(4, floor(k * 5.0 / greatest(1, p_n))::int), prev = null
     where fight_id = p_fight and owner_id = x.owner_id;
    k := k + 1;
  end loop;
  select jsonb_object_agg(c::text, floor(random() * 10)::int) into tags from (select generate_series(1, 5) c union all select generate_series(11, 15)) s;
  update public.world_gw_fights set board = coalesce(board, '{}'::jsonb) || jsonb_build_object('hz', '[]'::jsonb, 'tags', tags, 'closed', '[]'::jsonb, 'seq', 0, 'hid', 0, 'broke', 0)
   where fight_id = p_fight;
  perform public.world_gw_say(p_fight, 0, 'phase', '사당 마룻바닥 밑에서 젖은 장부 더미가 기어 나와 골목 끝 저울 위에 앉는다. 위아래 좌판마다 값표가 붙어 있고, 저마다의 머리 위에도 값(섬)이 매겨진다.');
  perform public.world_gw_say(p_fight, 0, 'phase', '값귀가 주판알을 튕긴다. 「한 줄에 쌀 두 섬. 휘두를수록 값이 오르지. 흥정을 하든가, 서로 값을 매겨 주든가.」');
end $f$;

create or replace function public.world_gg_round(p_fight uuid)
 returns void language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare f public.world_gw_fights%rowtype; br jsonb := public.world_boss_fight_rules(p_fight); rb jsonb; b jsonb; nr int; ph int; m jsonb; tell text := '';
  n int; na int; alive uuid[]; hz jsonb := '[]'; h jsonb; cur jsonb; mechs text[]; story boolean; len int := 5; hid int; c int; k int; t int; cells int[]; closed int[];
  col int; due boolean := false; s int; i int;
begin
  select * into f from public.world_gw_fights where fight_id = p_fight for update;
  rb := br -> 'board'; b := coalesce(f.board, '{}'::jsonb); nr := f.round + 1; story := f.mode = 'story';
  ph := case when f.hp * 4 > f.max_hp * 3 then 1 when f.hp * 2 > f.max_hp then 2 when f.hp * 4 > f.max_hp then 3 else 4 end;
  select count(*) into n from public.world_gw_members where fight_id = p_fight;
  select coalesce(array_agg(owner_id order by random()), '{}') into alive from public.world_gw_members where fight_id = p_fight and out_rounds = 0 and not rest;
  na := coalesce(array_length(alive, 1), 0);
  hid := coalesce((b ->> 'hid')::int, 0);
  closed := array(select jsonb_array_elements_text(coalesce(b -> 'closed', '[]'::jsonb))::int);
  cur := public.world_gg_seq(p_fight, f.hp, f.max_hp);
  mechs := array(select jsonb_array_elements_text(cur -> 'm'));
  if (cur ->> 'i')::int <> coalesce((b ->> 'seq')::int, 0) then
    perform public.world_gw_say(p_fight, nr, 'phase', case
      when 'close' = any (mechs) then '사당 밑 곳간에 물이 차오른다. 골목 왼쪽 끝부터 좌판이 하나둘 덧문을 내린다. 「장이 파한다. 파하기 전에 셈을 끝내자.」'
      when 'tether' = any (mechs) then '값귀가 두 사람의 소매를 붉은 외상 줄로 묶는다. 「같이 갚든가, 갈라서든가.」'
      when 'ledger' = any (mechs) then '값귀가 낱장을 펼쳐 좌판 위에 깐다. 「그 좌판에 선 이들의 값을 더해 맞추면 장부를 덮어 주마.」'
      when 'bargain' = any (mechs) then '주판알이 사납게 맞부딪친다. 「값이 비싼 놈부터 거둔다.」'
      when 'tagm' = any (mechs) then '좌판의 값표가 하나씩 반짝인다. 제 값과 같은 값표 앞에 서면 값귀가 움찔한다.'
      else '값귀가 장부를 넘긴다.' end);
    b := b || jsonb_build_object('seq', (cur ->> 'i')::int);
  end if;
  for h in select * from jsonb_array_elements(coalesce(b -> 'hz', '[]'::jsonb)) loop
    h := h || jsonb_build_object('left', (h ->> 'left')::int - 1);
    if h ->> 'k' = 'judge' and coalesce((rb -> 'judge' ->> 'shift')::boolean, false) and (h ->> 'left')::int = 0 and not coalesce((h ->> 'sh')::boolean, false) then
      col := (h ->> 'col')::int;
      col := case when col = 1 then 2 when col = 5 then 4 when random() < 0.5 then col - 1 else col + 1 end;
      h := h || jsonb_build_object('col', col, 'sh', true);
      perform public.world_gw_say(p_fight, nr, 'warn', '망치가 기운다.');
    end if;
    hz := hz || jsonb_build_array(h);
  end loop;
  if na > 0 then
    if 'judge' = any (mechs) and nr % (rb -> 'judge' ->> 'every')::int = (rb -> 'judge' ->> 'off')::int then
      select pos into c from public.world_gw_members where fight_id = p_fight and owner_id = alive[1];
      col := coalesce(((c - 1) % 5) + 1, 1 + floor(random() * 5)::int);
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'judge', 'col', col, 'left', (rb -> 'judge' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || '값귀가 판결 망치를 든다. ' || col || '번째 줄을 겨눈다.';
    end if;
    if 'bargain' = any (mechs) and nr % (rb -> 'bargain' ->> 'every')::int = (rb -> 'bargain' ->> 'off')::int then
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'bargain', 'left', (rb -> 'bargain' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || '값귀가 주판을 튕긴다. 값이 비싼 사람부터 크게 거둘 것이다.';
    end if;
    if 'ledger' = any (mechs) and not exists (select 1 from jsonb_array_elements(hz) e where e ->> 'k' = 'ledger') and nr % (rb -> 'ledger' ->> 'every')::int = (rb -> 'ledger' ->> 'off')::int then
      k := least(na, coalesce((rb -> 'ledger' -> 'cells' ->> (least(4, greatest(1, n)) - 1))::int, 2));
      cells := '{}';
      for i in 1 .. k loop
        select pos into c from public.world_gw_members where fight_id = p_fight and owner_id = alive[i];
        select z into s from (select generate_series(1, 5) z union all select generate_series(11, 15)) q
         where not (((z - 1) % 5) + 1 = any (closed)) and not (z = any (cells)) order by public.world_gg_dist(z, c), random() limit 1;
        if s is not null then cells := cells || s; end if;
      end loop;
      t := greatest(0, (select coalesce(sum(gval), 0) from public.world_gw_members where fight_id = p_fight and owner_id = any (alive[1:k])) + floor(random() * 5)::int - 2);
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'ledger', 'cells', to_jsonb(cells), 't', t, 'left', (rb -> 'ledger' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || '흰 낱장이 좌판 ' || k || '곳에 깔린다. 그 위에 선 이들의 값을 더해 ' || t || '섬을 맞춰라.';
    end if;
    if 'tether' = any (mechs) and na >= 2 and nr % (rb -> 'tether' ->> 'every')::int = (rb -> 'tether' ->> 'off')::int then
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'tether', 'a', alive[1], 'b', alive[2], 'left', (rb -> 'tether' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || '붉은 외상 줄이 두 사람을 묶는다. 멀리 떨어져야 끊긴다.';
    end if;
    if 'close' = any (mechs) and coalesce(array_length(closed, 1), 0) < (rb -> 'close' ->> 'max')::int
       and not exists (select 1 from jsonb_array_elements(hz) e where e ->> 'k' = 'close') and nr % (rb -> 'close' ->> 'every')::int = (rb -> 'close' ->> 'off')::int then
      col := coalesce(array_length(closed, 1), 0) + 1;
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'close', 'col', col, 'left', (rb -> 'close' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || col || '번째 줄 좌판이 덧문을 내리려 한다.';
    end if;
    if 'basket' = any (mechs) and nr % (rb -> 'basket' ->> 'every')::int = (rb -> 'basket' ->> 'off')::int then
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'basket', 'c', 6 + floor(random() * 5)::int, 'left', (rb -> 'basket' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || '떨이 바구니가 거리 위에 멈춘다. 누군가 그 아래에서 막으면 엎어진다.';
    end if;
    if 'tagm' = any (mechs) and nr % (rb -> 'tagm' ->> 'every')::int = (rb -> 'tagm' ->> 'off')::int then
      select z into c from (select generate_series(1, 5) z union all select generate_series(11, 15)) s order by random() limit 1;
      hid := hid + 1;
      hz := hz || jsonb_build_array(jsonb_build_object('id', hid, 'k', 'tagm', 'c', c, 'left', (rb -> 'tagm' ->> 'left')::int));
      tell := tell || case when tell <> '' then ' ' else '' end || c || '번 좌판 값표가 반짝인다(' || (b -> 'tags' ->> c::text) || '섬). 같은 값인 사람이 그 앞에 서라.';
    end if;
  end if;
  if exists (select 1 from jsonb_array_elements(hz) e where (e ->> 'left')::int <= 0) then due := true; end if;
  if tell = '' then tell := '값귀가 주판알을 딸깍인다. 「한 줄에 쌀 두 섬. 한 줄에 쌀 두 섬.」'; end if;
  b := b || jsonb_build_object('hz', hz, 'hid', hid);
  m := jsonb_build_object('k', 'normal', 'phase_name', br -> 'phases' ->> (ph - 1), 'aoe', false, 'tell', tell, 'mechs', to_jsonb(mechs));
  if due then len := 10; end if;
  update public.world_gw_fights set phase = ph, round = nr, cycle = f.cycle + 1, mech = m, board = b,
    round_ends_at = now() + make_interval(secs => case when not story then len when n = 1 then 86400 else (br ->> 'round_s')::int end), updated_at = now()
   where fight_id = p_fight;
  update public.world_gw_members set act = null where fight_id = p_fight;
  perform public.world_gw_say(p_fight, nr, case when due then 'warn' else 'tell' end, tell);
end $f$;

create or replace function public.world_gg_steps(p_fight uuid, p_round integer)
 returns void language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare x record; t int;
begin
  for x in select * from public.world_gw_members where fight_id = p_fight and out_rounds = 0 and not rest and act ? 'm' order by joined_at, owner_id loop
    t := (x.act ->> 'm')::int;
    if t = any (public.world_gg_nb(x.pos)) then
      update public.world_gw_members set prev = pos, pos = t where fight_id = p_fight and owner_id = x.owner_id;
    end if;
  end loop;
end $f$;

create or replace function public.world_gg_on_attack(p_fight uuid, p_uid uuid, p_round integer, p_d numeric)
 returns numeric language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare rb jsonb := public.world_boss_fight_rules(p_fight) -> 'board'; f public.world_gw_fights%rowtype;
begin
  select * into f from public.world_gw_fights where fight_id = p_fight;
  return p_d * case when coalesce((f.board ->> 'broke')::int, 0) > 0 then 1 + coalesce((rb -> 'ledger' ->> 'broke_pct')::numeric, 0) / 100.0 else 1 end;
end $f$;

create or replace function public.world_gg_mech(p_fight uuid, p_round integer, p_broke boolean, p_delayed boolean, p_freed uuid[])
 returns numeric language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare rb jsonb := public.world_boss_fight_rules(p_fight) -> 'board'; f public.world_gw_fights%rowtype; b jsonb; w record; x record; h jsonb; keep jsonb := '[]';
  extra numeric := 0; cells int[]; closed int[]; cnt int; sm int; nm text; tn text; fails int := 0; na int; tv int; hv int; mx int;
begin
  select * into f from public.world_gw_fights where fight_id = p_fight for update;
  b := f.board; mx := coalesce((rb ->> 'max')::int, 9);
  closed := array(select jsonb_array_elements_text(coalesce(b -> 'closed', '[]'::jsonb))::int);
  select count(*) into na from public.world_gw_members where fight_id = p_fight and out_rounds = 0 and not rest;
  if coalesce((b ->> 'broke')::int, 0) > 0 then b := b || jsonb_build_object('broke', (b ->> 'broke')::int - 1); end if;
  update public.world_gw_members x2 set gval = least(mx, greatest(0, x2.gval + coalesce((rb -> 'delta' ->> (x2.act ->> 'a'))::int, 0)))
   where x2.fight_id = p_fight and x2.out_rounds = 0 and not x2.rest and x2.gval is not null;
  for w in select x2.* from public.world_gw_members x2 where x2.fight_id = p_fight and x2.out_rounds = 0 and not x2.rest and x2.act ->> 'a' = 'deal' order by x2.joined_at loop
    update public.world_gw_members set gval = greatest(0, gval + (rb ->> 'haggle')::int) where fight_id = p_fight and owner_id = w.owner_id returning gval into tv;
    perform public.world_gw_say(p_fight, p_round, 'good', w.name || ' — 값귀에게 흥정을 걸어 제 값을 ' || tv || '섬으로 깎았습니다.');
  end loop;
  for w in select x2.* from public.world_gw_members x2 where x2.fight_id = p_fight and x2.out_rounds = 0 and not x2.rest and x2.act ->> 'a' = 'call' and nullif(x2.act ->> 't', '') is not null
            and (x2.act ->> 't')::uuid <> x2.owner_id order by x2.joined_at loop
    select name, pos into tn, hv from public.world_gw_members where fight_id = p_fight and owner_id = (w.act ->> 't')::uuid and out_rounds = 0;
    if tn is null then continue; end if;
    if public.world_gg_dist(w.pos, hv) > 1 then
      perform public.world_gw_say(p_fight, p_round, 'miss', w.name || ' — ' || tn || '이(가) 너무 멀어 값을 매겨 줄 수 없습니다(바로 옆 칸만).'); continue;
    end if;
    update public.world_gw_members set gval = least(mx, gval + (rb ->> 'price')::int) where fight_id = p_fight and owner_id = (w.act ->> 't')::uuid returning gval into tv;
    perform public.world_gw_say(p_fight, p_round, 'good', w.name || ' — ' || tn || '의 값을 ' || tv || '섬으로 매겨 주었습니다.');
  end loop;
  for h in select * from jsonb_array_elements(coalesce(b -> 'hz', '[]'::jsonb)) loop
    if (h ->> 'left')::int > 0 then keep := keep || jsonb_build_array(h); continue; end if;
    cells := public.world_gg_hz_cells(p_fight, h);
    if h ->> 'k' = 'judge' then
      perform public.world_gw_say(p_fight, p_round, 'boss', '판결 망치가 ' || (h ->> 'col') || '번째 줄을 내리칩니다!');
      if exists (select 1 from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.pos = any (cells)) then fails := fails + 1; end if;
      for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.pos = any (cells) loop
        perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'judge' ->> 'raw')::numeric * case when p_broke then 0.5 else 1 end, p_round, '판결 망치에', true);
      end loop;
    elsif h ->> 'k' = 'bargain' then
      perform public.world_gw_say(p_fight, p_round, 'boss', '값귀가 바가지를 씌웁니다! 값이 비쌀수록 크게 거둡니다.');
      for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest loop
        perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'bargain' ->> 'raw')::numeric * ((rb -> 'bargain' ->> 'base')::numeric + (rb -> 'bargain' ->> 'k')::numeric * coalesce(x.gval, 0))
          * case when p_broke then 0.5 else 1 end, p_round, x.gval || '섬 바가지에', true);
      end loop;
      if exists (select 1 from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.gval >= 8) then fails := fails + 1; end if;
    elsif h ->> 'k' = 'ledger' then
      select count(distinct y.pos), coalesce(sum(y.gval), 0) into cnt, sm from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.pos = any (cells);
      if cnt >= least(cardinality(cells), na) and sm = (h ->> 't')::int then
        extra := extra + round(f.max_hp * (rb -> 'ledger' ->> 'hit_pct')::numeric / 100.0);
        b := b || jsonb_build_object('broke', (rb -> 'ledger' ->> 'broke')::int);
        perform public.world_gw_say(p_fight, p_round, 'good', '좌판 위 값의 합 ' || sm || '섬 — 장부가 맞았습니다! 값귀가 제 장부에 걸려 휘청입니다.');
      else
        fails := fails + 1;
        update public.world_gw_fights set hp = least(max_hp, hp + round(max_hp * (rb -> 'ledger' ->> 'heal_pct')::numeric / 100.0)), updated_at = now() where fight_id = p_fight;
        perform public.world_gw_say(p_fight, p_round, 'bad', '좌판 위 값의 합 ' || sm || '섬(선 곳 ' || cnt || '/' || least(cardinality(cells), na) || ') — 장부가 맞지 않았습니다(목표 ' || (h ->> 't') || '섬). 값귀가 물 밑 장부에서 값을 꺼내 낫습니다.');
        for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest loop
          perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'ledger' ->> 'raw')::numeric, p_round, '맞지 않은 장부에', true);
        end loop;
      end if;
    elsif h ->> 'k' = 'tether' then
      if cardinality(cells) = 2 and public.world_gg_dist(cells[1], cells[2]) < (rb -> 'tether' ->> 'dist')::int then
        fails := fails + 1;
        perform public.world_gw_say(p_fight, p_round, 'bad', '외상 줄이 팽팽해지기 전에 두 사람이 너무 가까웠습니다. 줄이 두 사람을 함께 조입니다.');
        for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.owner_id in ((h ->> 'a')::uuid, (h ->> 'b')::uuid) loop
          perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'tether' ->> 'raw')::numeric, p_round, '외상 줄에', false);
        end loop;
      else
        perform public.world_gw_say(p_fight, p_round, 'good', '멀리 떨어져 선 두 사람 사이에서 외상 줄이 툭 끊어졌습니다.');
      end if;
    elsif h ->> 'k' = 'close' then
      closed := closed || (h ->> 'col')::int;
      perform public.world_gw_say(p_fight, p_round, 'bad', (h ->> 'col') || '번째 줄 좌판이 덧문을 내렸습니다. 그 줄에 서 있으면 라운드마다 다칩니다.');
    elsif h ->> 'k' = 'basket' then
      select string_agg(y.name, '·') into nm from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.pos = (h ->> 'c')::int
        and coalesce(y.act ->> 'a', 'guard') in ('guard', 'brace');
      if nm is not null then
        perform public.world_gw_say(p_fight, p_round, 'good', nm || ' — 떨이 바구니를 막아 엎었습니다.');
      else
        perform public.world_gw_say(p_fight, p_round, 'bad', '아무도 막지 않아 떨이 바구니가 쏟아집니다.');
        for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest loop
          perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'basket' ->> 'raw')::numeric, p_round, '쏟아진 떨이에', true);
        end loop;
      end if;
    elsif h ->> 'k' = 'tagm' then
      select string_agg(y.name, '·') into nm from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and y.pos = (h ->> 'c')::int
        and y.gval = (b -> 'tags' ->> (h ->> 'c'))::int;
      if nm is not null then
        extra := extra + round(f.max_hp * (rb -> 'tagm' ->> 'hit_pct')::numeric / 100.0);
        perform public.world_gw_say(p_fight, p_round, 'good', nm || ' — 값표와 값이 꼭 맞았습니다. 값귀가 움찔합니다.');
      else
        perform public.world_gw_say(p_fight, p_round, 'bad', '값표 앞에 같은 값인 사람이 없었습니다.');
        for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest loop
          perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'tagm' ->> 'raw')::numeric, p_round, '어긋난 셈에', true);
        end loop;
      end if;
    end if;
  end loop;
  if cardinality(closed) > 0 then
    for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest and ((y.pos - 1) % 5) + 1 = any (closed) loop
      perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'close' ->> 'raw')::numeric, p_round, '닫힌 좌판에 끼여', false);
    end loop;
  end if;
  if fails > 0 and jsonb_typeof(rb -> 'fail_party') = 'object' then
    perform public.world_gw_say(p_fight, p_round, 'bad', '한 사람의 셈이 틀린 틈으로 값귀가 모두의 값을 거둡니다' || case when fails > 1 then '(' || fails || '번)' else '' end || '.');
    for x in select * from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0 and not y.rest loop
      perform public.world_gg_dmg(p_fight, x.owner_id, (rb -> 'fail_party' ->> 'raw')::numeric * fails, p_round, '함께 거둔 값에', false);
    end loop;
  end if;
  update public.world_gw_fights set board = b || jsonb_build_object('hz', keep, 'closed', to_jsonb(closed)) where fight_id = p_fight;
  return extra;
end $f$;

create or replace function public.world_gg_after(p_fight uuid, p_round integer)
 returns boolean language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare rb jsonb := public.world_boss_fight_rules(p_fight) -> 'board'; f public.world_gw_fights%rowtype;
begin
  select * into f from public.world_gw_fights where fight_id = p_fight for update;
  if f.status <> 'fight' then return true; end if;
  if not coalesce((f.board ->> 'low')::boolean, false) and f.hp > 0 and f.hp * 100 < f.max_hp * coalesce((rb ->> 'low_pct')::numeric, 10) then
    perform public.world_gw_say(p_fight, p_round, 'boss', '값귀의 낱장이 하나둘 하얗게 바랜다. 주판알이 헛돈다. 「한 줄에 쌀 두… 두…」');
    update public.world_gw_fights set board = board || '{"low": true}'::jsonb where fight_id = p_fight;
  end if;
  if rb ? 'close' and jsonb_array_length(coalesce(f.board -> 'closed', '[]'::jsonb)) >= (rb -> 'close' ->> 'max')::int and f.hp > 0 then
    perform public.world_gw_say(p_fight, p_round, 'bad', '장날이 파했습니다. 물이 곳간을 채우고 값귀가 장부를 안은 채 물 밑으로 가라앉습니다.');
    perform public.world_gw_settle(p_fight, false);
    return true;
  end if;
  return false;
end $f$;

create or replace function public.world_gg_view(p_fight uuid, p_uid uuid)
 returns jsonb language plpgsql stable security definer set search_path = pg_catalog, public
as $f$
declare br jsonb := public.world_boss_fight_rules(p_fight); rb jsonb := br -> 'board'; f public.world_gw_fights%rowtype; me public.world_gw_members%rowtype; b jsonb; cur jsonb;
begin
  select * into f from public.world_gw_fights where fight_id = p_fight;
  select * into me from public.world_gw_members where fight_id = p_fight and owner_id = p_uid;
  b := coalesce(f.board, '{}'::jsonb);
  cur := public.world_gg_seq(p_fight, f.hp, f.max_hp);
  return jsonb_build_object(
    'phase_name', br -> 'phases' ->> (f.phase - 1), 'phases', br -> 'phases', 'mechs', cur -> 'm', 'mech_names', br -> 'mech_names',
    'vals', (select coalesce(jsonb_object_agg(x.owner_id::text, x.gval), '{}'::jsonb) from public.world_gw_members x where x.fight_id = p_fight),
    'mine', me.gval, 'my_pos', me.pos,
    'moves', case when me.pos is not null and f.status = 'fight' then to_jsonb(public.world_gg_nb(me.pos)) else '[]'::jsonb end,
    'tags', coalesce(b -> 'tags', '{}'::jsonb), 'closed', coalesce(b -> 'closed', '[]'::jsonb),
    'hz', (select coalesce(jsonb_agg(e || jsonb_build_object('cells', to_jsonb(public.world_gg_hz_cells(p_fight, e)))
      || case when e ->> 'k' = 'ledger' then jsonb_build_object('sum', (select coalesce(sum(y.gval), 0) from public.world_gw_members y where y.fight_id = p_fight and y.out_rounds = 0
        and y.pos = any (array(select jsonb_array_elements_text(e -> 'cells')::int)))) else '{}'::jsonb end), '[]'::jsonb)
      from jsonb_array_elements(coalesce(b -> 'hz', '[]'::jsonb)) e),
    'delta', rb -> 'delta', 'haggle', (rb ->> 'haggle')::int, 'price', (rb ->> 'price')::int, 'max', coalesce((rb ->> 'max')::int, 9),
    'bargain', case when rb ? 'bargain' then jsonb_build_object('base', (rb -> 'bargain' ->> 'base')::numeric, 'k', (rb -> 'bargain' ->> 'k')::numeric, 'cap', (rb -> 'bargain' ->> 'cap')::int) end,
    'close_max', (rb -> 'close' ->> 'max')::int,
    'broke', coalesce((b ->> 'broke')::int, 0));
end $f$;

create or replace function public.world_gg_settle(p_fight uuid, p_won boolean)
 returns void language plpgsql security definer set search_path = pg_catalog, public
as $f$
declare r jsonb := public.world_boss_fight_rules(p_fight); f public.world_gw_fights%rowtype; m record; today date := (now() at time zone 'Asia/Seoul')::date;
  rec public.world_gw_records%rowtype; n int; solo boolean; flawless boolean; is_first boolean; xp int; msg text; lv int; v_gil int;
begin
  select * into f from public.world_gw_fights where fight_id = p_fight for update;
  if f.status not in ('fight', 'wait') then return; end if;
  update public.world_gw_fights set status = case when p_won then 'won' else 'failed' end, ended_at = now(), updated_at = now(), hp = case when p_won then 0 else hp end where fight_id = p_fight;
  select count(*), coalesce(sum(falls), 0) = 0 into n, flawless from public.world_gw_members where fight_id = p_fight;
  solo := n = 1;
  if f.mode = 'story' then
    for m in select * from public.world_gw_members where fight_id = p_fight loop
      update public.world_characters set health = greatest(1, m.hp), updated_at = now() where owner_id = m.owner_id;
      if p_won then
        insert into public.world_gw_records(owner_id, boss_id) values (m.owner_id, 'gapgwi_story') on conflict do nothing;
        select * into rec from public.world_gw_records where owner_id = m.owner_id and boss_id = 'gapgwi_story' for update;
        is_first := coalesce(rec.kills, 0) = 0;
        update public.world_gw_records set kills = kills + 1, last_kill_day = today, first_kill_at = coalesce(first_kill_at, now()) where owner_id = m.owner_id and boss_id = 'gapgwi_story';
        v_gil := 0;
        if is_first then
          v_gil := (r -> 'first' ->> 'gil')::int;
          update public.world_characters set gil = gil + v_gil, updated_at = now() where owner_id = m.owner_id;
        end if;
        insert into public.world_notifications(user_id, kind, title, content, payload) values (m.owner_id, 'reward', '값귀를 쓰러뜨렸습니다',
          case when is_first then '붉은 사당 골목에서 값귀를 쓰러뜨렸습니다. ' || to_char(v_gil, 'FM999,999') || '전을 받았습니다. 이야기를 이어 가세요.'
            else '붉은 사당 골목에서 다시 한 번 값귀를 쓰러뜨렸습니다.' end,
          jsonb_build_object('fight_id', p_fight, 'boss', 'gapgwi', 'mode', 'story', 'first', is_first));
      else
        insert into public.world_notifications(user_id, kind, title, content, payload)
        values (m.owner_id, 'gw', '값귀 앞에서 밀려났습니다', '이야기판은 밀려나도 잃는 것이 없습니다. 숨을 고르고 다시 서세요.', jsonb_build_object('fight_id', p_fight, 'boss', 'gapgwi', 'mode', 'story'));
      end if;
    end loop;
  else
    for m in select * from public.world_gw_members where fight_id = p_fight loop
      if p_won then
        update public.world_characters set health = greatest(1, m.hp), updated_at = now() where owner_id = m.owner_id;
        insert into public.world_gw_records(owner_id, boss_id) values (m.owner_id, 'gapgwi') on conflict do nothing;
        select * into rec from public.world_gw_records where owner_id = m.owner_id and boss_id = 'gapgwi' for update;
        if rec.last_kill_day is distinct from today then
          is_first := coalesce(rec.kills, 0) = 0;
          update public.world_gw_records set kills = kills + 1, last_kill_day = today, first_kill_at = coalesce(first_kill_at, now()) where owner_id = m.owner_id and boss_id = 'gapgwi';
          select level into lv from public.world_characters where owner_id = m.owner_id;
          xp := case when lv >= (r ->> 'xp_cap_lv')::int then 0
            else round(public.world_xp_need(lv) * case when is_first then (r -> 'first' ->> 'xp')::numeric else (r -> 'again' ->> 'xp')::numeric end) end;
          v_gil := case when is_first then (r -> 'first' ->> 'gil')::int else (r -> 'again' ->> 'gil')::int end;
          update public.world_characters set gil = gil + v_gil, updated_at = now() where owner_id = m.owner_id;
          if xp > 0 then xp := coalesce((public.world_grant_xp_got(m.owner_id, xp) ->> 'xp')::int, 0); end if;
          msg := case when is_first then '값귀를 처음으로 쓰러뜨렸습니다. ' || to_char(v_gil, 'FM999,999') || '전' || case when xp > 0 then ' · 경험치 ' || xp else '' end || '을 받았습니다.'
            else '값귀를 쓰러뜨렸습니다(' || (coalesce(rec.kills, 0) + 1) || '번째). ' || v_gil || '전' || case when xp > 0 then ' · 경험치 ' || xp else '' end || '.' end;
          insert into public.world_notifications(user_id, kind, title, content, payload) values (m.owner_id, 'reward', '값귀 처치', msg, jsonb_build_object('fight_id', p_fight, 'first', is_first, 'boss', 'gapgwi'));
          insert into public.world_events(actor_id, actor_name, event_type, content, payload)
          values (m.owner_id, m.name, 'gg_win', m.name || '이(가) 붉은 사당 골목에서 값귀를 쓰러뜨렸습니다.',
                  jsonb_build_object('fight_id', p_fight, 'boss', 'gapgwi', 'first', is_first, 'solo', solo, 'flawless', flawless and n >= 2, 'members', n, 'kills', coalesce(rec.kills, 0) + 1));
        else
          insert into public.world_notifications(user_id, kind, title, content, payload) values (m.owner_id, 'reward', '값귀 처치', '오늘은 이미 처치를 인정받아 보상은 없습니다.', jsonb_build_object('fight_id', p_fight, 'boss', 'gapgwi'));
        end if;
      else
        update public.world_item_durability d set durability = greatest(0, d.durability - ceil(public.world_item_max_durability(d.item_id) * (r -> 'fail' ->> 'dur')::numeric / 100.0)::int), updated_at = now()
          from public.world_character_equipment e where e.owner_id = m.owner_id and d.owner_id = m.owner_id and d.item_id = e.item_id;
        perform public.world_yohwa_overflow(m.owner_id, (select erosion from public.world_characters where owner_id = m.owner_id) + (r -> 'fail' ->> 'er')::int - 100);
        update public.world_characters set health = greatest(1, m.hp), erosion = least(100, erosion + (r -> 'fail' ->> 'er')::int),
               erosion_stage = case when least(100, erosion + (r -> 'fail' ->> 'er')::int) >= 80 then 4 when least(100, erosion + (r -> 'fail' ->> 'er')::int) >= 55 then 3
                 when least(100, erosion + (r -> 'fail' ->> 'er')::int) >= 30 then 2 when least(100, erosion + (r -> 'fail' ->> 'er')::int) >= 10 then 1 else 0 end,
               updated_at = now() where owner_id = m.owner_id;
        insert into public.world_gw_records(owner_id, boss_id, last_fail_at) values (m.owner_id, 'gapgwi', now()) on conflict (owner_id, boss_id) do update set last_fail_at = now();
        insert into public.world_notifications(user_id, kind, title, content, payload)
        values (m.owner_id, 'gw', '값귀 도전 실패', '장부에 값을 거두어져 밀려났습니다. 장착한 장비 내구도가 ' || (r -> 'fail' ->> 'dur') || '% 닳고 침식이 ' || (r -> 'fail' ->> 'er') || ' 올랐습니다. '
          || (r -> 'fail' ->> 'cd') || '분 뒤 다시 도전할 수 있습니다.', jsonb_build_object('fight_id', p_fight, 'boss', 'gapgwi'));
      end if;
    end loop;
  end if;
  perform public.world_gw_say(p_fight, f.round, case when p_won then 'win' else 'bad' end, case when p_won
    then '값귀가 「한 줄에 쌀 두…」 하다가 말을 잇지 못한다. 덩어리가 무너지며 낱장이 눈보라처럼 흩날리고, 바닥에 닿은 낱장마다 먹 글씨가 하얗게 바랜다. 머리 위의 「섬」 글씨도 함께 사라졌다.'
    else '도전이 끝났습니다.' end);
end $f$;

revoke all on function public.world_gg_nb(integer), public.world_gg_col(integer), public.world_gg_dist(integer, integer), public.world_gg_dmg(uuid, uuid, numeric, integer, text, boolean),
  public.world_gg_hz_cells(uuid, jsonb), public.world_gg_seq(uuid, integer, integer), public.world_gg_steps(uuid, integer) from public, anon, authenticated;
grant execute on function public.world_gg_nb(integer), public.world_gg_col(integer), public.world_gg_dist(integer, integer), public.world_gg_dmg(uuid, uuid, numeric, integer, text, boolean),
  public.world_gg_hz_cells(uuid, jsonb), public.world_gg_seq(uuid, integer, integer), public.world_gg_steps(uuid, integer) to service_role, fn_owner_field;

revoke all on function public.world_gg_begin(uuid, integer), public.world_gg_round(uuid), public.world_gg_on_attack(uuid, uuid, integer, numeric),
  public.world_gg_mech(uuid, integer, boolean, boolean, uuid[]), public.world_gg_after(uuid, integer), public.world_gg_view(uuid, uuid),
  public.world_gg_settle(uuid, boolean) from public, anon, authenticated;
grant execute on function public.world_gg_begin(uuid, integer), public.world_gg_round(uuid), public.world_gg_on_attack(uuid, uuid, integer, numeric),
  public.world_gg_mech(uuid, integer, boolean, boolean, uuid[]), public.world_gg_after(uuid, integer), public.world_gg_view(uuid, uuid),
  public.world_gg_settle(uuid, boolean) to service_role, fn_owner_field;

select pg_temp.yh_patch('public.world_gw_next_round(uuid)',
  $o$  if f.mode = 'story' then perform public.world_story_round(p_fight); return; end if;$o$,
  $n$  if f.boss_id = 'gapgwi' then perform public.world_gg_round(p_fight); return; end if;
  if f.mode = 'story' then perform public.world_story_round(p_fight); return; end if;$n$);

select pg_temp.yh_patch('public.world_gw_start(uuid)',
  $o$  if f.mode = 'story' then
    br := public.world_boss_fight_rules(p_fight);$o$,
  $n$  if f.boss_id = 'gapgwi' then
    br := public.world_boss_fight_rules(p_fight);
    update public.world_gw_fights set status = 'fight',
           max_hp = round(greatest((br ->> 'hp_min')::numeric, sa * (br ->> 'hp_atk')::numeric) * (br -> 'hp_n' ->> (least(4, n) - 1))::numeric),
           hp = round(greatest((br ->> 'hp_min')::numeric, sa * (br ->> 'hp_atk')::numeric) * (br -> 'hp_n' ->> (least(4, n) - 1))::numeric), phase = 1, round = 0, cycle = 0,
           ends_at = now() + make_interval(mins => (br ->> 'min')::int), updated_at = now() where fight_id = p_fight;
    if n = 1 and f.mode <> 'story' then update public.world_gw_members m set stats = m.stats || public.world_solo_aid(m.job_key, 'gapgwi') where fight_id = p_fight; end if;
    perform public.world_gg_begin(p_fight, n);
    perform public.world_gw_next_round(p_fight);
    return;
  end if;
  if f.mode = 'story' then
    br := public.world_boss_fight_rules(p_fight);$n$);

