    "seq": [{"at": 100, "m": ["arrow"]}, {"at": 87.5, "m": ["arrow", "brush", "gust"]}, {"at": 75, "m": ["brush", "drop", "num", "gust"]}, {"at": 50, "m": ["brush", "drop", "tower", "num", "big", "gust"]},
      {"at": 37.5, "m": ["arrow", "tower", "clock", "big", "gust", "drop", "num"]}, {"at": 25, "m": ["arrow", "drop", "brush", "clock", "big", "num"]}]}, "raw_n": [1, 1.2, 1.4, 1.4], "hp_atk": 6, "hp_min": 9000}$j$::jsonb);
