  $n$  return public.world_mk_raw(p_fight) * case when d then 2 else 1 end * case when public.world_ug_wm_on(p_fight) then coalesce((public.world_ug_wm_cfg(p_fight) ->> 'hand')::numeric, 1) else 1 end;$n$);

