do $c$ declare x jsonb; ok boolean; miss text[] := '{}';
begin
  for x in select jsonb_array_elements(public.world_ultimate_rules() -> 'shop') loop
    ok := case x ->> 'kind'
      when 'item' then exists (select 1 from public.world_item_catalog where item_id = x ->> 'id')
      when 'outfit' then public.world_avatar_parts() -> 'outfits' ? (x ->> 'id')
      when 'pet' then exists (select 1 from public.world_pet_species where pet_id = x ->> 'id')
      when 'name_style' then x ->> 'id' like 'ns:%'
      else exists (select 1 from public.world_cosmetic_catalog where cosmetic_key = x ->> 'id') end;
    if not ok then miss := miss || (x ->> 'name'); end if;
  end loop;
  if cardinality(miss) > 0 then raise exception '극 판 교환 물품이 없음: %', array_to_string(miss, ', '); end if;
end $c$;
insert into public.world_title_catalog(title_key, title_name, description, condition_text, bonus, hidden, rule, sort, category, grade)
select x.title_key, x.title_name, x.description, case when x.hidden then '숨겨진 조건' else x.cond end, x.bonus, x.hidden, x.rule, 3200 + x.n, '무용담', x.grade
  from jsonb_to_recordset($J$[{"title_key":"ug_gwiheo_1","title_name":"무용담 속 귀허를 건넌 이","grade":5,"bonus":{},"rule":{"n":1,"ev":"ug_win","p":{"board":"gwiheo"}},"cond":"무용담 · 귀허의 주인을 깬다","hidden":false,"description":"무용담 · 귀허의 주인을 깬다.","n":0},{"title_key":"ug_gwiheo_10","title_name":"소용돌이를 길들인 이","grade":5,"bonus":{},"rule":{"n":10,"ev":"ug_win","p":{"board":"gwiheo"}},"cond":"무용담 · 귀허의 주인을 10번 깬다","hidden":false,"description":"무용담 · 귀허의 주인을 10번 깬다.","n":1},{"title_key":"ug_mukjeok_1","title_name":"무용담 속 명부를 다시 쓴 이","grade":5,"bonus":{},"rule":{"n":1,"ev":"ug_win","p":{"board":"mukjeok"}},"cond":"무용담 · 먹그림자를 깬다","hidden":false,"description":"무용담 · 먹그림자를 깬다.","n":2},{"title_key":"ug_mukjeok_10","title_name":"아홉 칸의 주인","grade":5,"bonus":{},"rule":{"n":10,"ev":"ug_win","p":{"board":"mukjeok"}},"cond":"무용담 · 먹그림자를 10번 깬다","hidden":false,"description":"무용담 · 먹그림자를 10번 깬다.","n":3},{"title_key":"ug_gapgwi_1","title_name":"무용담 속 장부를 덮은 이","grade":5,"bonus":{},"rule":{"n":1,"ev":"ug_win","p":{"board":"gapgwi"}},"cond":"무용담 · 값귀를 깬다","hidden":false,"description":"무용담 · 값귀를 깬다.","n":4},{"title_key":"ug_gapgwi_10","title_name":"셈이 끝난 밤","grade":5,"bonus":{},"rule":{"n":10,"ev":"ug_win","p":{"board":"gapgwi"}},"cond":"무용담 · 값귀를 10번 깬다","hidden":false,"description":"무용담 · 값귀를 10번 깬다.","n":5},{"title_key":"ug_duo","title_name":"둘이서 끝을 본 이","grade":5,"bonus":{},"rule":{"n":1,"ev":"ug_win","p":{"duo":true}},"cond":"둘이서 무용담 하나를 깬다","hidden":true,"description":"둘이서 무용담 하나를 깬다.","n":6},{"title_key":"ug_flawless","title_name":"아무도 쓰러지지 않은 끝","grade":5,"bonus":{},"rule":{"n":1,"ev":"ug_win","p":{"flawless":true}},"cond":"아무도 쓰러지지 않고 무용담 하나를 깬다","hidden":true,"description":"아무도 쓰러지지 않고 무용담 하나를 깬다.","n":7},{"title_key":"ug_all","title_name":"부풀린 이야기를 모두 겪은 이","grade":5,"bonus":{},"rule":{"all":[{"p":{"board":"gwiheo"},"ev":"ug_win"},{"p":{"board":"mukjeok"},"ev":"ug_win"},{"p":{"board":"gapgwi"},"ev":"ug_win"}]},"cond":"무용담 셋을 모두 깬다","hidden":false,"description":"무용담 셋을 모두 깬다.","n":8}]$J$::jsonb)
    as x(title_key text, title_name text, grade int, bonus jsonb, rule jsonb, cond text, hidden boolean, description text, n int)
on conflict (title_key) do update set title_name = excluded.title_name, description = excluded.description, condition_text = excluded.condition_text, bonus = excluded.bonus,
  hidden = excluded.hidden, rule = excluded.rule, category = excluded.category, grade = excluded.grade;
insert into public.world_quest_npcs(npc_key, npc_name, bio) select x.k, x.n, x.b from jsonb_to_recordset($J$[{"k":"q:ug_deoksam","n":"봉연 나루지기 덕삼","b":"구중 봉연 가라앉은 문 앞에서 거룻배를 지키는 늙은 나루지기. 물결 소리만 듣고도 문 아래에서 무엇이 뒤척이는지 안다고 큰소리친다."},{"k":"q:ug_hongmae","n":"묵창 주막 주모 홍매댁","b":"묵창 나루 주막을 꾸리는 주모. 손님이 흘린 이야기는 한 마디도 잊지 않고, 먹물 묻은 앞치마로 술상을 훔친다."},{"k":"q:ug_charang","n":"선착 등지기 차랑","b":"남문 수로 선착에서 뱃길 등을 지키는 젊은 등지기. 흰 밤에도 등심을 하루 세 번 손질한다."}]$J$::jsonb) as x(k text, n text, b text)
on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, sort, epilogue, active)
select x.quest_id, 'side', x.cat, x.title, x.summary, x.region_id, x.min_level, array(select jsonb_array_elements_text(x.after)), x.sort, x.epilogue, true from jsonb_to_recordset($J$[{"quest_id":"mdq_x_ug_gwiheo","cat":"무용담","title":"아홉 겹 무용담","summary":"구중 봉연 나루지기 덕삼이 객사에서 흘러온 부풀린 무용담을 전한다. 봉연의 물이 그 이야기를 받아 적어, 구중 봉주와 귀허의 주인이 이야기 속 모습으로 다시 깨어나려 한다.","region_id":"sealed_abyss","min_level":50,"after":["gq_5"],"sort":1490,"epilogue":[]},{"quest_id":"mdq_x_ug_mukjeok","cat":"무용담","title":"스물일곱 칸 무용담","summary":"묵창 주막 주모 홍매댁이 손님들이 떠드는 부풀린 무용담을 전한다. 아홉 칸 명부가 그 이야기를 받아 적어 먹그림자가 이야기 속 모습으로 다시 깨어나려 한다.","region_id":"mukchang_ferry","min_level":50,"after":["mkq_5"],"sort":1491,"epilogue":[]},{"quest_id":"mdq_x_ug_gapgwi","cat":"무용담","title":"흰 밤의 무용담","summary":"남문 수로 선착 등지기 차랑이 뱃사람들이 옮겨 온 부풀린 무용담을 전한다. 등도의 흰 밤이 그 이야기를 받아 적어, 값귀와 백야가 이야기 속 모습으로 다시 깨어나려 한다.","region_id":"deungdo_landing","min_level":50,"after":["mdq_17"],"sort":1492,"epilogue":[]}]$J$::jsonb) as x(quest_id text, kind text, cat text, title text, summary text, region_id text, min_level int, after jsonb, sort int, epilogue jsonb, active boolean)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, epilogue = excluded.epilogue, active = excluded.active;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward)
select x.quest_id, x.step, x.title, x.goal, x.need, x.lines, x.reward from jsonb_to_recordset($J$[{"quest_id":"mdq_x_ug_gwiheo","step":1,"title":"나루지기의 소문","goal":"구중 봉연에서 덕삼의 이야기를 듣는다","need":{"at":["sealed_abyss"],"tasks":[]},"lines":[{"s":null,"t":"구중 봉연의 가라앉은 문 앞에 거룻배 한 척이 매여 있었다. 뱃전에 걸터앉은 노인이 곰방대를 문 채 물결을 내려다보고 있었다."},{"s":null,"t":"노인은 내 발소리에 고개를 들더니 곰방대를 뱃전에 탁탁 털었다. 그러고는 반갑다는 듯 손짓으로 나를 불렀다."},{"s":"q:ug_deoksam","t":"{이름} 조사원 아니시오? 요즘 본부 객사에서 춘보라는 이야기꾼이 조사원 얘기를 떠든다더이다. 봉주가 봉인을 아홉 겹이나 한꺼번에 깨고 나왔는데 조사원이 맨손으로 도로 눌렀다나."},{"s":null,"t":"나는 그런 적이 없다고 했다. 덕삼은 껄껄 웃더니 곧 웃음을 거두고 문 아래 물을 가리켰다."},{"s":"q:ug_deoksam","t":"그 얘기가 장사꾼들 입을 타고 여기까지 왔소. 그런데 이 봉연 물이 고약하오. 문을 막을 때 이름을 잔뜩 묻어서 그런지, 물가에서 떠든 말을 그대로 받아 적는단 말이오. 보시오, 물결이 아홉 겹이오."},{"s":null,"t":"문 아래 물이 정말로 아홉 겹으로 출렁이고 있었다. 물결 위에 먹 글씨가 떠올랐다가 가라앉았다. 「구중 봉주 — 봉인 아홉 겹」. 글씨는 문 너머 귀허 쪽으로 흘러갔다."},{"s":"q:ug_deoksam","t":"글씨가 귀허로 흘러가오. 귀허의 주인 얘기도 부풀려졌다던데, 거기도 한번 가 보시겠소? 그 물가를 한 번 살펴 주시오."}],"reward":{}},{"quest_id":"mdq_x_ug_gwiheo","step":2,"title":"얼굴 아홉의 소문","goal":"귀허에 도착해 한 번 탐색한다","need":{"at":["gwiheo_core"],"tasks":[{"t":"travel","n":1,"r":["gwiheo_core"]},{"t":"search","n":1,"r":["gwiheo_core"]}]},"lines":[{"s":null,"t":"귀허의 빈 왕좌 둘레에서 소용돌이가 다시 돌고 있었다. 물속에서 얼굴 둘이 번갈아 떠올랐다. 얼굴이 떠오를 때마다 그 둘레에 흐릿한 얼굴이 하나씩 더 맺혔다가 흩어졌다."},{"s":null,"t":"왕좌 아래 물가에 작은 글씨가 한 줄 떠 있었다. 「앞의 것을 보내지 못하면 뒤의 것을 만나지 못한다.」 이야기 속에서는 봉주와 주인이 한 판에 이어져 있었다. 나는 그 줄을 수첩에 옮겨 적고 구중 봉연으로 돌아갔다."}],"reward":{}},{"quest_id":"mdq_x_ug_gwiheo","step":3,"title":"아홉 겹 무용담","goal":"구중 봉연에 도착해 덕삼에게 알린다","need":{"at":["sealed_abyss"],"tasks":[{"t":"travel","n":1,"r":["sealed_abyss"]}]},"lines":[{"s":null,"t":"덕삼은 그때까지 거룻배에서 기다리고 있었다. 내가 귀허에서 본 것을 들려주자 덕삼이 곰방대를 입에서 떼고 한참 물결을 내려다보았다."},{"s":"q:ug_deoksam","t":"봉주를 넘어야 주인을 만나는 이야기라. 그럼 그 이야기를 끝까지 겪어 주는 수밖에 없소. 끝을 본 이야기는 물이 잠깐 덮어 둔다오. 이야기꾼이 또 떠들면 또 적히겠지만."},{"s":"q:ug_deoksam","t":"이야기 속 봉주와 주인은 무엇을 할지 미리 말해 주지 않을 거요. 다만 물결을 잘 보시오. 덮치기 전에 반드시 물빛이 먼저 바뀌오. 그 대신 아무리 져도 잃는 건 없습니다. 혼자서는 못 들어가고, 둘에서 넷까지 함께 가야 합니다. 그리고 다 같이 칼만 휘두르면 못 넘습니다. 노림을 받아 버텨 줄 사람이나 다친 이를 돌볼 사람이 꼭 함께여야 합니다."},{"s":null,"t":"덕삼이 뱃바닥에서 작은 궤짝 하나를 끌어냈다. 궤짝 안에는 물에서 건진 물건들이 가지런히 들어 있었다."},{"s":"q:ug_deoksam","t":"이야기를 끝맺을 때마다 물에서 귀허 등심이 떠오를 거요. 그걸 가져오면 내가 건져 둔 것들과 바꿔 드리리다. 빈 왕좌며 사슬 등롱이며, 다 이 물에서 건진 거요."}],"reward":{}},{"quest_id":"mdq_x_ug_mukjeok","step":1,"title":"주막의 이야기","goal":"묵창 나루에서 홍매댁의 이야기를 듣는다","need":{"at":["mukchang_ferry"],"tasks":[]},"lines":[{"s":null,"t":"묵창 주막은 저녁 손님으로 붐볐다. 주모 홍매댁이 먹물 묻은 앞치마로 술상을 훔치다가 나를 보고 손을 멈췄다."},{"s":"q:ug_hongmae","t":"어머, 이야기 속 그분이 오셨네. 요새 손님들이 죄 조사원님 얘기예요. 먹그림자가 칸을 스물일곱 개로 늘려 놓았는데, 조사원님이 눈을 감고도 밟을 칸을 다 맞혔다던가요."},{"s":null,"t":"나는 칸은 아홉이었고 눈을 감은 적도 없다고 했다. 홍매댁이 깔깔 웃더니 주막 뒤 나루 쪽을 턱으로 가리켰다."},{"s":"q:ug_hongmae","t":"저도 처음엔 웃었죠. 그런데 그 얘기가 돌고부터 나루 물에 먹줄이 떠요. 꼭 칸을 긋는 것처럼요. 아홉 칸 뜰에 한번 가 보세요. 거기 명부가 그 얘기를 받아 적고 있는 것 같아요."}],"reward":{}},{"quest_id":"mdq_x_ug_mukjeok","step":2,"title":"스물일곱 칸","goal":"아홉 칸 뜰에 도착해 한 번 탐색한다","need":{"at":["nine_court"],"tasks":[{"t":"travel","n":1,"r":["nine_court"]},{"t":"search","n":1,"r":["nine_court"]}]},"lines":[{"s":null,"t":"아홉 칸 뜰의 칸들은 모두 빛나고 있었다. 그런데 칸 하나하나에 가는 먹줄이 그어져 다시 아홉으로 나뉘려 하고 있었다."},{"s":null,"t":"가운데 칸의 먹이 저절로 글자를 이루었다. 「먹그림자」였다. 그 아래에는 손님들 말투 그대로 한 줄이 덧붙어 있었다. 「먹이 떨어지기 전에 칸이 먼저 젖었다지 뭐요.」 나는 그 줄을 옮겨 적고 묵창 나루로 돌아갔다."}],"reward":{}},{"quest_id":"mdq_x_ug_mukjeok","step":3,"title":"스물일곱 칸 무용담","goal":"묵창 나루에 도착해 홍매댁에게 알린다","need":{"at":["mukchang_ferry"],"tasks":[{"t":"travel","n":1,"r":["mukchang_ferry"]}]},"lines":[{"s":null,"t":"홍매댁은 주막 문을 닫고 나를 기다리고 있었다. 내가 아홉 칸 뜰에서 본 줄을 읽어 주자 홍매댁이 앞치마를 꼭 쥐었다."},{"s":"q:ug_hongmae","t":"칸이 먼저 젖는다니, 그게 단서네요. 이야기를 끝까지 겪으면 명부가 잠깐 덮인대요. 손님들이 또 떠들면 또 적히겠지만요. 그 대신 아무리 져도 잃는 건 없어요. 혼자서는 못 들어가고, 둘에서 넷까지 함께 가야 해요. 그리고 다 같이 칼만 휘두르면 못 넘어요. 노림을 받아 버텨 줄 사람이나 다친 이를 돌볼 사람이 꼭 함께여야 해요."},{"s":null,"t":"홍매댁이 주막 다락에서 보따리 하나를 내려왔다. 먹빛 옷가지와 붓걸이, 바둑상 같은 것이 들어 있었다."},{"s":"q:ug_hongmae","t":"이야기를 끝맺을 때마다 명부 먹심이 남을 거예요. 그걸 가져오시면 이것들과 바꿔 드릴게요. 다 손님들이 술값 대신 맡기고 간 물건이에요."}],"reward":{}},{"quest_id":"mdq_x_ug_gapgwi","step":1,"title":"등지기의 소문","goal":"남문 수로 선착에서 차랑의 이야기를 듣는다","need":{"at":["deungdo_landing"],"tasks":[]},"lines":[{"s":null,"t":"남문 수로 선착의 뱃길 등 아래에서 젊은 등지기가 등심을 손질하고 있었다. 등지기는 나를 보더니 손에 묻은 기름을 바지에 닦고 다가왔다."},{"s":"q:ug_charang","t":"{이름} 조사원님이시죠? 저는 이 선착 등을 지키는 차랑이에요. 요새 뱃사람들이 객사에서 들었다는 이야기를 옮겨 와요. 값귀 주판알이 산더미였고, 백야가 등 일곱을 한꺼번에 껐다고요."},{"s":null,"t":"나는 그 이야기의 절반은 꾸민 말이라고 했다. 차랑이 고개를 끄덕이면서도 선착 등 하나를 가리켰다. 등이 아무 바람도 없는데 깜빡이고 있었다."},{"s":"q:ug_charang","t":"그 얘기가 들어오고부터 등이 저래요. 흰 밤이 사람들 말을 받아 적는 것 같아요. 붉은 사당 골목부터 가 보시겠어요? 주판 소리가 다시 난대요."}],"reward":{}},{"quest_id":"mdq_x_ug_gapgwi","step":2,"title":"주판알 산더미","goal":"붉은 사당 골목에 도착해 한 번 탐색한다","need":{"at":["red_shrine_lane"],"tasks":[{"t":"travel","n":1,"r":["red_shrine_lane"]},{"t":"search","n":1,"r":["red_shrine_lane"]}]},"lines":[{"s":null,"t":"붉은 사당 마룻바닥 밑에서 주판알 튕기는 소리가 났다. 마룻바닥 틈으로 주판알이 넘쳐 계단까지 굴러 나와 있었다."},{"s":null,"t":"틈 사이로 「값귀」라는 먹 글씨가 비쳤다. 글씨 끝에서 가는 먹줄 하나가 맹약 마당 쪽으로 뻗어 나가 있었다. 나는 그 줄을 따라 맹약 마당으로 갔다."}],"reward":{}},{"quest_id":"mdq_x_ug_gapgwi","step":3,"title":"한꺼번에 꺼진 등","goal":"맹약 마당에 도착해 한 번 탐색한다","need":{"at":["pact_court"],"tasks":[{"t":"travel","n":1,"r":["pact_court"]},{"t":"search","n":1,"r":["pact_court"]}]},"lines":[{"s":null,"t":"맹약 마당에 들어서는 순간 일곱 자리 등이 한꺼번에 깜빡였다가 다시 켜졌다. 돌상 위 서리를 쓸자 사당에서 뻗어 온 먹줄이 「백야」라는 이름에 닿아 「값귀」와 한 장처럼 이어져 있었다."},{"s":null,"t":"돌상 모서리에 뱃사람 말투로 적힌 줄이 하나 있었다. 「꺼지기 전에 등이 먼저 떨었다지.」 나는 그 줄을 옮겨 적고 남문 수로 선착으로 돌아갔다."}],"reward":{}},{"quest_id":"mdq_x_ug_gapgwi","step":4,"title":"흰 밤의 무용담","goal":"남문 수로 선착에 도착해 차랑에게 알린다","need":{"at":["deungdo_landing"],"tasks":[{"t":"travel","n":1,"r":["deungdo_landing"]}]},"lines":[{"s":null,"t":"차랑은 선착 등 아래에서 나를 기다리고 있었다. 내가 사당과 마당에서 본 것을 들려주자 차랑이 깜빡이는 등을 올려다보았다."},{"s":"q:ug_charang","t":"등이 먼저 떤다니, 저희 등지기들이 늘 보는 거예요. 꺼지기 전엔 꼭 떨거든요. 값귀를 넘어야 백야를 만나는 이야기네요. 끝까지 겪으면 흰 밤이 그 이야기를 잠깐 덮어 둔대요. 그 대신 아무리 져도 잃는 건 없어요. 혼자서는 못 들어가고, 둘에서 넷까지 함께 가야 해요. 그리고 다 같이 칼만 휘두르면 못 넘어요. 노림을 받아 버텨 줄 사람이나 다친 이를 돌볼 사람이 꼭 함께여야 해요."},{"s":null,"t":"차랑이 선착 창고 문을 열었다. 안에는 주판 탁자와 일곱 등 진열대, 흰 밤 빛깔 철릭 같은 것이 쌓여 있었다."},{"s":"q:ug_charang","t":"이야기를 끝맺을 때마다 장부 셈가지가 남을 거예요. 그걸 가져오시면 여기 있는 것들과 바꿔 드릴게요. 다 등도에서 건져 온 물건이에요."}],"reward":{}}]$J$::jsonb) as x(quest_id text, step int, title text, goal text, need jsonb, lines jsonb, reward jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
do $g$ declare n int; begin
  if (select count(*) from (select npc_key from public.world_quest_npcs union select npc_key from public.world_faction_npcs) n where n.npc_key = any('{black_lotus:guseul,mandate_court:hahu,mandate_court:seo,night_office:baek,night_office:han,night_office:mo,north_league:seok,north_league:yeo,q:g_dani,q:g_juji,q:g_lord,q:g_memory,q:g_mukho,q:g_sagong,q:g_yeoul,q:m_baekmu,q:m_dohwa,q:m_gaon,q:m_sawol,q:m_yeon,q:m_yun,red_moon_cult:danbi,red_moon_cult:sama,red_moon_cult:wolhwa,river_alliance:jin,river_alliance:nodeul,southern_remnant:galmae,southern_remnant:jang,southern_remnant:soi}'::text[])) <> 29 then raise exception '홍인사·요인록 대본: 없는 말하는이 키'; end if;
end $g$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "정청의 새벽은 아직 어두웠다. 등잔 기름 냄새 사이로 장부 넘기는 소리만 사락사락 들렸다."}, {"s": null, "t": "창가 자리의 서기관이 붓을 내려놓고 일어섰다. 걷어 올린 소매 아래 팔목에 먹 자국이 점점이 묻어 있었다."}, {"s": "q:m_yeon", "t": "{이름} 님이죠? 왔군요. 오늘부터 {이름} 님을 맡게 된 담당 서기관 연서희예요. 반가워요."}, {"s": "q:m_yeon", "t": "호위대에서 왔군요. 칼 든 사람이 붙어 주면 서고 사람들이 덜 떨어요. 앞은 맡길게요.", "job": "artificer"}, {"s": "q:m_yeon", "t": "월궁 사수군요. 눈이 밝다고 들었어요. 오늘은 그 눈이 제일 필요해요.", "job": "scout"}, {"s": "q:m_yeon", "t": "퇴마관이군요. 방울 소리를 들으니 든든하네요. 사당 쪽 일이 생기면 먼저 부를게요.", "job": "exorcist"}, {"s": "q:m_yeon", "t": "의무관이군요. 솔직히 반가워요. 지난달엔 돌아오지 못한 사람이 둘이었거든요.", "job": "medic"}, {"s": "q:m_yeon", "t": "봉인술사군요. 이번 일엔 봉인 장부가 얽혀 있어요. 그 눈으로 봐 주면 좋겠어요.", "job": "sealmaster"}, {"s": "q:m_yeon", "t": "암영에서 왔군요. 어둠 속에서 틈을 읽는 눈이 있다고요. 금고 자물쇠부터 한번 봐 줘요.", "job": "analyst"}, {"s": "q:m_yeon", "t": "조련사군요. 곁에 있는 동무도 반가워요. 서고엔 쥐구멍이 많으니 그 코가 쓸모 있을 거예요.", "job": "tamer"}, {"s": "q:m_yeon", "t": "본부 직속이면 장부 보는 법은 알겠네요. 출납관이 반가워하겠어요.", "affil": "headquarters"}, {"s": "q:m_yeon", "t": "현장대응국에서 넘어왔다고요? 들녘 순찰조가 아쉬워하겠네요.", "affil": "fieldbureau"}, {"s": "q:m_yeon", "t": "기록감찰국이라… 빈 쪽을 처음 찾은 게 그쪽 사람이었죠. 잘 왔어요.", "affil": "archivebureau"}, {"s": "q:m_yeon", "t": "봉인관리국 사람이면 인장이 얼마나 무서운 물건인지 알 거예요.", "affil": "sealbureau"}, {"s": "q:m_yeon", "t": "의무지원국이면 객사 의원 쪽이죠? 다치면 제일 먼저 그리로 가요.", "affil": "medicalbureau"}, {"s": "q:m_yeon", "t": "외부 협력자라… 명부에 이름만 있으면 돼요. 여기선 누구나 같은 밤을 걸어요.", "affil": "independent"}, {"s": null, "t": "연서희가 내 얼굴을 찬찬히 들여다보았다. 눈 밑이 부었다며 웃었다."}, {"s": "q:m_yeon", "t": "오는 길에 잠은 좀 잤어요? 첫날부터 얼굴이 퉁퉁하네요."}, {"s": null, "t": "나는 오는 길에 이상한 꿈을 꿨다고 말했다. 해가 뜨지 않는 밤이었고, 등불이 하나씩 꺼지다가 마지막엔 정청 등불 하나만 남았다고 했다."}, {"s": null, "t": "연서희의 붓끝이 허공에서 멈췄다. 연서희가 아주 잠깐 나를 바라보았다."}, {"s": "q:m_yeon", "t": "해가 뜨지 않는 밤이요? …글쎄요. 어젯밤은 별일 없이 조용했어요. 정청에 처음 오는 사람들은 다들 그런 꿈을 꾼다더라고요."}, {"s": null, "t": "서가 뒤에서 늙은 서리 하나가 「간밤에 정청 등불 하나가 새벽까지 안 꺼졌다더군. 누가 밤새 장부를 붙들고 있었나.」 하고 하품 섞인 목소리로 중얼거렸다."}, {"s": null, "t": "연서희의 손끝에 붉은 인주가 희미하게 묻어 있었다. 연서희가 아무렇지 않게 소매로 그 손끝을 덮었다."}, {"s": "q:m_yeon", "t": "꿈 얘기는 나중에 해요. 이름이 장부에 남아 있으면, 아침은 다시 와요."}, {"s": null, "t": "연서희가 책상 밑에서 대나무 잎에 싼 것을 꺼내 내 손에 쥐여 주었다. 아직 따뜻한 보리 주먹밥이었다."}, {"s": "q:m_yeon", "t": "먹으면서 들어요. 정청 첫날은 다들 밥을 거르더라고요. 저도 그랬고요."}, {"s": null, "t": "나는 고맙다고 하고 한 입 베어 물었다. 소금 간이 짭짤했다."}, {"s": "q:m_yeon", "t": "인사는 짧게 할게요. 어젯밤 부적 출납 장부에서 몇 쪽이 통째로 비었어요. 그리고 금고에 있어야 할 붉은 인장이 없어졌고요."}, {"s": null, "t": "옆 책상에서 장부를 맞추던 사내가 붓을 내려놓았다. 소매 끝에 먹물이 배어 있었다. 사내는 장부를 펴 보지도 않고 입을 열었다."}, {"s": "q:m_yun", "t": "정확히는 쉰두 쪽부터 쉰일곱 쪽까지입니다. 청명 부적 서른 장, 봉인 부적 열두 장이 적힌 자리였지요."}, {"s": "q:m_yeon", "t": "출납관 윤도한이에요. 장부라면 이 사람만 한 사람이 없죠."}, {"s": "q:m_yun", "t": "반갑습니다, 조사원 님. 앞으로 운임이며 보급은 제 장부로 달아 두십시오. 처음 오신 분들은 뭘 얼마나 써야 할지 모르시니까요."}, {"s": null, "t": "나는 주먹밥을 든 채 엉거주춤 고개를 숙였다. 윤도한이 그 모양을 보고 빙그레 웃었다."}, {"s": "q:m_yeon", "t": "부적 장부라도 받아 간 사람 이름이 함께 적혀요. 이름은 사람을 이 세상에 묶어 두는 명줄이라, 장부 한 쪽이 비면 그만큼 사람이 비는 거예요."}, {"s": "q:m_yeon", "t": "그러니까 우리가 찾는 건 인장만이 아니에요. 그 여섯 쪽에 적혀 있던 이름들이에요."}, {"s": "q:m_yeon", "t": "먼저 장서각 지하서고로 가 보세요. 기록관 모가람이 기다려요. 도려낸 자리를 제일 잘 읽는 사람이 그분이거든요. 갈 곳은 지도에서 고르면 돼요."}, {"s": null, "t": "나는 주먹밥을 마저 입에 넣고 다녀오겠다고 했다."}]'::jsonb where quest_id = 'mq_red_seal' and step = 1 and md5(need::text) = md5('{"at": ["hq_yard"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_seal'' and step = 1 and md5(need::text) = '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "계단을 내려가자 공기가 차가워졌다. 서가 사이에서 촛불 하나가 가늘게 흔들렸다."}, {"s": null, "t": "둥근 얼굴의 기록관이 책 더미 사이에서 고개를 쏙 내밀었다. 소매에 먼지가 하얗게 묻어 있었다."}, {"s": "night_office:mo", "t": "아, 연 서기관이 보낸 분이죠? 어서 와요, 어서. 먼지는 신경 쓰지 말고요."}, {"s": "night_office:mo", "t": "보리차 한 잔 드실래요? 식었어요. 뜨거운 차는 종이에 해롭거든요."}, {"s": null, "t": "모가람이 찻잔을 내밀었다. 나는 한 모금 마셨다. 미지근하고 구수했다."}, {"s": null, "t": "나는 사라진 쪽을 보러 왔다고 했다."}, {"s": "night_office:mo", "t": "사라진 쪽이요? 찢긴 게 아니에요. 칼로 반듯하게 도려냈어요. 손에 익은 사람 솜씨죠."}, {"s": "night_office:mo", "t": "해마다 오래된 쪽을 거둘 때도 이렇게 반듯하게 잘라 내긴 해요. 그런데 이건 거둘 쪽이 아니었어요. 작년에 적은 거거든요."}, {"s": null, "t": "나는 거둔다는 게 무슨 말이냐고 물었다. 모가람이 웃으며 괜히 찻주전자 뚜껑을 만지작거렸다."}, {"s": "night_office:mo", "t": "아, 그건 서고 살림 얘기예요. 낡은 종이는 내보내야 새 종이가 들어오죠. 그보다 큰일은 따로 있어요."}, {"s": "night_office:mo", "t": "요 며칠 책벌레 요괴가 들끓어서 남은 쪽까지 갉아 먹고 있어요. 글자를, 특히 이름을 갉아 먹고 사는 놈들이라 장부엔 제일 해로워요."}, {"s": "night_office:mo", "t": "놈들이 남은 쪽을 다 먹어 치우기 전에 장부를 꺼내야 하는데, 저는 붓만 쥐어 봤지 칼은 못 쥐어 봤어요."}, {"s": null, "t": "그때 뒤에서 또각또각 발소리가 났다. 검은 관복 차림의 감찰관이 장부 하나를 옆구리에 끼고 다가왔다."}, {"s": "night_office:han", "t": "모 기록관. 외부 출입 기록부터 남기십시오. 조사원도 예외는 없습니다."}, {"s": "night_office:mo", "t": "네, 네, 감찰관님. 저분이 감찰관 한설이에요. 무서워 보여도 공정한 분이랍니다."}, {"s": null, "t": "한설이 출입 장부를 펼쳐 내 앞에 놓았다. 나는 이름 칸에 내 이름을 적었다."}, {"s": "night_office:han", "t": "획을 흘리지 마십시오. 이곳 장부에 한 번 적힌 이름은 오래 남습니다."}, {"s": null, "t": "나는 마지막 획을 끝까지 눌러 다시 그었다. 한설이 장부를 한참 내려다보다가 짧게 고개를 끄덕였다."}, {"s": "night_office:han", "t": "…됐습니다. 책벌레는 이름 획부터 갉습니다. 서고 안쪽을 탐색하면 먹 냄새를 맡고 기어 나올 겁니다."}, {"s": "night_office:mo", "t": "두 마리만 잡아 주세요. 그러면 놈들이 숨겨 둔 장부를 꺼내 올 수 있어요. 다치면 바로 올라오고요!"}]'::jsonb where quest_id = 'mq_red_seal' and step = 2 and md5(need::text) = md5('{"at": ["hq_archive"], "tasks": [{"n": 1, "r": ["hq_archive"], "t": "travel"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_seal'' and step = 2 and md5(need::text) = '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "마지막 책벌레가 바스락거리며 서가 밑으로 기어들려 했다. 내가 내리치자 퍽 소리와 함께 몸뚱이가 터졌다."}, {"s": null, "t": "쓰러진 책벌레의 배 속에서 젖은 종잇조각이 주르르 흘러나왔다."}, {"s": "night_office:mo", "t": "어머, 장부 종이예요. 그런데 왜 젖어 있지? 서고엔 물기가 없는데."}, {"s": null, "t": "나는 종이를 코에 대 보고 비린내가 난다고 말했다."}, {"s": "night_office:mo", "t": "물비린내네요. 고인 물, 오래된 수로 바닥 같은. 이상하다."}, {"s": "night_office:han", "t": "누군가 물 묻은 손으로 서고에 들어왔다는 뜻입니다. 기록해 두지요."}, {"s": null, "t": "한설이 붓을 꺼내 수건으로 천천히 닦았다. 한 번, 또 한 번, 아주 천천히 닦았다."}, {"s": "night_office:mo", "t": "보세요, 감찰관님이 붓을 저렇게 천천히 닦으면 화가 많이 나신 거예요."}, {"s": "night_office:han", "t": "모 기록관."}, {"s": "night_office:mo", "t": "네, 네. 입 다물게요."}, {"s": null, "t": "모가람이 내 쪽으로 눈을 찡긋했다. 나는 웃음을 참느라 입술을 깨물었다."}, {"s": "night_office:mo", "t": "지워진 자리를 읽으려면 야령초가 있어야 해요. 태운 연기를 쐬면 지운 먹 자국이 떠오르거든요."}, {"s": "night_office:mo", "t": "잿빛 들녘 채집터에 많이 나요. 제가 캐 오면 좋겠지만 들녘엔 요괴가 나와서요. 세 번 캐다가 저한테 가져다주세요. 바로 태워 볼게요."}]'::jsonb where quest_id = 'mq_red_seal' and step = 3 and md5(need::text) = md5('{"at": ["hq_archive"], "tasks": [{"m": ["g_hq_archive"], "n": 2, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_seal'' and step = 3 and md5(need::text) = '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "모가람이 야령초를 화로에 얹었다. 마른 잎이 타닥타닥 타며 푸른 연기가 피어올랐다."}, {"s": null, "t": "연기는 위로 흩어지지 않았다. 빈 쪽 위로 천천히 내려앉더니 종이 결 사이로 스며들었다."}, {"s": null, "t": "하얗던 자리에 붉은 점이 하나 돋았다. 점은 먹물이 번지듯 퍼져 둥근 테를 이루었고, 그 안에 글자가 차례로 떠올랐다."}, {"s": null, "t": "인장을 찍은 자국이었다. 글자는 모두 거울에 비친 것처럼 거꾸로 돌아가 있었다. 손끝에 닿은 종이가 얼음처럼 차가웠다."}, {"s": "night_office:mo", "t": "어머나… 서른 해 서고를 지켰는데 이런 건 처음이에요."}, {"s": "night_office:mo", "t": "이건 봉인식을 반대로 읊으면서 찍은 자국이에요. 봉인을 거는 게 아니라 푸는 쪽으로요."}, {"s": "night_office:han", "t": "붉은 인장은 정청 금고에만 있습니다. 그 인장으로 봉인을 거꾸로 돌렸다면."}, {"s": "night_office:mo", "t": "안에 있는 사람이라는 얘기죠. 아이고, 머리야."}, {"s": "night_office:han", "t": "섣부른 말은 하지 마십시오. 증거 없이 적힌 말은 증거 없이 지워집니다."}, {"s": null, "t": "나는 봉인식은 어디에서 지내느냐고 물었다."}, {"s": "night_office:han", "t": "원래는 폐쇄 사당에서 지냈습니다. 인장을 거꾸로 돌렸다면 그 자리에 흔적이 남았을 겁니다."}, {"s": "night_office:han", "t": "조사원, 폐쇄 사당을 두어 번 탐색해 보고 정청의 연 서기관에게 보고하십시오. 이 사건 장부는 연 서기관이 맡았습니다."}, {"s": "night_office:mo", "t": "사당은 추워요. 보리차 한 병 싸 드릴게요. 식은 거지만요."}, {"s": null, "t": "나는 식은 것도 괜찮다고 했다. 모가람이 소리 내어 웃으며 병마개를 꼭 눌러 닫아 주었다."}]'::jsonb where quest_id = 'mq_red_seal' and step = 4 and md5(need::text) = md5('{"at": ["hq_archive"], "give": {"herb": 3}, "tasks": [{"n": 3, "r": ["field_outskirts"], "t": "gather", "items": ["herb"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_seal'' and step = 4 and md5(need::text) = '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "사당 마당의 금줄은 끊겨 있었다. 제단의 촛농을 손가락으로 누르자 아직 말랑했다. 누군가 바로 얼마 전에 다녀간 자리였다."}, {"s": null, "t": "정청으로 돌아오자 연서희가 붓을 놓고 달려 나왔다. 내 소매에 묻은 흙을 탁탁 털어 주었다."}, {"s": "q:m_yeon", "t": "수고했어요. 처음치고 아주 잘했어요. 다친 데는 없죠?"}, {"s": null, "t": "나는 다친 데는 없다고 했다. 사당 촛농이 아직 굳지 않았다는 것도 말했다."}, {"s": "q:m_yeon", "t": "거꾸로 찍힌 인장, 젖은 종이, 사당의 촛농이라. 하나로 이어질 것 같은데 아직 근거가 없어요."}, {"s": "q:m_yeon", "t": "윤 출납관, 금고 열쇠 기록 좀 뽑아 줄래요? 윤 출납관?"}, {"s": null, "t": "윤도한은 창밖을 보고 있었다. 한 박자 늦게 고개를 들었다."}, {"s": "q:m_yun", "t": "아, 예. 곧 가져다 드리지요. 잠시 딴생각을 했습니다."}, {"s": null, "t": "윤도한이 서랍을 열었다. 서랍 안에서 젖은 걸레 냄새가 희미하게 풍겼다가 이내 사라졌다."}, {"s": "q:m_yeon", "t": "쉰두 쪽부터 쉰일곱 쪽까지예요. 거기 적혀 있던 사람들을 찾아 줘야 해요. 장부에서 빠진 채로 두면 그 사람들은 정말로 빠지는 거니까요."}, {"s": "q:m_yeon", "t": "이제 장서각 지하서고와 폐쇄 사당에서 단서를 찾아요. 탐색하다 보면 단서가 보일 거예요. 찾은 단서는 일지에서 짝을 맞춰 보면 돼요."}]'::jsonb where quest_id = 'mq_red_seal' and step = 5 and md5(need::text) = md5('{"at": ["hq_yard"], "tasks": [{"n": 2, "r": ["shrine_ruins"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_seal'' and step = 5 and md5(need::text) = '; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "연서희가 단서를 맞춘 일지를 한참 들여다보았다. 등잔불이 그 위에서 흔들렸다."}, {"s": "q:m_yeon", "t": "정리할게요. 누군가 붉은 인장을 들고 사당에서 봉인식을 거꾸로 돌렸어요. 봉인을 건 게 아니라 푼 거예요."}, {"s": "q:m_yeon", "t": "그리고 그 사람이 쓴 먹물에서 물비린내가 나요. 서고에서도, 사당에서도."}, {"s": "night_office:mo", "t": "먹에 물 섞는 데야 많죠. 그런데 이건 고인 물 냄새예요. 오래된 수로 바닥 같은."}, {"s": "q:m_yun", "t": "구룡 폐수로겠지요. 그 물은 녹이 섞여서 먹이 푸르스름하게 번집니다."}, {"s": "q:m_yeon", "t": "그런 것까지 알아요?"}, {"s": "q:m_yun", "t": "출납을 오래 하다 보면 이것저것 주워듣게 됩니다."}, {"s": "night_office:han", "t": "사라진 쪽은 아직 어딘가에 있습니다. 젖은 채로."}, {"s": null, "t": "한설이 내 보고서를 집어 들고 끝까지 읽었다. 쉼표 하나를 손톱으로 짚었다가 그냥 넘어갔다."}, {"s": "q:m_yeon", "t": "봤어요? 감찰관님은 보고서마다 쉼표 하나까지 짚어서 「한 줄 더」 하고 돌려보내는 분이에요. 신입들 사이에선 아예 별명이 「한 줄 더」예요. 그런 분이 첫 보고서를 한 번에 넘겼어요."}, {"s": "q:m_yeon", "t": "좋아요. 다음은 물길이에요. 조금 더 단련하고 오면, 그때 함께 따라가 봐요."}]'::jsonb where quest_id = 'mq_red_seal';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "정청 마당 물통 옆에 젖은 종이 한 장이 널려 있었다. 먹이 푸르스름하게 번져 있었다."}, {"s": null, "t": "연서희가 부채로 종이를 살살 부치고 있었다. 나는 바람에 들썩이는 종이 귀퉁이를 손가락으로 눌러 주었다."}, {"s": "q:m_yeon", "t": "고마워요. 조금만 더 누르고 있어요. 마르면서 오그라들면 글자가 갈라지거든요."}, {"s": "q:m_yeon", "t": "구름나루 뱃사공이 강에서 건져 보냈어요. 사라졌던 쉰세 쪽이에요."}, {"s": "q:m_yeon", "t": "한 장만이 아니래요. 여러 장이 물길을 따라 떠가는 걸 본 사람이 있대요."}, {"s": null, "t": "옆 책상에서 뱃삯 장부를 넘기던 윤도한이 고개를 들었다."}, {"s": "q:m_yun", "t": "구룡 폐수로에서 빠지는 물은 구름나루를 지나 염등촌으로 흐릅니다. 썰물 때면 반나절이면 닿지요."}, {"s": "q:m_yeon", "t": "역시 잘 아네요."}, {"s": "q:m_yun", "t": "뱃삯 장부도 제 일이라 그렇습니다. 나루까지 뱃삯은 제가 달아 두겠습니다."}, {"s": null, "t": "나는 쉰세 쪽에 적힌 이름이 남아 있느냐고 물었다. 연서희가 종이 가운데를 손끝으로 가리켰다. 이름 칸만 하얗게 비어 있었다."}, {"s": "q:m_yeon", "t": "숫자는 남고 이름만 빠졌어요. 돌아온 건 종이뿐이에요. 나머지 쪽도 이 꼴로 어딘가 떠 있을 거예요."}, {"s": "q:m_yeon", "t": "구름나루의 노들 영감을 찾아가 보세요. 그 종이를 건진 분이고, 물길 소문이라면 그분이 제일이에요."}]'::jsonb where quest_id = 'mq_drowned_ledger' and step = 1 and md5(need::text) = md5('{"at": ["hq_yard"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_drowned_ledger'' and step = 1 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나루터에 안개가 낮게 깔려 있었다. 노를 손질하던 노인이 곰방대를 문 채 고개를 들었다."}, {"s": "river_alliance:nodeul", "t": "정청에서 왔구먼. 그 젖은 종이 건진 게 나여."}, {"s": "river_alliance:nodeul", "t": "오십 년 노를 저었어도 종이가 물을 거슬러 가는 건 처음 봤어. 바람 한 점 없는데 말이여."}, {"s": null, "t": "나는 거슬러 갔다는 말이냐고 되물었다."}, {"s": "river_alliance:nodeul", "t": "그려. 물살은 이리 내려오는데 종이 여남은 장이 줄을 지어서 위로 쓱쓱 올라가더라고."}, {"s": "river_alliance:nodeul", "t": "물고기처럼 꼬리를 치는 것도 아니여. 물낯에 납작 붙어서 미끄러지듯 가더라니까. 노 끝으로 하나 겨우 건졌지."}, {"s": null, "t": "노들 영감이 곰방대를 탁탁 털었다. 그 손이 아직도 조금 떨렸다."}, {"s": "river_alliance:nodeul", "t": "누가 끌고 간 거지. 물 밑에서."}, {"s": null, "t": "노들 영감이 엎어 둔 배 바닥을 손바닥으로 툭툭 쳤다."}, {"s": "river_alliance:nodeul", "t": "앉게. 이건 서서 들을 얘기가 아니여."}, {"s": null, "t": "나는 배 바닥에 걸터앉았다. 노들 영감이 곰방대를 문 채 나를 흘끗 보더니 입꼬리를 올렸다."}, {"s": "river_alliance:nodeul", "t": "정청 사람들은 늘 바쁘다고 선 채로 묻고는 대답을 다 듣기도 전에 가 버리더구먼. 자네는 앉을 줄 아는구먼."}, {"s": "river_alliance:nodeul", "t": "구룡 폐수로 수문께에 수문아귀 놈들이 자리를 틀었어. 종이가 지나간 길목이 바로 거기여."}, {"s": "river_alliance:nodeul", "t": "내 노는 이제 물만 젓지 아귀 대가리는 못 쳐. 두어 놈 잡아서 뭘 물고 다니는지 보고 오게."}]'::jsonb where quest_id = 'mq_drowned_ledger' and step = 2 and md5(need::text) = md5('{"at": ["river_ferry"], "tasks": [{"n": 1, "r": ["river_ferry"], "t": "travel"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_drowned_ledger'' and step = 2 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "수문아귀가 철썩 물을 튀기며 덤벼들었다. 내 일격에 놈의 아가리가 쩍 벌어진 채 굳었다."}, {"s": null, "t": "아가리 속에 젖은 종이 뭉치와 녹슨 엽전 몇 닢이 엉겨 있었다. 나는 그것을 싸 들고 나루로 돌아왔다."}, {"s": "river_alliance:nodeul", "t": "이게 뭔가 하면, 뱃삯이여. 옛 정청 엽전이지. 지금은 안 쓰는 거."}, {"s": "river_alliance:nodeul", "t": "귀신 물길엔 귀신 뱃삯이 있어. 누가 이걸 치르고 장부를 실어 보낸 게야."}, {"s": null, "t": "나는 정청 엽전을 쓰는 사람이라면, 하고 말끝을 흐렸다."}, {"s": "river_alliance:nodeul", "t": "그건 자네들 사정이고. 나는 물길만 알아."}, {"s": null, "t": "노들 영감이 엽전 하나를 엄지로 문질러 보더니 내 손바닥에 도로 놓았다."}, {"s": "river_alliance:nodeul", "t": "가져가게. 정청 물건은 정청 사람이 지니는 게 맞지."}, {"s": "river_alliance:nodeul", "t": "종이가 어디까지 갔는지는 물귀신들이 알아. 염등촌 물귀신들은 비늘에 물길을 새긴다는 말이 있어."}, {"s": "river_alliance:nodeul", "t": "거기서 수귀 비늘 세 장만 주워다 주게. 그러면 장부가 어디로 갔는지 읽어 주지."}]'::jsonb where quest_id = 'mq_drowned_ledger' and step = 3 and md5(need::text) = md5('{"at": ["river_ferry"], "tasks": [{"m": ["m_04"], "n": 2, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_drowned_ledger'' and step = 3 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "노들 영감이 비늘 한 장을 등불에 비추었다. 손바닥만 한 비늘 속에 머리카락보다 가는 금이 물결처럼 이어져 있었다."}, {"s": null, "t": "등불이 흔들릴 때마다 금이 살랑살랑 움직였다. 비늘 안에서 작은 강이 흐르는 것 같았다."}, {"s": "river_alliance:nodeul", "t": "여기 손가락을 대 보게. 물결이 갈라지는 데가 보이나?"}, {"s": null, "t": "나는 비늘에 검지를 얹었다. 비늘은 차가웠고, 손끝 아래에서 금 하나가 갈래를 쳤다."}, {"s": "river_alliance:nodeul", "t": "잘 짚었네. 염등촌을 지나, 뱃길을 타고, 서쪽이여. 서문 폐성벽 해자까지 갔구먼."}, {"s": "river_alliance:nodeul", "t": "근데 이상하네. 중간에 한 번 멈췄어. 침수된 구시가지에서."}, {"s": "river_alliance:nodeul", "t": "물에 잠긴 장터 말이여. 누가 거기서 장부를 받아 보고 다시 띄워 보낸 거지."}, {"s": null, "t": "나는 받아 본 사람이 있었다는 말씀이냐고 물었다."}, {"s": "river_alliance:nodeul", "t": "그려. 사는 쪽이 물건을 펼쳐 보고 값을 매긴 게지. 장사꾼들이 다 그래."}, {"s": "river_alliance:nodeul", "t": "장부 쪽에 적힌 게 다 사람 이름 아닌가. 물 위엔 이름을 사고파는 장사꾼도 있다더구먼."}, {"s": "river_alliance:nodeul", "t": "침수된 구시가지에 가서 두어 번 뒤져 보게. 값을 매긴 놈이 뭐라도 흘렸을 게야. 다 보거든 나한테 다시 들르고."}]'::jsonb where quest_id = 'mq_drowned_ledger' and step = 4 and md5(need::text) = md5('{"at": ["river_ferry"], "give": {"drowned_scale": 3}, "tasks": [{"n": 3, "r": ["salt_village"], "t": "gather", "items": ["drowned_scale"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_drowned_ledger'' and step = 4 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "물에 잠긴 장터 기둥에 붉은 칠이 남아 있었다. 둥근 달 안에 눈 하나가 그려져 있었다."}, {"s": null, "t": "나는 나루로 돌아와 기둥의 문양과 옛 정청 엽전 이야기를 쪽지에 적었다. 노들 영감이 기르는 전서구 발목에 그 쪽지를 묶어 띄웠다."}, {"s": null, "t": "해가 기울 무렵 전서구가 돌아왔다. 나는 연서희의 답장을 펴서 소리 내어 읽었다."}, {"s": "q:m_yeon", "t": "「붉은 달 문양이라면 적월교예요. 조심해요. 그쪽 사람들은 웃으면서 칼을 꺼내요.」"}, {"s": "q:m_yeon", "t": "「윤 출납관에게 옛 정청 엽전을 물어보려 했는데, 오늘따라 자리에 없네요. 내일 다시 물어볼게요.」"}, {"s": "q:m_yeon", "t": "「그리고 노들 영감님께 곰방대 연기는 조금만 드시라고 전해 줘요. 쪽지에서도 담배 냄새가 나요.」"}, {"s": null, "t": "노들 영감이 껄껄 웃다가 연기에 콜록거렸다."}, {"s": "river_alliance:nodeul", "t": "허, 그 서기관 아가씨가 그새 내 흉을 봤구먼. 그나저나 붉은 달이라. 요새 서쪽 가는 배들이 그 표식 단 짐을 많이 싣더구먼."}, {"s": null, "t": "노들 영감이 곰방대로 쪽지 끝을 가리켰다. 나는 남은 줄을 마저 읽었다."}, {"s": "q:m_yeon", "t": "「이제 구룡 폐수로와 침수된 구시가지, 염등촌과 서문 폐성벽에서 단서를 찾아요. 장부가 지나간 자리마다 흔적이 남았을 거예요. 그 쪽에 있던 이름들이 어디로 갔는지, 그게 알고 싶어요.」"}]'::jsonb where quest_id = 'mq_drowned_ledger' and step = 5 and md5(need::text) = md5('{"at": ["river_ferry"], "tasks": [{"n": 2, "r": ["sunken_district"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_drowned_ledger'' and step = 5 and md5(need::te'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "단서 넷이 하나의 물길로 이어졌다. 폐수로에서 강으로, 소금 마을을 지나 서쪽 성벽까지 닿았다."}, {"s": "q:m_yeon", "t": "장부는 팔려 간 거예요. 산 사람은 붉은 달 인장을 쓰는 자들, 적월교."}, {"s": "q:m_yeon", "t": "그들이 원한 건 부적 수량이 아니었어요. 지워진 칸 옆에 적힌 이름들이었죠."}, {"s": "q:m_yun", "t": "봉인 부적을 받아 간 사람들 이름입니다. 대개 오래전에 죽었거나 행방이 끊긴 이들이지요."}, {"s": "q:m_yeon", "t": "죽은 사람 이름을 왜 사 가요?"}, {"s": "q:m_yun", "t": "값이 있으니 사 갔겠지요. 몸은 갔어도 장부에 이름이 남아 있으면 아직 영으로 남은 사람들이니까요. 장부에서는 모든 게 값이 있습니다."}, {"s": null, "t": "윤도한이 웃었다. 연서희는 웃지 않았다."}, {"s": null, "t": "나는 주머니에서 노들 영감이 준 옛 엽전을 꺼내 책상에 놓았다. 윤도한의 눈길이 엽전에 잠깐 머물렀다가 장부로 돌아갔다."}, {"s": "q:m_yeon", "t": "적월 교령으로 가야겠어요. 백골 장터라면 정청 사람도 드나들 수 있어요. 준비되면 말해요."}]'::jsonb where quest_id = 'mq_drowned_ledger';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "정청 문 앞에 붉은 봉투가 꽂혀 있었다. 달 모양 밀랍이 찍혀 있었다."}, {"s": "q:m_yeon", "t": "적월교에서 온 거예요. 「장부를 쫓는 손님을 백골 장터로 모신다.」 우리가 쫓는 걸 다 알고 있어요."}, {"s": null, "t": "곁에 서 있던 한설이 봉투를 받아 밀랍 자국을 손끝으로 쓸어 보았다."}, {"s": "night_office:han", "t": "함정일 가능성이 높습니다. 다만 거절하면 길이 끊깁니다."}, {"s": null, "t": "나는 장부에서 빠진 이름들이 그곳에 있다면 가 봐야 한다고 했다."}, {"s": "q:m_yeon", "t": "맞아요. 그 이름들을 데려오는 게 우리 일이니까요. 가 보세요. 대신 혼자 깊이 들어가지는 마요. 이상하면 바로 돌아오고요."}, {"s": "q:m_yeon", "t": "그리고 이거. 정화 부적이에요. 그쪽 땅은 공기부터 달라요. 손 줘 봐요."}, {"s": null, "t": "연서희가 부적을 반으로 접어 내 소맷부리 안쪽에 꼭꼭 밀어 넣었다."}, {"s": "q:m_yeon", "t": "여기 넣어 두면 잃어버리지 않아요. 제가 처음 현장에 나갈 때 출납관님이 이렇게 넣어 주셨어요."}, {"s": "night_office:han", "t": "돌아오면 보고서부터 쓰십시오. 그 땅에서 본 것은 하나도 빼지 말고."}, {"s": null, "t": "나는 다녀오겠다고 했다."}]'::jsonb where quest_id = 'mq_red_moon_oath' and step = 1 and md5(need::text) = md5('{"at": ["hq_yard"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_moon_oath'' and step = 1 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "뼈로 엮은 차양 아래 붉은 등이 줄지어 걸려 있었다. 장사꾼들이 웃으며 길을 비켜 주었다."}, {"s": null, "t": "장터 끝 붉은 등 아래 앳된 무녀가 앉아 있었다. 무녀가 손에 쥔 종이봉투를 흔들며 손짓했다."}, {"s": "red_moon_cult:danbi", "t": "왔네요, 장부 손님. 정청 먹 냄새가 여기까지 나네요.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": "red_moon_cult:danbi", "t": "어머, 장부 손님이 우리 교 사람이었네요? 교주님이 정청 손님이라고만 하셔서 누군가 했어요. 오늘은 정청 손님으로 모실게요.", "fac": "red_moon_cult", "spec": 1, "grp": 1}, {"s": "red_moon_cult:danbi", "t": "걱정 마세요. 오늘은 안 잡아먹어요. 교주님께서 손님 대접하라 하셨거든요. 사탕 하나 드실래요? 장터 애들 주려고 산 건데."}, {"s": null, "t": "나는 잠깐 망설이다 사탕을 받아 쥐었다."}, {"s": "red_moon_cult:danbi", "t": "어머, 받으시네. 독이라도 들었으면 어쩌시려고요. …안 들었어요. 오늘은요."}, {"s": null, "t": "나는 사탕을 쥔 채 정청 장부에서 사라진 이름들을 사 간 게 적월교냐고 물었다."}, {"s": "red_moon_cult:danbi", "t": "그 이름들이요? 저희가 산 건 맞아요. 쓸 데가 있어서요."}, {"s": null, "t": "나는 어디에 쓰느냐고 물었다."}, {"s": "red_moon_cult:danbi", "t": "그건 말 못 해요. 대신 하나 알려 드릴게요. 우리 교에서 도망친 계집애가 하나 있는데, 적사 황무지 붉은 전갈 소굴에 숨었어요. 지금쯤 전갈 밥이 되고 있을걸요?"}, {"s": "red_moon_cult:danbi", "t": "그 애를 먼저 찾으면 손님이 이기는 거고, 우리가 먼저 찾으면…"}, {"s": null, "t": "단비가 말끝을 흐리며 후후 웃었다."}, {"s": "red_moon_cult:danbi", "t": "아, 그 애가 숨은 바위 틈까지 가려면 붉은 전갈 떼부터 헤쳐야 할걸요. 셋쯤은 눕혀야 길이 날 거예요. 서두르세요, 손님."}]'::jsonb where quest_id = 'mq_red_moon_oath' and step = 2 and md5(need::text) = md5('{"at": ["bone_market"], "tasks": [{"n": 1, "r": ["bone_market"], "t": "travel"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_moon_oath'' and step = 2 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "전갈의 꼬리가 쉭 바람을 갈랐다. 나는 몸을 비틀어 피하고 단단한 등껍질을 내리쳤다. 쩍 소리가 나며 마지막 전갈이 모래 속으로 고꾸라졌다."}, {"s": null, "t": "바위 틈에서 흰 옷의 소녀가 기어 나왔다. 입술이 하얗게 갈라져 있었다."}, {"s": "q:m_sawol", "t": "정청 사람이에요? 단비 언니가 보낸 사람은 아니죠?"}, {"s": null, "t": "나는 정청 조사원이라고 밝혔다. 물통을 내밀자 소녀가 두 손으로 받아 꿀꺽꿀꺽 마셨다."}, {"s": "q:m_sawol", "t": "다행이다. 저는 사월이에요. 적월교 무녀였어요. 이제는 아니고요."}, {"s": null, "t": "사월은 말을 잇지 못하고 바들바들 떨기만 했다. 물통을 쥔 손끝이 얼음처럼 차가웠다."}, {"s": "q:m_sawol", "t": "미안해요. 사흘을 못 잤어요. 눈을 감으면 누가 이름을 불러서."}, {"s": null, "t": "나는 겉옷을 벗어 사월의 어깨에 걸쳐 주었다. 사월이 옷깃을 꼭 여몄다."}, {"s": "q:m_sawol", "t": "안신탕 한 그릇만 만들어 줄 수 있어요? 그거라도 마시면 잠이 오고, 말도 할 수 있을 것 같아요. 저는 이 바위 틈에서 기다릴게요. 단비 언니가 오기 전에요."}]'::jsonb where quest_id = 'mq_red_moon_oath' and step = 3 and md5(need::text) = md5('{"at": ["red_plain"], "tasks": [{"m": ["g_red_plain"], "n": 3, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_moon_oath'' and step = 3 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "사월이 안신탕을 두 손으로 감싸 쥐고 후후 불어 가며 천천히 마셨다. 떨림이 조금씩 가라앉았다."}, {"s": "q:m_sawol", "t": "따뜻해요. 교에서는 이렇게 따뜻한 걸 받아 본 적이 없어요."}, {"s": null, "t": "사월의 숨이 고르게 돌아왔다. 나는 그제야 교가 사 간 이름들을 어디에 쓰느냐고 물었다."}, {"s": "q:m_sawol", "t": "서약이요. 사 온 이름을 제물로 바쳐요."}, {"s": null, "t": "나는 왜 하필 지워진 이름이냐고 물었다. 사월이 사발 가장자리를 손가락으로 쓸었다."}, {"s": "q:m_sawol", "t": "아무도 안 찾으니까요. 불러 줄 사람이 없는 이름은 가져가도 아무도 몰라요."}, {"s": null, "t": "나는 무엇에 바치느냐고 물었다."}, {"s": "q:m_sawol", "t": "북쪽이요. 얼음 아래 무언가가 있대요. 교주님은 그걸 깨운다고만 하셨어요."}, {"s": null, "t": "사월이 품에서 꼬깃한 종이 한 장을 꺼냈다. 서약에 올릴 이름 명단이었다. 맨 끝 줄에 「사월」 두 글자가 먹도 채 마르지 않은 채 적혀 있었다."}, {"s": "q:m_sawol", "t": "그래서 도망쳤어요. 제 이름도 지우려고 했거든요."}, {"s": "q:m_sawol", "t": "이름이 지워지면 살아 있어도 없는 사람이 돼요. 아무도 안 찾고, 끝내는 저도 저를 잊겠죠."}, {"s": null, "t": "나는 명단을 접어 사월의 손에 다시 쥐여 주었다. 사월의 이름도 한 번 또박또박 불러 주었다."}, {"s": "q:m_sawol", "t": "…네. 사월이에요. 이상하네요, 누가 불러 주니까 제 이름 같아요. 조사원 님 이름은요?"}, {"s": null, "t": "나는 내 이름을 알려 주었다."}, {"s": "q:m_sawol", "t": "{이름} 님. 잊지 않을게요."}, {"s": "q:m_sawol", "t": "유리협곡에 가 보세요. 서약에 오른 이름은 그곳 유리벽에 먼저 새겨진대요. 두어 번 살펴보면 보일 거예요. 어디까지 올라갔는지 알면, 서약이 어디로 가는지도 알 수 있어요."}, {"s": "q:m_sawol", "t": "부탁이 하나 더 있어요. 저를 정청으로 몰래 보내 주세요. 여기 있으면 단비 언니가 먼저 찾아낼 거예요."}, {"s": "q:m_sawol", "t": "유리협곡을 다 보고 나면 백골 장터로 돌아가세요. 단비 언니와의 내기는 거기서 끝내야 하니까요."}]'::jsonb where quest_id = 'mq_red_moon_oath' and step = 4 and md5(need::text) = md5('{"at": ["red_plain"], "give": {"calm_brew": 1}, "tasks": [{"n": 1, "t": "craft", "items": ["calm_brew"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_moon_oath'' and step = 4 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "유리협곡의 벽은 햇빛을 받아 붉게 달아올라 있었다. 벽 안쪽에 사람 이름들이 비쳤다."}, {"s": null, "t": "글자는 유리 겉이 아니라 속에 있었다. 누군가 유리 안에 들어가 한 자씩 새긴 것처럼 획마다 핏빛이 고여 있었다."}, {"s": null, "t": "손바닥을 대자 유리가 미지근했다. 귀를 대 보니 아주 멀리서 웅얼거리는 소리가 들렸다. 나는 손을 떼고 한참 그 이름들을 올려다보았다."}, {"s": null, "t": "나는 협곡에 오르기 전에 사월을 정청으로 가는 짐수레에 숨겨 보냈다. 백골 장터로 돌아오자 단비가 붉은 등 아래에서 기다리고 있었다."}, {"s": "red_moon_cult:danbi", "t": "먼저 찾으셨나 봐요. 얼굴에 다 쓰여 있네. 사탕은 드셨어요?"}, {"s": null, "t": "나는 아직 안 먹었다고 했다. 단비가 깔깔 웃었다."}, {"s": "red_moon_cult:danbi", "t": "조심성 많으시네. 괜찮아요. 그 애 이름 하나 빠진다고 서약이 무너지진 않거든요. 이름은 많으니까요. 정청 장부에 아주 많았죠. 오래된 쪽일수록 지키는 사람이 없던데요?"}, {"s": null, "t": "단비의 웃음은 그대로였다. 등불 아래 붉은 손톱만 장부를 넘기듯 탁자를 톡톡 두드렸다."}, {"s": null, "t": "그때 전서구가 등불 옆에 내려앉았다. 나는 연서희의 글씨를 알아보고 쪽지를 폈다."}, {"s": "q:m_yeon", "t": "「사월은 무사히 도착했어요. 이제 적사 황무지와 유리협곡, 회산 관문에서 단서를 찾아요. 서약이 어디로 향하는지 알아내야 해요. 그 끝에 장부에서 빠진 이름들이 있을 거예요.」"}]'::jsonb where quest_id = 'mq_red_moon_oath' and step = 5 and md5(need::text) = md5('{"at": ["bone_market"], "tasks": [{"n": 2, "r": ["glass_canyon"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_red_moon_oath'' and step = 5 and md5(need::tex'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "정청 뒷방에서 사월이 이불을 두른 채 단서를 맞춘 일지를 들여다보았다. 연서희가 이불 귀퉁이를 사월의 어깨 위로 끌어올려 주었다."}, {"s": "q:m_yeon", "t": "서약은 황무지에서 시작해 유리협곡을 지나 회산 관문으로 올라가요. 끝은 북쪽 설산이고요."}, {"s": "q:m_sawol", "t": "마지막 축문이 기억나요. 「빙인을 녹여라.」 얼음 인장을 녹이라는 뜻이에요."}, {"s": "night_office:han", "t": "북령맹이 지키는 얼음 인장입니다. 그것이 녹으면 맹약 자체가 깨집니다."}, {"s": "q:m_sawol", "t": "그 아래 뭐가 있는지는 저도 몰라요. 아는 사람은 교주님뿐이에요."}, {"s": "q:m_yun", "t": "북령맹이라면 호송대장 여운비가 길을 잘 압니다. 철벽 고찰로 전갈을 넣어 두지요."}, {"s": "q:m_yeon", "t": "고마워요, 윤 출납관. 사월, 당분간 객사에 있어요. 여긴 안전해요."}, {"s": "q:m_sawol", "t": "정청은 이름을 지키는 법을 알아요?"}, {"s": null, "t": "아무도 대답하지 않았다. 한설이 장부 귀퉁이를 한 번 쓸어내릴 뿐이었다."}, {"s": null, "t": "사월이 이불 속에서 내 소매를 살짝 잡아당겼다."}, {"s": "q:m_sawol", "t": "{이름} 님. 자기 전에 제 이름 한 번만 더 불러 주세요. 그러면 오늘은 잘 수 있을 것 같아요."}, {"s": null, "t": "나는 사월의 이름을 불러 주었다. 사월이 눈을 감고 아주 작게 웃었다."}]'::jsonb where quest_id = 'mq_red_moon_oath';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "정청 마당에 서리가 하얗게 내려 있었다. 아직 서리가 올 철이 아니었다."}, {"s": "q:m_yeon", "t": "북령맹에서 답이 왔어요. 얼음 인장 둘레가 녹고 있대요. 하룻밤에 한 뼘씩요."}, {"s": "q:m_yeon", "t": "사월이 들은 축문 그대로예요. 「빙인을 녹여라.」 서약이 거기까지 올라갔다는 뜻이에요."}, {"s": "q:m_yeon", "t": "맹주 석진악이 직접 보자고 해요. 철벽 고찰로 가 주세요."}, {"s": null, "t": "나는 윤 출납관은 어디 있느냐고 물었다. 철벽 고찰에 전갈을 넣어 두겠다던 사람이었다."}, {"s": "q:m_yeon", "t": "사흘째 휴가예요. 고향에 다녀온대요. 그런데 그 사람 고향이 어딘지 아는 사람이 없더라고요. 이상하죠."}, {"s": "q:m_yeon", "t": "북쪽은 추워요. 노정 건량 챙겨 가요. 거기서 쓰러지면 구하러 가기도 힘들어요."}, {"s": null, "t": "연서희가 목에 두르고 있던 무명 목도리를 풀어 내 목에 감아 주었다. 목도리에서 먹 냄새와 보리차 냄새가 났다."}, {"s": "q:m_yeon", "t": "빌려주는 거예요. 북쪽 바람은 귀부터 물어요. 돌려받으러 갈 테니 잃어버리지 마요."}]'::jsonb where quest_id = 'mq_frost_seal' and step = 1 and md5(need::text) = md5('{"at": ["hq_yard"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_frost_seal'' and step = 1 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "쇠로 덧댄 산문 앞에 거구의 사내가 팔짱을 끼고 서 있었다. 옆의 여장수는 지도를 말아 쥐고 있었다."}, {"s": "north_league:seok", "t": "네가 정청 조사원이냐. 짧게 말하지. 얼음 인장이 녹는다. 우리는 이유를 모른다.", "fac_not": "north_league", "spec": 2, "grp": 1}, {"s": "north_league:seok", "t": "정청이 보낸 조사원이 너였나. 맹 사람이니 돌려 말하지 않겠다. 얼음 인장이 녹는다. 우리는 이유를 모른다.", "fac": "north_league", "spec": 1, "grp": 1}, {"s": "north_league:seok", "t": "적월교 놈들 짓이라면 내 손으로 끝낸다. 하지만 증거가 먼저다. 그게 너희 일이지."}, {"s": "north_league:yeo", "t": "호송대장 여운비요. 인장까지 가려면 옥문 협로를 지나야 하오. 잔도가 요즘 성치 않소.", "fac_not": "north_league", "spec": 2, "grp": 2}, {"s": "north_league:yeo", "t": "정청 일로 왔다더니 당신이었소? 인장까지 가려면 옥문 협로를 지나야 하오. 잔도가 요즘 성치 않은 건 당신도 들었을 거요.", "fac": "north_league", "spec": 1, "grp": 2}, {"s": null, "t": "여운비가 내 발을 내려다보더니 혀를 끌끌 찼다."}, {"s": "north_league:yeo", "t": "감발을 그렇게 쳐서 잔도를 어찌 걷겠소. 발 이리 내시오."}, {"s": null, "t": "여운비가 쪼그려 앉아 내 발목의 감발을 풀었다. 손이 빠르게 움직이더니 천을 단단히 감아 다시 맸다."}, {"s": "north_league:yeo", "t": "됐소. 이러면 얼음 위에서도 발이 덜 미끄러질 거요. 북쪽에선 발이 먼저 어오."}, {"s": null, "t": "나는 고맙다고 했다. 여운비는 대꾸 없이 일어나 지도를 다시 펼쳤다."}, {"s": "north_league:yeo", "t": "잔도 쇠말뚝은 백무 영감이 지키오. 그 영감 허락 없이는 아무도 못 지나가오."}, {"s": "north_league:yeo", "t": "그런데 협로를 비취 수문장이 막아섰다는 소식이 있소. 영감은 그 안쪽에 갇혔을지도 모르오. 옥문 협로로 가서 수문장부터 쓰러뜨려 주시오. 영감은 그다음이오."}, {"s": null, "t": "나는 수문장이 어디쯤 있느냐고 물었다."}, {"s": "north_league:yeo", "t": "그놈은 협로 어귀엔 안 나오오. 답사 지도 셋째 칸부터, 안쪽 깊은 데까지 들어가 탐색해야 모습을 보이오. 우두머리들은 다 그렇소."}]'::jsonb where quest_id = 'mq_frost_seal' and step = 2 and md5(need::text) = md5('{"at": ["iron_monastery"], "tasks": [{"n": 1, "r": ["iron_monastery"], "t": "travel"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_frost_seal'' and step = 2 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "비취 수문장의 팔이 쩡 소리를 내며 바위를 찍었다. 나는 그 틈을 파고들어 가슴팍을 내리쳤다."}, {"s": null, "t": "쩌저적, 금이 사방으로 번졌다. 수문장의 몸이 와르르 무너지며 푸른 비취 조각이 잔도 아래로 쏟아져 내렸다."}, {"s": null, "t": "메아리가 가라앉자 잔도 끝에서 쇠망치 소리가 깡깡 들려왔다. 늙은이 하나가 말뚝을 두드리고 있었다."}, {"s": "q:m_baekmu", "t": "시끄럽게도 싸우는군. 덕분에 말뚝 두 개가 흔들렸어."}, {"s": "q:m_baekmu", "t": "백무다. 이 잔도 말뚝을 예순 해 지켰지. 맹약자라 부르는 놈도 있고, 말뚝지기라 부르는 놈도 있고."}, {"s": null, "t": "나는 얼음 인장까지 가야 한다고 했다."}, {"s": "q:m_baekmu", "t": "알아. 다들 그리로 가려고 하지. 근데 말뚝이 풀리면 너도 못 가."}, {"s": null, "t": "백무가 흔들리는 말뚝 머리를 손바닥으로 짚었다. 말뚝이 잘그락거리며 좌우로 놀았다."}, {"s": "q:m_baekmu", "t": "봐라, 이 꼴이다. 빙혼곡 빙정염이 있어야 말뚝을 다시 박는다. 세 덩이만 캐다 나한테 가져와. 얼음 틈 아래서 캔 게 진짜다."}, {"s": "q:m_baekmu", "t": "내 무릎으론 빙혼곡까지 하루가 걸려. 너는 반나절이면 되겠지."}]'::jsonb where quest_id = 'mq_frost_seal' and step = 3 and md5(need::text) = md5('{"at": ["jade_pass"], "tasks": [{"n": 1, "r": ["jade_pass"], "t": "win", "rank": "guardian"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_frost_seal'' and step = 3 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "백무는 말뚝 곁에서 망치를 쥔 채 기다리고 있었다. 내가 빙정염 꾸러미를 내밀자 백무가 망치를 고쳐 쥐었다."}, {"s": "q:m_baekmu", "t": "빨리도 왔다. 그 말뚝 좀 잡아라. 꽉. 손 얼면 말하고."}, {"s": null, "t": "나는 두 손으로 말뚝을 붙들었다. 백무가 빙정염을 말뚝 구멍에 부었다. 하얀 김이 쉭 솟았다."}, {"s": null, "t": "백무가 망치를 깡 내리쳤다. 말뚝을 쥔 손바닥이 얼얼하게 울렸다."}, {"s": null, "t": "그 울림이 끝나기 전에 땅 밑에서 무언가 낮게 울렸다. 웅, 하는 소리가 발바닥부터 무릎까지 차올랐다."}, {"s": null, "t": "잔도의 쇠사슬이 저 혼자 찰랑거렸다. 얼음 틈에서 미지근한 바람이 한 줄기 새어 나왔다. 숨소리 같았다."}, {"s": "q:m_baekmu", "t": "들었냐."}, {"s": null, "t": "나는 방금 그게 무엇이었느냐고 묻다가 말을 삼켰다. 말뚝을 쥔 손이 저절로 떨렸다."}, {"s": "q:m_baekmu", "t": "이 말뚝들 말이다. 바깥에서 들어오는 놈 막으려고 박은 게 아니야. 안에 있는 걸 못 나오게 박은 거지."}, {"s": "q:m_baekmu", "t": "예순 해 동안 한 번도 안 깼는데, 요 보름 사이 세 번이나 뒤척였어."}, {"s": "q:m_baekmu", "t": "맹주는 몰라. 맹약은 말뚝지기한테만 전해지거든. 이제 너도 들었으니 너도 말뚝지기다."}, {"s": "q:m_baekmu", "t": "말뚝 머리마다 먼저 간 말뚝지기 이름이 새겨져 있다. 내 이름도 저 끝에 있지. 이름이 붙어 있어야 말뚝이 안 풀린다더라."}, {"s": null, "t": "백무가 웃는 얼굴로 망치를 내려놓았다. 망치 쥔 손이 덜덜 떨리고 있었다."}, {"s": null, "t": "나는 말뚝 끝에 새겨진 「백무」 두 글자를 손가락으로 쓸어 보았다. 백무가 헛기침을 하며 고개를 돌렸다."}, {"s": "q:m_baekmu", "t": "쓸데없는 짓 말고. 말뚝은 박았으니 잔도는 버틴다. 원정을 꾸려 얼음 너머까지 한 번 끝까지 다녀와라."}, {"s": "q:m_baekmu", "t": "뭐가 뒤척이는지 네 눈으로 보고, 철벽 고찰에 가서 맹주한테 전해. 증거를 가져오라던 사람이니, 본 사람 말은 들을 게다."}]'::jsonb where quest_id = 'mq_frost_seal' and step = 4 and md5(need::text) = md5('{"at": ["jade_pass"], "give": {"frost_salt": 3}, "tasks": [{"n": 3, "r": ["frost_valley"], "t": "gather", "items": ["frost_salt"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_frost_seal'' and step = 4 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 원정에서 돌아오는 길에 얼어붙은 천경호를 건넜다. 발밑 얼음 아래로 크고 둥근 그림자가 비쳤다."}, {"s": null, "t": "그림자는 배 열 척을 합친 것보다 컸다. 그림자가 천천히 부풀자 얼음이 쩌억 우는 소리를 냈고, 얼음 위로 물결 같은 무늬가 번져 나갔다."}, {"s": null, "t": "나는 그 자리에 엎드려 귀를 대 보았다. 둥, 둥, 아주 느린 북소리 같은 것이 얼음 밑에서 올라왔다."}, {"s": null, "t": "고찰 산문에 닿자 여운비가 화롯가에서 벌떡 일어섰다."}, {"s": "north_league:yeo", "t": "다녀왔소? 얼굴이 하얗소. 무얼 봤소?"}, {"s": null, "t": "나는 얼음 아래에서 무언가 숨을 쉬고 있다고 말했다. 천경호 밑 그림자와 북소리 이야기도 했다."}, {"s": null, "t": "여운비가 뜨거운 보리 미숫가루 한 사발을 내 손에 쥐여 주었다. 한참 내 얼굴을 보다가 짧게 말했다."}, {"s": "north_league:yeo", "t": "…살아 왔으면 됐소."}, {"s": null, "t": "화로 건너편에 앉아 있던 석진악이 내 손의 사발을 내려다보며 입을 열었다."}, {"s": "north_league:seok", "t": "백무 영감이 그러더냐. 그 늙은이, 나한테는 한 번도 말 안 했지."}, {"s": null, "t": "석진악이 주먹으로 화로 가장자리를 쿵 내리쳤다. 주먹은 그릇 바로 앞에서 멈췄다."}, {"s": "north_league:seok", "t": "좋다. 증거를 가져와라. 그럼 내가 움직인다. 적월교든 다른 놈이든, 무엇이 녹이는지 알아야 칼을 뽑지."}, {"s": null, "t": "고찰 처마에 앉은 전서구 발목에 쪽지가 묶여 있었다. 나는 연서희의 글씨를 펴서 읽었다."}, {"s": "q:m_yeon", "t": "「이제 빙혼곡과 옥문 협로, 천경호에서 단서를 찾아요. 무엇이 숨 쉬는지 알아내야 해요. 서약에 바친 이름들이 그것을 깨우는 데 쓰였다면, 그 이름들도 거기 있을 거예요. 목도리는 하고 있죠?」"}]'::jsonb where quest_id = 'mq_frost_seal' and step = 5 and md5(need::text) = md5('{"at": ["iron_monastery"], "tasks": [{"n": 1, "t": "expedition"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_frost_seal'' and step = 5 and md5(need::text) '; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "철벽 고찰 화롯가에 연서희가 앉아 있었다. 정청에서 북쪽까지 직접 올라온 길이라 신발이 눈에 흠뻑 젖어 있었다."}, {"s": null, "t": "단서를 맞추자 얼음 인장의 생김새가 드러났다. 인장이 아니었다. 엎어 둔 종의 뚜껑이었다."}, {"s": "q:m_yeon", "t": "얼음 아래 잠든 건 종이에요. 이름 없는 종. 그런데 숨을 쉬어요. 살아 있는 것처럼."}, {"s": "north_league:seok", "t": "그딴 걸 우리 조상들이 깔고 앉아 있었단 말이냐."}, {"s": "q:m_baekmu", "t": "깔고 앉은 게 아니라 눌러 둔 거다, 맹주. 맹약 첫 줄에 있어. 「종을 울리지 마라. 짝이 깬다.」"}, {"s": null, "t": "나는 짝이라니, 하고 되물었다."}, {"s": "q:m_baekmu", "t": "북쪽 종이 있으면 남쪽 종도 있지. 한 쌍이니까."}, {"s": null, "t": "그때 문간에서 낯익은 목소리가 났다. 휴가 중이라던 윤도한이 어느새 고찰 문간에 서 있었다. 언제 왔는지 본 사람은 없었다."}, {"s": "q:m_yun", "t": "남쪽이라면 남명 망국령이겠군요. 잔불촌의 소이 무녀가 옛 노래를 많이 압니다."}, {"s": "q:m_yeon", "t": "윤 출납관, 언제 왔어요?"}, {"s": null, "t": "윤도한은 지나는 길에 들렀다고만 하고 웃었다."}, {"s": "q:m_yeon", "t": "…아니, 됐어요. 남쪽으로 가요."}, {"s": null, "t": "나는 목도리를 풀어 연서희에게 내밀었다. 연서희가 고개를 저으며 목도리를 도로 내 목에 감아 주었다."}, {"s": "q:m_yeon", "t": "남쪽까지 하고 다녀요. 남쪽 바람도 귀는 물어요."}]'::jsonb where quest_id = 'mq_frost_seal';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "장서각에서 옛 맹약문을 베껴 온 모가람이 탁자에 종이를 펼쳤다. 그 곁에 식은 보리차를 한 잔씩 따라 놓았다."}, {"s": "night_office:mo", "t": "북쪽 종이 깨면 짝도 깬대요. 남쪽 종이요. 그런데 남쪽 기록이 하나도 없어요. 전부 지워졌어요."}, {"s": "q:m_yeon", "t": "지워진 기록, 지워진 이름. 계속 같은 얘기예요."}, {"s": null, "t": "창가 책상에서 결산 장부를 넘기던 윤도한이 붓을 놓았다."}, {"s": "q:m_yun", "t": "남명 망국령은 글 대신 노래로 남깁니다. 잔불촌의 소이 무녀를 찾으시지요."}, {"s": "q:m_yeon", "t": "윤 출납관, 같이 가 줄 수 있어요? 남쪽 길이라면."}, {"s": "q:m_yun", "t": "송구합니다. 이번 달 결산이 밀렸습니다. 대신 잔불촌까지 운임은 장부에 미리 달아 두었습니다."}, {"s": null, "t": "윤도한은 자기 앞의 보리차를 끝내 입에 대지 않았다. 모가람이 그 잔을 슬쩍 내 쪽으로 밀어 주었다."}, {"s": "night_office:mo", "t": "출납관님이 안 드시니 조사원 님이 두 잔 드세요. 남쪽은 더워서 목이 마를 거예요."}, {"s": null, "t": "나는 두 잔을 다 비웠다. 모가람이 손뼉을 치며 좋아했다."}, {"s": "q:m_yeon", "t": "북쪽 종 아래 이름들이 깔려 있었다면, 남쪽 종에도 누군가의 이름이 먹혔을 거예요. 그걸 찾아서 막아야 해요."}, {"s": "q:m_yeon", "t": "조심해요. 이번엔 {이름} 님 이름이 걸려 있다고 생각하고 움직여요. 종은 이름을 먹는대요."}]'::jsonb where quest_id = 'mq_nameless_bell' and step = 1 and md5(need::text) = md5('{"at": ["hq_yard"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nameless_bell'' and step = 1 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "꺼질 듯 꺼지지 않는 화톳불이 마을 곳곳에 피어 있었다. 그 가운데서 젊은 무녀가 낮게 노래하고 있었다."}, {"s": "southern_remnant:soi", "t": "「북녘 종은 숨을 쉬고, 남녘 종은 이름을 먹네. 한 번 울면 너를 잊고, 두 번 울면 나를 잊네.」"}, {"s": "southern_remnant:soi", "t": "정청 분이시죠? 노래 들으러 오셨으면 잘 오셨어요. 들려 드릴 게 노래밖에 없거든요.", "fac_not": "southern_remnant", "spec": 2, "grp": 1}, {"s": "southern_remnant:soi", "t": "어머, 우리 마을 분이 정청 일로 오셨네요. 노래 들으러 오셨으면 잘 오셨어요. 들려 드릴 게 노래밖에 없거든요.", "fac": "southern_remnant", "spec": 1, "grp": 1}, {"s": null, "t": "소이가 부지깽이로 잿더미를 헤쳐 군고구마 하나를 꺼냈다. 호호 불어 반으로 갈라 내게 한쪽을 내밀었다."}, {"s": "southern_remnant:soi", "t": "불씨 곁에선 다들 이걸 먹사와요. 뜨거우니 조심하시고요."}, {"s": null, "t": "나는 고구마를 받아 들고 남녘 종이 어디 있느냐고 물었다."}, {"s": "southern_remnant:soi", "t": "남녘 종은 주혈 광산 깊은 갱도에 매달려 있었어요. 있었다고 하는 건, 지금은 없어서예요."}, {"s": null, "t": "나는 누가 가져갔느냐고 물었다."}, {"s": "southern_remnant:soi", "t": "끌고 갔어요. 더 깊은 땅 밑으로. 갱도 바닥에 끌린 자국이 남았대요. 그 갱도에서 죽은 광부들의 넋이 종소리를 듣고 미쳐 버렸다고 해요."}, {"s": "southern_remnant:soi", "t": "주혈 광산에 가서 미쳐 떠도는 갱도 원령 셋만 잠재워 주세요. 넋들이 갱도를 막고 있어서, 그래야 끌린 자국을 따라가 볼 수 있어요. 저는 여기서 노래를 부르며 기다릴게요."}]'::jsonb where quest_id = 'mq_nameless_bell' and step = 2 and md5(need::text) = md5('{"at": ["ember_village"], "tasks": [{"n": 1, "r": ["ember_village"], "t": "travel"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nameless_bell'' and step = 2 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "갱도 원령들이 우우우 울며 달려들었다. 녹슨 곡괭이가 바위벽을 깡깡 긁었다. 셋째 원령이 흩어지자 갱도가 거짓말처럼 조용해졌다."}, {"s": null, "t": "원령이 흩어진 자리에 녹슨 이름패 하나가 떨어져 있었다. 패에 새겨져 있던 이름자는 모두 긁혀 나가 있었다."}, {"s": null, "t": "나는 이름패를 잔불촌까지 가져와 소이에게 건넸다. 소이가 패를 소매로 오래오래 닦았다."}, {"s": "southern_remnant:soi", "t": "그 넋들은 저희 조상이에요. 남명이 무너질 때 광산을 지키다 묻힌 분들이죠. 이름이 불리는 동안엔 갱도를 지키는 영이었어요. 종소리를 듣고 그 이름을 잃은 거예요."}, {"s": "southern_remnant:soi", "t": "울린 자만 이름을 잃는 줄 알았는데. 들은 것들까지."}, {"s": "southern_remnant:soi", "t": "이름을 다 잃으면 사람이든 영이든 요괴가 돼요. 그때부턴 아무도 이름으로 안 불러요. 갱도 원령, 그렇게 갈래로만 부르죠."}, {"s": null, "t": "소이가 이름패를 가슴에 대고 한 소절을 흥얼거렸다. 가사는 없었다. 목소리가 갈라져 있었다."}, {"s": null, "t": "나는 소이가 노래를 마칠 때까지 기다렸다가 끌린 자국이 어디로 이어지느냐고 물었다."}, {"s": "southern_remnant:soi", "t": "만인장으로요. 흑련회 땅이에요. 들어가려면 몸부터 지켜야 해요. 그 땅은 이름 지우는 기운이 짙거든요."}, {"s": "southern_remnant:soi", "t": "청정수 두 병만 만들어 주세요. 이름 지우는 기운을 씻어 낼 수 있어요. 노래로 축을 걸어 드릴게요."}]'::jsonb where quest_id = 'mq_nameless_bell' and step = 3 and md5(need::text) = md5('{"at": ["ember_village"], "tasks": [{"m": ["x_crimson_mine_2"], "n": 3, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nameless_bell'' and step = 3 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "소이가 청정수를 손바닥에 덜어 내 이마에 발랐다. 차갑다가 이내 따뜻해졌다."}, {"s": "southern_remnant:soi", "t": "「잊지 마라, 네 이름. 누가 불러도 돌아보지 마라, 네 이름이 아니거든.」"}, {"s": "southern_remnant:soi", "t": "이 노래를 기억해요. 땅 밑에서 누가 이름을 부르면 대답하지 말아요."}, {"s": null, "t": "나는 노래를 한 번 따라 불렀다. 소이가 가락이 틀렸다며 웃더니 한 줄씩 다시 불러 주었다."}, {"s": "southern_remnant:soi", "t": "이제 맞아요. 그대 목소리로 부르니 다른 노래 같네요."}, {"s": "southern_remnant:soi", "t": "하나 더. 할머니가 할머니한테서 들었다는 아주 오래된 이야기예요. 종을 처음 울린 자는 남명 사람이 아니었대요. 북쪽에서 내려온 관리였대요."}, {"s": null, "t": "나는 관리라는 말이냐고 되물었다."}, {"s": "southern_remnant:soi", "t": "이름은 몰라요. 그 사람이 종을 울린 뒤로 아무도 그 이름을 기억하지 못했거든요. 그 뒤로 이름 잃은 사람들을 모아 어디론가 갔다는 말만 남았어요."}, {"s": "southern_remnant:soi", "t": "끌린 자국은 만인장으로 이어졌다고 했죠. 그곳 비석들 사이를 세 번쯤 살펴보시고, 그다음엔 십삼문 암시장으로 가세요. 흑련회 땅에서 소문을 살 수 있는 곳은 거기뿐이에요."}]'::jsonb where quest_id = 'mq_nameless_bell' and step = 4 and md5(need::text) = md5('{"at": ["ember_village"], "give": {"purify_water": 2}, "tasks": [{"n": 2, "t": "craft", "items": ["purify_water"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nameless_bell'' and step = 4 and md5(need::tex'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "만인장의 비석들은 줄지어 서 있었지만 이름을 새긴 것은 하나도 없었다. 땅에는 무거운 것을 끈 자국이 깊게 패어 무명 고도 쪽으로 이어졌다."}, {"s": null, "t": "십삼문 암시장에 들어서자 딱, 딱, 딱 하는 주판 소리가 먼저 들렸다."}, {"s": null, "t": "주판을 무릎에 얹은 여인이 고개도 들지 않고 알을 튕기다가 손을 멈췄다."}, {"s": "black_lotus:guseul", "t": "종을 쫓는 분이구나. 걸음이 빠르시네. 적월교 쪽도 어제 다녀갔어요.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "black_lotus:guseul", "t": "어머, 우리 회원께서 종을 쫓고 계셨구나. 걸음이 빠르시네. 적월교 쪽도 어제 다녀갔어요.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "나는 종이 지금 어디 있느냐고 물었다."}, {"s": "black_lotus:guseul", "t": "종은 지금 무명 고도 밑, 구중 봉연 첫 문 앞에 있어요. 누가 끌고 갔냐고요? 셈은 공짜가 아니라서."}, {"s": null, "t": "나는 값을 묻지 않고 주머니를 열었다. 구슬이 주판알 하나를 튕기며 고개를 저었다."}, {"s": "black_lotus:guseul", "t": "넣어 두세요. 저는 첫 손님한테는 이자를 안 받아요. 대신 하나만 덤으로 드리죠.", "fac_not": "black_lotus", "spec": 2, "grp": 2}, {"s": "black_lotus:guseul", "t": "넣어 두세요. 회원한테 소문값을 받았다간 회주님 장부에 제 이름이 적혀요. 대신 하나만 덤으로 드리죠.", "fac": "black_lotus", "spec": 1, "grp": 2}, {"s": "black_lotus:guseul", "t": "얼마 전 그 종이 우리 땅을 끌려 지나갔어요. 회주님이 그 소리를 들으시고는, 제 이름을 회원 장부 더 깊숙이 넣어 두고 다시 꺼내지 않으세요."}, {"s": "black_lotus:guseul", "t": "이건 정말 덤이에요. 흑련회를 처음 세운 분도 그 종을 울려 이름을 잃은 북쪽 관리였대요. 이름 잃은 사람들을 모아 이름을 대신 지켜 준 게 저희 장사의 시작이죠."}, {"s": null, "t": "나는 무명이라는 이름은 무엇이냐고 묻다가 말을 멈췄다."}, {"s": "black_lotus:guseul", "t": "무명은 이름이 아니라 빈칸이에요. 신원 모를 시신도, 명부에서 지워진 사람도, 이름을 맡긴 사람도 장부엔 다 「무명」으로 적히죠. 회주님은 그 말을 호칭으로 쓰실 뿐이에요."}, {"s": "black_lotus:guseul", "t": "명줄은 매듭이라 풀어서 남한테 맡길 수 있어요. 맡긴 사람은 그 이름으로 불려도 돌아보지 못하지만, 저희가 회원 장부에 적어 지키니 요화하진 않아요. 저희 장사가 그거예요."}, {"s": null, "t": "전서구가 구슬의 주판 위에 내려앉았다. 주판알이 와르르 흩어졌다."}, {"s": "black_lotus:guseul", "t": "어머, 제 셈이 다 날아갔네. 정청 새는 예의가 없어요."}, {"s": null, "t": "나는 쪽지를 펴서 연서희의 글씨를 읽었다."}, {"s": "q:m_yeon", "t": "「이제 만인장과 주혈 광산, 무명 고도에서 단서를 찾아요. 종이 어디로 갔는지, 누가 노리는지 밝혀야 해요. 종이 또 울리기 전에요.」"}]'::jsonb where quest_id = 'mq_nameless_bell' and step = 5 and md5(need::text) = md5('{"at": ["hidden_bazaar"], "tasks": [{"n": 3, "r": ["burial_steps"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nameless_bell'' and step = 5 and md5(need::tex'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "정청 뒷방에서 맞춰 놓은 단서 위로 등잔 그림자가 흔들렸다."}, {"s": "q:m_yeon", "t": "종을 울린 자는 이름을 잃어요. 들은 것들도 이름이 흐려지고요. 그 종이 지금 구중 봉연 첫 문 앞에 있어요."}, {"s": "night_office:han", "t": "적월교는 지워진 이름을 바쳐 문을 열려 하고, 흑련회는 종 자체를 노립니다. 둘이 같은 곳을 보고 있습니다."}, {"s": "night_office:mo", "t": "구중 봉연이라니. 기록에서도 그 이름은 함부로 안 써요. 아홉 겹으로 봉한 연못이라던데."}, {"s": "q:m_yeon", "t": "윤 출납관, 흑련회 회주에 대한 기록 있어요?"}, {"s": null, "t": "대답이 없었다. 연서희가 한 번 더 부르자 그제야 윤도한이 고개를 들었다."}, {"s": "q:m_yun", "t": "없습니다. 이름 없는 사람의 기록은 남지 않으니까요."}, {"s": "q:m_yeon", "t": "그렇겠죠. 적월교가 먼저 움직일 거예요. 다음 월식이 오기 전에 준비해 둬요."}, {"s": null, "t": "창밖 아주 먼 곳에서 종소리 같은 것이 한 번 울렸다. 누구의 이름이 지워졌는지는 아무도 몰랐다."}, {"s": null, "t": "나는 소이에게 배운 노래를 입속으로 한 번 불러 보았다. 연서희가 그 가락을 듣고 붓을 멈췄다."}]'::jsonb where quest_id = 'mq_nameless_bell';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "백골 장터의 천막 사이로 붉은 등이 흔들렸다. 뼈 깎는 소리가 사각사각 그치지 않았다."}, {"s": null, "t": "천막 그늘에서 사월이 뛰어나왔다. 볼에 살이 조금 올라 있었다."}, {"s": "q:m_sawol", "t": "{이름} 님! 저 요즘은 잠을 자요. 객사 이불이 두꺼워서요."}, {"s": null, "t": "사월 뒤로 연서희가 보따리를 들고 따라 나왔다. 정청에서 사월을 데리고 하루 먼저 내려와 있던 참이었다."}, {"s": "q:m_yeon", "t": "이불을 두 채나 덮고 자요. 아침마다 깨우느라 제가 혼나요."}, {"s": "q:m_yeon", "t": "종이 땅 밑으로 끌려간 뒤로 적월교가 갑자기 조용해졌어요. 조용한 건 늘 나쁜 징조예요."}, {"s": "q:m_sawol", "t": "월식이 사흘 남았어요. 교주님은… 월화는 그날 흑사단의 남은 이름을 모두 바칠 거예요."}, {"s": "q:m_yeon", "t": "흑사단은 이미 무너진 교단이에요. 남은 이름이라니요?"}, {"s": "q:m_sawol", "t": "무너졌어도 명부는 남아요. 부르는 사람은 없어도 글자가 남아 있으면, 그 사람들은 아직 영으로 남아 있어요. 그 마지막 가닥을 걷어 바치는 거예요."}, {"s": null, "t": "장터 어귀에 짐수레를 세워 둔 윤도한이 천막 사이로 걸어왔다."}, {"s": "q:m_yun", "t": "노자와 보급은 제가 챙겨 왔습니다. 그런데 사월 무녀, 그 명부에 이름이 몇이나 적혀 있습니까? 장부쟁이 버릇이라 숫자가 궁금합니다."}, {"s": "q:m_sawol", "t": "…이백하고도 셋. 왜 그렇게 정확히 물으시죠?"}, {"s": null, "t": "윤도한이 소리 내어 웃었다."}, {"s": "q:m_yun", "t": "셈이 맞아야 마음이 놓이는 사람이라 그렇습니다. 조심히 다녀오십시오."}, {"s": null, "t": "윤도한이 내 짐에 노정 건량을 하나 더 얹어 주었다. 짐 끈을 매 주는 손끝이 아주 정갈했다."}, {"s": "q:m_yeon", "t": "이름이 문 앞에 바쳐지면 그걸로 끝이에요. 그 전에 데려와야 해요."}, {"s": "q:m_yeon", "t": "먼저 흑사단 폐단으로 가 주세요. 명부가 아직 거기 있는지 확인해야 해요. 흑사 주술승들이 제단을 지키고 있다니, 둘쯤은 쓰러뜨려야 들어갈 수 있을 거예요. 사월이 길을 알아요."}]'::jsonb where quest_id = 'mq_eclipse_gate' and step = 1 and md5(need::text) = md5('{"at": ["bone_market"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_eclipse_gate'' and step = 1 and md5(need::text'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "주술승의 경문 소리가 웅웅 울렸다. 나는 그 소리를 끊듯 들이쳤고, 둘째 주술승이 털썩 모래 위에 쓰러졌다."}, {"s": null, "t": "검은 모래가 제단을 반쯤 묻고 있었다. 찢어진 경문 조각이 바람에 펄럭펄럭 날렸다."}, {"s": null, "t": "제단 아래 돌함이 열려 있었다. 명부는 그대로였지만 종이마다 이름이 있던 자리만 하얗게 비어 있었다."}, {"s": "q:m_sawol", "t": "늦었어요. 벌써 이름을 걷어 갔어요. 먹은 남고 이름만 사라졌어요."}, {"s": null, "t": "나는 이름은 어디로 갔느냐고 중얼거렸다."}, {"s": "q:m_sawol", "t": "월식성 제단으로요. 이름은 달이 가려질 때 문 앞에 놓여야 해요. 그때까지는 붉은 실에 묶어 두죠."}, {"s": "q:m_sawol", "t": "아직 사흘이 있어요. 그 사이에 성에 들어가야 해요."}, {"s": "q:m_sawol", "t": "성에 들어가려면 교도처럼 보여야 해요. 교도들은 정화 부적을 붉은 실로 감아 허리에 차요. 이 폐단에서 부적실을 모아 정화 부적 두 장만 만들어 주세요. 백골 장터에서 제가 실을 감을게요."}, {"s": null, "t": "모래 속에서 무언가 아직 웅얼거렸다. 이백세 개의 빈칸이 바람에 한 장씩 넘어갔다."}]'::jsonb where quest_id = 'mq_eclipse_gate' and step = 2 and md5(need::text) = md5('{"at": ["black_sand_temple"], "tasks": [{"n": 1, "r": ["black_sand_temple"], "t": "travel"}, {"m": ["m_11"], "n": 2, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_eclipse_gate'' and step = 2 and md5(need::text'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "사월이 부적에 붉은 실을 감았다. 손끝이 익숙했다. 한때 날마다 하던 일이었을 것이다."}, {"s": "q:m_sawol", "t": "이렇게 일곱 번. 월식의 일곱 날을 뜻해요. 저도 열두 살 때 처음 감았어요."}, {"s": "q:m_sawol", "t": "하나는 {이름} 님이 감아 봐요. 제 것만 감으면 성에서 손 모양이 다르다고 들킬지도 몰라요."}, {"s": null, "t": "나는 사월을 따라 실을 감았다. 다섯 번째에서 실이 꼬여 엉켰다."}, {"s": "q:m_sawol", "t": "아이참, 반대로 돌렸잖아요. 그렇게 감으면 월식이 하루 늘어나요. …농담이에요. 다시 해 봐요."}, {"s": null, "t": "사월이 내 손등을 잡고 실을 한 바퀴씩 함께 돌려 주었다. 일곱 번째 매듭이 단단히 묶였다."}, {"s": "q:m_yeon", "t": "사월 씨, 성 안에서 누가 알아보면 어떡하죠?"}, {"s": "q:m_sawol", "t": "알아보겠죠. 대호법 사마겸은 저를 길렀으니까요. 하지만 그분은 강한 사람을 먼저 봐요. 조사원 님이 강하면, 저는 뒤에 숨어 있을 수 있어요."}, {"s": "q:m_yun", "t": "월식성 지도는 옛 진상 장부에서 베껴 왔습니다. 동쪽 수문이 가장 허술하다고 적혀 있더군요."}, {"s": "q:m_yeon", "t": "출납관님은 그런 것까지 다 갖고 계시네요."}, {"s": "q:m_yun", "t": "장부는 다 기억합니다. 잊히는 건… 늘 사람이 먼저지요."}, {"s": "q:m_yeon", "t": "월식은 오늘 밤이에요. 적월교 월식성 성문을 지키는 월식 파계장을 쓰러뜨려야 제단까지 길이 열려요."}, {"s": "q:m_sawol", "t": "파계장은 성 어귀엔 안 나와요. 답사 지도 셋째 칸부터, 안쪽 깊은 데까지 들어가 탐색해야 나타나요. 교도들도 그 안쪽을 「문지기 마당」이라고 불러요."}]'::jsonb where quest_id = 'mq_eclipse_gate' and step = 3 and md5(need::text) = md5('{"at": ["bone_market"], "give": {"ward_talisman": 2}, "tasks": [{"n": 3, "r": ["black_sand_temple"], "t": "gather", "items": ["talisman_thread"]}, {"n": 2, "t": "craft", "items": ["ward_talisman"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_eclipse_gate'' and step = 3 and md5(need::text'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "파계장의 도끼가 휘익 바람을 가르며 내려왔다. 나는 몸을 굴려 피했다. 도끼날이 쾅 떨어진 자리에서 돌바닥이 쩍 갈라졌다."}, {"s": null, "t": "나는 갈라진 틈을 딛고 뛰어올라 마지막 일격을 넣었다. 파계장이 무릎부터 털썩 무너졌다."}, {"s": null, "t": "그 순간 하늘의 달이 붉게 먹혀 들어갔다. 누가 한 입씩 베어 무는 것처럼 둥근 가장자리가 차례로 사라졌다."}, {"s": null, "t": "성벽 위 횃불이 일제히 꺼졌다. 어둠 속에서 제단 위로 붉은 실 이백세 가닥이 스르르 떠올랐다."}, {"s": null, "t": "실마다 끝에 작은 불티 같은 것이 매달려 웅웅 떨었다. 실이 흔들릴 때마다 사람의 숨소리 같은 것이 섞여 들렸다. 사월이 내 등 뒤에서 내 옷자락을 꽉 움켜쥐었다."}, {"s": "red_moon_cult:wolhwa", "t": "왔구나, 사월아. 네가 데려온 이가 파계장을 눕혔다니. 손님 대접을 해야겠네."}, {"s": null, "t": "목소리는 바로 귓가에서 들렸다. 붉은 면사포를 쓴 이는 몇 걸음 떨어진 제단 위에 서 있었다. 나는 사월 앞을 막아섰다."}, {"s": "q:m_sawol", "t": "그만두세요, 교주님! 그 이름들은 다 사람이었어요. 우리한테 밥을 지어 주던 사람도 있었어요!"}, {"s": "red_moon_cult:wolhwa", "t": "그래서 바치는 거란다. 아무도 부르지 않는 이름은 문 앞에서나 쓸모가 있지."}, {"s": "red_moon_cult:wolhwa", "t": "버리는 쪽은 따로 있는데, 줍는 우리만 늘 욕을 먹는구나."}, {"s": null, "t": "월화가 면사포를 걷었다. 실이 한꺼번에 툭툭 끊어졌다. 제단 아래 돌바닥이 숨을 쉬듯 우르르 갈라졌다. 두 번째 문이 열렸다."}, {"s": "q:m_sawol", "t": "안 돼… 안 돼요! 다들 가 버렸어요!"}, {"s": null, "t": "사월이 끊어진 실 쪽으로 달려가려 했다. 나는 사월의 팔을 붙잡아 끌어당겼다. 갈라진 틈에서 차가운 바람이 휘몰아쳤다."}, {"s": null, "t": "제단 옆 그늘에서 어깨가 넓은 사내가 걸어 나왔다. 적월 대호법 사마겸이었다."}, {"s": "red_moon_cult:sama", "t": "교주. 문은 열렸소. 이 아이와 조사원은 내가 내보내겠소. 강한 자는 이런 데서 죽기 아깝지."}, {"s": "red_moon_cult:wolhwa", "t": "마음대로 하렴, 겸. 다음 문은 물 밑에 있으니, 어차피 우리 길은 또 만나."}, {"s": null, "t": "사마겸이 사월과 나를 성 뒷문까지 데려갔다. 품에서 깎다 만 무 한 토막을 꺼내 사월의 손에 쥐여 주었다."}, {"s": "red_moon_cult:sama", "t": "먹어라. 울면 배가 고프다. 너는 어릴 때도 울고 나면 무를 찾았지."}, {"s": "red_moon_cult:sama", "t": "조사원. 살아서 나간 놈은 내가 기억한다. 뇌명봉으로 가라. 벼락 맞은 바위에 문의 메아리가 새겨진다. 꼭대기를 몇 번이고 뒤져 봐라. 내가 줄 수 있는 건 거기까지다.", "fac_not": "red_moon_cult", "spec": 2, "grp": 1}, {"s": "red_moon_cult:sama", "t": "교의 밥을 먹으면서 정청 일을 끝까지 하는구나. 그것도 강한 거다. 뇌명봉으로 가라. 벼락 맞은 바위에 문의 메아리가 새겨진다. 꼭대기를 몇 번이고 뒤져 봐라. 내가 줄 수 있는 건 거기까지다.", "fac": "red_moon_cult", "spec": 1, "grp": 1}, {"s": "q:m_sawol", "t": "…고마워요, 사부님."}]'::jsonb where quest_id = 'mq_eclipse_gate' and step = 4 and md5(need::text) = md5('{"at": ["red_moon_fort"], "tasks": [{"n": 1, "r": ["red_moon_fort"], "t": "win", "rank": "guardian"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_eclipse_gate'' and step = 4 and md5(need::text'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "뇌명봉 꼭대기에 벼락이 꽈르릉 내리쳤다. 그때마다 검게 그을린 바위에 흰 글자가 잠깐 떠올랐다 사라졌다."}, {"s": null, "t": "글자는 불에 달군 쇠처럼 하얗게 빛났다. 손을 대려 하자 찌릿한 기운이 손끝을 쳐냈다. 다음 벼락에는 다른 글자가 떠올랐다."}, {"s": "q:m_sawol", "t": "이건 문이 열릴 때 울린 소리가 남긴 자국이에요. 이름 대신 소리만 남은 거죠."}, {"s": null, "t": "나는 벼락이 칠 때마다 떠오르는 글자를 하나씩 세었다. 비가 그칠 무렵 다 세고 나서 이백세 개라고 말했다."}, {"s": "q:m_sawol", "t": "…다 세셨군요. 잊지 않아 주셔서 고마워요. 누가 세어 주고 기억해 주면, 그만큼은 덜 사라지는 거래요."}, {"s": null, "t": "사월이 사마겸이 준 무를 반으로 쪼개 한쪽을 내게 내밀었다. 우리는 젖은 바위에 나란히 앉아 무를 아삭아삭 씹었다."}, {"s": null, "t": "바람을 타고 전서구가 날아들었다. 나는 연서희의 글을 펴서 읽었다."}, {"s": "q:m_yeon", "t": "「문이 열렸다면 그 길을 거꾸로 따라가야 해요. 세 곳에 남은 흔적을 맞추면 다음 문이 어디인지 알 수 있을 거예요. 막지 못한 문은 어디로 가는지라도 알아야 해요.」"}, {"s": "q:m_yeon", "t": "「이제 흑사단 폐단과 적월교 월식성, 뇌명봉에서 단서를 찾아 주세요.」"}]'::jsonb where quest_id = 'mq_eclipse_gate' and step = 5 and md5(need::text) = md5('{"at": ["thunder_peak"], "tasks": [{"n": 3, "r": ["thunder_peak"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_eclipse_gate'' and step = 5 and md5(need::text'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "맞춘 단서들이 한 줄로 이어졌다. 흑사단의 이름, 월식의 실, 벼락의 메아리가 차례로 놓였다."}, {"s": "q:m_yeon", "t": "두 번째 문은 이미 열렸어요. 막지는 못했지만, 어디로 가는지는 알았어요."}, {"s": "q:m_sawol", "t": "메아리가 아래로, 물 쪽으로 흘렀어요. 다음 문은 물 밑이에요."}, {"s": "q:m_yeon", "t": "수향 뱃길이군요. 젖은 장부가 흘러갔던 바로 그 물길이요."}, {"s": "q:m_yun", "t": "수향 연맹 쪽 장부라면 제가 먼저 맞춰 보겠습니다. 뱃삯 기록에 뭔가 남아 있을지도 모릅니다."}, {"s": "q:m_sawol", "t": "저는 여기 남을게요. 성에 남은 아이들 중에 아직 제 이름을 지킬 수 있는 아이들이 있어요."}, {"s": null, "t": "사월이 붉은 실 한 가닥을 내 손목에 감아 주었다. 일곱 번을 감고 단단히 맸다."}, {"s": "q:m_sawol", "t": "이번엔 바로 돌렸어요. 하루도 안 늘어요."}, {"s": "q:m_yeon", "t": "구름나루로 가요. 물이 무언가를 기억하고 있을 거예요."}]'::jsonb where quest_id = 'mq_eclipse_gate';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "구름나루의 물빛이 이상했다. 밤인데도 물 밑에서 희미한 등불이 떠다녔다."}, {"s": null, "t": "등불은 물낯 한 길 아래에서 둥실둥실 흘렀다. 물살을 따라가지 않고 제멋대로 떠돌다가, 배가 가까이 가면 스르르 가라앉았다."}, {"s": null, "t": "불빛은 차갑고 푸르렀다. 손을 물에 넣어 보니 등불 근처만 얼음물처럼 시렸다."}, {"s": null, "t": "나루 평상에는 정청에서 먼저 내려온 연서희와 윤도한이 앉아 있었다. 뱃전에 걸터앉은 노들 영감이 곰방대를 문 채 물을 내려다보았다."}, {"s": "river_alliance:nodeul", "t": "종이가 물을 거슬러 가는 것까지는 봤네만, 물 밑에 등이 켜진 건 또 처음이여. 저건 산 사람이 든 등이 아니여."}, {"s": null, "t": "나루 장부를 끼고 선 도방 진소랑이 한숨을 쉬었다."}, {"s": "river_alliance:jin", "t": "손님들이 무서워서 배를 안 타요. 장사가 반토막이랍니다. 천엽 연화늪 쪽에서는 밤마다 노래가 들린대요. 가사가 없는 노래요."}, {"s": "q:m_yeon", "t": "가사 없는 노래… 이름이 지워진 노래일지도 몰라요."}, {"s": "q:m_yun", "t": "뱃삯 장부를 맞춰 봤습니다. 지난 석 달, 용잠 수궁 쪽으로 나간 배는 장부에 있는데 돌아온 기록이 없습니다. 열한 척입니다."}, {"s": "q:m_yun", "t": "역린이 닫혔다는 뱃사람 소문이 헛말은 아니었나 봅니다."}, {"s": "river_alliance:nodeul", "t": "역린? 자네, 그 말을 어디서 들었나. 그건 우리 뱃사람끼리도 입에 안 올리는 말인데."}, {"s": "q:m_yun", "t": "장부 귀퉁이에 적혀 있더군요. 장부는 뭐든 다 압니다."}, {"s": "river_alliance:nodeul", "t": "역린은 용 목 밑에 거꾸로 난 비늘이여. 용잠 수궁 깊은 데 그런 비늘 하나가 문처럼 물길을 잠가 두고 있다는 게지."}, {"s": "q:m_yeon", "t": "물 밑 문이에요. 사월이 말한 다음 문이요. 이번엔 열리기 전에 닿아야 해요."}, {"s": "river_alliance:jin", "t": "정청에서 이 일을 맡아 주시면 뱃삯은 반값으로 해 드릴게요."}, {"s": "q:m_yeon", "t": "반값이요? 지난번엔 공짜라고 하셨잖아요."}, {"s": "river_alliance:jin", "t": "어머, 제가 그랬나요? 장부를 봐야겠네. 그럼 칠 할 깎아 드리죠. 약속은 약속이니까요."}, {"s": null, "t": "진소랑이 주판의 붉은 알 하나를 손끝으로 톡 튕겼다. 연서희가 소리 없이 웃었다."}, {"s": "river_alliance:nodeul", "t": "흥정은 됐으면 들어 보게. 노래가 어디서 오는지부터 알아야 하네."}, {"s": "river_alliance:nodeul", "t": "천엽 연화늪에 가서 수향 갈대 세 대만 꺾어 오게. 갈대 피리는 물이 부르는 노래를 따라 부르지. 피리는 내가 깎아 주겠네."}]'::jsonb where quest_id = 'mq_sunken_lantern' and step = 1 and md5(need::text) = md5('{"at": ["river_ferry"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_sunken_lantern'' and step = 1 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "노들 영감이 갈대 마디를 칼끝으로 뚫었다. 구멍은 일곱 개였다. 사월이 감아 준 실의 수와 같았다."}, {"s": null, "t": "나는 손목에 감긴 붉은 실을 내려다보았다. 노들 영감이 그것을 보고 고개를 끄덕였다."}, {"s": "river_alliance:nodeul", "t": "좋은 실을 찼구먼. 피리는 자네가 쥐게. 갈대를 꺾어 온 손이 쥐어야 소리가 나지."}, {"s": "river_alliance:nodeul", "t": "물에 대고 불지 말고, 물이 불게 두게. 피리는 듣는 거여."}, {"s": null, "t": "나는 피리를 물가에 대었다. 바람도 없는데 피리에서 소리가 났다."}, {"s": null, "t": "소리는 낮고 길었다. 여러 사람이 한꺼번에 흥얼거리는 소리가 일곱 구멍에서 번갈아 새어 나왔다. 피리를 쥔 손바닥이 덜덜 울렸다."}, {"s": "q:m_yeon", "t": "사람 목소리예요. 여럿이…. 이름을 부르려다 끝내 못 부르는 목소리."}, {"s": "river_alliance:nodeul", "t": "돌아오지 못한 열한 척 뱃사람들도 저 안에 있겠지. 노래는 수경루 쪽으로 흐르네. 거울 누각이 물 노래를 비춰 보여 줄 걸세."}, {"s": "river_alliance:jin", "t": "수경루엔 수경무희들이 밤새 춤을 춘다던데요. 둘만 쓰러뜨려도 춤이 멎고 거울이 맑아질 거예요."}, {"s": "river_alliance:jin", "t": "우리 뱃사람들 얼굴이라도 봐야 식구들한테 말을 전하죠. 뱃삯은 깎아 드릴 테니 꼭 부탁드려요. 칠 할이요."}]'::jsonb where quest_id = 'mq_sunken_lantern' and step = 2 and md5(need::text) = md5('{"at": ["river_ferry"], "give": {"river_reed": 3}, "tasks": [{"n": 3, "r": ["lotus_marsh"], "t": "gather", "items": ["river_reed"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_sunken_lantern'' and step = 2 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "수경무희의 소맷자락이 사르르 휘감겨 왔다. 나는 소매를 끊어 내며 파고들었다. 둘째 무희가 물보라를 일으키며 철썩 쓰러졌다."}, {"s": null, "t": "춤이 멎자 물 위 누각이 고요해졌다. 호수에 비친 달 아래로 거울처럼 맑은 물속이 들여다보였다."}, {"s": null, "t": "물 밑에 사람들이 줄지어 서 있었다. 얼굴은 흐릿했고 입만 움직였다. 모두 같은 노래를 부르고 있었다."}, {"s": null, "t": "행렬은 물 밑 바닥을 따라 끝없이 이어졌다. 누구는 노를 쥐고 있었고, 누구는 아이를 업고 있었다. 발이 땅에 닿지 않은 채 한 걸음씩 아래로 걸어 내려갔다."}, {"s": "q:m_yeon", "t": "저 사람들… 장부에서 지워진 이름들이에요. 붉은 인장과 함께 사라진 부적 기록에 있던 사람도 보여요. 아직 흩어지지 않은 걸 보면, 누군가 저 이름들을 붙들고 있나 봐요."}, {"s": null, "t": "연서희가 난간을 붙잡은 채 몸을 내밀었다. 나는 연서희의 허리띠를 붙들어 주었다."}, {"s": "q:m_yeon", "t": "괜찮아요, 안 빠져요. …그래도 놓지는 마요."}, {"s": null, "t": "나는 저 사람들이 무엇을 향해 부르고 있느냐고 중얼거렸다."}, {"s": null, "t": "행렬은 아래로, 더 아래로 이어졌다. 그 끝에 거대한 비늘 하나가 문처럼 서 있었다. 노래가 닿을 때마다 비늘이 끼긱, 조금씩 돌아갔다."}, {"s": "q:m_yeon", "t": "노래가 열쇠를 돌리고 있어요. 다 돌아가면 세 번째 문이 열려요."}, {"s": "q:m_yeon", "t": "수궁은 깊어요. 빛이 없으면 길을 잃어요. 어유 등잔을 하나 만들어 용잠 수궁으로 들고 가요. 물 밑에서도 꺼지지 않는 불이 필요해요. 저도 따라갈게요."}]'::jsonb where quest_id = 'mq_sunken_lantern' and step = 3 and md5(need::text) = md5('{"at": ["mirror_pavilion"], "tasks": [{"m": ["m_18"], "n": 2, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_sunken_lantern'' and step = 3 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "등잔을 켜자 수궁의 산호 기둥이 하나씩 모습을 드러냈다. 기둥 사이에서 집채만 한 등딱지가 천천히 움직였다."}, {"s": null, "t": "등딱지에는 이끼와 조개가 켜켜이 붙어 있었다. 등딱지가 움직일 때마다 뽀글뽀글 거품이 솟았고, 바닥의 모래가 스르르 밀려났다."}, {"s": null, "t": "기둥만 한 목이 어둠 속에서 쑥 나왔다. 사람 머리만 한 눈이 등잔불을 비추며 느리게 깜빡였다. 연서희가 숨을 들이켜며 내 팔을 붙잡았다."}, {"s": "q:m_gaon", "t": "불을 들고 온 사람은… 백 년 만이구나. 대부분은 불 없이 와서, 불 없이 남았지."}, {"s": null, "t": "나는 누구냐고 물었다."}, {"s": "q:m_gaon", "t": "가온이라 한다. 이 수궁의 문을 지켜 왔지. 이제는 지켰다고 말하기 부끄럽다만."}, {"s": "q:m_gaon", "t": "역린은 본디 용왕이 스스로 잠근 것이다. 그 아래 있는 것을 다시는 내보내지 않으려고. 그런데 누군가 이름들을 물에 풀었어. 이름의 노래는 역린을 돌린다."}, {"s": "q:m_yeon", "t": "누가 풀었는지 보셨나요?"}, {"s": "q:m_gaon", "t": "얼굴은 못 봤다. 장부 냄새가 났지. 먹물과 젖은 종이 냄새. 손끝이 아주 정갈한 자였다."}, {"s": "q:m_gaon", "t": "그자는 이름을 물에 풀기 전에 하나하나 낮게 불러 주더군. 저 행렬이 흩어지지 않은 건, 누군가 오래 그렇게 불러 왔기 때문일 게다."}, {"s": null, "t": "연서희가 아무 말 없이 등잔 불빛을 내려다보았다. 등잔을 쥔 내 손등에 연서희의 손이 잠깐 얹혔다가 떨어졌다."}, {"s": "q:m_gaon", "t": "수궁 해일장이 문 앞을 막고 있다. 저것이 깨어 있는 한 나는 등딱지를 들 수가 없다. 그대가 눕혀 주게."}, {"s": "q:m_gaon", "t": "문 가까이엔 오지 않는다. 그 등불을 들고 수궁 깊은 데로, 답사 지도 셋째 칸 안쪽까지 들어가 뒤지면 놈이 냄새를 맡고 나올 게다."}]'::jsonb where quest_id = 'mq_sunken_lantern' and step = 4 and md5(need::text) = md5('{"at": ["sunken_palace"], "give": {"fish_oil_lamp": 1}, "tasks": [{"n": 1, "r": ["sunken_palace"], "t": "travel"}, {"n": 1, "t": "craft", "items": ["fish_oil_lamp"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_sunken_lantern'' and step = 4 and md5(need::te'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "해일장이 일으킨 물기둥이 쏴아아 쏟아졌다. 등잔불이 꺼질 듯 흔들렸다. 나는 등잔을 등 뒤로 감추며 해일장의 옆구리를 베었다."}, {"s": null, "t": "해일장이 무너지자 수궁 전체가 한 번 크게 출렁였다. 물이 빠져나가듯 노래가 잠깐 멎었다."}, {"s": "q:m_gaon", "t": "이제 보이는가. 역린이다."}, {"s": null, "t": "문만 한 비늘이 반쯤 돌아가 있었다. 비늘 겉은 검푸른 쇠처럼 번들거렸고, 가장자리에 사람 손자국 같은 홈이 수없이 패어 있었다."}, {"s": null, "t": "비늘 틈으로 차가운 숨이 새어 나왔다. 이름 없는 얼굴들이 비늘 앞에 모여 소리 없이 입을 벌렸다."}, {"s": "q:m_yeon", "t": "다 막지는 못해도… 저 사람들이라도 노래를 그치게 할 수는 없을까요?"}, {"s": "q:m_gaon", "t": "노래는 누가 시작했는지 알아야 끝낼 수 있다. 노래는 남쪽에서 왔다. 바다 끝, 등대들이 서 있는 곳에서."}, {"s": "q:m_gaon", "t": "연화늪의 갈대, 수경루의 거울, 이 수궁의 비늘. 노래가 지나간 자리를 맞춰 보면 누가 불을 붙였는지 보일 게다."}, {"s": "q:m_yeon", "t": "이제 천엽 연화늪과 수경루, 용잠 수궁에서 단서를 찾아 주세요. 노래를 시작한 사람을 찾으면, 저 사람들을 쉬게 할 수 있을지도 몰라요."}]'::jsonb where quest_id = 'mq_sunken_lantern' and step = 5 and md5(need::text) = md5('{"at": ["sunken_palace"], "tasks": [{"n": 1, "r": ["sunken_palace"], "t": "win", "rank": "guardian"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_sunken_lantern'' and step = 5 and md5(need::te'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "단서가 맞물렸다. 노래는 남쪽 바다의 등대 불빛을 타고 물길로 흘러들었다."}, {"s": "q:m_gaon", "t": "세 번째 문은 결국 열리겠지. 나 혼자서는 비늘을 붙잡아 둘 수 없다."}, {"s": "q:m_yeon", "t": "그럼 같이 가요. 문 앞에서 기다리는 것보다, 문을 연 사람을 찾는 게 빨라요."}, {"s": "q:m_gaon", "t": "…천 년을 한자리에 있었다. 등딱지가 굳어서 걸을 수나 있을지."}, {"s": null, "t": "나는 길은 내가 안다고 말했다."}, {"s": null, "t": "가온이 허허 웃었다. 웃음소리가 물속에서 둥글게 울렸다."}, {"s": "q:m_gaon", "t": "불을 들고 온 사람이니 따라가 볼 만하겠지. 내 등에 타게. 물길이라면 아직 누구보다 빠르다."}, {"s": null, "t": "가온의 등딱지에 연꽃 무늬가 피어났다. 늙은 거북이 천 년 만에 수궁 밖으로 헤엄쳐 나왔다."}, {"s": null, "t": "등에 오르자 연서희가 내 소매를 꼭 붙들었다. 물살이 거세지자 연서희가 아이처럼 눈을 질끈 감았다."}, {"s": "q:m_yeon", "t": "저 헤엄 못 쳐요. 정청 사람들한텐 비밀이에요."}, {"s": null, "t": "가온이 구름나루 물가에 닿자 노들 영감과 윤도한이 나루 끝까지 나와 있었다."}, {"s": "river_alliance:nodeul", "t": "살다 보니 용궁 거북 등에 탄 사람을 다 보네. 남쪽 바다까지 몸조심하게."}, {"s": "q:m_yun", "t": "남쪽이면 남명 망국령이군요. 잔불촌 쪽 보급은 제가 미리 장부를 잡아 두겠습니다."}, {"s": "q:m_yeon", "t": "아홉 등대가 서 있는 바다로 가요."}]'::jsonb where quest_id = 'mq_sunken_lantern';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 잔불촌 언덕에서 바다를 내려다보았다. 군도 위 아홉 등대 가운데 불이 켜진 것은 셋뿐이었다."}, {"s": null, "t": "언덕 꼭대기 화로 앞에 한 팔뿐인 노장이 앉아 있었다. 빈 소매를 화로 쪽으로 바짝 대고 있었다."}, {"s": "southern_remnant:jang", "t": "앉으시오. 없는 팔이 밤마다 시려서, 늙은이가 불 앞을 못 떠나오."}, {"s": "southern_remnant:jang", "t": "나라가 망하던 밤에도 등대는 꺼지지 않았소. 그런데 지난달부터 하나씩, 하나씩 꺼져 가고 있소."}, {"s": null, "t": "나와 함께 언덕을 오른 연서희가 화로 곁에 앉아 군도를 내려다보았다."}, {"s": "q:m_yeon", "t": "아홉 등대가 아홉 문과 짝이라는 기록이 있어요. 등대가 꺼질 때마다 문이 하나씩 열린 거라면…."}, {"s": "southern_remnant:jang", "t": "이미 여섯이 꺼졌소. 남은 셋이 마지막 문들이겠지."}, {"s": null, "t": "화로 뒤에서 젊은 여자가 재를 털며 일어섰다. 정찰대장 갈매가 나를 위아래로 훑어보았다."}, {"s": "southern_remnant:galmae", "t": "정청 사람이 또 왔네. 너네가 와서 불이 켜진 적이 있냐?", "fac_not": "southern_remnant", "spec": 2, "grp": 1}, {"s": "southern_remnant:galmae", "t": "너였어? 정청 사람들 데리고 왔네. 저 사람들 와서 불이 켜진 적이 있는지 한번 보자.", "fac": "southern_remnant", "spec": 1, "grp": 1}, {"s": "southern_remnant:jang", "t": "갈매야."}, {"s": "southern_remnant:galmae", "t": "…알았어, 할배. 꺼진 등대 밑마다 검은 연꽃 표식이 있었어. 흑련회 놈들이야. 배를 타고 재의 해안 쪽으로 드나들더라."}, {"s": "q:m_yeon", "t": "종을 노리던 흑련회가 등대까지 손을 댔다면, 문을 여는 손이 하나가 아니에요. 그 배를 찾아야 해요."}, {"s": "q:m_yeon", "t": "해안에 그 배가 남아 있을지도 몰라요. 갈매 대장과 함께 재의 해안을 몇 번이고 뒤져 주세요."}, {"s": "southern_remnant:galmae", "t": "따라오든가. 대신 느리면 두고 간다."}]'::jsonb where quest_id = 'mq_ash_sea' and step = 1 and md5(need::text) = md5('{"at": ["ember_village"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_ash_sea'' and step = 1 and md5(need::text) = m'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "잿빛 파도가 난파선 옆구리를 철썩철썩 때렸다. 기울어진 갑판이 미끈거렸다."}, {"s": null, "t": "선창으로 내려가던 내 발이 쭉 미끄러졌다. 갈매가 내 뒷덜미를 확 낚아채 끌어올렸다."}, {"s": "southern_remnant:galmae", "t": "발밑 보라고! 여기 판자 썩은 거 안 보여?"}, {"s": null, "t": "나는 고맙다고 했다. 갈매는 대꾸 대신 고개를 홱 돌리고 먼저 선창 안으로 내려갔다."}, {"s": null, "t": "선창 안에 젖은 상자들이 쌓여 있었다. 상자마다 검은 연꽃이 찍혀 있었다."}, {"s": "southern_remnant:galmae", "t": "기름이네. 등대 기름을 빼돌려서 바다에 버렸어. 불을 끄려고 일부러."}, {"s": null, "t": "상자 밑바닥에 기름 먹은 장부 한 권이 붙어 있었다. 글씨가 아주 정갈했다."}, {"s": "q:m_yeon", "t": "이 글씨… 어디서 본 것 같은데. 정청 서식이에요. 칸 나누는 법까지 똑같아요."}, {"s": "southern_remnant:galmae", "t": "너네 본부 사람이 흑련회 짐을 셈해 줬다는 거야?"}, {"s": "q:m_yeon", "t": "정청 서식은 누구나 베낄 수 있어요. 아직 단정하긴 일러요."}, {"s": null, "t": "연서희는 그렇게 말하면서도 장부를 품에 넣고 오래 손을 떼지 못했다."}, {"s": "southern_remnant:galmae", "t": "하여간. 장 장군이 등대를 다시 켤 쇠틀을 만든대. 기름이 없으면 쇠틀이라도 있어야 불이 바람에 안 꺼져."}, {"s": "southern_remnant:galmae", "t": "주혈 광산에서 생 월철 네 덩이를 캐다 잔불촌의 장군께 갖다 줘. 갱도 원령들이 길을 막을 테니 두엇은 쓰러뜨려야 할 거야. 나는 해안을 지켜야 해서 못 가."}]'::jsonb where quest_id = 'mq_ash_sea' and step = 2 and md5(need::text) = md5('{"at": ["ash_coast"], "tasks": [{"n": 3, "r": ["ash_coast"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_ash_sea'' and step = 2 and md5(need::text) = m'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "장무현이 한 팔로 망치를 들었다. 생 월철이 불 속에서 붉게 달아올랐다."}, {"s": "southern_remnant:jang", "t": "집게를 잡아 주시오. 팔이 하나라 쇠를 붙들 손이 없소."}, {"s": null, "t": "나는 집게로 달군 쇠를 모루 위에 붙들었다. 장무현의 망치가 떨어질 때마다 땅, 땅 소리와 함께 불티가 튀었다."}, {"s": "southern_remnant:jang", "t": "등대 불은 쇠틀에 담아야 바람에 안 꺼지오. 나라가 망한 뒤로 망치를 든 적이 없는데. 손이 잘 맞소."}, {"s": null, "t": "나는 광산 원령들이 「돌려 달라」고 울부짖더라고 말했다."}, {"s": "q:m_yeon", "t": "장군님, 무엇을 돌려 달라는 걸까요."}, {"s": "southern_remnant:jang", "t": "이름이오. 저 광산에서 죽은 우리 백성들은 장부에 이름 한 줄 못 남겼소. 망국의 백성은 어느 장부에서든 먼저 지워지지."}, {"s": "q:m_yeon", "t": "…그래서 흑련회가 그 이름을 쓸 수 있었군요. 아무도 찾지 않는 이름이니까. 이름도 없이 원한만 남아서 원령이 된 거고요."}, {"s": null, "t": "장무현이 망치를 내려놓고 빈 소매를 화로 쪽으로 돌렸다. 한참 아무 말도 하지 않았다."}, {"s": "southern_remnant:jang", "t": "쇠틀은 다 됐소. 허나 구등대 군도까지는 물살이 사나워 배가 못 가오. 원정을 꾸려 끝까지 건너가시오. 남은 세 등대는 등대지기 하나가 홀로 섬을 돌며 지킨다 들었소."}, {"s": "q:m_yeon", "t": "저는 나루로 가서 보급선을 잡아 둘게요. 기름이며 먹을 것을 싣고 뒤따라갈게요. 혼자 섬을 지키는 사람한테 빈손으로 갈 수는 없잖아요."}]'::jsonb where quest_id = 'mq_ash_sea' and step = 3 and md5(need::text) = md5('{"at": ["ember_village"], "give": {"raw_iron": 4}, "tasks": [{"n": 4, "r": ["crimson_mine"], "t": "gather", "items": ["raw_iron"]}, {"m": ["x_crimson_mine_2"], "n": 2, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_ash_sea'' and step = 3 and md5(need::text) = m'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 안개를 헤치고 군도의 가장 바깥 섬에 닿았다. 등대 꼭대기에서 작은 불씨 하나가 흔들리고 있었다. 기름통을 진 사람이 막 계단을 내려오고 있었다."}, {"s": "q:m_dohwa", "t": "오지 마세요! …아, 흑련회가 아니군요. 미안해요. 요즘은 발소리만 들려도 무서워서."}, {"s": null, "t": "도화는 기름통을 내려놓고도 한참 숨을 몰아쉬었다. 손바닥이 기름통 끈에 쓸려 벌겋게 벗겨져 있었다."}, {"s": null, "t": "나는 짐에서 고약을 꺼내 도화의 손바닥에 발라 주었다. 도화가 따가운지 어깨를 움찔했다."}, {"s": "q:m_dohwa", "t": "고마워요. 누가 제 손을 봐 준 게 할머니 돌아가신 뒤로 처음이에요."}, {"s": "q:m_dohwa", "t": "저는 도화예요. 아홉 등대지기 가운데 마지막으로 남았어요. 다른 여덟은… 명령서를 받고 스스로 불을 끄고 떠났어요. 남은 세 등대는 제가 섬을 돌아가며 지켜요."}, {"s": null, "t": "나는 명령서라니, 하고 되물었다."}, {"s": "q:m_dohwa", "t": "이거요. 본부에서 왔대요. 「구등대의 불을 거두고 등대지기는 철수하라」. 저만 따르지 않았어요. 할머니가 그러셨거든요. 등대는 누가 시켜서 켜는 게 아니라고."}, {"s": null, "t": "젖은 종이 아래 붉은 인장이 선명했다. 야행국 본부 정청의 인장이었다."}, {"s": "q:m_dohwa", "t": "세 섬을 혼자 돌다 보니 기름이 다 떨어져서, 이 불도 곧 꺼져요. 이 불이 꺼지면 문이 또 하나 열린대요."}, {"s": "q:m_dohwa", "t": "등대 불은 영기가 뭉친 응축 영핵이 있어야 다시 커져요. 하나만 만들어 주실 수 있어요?"}]'::jsonb where quest_id = 'mq_ash_sea' and step = 4 and md5(need::text) = md5('{"at": ["nine_lighthouse"], "tasks": [{"n": 1, "t": "expedition"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_ash_sea'' and step = 4 and md5(need::text) = m'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 응축 영핵을 쇠틀에 얹었다. 영핵이 쩌릉 울리더니 푸른 불씨가 단숨에 기둥처럼 솟구쳤다."}, {"s": null, "t": "불기둥은 등대 꼭대기를 넘어 하늘까지 닿았다. 뜨겁지 않았다. 볼에 닿는 빛이 봄볕처럼 미지근했다."}, {"s": null, "t": "빛이 퍼지며 안개가 양쪽으로 갈라졌다. 꺼졌던 여섯 등대의 윤곽이 바다 위에 검게 드러났다."}, {"s": "q:m_dohwa", "t": "켜졌어요… 할머니, 보세요. 켜졌어요."}, {"s": null, "t": "도화가 등대 난간을 붙잡고 엉엉 울었다. 나는 도화의 등을 가만히 두드려 주었다."}, {"s": null, "t": "그때 보급선이 섬에 닿았다. 연서희와 윤도한이 배에서 내렸다. 윤도한은 명령서를 받아 들자마자 입을 열었다."}, {"s": "q:m_yun", "t": "위조입니다. 인장 테두리가 반 푼 굵습니다. 정청 인장은 이렇게 찍히지 않습니다."}, {"s": "q:m_yeon", "t": "…한눈에 아시네요. 저는 몇 번을 봐도 진짜 같은데."}, {"s": "q:m_yun", "t": "장부만 십오 년을 봤으니까요. 이건 제가 정청에 가져가 감찰관님께 넘기겠습니다. 걱정 마십시오."}, {"s": "q:m_dohwa", "t": "안 돼요. 이건 제가 가지고 있을래요. …죄송해요. 지금은 아무도 못 믿겠어요."}, {"s": null, "t": "윤도한이 명령서를 내밀던 손을 천천히 거두었다. 웃는 얼굴 그대로였다."}, {"s": "q:m_yeon", "t": "이제 재의 해안과 주혈 광산, 구등대 군도에서 단서를 찾아 주세요. 명령서가 어디서 왔는지, 이 바다가 먼저 말해 줄 거예요. 누가 불을 껐는지 알아야 남은 불을 지킬 수 있어요."}]'::jsonb where quest_id = 'mq_ash_sea' and step = 5 and md5(need::text) = md5('{"at": ["nine_lighthouse"], "give": {"spirit_core": 1}, "tasks": [{"n": 1, "t": "craft", "items": ["spirit_core"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_ash_sea'' and step = 5 and md5(need::text) = m'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "단서가 이어졌다. 등대 기름을 빼돌린 배, 망국 백성의 이름, 명령서가 지나온 길이 한 줄로 놓였다."}, {"s": "q:m_yeon", "t": "명령서는 정청 문서함을 거쳐 나갔어요. 위조든 아니든, 정청 안에서 찍혔어요."}, {"s": "southern_remnant:jang", "t": "등잔 밑이 어둡다는 말이 있소. 바깥만 보지 마시오."}, {"s": "q:m_dohwa", "t": "꺼진 등대 여섯은 다시 켤 수 없어요. 문이 이미 열렸으니까. 그래도 남은 세 불은 제가 계속 돌아가며 지킬게요."}, {"s": null, "t": "도화가 등대 불씨를 작은 등롱 노리개에 옮겨 담아 내 손에 쥐여 주었다."}, {"s": "q:m_dohwa", "t": "할머니가 물려준 불이에요. 어두운 데 가실 거잖아요. 가장 어두운 데로요."}, {"s": "southern_remnant:galmae", "t": "그 불 꺼뜨리면 다신 잔불촌에 오지 마."}, {"s": null, "t": "갈매는 그렇게 말하고 고개를 돌렸다. 귀 끝이 빨갰다."}, {"s": "q:m_yun", "t": "정청으로 돌아가시지요. 문서함 기록은 제가 미리 정리해 두겠습니다. 다들 고생 많으셨습니다."}, {"s": "q:m_yeon", "t": "…네. 돌아가요. 본부로."}, {"s": null, "t": "돌아가는 배 위에서 윤도한은 한 번도 바다를 돌아보지 않았다."}]'::jsonb where quest_id = 'mq_ash_sea';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "정청 대청에 등이 낮게 걸려 있었다. 감찰관 한설이 도화에게서 빌려 온 명령서를 상 위에 펼쳤다."}, {"s": null, "t": "연서희가 남쪽에서 막 닿은 전서를 펴 들고 있었다. 종이를 쥔 손가락이 하얬다."}, {"s": "q:m_yeon", "t": "도화 씨 편지예요. 「세 등대 가운데 둘이 결국 꺼졌어요. 혼자서는 다 못 돌았어요. 마지막 하나는 아직 버텨요.」"}, {"s": "q:m_yeon", "t": "꺼진 등대가 여덟이면 열린 문도 여덟이에요. 남은 건 도화 씨가 지키는 불 하나뿐이고요."}, {"s": null, "t": "나는 허리춤의 등롱 노리개를 만져 보았다. 노리개 안의 불씨가 작게 흔들렸다."}, {"s": null, "t": "한설이 명령서에서 눈을 떼지 않고 입을 열었다. 늘 붙이던 존댓말이 없었다."}, {"s": "night_office:han", "t": "인장은 진짜다. 정청 문서함 안에서, 정청 인장으로 찍혔다."}, {"s": "q:m_yeon", "t": "하지만 출납관님은 테두리가 굵다고…."}, {"s": "night_office:han", "t": "습기를 먹으면 테두리는 번진다. 그 정도는 장부를 십오 년 본 사람이면 안다."}, {"s": null, "t": "윤도한이 귀끝까지 붉어지며 고개를 숙였다."}, {"s": "q:m_yun", "t": "제가 성급했군요. 바닷바람에 젖은 걸 미처 생각하지 못했습니다. 부끄럽습니다."}, {"s": null, "t": "상석에 앉아 있던 도제조 백운서가 명령서를 끌어당겨 오래 들여다보았다."}, {"s": "night_office:baek", "t": "…문서함 열쇠를 가진 자는 셋이다. 나, 감찰관, 출납관."}, {"s": null, "t": "대청이 조용해졌다. 등잔 심지가 타는 소리만 지직 들렸다."}, {"s": "night_office:han", "t": "그리고 명령서 서식은 연화원 시절 것이다. 연화원이 봉인되기 전, 그곳 관리들이 쓰던 칸 나눔이다."}, {"s": "q:m_yeon", "t": "연화원 관리 명부는 장서각에 있었는데, 몇 해 전에 통째로 젖어서 버렸다고 들었어요. 그 무렵부터 백지교 아래로 종이학이 떠내려온다는 말이 돌았고요."}, {"s": "night_office:han", "t": "그 명부에 이 서식을 쓴 사람이 있을 거다. 조사원, 백지교를 세 번쯤 뒤져 건질 수 있는 건 다 건져 와라. 모 기록관은 정청으로 불러 두겠다."}]'::jsonb where quest_id = 'mq_lamp_shadow' and step = 1 and md5(need::text) = md5('{"at": ["hq_yard"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_lamp_shadow'' and step = 1 and md5(need::text)'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 백지교 아래 강물에서 건져 온 종이학들을 상 위에 하나씩 펴 놓았다. 하나같이 연화원 관리 명부의 낱장이었다."}, {"s": "night_office:mo", "t": "아이고, 이걸 다 건져 왔어요? 장서각 명부가 몇 해 전에 통째로 젖었다더니, 누가 백지교에 띄워 버렸던 거군요."}, {"s": "night_office:mo", "t": "가만있자… 연화원 관리 스물둘. 그런데 한 사람 자리만 이름이 비었어요. 긁어낸 게 아니라 먹을 다시 거둬 낸 자국이에요."}, {"s": "q:m_yeon", "t": "먹을 거둬 냈다면… 이름을 쓴 사람만 할 수 있는 방법이죠?"}, {"s": "night_office:mo", "t": "그렇죠. 제 손으로 쓴 이름을 제 손으로 거둔 거예요. 스스로 장부에서 사라진 사람이에요."}, {"s": null, "t": "모가람이 웃으려다 그만두었다. 찻주전자를 쥔 손이 한참 움직이지 않았다."}, {"s": "night_office:mo", "t": "서희야, 이제 너도 알아야겠다. 정청은 해마다 오래된 이름을 명부에서 거둬. 「명부 정리」라고, 우리 서리들은 「먹 거두기」라 부르지."}, {"s": "q:m_yeon", "t": "…거둬요? 무슨 기준으로요?"}, {"s": "night_office:mo", "t": "부를 사람도, 제사를 이을 사람도 없는 이름부터. 낡은 쪽부터. 거둔 이름은 아무 데도 묶이지 않아. 그게 지워진 이름이야."}, {"s": null, "t": "나는 처음 서고에 갔던 날을 떠올렸다. 모가람이 「해마다 오래된 쪽을 거둔다」고 해 놓고 웃으며 말을 돌렸던 날이었다."}, {"s": null, "t": "내가 그날 일을 말하자 모가람이 고개를 숙였다."}, {"s": "night_office:mo", "t": "…기억하시네요. 그때는 웃으면 넘어갈 줄 알았어요. 서른 해를 그렇게 넘어왔거든요."}, {"s": null, "t": "모가람이 떨리는 손으로 보리차를 따랐다. 찻물이 잔 밖으로 넘쳐 탁자를 적셨다. 나는 행주로 탁자를 닦고 잔을 모가람 앞에 놓아 주었다."}, {"s": "night_office:mo", "t": "고마워요. 오늘은 제가 받아 마셔야겠네요."}, {"s": "night_office:mo", "t": "거둔 먹은 영맥 수피 즙에 담그면 다시 떠올라요. 지운 사람이 누군지 보려면 그 수밖에 없어요. 귀죽림 영맥 수피가 가장 진하니, 세 장만 벗겨 와 주세요."}]'::jsonb where quest_id = 'mq_lamp_shadow' and step = 2 and md5(need::text) = md5('{"at": ["hq_yard"], "tasks": [{"n": 3, "r": ["paper_bridge"], "t": "search"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_lamp_shadow'' and step = 2 and md5(need::text)'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "모가람이 수피 즙에 낱장을 담갔다. 빈칸에서 먹이 천천히 배어 나왔다. 이름은 아직 흐렸지만 글씨체는 또렷했다."}, {"s": "night_office:mo", "t": "어… 이 글씨는."}, {"s": "q:m_yeon", "t": "정청 출납 장부 글씨예요. 칸마다 획을 끝까지 눌러 쓰는 버릇. 제가 매일 보는…."}, {"s": "night_office:mo", "t": "서희야, 아직 단정하지 마. 글씨는 닮을 수 있어."}, {"s": null, "t": "연서희가 대답 없이 출납관 자리를 돌아보았다. 의자가 비어 있었다."}, {"s": "q:m_yeon", "t": "출납관님은 오늘 아침 연화원 봉인 점검을 나가셨어요. 혼자서요."}, {"s": null, "t": "문간에서 출입 장부를 넘겨 보던 한설이 고개를 저었다."}, {"s": "night_office:han", "t": "서류에 없는 점검이다."}, {"s": null, "t": "한설이 붓을 꺼내 아주 천천히 닦았다. 다 닦은 붓을 내려놓는 손등에 힘줄이 섰다."}, {"s": "night_office:han", "t": "조사원, 지금 폐쇄된 연화원으로 가라. 봉인이 풀렸다면 연화원 봉인파쇄귀가 먼저 깨어 있을 거다. 나는 정청 문을 닫는다. 누가 드나드는지 내가 지켜야 한다."}, {"s": "night_office:han", "t": "봉인파쇄귀는 연화원 어귀엔 안 나온다. 답사 지도 셋째 칸부터, 안쪽 깊은 데까지 들어가 탐색해라."}, {"s": "q:m_yeon", "t": "저도 갈게요. …제 눈으로 직접 봐야겠어요."}, {"s": null, "t": "연서희가 붓을 필통에 꽂았다. 필통 뚜껑을 닫는 손이 떨려 두 번이나 헛돌았다. 나는 뚜껑을 대신 닫아 주었다."}]'::jsonb where quest_id = 'mq_lamp_shadow' and step = 3 and md5(need::text) = md5('{"at": ["hq_yard"], "give": {"spirit_bark": 3}, "tasks": [{"n": 3, "r": ["ghost_bamboo"], "t": "gather", "items": ["spirit_bark"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_lamp_shadow'' and step = 3 and md5(need::text)'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "봉인파쇄귀의 손톱이 쇳소리를 내며 휘몰아쳤다. 나는 연서희를 등 뒤로 밀어내고 그 손톱을 받아 냈다. 되받아친 일격에 파쇄귀가 쾅 연못 둑에 처박혀 무너졌다."}, {"s": null, "t": "파쇄귀가 쓰러지자 연못의 연잎이 일제히 뒤집혔다. 물 위에 등 하나가 떠 있었고, 그 곁에 윤도한이 서 있었다. 윤도한의 품에서 붉은 빛이 새어 나왔다."}, {"s": "q:m_yeon", "t": "출납관님. …그 품에 든 거, 붉은 인장이죠. 장부에서 사라졌던."}, {"s": "q:m_yun", "t": "서희 씨는 늘 정확했지요. 그래서 이 일을 맡기면 끝까지 올 줄 알았습니다. 여기까지 와 줘서 고맙습니다."}, {"s": "q:m_yun", "t": "연화원의 스물두 번째 관리. 제 이름은 제가 지웠습니다. 흑련회 사람들은 그런 저를 무명이라 부르더군요."}, {"s": "q:m_yeon", "t": "무명이라니… 신원 모를 시신한테나 적는 말이잖아요."}, {"s": "q:m_yeon", "t": "왜요. 등대를 끄고, 장부를 적시고, 그 사람들 이름을 문에 바치고. 왜요!"}, {"s": "q:m_yun", "t": "바친 게 아닙니다. 돌려보낸 겁니다. 망국의 백성, 흑사단, 등대지기들. 해마다 명부 정리에서 맨 먼저 거둬지는 이름들이지요."}, {"s": "q:m_yun", "t": "그 먹을 십오 년 동안 제 손으로 거뒀습니다. 그래서 밤마다 그 이름들을 몰래 불렀지요. 수경루 물 밑의 행렬이 여태 흩어지지 않은 건 그 덕입니다."}, {"s": "q:m_yun", "t": "그래도 이 세상 어느 장부도 그들을 다시 적어 주지 않습니다. 문 너머에는 지워진 이름이 전부 모여 있습니다. 마지막 문을 열면 데려올 수 있습니다."}, {"s": null, "t": "나는 문 너머에 있는 건 사람이 아니라고 말했다."}, {"s": "q:m_yun", "t": "그럴지도 모르지요. 그래도 아무도 부르지 않는 것보다는 낫습니다. …서희 씨, 출납 장부는 서희 씨가 맡아 주십시오. 셈은 다 맞춰 두었습니다."}, {"s": null, "t": "윤도한이 등을 들고 연못 아래 돌계단으로 내려갔다. 물이 그의 발목과 무릎과 어깨를 차례로 삼켰다."}, {"s": "q:m_yeon", "t": "안 돼요! 출납관님! 거기 서요, 출납관님!"}, {"s": null, "t": "연서희가 물속으로 뛰어들려 했다. 나는 연서희의 팔을 붙잡아 끌어안았다. 연서희가 내 팔을 마구 때리며 몸부림쳤다."}, {"s": "q:m_yeon", "t": "놔요! 놔 줘요…! 아직 못 물어본 게 많아요…! 출납관님, 대답해요…!"}, {"s": null, "t": "등불이 물 밑에서 한참 흔들렸다. 이윽고 그 불이 스르르 꺼졌다. 연못이 다시 잔잔해졌다."}, {"s": null, "t": "연서희가 물가에 털썩 주저앉았다. 쥔 손이 멈추지 않고 덜덜 떨렸다."}, {"s": null, "t": "나는 연서희의 어깨에 겉옷을 덮어 주었다. 정청으로 돌아가면 안신탕부터 달여 먹여야겠다고 생각했다."}]'::jsonb where quest_id = 'mq_lamp_shadow' and step = 4 and md5(need::text) = md5('{"at": ["sealed_garden"], "tasks": [{"n": 1, "r": ["sealed_garden"], "t": "travel"}, {"n": 1, "r": ["sealed_garden"], "t": "win", "rank": "guardian"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_lamp_shadow'' and step = 4 and md5(need::text)'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "정청 뒤뜰에서 연서희가 출납 장부를 무릎에 얹고 앉아 있었다. 장부는 마지막 장까지 셈이 정확히 맞았다."}, {"s": null, "t": "나는 달여 온 안신탕을 건네며 마시라고 했다."}, {"s": "q:m_yeon", "t": "…안신탕이네요. 고마워요. 손이 계속 떨려서 붓을 못 들겠더라고요."}, {"s": null, "t": "연서희가 사발을 두 손으로 감싸 쥐었다. 한 모금 마시고 나서야 숨을 길게 내쉬었다."}, {"s": "q:m_yeon", "t": "십 년을 같이 일했어요. 제가 처음 정청에 온 날, 장부 칸 나누는 법을 가르쳐 준 사람이에요."}, {"s": "q:m_yeon", "t": "첫날 제가 밥을 거르니까 주먹밥을 쥐여 줬어요. 제가 {이름} 님한테 줬던 그 주먹밥요. …그것도 그 사람한테 배운 거예요."}, {"s": null, "t": "연서희가 붓을 들어 출납 장부 맨 끝 빈칸을 한참 내려다보았다. 끝내 아무것도 적지 못했다."}, {"s": null, "t": "발소리가 났다. 한설이 서류 묶음 하나를 들고 뒤뜰로 나왔다. 묶음을 말없이 연서희 무릎 위에 놓았다."}, {"s": "night_office:han", "t": "조사원이 처음 올린 보고서다. 서랍에 따로 묶어 둔 거다."}, {"s": "night_office:han", "t": "서희, 네 첫 보고서도 그 밑에 있다. 칸 나눔이 출납관 것과 똑같더군. 그 사람이 가르친 건 그 칸이다. 다른 건 가르치지 않았다."}, {"s": null, "t": "연서희가 묶음을 끌어안고 고개를 숙였다. 어깨가 한참 들썩였다. 한설은 그 곁에 서서 붓을 닦았다. 이번에는 빠르게 닦았다."}, {"s": null, "t": "도제조 백운서가 회랑 끝에서 천천히 걸어 나왔다. 왼손 약지에 밴 먹 자국이 등불에 검게 비쳤다."}, {"s": "night_office:baek", "t": "서희. 그를 쫓을 사람은 이 사람이다. 너는 이 사람을 맡아라. 그게 네 일이다."}, {"s": "q:m_yeon", "t": "…네, 도제조님. 저 아직 담당 서기관이에요. 조사원 님 곁을 떠나지 않아요."}, {"s": "q:m_yeon", "t": "그가 남긴 흔적을 거꾸로 따라가요. 처음 장부가 젖은 곳부터요. 쫓아가서 데려와야 해요. 붉은 인장도, 그 사람도요."}, {"s": "q:m_yeon", "t": "이제 잿빛 들녘과 백지교, 폐쇄된 연화원, 귀죽림에서 단서를 찾아 주세요."}]'::jsonb where quest_id = 'mq_lamp_shadow' and step = 5 and md5(need::text) = md5('{"at": ["hq_yard"], "give": {"calm_brew": 1}, "tasks": [{"n": 1, "t": "craft", "items": ["calm_brew"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_lamp_shadow'' and step = 5 and md5(need::text)'; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "네 곳의 단서가 하나로 모였다. 장부를 적신 들녘의 물, 백지교에 띄운 명부, 연화원의 돌계단, 귀죽림에 묻어 둔 등이 차례로 놓였다."}, {"s": "night_office:mo", "t": "연화원 계단은 지맥의 뿌리로 이어져요. 그 아래는 흑조 균열, 그리고… 구중 봉연."}, {"s": "night_office:han", "t": "그는 정청 인장을 쓰고 붉은 인장을 가져갔다. 봉연의 마지막 문은 붉은 인장으로만 잠긴다. 그것으로 문을 열 수도, 닫을 수도 있다는 뜻이다."}, {"s": "night_office:baek", "t": "길은 별이 안다. 무극 관성대로 가라. 천명원에 서신을 보내 두었다."}, {"s": "q:m_yeon", "t": "출납 장부 맨 뒷장에 한 줄이 더 있었어요. 「구중 봉연, 아홉째 문 앞에서 기다리겠습니다.」"}, {"s": "q:m_yeon", "t": "기다린다면 가 줘야죠. 그리고 데려와야죠. 인장이든, 사람이든."}, {"s": null, "t": "연서희가 장부를 덮었다. 손은 더 이상 떨리지 않았다."}, {"s": null, "t": "연서희가 내 소매 끝을 한 번 잡았다가 놓았다."}, {"s": "q:m_yeon", "t": "같이 가 줄 거죠. 끝까지요."}, {"s": null, "t": "나는 끝까지 가겠다고 했다."}]'::jsonb where quest_id = 'mq_lamp_shadow';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "무극 관성대 꼭대기에서 혼천의가 저절로 돌고 있었다. 끼리릭, 끼리릭, 놋쇠 고리가 맞물리는 소리가 밤하늘로 올라갔다."}, {"s": null, "t": "북쪽 하늘의 아홉 별이 하나씩 빛을 잃는 중이었다. 별 하나가 꺼질 때마다 혼천의 고리 하나가 덜컥 멈췄다."}, {"s": null, "t": "혼천의 아래 돗자리에 웅크리고 있던 관측관 하나가 부스스 일어났다. 눈 밑이 거뭇했다."}, {"s": "mandate_court:seo", "t": "아, 오셨군요. 졸려 보이나요? 사실은 사흘째 못 잤어요. 별이 꺼지는 순서가 등대가 꺼진 순서랑 똑같아요. 남은 별은 하나예요."}, {"s": null, "t": "서이연이 하품을 하다가 내 허리춤을 보고 눈을 크게 떴다."}, {"s": "mandate_court:seo", "t": "그 노리개… 등대 불씨죠? 별 하나가 아직 버티는 까닭을 알겠네요. 그 불이 아직 꺼지지 않았으니까요."}, {"s": null, "t": "태사령 하후정이 말없이 별 지도 한 장을 상 위에 폈다. 눈은 감은 채였다. 정청에서 함께 올라온 백운서가 그 곁에 서서 지도를 내려다보았다."}, {"s": "night_office:baek", "t": "태사령은 예언을 입에 담지 않는다. 대신 지도를 그린다. 그거면 충분하다."}, {"s": "q:m_yeon", "t": "지도 끝이 구중 봉연이네요. 그런데 길 가운데가 비어 있어요."}, {"s": "mandate_court:seo", "t": "빈 길을 채우려면 별모래가 있어야 해요. 백옥 천문탑에서 성진사를 세 줌만 담아 와 주세요. 탑 별빛을 먹은 모래라, 그걸 뿌리면 빈 길이 그려질 거예요."}, {"s": "mandate_court:seo", "t": "제가 가면 좋겠지만, 탑 계단에서 졸다가 굴러떨어진 적이 있어서요. 태사령께서 다시는 혼자 보내지 않으세요."}, {"s": "night_office:baek", "t": "다녀오너라. 이번이 마지막 장부다."}]'::jsonb where quest_id = 'mq_nine_gates' and step = 1 and md5(need::text) = md5('{"at": ["star_observatory"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nine_gates'' and step = 1 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "서이연이 내가 담아 온 성진사를 지도 위에 흩뿌렸다. 모래알 하나하나가 작은 별처럼 반짝였다."}, {"s": null, "t": "모래알이 스스로 데굴데굴 구르기 시작했다. 사르르 사르르 소리를 내며 지도의 빈 길로 모여들었다."}, {"s": null, "t": "모래가 지나간 자리마다 은빛 선이 남았다. 손가락을 대자 선이 서늘했고, 은은한 쇠 냄새가 났다. 연서희가 숨을 죽이고 그 선을 따라 손가락을 옮겼다."}, {"s": "mandate_court:seo", "t": "지맥의 뿌리, 흑조 균열, 그리고 봉연. 길은 하나뿐이에요. 돌아오는 길은… 안 그려지네요."}, {"s": "q:m_yeon", "t": "돌아오는 길은 우리가 그리면 돼요."}, {"s": null, "t": "눈을 감고 있던 하후정이 천천히 눈을 떴다. 나를 한 번, 연서희를 한 번 보았다."}, {"s": "mandate_court:hahu", "t": "붉은 인장은 제자리에 있을 때 빛난다. 손에 쥔 자에게서는 빛나지 않는다."}, {"s": "mandate_court:seo", "t": "…태사령께서 입을 여셨네. 십 년 만에 처음이에요."}, {"s": null, "t": "서이연의 졸린 눈이 처음으로 동그랗게 커졌다. 하후정은 다시 눈을 감았다."}, {"s": "mandate_court:seo", "t": "흑조 균열에 역천 표류체가 모여들고 있어요. 문이 열리며 밀려 나온 것들이에요. 둘만 치워도 아래로 내려갈 길이 열릴 거예요."}]'::jsonb where quest_id = 'mq_nine_gates' and step = 2 and md5(need::text) = md5('{"at": ["star_observatory"], "give": {"star_sand": 3}, "tasks": [{"n": 1, "r": ["white_tower"], "t": "travel"}, {"n": 3, "r": ["white_tower"], "t": "gather", "items": ["star_sand"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nine_gates'' and step = 2 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "흑조 균열의 검은 물이 거꾸로 하늘을 향해 흘렀다. 물줄기가 머리 위로 솟아 어둠 속으로 사라졌다."}, {"s": null, "t": "물방울이 아래로 떨어지지 않고 위로 톡톡 튀어 올랐다. 손바닥을 펴자 물이 손등을 타고 거꾸로 기어올랐다. 연서희가 놀라 소매를 털었다."}, {"s": null, "t": "표류체가 쉬익 하고 물줄기를 타고 내려왔다. 나는 등롱 노리개의 불빛을 앞세워 그 몸통을 베었다. 둘째 표류체가 흩어지자 균열 바닥에서 무언가 반짝였다. 정청 출납 장부의 낱장이었다."}, {"s": "q:m_yeon", "t": "그가 떨어뜨린 거예요. 일부러요. 길을 알려 주려고."}, {"s": null, "t": "낱장에는 숫자만 적혀 있었다. 망국 백성 사천, 흑사단 이백셋, 수향 뱃사람 열하나, 등대지기 여덟이었다."}, {"s": "q:m_yeon", "t": "다 셌어요. 한 사람도 빠짐없이. …이렇게까지 셀 줄 아는 사람이, 왜."}, {"s": null, "t": "나는 셀 줄 알아서라고 답했다."}, {"s": "q:m_yeon", "t": "…그렇네요. 아무도 세지 않으니까, 혼자 세다가 여기까지 온 거네요."}, {"s": null, "t": "연서희가 낱장을 접어 품에 넣었다. 품에서 대나무 잎에 싼 것을 꺼내 반으로 갈랐다. 보리 주먹밥이었다."}, {"s": "q:m_yeon", "t": "처음 왔던 날 기억나요? 그날 드린 주먹밥이요. 내려가기 전에 먹어 둬요. 봉연에선 밥 먹을 짬이 없을 거예요."}, {"s": null, "t": "우리는 거꾸로 흐르는 물소리 아래 나란히 앉아 주먹밥을 먹었다. 소금 간이 그날처럼 짭짤했다."}, {"s": "q:m_yeon", "t": "봉연은 오래 내려가야 해요. 쓰러져도 다시 일어날 수 있게 회생 부적을 한 장 만들어 품고, 원정을 꾸려 구중 봉연 끝까지 내려가요. 그 사람이 아홉째 문 앞에서 기다린다고 했으니까요."}]'::jsonb where quest_id = 'mq_nine_gates' and step = 3 and md5(need::text) = md5('{"at": ["black_tide_rift"], "tasks": [{"m": ["m_rift"], "n": 2, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nine_gates'' and step = 3 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "사슬이 천장에서 바닥까지 늘어져 있었다. 내려갈수록 소리가 사라졌다. 발소리도, 숨소리도 들리지 않았다."}, {"s": null, "t": "나는 입을 열어 연서희의 이름을 불러 보았다. 목이 울리는 것은 느껴졌지만 아무 소리도 나지 않았다."}, {"s": null, "t": "연서희가 놀란 얼굴로 나를 돌아보았다. 연서희의 입도 움직였지만 소리는 없었다. 연서희가 내 손을 더듬어 꼭 잡았다. 우리는 손을 잡은 채 한 계단씩 내려갔다."}, {"s": null, "t": "지나온 문들이 차례로 보였다. 종이 걸린 첫 문, 붉은 실이 끊어진 둘째 문, 비늘이 돌아간 셋째 문, 꺼진 등대 불빛이 비친 다섯 문이 있었다."}, {"s": null, "t": "아홉째 문 앞에 이르자 소리가 한꺼번에 돌아왔다. 귀가 먹먹하게 울렸다."}, {"s": "q:m_yeon", "t": "여덟 개가 열렸어요. 남은 건 하나."}, {"s": null, "t": "아홉째 문 앞을 사슬을 끊어 내는 거대한 그림자가 막고 서 있었다. 그 너머 문턱에 등 하나가 놓여 있었다."}, {"s": null, "t": "등 곁 어둠 속에서 윤도한이 걸어 나왔다. 손에 든 장부가 젖어 있지 않았다."}, {"s": "q:m_yun", "t": "와 주셨군요. 서희 씨도."}, {"s": null, "t": "연서희가 잡고 있던 내 손을 더 세게 쥐었다. 손바닥이 땀에 젖어 있었다."}, {"s": "q:m_yun", "t": "사슬 끊는 자가 문을 붙들고 있습니다. 저것이 사슬을 다 끊으면 문은 스스로 열립니다. 제가 인장을 쓸 필요도 없이요. …막고 싶으시면 막아 보십시오."}, {"s": "q:m_yeon", "t": "막을 거예요. 막고, 출납관님도 데려갈 거예요."}, {"s": "q:m_yeon", "t": "저 그림자는 문턱 가까이에서만 몸을 드러내요. 봉연 깊은 데로, 답사 지도 셋째 칸 안쪽까지 내려가 탐색해야 마주칠 거예요."}]'::jsonb where quest_id = 'mq_nine_gates' and step = 4 and md5(need::text) = md5('{"at": ["sealed_abyss"], "tasks": [{"n": 1, "t": "craft", "items": ["revival_charm"]}, {"n": 1, "t": "expedition"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nine_gates'' and step = 4 and md5(need::text) '; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "사슬 끊는 자가 팔을 휘두르자 사슬이 채찍처럼 쩌렁 울렸다. 나는 사슬을 피해 몸을 낮추고 그 품으로 파고들었다."}, {"s": null, "t": "마지막 일격에 사슬 끊는 자가 무너졌다. 끊긴 사슬들이 와르르 한꺼번에 바닥에 쏟아졌다. 문이 멈췄다. 반쯤 열린 채였다."}, {"s": null, "t": "문틈 너머에서 수많은 목소리가 이름을 불렀다. 누구의 이름도 아니고, 누구의 이름이기도 한 소리였다."}, {"s": "q:m_yun", "t": "들리지요. 저들이 지워진 사람들입니다. 저 안에서 기다리고 있습니다."}, {"s": null, "t": "나는 저건 이름을 먹는 소리라고 말했다."}, {"s": "q:m_yun", "t": "…압니다. 처음부터 알았는지도 모르지요. 그래도 문을 닫으면, 저들은 영영 아무도 아닌 채로 남습니다."}, {"s": "q:m_yeon", "t": "출납관님이 셌잖아요. 사천, 이백셋, 열하나, 여덟. 장부에 남았어요. 아무도 아닌 게 아니에요."}, {"s": "q:m_yeon", "t": "명부 정리도, 먹 거두기도 이제 알아요. 돌아가면 거둔 이름도 숫자로라도 남기게 할게요. 출납관님이 그랬던 것처럼요."}, {"s": "q:m_yun", "t": "…서희 씨는 정말 끝까지 정확하시군요. 인장은 아직 못 드립니다. 문을 닫는 법을 모르시지 않습니까. 문이 열린 길을 거꾸로 맞춰 오십시오. 그러면 드리지요."}, {"s": "q:m_yeon", "t": "이제 지맥의 뿌리와 흑조 균열, 백옥 천문탑, 구중 봉연에서 단서를 찾아 주세요. 기다려요, 출납관님. 금방 와요."}]'::jsonb where quest_id = 'mq_nine_gates' and step = 5 and md5(need::text) = md5('{"at": ["sealed_abyss"], "tasks": [{"n": 1, "r": ["sealed_abyss"], "t": "win", "rank": "guardian"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''mq_nine_gates'' and step = 5 and md5(need::text) '; end if; end $u$;
update public.world_quests set epilogue = '[{"s": null, "t": "네 곳의 단서가 맞물리자 문 앞 바닥에 아홉 겹 봉인식이 떠올랐다. 처음 그 밤, 누군가 사당에서 거꾸로 돌렸던 바로 그 식이었다."}, {"s": "q:m_yun", "t": "맞습니다. 그게 닫는 법입니다. 열 때와 똑같이, 반대로."}, {"s": null, "t": "윤도한이 품에서 붉은 인장을 꺼냈다. 인장은 그의 손에서 빛나지 않았다."}, {"s": "q:m_yun", "t": "인장은 서희 씨가 찍으십시오. 저는 문 안쪽에서 빗장을 잡겠습니다. 바깥에서만 잠그면 저것들이 다시 밀고 나올 테니까요."}, {"s": "q:m_yeon", "t": "안 돼요. 같이 나가요. 장부에 출납관님 이름 다시 적을게요. 제 손으로요."}, {"s": null, "t": "나는 윤도한의 소매를 붙잡았다. 윤도한이 내 손등을 가만히 두드리고 손가락을 하나씩 떼어 냈다."}, {"s": "q:m_yun", "t": "조사원 님, 운임 장부는 서희 씨한테 넘겨 두었습니다. 셈은 다 맞습니다."}, {"s": "q:m_yun", "t": "그럼 적어 주십시오. 윤도한. 그 이름이면 충분합니다. 무명은 여기 두고 가지요."}, {"s": null, "t": "윤도한이 문 안쪽으로 걸어 들어갔다. 연서희가 울면서 인장을 찍었다."}, {"s": null, "t": "붉은 빛이 아홉 문을 차례로 건너갔다. 마지막 문이 소리 없이 닫혔다. 문 안쪽에서 등불 하나가 끝까지 흔들렸다."}, {"s": null, "t": "우리는 정청으로 돌아와 붉은 인장을 제자리에 두었다. 인장이 그제야 붉게 빛났다. 도제조 백운서가 장부에 붓을 들었다."}, {"s": "night_office:baek", "t": "출납관 윤도한. 구중 봉연, 아홉째 문 안쪽 근무. …지운 자리 없이 적어라. 올해 먹 거두기는 하지 않는다."}, {"s": "q:m_yeon", "t": "네. 또박또박, 끝까지 눌러서요."}, {"s": null, "t": "연서희가 붓을 받아 「윤도한」 세 글자를 적었다. 마지막 획을 끝까지 눌러 그었다. 나는 그 곁에서 먹을 갈았다."}, {"s": null, "t": "그 시각, 봉연 가장 깊은 곳에서는 닫힌 문 아래 어둠 속에서 구중 봉주가 천천히 숨을 고르고 있었다. 문틈으로 스며드는 지워진 이름들을 하나씩 삼키고 있었다."}, {"s": null, "t": "봉주가 숨을 들이쉴 때마다 사슬이 한 번씩 울었다. 사흘에 한 번, 혹은 나흘에 한 번이었다. 문은 다시 흔들릴 것이었다."}]'::jsonb where quest_id = 'mq_nine_gates';
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "구중 봉연의 마지막 문이 닫히고 나서도 물소리는 그치지 않았다. 졸졸, 문 아래 어딘가에서 물이 새어 나가고 있었다."}, {"s": null, "t": "나는 그 소리를 따라 내려갔다. 봉연 아래로 검은 물길이 하나 더 나 있었고, 그 끝에 빈 나룻배 한 척이 매여 있었다."}, {"s": null, "t": "나는 그 배에 올랐다. 노를 젓지 않았는데도 배가 스르르 물길을 따라 미끄러졌다."}, {"s": null, "t": "한참 뒤에 뱃머리가 바닥에 닿았다. 물이 아니라 재 위에 닿은 것처럼 아무 소리도 나지 않았다."}, {"s": null, "t": "나는 뱃전 밖으로 손을 내밀어 물을 떠 보았다. 물은 차지도 미지근하지도 않았다."}, {"s": null, "t": "손가락 사이로 흘러내린 물방울이 바로 떨어지지 않았다. 물방울은 공중에서 잠깐 머뭇거리다가 뚝 떨어졌다."}, {"s": null, "t": "선창 위로 비늘을 이은 지붕들이 보였다. 지붕 아래에서 등불이 하나, 둘 켜졌다."}, {"s": null, "t": "문간마다 사람들이 나와 이쪽을 보았다. 손등에도 목덜미에도 비늘이 돋아 등불에 반짝반짝 빛났다."}, {"s": null, "t": "아무도 다가오지 않았다. 아이 하나가 어른 옷자락 뒤로 쏙 숨었다."}, {"s": null, "t": "그중 한 여자가 사람들 사이를 헤치고 선창까지 내려왔다. 여자는 내 허리춤에 달린 인장을 한참 들여다보았다."}, {"s": "q:g_yeoul", "t": "…야행국 인장이네. 봉연을 건너온 사람은 정말 오랜만이야."}, {"s": null, "t": "나는 저도 모르게 한 걸음 물러섰다. 여자가 그것을 보고 소매를 걷어 보였다."}, {"s": null, "t": "왼쪽 손목부터 팔꿈치까지 푸른 비늘이 덮여 있었다."}, {"s": "q:g_yeoul", "t": "놀라지 마. 여기선 다 이래. 나는 여울이야. 예전엔 너처럼 조사원이었어."}, {"s": null, "t": "나는 이런 섬이 있다는 말은 들어 본 적이 없다고 했다."}, {"s": null, "t": "여울이 웃었다. 웃음 끝이 조금 떨렸다."}, {"s": "q:g_yeoul", "t": "그렇겠지. 야행국이 지도에서 이 섬을 지웠으니까."}, {"s": null, "t": "나는 그럼 여기가 어디냐고 물었다."}, {"s": "q:g_yeoul", "t": "반요촌. 지워진 사람들이 사는 마을이야. 너는 지금 지도에 없는 데 서 있는 거고."}, {"s": null, "t": "여울은 마을 안쪽에서 가장 큰 집을 턱으로 가리켰다. 문간에 노인 하나가 쪼그려 앉아 있었다. 노인의 망치 소리가 똑, 똑 울렸다."}, {"s": "q:g_yeoul", "t": "촌장님이 너를 보자고 하실 거야. 바깥 사람이 오면 늘 먼저 만나시거든. 이름을 물으실 테니까 천천히, 또박또박 말해 줘."}, {"s": null, "t": "나는 왜 또박또박 말해야 하느냐고 물었다."}, {"s": "q:g_yeoul", "t": "촌장님 귀에선 이름이 자꾸 흘러내리거든. 한 번에 또렷하게 들어야 붙잡으셔."}, {"s": null, "t": "여울이 지붕 하나를 올려다보았다. 비늘 몇 장이 빠진 자리로 등불 빛이 숭숭 새어 나왔다."}, {"s": "q:g_yeoul", "t": "그 전에 부탁이 하나 있어. 촌장님은 요즘 지붕 이을 비늘이 모자라 걱정이셔. 비늘이 빠진 집엔 밤마다 갈대숲 바람이 들어와."}, {"s": null, "t": "나는 그 비늘을 어디서 구하느냐고 물었다."}, {"s": "q:g_yeoul", "t": "잿빛 갈대숲의 갈대 물귀신들이 떨어뜨려. 세 마리쯤 쓰러뜨리면 반요 비늘 두 개는 나올 거야."}, {"s": null, "t": "나는 여울이 직접 가지 않는 까닭을 물었다. 여울이 손목의 비늘을 엄지로 문질렀다."}, {"s": "q:g_yeoul", "t": "내 이름은 반쯤 번졌어. 물귀신들은 번진 이름을 귀신같이 알아채고 불러 대. 바깥 이름이 또렷한 네가 가는 게 덜 위험해."}, {"s": "q:g_yeoul", "t": "처음 온 손님한테 일부터 시켜서 미안해. 대신 다녀오면 촌장님이 네 이름을 제일 먼저 기억해 주실 거야. 이 섬에선 그게 제일 큰 인사야."}, {"s": null, "t": "나는 다녀오겠다고 했다. 여울이 그제야 어깨에서 힘을 조금 뺐다."}]'::jsonb where quest_id = 'gq_1' and step = 1 and md5(need::text) = md5('{"at": ["banyo_village"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_1'' and step = 1 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "갈대 물귀신들은 물 밑에서 사람 목소리를 흉내 내며 기어올랐다. 나는 대꾸하지 않고 셋을 차례로 쓰러뜨렸다."}, {"s": null, "t": "물귀신이 쓰러질 때마다 철썩 물보라가 일었다. 물보라 속에서 비늘이 반짝 튀어 올랐다."}, {"s": null, "t": "나는 반요 비늘 두 개를 챙겨 반요촌으로 돌아왔다. 촌장은 아까 그 문간에서 문패를 고쳐 달고 있었다."}, {"s": null, "t": "문패 하나에 이름이 두 개씩 적혀 있었다. 이웃집 문패도, 그 옆집 문패도 그랬다."}, {"s": null, "t": "노인이 망치를 내려놓고 나를 올려다보았다. 눈가가 짓물러 있었지만 목소리는 차분했다."}, {"s": "q:g_mukho", "t": "…손님이군. 미안하네. 자네 이름을 듣기 전에 내 이름부터 확인해야 해서."}, {"s": null, "t": "노인이 문패 위쪽 이름을 손가락으로 짚었다. 먹이 번져 첫 글자가 보이지 않았다."}, {"s": "q:g_mukho", "t": "어제는 이 글자를 알았네. 오늘은 모르겠어. 내일은 둘째 글자를 잊겠지."}, {"s": null, "t": "나는 무슨 글자였는지 짐작도 안 가느냐고 물었다."}, {"s": "q:g_mukho", "t": "짐작이야 가지. 하지만 짐작으로 제 이름을 부르면 그건 남의 이름일세."}, {"s": null, "t": "노인은 손가락을 아래쪽 이름으로 옮겼다. 그 이름은 먹이 아직 진했다."}, {"s": "q:g_mukho", "t": "그래서 여기선 이름을 하나 더 지어 문패에 같이 적어 두네. 위는 바깥에서 받은 이름, 아래는 이 섬에서 지은 이름이야. 바깥 이름이 다 번져도 아래 이름으로 불리면 사람으로 남을 수 있거든. 나는 아래 이름으로 묵호라고 불리네."}, {"s": null, "t": "묵호는 문패에서 손을 떼고 나를 똑바로 보았다."}, {"s": "q:g_mukho", "t": "자, 이제 자네 차례일세. 이름이 뭔가."}, {"s": null, "t": "나는 여울의 당부대로 내 이름을 한 글자씩 끊어 천천히 말했다."}, {"s": null, "t": "묵호가 입속으로 내 이름을 두어 번 굴려 보았다. 이윽고 고개를 끄덕였다."}, {"s": "q:g_mukho", "t": "{이름}. 소리가 또렷하군. 바깥 이름이 아직 하나도 안 번졌구먼."}, {"s": null, "t": "나는 갈대숲에서 가져온 비늘 두 개를 내밀었다. 묵호는 비늘을 받아 들고 등불에 비추어 한참 들여다보았다."}, {"s": "q:g_mukho", "t": "갈대숲 물귀신들은 밤마다 마을 우물까지 올라와. 사람을 끌어가진 않지만… 끌려가고 싶은 사람이 생기거든."}, {"s": "q:g_mukho", "t": "이것도 누군가의 살갗이었겠지. 지붕에 잘 이어 주겠네."}, {"s": null, "t": "묵호가 무릎을 짚고 일어서다 휘청했다. 나는 얼른 노인의 팔을 붙들었다."}, {"s": "q:g_mukho", "t": "허, 고맙네. 젊은 팔이 좋구먼. 온 김에 저 문패 좀 바로 걸어 주겠나. 내 손이 자꾸 비뚤게 거네."}, {"s": null, "t": "나는 문패를 받아 못에 걸었다. 묵호가 뒤로 두 걸음 물러나 고개를 이리저리 기울였다."}, {"s": "q:g_mukho", "t": "조금 왼쪽. 옳지, 됐네. 바르게 걸린 걸 보니 내 이름도 오늘은 안 떨어지겠어."}, {"s": null, "t": "묵호는 비늘을 품에 넣고, 마을 끝에서 연기가 오르는 쪽을 가리켰다."}, {"s": "q:g_mukho", "t": "여울이 마을 끝 화로 곁에서 기다릴 걸세. 그 사람은 바깥 사람이 오면 꼭 그 불 앞에서 할 말이 있어. 밤이 깊거든 가 보게."}, {"s": "q:g_mukho", "t": "빈속으로 가지는 말고. 화로에 얹힌 갈대 뿌리 죽도 한 그릇 얻어먹게."}]'::jsonb where quest_id = 'gq_1' and step = 2 and md5(need::text) = md5('{"at": ["banyo_village"], "give": {"banyo_scale": 2}, "tasks": [{"m": ["gw_reed_1"], "n": 3, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_1'' and step = 2 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "밤이 깊었다. 마을 끝 화로 앞에서 누군가 낮게 노래를 불렀다. 떠나는 이를 배웅하는 노래였다."}, {"s": null, "t": "여울은 화로 곁에 무릎을 세우고 앉아 있었다. 노래가 끝나자 여울은 장작 하나를 불 속에 밀어 넣었다. 탁, 불똥이 튀었다."}, {"s": "q:g_yeoul", "t": "왔어? 앉아. 촌장님이 죽 먹으라고 하셨지? 그분은 손님만 오면 그 말부터 하셔."}, {"s": null, "t": "여울이 냄비에서 죽을 떠 내게 건넸다. 잿빛 죽에서 갈대 뿌리 냄새가 났다."}, {"s": null, "t": "한 숟갈 떠먹자 속이 뜨끈해졌다. 나는 생각보다 맛이 좋다고 했다."}, {"s": "q:g_yeoul", "t": "거짓말이 서툴구나. 처음엔 다들 재 맛이 난다고 해. 사흘만 먹어 봐. 바깥 쌀죽이 싱거워질걸."}, {"s": null, "t": "노래하던 사람들이 하나둘 집으로 돌아갔다. 화로 곁에는 여울과 나만 남았다."}, {"s": "q:g_yeoul", "t": "여기엔 배웅 노래밖에 없어. 맞이하는 노래는 아무도 몰라."}, {"s": null, "t": "나는 숟가락을 내려놓고, 여기 사람들은 왜 바깥으로 돌아가지 않느냐고 물었다."}, {"s": "q:g_yeoul", "t": "돌아갈 데가 없으니까. 침식이 여든을 넘으면 야행국은 「귀허 이송」을 했어. 반쯤 요괴가 된 사람을 배에 태워 이 섬으로 보냈지."}, {"s": "q:g_yeoul", "t": "여기선 그런 사람을 반요라고 불러. 요기가 명줄을 갉으면 처음엔 제 이름이 남의 이름처럼 들리고, 나중엔 누가 불러 줘야 잠깐 돌아와. 다 끊기면 요괴가 되고."}, {"s": null, "t": "화로 불꽃이 한 번 튀었다. 여울이 손목의 비늘을 엄지로 문질렀다. 오래된 버릇 같았다."}, {"s": "q:g_yeoul", "t": "나도 그 배를 탔어. 아니, 처음엔 그 배를 보내는 쪽이었지."}, {"s": null, "t": "여울은 거기서 말을 끊었다. 나는 무슨 뜻이냐고 묻지 않았다. 대신 장작 하나를 불 속에 더 넣었다."}, {"s": null, "t": "불을 보던 여울이 피식 웃었다."}, {"s": "q:g_yeoul", "t": "안 묻네. 바깥 조사원들은 다 캐묻던데."}, {"s": null, "t": "나는 말하고 싶을 때 말해 달라고 했다."}, {"s": "q:g_yeoul", "t": "…고마워. 그런 말 들은 거, 오랜만이야."}, {"s": null, "t": "여울은 무릎을 짚고 일어섰다. 옷자락에 묻은 재를 탁탁 털었다."}, {"s": "q:g_yeoul", "t": "오늘은 여기까지 하자. 객방에 자리 펴 뒀어. 머리맡에 종이 한 장이 있을 거야."}, {"s": null, "t": "나는 무슨 종이냐고 물었다."}, {"s": "q:g_yeoul", "t": "이 섬에선 가끔 남의 기억이 종이가 되어 굴러다녀. 누군가 읽어 줘야 끝나는 기억이야."}, {"s": "q:g_yeoul", "t": "이름이 번진 사람이 읽으면 글자도 같이 번져 버려. 너처럼 바깥 이름이 또렷한 사람이 읽어 줘야 해. 내가 너를 붙잡아 두는 까닭이 그거야. 미안하지만."}, {"s": null, "t": "나는 바깥이 왜 이 섬을 지웠는지 나도 알고 싶다고 했다. 여울이 잠깐 나를 내려다보았다."}, {"s": "q:g_yeoul", "t": "그럼 우린 같은 걸 찾는 셈이네."}, {"s": "q:g_yeoul", "t": "내일은 잿빛 갈대숲 안쪽으로 들어가 봐. 요즘 그 안에서 누가 밤새 이름을 불러. 물귀신들이 우물까지 올라오는 것도 그 소리 때문이야."}, {"s": "q:g_yeoul", "t": "이름을 부르는 소리가 들리면 대답하지 마. 무슨 이름이든."}]'::jsonb where quest_id = 'gq_1' and step = 3 and md5(need::text) = md5('{"at": ["banyo_village"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_1'' and step = 3 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "객방은 좁았다. 비늘 지붕 틈으로 별빛 대신 등불 빛이 조금 들어왔다."}, {"s": null, "t": "머리맡에 여울이 말한 종잇조각이 놓여 있었다. 종이는 물에 젖은 것처럼 축축했다."}, {"s": null, "t": "내가 종이를 펼치자 글씨가 내 목소리로 들려왔다. 입을 다물고 있는데도 목 안쪽이 웅웅 울렸다."}, {"s": "q:g_memory", "t": "그날 침식은 아흔둘이었다. 거울을 보지 않아도 알았다. 숨을 쉴 때마다 목 안쪽이 서늘했다."}, {"s": "q:g_memory", "t": "동료가 정화 부적을 세 장이나 붙여 주었다. 네 번째 부적을 꺼낼 때 그의 손이 떨렸다. 나는 그 손을 잡아 내렸다."}, {"s": "q:g_memory", "t": "이송 명부에 내 이름을 적은 건 나였다. 내 글씨는 끝까지 반듯했다."}, {"s": null, "t": "목소리가 멎자 축축하던 종이가 바싹 말랐다."}, {"s": null, "t": "종이 아래쪽에 작은 글씨로 「여울」이라는 이름이 덧붙어 있었다."}, {"s": null, "t": "나는 종이를 접어 품에 넣었다. 화로 쪽에서 배웅 노래가 한 소절만 들리다 그쳤다."}]'::jsonb where quest_id = 'gq_1' and step = 4 and md5(need::text) = md5('{"at": ["banyo_village"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_1'' and step = 4 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "이튿날 아침, 나는 여울의 말대로 잿빛 갈대숲 안쪽으로 들어갔다. 바람도 없는데 갈대가 사락사락 흔들렸다."}, {"s": null, "t": "갈대는 내 키의 두 배쯤 되었다. 이삭마다 재가 앉아, 스칠 때마다 잿가루가 소매에 묻어났다."}, {"s": null, "t": "바스락거리는 소리 사이로 누군가 이름을 불렀다. 처음 듣는 이름이었다."}, {"s": null, "t": "처음 듣는 이름인데도 대답하고 싶어졌다. 「네」 하는 소리가 목구멍까지 올라왔다. 나는 여울의 말을 떠올리고 입술을 꽉 깨물었다."}, {"s": null, "t": "안개 속에서 낡은 나룻배 한 척이 스르르 미끄러져 왔다. 노를 쥔 사공의 손이 반쯤 비쳐 보였다. 손 너머로 갈대가 어른거렸다."}, {"s": null, "t": "사공은 배를 내 앞에 대고 삿갓 아래로 웃어 보였다."}, {"s": "q:g_sagong", "t": "건너가시오? 건너편까지 모셔다 드리지. 값은 안 받소. 이름 하나만 주시오."}, {"s": null, "t": "나는 이름은 줄 수 없다고 잘라 말했다."}, {"s": null, "t": "사공은 노에 턱을 괴고 나를 오래 바라보았다. 혀끝으로 무언가를 맛보듯 입을 달싹였다."}, {"s": "q:g_sagong", "t": "…다들 그 말을 하더군. 그래도 결국엔 다 주고 갔소. {이름}… 그렇게 부르면 돌아보시겠지."}, {"s": null, "t": "사공이 내 이름을 입에 올리자 등골이 오싹했다. 나는 돌아보지 않았다."}, {"s": null, "t": "사공이 노를 멈췄다. 배는 그대로인데 갈대가 쑥쑥 뒤로 흘러갔다. 땅이 나를 배 쪽으로 끌어당기는 것 같았다."}, {"s": null, "t": "나는 발끝에 힘을 주고 버텼다. 품속에서 어젯밤 접어 둔 종이가 바스락거렸다."}, {"s": null, "t": "한참 뒤에 사공이 어깨를 늘어뜨리고 허허 웃었다. 장난이 들킨 아이 같은 얼굴이었다."}, {"s": "q:g_sagong", "t": "됐소. 안 뺏을 테니 겁먹지 마시오. 실은 내가 내 이름을 찾고 싶소."}, {"s": null, "t": "나는 이름을 잃었느냐고 물었다."}, {"s": "q:g_sagong", "t": "잃은 줄도 몰랐소. 손님들 이름을 받다 보니 내 것이 어느 틈에 빠져나갔더구려."}, {"s": null, "t": "사공은 노 끝으로 물 위에 비죽 솟은 말뚝 하나를 가리켰다. 말뚝에 글자가 새겨져 있었지만 반쯤 물에 잠겨 있었다."}, {"s": "q:g_sagong", "t": "내 이름은 저런 말뚝 어딘가에 있소. 물에 잠겨 읽을 수가 없어. 찾아 주면… 건너편 이야기를 해 주지."}, {"s": null, "t": "나는 밤마다 마을까지 들리는 부름 소리가 당신이냐고 물었다."}, {"s": "q:g_sagong", "t": "내가 부르는 게 아니오. 내가 잃은 이름이 나를 찾아 우는 거지. 이름을 찾으면 그 소리도 그칠 거요."}, {"s": "q:g_sagong", "t": "말뚝은 갈대숲 곳곳에 박혀 있소. 네 군데는 뒤져야 할 거요. 갈대 영사 세 타래로 물살을 거르면 잠긴 글자가 떠오를 거요. 영사가 물에 섞인 재를 걸러 내거든."}, {"s": null, "t": "나는 찾아보겠다고 했다. 사공이 삿갓을 살짝 들어 올렸다. 그 아래 눈이 처음으로 웃었다."}]'::jsonb where quest_id = 'gq_2' and step = 1 and md5(need::text) = md5('{"at": ["ash_reeds"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_2'' and step = 1 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 갈대숲을 네 군데 뒤졌다. 말뚝마다 이름이 새겨져 있었고, 대부분 반쯤 물에 잠겨 있었다."}, {"s": null, "t": "물 위로 드러난 글자만 이어 읽으면 이상한 문장이 되었다. 나는 읽다 말고 고개를 저었다."}, {"s": null, "t": "나는 갈대 끝에 맺힌 영사를 세 타래 걷었다. 은빛 실이 손가락에 감기며 차갑게 반짝였다."}, {"s": null, "t": "마지막 말뚝 둘레에 갈대 영사를 감아 물살을 걸렀다. 잿물이 실에 걸러지며 물이 맑아졌다."}, {"s": null, "t": "잠긴 글자들이 하나씩 떠올랐다. 「수향 나루 일번선 사공 □□」까지 읽혔다. 이름 두 글자만은 끝내 떠오르지 않았다."}, {"s": null, "t": "내가 떠오른 글자를 소리 내어 읽자 사공의 몸이 부르르 떨렸다. 사공은 노를 쥔 채 다른 손을 뻗어 말뚝의 글자를 더듬었다."}, {"s": "q:g_sagong", "t": "…수향. 그래, 수향이었지. 나는 나루에서 배를 몰았소."}, {"s": null, "t": "나는 그 나루에서 무엇을 실어 날랐느냐고 물었다."}, {"s": "q:g_sagong", "t": "야행국 사람들이 밤마다 손님을 데려왔지. 얼굴을 천으로 가린 손님들이었소. 손목마다 비늘이 있었고."}, {"s": null, "t": "사공은 말뚝에서 손을 떼고 고개를 숙였다. 목소리가 낮아졌다."}, {"s": "q:g_sagong", "t": "나는 묻지 않았소. 묻지 말라고 웃돈을 받았으니까."}, {"s": null, "t": "사공의 손이 떨렸다. 철썩, 노가 물을 쳤다. 처음으로 배가 앞으로 나아갔다."}, {"s": null, "t": "배가 몇 길 나아가다 멈췄다. 사공은 노를 쥔 제 손을 내려다보았다."}, {"s": null, "t": "손가락이 노 손잡이에 뿌리처럼 박혀 있었다. 사공이 손을 떼려고 몸을 비틀자 노가 끼익끼익 울기만 했다."}, {"s": "q:g_sagong", "t": "…이제 생각나는구려. 건너편은 없소."}, {"s": null, "t": "나는 그게 무슨 말이냐고 물었다."}, {"s": "q:g_sagong", "t": "손님을 다 내려 주고도 이 손이 노를 놓지 않소. 이 손이 쥐고 있는 한 나는 이 물을 못 떠나오."}, {"s": "q:g_sagong", "t": "나를 놓아주시오. 이 노를 쥔 손을 쳐서 떨어뜨려 주시오."}, {"s": null, "t": "나는 그러면 당신이 흩어질 수도 있다고 했다."}, {"s": "q:g_sagong", "t": "알고 있소. 그래도 손님 이름이나 훔치며 떠도는 것보다는 낫지. 부탁이오."}]'::jsonb where quest_id = 'gq_2' and step = 2 and md5(need::text) = md5('{"at": ["ash_reeds"], "tasks": [{"n": 4, "r": ["ash_reeds"], "t": "search"}, {"n": 3, "r": ["ash_reeds"], "t": "gather", "items": ["reed_silk"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_2'' and step = 2 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "사공이 노를 치켜들었다. 휘익, 노 끝이 내 머리 위를 스쳤다. 놓아 달라던 손이 제 뜻과 달리 나를 치고 있었다."}, {"s": null, "t": "나는 몸을 낮추고 노를 쥔 손을 노렸다. 쾅! 내 공격이 닿자 사공의 윤곽이 물보라처럼 흩어지기 시작했다."}, {"s": "q:g_sagong", "t": "그렇지…! 조금만, 조금만 더…!"}, {"s": null, "t": "사공은 흩어지면서도 노를 놓지 않았다. 갈라진 목소리로 말을 이었다."}, {"s": "q:g_sagong", "t": "마지막 손님이 내 아들이었소. 천을 벗기고서야 알았지."}, {"s": "q:g_sagong", "t": "그 애를 여기 내려 주고 나는 돌아가지 않았소. 돌아갈 수가 없었어."}, {"s": null, "t": "흩어지는 윤곽 사이로 노 한 자루가 풍덩 물에 떨어졌다. 나는 물에 뜬 노를 건져 올렸다."}, {"s": null, "t": "노 손잡이에 칼로 새긴 글자 두 개가 있었다. 「한결」이라는 글자였다."}, {"s": null, "t": "나는 사라져 가는 사공에게, 이것이 당신 이름이냐고 물었다."}, {"s": null, "t": "대답 대신 갈대가 한꺼번에 고개를 숙였다. 쏴아, 이삭에 앉은 재가 비처럼 쏟아졌다. 이름을 부르던 소리도 뚝 멎었다."}, {"s": null, "t": "등 뒤에서 철벅철벅 발소리가 났다. 여울이 갈대를 헤치고 서 있었다. 숨이 차서 어깨가 들썩였다."}, {"s": "q:g_yeoul", "t": "괜찮아? 소리가 갑자기 그쳐서 뛰어왔어. 다친 데는?"}, {"s": null, "t": "나는 괜찮다고 했다. 여울은 내 손에 든 노를 보고 잠깐 눈을 감았다."}, {"s": "q:g_yeoul", "t": "그건 아들 이름이야. 한결이는 지금 반요촌에서 나무를 해."}, {"s": "q:g_yeoul", "t": "아버지 얼굴은 기억 못 하는데, 노 젓는 소리가 들리면 아직도 물가에 나가 서 있어."}, {"s": null, "t": "노를 쥔 내 손에 힘이 들어갔다. 나는 이 노를 한결에게 가져다주어야 하지 않느냐고 물었다."}, {"s": "q:g_yeoul", "t": "…그건 내가 할게. 물가에 세워 두면 한결이가 알아서 찾을 거야. 누가 쥐던 건지는 말 안 할래. 그 애가 스스로 알게 되면 그때 이야기할게."}, {"s": null, "t": "여울이 노를 받아 어깨에 걸쳤다. 여울의 몸이 조금 휘청했다. 나는 노 끝을 함께 받쳐 들었다."}, {"s": "q:g_yeoul", "t": "그 사공, 우리 배도 몰았어. 누가 이름을 불러 줬으니 이제야 쉬네."}, {"s": null, "t": "여울은 물가로 걸어가 수면을 내려다보았다. 물이 쪼르륵 소리를 내며 천천히 빠지고 있었다."}, {"s": "q:g_yeoul", "t": "물이 빠지면 종이가 하나 떠오를 거야. 그것도 읽어 줘. 네가 읽어 줘야 그 사람이 정말로 쉬어."}, {"s": null, "t": "여울이 말끝을 흐리며 마을 쪽을 돌아보았다. 눈썹 사이가 좁아졌다."}, {"s": "q:g_yeoul", "t": "그리고… 부탁이 하나 더 있어. 단이라는 아이가 오늘 아침부터 안 보여. 약 상자를 멘 쪼그만 애야."}, {"s": null, "t": "나는 그 아이가 어디로 갔을 것 같으냐고 물었다."}, {"s": "q:g_yeoul", "t": "그 애는 엄마 이야기만 나오면 거꾸로 선 사당에 가. 아무래도 거기 갔을 거야."}, {"s": "q:g_yeoul", "t": "나는 마을 사람들이랑 우물 쪽부터 찾아볼게. 너는 사당 쪽을 봐 줘. 아이 혼자 있기엔 무서운 데야."}]'::jsonb where quest_id = 'gq_2' and step = 3 and md5(need::text) = md5('{"at": ["ash_reeds"], "tasks": [{"m": ["gw_reed_3"], "n": 1, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_2'' and step = 3 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "물이 물러난 자리에 종잇조각 하나가 떠 있었다. 나는 종이를 건져 펼쳤다. 젖었는데도 글씨가 번지지 않았다."}, {"s": null, "t": "글씨에서 삐걱삐걱 노 젓는 소리가 났다. 내 목소리가 그 소리에 실려 흘러나왔다."}, {"s": "q:g_memory", "t": "아들은 배에서 내리기 전에 천을 벗었다. 아버지 손은 차갑네, 하고 웃었다. 비늘이 덮인 제 손이 더 차가웠을 텐데."}, {"s": "q:g_memory", "t": "돌아가는 뱃길에서 나는 노를 놓았다. 배는 섬을 몇 바퀴 돌다가 갈대 사이에 멈췄다."}, {"s": "q:g_memory", "t": "그 뒤로 손님이 올 때마다 건너편까지 데려다주고 싶었다. 건너편이 어디인지 잊은 뒤에도."}, {"s": null, "t": "목소리가 끝나자 노 소리도 그쳤다. 나는 종이를 접어 품에 넣었다."}, {"s": null, "t": "마른 갈대 사이로 언덕 하나가 보였다. 언덕 꼭대기에 기와지붕이 거꾸로 박혀 있었다."}, {"s": null, "t": "여울이 말한 거꾸로 선 사당이었다. 약 상자를 멘 아이가 저 언덕을 혼자 올랐을 것을 생각하자 걸음이 저절로 빨라졌다."}]'::jsonb where quest_id = 'gq_2' and step = 4 and md5(need::text) = md5('{"at": ["ash_reeds"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_2'' and step = 4 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 갈대숲을 지나 언덕을 올랐다. 언덕 위에 거꾸로 선 사당이 있었다."}, {"s": null, "t": "일주문이 거꾸로 박혀 있었다. 기둥 끝은 하늘을 찌르고, 처마는 발밑 흙에 묻혀 있었다."}, {"s": null, "t": "향 연기가 위가 아니라 아래로 흘렀다. 연기는 실뱀처럼 꿈틀거리며 내려와 발목 높이에 고였다."}, {"s": null, "t": "고인 연기를 발로 헤치자 찬물을 휘젓는 느낌이 났다. 연기는 흩어지지 않고 스르르 다시 모였다."}, {"s": null, "t": "내가 법당 안으로 한 걸음 들어서자 머리 위에서 작은 목소리가 들렸다."}, {"s": "q:g_dani", "t": "쉿. 크게 걸으면 스님들이 깨요."}, {"s": null, "t": "고개를 드니 아이 하나가 천장 대들보에 다리를 걸고 거꾸로 매달려 있었다. 등에 멘 약 상자가 아이 몸보다 컸다."}, {"s": null, "t": "아이는 코를 킁킁거리더니 눈을 동그랗게 떴다."}, {"s": "q:g_dani", "t": "바깥 사람이죠? 냄새가 달라요. 바다 냄새가 안 나요."}, {"s": null, "t": "아이는 대들보에서 몸을 휙 뒤집어 사뿐히 내려섰다. 약 상자가 덜컹 소리를 냈다."}, {"s": null, "t": "아이는 상자 끈을 두 손으로 꼭 쥐었다."}, {"s": "q:g_dani", "t": "저는 단이예요. 여기서 태어났어요. 엄마는 의무관이었대요. 이 상자가 엄마 거예요."}, {"s": null, "t": "나는 여울이 너를 찾느라 걱정하고 있다고 했다."}, {"s": "q:g_dani", "t": "…저 또 혼나겠다."}, {"s": null, "t": "나는 혼나지 않게 잘 말해 주겠다고 했다. 단이가 그제야 입꼬리를 조금 올렸다."}, {"s": null, "t": "나는 여기서 무엇을 하고 있었느냐고 물었다. 단이는 고개를 숙이고 발끝으로 바닥에 고인 연기를 휘저었다."}, {"s": "q:g_dani", "t": "엄마 이름이 잊히지 않게 빌러 왔어요. 근데 여기 기도는 다 거꾸로 된대요. 기억해 달라고 빌면 잊힌대요."}, {"s": null, "t": "단이는 법당 구석을 가리켰다. 향들이 모두 머리를 땅에 박고 쓰러져 있었다."}, {"s": "q:g_dani", "t": "향을 바로 세우면 기도도 바로 된대요. 근데 세울 거꾸로 향목은 매달린 동자들 밑에만 떨어져 있어요."}, {"s": null, "t": "나는 동자들이 어디 있느냐고 물었다. 단이가 법당 뒤 처마를 가리켰다. 가리키는 손가락이 바들바들 떨렸다."}, {"s": null, "t": "처마 끝에 작은 그림자들이 거꾸로 대롱대롱 매달려 있었다. 그림자들이 킥킥 웃을 때마다 향목이 툭, 툭 떨어졌다."}, {"s": "q:g_dani", "t": "쟤들이 웃으면 제 이름이 머릿속에서 미끄러져요. 그래서 무서워서 못 줍겠어요."}, {"s": "q:g_dani", "t": "동자들을 세 번만 쫓아 주시고, 향목 세 개만 주워 주세요. 그동안 저는 향 꽂을 자리 닦고 있을게요. 안 도망가요, 약속해요."}, {"s": null, "t": "나는 단이의 머리를 한 번 쓰다듬었다. 단이가 새끼손가락을 내밀었고, 나는 그 손가락에 내 새끼손가락을 걸었다."}]'::jsonb where quest_id = 'gq_3' and step = 1 and md5(need::text) = md5('{"at": ["inverted_shrine"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_3'' and step = 1 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 매달린 동자들을 쫓아내고 그 밑에 떨어진 거꾸로 향목 세 개를 주워 왔다. 동자들이 흩어질 때마다 사당 어딘가에서 들리던 목탁 소리가 하나씩 멎었다."}, {"s": null, "t": "법당에 돌아오니 단이가 소매로 향꽂이를 반들반들하게 닦아 두었다. 단이는 나를 보자 벌떡 일어났다."}, {"s": "q:g_dani", "t": "다 쫓았어요? 안 다쳤어요? 다쳤으면 말해요. 엄마 상자에 고약 있어요."}, {"s": null, "t": "나는 손등이 조금 긁혔다고 했다."}, {"s": null, "t": "단이가 상자를 열고 반요 고약을 손가락으로 듬뿍 떴다. 고약이 내 손등에 닿자 서늘하게 스며들었다."}, {"s": "q:g_dani", "t": "고약은 아끼지 말고 듬뿍 바르랬어요. 아까우면 다음에 또 개면 된대요."}, {"s": null, "t": "그때 법당 앞 연못에서 목소리가 들렸다. 연못에 늙은 승려가 비쳐 합장하고 있었다."}, {"s": null, "t": "연못 밖에는 아무도 없었다. 물그림자만 연못 안에서 홀로 고개를 숙였다."}, {"s": "q:g_juji", "t": "그 아이들도 잊히고 싶어서 여기 온 것이라오."}, {"s": null, "t": "단이가 쪼르르 내 등 뒤로 숨었다. 연못 속 승려는 아이를 보고 눈을 가늘게 떴다. 꾸짖는 눈은 아니었다."}, {"s": null, "t": "나는 승려에게, 그 아이들이 왜 잊히고 싶어 했느냐고 물었다."}, {"s": "q:g_juji", "t": "이 섬에 온 이들은 처음엔 기억되기를 빌었소. 바깥의 가족이 자기를 잊지 않기를."}, {"s": "q:g_juji", "t": "헌데 사당이 거꾸로 서자 기도도 거꾸로 이루어졌지. 그 뒤로는 모두 잊히기를 빌었소. 그래야 바깥 사람들이 덜 아플 테니."}, {"s": null, "t": "단이가 내 등 뒤에서 한 발 나왔다. 상자 끈을 쥔 손이 하얘져 있었다."}, {"s": "q:g_dani", "t": "…저는 잊히기 싫어요. 엄마도 잊히기 싫었을 거예요."}, {"s": null, "t": "나는 주워 온 향목 하나를 단이에게 건넸다. 단이가 두 손으로 받아 향꽂이에 바로 세웠다."}, {"s": null, "t": "연기가 처음으로 위로 올랐다. 가느다란 연기 한 줄이 천장까지 곧게 뻗었다. 단이가 「와아」 하고 입을 벌렸다."}, {"s": null, "t": "주지는 위로 오르는 연기를 오래 바라보았다. 이윽고 법당 지붕 위를 눈짓으로 가리켰다."}, {"s": null, "t": "거꾸로 매달린 범종이 혼자 흔들리고 있었다. 우우웅, 종소리가 땅 밑에서 거꾸로 올라왔다. 소리가 울릴 때마다 위로 오르던 연기가 휘청 꺾였다."}, {"s": "q:g_juji", "t": "범종이 아직 거꾸로 울고 있소. 저 종이 울면 바로 세운 향도 다시 고개를 숙이지. 거꾸로 선 범종귀를 잠재우면 이 사당의 기도가 바로 설 것이오."}, {"s": "q:g_dani", "t": "{이름} 님, 저것도 쫓을 수 있어요? 저건 동자들보다 훨씬 커요…"}, {"s": null, "t": "나는 해 보겠다고 했다. 단이가 고약 단지를 꼭 쥐고 연못 곁에 쪼그려 앉았다."}]'::jsonb where quest_id = 'gq_3' and step = 2 and md5(need::text) = md5('{"at": ["inverted_shrine"], "tasks": [{"m": ["gw_shrine_1"], "n": 3, "t": "win"}, {"n": 3, "r": ["inverted_shrine"], "t": "gather", "items": ["inverted_incense"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_3'' and step = 2 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "범종귀가 쿵, 쿵 몸을 흔들며 덤벼들었다. 종 안쪽이 입처럼 쩍 벌어졌다 닫혔다."}, {"s": null, "t": "나는 종 테두리를 노려 힘껏 쳤다. 쩌엉! 범종귀가 쓰러지며 범종이 마지막으로 거꾸로 울었다."}, {"s": null, "t": "그 소리가 귀가 아니라 발바닥으로 들어왔다. 무릎이 덜덜 떨렸다."}, {"s": "q:g_dani", "t": "{이름} 님! 괜찮아요? 서 있을 수 있어요?"}, {"s": null, "t": "나는 손을 들어 괜찮다고 했다. 달려오던 단이가 무너진 종 앞에서 멈칫 섰다."}, {"s": null, "t": "무너진 종 아래에서 녹슨 자물쇠 하나가 데구루루 굴러 나왔다. 단이가 자물쇠를 주워 들고 제 약 상자에 대어 보았다. 딸깍, 꼭 맞았다."}, {"s": "q:g_dani", "t": "이거… 엄마 거예요. 엄마도 여기 왔었구나."}, {"s": null, "t": "연못 속 주지가 고개를 끄덕였다. 목소리가 아까보다 부드러웠다."}, {"s": "q:g_juji", "t": "그 의무관은 잊히기를 빌지 않았소. 아이가 자기를 기억해 주기를 빌었지. 거꾸로 선 사당에서 바르게 빈 사람은 그이뿐이었소."}, {"s": null, "t": "연못에 비친 주지의 모습이 흐려지기 시작했다. 처음으로 웃는 얼굴이었다."}, {"s": "q:g_juji", "t": "종이 바로 섰으니 이제 바른 기도가 되겠구려. 아이야, 어미의 이름을 불러 보아라. 불러 주는 이가 있는 한 이름은 흩어지지 않는다오."}, {"s": null, "t": "단이는 자물쇠를 가슴에 안고 한참 입술만 달싹였다. 나는 단이 곁에 쪼그려 앉아 기다렸다."}, {"s": "q:g_dani", "t": "…틀리면 어떡해요?"}, {"s": null, "t": "나는 틀려도 괜찮으니 아는 대로 불러 보라고 했다."}, {"s": null, "t": "단이가 숨을 크게 들이마셨다. 아주 작게, 또박또박 불렀다."}, {"s": "q:g_dani", "t": "…서연. 엄마 이름은 서연이에요."}, {"s": null, "t": "연못 위로 잔물결이 동그랗게 번졌다. 주지의 모습은 그 물결을 따라 사라졌다."}, {"s": null, "t": "단이가 자물쇠를 상자에 끼우자 뚜껑 안쪽에서 종이 한 장이 비어져 나왔다. 단이는 종이를 내게 내밀었다."}, {"s": "q:g_dani", "t": "읽어 주실래요? 저 아직 글 잘 못 읽어요. 받침 있는 글자는 다 똑같아 보여요."}, {"s": null, "t": "내가 종이를 받는데 사당 문간에서 숨찬 발소리가 났다. 여울이었다. 여울은 단이를 보자 다리에 힘이 풀린 듯 문설주를 붙잡았다."}, {"s": "q:g_yeoul", "t": "단이야…! 너, 너 정말…!"}, {"s": null, "t": "단이가 약 상자를 끌어안고 고개를 푹 숙였다. 여울은 화를 내는 대신 단이를 와락 끌어안았다. 약 상자가 둘 사이에 끼어 덜컹 울렸다."}, {"s": "q:g_yeoul", "t": "다행이다. 저잣거리 쪽에 갔으면 어쩌나 했어."}, {"s": null, "t": "나는 저잣거리가 왜 위험하냐고 물었다."}, {"s": "q:g_yeoul", "t": "요즘 달 없는 저잣거리에 야행국 인장 찍힌 장부가 돈다는 말이 있거든. 그런 게 돌면 그 거리 것들이 사람 기억까지 값을 매겨."}, {"s": null, "t": "여울은 장부 이야기를 하면서 내 눈을 피했다. 단이를 안은 팔에만 힘이 들어갔다."}]'::jsonb where quest_id = 'gq_3' and step = 3 and md5(need::text) = md5('{"at": ["inverted_shrine"], "tasks": [{"m": ["gw_shrine_5"], "n": 1, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_3'' and step = 3 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 단이 곁에 앉아 종이를 소리 내어 읽었다. 여울은 문간에 선 채 듣고 있었다."}, {"s": "q:g_memory", "t": "이 섬에서 아이를 낳았다. 아이 손등에는 비늘이 없었다. 나는 그게 기뻤다가 무서웠다."}, {"s": "q:g_memory", "t": "여기서 비늘 없는 아이는 바깥으로도 섬으로도 갈 곳이 없다. 그래서 상자에 약을 채웠다. 어느 쪽에서든 누군가를 고칠 수 있게."}, {"s": "q:g_memory", "t": "단이야, 네가 이걸 읽을 때쯤 엄마는 아마 네 이름을 잊었을 거야. 대신 네가 엄마를 기억해 줘. 거꾸로 선 사당에서는 그게 바른 기도란다."}, {"s": null, "t": "내가 다 읽자 단이가 코를 훌쩍였다. 단이는 끝까지 울지 않았다."}, {"s": "q:g_dani", "t": "엄마가 제 이름을 잊었어도 괜찮아요. 제가 기억하면 되니까요. 그쵸?"}, {"s": null, "t": "나는 그렇다고 했다. 문간의 여울이 고개를 돌려 소매로 눈가를 훔쳤다."}, {"s": null, "t": "단이는 종이를 받아 약 상자 뚜껑 안쪽에 다시 붙였다. 아까보다 조금 높은 자리였다."}, {"s": "q:g_dani", "t": "여기 붙여 두면 상자 열 때마다 보여요. 키가 크면 더 높이 붙일 거예요."}, {"s": "q:g_yeoul", "t": "저 애가 울지 않고 끝까지 들은 건 처음이야. 내가 읽었으면 글자가 번져서 마지막 줄은 저 애한테 닿지도 못했을 거야."}, {"s": null, "t": "나는 이 섬 기억이라면 끝까지 읽어 주겠다고 했다. 여울이 나를 보다가 고개를 끄덕였다."}, {"s": "q:g_yeoul", "t": "돌아가자. 오늘은 내가 업어 줄게, 단이야."}, {"s": null, "t": "단이는 싫다고 버티다가 사당 계단 앞에서 여울 등에 냉큼 업혔다. 나는 덜렁거리는 약 상자를 받아 대신 멨다. 상자는 생각보다 묵직했다."}, {"s": null, "t": "내려가는 길에 여울이 한 번 뒤를 돌아보았다. 달 없는 저잣거리 쪽 하늘이었다. 여울은 아무 말도 하지 않았다."}]'::jsonb where quest_id = 'gq_3' and step = 4 and md5(need::text) = md5('{"at": ["inverted_shrine"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_3'' and step = 4 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "여울이 피하던 장부 이야기가 마음에 걸렸다. 이튿날 나는 혼자 달 없는 저잣거리로 갔다."}, {"s": null, "t": "꺼진 청사초롱이 길 양쪽에 끝없이 늘어서 있었다. 하늘에는 달도 별도 없었다. 빛 하나 없는데도 길은 희부옇게 보였다."}, {"s": null, "t": "좌판마다 손님이 서 있었지만 얼굴이 없었다. 갓 아래가 텅 비어 있었다."}, {"s": null, "t": "얼굴 없는 손님 하나가 내 곁을 스쳐 지나갔다. 옷자락이 닿은 팔이 얼음에 댄 것처럼 시렸다."}, {"s": null, "t": "손님이 지나간 자리에서 누군가의 웃음소리가 아주 잠깐 들렸다. 웃음소리는 금세 흩어져 사라졌다."}, {"s": null, "t": "흥정하는 소리가 들렸다. 손님들이 값으로 부르는 것은 전이 아니었다."}, {"s": null, "t": "「첫눈 오던 날 한 번」, 「어머니 목소리 두 번」 하는 값이 좌판마다 오갔다."}, {"s": null, "t": "네 번째 골목 끝, 먼지 앉은 좌판 위에 장부 한 권이 놓여 있었다. 표지에 야행국 본부 인장이 찍혀 있었다."}, {"s": null, "t": "표지에는 「귀허 이송 명부」라고 적혀 있었다."}, {"s": null, "t": "내가 장을 넘기니 이름과 침식 수치와 이송 날짜가 줄줄이 적혀 있었다. 이름마다 줄이 그어져 있었다."}, {"s": null, "t": "줄 옆에는 같은 글씨로 「잔여 없음」이라고 적혀 있었다. 몇 장을 넘겨도 글씨는 하나같이 반듯했다."}, {"s": null, "t": "등 뒤에서 누군가 헉 하고 숨을 들이켰다. 여울이 좌판 너머에 서 있었다. 얼굴이 하얗게 질려 있었다."}, {"s": "q:g_yeoul", "t": "…찾았구나."}, {"s": null, "t": "나는 따라왔느냐고 물었다."}, {"s": "q:g_yeoul", "t": "네가 아침에 이쪽으로 가는 걸 봤어. 말리려고 뛰어왔는데… 늦었네."}, {"s": null, "t": "여울은 장부에서 눈을 떼지 못하다가 억지로 고개를 돌렸다. 손목의 비늘을 문지르는 손이 빨라졌다."}, {"s": null, "t": "그사이 얼굴 없는 손님들이 하나둘 우리 쪽으로 갓을 돌렸다. 빈 갓 아래에서 킁킁 냄새를 맡는 소리가 났다."}, {"s": "q:g_yeoul", "t": "그 장부, 함부로 펼치지 마. 이 거리에선 기억도 물건이라 노리는 것들이 많아. 저것들이 벌써 냄새를 맡았어."}, {"s": null, "t": "나는 장부를 품에 넣고 어떻게 하면 되느냐고 물었다."}, {"s": "q:g_yeoul", "t": "이 거리는 골목이 저절로 자리를 바꿔. 길을 모르면 저것들한테 몰려. 놈들이 따라붙기 전에 거리를 네 번쯤 돌면서 눈에 익혀 둬. 빠져나갈 길을 알아야 해."}, {"s": "q:g_yeoul", "t": "저 끝 좌판의 기억 저울 장수가 이 거리 기억을 다 쥐고 있어. 손님들을 부리는 것도 그 장수야. 쓰러뜨리면 저울에 올린 기억이 망각 수정으로 굴러떨어질 거야."}, {"s": null, "t": "나는 그 수정을 어디에 쓰느냐고 물었다."}, {"s": "q:g_yeoul", "t": "녹이면 잊은 걸 잠깐 돌려줘. 반요촌엔 그게 필요한 사람이 많아. 세 개만 주워 와."}, {"s": null, "t": "나는 장부 이야기도 해 달라고 했다. 여울이 입술을 달싹이다가 고개를 끄덕였다."}, {"s": "q:g_yeoul", "t": "…장부 이야기는 그다음에 할게. 약속해. 이번엔 안 피할게."}]'::jsonb where quest_id = 'gq_4' and step = 1 and md5(need::text) = md5('{"at": ["moonless_market"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_4'' and step = 1 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 거리를 네 번 돌았다. 돌 때마다 골목 하나가 자리를 바꾸었다. 네 번째에야 빠져나가는 길이 눈에 들어왔다."}, {"s": null, "t": "기억 저울 장수는 저울 두 접시에 기억을 올려놓고 흔들었다. 접시가 짤랑짤랑 기울 때마다 누군가의 목소리가 새어 나왔다."}, {"s": null, "t": "나는 저울대를 노려 내리쳤다. 와장창! 저울이 부서지며 접시에 올려 두었던 기억들이 망각 수정이 되어 데굴데굴 굴러떨어졌다."}, {"s": null, "t": "내가 수정 하나를 집어 들자 그 안에 낯선 얼굴이 비쳤다. 젊은 조사원 하나가 붓을 들고 장부에 이름을 적고 있었다. 글씨가 반듯했다."}, {"s": null, "t": "어느새 곁에 와 있던 여울이 수정을 들여다보았다. 여울은 놀라지도 않고 쓴웃음을 지었다."}, {"s": "q:g_yeoul", "t": "그건 내 기억이야. 팔아 치웠는데, 여기 남아 있었네."}, {"s": null, "t": "나는 왜 기억을 팔았느냐고 물었다."}, {"s": "q:g_yeoul", "t": "잊고 싶었으니까. 팔면 잊힐 줄 알았는데, 아무도 안 사 가고 여기 굴러다니고 있었어."}, {"s": "q:g_yeoul", "t": "나는 본부 기록감찰국 서리였어. 침식 수치가 여든을 넘은 사람 이름을 받아 적었지. 그게 내 일이었어."}, {"s": null, "t": "여울은 수정을 내 손에서 가져가지 않았다. 오히려 한 걸음 물러섰다."}, {"s": "q:g_yeoul", "t": "여든에서 아흔 사이는 아직 사람이었어. 잘 쉬면 돌아오는 사람도 있었고. 그래도 적었어. 위에서 「잔여 없음」으로 정리하라고 했으니까."}, {"s": "q:g_yeoul", "t": "바깥 정청이 해마다 하는 명부 정리랑 같은 셈이야. 줄 하나 그으면 바깥에선 아무도 그 이름을 다시 안 불러."}, {"s": null, "t": "여울의 목소리가 갈라졌다. 나는 수정을 주머니에 넣고 여울의 손을 잡았다. 비늘 덮인 손목이 차갑게 떨고 있었다."}, {"s": "q:g_yeoul", "t": "…왜 손을 잡아. 나 그런 사람이라니까."}, {"s": null, "t": "나는 그래서 지금 그 이름들을 같이 찾고 있는 것 아니냐고 했다."}, {"s": null, "t": "여울이 한참 나를 보았다. 잡힌 손을 빼지 않았다."}, {"s": "q:g_yeoul", "t": "바깥 사람이 와서 이 섬 기억을 끝까지 읽어 주는 거. 그게 내가 너를 붙잡은 까닭이었는데. 이젠 네가 나를 붙잡네."}, {"s": null, "t": "나는 여울에게 그 「위」가 누구였느냐고 물었다."}, {"s": null, "t": "여울은 바로 대답하지 않았다. 저잣거리 너머, 소용돌이가 도는 바다 쪽을 오래 바라보았다."}, {"s": "q:g_yeoul", "t": "…귀허에 가면 알 거야. 그 사람도 결국 여기로 왔거든."}, {"s": "q:g_yeoul", "t": "그 전에 반요촌에 가자. 촌장님께 그 장부를 보여 드리고 망각 수정도 하나 드려. 그분 이름도 거기 있을 거야."}, {"s": "q:g_yeoul", "t": "촌장님, 문패에서 첫 글자를 잊으셨잖아. 수정을 녹이면 그 글자가 돌아올지도 몰라."}]'::jsonb where quest_id = 'gq_4' and step = 2 and md5(need::text) = md5('{"at": ["moonless_market"], "tasks": [{"n": 4, "r": ["moonless_market"], "t": "search"}, {"m": ["gw_market_3"], "n": 1, "t": "win"}, {"n": 3, "r": ["moonless_market"], "t": "gather", "items": ["oblivion_crystal"]}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_4'' and step = 2 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "반요촌에 돌아와 나는 묵호에게 장부를 내밀었다. 여울은 내 뒤에 한 걸음 떨어져 서 있었다."}, {"s": null, "t": "묵호가 화로 곁에 앉아 장부를 한 장씩 넘겼다. 사락, 사락, 종이 넘어가는 소리만 났다. 한 장에서 묵호의 손이 멈췄다."}, {"s": "q:g_mukho", "t": "…여기 있구먼. 내 이름."}, {"s": null, "t": "줄 그어진 이름 위를 노인의 손가락이 천천히 지나갔다. 문패에서 잊어버린 첫 글자가 장부에는 또렷하게 남아 있었다."}, {"s": null, "t": "묵호는 장부에서 고개를 들어 여울을 보았다. 목소리에 노여움은 없었다."}, {"s": "q:g_mukho", "t": "자네가 적었나, 여울."}, {"s": null, "t": "여울은 무릎을 꿇었다. 고개는 숙이지 않았다."}, {"s": "q:g_yeoul", "t": "네. 제가 적었습니다."}, {"s": null, "t": "나는 여울 곁으로 한 걸음 다가섰다. 여울이 고개를 저어 나를 말렸다."}, {"s": "q:g_yeoul", "t": "괜찮아. 이건 내가 대답해야 해."}, {"s": null, "t": "한동안 아무도 말하지 않았다. 화로 불꽃만 탁, 탁 두 번 튀었다."}, {"s": null, "t": "묵호가 먼저 웃었다. 주름이 깊게 접혔다."}, {"s": "q:g_mukho", "t": "반듯하게도 적었군. 덕분에 오늘은 첫 글자를 읽었네. 고맙네."}, {"s": "q:g_yeoul", "t": "촌장님, 저는…"}, {"s": "q:g_mukho", "t": "됐네. 자네가 안 적었으면 이 첫 글자는 이제 어디에도 없었을 걸세. 일어나게. 보는 내 무릎이 다 시리네."}, {"s": null, "t": "여울은 쉽게 일어서지 못했다. 나는 여울의 팔을 잡아 일으켰다. 여울의 무릎에서 재가 우수수 떨어졌다."}, {"s": null, "t": "나는 품에서 망각 수정 하나를 꺼내 묵호에게 건넸다. 묵호가 수정을 화로에 넣었다."}, {"s": null, "t": "수정이 지글지글 녹았다. 푸른 김이 피어올라 문간 쪽으로 흘러갔다."}, {"s": null, "t": "김이 닿자 문간에 걸린 묵호의 문패에서 번졌던 먹이 다시 또렷해졌다."}, {"s": null, "t": "묵호가 일어나 문패 앞에 섰다. 위쪽 이름의 첫 글자를 손가락으로 천천히 따라 썼다."}, {"s": "q:g_mukho", "t": "…그래, 이 글자였어. 이 글자였구먼."}, {"s": null, "t": "묵호는 장부를 덮어 내게 돌려주었다. 이어 바다 쪽을 보며 말했다."}, {"s": "q:g_mukho", "t": "귀허에 가거든 주인에게 전해 주게. 이 섬 사람들은 아직 이름이 있다고."}, {"s": null, "t": "나는 귀허의 주인이 누구냐고 물었다. 묵호는 대답 대신 여울을 보았다. 여울이 입술을 깨물었다."}, {"s": null, "t": "내가 장부를 받아 드는데, 마지막 장 뒤에 접힌 종이가 끼어 있는 것이 보였다."}]'::jsonb where quest_id = 'gq_4' and step = 3 and md5(need::text) = md5('{"at": ["banyo_village"], "give": {"oblivion_crystal": 1}}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_4'' and step = 3 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "나는 접힌 종이를 펼쳤다. 다른 조각들과 달리 글씨가 크고 거칠었다. 붓을 꾹꾹 눌러 쓴 자국이 종이 뒷면까지 배어 있었다."}, {"s": null, "t": "여울이 그 글씨를 보고 숨을 삼켰다."}, {"s": "q:g_memory", "t": "「귀허 이송」을 처음 제안한 이는 기록감찰국 국장이었다. 섬으로 보내면 바깥은 안전해진다고 했다. 이송된 자들은 「잔여 없음」으로 기록하라고 했다."}, {"s": "q:g_memory", "t": "국장의 침식이 여든을 넘던 날, 그는 자기 이름을 스스로 명부에 적었다. 그리고 첫 배를 탔다."}, {"s": "q:g_memory", "t": "그가 섬에 닿은 뒤로 귀허의 소용돌이가 생겼다고 반요촌 사람들은 말한다. 바깥이 잊은 이름들을 모두 끌어모으는 소용돌이가."}, {"s": null, "t": "여울이 종이 끝을 손가락으로 짚었다."}, {"s": "q:g_yeoul", "t": "국장님 글씨야."}, {"s": null, "t": "나는 여울에게 국장이 어떤 사람이었느냐고 물었다."}, {"s": "q:g_yeoul", "t": "…반듯한 글씨를 좋아하셨어. 그 이상은 묻지 마. 귀허에서 보면 알아."}, {"s": null, "t": "묵호가 화로 곁 궤짝을 열었다. 궤짝에서 짠 바다 냄새가 훅 끼쳤다. 묵호는 부적 한 장을 꺼내 내 손에 쥐여 주었다."}, {"s": "q:g_mukho", "t": "귀허 부적일세. 귀허 한가운데로 가려면 이게 있어야 하네. 바깥 사람한테 이걸 내주는 건 처음일세."}, {"s": "q:g_yeoul", "t": "귀허에서 기다릴게. 혼자 가게 두지 않을 거야."}, {"s": null, "t": "여울은 그 말을 남기고 먼저 화로 곁을 떠났다. 여울의 등이 아까보다 곧았다."}]'::jsonb where quest_id = 'gq_4' and step = 4 and md5(need::text) = md5('{"at": ["banyo_village"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_4'' and step = 4 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "묵호의 말을 전하러 나는 섬 끝 귀허로 갔다. 발밑의 돌길이 천천히 가라앉았다. 걸음을 멈출 때마다 물이 발목까지 차올랐다."}, {"s": null, "t": "바다가 한가운데로 빨려 들고 있었다. 쏴아아, 소용돌이 소리에 귀가 먹먹했다."}, {"s": null, "t": "물살에 휩쓸린 글자들이 거품처럼 떠올랐다가 꺼졌다. 나는 글자 하나를 손으로 건져 보았다."}, {"s": null, "t": "글자는 손바닥에서 차갑게 꿈틀거렸다. 이내 스르르 녹아 손가락 사이로 빠져나갔다."}, {"s": null, "t": "소용돌이 한가운데에 왕좌 하나가 떠 있었다. 왕좌는 비어 있었다."}, {"s": null, "t": "아무도 앉지 않았는데도 물살이 그 둘레를 비켜 돌았다."}, {"s": null, "t": "돌길 끝에서 여울이 기다리고 있었다. 여울은 왕좌 쪽을 보지 않으려는 듯 내 얼굴만 보았다."}, {"s": "q:g_yeoul", "t": "왔구나. 여기까지 와 준 바깥 사람은 처음이야."}, {"s": null, "t": "나는 돌길이 자꾸 가라앉는다고 했다. 여울이 손을 내밀었다."}, {"s": "q:g_yeoul", "t": "멈추지 말고 걸어. 서 있으면 가라앉고, 걸으면 버텨. 손 잡아."}, {"s": null, "t": "나는 여울의 손을 잡았다. 비늘 덮인 손이 저잣거리에서보다 따뜻했다. 우리는 발을 맞추어 첨벙첨벙 걸었다."}, {"s": "q:g_yeoul", "t": "왕좌 앞에 귀허의 문지기가 있어. 몸이 거울이라 때리면 되튕겨. 그걸 넘어야 왕좌 앞에 설 수 있어."}, {"s": null, "t": "나는 문지기를 넘으면 무엇이 있느냐고 물었다."}, {"s": "q:g_yeoul", "t": "국장님. …아니, 국장님이었던 거. 촌장님 말을 전하려면 그분 앞에 서야 해. 나도 그분한테 들어야 할 말이 있고."}, {"s": null, "t": "뒤에서 약 상자가 덜컹거렸다. 단이가 상자를 고쳐 메며 숨을 헉헉 몰아쉬고 있었다. 반요촌에서부터 몰래 따라온 모양이었다."}, {"s": "q:g_yeoul", "t": "단이야! 여기가 어디라고…!"}, {"s": "q:g_dani", "t": "저도 갈래요. {이름} 님이 다치면 제가 고쳐 줄게요. 고약도 새로 개어 왔어요."}, {"s": null, "t": "여울은 단이를 돌려보내려고 입을 열었다가 그만두었다. 아이의 손이 상자 끈을 놓지 않았다."}, {"s": null, "t": "나는 단이에게 내 뒤에서 떨어지지 말라고 했다. 단이가 고개를 세게 끄덕였다."}, {"s": "q:g_yeoul", "t": "…그래. 같이 가자. 셋이 가면 하나가 이름을 놓쳐도 둘이 불러 줄 수 있으니까."}]'::jsonb where quest_id = 'gq_5' and step = 1 and md5(need::text) = md5('{"at": ["gwiheo_core"]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_5'' and step = 1 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "문지기가 거울 팔을 휘둘렀다. 내 공격이 거울에 부딪혀 쨍 하고 되튕겼다. 되튕긴 힘에 나는 돌길 위로 털썩 주저앉았다."}, {"s": "q:g_dani", "t": "{이름} 님! 일어나요, 빨리!"}, {"s": null, "t": "단이가 달려와 내 팔에 고약을 철썩 발랐다. 나는 다시 일어나 거울 몸 한가운데를 노렸다."}, {"s": null, "t": "쨍그랑! 문지기의 거울 몸이 산산이 부서졌다. 흩어진 조각마다 다른 얼굴이 비쳤다."}, {"s": null, "t": "모두 반요촌 문패에서 본 이름의 주인들이었다."}, {"s": "q:g_dani", "t": "저 아저씨, 우물 옆집 사람이에요. 저 할머니는 바느질하는 집…"}, {"s": null, "t": "마지막 조각에 늙은 남자의 얼굴이 비쳤다. 야행국 본부 대청에 걸린 역대 국장 초상화 가운데 하나와 같은 얼굴이었다."}, {"s": null, "t": "여울이 조각 앞에 멈춰 섰다. 등이 곧게 펴졌다. 서리가 윗사람을 맞는 자세였다."}, {"s": "q:g_yeoul", "t": "국장님."}, {"s": null, "t": "소용돌이가 뚝 멈췄다. 빈 왕좌 위로 물이 솟아올라 사람 꼴이 되었다. 물로 된 노인이 왕좌에 앉아 여울을 내려다보았다."}, {"s": null, "t": "노인의 몸속에서 물이 쉬지 않고 돌았다. 그 물살 속에 이름들이 휩쓸려 다녔다."}, {"s": null, "t": "노인이 숨을 쉴 때마다 섬 전체가 쿠르릉 울렸다."}, {"s": "q:g_lord", "t": "오랜만이구나, 서리. 반듯한 글씨는 여전하냐."}, {"s": null, "t": "여울의 입술이 달싹였다. 대답은 나오지 않았다."}, {"s": null, "t": "노인의 눈이 나에게로 옮겨 왔다. 이름을 찾는 듯 잠시 말이 없었다."}, {"s": "q:g_lord", "t": "그리고 너는… {이름}. 바깥 명부에서 본 이름이다. 아직 줄이 그어지지 않았더구나."}, {"s": null, "t": "나는 묵호 촌장의 말을 전했다. 이 섬 사람들은 아직 이름이 있다고 했다."}, {"s": "q:g_lord", "t": "안다. 그래서 내가 여기 있다."}, {"s": null, "t": "노인은 왕좌 팔걸이를 쓸었다. 손이 지나간 자리마다 물속에서 글자들이 떠올랐다가 가라앉았다. 모두 이름이었다."}, {"s": "q:g_lord", "t": "나는 이 섬으로 보낸 이름을 모두 기억한다. 바깥이 잊었으니 누군가는 기억해야 했다. 그 이름들을 모두 끌어모아 바깥으로 되돌려 보낼 것이다. 침식째로."}, {"s": null, "t": "나는 그러면 바깥 사람들이 모두 요화한다고 말했다."}, {"s": null, "t": "노인은 표정 하나 바꾸지 않았다."}, {"s": "q:g_lord", "t": "그래야 공평하지 않으냐."}, {"s": "q:g_dani", "t": "그럼 반요촌 사람들은요? 촌장 할아버지는요? 다 같이 쓸려 가요?"}, {"s": null, "t": "노인은 단이를 보지 않았다. 소용돌이가 다시 돌기 시작했다. 쿠르르릉, 돌길이 크게 흔들렸다."}, {"s": null, "t": "단이가 비틀거리다 물 쪽으로 미끄러졌다. 나는 단이의 팔을 낚아채 끌어당겼다."}, {"s": null, "t": "여울이 내 소매를 잡아끌었다. 목소리가 떨렸지만 말은 빨랐다."}, {"s": "q:g_yeoul", "t": "…막아야 해! 저 사람이 소용돌이를 다 끌어모으면 반요촌도 바깥도 끝이야!"}, {"s": "q:g_yeoul", "t": "촌장님이 준 귀허 부적, 지니고 있지? 다 썼으면 반요촌 상점에서 구할 수 있어. 혼자든, 동료와 넷까지든 좋아."}, {"s": "q:g_yeoul", "t": "나랑 단이는 뒤에서 네 이름을 부르고 있을게. 이름 놓치지 마."}]'::jsonb where quest_id = 'gq_5' and step = 2 and md5(need::text) = md5('{"at": ["gwiheo_core"], "tasks": [{"m": ["gw_core_5"], "n": 1, "t": "win"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_5'' and step = 2 and md5(need::text) = md5(''{"'; end if; end $u$;
do $u$ declare n int; begin update public.world_quest_steps set lines = '[{"s": null, "t": "소용돌이가 우르르 무너져 내렸다. 왕좌 위의 물이 사람 꼴을 잃고 천천히 흘러내렸다."}, {"s": null, "t": "나는 숨을 몰아쉬며 무릎을 짚었다. 단이가 달려와 내 손등에 고약을 바르려다 손을 멈추었다. 단이의 눈이 노인을 향해 있었다."}, {"s": null, "t": "흘러내리던 노인이 마지막으로 고개를 들었다. 묻는 목소리가 처음으로 작았다."}, {"s": "q:g_lord", "t": "…이름을 하나만 다오. 내가 기억하지 못한 이름이 하나라도 있느냐."}, {"s": null, "t": "단이가 내 곁에서 한 걸음 나섰다. 약 상자를 등 뒤로 돌려 메고, 노인을 똑바로 올려다보았다."}, {"s": "q:g_yeoul", "t": "단이야…!"}, {"s": "q:g_dani", "t": "단이. 저는 여기서 태어났어요. 바깥에서 보내진 적 없어요."}, {"s": null, "t": "흘러내리던 물이 멈췄다. 노인의 얼굴이 아이를 오래 내려다보았다."}, {"s": "q:g_lord", "t": "…그렇구나. 이 섬에서 난 이름도 있었구나. 나는 보내진 이름만 세었다."}, {"s": null, "t": "노인은 여울 쪽으로 얼굴을 돌렸다. 마지막 남은 물이 입가에서 똑 떨어졌다."}, {"s": "q:g_lord", "t": "서리. 명부를 다시 써라. 「잔여 없음」 말고. 남은 이들의 이름을."}, {"s": null, "t": "여울은 두 손을 모으고 고개를 숙였다. 이번에는 똑바로 숙였다."}, {"s": "q:g_yeoul", "t": "네. 반듯하게 쓰겠습니다."}, {"s": null, "t": "물이 바다로 돌아갔다. 소용돌이가 있던 자리에 처음으로 달빛 비슷한 것이 비쳤다."}, {"s": null, "t": "여울은 한참 그 자리에 서 있었다. 어깨가 조금씩 들썩였다. 단이가 여울의 옷자락을 꼭 쥐었다."}, {"s": null, "t": "나는 여울 곁에 말없이 서 있었다. 여울이 고개를 돌려 나를 보았다. 눈가가 젖어 있었다."}, {"s": "q:g_yeoul", "t": "…고마워. 끝까지 같이 와 줘서."}, {"s": null, "t": "며칠 뒤 반요촌에 새 문패가 걸렸다. 이름이 두 개씩 적힌 문패들 사이에, 이름이 하나뿐인 문패가 있었다."}, {"s": null, "t": "그 문패에는 「단이」 두 글자만 적혀 있었다."}, {"s": null, "t": "문패를 거는 날, 단이는 내 소매를 붙들고 못 박을 자리를 정해 달라고 했다. 나는 단이 키보다 조금 높은 자리에 못을 박았다. 단이가 까치발을 하고 문패를 걸었다."}, {"s": "q:g_dani", "t": "키가 크면 까치발 안 해도 되겠다. 그쵸?"}, {"s": null, "t": "묵호는 제 문패 앞에 서서 위쪽 이름을 손가락으로 짚어 보았다. 이윽고 나를 돌아보며 웃었다."}, {"s": "q:g_mukho", "t": "첫 글자를 아직 기억하네. 오늘도."}, {"s": null, "t": "여울은 화로 곁에서 새 장부에 이름을 옮겨 적고 있었다. 여울이 붓을 내려놓고 나를 보았다."}, {"s": "q:g_yeoul", "t": "본부에 명부를 보낼 거야. 「귀허 이송 명부」 말고 「반요촌 주민 명부」로. 받아 줄지는 모르겠지만."}, {"s": null, "t": "나는 받아 주지 않으면 어떻게 하겠느냐고 물었다."}, {"s": "q:g_yeoul", "t": "받아 주지 않아도 계속 보낼 거야. 반듯하게."}, {"s": null, "t": "내가 선창으로 내려가 배에 오르자, 단이가 선창 끝까지 따라 나와 손을 흔들었다."}, {"s": "q:g_dani", "t": "{이름} 님, 또 와요. 다음엔 바다 냄새를 묻혀 올게요."}, {"s": null, "t": "나는 꼭 다시 오겠다고 했다. 단이가 두 팔을 머리 위로 휘휘 흔들었다."}, {"s": null, "t": "마을 쪽에서 배웅 노래가 들렸다. 오늘은 끝 소절이 달랐다. 누군가 맞이하는 노래를 처음으로 짓고 있었다."}]'::jsonb where quest_id = 'gq_5' and step = 3 and md5(need::text) = md5('{"at": ["gwiheo_core"], "tasks": [{"n": 1, "t": "gw", "mode": "any"}]}'::jsonb::text); get diagnostics n = row_count; if n <> 1 then raise exception '대본을 넣을 장면이 원본과 다름: %', 'quest_id = ''gq_5'' and step = 3 and md5(need::text) = md5(''{"'; end if; end $u$;

insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_chunbo', '객사 이야기꾼 춘보', '본부 객사 대청에서 손님들에게 무용담을 들려주는 이야기꾼. 숫자는 서너 곱절 부풀려도 이름은 버리지 않는다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_durye', '흑련 문지기 두례', '흑련 장부고 문지기. 겁이 많아 칼끝이 떨리지만 칼을 내려놓지는 않는다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_elder', '잔불촌 노인', '잔불촌 화로 곁에서 밤을 새우는 마을 노인.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_eonnyeon', '엿집 할멈 언년', '적사 황무지 어귀 사당 아랫마을에서 사당에 올릴 엿을 고는 노파. 엿 주걱을 손에서 놓지 않는다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_eopdong', '저울추지기 업동', '정리소에서 마흔 해 동안 가늠 저울추를 닦던 사람. 진이 꺼진 뒤 발밑에 그림자가 돌아왔다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_gaedong', '그물 깁는 개동 영감', '구름나루 선창 끝에서 그물을 깁는 여든 남짓한 노인. 어려서 구름나루 장부방 사환이었다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_hambak', '쉼막 맏이 함박', '등지기 쉼막에 거처를 차린 수향 뱃사람들의 맏이. 손이 커서 무엇이든 넉넉히 퍼 준다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_makdong', '흑련 문지기 막동이', '흑련 문지기 막내. 어머니가 앓아누운 뒤로 밤마다 어머니 이름을 불러 드려, 글자만 보면 소리 내어 읽는다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_maksoe', '흑련 문지기 막쇠', '흑련 장부고 문을 지키던 문지기. 칼을 늘 칼집째 쥐고 다니며 말수가 적다. 남문 수로 선착 야영소를 지키러 등도까지 내려왔다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_meoru', '잔불촌 아낙 머루댁', '갈매를 어릴 때부터 「갈매야」라고 부르던 잔불촌 아낙. 말끝마다 혀를 끌끌 찬다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_ongsim', '수향 뱃사람 옹심', '등지기 쉼막에 사는 수향 뱃사람. 쉼막 등에 넣을 기름을 얻으러 다닌다. 남의 물건에 손대기 전에 꼭 고개를 숙인다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_quest_npcs(npc_key, npc_name, bio) values ('q:sx_md_satdae', '수향 뱃사람 삿대', '청파와 같은 나루에서 자란 젊은 뱃사람. 거룻배로 봉인고와 남문 수로 선착을 오가며 짐을 나른다.') on conflict (npc_key) do update set npc_name = excluded.npc_name, bio = excluded.bio;
insert into public.world_item_catalog(item_id, item_name, category, tier, description, stackable, tradeable, reference_price, stack_size, equipment_traits) values
('hf_md_yeotjar', '앵두 엿 항아리', 'furniture', 4, '별채 가구 · 소품. 뚜껑에 아이 손자국이 남은 엿 항아리입니다. 동짓밤마다 엿을 가득 채워 적사 황무지로 들고 갑니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.', false, false, 800, 1, '{"hk": "md_yeotjar", "kind": "surface", "w": 1, "d": 1, "top": 0, "cat": "소품", "grade": 4}'::jsonb),
('hf_md_swordrack', '붉은 술 단 칼걸이', 'furniture', 4, '별채 가구 · 소품. 여씨 집안 목인 받침 나무로 짠 칼걸이입니다. 윗단에 붉은 술 끈이 매여 있어 창을 열면 바람 부는 쪽으로 날립니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.', false, false, 800, 1, '{"hk": "md_swordrack", "kind": "floor", "w": 1, "d": 1, "top": 0, "cat": "소품", "grade": 4}'::jsonb),
('hf_md_shipmodel', '청씨 배 모형', 'furniture', 4, '별채 가구 · 소품. 노들 영감이 깎은 손바닥만 한 배입니다. 돛대 밑에 금 서른둘이 새겨져 있고, 실처럼 가는 청씨 깃발이 달려 있습니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.', false, false, 800, 1, '{"hk": "md_shipmodel", "kind": "surface", "w": 1, "d": 1, "top": 0, "cat": "소품", "grade": 4}'::jsonb),
('hf_md_brazier', '남명 화로', 'furniture', 4, '별채 가구 · 조명. 장무현 화로의 흰 불씨를 나눠 담은 놋쇠 화로입니다. 뚜껑 틈으로 흔들리지 않는 흰빛이 새어 나옵니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.', false, false, 800, 1, '{"hk": "md_brazier", "kind": "floor", "w": 1, "d": 1, "top": 0, "cat": "조명", "grade": 4}'::jsonb),
('hf_md_starplate', '작은 별 기록판', 'furniture', 4, '별채 가구 · 족자. 하후정이 첫 관상대 별 기록판을 줄여 깎은 돌판입니다. 송곳 점으로 「빈」의 자리와 엉뚱한 데 찍힌 점 하나가 남아 있습니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.', false, false, 800, 1, '{"hk": "md_starplate", "kind": "wall", "wall": "deco", "ww": 1.2, "wh": 30, "cat": "족자", "grade": 4}'::jsonb),
('hf_md_feastlamp', '명등제 등롱', 'furniture', 4, '별채 가구 · 조명. 이름을 적자 기름 없이 불이 붙은 등롱입니다. 아랫단에 「내년 동지 · 꺼진 관아 터」가 적혀 있습니다. 별채에 놓으면 가방에서 빠지고, 거두면 곳간으로 갑니다.', false, false, 800, 1, '{"hk": "md_feastlamp", "kind": "wall", "wall": "deco", "ww": 1, "wh": 40, "cat": "조명", "grade": 4}'::jsonb)
