insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_shoes', 1, '가지런한 신', '가지런한 신', '{"at": ["dark_yamen"]}'::jsonb, '[{"s": null, "t": "꺼진 관아 터 뒤뜰의 느티나무 아래에서 흑련 문지기 두례가 쪼그려 앉아 있었다. 선착 야영소를 지키러 내려왔다가 관아 터 순찰을 맡은 두례는 칼을 땅에 내려놓은 채, 두 손으로 무릎을 감싸 쥐고 무언가를 들여다보았다."}, {"s": null, "t": "나무 밑동 곁에 작은 짚신 한 켤레가 놓여 있었다. 누가 벗어 둔 것처럼 앞코를 나란히 맞춘 채였다. 짚은 하얗게 바랬지만 끈은 끊어지지 않았다."}, {"s": null, "t": "두례가 나를 돌아보며 짚신 쪽으로 손짓했다. 목소리가 저도 모르게 작아져 있었다."}, {"s": "q:sx_md_durye", "t": "조사원님, 이거 보세요. 아이 신이에요. 제 손바닥보다 작아요. 누가 여기서 신을 벗고 갔을까요. 신을 벗고 어디를 가요, 맨발로."}, {"s": null, "t": "두례 뒤에서 막쇠가 칼집째 쥔 칼로 땅을 짚고 서 있었다. 막쇠는 짚신을 내려다보다가 짧게 혀를 찼다."}, {"s": "q:sx_md_maksoe", "t": "벗은 게 아니야. 사흘째에 몸이 풀리면 옷이랑 신만 남는대. 장부고 어른들이 그랬어."}, {"s": null, "t": "두례의 어깨가 움찔했다. 두례가 칼을 다시 집어 들었는데, 칼끝이 바들바들 떨렸다."}, {"s": "q:sx_md_durye", "t": "그럼 더 찾아 줘야죠. 이 신 주인을 아무도 안 부르면, 이건 그냥 짚 쪼가리잖아요. 신 안에 약풀 잎이 끼어 있어요. 이 둘레 약풀 둔덕에서 뭐라도 나올지 몰라요. 조사원님, 같이 좀 뒤져 주세요."}, {"s": null, "t": "막쇠가 칼집 끝으로 약풀 둔덕을 툭툭 짚으며 한숨을 쉬었다."}, {"s": "q:sx_md_maksoe", "t": "……네 번만 뒤져. 그 이상은 칼끝 떨리는 놈이 못 버텨."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_shoes', 2, '약풀 틈의 패', '꺼진 관아 터에서 채집한다', '{"at": ["dark_yamen"], "tasks": [{"t": "gather", "r": ["dark_yamen"], "n": 4}]}'::jsonb, '[{"s": null, "t": "느티나무 둘레 약풀 둔덕을 헤치다가, 흰 약풀 잎에 싸인 나무패 하나를 찾았다. 잎을 벗겨 내자 패 앞면에 글자 몇 획이 아주 옅게 남아 있었다."}, {"s": null, "t": "두례가 패를 받아 들고 흰 하늘에 비추어 보았다. 획은 비출수록 더 하얗게 날아갔다."}, {"s": "q:sx_md_durye", "t": "안 보여요. 다 바랬어요. 하늘이 이렇게 하얀데 왜 글자는 안 보여요."}, {"s": null, "t": "막쇠가 패를 두례 손에서 건네받아 칼집 끝으로 획 하나를 짚었다. 그 획만은 다른 것보다 조금 짙었다."}, {"s": "q:sx_md_maksoe", "t": "선착 야영소 천막엔 등을 켜 뒀잖아. 거긴 흰 밤이 안 닿아. 등 밑에 하룻밤 두면 획이 좀 살아날 거야. 관아 터 처마에 이름 적은 등을 달았을 때도 그 둘레만 색이 돌아왔다더라."}, {"s": null, "t": "두례가 벌떡 일어섰다. 칼끝 떨리는 것도 잊은 얼굴이었다."}, {"s": "q:sx_md_durye", "t": "그럼 가요. 지금 가요. 신은 제가 들고 갈게요."}, {"s": null, "t": "두례가 짚신을 조심스레 집어 품에 안았다. 막쇠가 고개를 저으며 두례의 팔을 붙잡았다."}, {"s": "q:sx_md_maksoe", "t": "신은 두고 가. 신은 제자리에 있어야 주인이 알아보지. 패만 들고 가자."}]'::jsonb, '{"xp": 3840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_shoes', 3, '등불 밑에서 살아난 이름', '남문 수로 선착에 간다, 남문 수로 선착에서 쉰다', '{"at": ["deungdo_landing"], "tasks": [{"t": "travel", "r": ["deungdo_landing"], "n": 1}, {"t": "rest", "r": ["deungdo_landing"], "n": 1}]}'::jsonb, '[{"s": null, "t": "우리는 선착 야영소 천막 등불 아래에 패를 놓고 하룻밤을 쉬었다. 새벽에 두례가 먼저 일어나 패를 들여다보다가, 나와 막쇠를 흔들어 깨웠다."}, {"s": null, "t": "패의 획이 밤사이 짙어져 있었다. 「관아 약방 심부름꾼 자근이」라는 글자가 등불 빛 아래에서 또렷하게 읽혔다."}, {"s": null, "t": "두례가 패를 들여다보며 입술을 달싹였다."}, {"s": "q:sx_md_durye", "t": "자근이. 자근이래요. 약방 심부름꾼이었대요. 그래서 신에 약풀이 끼어 있었구나."}, {"s": null, "t": "두례가 패를 두 손으로 감싸 쥐었다. 막쇠는 패를 한 번 보고 천막 밖으로 고개를 돌렸다."}, {"s": "q:sx_md_maksoe", "t": "약방 심부름이면 뒤뜰 약풀 둔덕을 날마다 오갔겠지. 그 느티나무가 지름길이었을 거고."}, {"s": null, "t": "막쇠는 한동안 말이 없다가, 칼집을 쥔 손에 힘을 주었다."}, {"s": "q:sx_md_maksoe", "t": "그 나무 둘레에 먹 묻은 것들이 자꾸 돌더라. 입만 뻐끔거리면서. 어제는 그냥 귀찮은 것들인 줄 알았는데…… 누구를 부르다 굳은 거라며. 그 아이를 부르던 사람이었을지도 몰라."}, {"s": null, "t": "두례가 패를 품에 넣고 칼을 고쳐 쥐었다. 칼끝은 여전히 떨렸지만 두례는 칼을 내려놓지 않았다."}, {"s": "q:sx_md_durye", "t": "그럼 풀어 줘야죠. 계속 그 입 모양으로 돌게 둘 수는 없잖아요. 조사원님, 저도 갈게요. 칼끝은 떨려도 따라갈 수는 있어요."}]'::jsonb, '{"xp": 3840}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_shoes', 4, '신 안에 넣은 이름', '꺼진 관아 터에 간다, 부르다 굳은 넋을(를) 물리친다', '{"at": ["dark_yamen"], "tasks": [{"t": "travel", "r": ["dark_yamen"], "n": 1}, {"t": "win", "m": ["dd_yamen_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "느티나무 둘레를 맴돌던 부르다 굳은 넋들이 하나씩 쓰러지자, 먹이 빠진 자리마다 바랜 등롱 종이가 한 장씩 남았다. 마지막 하나는 쓰러지기 전에 짚신 쪽으로 손을 뻗었다가, 손끝부터 먹으로 풀려 땅에 스몄다."}, {"s": null, "t": "두례가 그 자리에 무릎을 꿇었다. 패를 짚신 한 짝 안에 넣고, 신 두 짝의 앞코를 다시 나란히 맞추었다."}, {"s": "q:sx_md_durye", "t": "자근아."}, {"s": null, "t": "두례의 입김이 흩어졌다. 금빛은 일지 않았다. 두례는 한 번 더 불러 보려다가 입술을 깨물었다."}, {"s": "q:sx_md_durye", "t": "안 닿네요. 알아요. 없는 사람한테는 안 닿는다는 거. 그래도 오늘은 누가 불렀잖아요. 일흔 해 만에요."}, {"s": null, "t": "막쇠가 두례 곁에 칼을 내려놓고 앉았다. 막쇠는 한참 짚신을 보다가, 품에서 흑련 꾸러미 끈을 꺼내 신 두 짝을 느슨하게 묶었다."}, {"s": "q:sx_md_maksoe", "t": "흑련은 이름을 맡아 두는 데야. 이름을 찾았으니 이제 신은 자리를 옮겨도 돼. 장부고에 가져가자. 맡을 사람이 없으면 우리가 맡으면 돼."}, {"s": null, "t": "두례가 눈을 동그랗게 뜨고 막쇠를 보았다."}, {"s": "q:sx_md_durye", "t": "……막쇠가 그런 말도 할 줄 알아요?"}, {"s": null, "t": "막쇠가 고개를 홱 돌리고 칼집을 집어 들었다."}, {"s": "q:sx_md_maksoe", "t": "시끄러. 칼이나 주워."}, {"s": null, "t": "두례가 웃으며 칼을 주웠다. 칼끝은 아직도 조금 떨렸지만, 두례는 짚신을 품에 안은 채 느티나무 아래를 한 번 돌아보고 일어섰다."}]'::jsonb, '{"xp": 3840, "gil": 185, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
