delete from public.world_quest_steps where quest_id = 'mds_arrows' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_arrows', 1, '손에 잡힌 화살', '손에 잡힌 화살', '{"at": ["martial_row"]}'::jsonb, '[{"s": null, "t": "연무장 목인 앞에서 여운비가 허공에 멈춘 화살 하나를 쥐고 있었다. 흰 밤 동안에는 손을 대면 손끝이 바래던 화살이었는데, 밤빛이 돌아온 뒤로는 손에 쥐어도 아무렇지 않았다."}, {"s": null, "t": "여운비가 손에 힘을 주자 화살이 허공에서 툭 빠져 손안으로 떨어졌다. 일흔 해 동안 날아가던 화살이 그제야 멈춘 것 같았다."}, {"s": "north_league:yeo", "t": "밤이 돌아오니 화살이 손에 잡히오. 그런데 이걸 보시오. 깃 아래에 이름이 있소."}, {"s": null, "t": "여운비가 깃털을 엄지로 젖혔다. 화살대에 작은 글씨가 새겨져 있었다. 쏜 사람의 이름이었다."}, {"s": "north_league:yeo", "t": "북령 무관은 제 화살대에 이름을 새기오. 싸움터에서 누가 쏜 화살인지 알아야 거둘 때 주인한테 돌려주니까. 주인이 죽으면 그 화살은 고찰 활터 시렁에 걸고."}, {"s": "north_league:yeo", "t": "이 거리 화살들은 일흔 해 동안 아무도 거두지 못했소. 고찰 시렁에 걸어 주고 싶소. 연무장과 과녁 터에 남은 멈춘 화살대를 여덟 대만 모아 주시겠소? 나는 목인 쪽을 맡겠소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_arrows', 2, '과녁 못 닿은 것들', '무관 거리에서 멈춘 화살대을(를) 모은다', '{"at": ["martial_row"], "tasks": [{"t": "gather", "items": ["frozen_arrow_shaft"], "r": ["martial_row"], "n": 8}]}'::jsonb, '[{"s": null, "t": "모은 화살대를 펼쳐 놓자, 여운비가 깃을 하나씩 젖혀 이름을 읽었다. 이름 몇은 아주 옅었지만, 밤빛 아래에서는 획이 끊기지 않고 이어져 보였다."}, {"s": "north_league:yeo", "t": "여덟 대에 이름이 여섯이오. 두 대씩 쏜 사람이 둘이오. 그날 밤에도 여기서 활을 쏘고 있었던 거요."}, {"s": null, "t": "여운비가 화살대를 천으로 감싸 묶다가 손을 멈추고 하늘을 올려다보았다. 연무장 위로 화살 모양의 검은 것들이 맴돌고 있었다."}, {"s": "north_league:yeo", "t": "저것들도 화살이오. 과녁에 못 닿고 멈춰 있다가 요괴가 된 것들. 저 안에도 이름 새긴 화살대가 들어 있을 거요."}, {"s": "north_league:yeo", "t": "여덟만 떨어뜨립시다. 떨어뜨린 것은 화살대만 거두면 되오. 북령 화살은 북령 시렁으로 가야 하오."}]'::jsonb, '{"xp": 3999}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_arrows', 3, '고찰로 가는 짐', '과녁 못 닿은 화살귀을(를) 물리친다', '{"at": ["martial_row"], "tasks": [{"t": "win", "m": ["dd_martial_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "떨어뜨린 화살귀에서 거둔 화살대까지 더하자, 천에 싼 화살 묶음이 한 아름이 되었다. 여운비는 묶음을 끈으로 세 번 감고 북령 매듭으로 묶었다."}, {"s": "north_league:yeo", "t": "고찰 활터 시렁에는 이름마다 자리가 정해져 있소. 그런데 어릴 때부터 이상하게 여긴 게 하나 있소. 시렁 맨 아래 한 줄이 늘 비어 있었소. 아무도 그 줄에는 화살을 걸지 않았고, 왜 비우는지도 가르쳐 주지 않았소."}, {"s": null, "t": "여운비가 묶음을 내 품에 안겨 주고는 칼자루 끝 붉은 술을 들어 보았다. 밤빛 아래에서도 술은 곧게 늘어져 있었다."}, {"s": "north_league:yeo", "t": "여기는 아직 바람이 없구려. 고찰 산문에 닿으면 북쪽 바람이 길을 일러 줄 거요. 맹주께 이 화살들을 보여 드립시다. 시렁에 거는 일은 맹주께서 하셔야 하오."}]'::jsonb, '{"xp": 3999}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_arrows', 4, '비워 둔 줄', '철벽 고찰에 간다, 멈춘 화살대을(를) 넘긴다', '{"at": ["iron_monastery"], "tasks": [{"t": "travel", "r": ["iron_monastery"], "n": 1}], "give": {"frozen_arrow_shaft": 8}}'::jsonb, '[{"s": null, "t": "철벽 고찰 활터에 들어서자 맹주 석진악이 시렁 앞에 서 있었다. 수좌 혜각이 우리를 보고 먼저 산문 쪽에서 걸어왔고, 염주를 굴리던 손이 화살 묶음을 보고 멈췄다."}, {"s": "north_league:hyegak", "t": "허허, 호송대장이 이번엔 사람 대신 화살을 호송해 왔군요. 맹주님이 아침부터 활터에 나와 계셨습니다. 무관 거리에 밤이 돌아왔다는 소식을 듣고요."}, {"s": null, "t": "석진악은 아무 말 없이 화살 묶음을 받아 끈을 풀었다. 노인은 화살대를 하나씩 들어 깃을 젖혀 보았다. 넷째 화살에서 노인의 손이 멈췄다."}, {"s": "north_league:seok", "t": "……이 사람은 내가 아네. 내가 열 살 때 처음 활을 쥐여 준 사형이야. 남쪽 도성 수비로 내려갔다가 돌아오지 않았지. 나는 그 사형이 어디서 사라졌는지 일흔 해 동안 몰랐네."}, {"s": null, "t": "석진악이 그 화살을 두 손으로 쥐고 시렁 맨 아래 줄 앞에 섰다. 여운비가 어릴 때부터 비어 있었다던 줄이었다."}, {"s": "north_league:seok", "t": "이 줄은 우리 윗대 어른들이 비워 두라 하셨네. 까닭은 묻지 말라 하셨고. 이제 알겠구먼. 등도로 내려가 돌아오지 못한 이들 자리였어. 부끄러워서 이름도 못 걸고, 자리만 비워 둔 걸세."}, {"s": null, "t": "석진악이 화살을 하나씩 시렁에 걸었다. 걸 때마다 깃 아래 이름을 소리 내어 읽었다. 노인의 목소리가 활터 둘레 바위에 부딪혀 낮게 울렸다."}, {"s": "north_league:seok", "t": "운비야. 남은 건 네가 걸거라. 나는 손이 떨려서 안 되겠다."}, {"s": null, "t": "여운비가 남은 화살을 받아 시렁에 걸었다. 여운비도 이름을 하나씩 읽었고, 맨 끝 화살을 걸고 나서 한 걸음 물러섰다. 비어 있던 맨 아래 줄이 화살로 반쯤 찼다."}, {"s": null, "t": "혜각이 염주를 손목에 걸고 시렁 앞으로 다가와 합장했다."}, {"s": "north_league:hyegak", "t": "허허, 일흔 해 비워 둔 줄을 이제야 채우는군요. 시렁도 숨을 돌리겠습니다. 다들 공양간으로 오세요. 빙어국이 끓고 있습니다. 화살을 걸어 준 손님은 한 그릇 더 드리고요."}, {"s": null, "t": "석진악은 공양간으로 가지 않고 시렁 앞에 한참 서 있었다. 노인의 큰 손이 사형의 화살 깃을 한 번 쓸고서야 떨어졌다."}]'::jsonb, '{"xp": 3999, "gil": 189, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mds_dummy', 'side', '전투·무관 거리', '그림자 없는 목인', '무관 거리에 밤빛이 돌아오자 목인마다 그림자가 생기고 이름이 살아났다. 그런데 몇몇 목인은 그림자도 이름도 없다. 걸어 나간 그림자들을 찾아 돌려놓는다.', 'martial_row', 46, '{mdq_6}'::text[], null, 1425, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mds_dummy' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_dummy', 1, '그림자를 세는 사람', '그림자를 세는 사람', '{"at": ["martial_row"]}'::jsonb, '[{"s": null, "t": "무관 거리에 밤빛이 돌아와 있었다. 돌바닥 서리 위로 푸르스름한 기운이 깔렸고, 연무장 처마 등롱 둘레에서 짚 목인들의 그림자가 저마다 길게 누워 있었다."}, {"s": null, "t": "여운비가 목인 줄 앞을 천천히 걸으며 그림자를 하나씩 세고 있었다. 여운비는 버릇처럼 칼자루 끝 붉은 술을 한 번 들어 보았다. 밤은 돌아왔는데 술은 여전히 곧게 늘어져 있었다."}, {"s": "north_league:yeo", "t": "밤이 돌아오니 목인마다 그림자가 생겼소. 그림자가 생긴 목인은 가슴께 이름도 돌아왔고. 그런데 여기 좀 보시오."}, {"s": null, "t": "여운비가 가리킨 목인 몇은 처마 등롱 바로 아래 서 있는데도 그림자가 없었다. 가슴께 글씨도 하얗게 바랜 그대로였다."}, {"s": "north_league:yeo", "t": "열하나요. 그림자 없는 목인이 열하나. 그림자가 어디로 갔는지는 짐작이 가오. 흰 밤 동안 목인 사이에 섞여 있다 덤비던 것들, 기억나시오?"}, {"s": null, "t": "나는 목인 줄 사이에서 튀어나오던 검은 것들을 떠올렸다. 그림자 없는 땅에서 제 그림자를 찾아 걸어 나왔다던 짚 목인 그림자였다."}, {"s": null, "t": "여운비가 바랜 목인 가슴께를 손끝으로 짚었다."}, {"s": "north_league:yeo", "t": "그것들이 목인 그림자였던 거요. 그림자가 걸어 나가면서 이름도 같이 들고 나간 모양이오. 거리에 흩어진 짚 목인 그림자를 풀어 보내면 제자리로 돌아올지도 모르겠소."}, {"s": "north_league:yeo", "t": "북령 무관은 처음 활을 잡는 날 목인에 제 이름을 새기오. 그 이름이 저렇게 남의 그림자에 들려 돌아다니는 건 두고 볼 수 없소."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_dummy', 2, '활 당기는 그림자', '짚 목인 그림자을(를) 물리친다', '{"at": ["martial_row"], "tasks": [{"t": "win", "m": ["dd_martial_2"], "n": 8}]}'::jsonb, '[{"s": null, "t": "짚 목인 그림자들이 쓰러지자 검은 몸이 땅바닥에 납작하게 깔리더니, 스르르 미끄러져 목인 발치로 돌아갔다. 목인 발밑에 그림자가 하나씩 다시 누웠다."}, {"s": null, "t": "그림자가 돌아온 목인의 가슴께에 바랜 글씨가 한 획씩 짙어졌다. 여운비가 목인 하나 앞에서 걸음을 멈추고 그림자를 내려다보았다."}, {"s": "north_league:yeo", "t": "그림자 모양을 보시오. 목인 그림자가 아니라 활을 당기는 사람 그림자요."}, {"s": null, "t": "땅바닥의 그림자는 짚 목인 모양이 아니었다. 시위를 귀까지 당긴 사람의 모양이었다. 목인 앞에 서서 활을 쏘던 무관의 그림자가 일흔 해 동안 목인에 붙어 있었던 것이다."}, {"s": null, "t": "여운비가 그림자를 하나씩 세며 목인 줄을 훑다가 맨 끝 작은 목인 앞에서 멈췄다. 그 목인만은 아직 그림자가 없었다. 다른 목인보다 키가 한 뼘이나 작았다."}, {"s": "north_league:yeo", "t": "아이 목인이오. 처음 활을 잡는 아이한테는 키에 맞춰 작게 깎아 주오. 내 첫 목인도 이만했소."}, {"s": "north_league:yeo", "t": "연무장 위를 맴도는 화살귀들이 보이시오. 과녁에 못 닿고 멈췄다 요괴가 된 것들이오. 저것들이 이 아이 그림자를 화살대에 꿰어 들고 다니는 것 같소. 여덟만 떨어뜨립시다. 내가 앞을 맡겠소."}]'::jsonb, '{"xp": 3999}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_dummy', 3, '비뚤게 새긴 이름', '과녁 못 닿은 화살귀을(를) 물리친다', '{"at": ["martial_row"], "tasks": [{"t": "win", "m": ["dd_martial_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "마지막 화살귀가 돌바닥에 떨어지자, 부러진 화살대 틈에서 작은 그림자 하나가 빠져나와 아이 목인 발치로 쪼르르 달려갔다. 그림자는 제 키만 한 활을 쥔 모양이었다."}, {"s": null, "t": "아이 목인 가슴께에 글씨가 떠올랐다. 칼끝으로 비뚤비뚤 새긴 두 글자, 「재복」이었다. 획마다 힘을 너무 준 자국이 남아 있었다."}, {"s": null, "t": "여운비가 아이 목인 앞에 무릎을 굽히고 앉았다."}, {"s": "north_league:yeo", "t": "재복. ……손에 힘이 너무 들어갔구려. 처음 새길 때는 다들 이렇소."}, {"s": null, "t": "여운비가 엄지로 그 글씨를 쓸었다. 칼자루 끝 붉은 술이 여운비의 손등 위로 늘어졌다."}, {"s": "north_league:yeo", "t": "내 첫 목인도 글씨가 이렇게 삐뚤었소. 그 목인 앞에서 활을 당기던 아이가 자라 처음 호송을 나가던 날, 아버지가 이 술을 칼자루에 달아 주셨지. 사람은 보지 말고 바람을 보라고."}, {"s": null, "t": "여운비가 술 끝을 손가락에 감았다가 놓았다. 술은 흔들리지 않고 곧게 떨어졌다. 여운비는 그것을 보고도 이번에는 술을 주먹에 쥐지 않았다."}, {"s": "north_league:yeo", "t": "오늘 밤은 여기 있겠소. 열한 목인 이름을 하나씩 읽어 주고 싶소. 밤이 돌아왔으니 이제는 소리가 세 걸음 밖으로도 갈 거요. 조사원도 같이 있어 주시겠소?"}]'::jsonb, '{"xp": 3999}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_dummy', 4, '멀리 가는 소리', '무관 거리에서 쉰다', '{"at": ["martial_row"], "tasks": [{"t": "rest", "r": ["martial_row"], "n": 1}]}'::jsonb, '[{"s": null, "t": "연무장 처마 아래 불을 피우고, 여운비는 목인 줄 앞에 서서 이름을 하나씩 읽었다. 목소리는 크지 않았지만 처음으로 거리 끝까지 울려 갔다."}, {"s": null, "t": "금빛은 일지 않았다. 목인 주인들은 일흔 해 전에 모두 거둬졌다. 그래도 여운비는 열한 이름을 빠짐없이 읽고, 맨 마지막에 「재복」을 한 번 더 읽었다."}, {"s": "north_league:yeo", "t": "금빛이 안 나는 건 아오. 그래도 이 거리에서 이름을 읽는 소리가 거리 끝까지 간 건 일흔 해 만일 거요."}, {"s": null, "t": "여운비가 불가로 돌아와 앉았다. 칼을 무릎에 눕히고 한참 불을 보다가 나를 돌아보았다."}, {"s": "north_league:yeo", "t": "조사원은 처음 무기를 쥐던 날이 어땠소. ……대답하지 않아도 되오. 그냥 물어보고 싶었소."}, {"s": null, "t": "나는 대답 대신 불에 장작을 하나 더 넣었다. 여운비가 짧게 웃었다."}, {"s": "north_league:yeo", "t": "…나쁘지 않소. 그 대답."}, {"s": null, "t": "처마 등롱 아래에서 열한 목인의 그림자가 활을 당긴 모양 그대로 땅에 누워 있었다. 모닥불이 흔들릴 때마다 그림자들도 함께 조금씩 흔들려, 시위를 놓기 직전의 사람들처럼 보였다."}]'::jsonb, '{"xp": 3999, "gil": 189, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
