insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mds_cargo', 'side', '조사·옛 나루 저자', '얹힌 배의 짐표', '주판을 내려놓은 도방 진소랑이 옛 나루 저자의 얹힌 배를 세러 왔다가, 소등 전날 떠나지 못한 짐배에서 짐표 하나를 찾는다. 받는 이는 구름나루 장부방 사환 아이 개동 — 지금은 여든이 넘은 그물 깁는 영감이다.', 'old_ferry_market', 48, '{mdq_10}'::text[], null, 1428, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mds_cargo' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_cargo', 1, '배를 세는 도방', '배를 세는 도방', '{"at": ["old_ferry_market"]}'::jsonb, '[{"s": null, "t": "마른 물길 둑에 앉은 도방 진소랑이 무릎에 장부를 펴 놓고 배를 세고 있었다. 주판은 둑 아래 돌 위에 엎어 둔 채였다. 손가락으로 배를 하나씩 짚을 때마다 붓으로 장부에 작은 동그라미를 그렸다."}, {"s": null, "t": "진소랑은 나를 보자 붓을 귀에 꽂고 웃었다. 장부방에서처럼 값을 깎는 웃음이 아니라, 조금 지친 웃음이었다."}, {"s": "river_alliance:jin", "t": "조사원님, 오셨어요. 장부방에 앉아 있자니 주판에 손이 자꾸 가서요. 이번엔 값 말고 배 수만 세러 왔어요. 수향 배가 몇 척이나 여기 얹혀 있는지, 그것부터 알아야 할 것 같아서요."}, {"s": "river_alliance:jin", "t": "서른일곱 척까지 셌는데, 저 작은 거룻배에서 이게 나왔어요."}, {"s": null, "t": "진소랑이 품에서 손바닥만 한 나무패 하나를 꺼냈다. 기름종이로 싼 보따리에 끈으로 매달려 있던 짐표였다. 먹은 하얗게 바랬지만 칼로 새긴 홈은 그대로 남아 있었다."}, {"s": null, "t": "나는 짐표의 홈을 손끝으로 더듬어 읽었다. 「보내는 이 — 옛 나루 잉어찜 집 볕뉘. 받는 이 — 구름나루 장부방 사환 개동. 뱃삯은 받을 때.」 날짜는 소등 전날이었다."}, {"s": "river_alliance:jin", "t": "짐배예요. 소등 전날 나루를 떠나야 했는데 끝내 못 떠난 배요. 짐을 다 싣고도 물길을 못 빠져나가고 여기서 멈춘 거죠. 저 배 말고도 짐표 달린 배가 더 있을 거예요."}, {"s": null, "t": "진소랑이 장부를 덮고 배들 사이를 돌아보았다. 빈 좌판마다 값을 적은 나무패가 꽂혀 있었고, 얹힌 배 밑 그늘에서 무언가 딸깍딸깍 집게를 부딪는 소리가 났다."}, {"s": "river_alliance:jin", "t": "저 소리 들으셨죠. 배 밑에 숨은 마른 물길 게들이에요. 제가 배를 하나 짚을 때마다 집게를 벌리고 기어 나와서 셈을 못 하겠어요. 그것들을 좀 치워 주시고, 다른 배에도 짐표가 있는지 같이 봐 주세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_cargo', 2, '떠나지 못한 짐', '마른 물길 게을(를) 물리친다, 옛 나루 저자을(를) 살핀다', '{"at": ["old_ferry_market"], "tasks": [{"t": "win", "m": ["dd_ferry_1"], "n": 8}, {"t": "search", "r": ["old_ferry_market"], "n": 3}]}'::jsonb, '[{"s": null, "t": "짐표 달린 배는 작은 거룻배 하나뿐이 아니었다. 배 무덤 바깥쪽에 비슷한 짐배 셋이 나란히 얹혀 있었고, 짐칸마다 기름종이 보따리가 빼곡했다. 보따리마다 짐표가 달려 있었는데, 받는 이의 홈은 거의 다 닳아 손끝으로도 읽히지 않았다."}, {"s": null, "t": "진소랑은 짐표를 하나씩 뒤집어 보다가 손을 멈추었다. 볕뉘의 보따리만은 홈이 깊었다. 누군가 칼끝을 세 번 네 번 눌러 가며 새긴 글씨였다."}, {"s": "river_alliance:jin", "t": "이 사람은 받는 이를 꼭 찾으라고 이렇게 깊게 판 거예요. 수향 뱃사람들은 짐표를 보면 알아요. 홈이 깊으면 귀한 짐이에요. 돈이 아니라, 사람한테 귀한 짐."}, {"s": null, "t": "진소랑이 보따리 끈을 조심스럽게 풀었다. 기름종이 안에서 누빈 버선 한 켤레와 접힌 편지 한 장이 나왔다. 버선은 열 살 남짓한 아이 발에 맞을 만한 크기였고, 편지 글씨는 하얗게 바래 한 자도 남아 있지 않았다."}, {"s": "river_alliance:jin", "t": "구름나루 장부방 사환이라… 일흔 해 전에 사환이었으면 그때 열 살쯤 됐겠네요. 그럼 지금은 여든이 넘었고요."}, {"s": null, "t": "진소랑이 버선을 손바닥 위에 올려놓고 오래 보았다. 그러다 무언가 떠오른 듯 고개를 들었다."}, {"s": "river_alliance:jin", "t": "선창 끝에서 그물 깁는 영감님이 계세요. 제가 태어나기 전부터 거기 앉아 계셨대요. 사람들이 개동 영감이라고 불러요. 어려서 장부방 심부름을 했다는 얘기를 들은 적이 있어요."}, {"s": "river_alliance:jin", "t": "이 보따리를 들고 구름나루로 가요. 다만 그냥 내밀 수는 없어요. 수향에서는 큰 소식을 전할 때 차부터 내요. 받는 사람이 손에 뭘 쥐고 들어야 덜 떨리거든요. 영초 차를 좀 우려 가 주세요. 영감님 몫이랑 제 몫이랑요."}]'::jsonb, '{"xp": 3244}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_cargo', 3, '얼굴 자리', '구름나루에 간다, 영초 차을(를) 만든다, 영초 차을(를) 넘긴다', '{"at": ["river_ferry"], "tasks": [{"t": "travel", "r": ["river_ferry"], "n": 1}, {"t": "craft", "items": ["spirit_tea"], "n": 2}], "give": {"spirit_tea": 2}}'::jsonb, '[{"s": null, "t": "구름나루 선창 끝에서 늙은 사내 하나가 해를 등지고 앉아 그물을 깁고 있었다. 등이 굽었고 손등에 검버섯이 앉았는데, 그물 바늘을 놀리는 손만은 젊은 뱃사람처럼 빨랐다."}, {"s": null, "t": "진소랑이 영초 차 한 잔을 노인 곁에 내려놓고 쭈그려 앉았다. 노인이 바늘을 멈추지 않은 채 고개만 조금 들었다."}, {"s": "q:sx_md_gaedong", "t": "도방이 이 끝까지 다 오고, 무슨 일인가. 그물 값 깎으러 온 얼굴은 아니구먼."}, {"s": null, "t": "진소랑이 기름종이 보따리를 노인 무릎에 올려놓고 짐표를 노인 손바닥에 쥐여 주었다. 노인은 짐표의 홈을 손끝으로 더듬다가 바늘을 떨어뜨렸다. 바늘이 선창 판자 틈으로 굴러 들어갔다."}, {"s": "q:sx_md_gaedong", "t": "개동이라. …내 이름이 새겨져 있구먼. 장부방 사환 개동. 맞아, 어려서 그 심부름을 했지. 그런데 보낸 이가… 볕뉘?"}, {"s": null, "t": "노인은 「볕뉘」라는 글자를 몇 번이고 손끝으로 쓸었다. 그러는 동안 노인의 눈이 허공 어딘가를 헤매었다."}, {"s": "q:sx_md_gaedong", "t": "이상한 일이구먼. 나는 어머니가 있었던 걸 아네. 누가 나를 이 나루에 심부름꾼으로 보냈으니까. 그런데 평생 어머니 얼굴이 떠오르지 않았어. 떠올리려고 하면 그 자리가 하얗게 비어 있었지. 어디서 왔는지도 생각나지 않았고."}, {"s": "q:sx_md_gaedong", "t": "다들 그러는 줄 알았네. 늙으면 다 그런 줄."}, {"s": null, "t": "나는 노인에게 등도 이야기를 했다. 흰 밤에 갇힌 옛 도성과 마른 물길에 얹힌 배들, 그 배 가운데 소등 전날 떠나지 못한 짐배를 차례로 들려주었다. 노인은 버선을 꺼내 제 무릎 위에 펼쳐 놓았다."}, {"s": "q:sx_md_gaedong", "t": "열 살짜리 발이구먼. 그해 겨울에 신으라고 보냈겠지. 그러고는 일흔 해를 물길에 얹혀 있었고."}, {"s": null, "t": "노인이 버선 한 짝을 집어 들고 볼에 대고 있다가, 진소랑을 돌아보며 품에서 낡은 돈주머니를 꺼냈다."}, {"s": "q:sx_md_gaedong", "t": "짐표에 뱃삯은 받을 때라 적혀 있지. 받았으니 내야지. 수향 짐은 뱃삯을 안 내면 안 받은 걸로 친다고 배웠네."}, {"s": null, "t": "진소랑이 노인의 손을 돈주머니째 감싸 쥐고 노인 품으로 도로 밀어 넣었다. 웃는 얼굴이었지만 눈가가 붉었다."}, {"s": "river_alliance:jin", "t": "일흔 해 동안 배달을 못 했으니, 그 뱃삯은 수향이 떼먹은 셈으로 칠게요. 도방이 뱃삯을 안 받는 건 연맹 장부에도 없는 일이에요."}, {"s": null, "t": "노인은 한참 말이 없다가 그물 바늘이 빠진 판자 틈을 내려다보았다."}, {"s": "q:sx_md_gaedong", "t": "볕뉘라는 이름은 이제 알았는데, 그 이름이 무얼 하던 사람인지 모르겠구먼. 잉어찜 집이라 했지. 그 집이 아직 거기 있다면… 조사원, 나는 이 다리로 그 물길까지는 못 가네. 그 집 자리를 한 번만 봐 주게. 무엇이 남았는지."}]'::jsonb, '{"xp": 3244}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_cargo', 4, '화덕 위 차림표', '옛 나루 저자에 간다, 옛 나루 저자에 원정을 다녀온다', '{"at": ["old_ferry_market"], "tasks": [{"t": "travel", "r": ["old_ferry_market"], "n": 1}, {"t": "expedition", "r": ["old_ferry_market"], "n": 1}]}'::jsonb, '[{"s": null, "t": "잉어찜 집은 빈 좌판 줄이 끝나는 자리에 있었다. 지붕은 내려앉았지만 흙으로 쌓은 화덕은 무너지지 않았고, 화덕 위에 큰 찜솥 하나가 뚜껑을 덮은 채 얹혀 있었다."}, {"s": null, "t": "화덕 뒤 벽에 나무 차림표가 걸려 있었다. 먹은 바랬지만 차림표도 칼로 새긴 것이라 손끝으로 읽혔다. 「청씨 잉어찜 · 한 그릇 두 푼 · 아이는 한 푼.」 맨 아래 귀퉁이에 작게 「개동이 오는 날은 공짜」라고 새겨져 있었다."}, {"s": null, "t": "나는 그 귀퉁이를 오래 손끝으로 눌렀다. 홈 안에 묵은 기름때가 끼어 미끈거렸다. 사람들이 오가며 그 줄을 손으로 자주 쓸었던 자리 같았다."}, {"s": null, "t": "찜솥 뚜껑을 들어 올리자 솥 안은 말라 있었다. 솥 바닥에 잉어 비늘 몇 장이 하얗게 바랜 채 붙어 있었고, 솥 옆에 손잡이가 닳은 나무 국자가 걸려 있었다. 국자 자루에도 칼로 새긴 이름이 있었다. 「볕뉘」였다."}, {"s": null, "t": "나는 국자를 기름종이에 싸서 품에 넣었다. 노인은 얼굴을 떠올리지 못한다고 했지만, 냄새라면 다를지도 몰랐다. 청씨 잉어는 우물 밑 물굴에 지금도 살고 있었다. 차림표대로 잉어찜 두 그릇을 쪄서, 한 그릇은 노인 몫으로 한 그릇은 진소랑 몫으로 구름나루까지 들고 가기로 했다."}]'::jsonb, '{"xp": 3244}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_cargo', 5, '공짜인 날', '청씨 잉어찜을(를) 만든다, 구름나루에 간다, 청씨 잉어찜을(를) 넘긴다', '{"at": ["river_ferry"], "tasks": [{"t": "craft", "items": ["cheong_carp_steam"], "n": 2}, {"t": "travel", "r": ["river_ferry"], "n": 1}], "give": {"cheong_carp_steam": 2}}'::jsonb, '[{"s": null, "t": "선창 끝의 개동 영감은 그 자리에 그대로 앉아 있었다. 그물은 무릎 옆으로 밀어 두었고, 손에는 버선 한 짝을 쥐고 있었다. 진소랑이 노인 곁에서 차를 다시 데우고 있었다."}, {"s": null, "t": "나는 잉어찜 한 그릇을 노인 앞에, 한 그릇을 진소랑 앞에 내려놓고 품에서 국자를 꺼내 노인에게 건넸다. 노인은 국자 자루의 홈을 엄지로 더듬다가, 그릇에서 올라오는 김에 얼굴을 묻듯이 고개를 숙였다."}, {"s": "q:sx_md_gaedong", "t": "…이 냄새는 알겠구먼. 얼굴은 끝내 안 떠오르는데, 이 냄새는 알겠어. 솥뚜껑 여는 소리랑 같이 오던 냄새야. 누가 콧노래를 불렀지. 「개동이 왔네, 개동이 왔네」 하고."}, {"s": null, "t": "나는 차림표 귀퉁이에 새겨져 있던 줄을 노인에게 들려주었다. 개동이 오는 날은 공짜라던 그 줄이었다. 노인의 어깨가 들썩이더니, 웃는 것 같기도 하고 우는 것 같기도 한 소리가 노인에게서 새어 나왔다."}, {"s": "q:sx_md_gaedong", "t": "공짜라. 그 집에서 나는 한 번도 값을 낸 적이 없었겠구먼. 그래서 버선에도 뱃삯을 받을 때 내라 했나. 내가 커서 갚으라고."}, {"s": null, "t": "진소랑이 데운 차를 노인의 손에 쥐여 주었다. 노인은 차 대신 국자를 쥐고 있던 손을 가슴께로 가져갔다."}, {"s": "q:sx_md_gaedong", "t": "조사원, 그 이름을 한 번 불러 보아도 되겠나. 여든 해 동안 한 번도 못 불러 본 이름이라, 입에 붙을지 모르겠네."}, {"s": null, "t": "나는 고개를 끄덕였다. 노인은 국자를 가슴에 댄 채 「볕뉘」 하고 천천히 불렀고, 한 번 더 조금 더 크게 「어머니. 볕뉘」 하고 불렀다."}, {"s": null, "t": "노인의 입김이 금빛 실 한 가닥으로 엉겨 국자 자루의 이름 위에 내려앉았다. 노인이 국자를 쥔 손을 펴 보았다. 자루가 미지근했다."}, {"s": "q:sx_md_gaedong", "t": "따뜻하구먼. 얼굴은 몰라도… 이제 이름은 아네."}, {"s": null, "t": "진소랑이 장부를 펴고 붓을 들었다. 장부의 줄 하나에 「옛 나루 잉어찜 집 볕뉘」라고 적고, 그 아래 「아들 개동」이라고 적었다. 값 칸에는 아무것도 적지 않았다."}, {"s": "river_alliance:jin", "t": "매향한테 이 줄을 연맹 새 장부에 옮겨 적으라고 할게요. 값 칸은 비워 두고요. 해마다 동지에 이 이름을 연맹이 같이 부를게요. 영감님 혼자 부르시지 않게요."}, {"s": null, "t": "노인이 진소랑의 장부를 곁눈질하다가, 비어 있는 값 칸에서 눈을 떼지 못했다. 노인의 입가에 주름이 깊게 잡혔다."}, {"s": "q:sx_md_gaedong", "t": "도방이 공짜 장사를 다 하는구먼. 이 나루도 많이 변했어."}, {"s": null, "t": "노인은 잉어찜을 한 숟가락 떠먹고 한참 눈을 감았다. 선창 끝에 해가 기울어 노인의 그림자가 강물 위로 길게 늘어났다."}]'::jsonb, '{"xp": 3244, "gil": 197, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mds_lampshop', 'side', '제작·등지기 쉼막', '쉼막의 등 하나', '등지기 쉼막의 등 하나를 늘 켜 두는 수향 뱃사람 함박이 불꽃이 자꾸 가늘어진다며 도움을 청한다. 등을 고치다 마루 밑에서 명등지기 윤슬의 연장함과 수첩이 나오고, 그 등에 붙일 이름을 처음으로 알게 된다.', 'lamp_rest', 48, '{mdq_10}'::text[], null, 1429, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mds_lampshop' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_lampshop', 1, '가늘어지는 불꽃', '가늘어지는 불꽃', '{"at": ["lamp_rest"]}'::jsonb, '[{"s": null, "t": "등지기 쉼막 한가운데 기둥에 등 하나가 걸려 있었다. 등도에 밤이 돌아온 뒤에도 쉼막 사람들은 저녁마다 그 등 아래 모여 밥을 먹었는데, 오늘은 그 불빛이 처마 끝까지 닿지 못하고 기둥 언저리에서 맴돌았다."}, {"s": null, "t": "등 아래에서 덩치 큰 아낙 하나가 기름 단지를 끌어안고 쪼그려 앉아 있었다. 아낙은 심지를 바늘로 돋우다가 불꽃이 파르르 줄어들자 「아이고」 하고 바늘을 내려놓았다."}, {"s": "q:sx_md_hambak", "t": "아이고, 손님이 다 보고 계셨네. 저는 함박이에요. 여기 처마 고치고 사는 수향 뱃사람들 맏이고요. 이름이 함박이라 다들 웃는 얼굴로 기억해 줘요."}, {"s": "q:sx_md_hambak", "t": "우리가 이 쉼막에 처음 들어왔을 때 이 등이 기둥에 걸려 있었어요. 꺼진 채로요. 기름은 반쯤 차 있고. 수향 뱃사람은 새 거처에 들면 등부터 하나 켜는 게 법이라, 제가 켰죠. 그 뒤로 하루도 안 꺼뜨렸어요."}, {"s": null, "t": "함박이 등을 올려다보았다. 등롱 종이에 무언가 적혀 있던 자국이 있었지만 글씨는 하얗게 바래 있었다."}, {"s": "q:sx_md_hambak", "t": "그런데 요 며칠 불꽃이 자꾸 가늘어져요. 기름도 넣고 심지도 돋웠는데요. 이 등이 꺼지면 쉼막에 저녁이 없어져요. 다들 이 등 아래서 밥을 먹는데."}, {"s": "q:sx_md_hambak", "t": "기름부터 넉넉히 넣어 보려고요. 기름은 늘 옹심이가 붉은 사당 골목 곳간에서 얻어 오는데, 요 며칠 몸살이 나서 누워 있어요. 손님, 그 골목에서 끊긴 등 기름을 좀 거둬 와 주실래요? 굳었어도 데우면 풀린대요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_lampshop', 2, '마루 밑의 연장함', '붉은 사당 골목에서 끊긴 등 기름을(를) 모은다', '{"at": ["lamp_rest"], "tasks": [{"t": "gather", "items": ["severed_lamp_oil"], "r": ["red_shrine_lane"], "n": 3}]}'::jsonb, '[{"s": null, "t": "내가 끊긴 등 기름을 들고 돌아오자 함박은 등 고치던 마루 위에서 판자 하나를 들어 올리고 있었다. 기름 단지를 놓으려다 썩은 판자를 밟아 발이 빠졌다고 했다."}, {"s": null, "t": "판자 밑 어둠 속에 나무 연장함 하나가 들어 있었다. 함 뚜껑에 칼로 새긴 이름이 있었다. 「윤슬」이었다."}, {"s": null, "t": "함 안에는 심지 가위와 종이 바르는 솔과 작은 기름 깔때기가 가지런히 누워 있었다. 연장마다 손잡이가 같은 자리만 반들반들 닳아 있었고, 맨 밑에 손바닥만 한 수첩 한 권이 깔려 있었다."}, {"s": null, "t": "함박이 글을 잘 못 읽는다며 손사래를 치고는 수첩을 내게 내밀었다. 나는 마루에 걸터앉아 수첩을 펼쳤다. 바랜 글씨였지만 붓을 눌러 쓴 자국이 남아 겨우 읽혔다."}, {"s": null, "t": "「남문 기둥 등, 심지 갈아 줌. 사당 골목 넷째 집 등, 종이 덧댐. 나루 잉어찜 집 등, 아이 이름 종이 새로 붙임.」 줄마다 등 하나와 그 등에 한 일이 적혀 있었다. 도성의 등을 고치는 사람의 일지였다."}, {"s": null, "t": "수첩 뒤쪽은 글씨가 달랐다. 서두르는 손이 쓴 듯 획이 흔들렸고, 장마다 한두 줄씩만 적혀 있었다."}, {"s": null, "t": "첫 장에는 「동짓날 밤. 종소리 셋이 울렸다. 도성 등이 다 꺼졌다. 다들 남문 물길로 나간다」라고 적혀 있었고, 그 아래에 「나는 남는다. 쉼막 등 하나는 꺼뜨리지 않는다. 누가 돌아오면 길을 찾게」라는 줄이 이어져 있었다."}, {"s": null, "t": "다음 장에는 「이튿날. 쉼막 등은 탄다. 손끝이 잿빛이다」라고 적혀 있었고, 그다음 장에는 「사흘째 새벽」이라는 말만 남아 있었다."}, {"s": null, "t": "수첩은 거기서 끝나 있었다. 내가 마지막 장까지 읽어 주자 함박이 연장함 곁에 털썩 주저앉았다. 큰 손이 무릎 위에서 바들바들 떨렸다."}, {"s": "q:sx_md_hambak", "t": "아이고… 아이고, 그럼 제가 처음 왔을 때 기름이 반쯤 차 있던 게… 그 사람이 마지막으로 채워 둔 기름이었네요. 일흔 해 동안 그대로."}, {"s": "q:sx_md_hambak", "t": "저는 날마다 「등지기 님」 하고 인사했어요. 누가 이 등을 지켰는지 몰라서, 그냥 등지기 님이라고요."}, {"s": null, "t": "나는 수첩 맨 앞장을 다시 펼쳤다. 거기에는 「불꽃이 가늘어지면 종이를 갈 것. 종이가 바래면 불이 이름을 못 찾는다. 종이는 관아 처마의 등롱 종이가 질기다. 심지는 꺼진 등롱의 심지로」라고 등 고치는 법이 적혀 있었다."}, {"s": null, "t": "함박이 눈물을 훔치고 수첩 앞장을 들여다보았다. 글자는 못 읽어도 그 장에 그려진 등롱 그림만은 알아보는 얼굴이었다."}, {"s": "q:sx_md_hambak", "t": "관아 처마면 꺼진 관아 터 말이죠. 우리 뱃사람들은 그 흰 골목엔 안 가요. 무서워서요. 심지도 꺼진 등롱에서 거둔 걸 써야 한대요. 손님, 이번 한 번만 부탁드려요. 이 등은 제가 고칠게요. 그 사람 연장으로요."}]'::jsonb, '{"xp": 4326}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_lampshop', 3, '이름 붙이는 손', '꺼진 관아 터에서 바랜 등롱 종이을(를) 모은다, 명등 심지을(를) 넘긴다', '{"at": ["lamp_rest"], "tasks": [{"t": "gather", "items": ["bleached_lantern_paper"], "r": ["dark_yamen"], "n": 4}], "give": {"lamp_wick_core": 2}}'::jsonb, '[{"s": null, "t": "함박은 바랜 등롱 종이를 받아 들고 윤슬의 솔로 등롱 살에 풀을 먹였다. 커다란 손이 그 솔을 쥐니 솔이 이쑤시개처럼 작아 보였지만, 함박은 숨까지 참아 가며 종이를 한 장씩 붙였다."}, {"s": null, "t": "심지를 갈 차례가 되자 함박이 윤슬의 심지 가위를 집었다. 가위 손잡이의 닳은 자리에 함박의 엄지가 꼭 맞게 들어갔다. 함박이 그 손잡이를 한참 내려다보았다."}, {"s": "q:sx_md_hambak", "t": "이 사람도 엄지가 굵었나 봐요. 저처럼요. …손님, 종이는 다 붙였는데요. 수첩에 등마다 이름 종이를 붙였다고 적혀 있잖아요. 이 등에는 누구 이름을 붙여야 해요?"}, {"s": null, "t": "함박이 빈 종이 한 장과 붓을 내밀었다. 나는 연장함 뚜껑에 새겨진 이름을 가리키며, 이 등을 마지막까지 켜 둔 사람의 이름을 붙이자고 했다."}, {"s": null, "t": "함박은 고개를 크게 끄덕이더니, 제 손으로는 글씨를 예쁘게 못 쓴다며 붓을 다시 내게 쥐여 주었다. 나는 빈 종이에 「윤슬」이라고 적었다. 함박이 그 종이를 등롱 한가운데에 붙이고 손바닥으로 꾹꾹 눌렀다."}, {"s": "q:sx_md_hambak", "t": "수첩에 하나 더 적혀 있었죠. 「쉼막 등은 늘 둘. 하나가 꺼지면 하나로 옮겨 붙인다.」 우리는 이제껏 하나로만 버텼어요. 하나 더 있어야겠어요. 손님, 명등 등롱 두 개만 지어 주세요. 하나는 짝으로 걸고, 하나는 옹심이가 사당 골목 상갓집에 빌려 드릴 등으로 쓸게요."}, {"s": "q:sx_md_hambak", "t": "그리고 오늘 밤은 여기서 같이 저녁 드시고 가요. 이 등이 제대로 타는지 다 같이 봐야죠. 밥은 제가 퍼 드릴게요. 많이요."}]'::jsonb, '{"xp": 4326}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_lampshop', 4, '등지기 님 말고', '명등 등롱을(를) 만든다, 등지기 쉼막에서 쉰다, 명등 등롱을(를) 넘긴다', '{"at": ["lamp_rest"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}, {"t": "rest", "r": ["lamp_rest"], "n": 1}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "저녁이 되자 쉼막의 뱃사람들이 하나둘 등 아래로 모여들었다. 함박은 밥을 고봉으로 퍼서 사람들 앞에 놓았고, 내 그릇에는 그보다 더 높이 담았다. 기둥에는 새 종이를 바른 등과 내가 지은 명등 등롱이 나란히 걸려 있었다."}, {"s": null, "t": "밥을 다 먹고 나자 함박이 늘 하던 대로 등 앞에 섰다. 입을 열다 말고 함박은 등롱 한가운데 붙은 이름 종이를 올려다보았다."}, {"s": "q:sx_md_hambak", "t": "아이고, 오늘은 인사가 달라야겠네. …등지기 님 말고요."}, {"s": null, "t": "함박이 숨을 크게 들이쉬었다. 「윤슬 님. 오늘도 고맙습니다.」 함박의 입김이 흩어지지 않고 금빛 실 한 가닥으로 엉겨 등롱 종이의 이름 위에 내려앉았다."}, {"s": null, "t": "가늘던 불꽃이 곧게 섰다. 불빛 가장자리에 아주 옅은 금빛이 번지더니, 불빛이 기둥을 넘어 처마 끝까지 천천히 퍼져 나갔다. 뱃사람들이 밥그릇을 든 채 고개를 들었다."}, {"s": null, "t": "맨 끝에 앉은 젊은 뱃사람이 「윤슬 님」 하고 따라 불렀고, 곁에 앉은 뱃사람이 이어서 그 이름을 불렀다. 함박이 그 소리를 들으며 소매로 눈가를 꾹 눌렀다."}, {"s": "q:sx_md_hambak", "t": "이름을 알고 부르니까 이렇게 다르네요. 저는 이제껏 남의 집 문간에서 「여보세요」만 하고 있었던 거예요. 일흔 해를 혼자 지킨 사람한테요."}, {"s": "q:sx_md_hambak", "t": "연장은 제가 물려받을게요. 수첩도 제가 이어서 적을래요. 글은 잘 못 쓰지만, 손님이 하나만 가르쳐 주고 가요. 「윤슬」 두 글자요. 날마다 이 등 앞에서 쓰게요."}, {"s": null, "t": "나는 함박의 큰 손에 붓을 쥐여 주고 그 손을 잡아 두 글자를 천천히 함께 썼다. 획이 삐뚤었지만 함박은 종이를 들어 올려 등불에 비춰 보며 크게 웃었다."}, {"s": null, "t": "그 밤 쉼막에는 처음으로 등 둘이 나란히 탔다. 함박은 자기 전에 밥 한 그릇을 더 퍼서 기둥 아래 놓아두었다."}]'::jsonb, '{"xp": 4326, "gil": 197, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
