insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mds_scale', 'side', '조사·정리소', '저울을 내리는 날', '명등청이 정리소의 가늠 저울을 내리기로 하고, 겁 많은 서리 문수가 그 일을 맡는다. 먹손이었던 저울추지기 업동과 함께 저울을 풀고, 봉연 수위 표 맨 아래에 새 줄을 적고, 저울추는 구중 봉연 문 앞의 판자를 누르는 돌이 된다.', 'jeongni_vault', 49, '{mdq_17}'::text[], null, 1434, '[]'::jsonb, true, null, null)
