delete from public.world_quest_steps where quest_id = 'mds_scale' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_scale', 1, '공문을 든 서리', '공문을 든 서리', '{"at": ["jeongni_vault"]}'::jsonb, '[{"s": null, "t": "정리소 우물 쇠 손잡이 끝에서 서리 문수가 공문을 가슴에 꼭 안고 서 있었다. 발 하나는 맨 아래 칸에 걸쳐 두었고, 다른 발은 정리소 돌바닥에 내려놓지 못한 채 허공에 떠 있었다."}, {"s": null, "t": "문수는 나를 보자 반가움과 두려움이 뒤섞인 얼굴로 손을 흔들다가, 손잡이를 놓칠 뻔해 다시 움켜쥐었다."}, {"s": "q:dh_munsu", "t": "조사원님! 아, 다행이다, 혼자 내려가야 하는 줄 알았거든요! 명등청에서 공문이 내려왔거든요. 정리소 가늠 저울을 내리라고요. 근데 그 일을 제가 맡았거든요. 정청 서리 가운데 정리소 문을 지켜 본 사람이 저랑 희수 서리뿐이라서요."}, {"s": "q:dh_munsu", "t": "희수 서리는 명부를 엮느라 바쁘고요. 그러니까 제가… 제가 해야 하거든요. 근데 저 저울이 무섭거든요. 사람 키만 하잖아요. 이름을 다는 저울이잖아요!"}, {"s": null, "t": "내가 문수의 팔을 잡아 끌어 내리자 문수는 눈을 질끈 감고 돌바닥에 발을 디뎠다. 먹 도랑의 먹물은 더 흐르지 않았고, 저울 받침 둘레의 촛불 일곱은 꺼진 채 굳어 있었다."}, {"s": null, "t": "저울 앞에 사내 하나가 등을 보이고 앉아 저울추를 마른 천으로 닦고 있었다. 사내는 인기척에 손을 멈추고, 곁에 놓인 등잔 쪽으로 손바닥을 내밀어 돌바닥에 비친 제 손 그림자를 한참 보더니 일어섰다."}, {"s": "q:sx_md_eopdong", "t": "정청에서 오셨습니까. 업동이라 합니다. 이 저울추를 닦던 사람입니다. 마흔 해를 닦았습니다. 이제 닦을 까닭이 없는 줄 알면서도, 손이 먼저 천을 쥡니다."}, {"s": null, "t": "문수가 사내의 발밑을 힐끔 내려다보고는 화들짝 고개를 들었다. 두 손을 내젓느라 공문이 구겨졌다."}, {"s": "q:dh_munsu", "t": "아, 먹손… 아니, 먹손이셨던 분이시죠? 그, 그림자 있으시네요! 있으시거든요! 저 지금 확인한 거 아니거든요!"}, {"s": null, "t": "업동이 문수의 말에 아주 조금 웃고는 저울 뒤쪽 시렁을 가리켰다. 추가 빠져나간 빈 홈이 여럿 보였다."}, {"s": "q:sx_md_eopdong", "t": "저울을 풀려면 추부터 내려야 합니다. 그런데 무거운 추 몇은 먹 도랑으로 굴러 떨어졌습니다. 도랑이 마른 뒤에도 바닥에서 검은 손들이 올라와 그 추를 움켜쥐고 놓지 않습니다. 그 손들을 먼저 풀어 보내 주셔야 합니다. 시렁 둘레에 떨어진 추도 찾아 주시고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_scale', 2, '도랑으로 온 목소리', '먹 도랑 검은 손을(를) 물리친다, 정리소을(를) 살핀다', '{"at": ["jeongni_vault"], "tasks": [{"t": "win", "m": ["dd_vault_1"], "n": 8}, {"t": "search", "r": ["jeongni_vault"], "n": 3}]}'::jsonb, '[{"s": null, "t": "검은 손들이 추를 놓고 도랑 바닥으로 스러지자 업동이 추를 하나씩 받아 시렁에 올렸다. 추마다 밑바닥에 해가 하나씩 새겨져 있었다. 백 년 전부터 올해까지, 한 해에 추 하나였다."}, {"s": null, "t": "문수는 저울 옆 벽의 봉연 수위 표 앞에 서 있었다. 맨 아래 줄 「삼백십이」를 올려다보던 문수가 손에 쥔 붓을 떨었다."}, {"s": "q:dh_munsu", "t": "이거… 지워야 하는 거예요? 공문엔 저울을 내리라고만 적혀 있거든요. 표 얘기는 없거든요. 근데 이걸 그대로 두면 누가 또 이 표대로 셀까 봐 무섭거든요."}, {"s": null, "t": "업동이 문수 곁으로 와 섰다. 업동은 대답하기 전에 또 한 번 등잔에 손바닥을 비춰 보았다."}, {"s": "q:sx_md_eopdong", "t": "지우지 마십시오. 이 방 저울 옆에 걸린 서식에 적혀 있었습니다. 「거둔 이름은 지우지 않고 적어 둔다.」 저는 마흔 해를 그 글 앞에서 추를 닦았습니다. 그 글만은 맞는 말이었습니다."}, {"s": null, "t": "그때 마른 먹 도랑 깊은 데서 쿵, 쿵 돌을 두드리는 소리가 올라왔다. 문수가 비명을 지르며 내 등 뒤로 숨었다. 소리 뒤로 낮고 또박또박한 목소리가 도랑을 타고 들려왔다."}, {"s": "q:m_yun", "t": "거기 누구 있습니까. 구중 봉연 아홉째 문 앞입니다. 문지기 윤도한입니다. 도랑이 말라서 소리가 더 잘 올라가는 모양입니다."}, {"s": null, "t": "문수가 내 등 뒤에서 고개만 빼꼼 내밀었다. 붓을 쥔 손이 아직 덜덜 떨렸다."}, {"s": "q:dh_munsu", "t": "무, 문지기님이요? 도랑에서 사람 목소리가 나니까 심장이 떨어지는 줄 알았거든요!"}, {"s": null, "t": "도랑 깊은 데서 잠깐 웃음 섞인 숨소리가 올라왔다. 문지기의 목소리가 조금 낮아졌다."}, {"s": "q:m_yun", "t": "놀라게 해서 미안합니다. 알려 드릴 것이 있습니다. 아홉째 문 앞 수위 표석을 재 보았습니다. 물이 한 치 내려갔습니다. 백 년 만에 처음입니다."}, {"s": "q:m_yun", "t": "다만 문 아래 물길에서 판자가 자꾸 떠오릅니다. 물이 빠지면서 바닥 판자가 들뜨는 것 같습니다. 판자를 눌러 둘 무거운 것이 있으면 좋겠습니다. 정리소에 무거운 쇳덩이가 많다고 들었습니다."}, {"s": null, "t": "업동이 시렁의 추들을 돌아보았다. 마흔 해 닦은 쇳덩이들이 등잔 빛에 둔하게 빛났다."}, {"s": "q:sx_md_eopdong", "t": "이것들은 이름을 달던 추입니다. 이제 판자나 누르면 되겠습니다. 그게 이것들한테도 낫겠습니다."}, {"s": "q:sx_md_eopdong", "t": "저울 기둥을 풀 연장이 있어야 합니다. 기둥 이음새가 백 년 묵은 쇠못이라 맨손으로는 안 빠집니다. 추는 무거운 놈들만 골라 따로 내려 주십시오."}]'::jsonb, '{"xp": 4495}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_scale', 3, '새로 적는 줄', '정리소에서 가늠 저울추을(를) 모은다, 장비 수리 도구을(를) 만든다, 장비 수리 도구을(를) 넘긴다', '{"at": ["jeongni_vault"], "tasks": [{"t": "gather", "items": ["balance_weight"], "r": ["jeongni_vault"], "n": 3}, {"t": "craft", "items": ["repair_kit"], "n": 2}], "give": {"repair_kit": 2}}'::jsonb, '[{"s": null, "t": "업동은 내가 지어 온 장비 수리 도구로 저울 기둥의 쇠못을 하나씩 뽑았다. 못이 빠질 때마다 끼이익 소리가 정리소 돌방마다 울렸다. 문수는 그 소리가 날 때마다 어깨를 움츠렸지만 기둥 아래를 받친 손은 놓지 않았다."}, {"s": null, "t": "마지막 못이 빠지자 저울이 천천히 기울었다. 업동과 내가 저울대를 받아 돌바닥에 눕혔다. 늘 한쪽으로 내려앉아 있던 저울 접시가 처음으로 반듯하게 바닥에 닿았다."}, {"s": null, "t": "문수가 수위 표 앞에 다시 섰다. 문수는 붓에 먹을 찍고 한참 숨을 고르더니, 「삼백십이」 아래 빈자리에 「올해 — 거둔 이름 없음. 부른 이름 — 」까지 새 줄을 적었다."}, {"s": null, "t": "문수의 붓이 「부른 이름」 뒤에서 멈추었다. 문수가 나를 돌아보았다."}, {"s": "q:dh_munsu", "t": "여기 몇이라고 적어야 해요? 첫 명등제 때 부른 이름이요. 정청에서 부른 것만 해도 셀 수가 없었거든요. 고찰이랑 장터랑 나루랑 다 합치면… 누가 셌는지도 모르겠거든요."}, {"s": null, "t": "업동이 문수의 붓 끝을 내려다보았다. 이번에는 등잔에 손을 비추지 않고 바로 말했다."}, {"s": "q:sx_md_eopdong", "t": "그럼 그렇게 적으십시오. 마흔 해 동안 이 표는 늘 셀 수 있는 숫자만 적었습니다. 한 줄쯤은 못 센다고 적어도 됩니다."}, {"s": null, "t": "문수가 붓을 다시 들어 「부른 이름 — 다 못 셈」이라고 적었다. 적고 나서 문수는 제 글씨를 들여다보다 풋 웃었다. 업동도 따라 웃었다. 마흔 해 동안 처음 웃는 사람처럼 어색한 웃음이었다."}, {"s": null, "t": "웃음소리가 잦아들자 마른 도랑 아래에서 다시 돌 두드리는 소리가 났다. 문지기의 목소리가 이번에는 한결 가볍게 올라왔다."}, {"s": "q:m_yun", "t": "거기 무슨 일입니까. 웃음소리가 도랑으로 다 내려옵니다. 정리소에서 웃음소리가 나는 것은 처음 듣습니다."}, {"s": null, "t": "문수가 도랑 쪽으로 몸을 숙이고 두 손을 입가에 모았다."}, {"s": "q:dh_munsu", "t": "아, 아무것도 아니거든요! 지금 추를 가지고 내려갈게요! 갈 거거든요! …조사원님이 같이 가 주시면요."}]'::jsonb, '{"xp": 4495}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_scale', 4, '문 너머의 물음', '구중 봉연에 간다, 가늠 저울추을(를) 넘긴다', '{"at": ["sealed_abyss"], "tasks": [{"t": "travel", "r": ["sealed_abyss"], "n": 1}], "give": {"balance_weight": 3}}'::jsonb, '[{"s": null, "t": "구중 봉연 아홉째 문 앞에는 문 아래 물길로 이어지는 돌 턱이 있었다. 그 턱 아래에서 젖은 판자 몇 장이 물살 없이도 들썩들썩 떠올라 있었다. 문 옆 바위 틈의 작은 등잔에서 흰 불씨 하나가 타고 있었다."}, {"s": null, "t": "업동이 저울추를 하나씩 판자 위에 내려놓았다. 추가 놓일 때마다 판자가 쑥 가라앉았고, 들뜨던 물소리가 잦아들었다. 마지막 추를 놓자 문 아래가 고요해졌다."}, {"s": null, "t": "문 너머에서 윤도한이 문에 손바닥을 대는 소리가 났다. 문지기의 목소리는 문틈을 지나 조금 먹먹하게 들렸다."}, {"s": "q:m_yun", "t": "조용해졌습니다. 고맙습니다. 그런데 거기, 추를 내려놓으신 분. 손이 아주 익숙하신 분 같습니다. 성함이 어찌 되십니까."}, {"s": null, "t": "업동이 문 앞에서 굳었다. 업동은 습관처럼 등잔 쪽으로 손바닥을 내밀었다가, 그 손을 천천히 거두었다."}, {"s": "q:sx_md_eopdong", "t": "…정리소에 내려온 뒤로 제 이름을 물어 준 사람이 없었습니다. 먹손한테는 다들 일만 물었으니까요. 마흔 해 만에 대답해 봅니다."}, {"s": "q:sx_md_eopdong", "t": "업동입니다. 저울추지기 업동."}, {"s": null, "t": "문 너머에서 잠깐 아무 소리도 나지 않았다. 이윽고 윤도한이 문틈에 입을 대고 또박또박 불렀다. 「업동 님.」 문틈으로 금빛 입김 한 가닥이 새어 나와 업동의 가슴께에 닿았다."}, {"s": null, "t": "업동이 가슴께에 손을 얹었다. 그 손이 떨렸다. 문수가 코를 훌쩍이며 업동의 소매를 잡았다."}, {"s": "q:dh_munsu", "t": "저도 불러 드릴게요. 업동 님. …제 이름은 문수거든요. 서리 문수요. 문지기님도 알아 두세요."}, {"s": null, "t": "문 너머에서 문지기가 문에 이마를 대는 듯한 소리가 났다. 목소리가 문틈에 바짝 붙어 들려왔다."}, {"s": "q:m_yun", "t": "문수 서리. 업동 님. 해마다 동지에 문 안쪽에서 두 분 이름도 함께 부르겠습니다. 부를 이름이 늘어서 좋습니다. 문틈의 두 분한테도 말벗이 늘었다고 전하겠습니다."}, {"s": null, "t": "업동은 바위 틈 등잔의 흰 불씨를 오래 바라보다가, 돌바닥에 비친 제 그림자를 한 번 내려다보고, 이번에는 확인하지 않아도 된다는 듯 고개를 들었다."}]'::jsonb, '{"xp": 4495, "gil": 201, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mds_seven', 'side', '제작·맹약 마당', '일곱 자리 등롱', '첫 명등제가 끝난 뒤, 무녀를 내려놓은 단비가 맹약 마당 일곱 자리의 등롱을 닦고 기름을 채우겠다고 나선다. 명등청 첫 명부를 엮는 희수가 그 자리마다 등롱지기를 적으러 온다. 해마다 할 일의 첫해다.', 'pact_court', 50, '{mdq_17}'::text[], null, 1435, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mds_seven' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_seven', 1, '엿 장수 말고', '엿 장수 말고', '{"at": ["pact_court"]}'::jsonb, '[{"s": null, "t": "맹약 마당에 밤이 내려앉아 있었다. 둥근 돌상 둘레 일곱 자리의 등롱은 마당 싸움 밤에 켜졌다가 다시 꺼진 채였고, 갓마다 흰 밤 서리가 하얗게 엉겨 붙어 있었다. 밤이 돌아온 뒤에도 그 서리는 녹지 않았다."}, {"s": null, "t": "돌상 곁에 단비가 기름 항아리 하나를 끌어안고 앉아 있었다. 오른손으로 걸레를 쥐었고, 먹빛으로 굳은 왼손은 무릎 위에 얹어 두었다. 단비가 나를 보고 오른손을 번쩍 들었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님! 딱 맞춰 오셨네요. 이거 보세요, 등롱이 다 꺼졌어요. 명등제 끝나고 아무도 안 닦았나 봐요. 내년 동지까지 이대로 두면 갓이 다 삭아 버릴 거예요."}, {"s": "red_moon_cult:danbi", "t": "저 이제 무녀가 아니잖아요. 대장님한테 엿 장사를 같이 하자고 했더니 동업은 안 하고 장부만 적어 주겠대요. 그래서 일을 하나 찾았어요. 이 마당 등롱 닦는 거요. 해마다요. 대장님은 관아 터에서 칼 닦고 계세요. 오늘은 따라오지 말라고 했어요. 제가 혼자 할 수 있는 일이 있다는 걸 보여 드리려고요."}, {"s": null, "t": "단비는 걸레를 이로 물고 오른손으로 등롱 갓을 붙잡아 보다가, 등롱이 기우뚱하자 얼른 걸레를 뱉었다."}, {"s": "red_moon_cult:danbi", "t": "…혼자 할 수 있는 일이라고 했는데요, 한 손으로는 좀 어렵네요. 왼손이 안 잡혀서요. {이름} 님은 왼쪽 맡아 주세요. 저는 오른쪽 할게요. 딱 반반이네요."}, {"s": null, "t": "단비가 마당 가장자리를 가리켰다. 꺼진 등롱 몇이 제자리를 떠나 먹 도랑 쪽에서 비척비척 걸어 다니고 있었다. 빈 등롱 안에서 웅얼거리는 소리가 새어 나왔다."}, {"s": "red_moon_cult:danbi", "t": "쟤네도 원래 이 마당 등롱이었대요. 꺼진 채로 너무 오래 서 있다가 걸어 나갔대요. 불쌍하긴 한데, 저렇게 돌아다니면 닦을 수가 없잖아요. 얌전히 보내 주세요. 그리고 갓에 낀 서리도 좀 긁어 주세요. 서리가 낀 채로 기름을 부으면 불이 안 붙어요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_seven', 2, '일곱 자리의 이름', '꺼진 자리 등롱을(를) 물리친다, 맹약 마당에서 흰 밤 서리을(를) 모은다', '{"at": ["pact_court"], "tasks": [{"t": "win", "m": ["dd_pact_1"], "n": 8}, {"t": "gather", "items": ["white_night_frost"], "r": ["pact_court"], "n": 4}]}'::jsonb, '[{"s": null, "t": "서리를 긁어낸 등롱 갓 아래쪽에 자리마다 다른 문양이 새겨져 있었다. 단비가 오른손으로 갓을 하나씩 돌려 가며 문양을 읽었다. 정청의 인장, 북령의 종, 적월의 초승달, 수향의 닻, 천명의 혼천의, 남명의 불꽃, 그리고 일곱째 자리에는 아무 문양도 없이 연꽃 한 송이가 검게 새겨져 있었다."}, {"s": "red_moon_cult:danbi", "t": "일곱째가 흑련 자리예요. 마당에서 {이름} 님이 서셨던 데요. 그때는 경황이 없어서 몰랐는데, 연꽃이 새겨져 있었네요."}, {"s": null, "t": "단비가 적월 자리 등롱 앞에 섰을 때 걸레질하던 손이 느려졌다. 초승달 문양이 거꾸로 누워 있었다. 붉은 사당 골목에서 처음 본 그 옛 문양이었다."}, {"s": "red_moon_cult:danbi", "t": "우리 옛날 문양이에요. 그날 사당에서 이걸 보고 얼굴이 하얘졌었죠. 지금은… 괜찮아요. 이 달은 원래 이렇게 누워 있던 거예요. 우리가 거꾸로 외웠던 거지."}, {"s": null, "t": "단비가 들어 보인 등롱 둘은 정청 자리와 흑련 자리의 것이었는데, 갓이 찢기고 살이 부러져 있었다. 마당 싸움 때 흰 소매에 가장 많이 덮였던 두 자리였다."}, {"s": "red_moon_cult:danbi", "t": "이 둘은 닦아서 될 게 아니에요. 새로 지어야겠어요. 명등 등롱으로요. 흰 밤이 걷힌 뒤에도 이름 글자를 비추는 건 그 등롱뿐이래요. 감찰관님이 그러셨어요."}, {"s": "red_moon_cult:danbi", "t": "기름도 모자라요. 이 항아리는 반밖에 안 남았거든요. 끊긴 등 기름은 우리 골목에 제일 많아요. 붉은 사당 골목이요. 제가 같이 가고 싶은데… 사실 그 골목은 아직 혼자 들어가기 좀 그래요. 그러니까 {이름} 님이 다녀와 주시면, 저는 여기서 나머지 다섯을 닦고 있을게요. 한 손으로 천천히요."}]'::jsonb, '{"xp": 4666}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_seven', 3, '등롱지기 칸', '붉은 사당 골목에서 끊긴 등 기름을(를) 모은다, 명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["pact_court"], "tasks": [{"t": "gather", "items": ["severed_lamp_oil"], "r": ["red_shrine_lane"], "n": 4}, {"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "내가 돌아오자 다섯 자리의 등롱이 반들반들하게 닦여 있었다. 단비는 돌상 곁에 주저앉아 오른팔을 주무르고 있었다. 그 곁에 서리 희수가 새 명부 한 권을 무릎에 펴 놓고 앉아 있었다."}, {"s": null, "t": "희수가 나를 보고 일어나 고개를 숙였다. 명부 줄마다 끝에 손바닥만 한 칸이 반듯하게 그어져 있었다."}, {"s": "q:mk_hisu", "t": "조사원. 명등청에서 왔습니다. 맹약 마당 등롱 일곱을 누가 맡는지 명부에 적어 두라고 해서요. 자리마다 한 줄씩, 끝에 등롱지기 칸을 그었습니다. 칸은 제가 긋는 게 버릇이 돼서요."}, {"s": null, "t": "단비가 오른손을 번쩍 들었다. 희수가 붓을 건네자 단비는 적월 자리 줄의 칸에 제 이름을 적었다. 오른손으로 쓴 글씨는 삐뚤삐뚤했지만, 칸 밖으로는 한 획도 나가지 않았다."}, {"s": "red_moon_cult:danbi", "t": "적월 자리는 제가 할게요. 이제 축문은 안 들리지만 기름 냄새는 제일 잘 알거든요. 희수 서리님, 칸 밖으로 안 나갔죠? 오른손으로 처음 쓴 이름이에요."}, {"s": null, "t": "희수가 명부를 받아 들고 칸 가장자리를 손끝으로 따라 그어 보았다. 희수의 입가가 조금 풀렸다."}, {"s": "q:mk_hisu", "t": "안 나갔습니다. 반듯해요. 제가 처음 칸을 그었을 때 제 글씨보다 더요."}, {"s": null, "t": "희수가 다른 줄들을 넘기며 붓끝으로 짚었다. 북령·수향·천명·남명 줄은 비어 있었다. 정청 줄에는 이미 「한설」이 적혀 있었다."}, {"s": "q:mk_hisu", "t": "나머지 세력 자리는 그 세력에서 사람을 보내 주기로 했어요. 그런데 흑련 자리 줄이 남았어요. 흑련은 이름을 맡아 주는 곳이라 제 이름을 명부에 잘 안 적는대요. 구슬 행수가 그러셨어요."}, {"s": null, "t": "단비가 오른쪽 귀를 희수 쪽으로 기울이고 듣다가, 손뼉 대신 오른손으로 제 무릎을 탁 쳤다."}, {"s": "red_moon_cult:danbi", "t": "그럼 {이름} 님이죠. 마당에서 그 자리에 서셨잖아요. 흑련 사람이 없어서 대신 서 주셨잖아요.", "fac_not": "black_lotus", "spec": 2, "grp": 1}, {"s": "red_moon_cult:danbi", "t": "그럼 {이름} 님이죠. 마당에서 그 자리에 서셨잖아요. 게다가 흑련 패까지 차셨으니까, 흑련 사람이 흑련 자리를 맡는 거예요.", "fac": "black_lotus", "spec": 1, "grp": 1}, {"s": null, "t": "희수가 붓을 내게 내밀었다."}, {"s": null, "t": "나는 붓을 받았지만 바로 적지 않고, 흑련에서 누가 오기 전까지만 맡았다가 그 사람이 오면 이 칸을 넘기겠다고 했다. 희수가 고개를 끄덕이며 내 이름 옆에 작게 「맡아 둠」이라고 덧붙였다.", "fac_not": "black_lotus", "spec": 2, "grp": 2}, {"s": null, "t": "나는 붓을 받아 흑련 자리 줄의 칸에 내 이름을 적었다. 희수가 칸 가장자리를 손끝으로 한 번 쓸어 보았다.", "fac": "black_lotus", "spec": 1, "grp": 2}, {"s": null, "t": "희수가 명부를 돌려받아 그 줄을 한참 들여다보았다. 굳어 있던 희수의 어깨가 조금 내려갔다."}, {"s": "q:mk_hisu", "t": "흑련이 이름을 맡아 주는 곳이라면, 조사원은 흑련 자리를 맡아 주는 사람이네요. 셈이 맞습니다.", "fac_not": "black_lotus", "spec": 2, "grp": 3}, {"s": "q:mk_hisu", "t": "흑련 분이 흑련 자리에 이름을 적으셨네요. 구슬 행수가 들으시면 셈이 맞다고 하실 거예요.", "fac": "black_lotus", "spec": 1, "grp": 3}, {"s": null, "t": "단비가 기름 항아리를 끌어당겨 품에 안고 등롱 일곱을 한 바퀴 둘러보았다. 왼쪽 어깨를 자꾸 움츠렸다."}, {"s": "red_moon_cult:danbi", "t": "이제 불만 켜면 돼요. 오늘 밤은 여기서 지켜봐요. 첫해니까요. 왼쪽이 자꾸 추우니까 밤빛 차도 좀 끓여 주세요. 희수 서리님 몫까지요."}]'::jsonb, '{"xp": 4666}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mds_seven', 4, '왼쪽에서 한 말', '밤빛 차을(를) 만든다, 맹약 마당에서 쉰다, 밤빛 차을(를) 넘긴다', '{"at": ["pact_court"], "tasks": [{"t": "craft", "items": ["night_tea"], "n": 2}, {"t": "rest", "r": ["pact_court"], "n": 1}], "give": {"night_tea": 2}}'::jsonb, '[{"s": null, "t": "그 밤 일곱 자리의 등롱에 차례로 불이 켜졌다. 새로 지은 정청 자리와 흑련 자리 등롱이 마지막으로 켜지자 일곱 불빛이 돌상 둘레에 원을 그렸다. 원 안쪽 돌바닥에 우리 셋의 그림자가 나란히 드리웠다."}, {"s": null, "t": "단비가 품에서 방울을 꺼내 오른손으로 딸랑 흔들었다. 축문은 들리지 않았지만 방울 소리는 마당 끝 먹 도랑 너머까지 멀리 굴러갔다. 단비가 그 소리를 따라 고개를 돌렸다."}, {"s": "red_moon_cult:danbi", "t": "들려요? 방울 소리가 이렇게 멀리 가요. 등도에서는 소리가 세 걸음 밖으로 안 나갔잖아요. 이제는 저 끝까지 가요."}, {"s": null, "t": "희수가 밤빛 차를 내려놓고 명부 맨 끝 줄에 「올해 등롱 일곱, 다 켬」이라고 적고는, 그 줄을 오래 내려다보았다."}, {"s": "q:mk_hisu", "t": "내년에도 이 줄을 적을 수 있으면 좋겠어요. 그다음 해에도요. 명부는 한 번 적으면 끝인 줄 알았는데, 해마다 이어 적는 명부도 있네요."}, {"s": null, "t": "단비가 차를 홀짝이다가 나를 돌아보았다. 단비의 왼쪽에 앉아 있던 나는, 오늘 고생했다고, 등롱지기 단비라고 불러도 되겠냐고 단비에게 물었다."}, {"s": null, "t": "단비는 고개를 갸웃하며 나를 빤히 보다가 웃음을 터뜨렸다."}, {"s": "red_moon_cult:danbi", "t": "방금 뭐라고 하셨어요? 왼쪽 귀는 엿 사러 갔어요. 오른쪽으로 다시 해 주세요."}, {"s": null, "t": "나는 일어나 단비의 오른쪽으로 옮겨 앉아 같은 말을 한 번 더 했다. 「등롱지기 단비.」 금빛 입김 한 가닥이 단비의 가슴께에 닿았다."}, {"s": "red_moon_cult:danbi", "t": "…좋네요. 무녀 단비보다 좋아요. 대장님한테도 이렇게 불러 달라고 해야겠어요. 대장님은 원래 제 오른쪽에 서시니까 한 번에 들리겠네요."}, {"s": null, "t": "단비가 붓을 들어 일곱 등롱 아랫단마다 「내년 동지 · 맹약 마당」이라고 작게 날짜를 적었다. 마지막으로 흑련 자리 등롱 아래에 이르러, 단비는 날짜 옆에 연꽃 한 송이를 서툴게 그려 넣었다."}, {"s": "red_moon_cult:danbi", "t": "이건 {이름} 님 자리 표시예요. 내년에 오시면 이 등부터 켜 주세요. 약속이에요."}]'::jsonb, '{"xp": 4666, "gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
