insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_cheongpa_2', 'side', '외전·명등기', '다음 배', '다시 뜬 청씨 배에 「태우지 못한 아이들」 서른둘의 이름을 싣고, 일흔 해 전 값을 치른 아이들이 내린 물가까지 데려간다. 그 물가 돌계단에 진소랑의 할머니가 남긴 글씨가 있다.', 'old_ferry_market', 50, '{mde_cheongpa_1}'::text[], null, 1437, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mde_cheongpa_2' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_cheongpa_2', 1, '서른두 장', '서른두 장', '{"at": ["old_ferry_market"]}'::jsonb, '[{"s": null, "t": "청씨 배가 뜬 지 이틀째 아침이었다. 청파는 선실 탁자에 수향 새 장부를 펴 놓고, 장부에 옮겨 적힌 서른두 이름을 한 장에 하나씩 새 종이에 옮겨 쓰고 있었다."}, {"s": null, "t": "청파는 이름 하나를 쓸 때마다 붓을 내려놓고 숨을 골랐다. 쇳소리 섞인 숨이 선실 안에 가늘게 울렸다. 맞은편에 앉은 매향이 청파가 쓴 종이를 장부와 한 장씩 맞춰 보았다."}, {"s": "river_alliance:maehyang", "t": "열아홉째 이름 받침이 틀렸어요. 「돌」이 아니라 「똘」이에요. 증조할아버지 글씨가 그래요."}, {"s": null, "t": "청파가 붓을 든 채 장부를 들여다보다가 머리를 긁었다."}, {"s": "q:sn_cheongpa", "t": "아, 「똘이」요. 다시 쓸게요. …행수님은 틀린 거 하나도 안 놓치시네요."}, {"s": null, "t": "매향이 종이 한 장을 청파 쪽으로 밀며 주판알을 하나 내렸다."}, {"s": "river_alliance:maehyang", "t": "장부 셈하는 사람이 이름 셈을 틀리면 안 되죠. 이 장부엔 값 칸이 없으니 이름이라도 맞아야 해요."}, {"s": null, "t": "뱃전 쪽에서 갈매가 선실 안으로 고개를 들이밀었다. 갈매의 엄지에는 아직 헝겊이 감겨 있었다."}, {"s": "southern_remnant:galmae", "t": "종이는 다 썼어? 그걸 어디 붙일 건데. 뱃전에 서른두 장을 다 붙이면 배가 종이배 되겠다."}, {"s": null, "t": "청파가 종이 더미를 두 손으로 감싸며 고개를 저었다."}, {"s": "q:sn_cheongpa", "t": "등롱에 붙일 거예요. 명등 등롱이요. 이름을 붙인 명등 등롱은 누가 불러 주는 동안 기름 없이 탄대요. 등롱 하나에 열 장 남짓씩 나눠 붙이면 셋이면 돼요."}, {"s": null, "t": "서하람이 뱃전을 더듬으며 갈매 뒤를 따라 선실로 들어왔다. 서하람이 탁자 위 종이 더미에 손바닥을 얹고 두께를 가늠했다."}, {"s": "q:r71_seoharam", "t": "종이가 모자라요. 이름 종이를 등롱 겉에 다 붙이고 나면 바람막이 종이가 없어요. 관아 터 처마에 바랜 등롱 종이가 많던데요."}, {"s": null, "t": "청파가 붓을 내려놓고 나를 돌아보았다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님, 관아 터에 다녀와 주실래요? 등롱도 지어 주시고요. 저는 이름을 마저 쓸게요. 숨을 안 쓰고 할 수 있는 건 이것뿐이라서요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_cheongpa_2', 2, '다섯 걸음', '꺼진 관아 터에서 바랜 등롱 종이을(를) 모은다, 명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["old_ferry_market"], "tasks": [{"t": "gather", "items": ["bleached_lantern_paper"], "r": ["dark_yamen"], "n": 4}, {"t": "craft", "items": ["myeongdeung_lamp"], "n": 3}], "give": {"myeongdeung_lamp": 3}}'::jsonb, '[{"s": null, "t": "내가 지어 온 등롱 셋에 청파가 이름 종이를 나눠 붙였다. 청파는 한 장을 붙일 때마다 종이 위의 이름을 손끝으로 한 번씩 쓸었지만, 소리 내어 읽지는 않았다."}, {"s": "q:sn_cheongpa", "t": "이름은 밤에 부를게요. 그 애들이 가야 했던 데에서요. 여기서 부르면 또 선창에서 부르는 거잖아요."}, {"s": null, "t": "해가 기울 무렵 청파가 등롱 셋을 들고 배에서 내려 선창 계단으로 갔다. 옛 나루 저자의 선창 계단은 아래 세 칸이 물에 잠겨 있었다. 일흔 해 동안 물이 빠진 채 말라 있던 돌계단이었다."}, {"s": null, "t": "청파가 등롱을 계단 맨 아래 칸에 내려놓고 한참을 그 앞에 쪼그려 앉아 있다가, 하나씩 들어 배 위로 올렸다. 계단에서 뱃전까지는 다섯 걸음이었다. 청파는 세 번을 오가는 동안 그 다섯 걸음을 한 번도 서두르지 않았다."}, {"s": null, "t": "뱃전에서 등롱을 받아 뱃머리에 나란히 세우던 노들 영감이 마지막 등롱을 받아 들며 혀를 찼다."}, {"s": "river_alliance:nodeul", "t": "다섯 걸음이었구먼. 일흔 해 전에 이 다섯 걸음을 못 건넌 애들이 서른둘이야."}, {"s": null, "t": "계단 위에서 그 말을 들은 갈매가 발치의 돌을 툭 찼다. 돌이 물에 퐁 빠졌다."}, {"s": "southern_remnant:galmae", "t": "다섯 걸음. 할배가 내 줄 대신 맨 앞에 섰던 것도 명부에서는 한 줄이었다던데. 한 줄, 다섯 걸음. 다 그렇게 짧아."}, {"s": null, "t": "서하람이 갈매의 소매를 찾아 쥐었다. 아무 말도 하지 않았고, 갈매도 소매를 빼지 않았다."}, {"s": null, "t": "노들 영감이 닻을 올리고 청파에게 키를 넘겼다. 청파가 키를 잡자 배가 선창을 떠나 물길을 따라 천천히 미끄러졌다. 나는 약속대로 키 옆에 섰다."}, {"s": "river_alliance:nodeul", "t": "물길은 남문 수로 선착까지 이어진다. 그런데 물이 돌아오니 물귀들도 다시 헤엄을 치는구먼. 문패 문 것들이 물길 굽이마다 떠 있어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_cheongpa_2', 3, '내린 데', '문패 문 물귀을(를) 물리친다, 남문 수로 선착에 간다', '{"at": ["deungdo_landing"], "tasks": [{"t": "win", "m": ["dd_ferry_2"], "n": 8}, {"t": "travel", "r": ["deungdo_landing"], "n": 1}]}'::jsonb, '[{"s": null, "t": "물길 굽이의 물귀들은 문패를 문 채 뱃전을 들이받았다. 쓰러진 물귀가 문패를 떨어뜨릴 때마다 서하람이 물소리를 듣고 「또 하나요」 하고 셌다. 남문 수로 선착에 닿았을 때는 날이 저물고 있었다."}, {"s": null, "t": "선착 돌계단에 나와 있던 야영소 뱃사람들이 청씨 깃발을 보고 웅성거렸다. 말뚝마다 거룻배가 매여 있었고, 그 너머로 남문 물길이 봉인고 쪽 어둠을 향해 좁게 이어져 있었다."}, {"s": null, "t": "노들 영감이 물길 폭을 눈으로 재 보고 고개를 저었다."}, {"s": "river_alliance:nodeul", "t": "이 배로는 여기까지다. 남문 물길은 거룻배 두 척이 겨우 비켜 가는 폭이야. 여든둘이 빠져나간 길도 거룻배였다지."}, {"s": null, "t": "청파가 키를 쥔 채 말이 없었다. 매향이 장부를 펴 맨 뒷장을 짚었다. 구름나루 장부방 옛 장부에서 매향이 베껴 온 한 줄이 거기 적혀 있었다."}, {"s": "river_alliance:maehyang", "t": "청파, 이것 봐. 장부방 옛 장부 맨 끝에 있던 거야. 「소등 전날. 청씨 선단 배에서 거룻배 셋에 옮겨 실어, 남문 물길 끝 돌계단에 아이 열일곱 내림. 수향 사람이 받으러 감.」"}, {"s": "river_alliance:maehyang", "t": "그 애들이 내린 데가 남문 물길 끝이에요. 지금은 봉인고 아래 수로 어귀고요. 다음 배가 갔어야 할 데도 거기예요."}, {"s": null, "t": "청파가 매향의 장부를 받아 들고 그 줄을 오래 보았다. 청파의 숨소리가 거칠어졌다."}, {"s": "q:sn_cheongpa", "t": "그럼 거기까지 가요. 배가 못 가면… 깃발이라도 가요. 이 배 깃발을 거룻배에 달고, 등롱을 싣고요. 그럼 이 배가 간 거예요."}, {"s": null, "t": "노들 영감이 청파를 보고 껄껄 웃었다. 영감이 돛대 줄을 풀어 청씨 깃발을 내렸다."}, {"s": "river_alliance:nodeul", "t": "수향 사람 다 됐다고 할 것도 없지. 원래 수향 사람이니까. 거룻배는 내가 젓는다. 봉인고 수로 어귀 계단에 뭐가 붙어 있다는 소문이 있으니, 앞은 자네가 맡게."}, {"s": null, "t": "갈매가 등롱 하나를 들고 거룻배에 먼저 올랐다. 서하람이 갈매의 손을 잡고 뒤따랐다. 매향은 장부를 품에 넣고 구름나루로 심부름꾼 하나를 보냈는데, 무엇을 전하는지는 말하지 않았다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_cheongpa_2', 4, '돌계단의 글씨', '봉인고에 간다, 봉인고의 요괴를 물리친다', '{"at": ["seal_vault"], "tasks": [{"t": "travel", "r": ["seal_vault"], "n": 1}, {"t": "win", "r": ["seal_vault"], "n": 8}]}'::jsonb, '[{"s": null, "t": "봉인고 아래 수로 어귀 돌계단에 붙어 있던 것들은 압수물 함에서 기어 나온 손들이었다. 손들이 함 속으로 물러나자, 물에 잠긴 맨 아래 칸부터 위로 일곱 칸 이어진 돌계단이 드러났다."}, {"s": null, "t": "서하람이 계단 셋째 칸에 앉아 돌을 쓰다듬다가 손을 멈췄다. 손끝 아래 무언가 긁힌 자국이 있었다."}, {"s": "q:r71_seoharam", "t": "여기 글씨가 있어요. 아주 작아요. 못 같은 걸로 긁은 거예요. 하나, 둘… 줄이 여러 개예요."}, {"s": null, "t": "갈매가 등롱을 낮춰 계단을 비췄다. 셋째 칸부터 다섯째 칸까지 돌 위에 작은 글씨가 빼곡했다. 아이 손으로 긁은 삐뚤삐뚤한 이름들이었다. 매향이 장부를 펴 놓고 하나씩 세었다."}, {"s": "river_alliance:maehyang", "t": "열일곱이에요. 그날 내린 애들 이름이에요. 기다리는 동안 계단에 제 이름을 긁어 둔 거예요."}, {"s": null, "t": "청파가 계단에 엎드려 이름들을 하나씩 들여다보았다. 다섯째 칸 맨 끝, 이름 하나 아래에 한 줄이 더 긁혀 있었다. 청파가 그것을 소리 내어 읽었다."}, {"s": "q:sn_cheongpa", "t": "「차돌아 다음 배 타고 와. 여기서 기다릴게. — 모란.」"}, {"s": null, "t": "청파가 떨리는 입술을 깨물고 품에서 명단을 꺼내 첫 줄을 짚었다. 첫 줄은 「차돌」이었다. 청파가 쿨럭쿨럭 기침을 했고, 기침이 멎을 때까지 아무도 말하지 않았다."}, {"s": null, "t": "그때 수로 위쪽 돌계단에서 발소리가 났다. 도방 진소랑이 등롱을 든 수향 뱃사람 여럿을 데리고 내려오고 있었다. 매향이 보낸 심부름꾼이 진소랑에게 닿은 것이었다."}, {"s": "river_alliance:jin", "t": "매향이 「이리 오셔야 할 셈이 있다」고만 보냈길래요. 셈이라길래 주판까지 들고 왔는데… 주판은 필요 없겠네요.", "fac_not": "river_alliance", "spec": 2, "grp": 1}, {"s": "river_alliance:jin", "t": "연맹 사람들이 다 모였네요. 매향이 「이리 오셔야 할 셈이 있다」고만 보냈길래 주판까지 들고 왔는데… 주판은 필요 없겠네요.", "fac": "river_alliance", "spec": 1, "grp": 1}, {"s": null, "t": "진소랑이 계단에 무릎을 꿇고 앉아 긁힌 글씨를 보았다. 「모란」에 닿은 진소랑의 손끝이 멈췄고, 얼굴에서 웃음기가 천천히 사라졌다."}, {"s": "river_alliance:jin", "t": "…우리 할머니 이름이에요. 모란. 할머니가 그날 값을 치르고 배를 탄 아이였다는 건 알고 있었어요. 제가 도방이 되던 날 어머니가 일러 주셨거든요. 그래서 그 밤 셈을 제 손으로 해 두려고 장부방을 맡았고요."}, {"s": "river_alliance:jin", "t": "그런데 할머니는 동짓날마다 밥상에 밥그릇을 하나 더 놓으셨어요. 누구 거냐고 물으면 「다음 배 몫」이라고만 하셨죠. 할머니가 돌아가신 뒤에는 어머니가, 지금은 제가 놓아요. 그 그릇이 누구 몫인지는 끝내 못 셈했어요. 할머니가 선창에 두고 온 사람이 있었다는 것도요."}, {"s": null, "t": "진소랑이 웃으려다 그만두었다. 진소랑의 눈에서 눈물 한 줄기가 떨어져 돌계단 글씨 위에 번졌다."}, {"s": "river_alliance:jin", "t": "차돌이었네요, 그 그릇 주인이. 청파야, 나도 네 집이랑 다를 게 없어. 우리 집은 그 배 덕에 산 집이고, 그걸 알면서도 남의 집 셈만 먼저 했어."}, {"s": null, "t": "청파가 고개를 저으며 진소랑의 손등에 제 손을 얹었다."}, {"s": "q:sn_cheongpa", "t": "도방님 할머니는 기다리셨잖아요. 평생 밥그릇을 놓고요. 도방님도 그 그릇을 놓으셨고요. 그건… 그건 다른 거예요."}, {"s": null, "t": "노들 영감이 거룻배에서 청씨 깃발을 들고 올라와 계단 맨 위에 꽂았다. 깃발이 수로 바람에 펄럭였다."}, {"s": "river_alliance:nodeul", "t": "밤까지 기다리세. 이름은 밤에 불러야 닿는다지. 도방님도 오늘은 셈을 그만하고 앉으시게."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_cheongpa_2', 5, '다음 배', '봉인고에서 쉰다', '{"at": ["seal_vault"], "tasks": [{"t": "rest", "r": ["seal_vault"], "n": 1}]}'::jsonb, '[{"s": null, "t": "밤이 내렸다. 수로 어귀 위로 별 몇 개가 돋았고, 물 위에 별빛이 흔들렸다. 계단 위 청씨 깃발 아래에 등롱 셋이 나란히 놓여 있었다."}, {"s": null, "t": "청파가 다섯째 칸 「모란」 글씨 곁에 섰다. 첫 등롱을 두 손으로 들고 첫 이름 종이를 본 청파가 숨을 깊이 들이쉬었다."}, {"s": "q:sn_cheongpa", "t": "차돌."}, {"s": null, "t": "금빛 입김 한 가닥이 등롱의 이름 종이에 닿았다. 기름 한 방울 없는 등롱에 화르르 불이 붙었다."}, {"s": "q:sn_cheongpa", "t": "차돌. 그날 선창 맨 아래 칸에 있던 차돌. 다음 배가 왔어. 모란 누나가 이 계단에서 기다렸고, 그 뒤로도 평생 기다렸대."}, {"s": null, "t": "청파가 등롱을 「모란」 글씨 바로 곁에 내려놓고 다음 이름을 불렀다. 숨이 가빠 몇 번이나 쉬었다가 다시 불렀다."}, {"s": null, "t": "청파가 기침으로 말을 잇지 못할 때마다 갈매가 그 이름을 받아 불렀다. 서하람은 다음 이름 종이를 손끝으로 더듬어 일러 주었다. 노들 영감이 굵은 목소리로 따라 부르자 수향 뱃사람들이 그 뒤를 이었고, 매향은 장부에 동그라미를 하나씩 쳤다. 나도 불렀다."}, {"s": null, "t": "진소랑은 청파 곁에 서서 이름이 하나 불릴 때마다 함께 불렀다. 장부방에서 값을 부르던 목소리와 달리 낮고 느린 목소리였다."}, {"s": null, "t": "서른두 번째 이름이 불렸을 때 등롱 셋이 모두 저녁 빛깔로 타오르고 있었다. 이름 종이 서른둘의 불빛이 계단 위 아이들 글씨를 비췄다. 계단에 긁힌 열일곱 이름과 등롱에 붙은 서른두 이름이 같은 불빛 아래 있었다."}, {"s": null, "t": "청파가 계단에 털썩 주저앉아 기침을 했다. 매향이 주판을 내려놓았다."}, {"s": "river_alliance:maehyang", "t": "오늘 기침은 아흔일곱 번이에요. 백 번은 안 넘었어요. 도방님, 데려가셔도 되겠죠?"}, {"s": null, "t": "진소랑이 매향을 보며 웃었다. 이번에는 끝까지 웃는 얼굴이었다."}, {"s": "river_alliance:jin", "t": "행수. 오늘 셈은 그만해."}, {"s": null, "t": "진소랑이 계단 위 열일곱 이름 쪽으로 돌아앉았다. 손끝으로 아이들 글씨를 하나씩 짚었다."}, {"s": "river_alliance:jin", "t": "이 애들 이름도 불러야겠어요. 값을 치르고 배를 탔어도, 이 계단에서 울면서 기다린 건 똑같으니까요. 할머니 이름은 제가 부를게요. …모란."}, {"s": null, "t": "진소랑의 입김이 금빛으로 엉겨 「모란」 글씨 위에 내려앉았다. 내가 손끝을 대 보니 긁힌 글씨가 미지근했다."}, {"s": null, "t": "노들 영감이 품에서 무언가를 꺼냈다. 손바닥만 한 나무 배 두 척이었다. 돛대마다 실처럼 가는 청씨 깃발이 달려 있었다."}, {"s": "river_alliance:nodeul", "t": "물이 차오르던 밤에 잠이 안 와서 깎았다. 하나는 도방님 몫이요. 동짓날 그 밥그릇 옆에 놓으시게. 이제 다음 배가 왔으니."}, {"s": null, "t": "진소랑이 나무 배를 두 손으로 받아 들었다. 노들 영감이 다른 하나를 내게 내밀었다."}, {"s": "river_alliance:nodeul", "t": "이건 자네 몫이야. 용잠 수궁 물길을 묻던 조사원이 이번엔 배를 띄웠으니 갚을 게 있어야지. 연화 거북한테도 보여 주게."}, {"s": null, "t": "청파가 작은 칼을 꺼내 내가 받은 나무 배의 돛대 밑에 금을 그었다. 하나, 둘, 서른둘까지 다 긋고 나서 청파가 기침을 하며 웃었다. 쉰 목소리였지만 웃음은 맑았다."}, {"s": "q:sn_cheongpa", "t": "{이름} 님 배에도 서른둘을 다 태웠어요. 이번엔 긋다 만 금 없이요."}, {"s": "q:sn_cheongpa", "t": "내년 동지엔 진짜 배로 사람들을 실어 올게요. 구름나루에서 이 계단까지, 그리고 등도까지요. 도방님 밥그릇도 같이요. 이번엔 값을 안 받고요. 처음부터요."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_md_shipmodel": 1}, "title": "md_keep_cheongpa"}'::jsonb)
