insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_danbi_1', 'side', '외전·명등기', '반쪽 이름', '단비가 명등제 밤에 부른 아이 이름이 어느 고을 누구였는지 알려고, 정리소 명부와 적월 교주가 사들인 목록을 거슬러 오른다.', 'ledger_cellar', 50, '{mdq_17}'::text[], null, 1438, '[]'::jsonb, true, null, null)
