delete from public.world_quest_steps where quest_id = 'mde_danbi_2' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_danbi_2', 1, '사당 아래 엿 솥', '사당 아래 엿 솥', '{"at": ["red_plain"]}'::jsonb, '[{"s": null, "t": "적사 황무지 어귀의 사당은 붉은 모래 언덕 아래에 웅크리고 있었다. 처마에는 까마귀 두 마리가 앉아 있었고, 사당 아래 비탈에는 흙집 여섯 채가 모래바람을 등지고 붙어 있었다."}, {"s": null, "t": "흙집 가운데 한 집 앞마당에 가마솥이 걸려 있었다. 솥 안에서 엿물이 뭉근하게 끓어, 단내가 모래바람을 타고 언덕 위까지 올라왔다."}, {"s": null, "t": "솥 앞에 쪼그려 앉아 긴 나무 주걱으로 엿물을 젓던 노파가 우리를 보더니 주걱을 든 채로 일어섰다."}, {"s": "q:sx_md_eonnyeon", "t": "방울 무녀 아니냐. 해마다 애들 이마를 닦아 주러 오던. 올해는 늦었다. 애들은 다 장터로 내려가 버렸어."}, {"s": null, "t": "단비가 걸음을 멈추었다. 늘 먼저 웃던 얼굴이 굳어 있었다. 단비의 눈길이 노파의 집 마당 한쪽으로 갔는데, 둥근 돌테를 두른 우물이 붉은 모래로 반쯤 메워져 있었다."}, {"s": "red_moon_cult:danbi", "t": "할머니… 여기가 모래 우물 집이에요?"}, {"s": null, "t": "언년이 주걱으로 솥 테두리를 탁 두드렸다. 엿물 방울이 솥 안으로 떨어졌다."}, {"s": "q:sx_md_eonnyeon", "t": "모래가 들어찬 우물이 있는 집이 이 집 하나니까 그렇게들 부르지. 내 집이다. 왜."}, {"s": null, "t": "단비가 입을 열었다가 소리를 내지 못했다. 쪽지를 쥔 오른손이 품 앞에서 멈춰 있었다. 여운비가 단비의 오른쪽에서 한 걸음 나섰다."}, {"s": "north_league:yeo", "t": "할머니, 먼 길을 와서 목이 마르오. 엿 고는 일을 거들 테니, 해 질 때까지 마당에 있게 해 주시오."}, {"s": null, "t": "언년이 여운비의 하얗게 바랜 오른 눈과 단비의 먹빛 왼손을 차례로 보았다. 주걱 끝에서 엿물이 실처럼 늘어져 떨어졌다."}, {"s": "q:sx_md_eonnyeon", "t": "다들 성한 데가 하나씩 모자라구먼. 거들려면 거들어. 대신 엿 냄새를 맡고 언덕 너머에서 내려오는 것들부터 쫓아. 무슨 진인가 꺼졌다더니 그것들은 아직 안 꺼졌어. 땔감도 모자라고."}, {"s": null, "t": "언덕 너머 모래 둔덕에서 무언가가 사각사각 모래를 긁는 소리가 들렸다. 내가 언덕 쪽으로 걸음을 옮기자 단비가 그제야 숨을 내쉬며 내 뒤를 따랐다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_danbi_2', 2, '작은 짚신', '적사 황무지의 요괴를 물리친다, 적사 황무지에서 채집한다', '{"at": ["red_plain"], "tasks": [{"t": "win", "r": ["red_plain"], "n": 8}, {"t": "gather", "r": ["red_plain"], "n": 3}]}'::jsonb, '[{"s": null, "t": "언덕 너머의 것들은 모래 속에 반쯤 몸을 묻고 먹물을 핥던 것들이었다. 쓰러지자 먹이 굳어 붉은 모래 위에 검은 얼룩으로 남았다. 땔감을 한 짐 지고 내려오자 해가 언덕 너머로 기울고 있었다."}, {"s": null, "t": "여운비는 언년에게서 주걱을 넘겨받아 엿물을 젓고 있었다. 오른쪽이 보이지 않아 주걱이 자꾸 솥 테두리에 부딪혔지만, 젓는 박자는 흐트러지지 않았다."}, {"s": null, "t": "언년이 솥 곁에 서서 허리를 두드리며 그 손놀림을 지켜보다가 고개를 끄덕였다."}, {"s": "q:sx_md_eonnyeon", "t": "북쪽 사람치고 손이 꾸준하네. 엿은 손이 꾸준해야 안 눌어."}, {"s": null, "t": "단비는 마당 끝 모래 우물 앞에 쪼그려 앉아 있었다. 우물 돌테 곁에 작은 항아리 하나가 놓여 있었는데, 항아리 뚜껑에 엿 묻은 손바닥 자국이 바래지 않은 채 남아 있었다. 아이 손만 한 자국이었다."}, {"s": null, "t": "단비가 그 자국에 제 오른손을 겹쳐 보려다 손을 거두었다. 언년이 주걱을 든 채 단비 곁으로 걸어왔다."}, {"s": "q:sx_md_eonnyeon", "t": "그건 건드리지 마라. 내 엿 항아리다. 열 해 전부터 거기 두고 엿을 안 담았어."}, {"s": null, "t": "단비는 손을 무릎 위로 거두고 항아리만 내려다보았다. 목소리가 작았다."}, {"s": "red_moon_cult:danbi", "t": "왜 안 담으셨어요?"}, {"s": null, "t": "언년이 주걱 끝으로 항아리 뚜껑을 가리켰다가 거두었다. 주걱을 쥔 손등에 핏줄이 섰다."}, {"s": "q:sx_md_eonnyeon", "t": "모르겠다. 담으려고 하면 손이 안 가. 그 안에 짚신 한 켤레랑 저고리 하나가 들었어. 아이 거야. 누구 건지 모르겠는데 버리지를 못하겠어."}, {"s": null, "t": "언년이 항아리 뚜껑을 열었다. 안에는 작은 짚신 한 켤레와 소매가 짧은 무명 저고리가 개켜져 있었다. 짚신 앞코가 닳아 있었다."}, {"s": "q:sx_md_eonnyeon", "t": "열 해 전 겨울 어느 아침에 이 우물가에서 주웠어. 옷하고 신만 벗어 놓은 것처럼 있더라. 이 집에 누가 하나 더 살았던 것 같은데… 생각하면 얼굴 자리가 하얘. 이름도 안 떠올라."}, {"s": null, "t": "단비의 어깨가 떨렸다. 단비는 품에서 쪽지와 다발에서 떼어 온 장을 꺼내 언년 앞에 놓았다."}, {"s": "red_moon_cult:danbi", "t": "할머니. 그 애 이름은 앵두예요. 아홉 살이었어요. 열 해 전 동지에 정청 명부에서 붉은 줄이 그어졌어요. 그 이름을 흑련 거둠꾼이 맡아 두었고, 적월 교주님이 쌀 세 섬에 샀고… 제가 태웠어요. 열네 살 첫 서약 때요. 그 이름으로 제가 무녀가 됐어요."}, {"s": null, "t": "마당이 조용해졌다. 솥 안의 엿물만 보글보글 끓었다. 언년은 종이를 내려다보았다가 단비를 보았다. 노파의 손에서 주걱이 마당으로 툭 떨어졌다."}, {"s": "q:sx_md_eonnyeon", "t": "…나가."}, {"s": null, "t": "단비가 고개를 숙였다. 아무 말 없이 일어나 마당 밖으로 걸어 나간 단비는 사립문 밖 모래 위에 무릎을 꿇고 앉았다."}, {"s": null, "t": "여운비가 주걱을 주워 솥 곁에 세워 두고 단비의 오른쪽에 가서 앉았다. 나도 그 곁에 앉았다. 언년은 짚신이 든 항아리를 끌어안고 집 안으로 들어가 문을 닫았다."}, {"s": null, "t": "해가 지기 전에 나는 단비 몫으로 등롱 둘을 지어 두기로 했다. 앵두의 이름 종이를 붙일 명등 등롱과, 종이가 미끄러질 때를 대비한 여벌이었다. 몸이 없는 이름이라도, 밤이 오면 그 이름이 닿을 곳이 하나는 있어야 했다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_danbi_2', 3, '앵두야', '명등 등롱을(를) 만든다, 적사 황무지에서 쉰다, 명등 등롱을(를) 넘긴다', '{"at": ["red_plain"], "tasks": [{"t": "craft", "items": ["myeongdeung_lamp"], "n": 2}, {"t": "rest", "r": ["red_plain"], "n": 1}], "give": {"myeongdeung_lamp": 2}}'::jsonb, '[{"s": null, "t": "해가 지고 황무지에 밤이 내려앉았다. 모래바람이 잦아들자 별이 하나둘 돋았다. 나는 지어 온 등롱을 단비에게 건넸다."}, {"s": null, "t": "단비가 등롱 겉에 「앵두」라고 적은 종이를 붙였다. 먹빛으로 굳은 왼손 대신 오른손 하나로 붙이느라 종이가 두 번 미끄러졌고, 여운비가 종이 끝을 손가락으로 눌러 주었다."}, {"s": null, "t": "단비는 등롱을 무릎 위에 세우고 한참 사립문 안쪽을 바라보았다. 집 안은 불이 꺼져 있었다."}, {"s": "red_moon_cult:danbi", "t": "할머니가 나오실 때까지 안 부를 거예요. 그 이름은 할머니 앞에서 불러야 해요. 저 혼자 부르면 또 반쪽이에요."}, {"s": null, "t": "단비는 밤새 엿 장수 이야기를 했다. 무녀 노릇을 못 하게 됐으니 장터에서 엿을 팔 거라고, 대장님이 장부를 적어 주면 좋겠다고 했다. 이야기하는 동안에도 단비의 눈은 사립문을 떠나지 않았다."}, {"s": null, "t": "자정이 가까울 무렵 사립문이 끼익 열렸다. 언년이 짚신 항아리를 품에 안고 서 있었다. 노파의 눈가가 퉁퉁 부어 있었다."}, {"s": "q:sx_md_eonnyeon", "t": "들어와라. 밤이슬을 맞으면 그 손이 더 굳어. …그 이름, 내 앞에서 한 번 불러 봐."}, {"s": null, "t": "단비가 일어나 마당으로 들어갔다. 우물 돌테 곁에 등롱을 내려놓고 짚신 항아리 앞에 무릎을 꿇었다. 단비가 숨을 한 번 고르고 입을 열었다."}, {"s": "red_moon_cult:danbi", "t": "앵두야."}, {"s": null, "t": "단비의 입김이 흩어지지 않고 금빛 실로 엉겼다. 실이 등롱 쪽으로 날아가 이름 종이에 닿자, 기름 한 방울 붓지 않은 등롱에 화르르 불이 붙었다."}, {"s": "red_moon_cult:danbi", "t": "앵두야. 적사 황무지 사당 아랫마을, 모래 우물 집 앵두야. 아홉 살 앵두야. 미안해. 네 이름으로 무녀가 됐어. 이번엔 다 불러 줄게."}, {"s": null, "t": "등롱 불빛이 마당을 비췄다. 우물 돌테와 엿 솥과 항아리 뚜껑의 작은 손자국이 저녁 빛깔로 물들었다."}, {"s": null, "t": "언년이 항아리를 끌어안은 채 등롱을 바라보았다. 노파의 입술이 몇 번 달싹이더니, 노파의 눈이 천천히 커졌다."}, {"s": "q:sx_md_eonnyeon", "t": "…앵두. 앵두. 그래, 앵두였어. 볼에 엿을 묻히고 다니던… 솥 젓는 사이에 손을 넣어서 내가 주걱으로 손등을 때리면, 웃으면서 또 손을 넣던 애."}, {"s": null, "t": "언년이 무릎으로 기어 등롱 앞으로 다가갔다. 주름진 손이 등롱 종이를 더듬었다. 노파의 입김도 금빛으로 엉겨 등롱에 닿았다."}, {"s": "q:sx_md_eonnyeon", "t": "앵두야. 할미다. 할미가 열 해 동안 네 얼굴을 잊고 살았다. 하얀 자리만 들여다보고 살았어."}, {"s": null, "t": "노파의 어깨가 들썩였다. 단비가 오른손으로 노파의 등을 쓸었다. 언년은 그 손을 뿌리치지 않았다."}, {"s": null, "t": "등롱 불은 새벽까지 꺼지지 않았다. 언년과 단비가 번갈아 그 이름을 불렀다. 동이 틀 무렵 언년이 마당에 떨어진 주걱을 주워 들고 솥 테두리를 탁 두드렸다."}, {"s": "q:sx_md_eonnyeon", "t": "아침 엿을 고아야겠다. 앵두가 좋아하던 갱엿으로. 땔감을 더 해 와. 엿기름 낼 보리 순도 언덕에서 좀 뜯어 오고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_danbi_2', 4, '엿 항아리', '적사 황무지에서 채집한다', '{"at": ["red_plain"], "tasks": [{"t": "gather", "r": ["red_plain"], "n": 4}]}'::jsonb, '[{"s": null, "t": "땔감과 보리 순을 내려놓자 언년은 아침 내내 솥 앞을 떠나지 않았다. 엿물이 졸아들어 갈색으로 굳어 가자 노파가 뜨거운 엿을 건져 늘이기 시작했다."}, {"s": null, "t": "엿을 늘이는 일에는 두 손이 필요했다. 단비가 오른손으로 한쪽 끝을 잡고, 여운비가 남은 왼 눈으로 단비 손끝을 보며 다른 쪽 끝을 잡았다. 두 사람이 엿을 당겼다 접었다 할 때마다 갈색이 조금씩 하얘졌다."}, {"s": null, "t": "언년이 솥 곁에서 두 사람의 손끝을 매섭게 지켜보았다."}, {"s": "q:sx_md_eonnyeon", "t": "늘일수록 하얘지는 게 엿이다. 힘 빼지 마. 놓으면 다 눌어붙어."}, {"s": null, "t": "굳은 엿을 다 자르고 나자 언년이 짚신 항아리를 두 손으로 들고 단비 앞에 섰다. 짚신과 저고리는 등롱 곁 상자에 옮겨 두었고, 항아리 안에는 갓 자른 엿이 가득 담겨 있었다."}, {"s": "q:sx_md_eonnyeon", "t": "가져가. 열 해 동안 엿을 못 담던 항아리야. 오늘 처음 담았어."}, {"s": null, "t": "단비가 항아리를 받지 못하고 언년을 올려다보았다."}, {"s": "red_moon_cult:danbi", "t": "할머니, 이건 앵두 손자국이 있는 항아리잖아요. 제가 어떻게…"}, {"s": null, "t": "언년이 주걱으로 단비의 정수리를 톡 두드렸다. 아프지 않게 두드린 손이었다."}, {"s": "q:sx_md_eonnyeon", "t": "그러니까 가져가라는 거다. 밤새 장터에서 엿 장사를 한다고 떠들지 않았냐. 장터 애들 이마 닦아 주던 그 손으로 이 엿 하나씩 쥐여 줘. 앵두 엿이라고 하고."}, {"s": "q:sx_md_eonnyeon", "t": "용서는 내가 하는 게 아니다. 앵두가 하든지 말든지 하겠지. 나는 엿이나 고아 줄란다. 동짓밤마다 이 항아리를 들고 와서 그 이름을 불러. 그럼 엿값은 안 받는다."}, {"s": null, "t": "단비가 항아리를 끌어안았다. 뚜껑 위 작은 손자국 곁에 단비의 오른손이 얹혔다. 단비가 처음으로 입을 벌리고 소리 내어 울었다."}, {"s": null, "t": "여운비가 단비 곁에 서서 한참 그 우는 소리를 듣다가, 오른손을 들어 단비의 머리를 서툴게 한 번 쓰다듬었다."}, {"s": "north_league:yeo", "t": "…엿 장사를 한다면 장부는 내가 적겠소. 호송 장부밖에 안 적어 봤지만, 짐 수 세는 건 같소."}, {"s": null, "t": "단비가 우는 얼굴 그대로 여운비를 올려다보았다. 눈물이 턱 끝에서 뚝뚝 떨어졌다."}, {"s": "red_moon_cult:danbi", "t": "대장님… 그럼 동업이에요? 진짜로요?"}, {"s": null, "t": "여운비가 고개를 돌려 버렸다. 귀 끝이 빨갰다."}, {"s": "north_league:yeo", "t": "동업은 아니오. 장부만 적는 거요."}, {"s": null, "t": "단비가 눈물범벅이 된 얼굴로 웃음을 터뜨렸다. 언년이 혀를 차며 주걱으로 솥을 탁 두드렸다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님, 장부고에 들러요. 아저씨한테 알려 드려야 해요. 다온이도 공책에 집을 적어야 하고요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_danbi_2', 5, '나머지 반쪽', '흑련 장부고에 간다, 흑련 장부고에서 쉰다', '{"at": ["ledger_cellar"], "tasks": [{"t": "travel", "r": ["ledger_cellar"], "n": 1}, {"t": "rest", "r": ["ledger_cellar"], "n": 1}]}'::jsonb, '[{"s": null, "t": "장부고 금고 앞 침상에서 월하가 엽전을 튕기다가 우리를 보고 손을 멈추었다. 단비가 엿 항아리를 침상 머리맡에 내려놓았다. 다온이 뚜껑의 손자국을 보고 눈을 동그랗게 떴다."}, {"s": "q:mk_daon", "t": "누나, 이거 아기 손이에요. 제 손보다 작아요."}, {"s": null, "t": "단비가 다온 곁에 쪼그려 앉아 뚜껑의 손자국을 손가락으로 가리켰다."}, {"s": "red_moon_cult:danbi", "t": "앵두 손이야. 아홉 살이었대. 적사 황무지 사당 아랫마을, 모래 우물 집 애."}, {"s": null, "t": "다온이 공책을 펼쳐 맨 끝 줄을 찾았다. 다온은 혀끝을 내밀고 「앵두」 두 글자 옆에 「적사 황무지 사당 아랫마을 모래 우물 집 · 아홉 살 · 할머니 언년」이라고 또박또박 이어 적었다."}, {"s": "q:mk_daon", "t": "이제 반쪽 아니에요. 다 적었어요."}, {"s": null, "t": "월하가 엿 항아리를 오래 내려다보았다. 엽전을 쥔 오른손이 이불 위에 가만히 놓여 있었다."}, {"s": "q:mk_wolha", "t": "그 이름을 팔던 날, 쪽지를 접으면서 손이 떨렸어요. 이름만 받으면 손이 안 떨리는 게 거둠꾼인데. 사는 데를 들은 것도 아닌데, 이상하게 그 이름에서 단내가 나는 것 같았거든."}, {"s": null, "t": "월하가 단비를 보았다. 늘 능청스럽던 눈이 오늘은 조금 젖어 있었다."}, {"s": "q:mk_wolha", "t": "할머니는 뭐래요. 나를 욕하던가요?"}, {"s": null, "t": "단비가 침상 끝에 걸터앉아 월하의 오른손 위에 제 손을 잠깐 얹었다가 내렸다."}, {"s": "red_moon_cult:danbi", "t": "판 사람 얘기도 다 했어요. 할머니가 그러셨어요. 용서는 앵두가 하는 거래요. 대신 동짓밤마다 와서 부르래요."}, {"s": null, "t": "월하가 웃었다. 웃음 끝이 조금 떨렸다. 월하가 엽전을 오른손으로 튕기자, 엽전이 핑그르르 돌다가 엿 항아리 뚜껑 위에 탁 내려앉았다. 앵두의 손자국 바로 옆이었다."}, {"s": "q:mk_wolha", "t": "그럼 나도 동짓밤에 끼워 줘요. 판 사람이 부르면 안 될 것 같다고 했는데… 할머니가 그렇게 말했다면, 판 사람도 맨 뒤에 서서 따라 부르는 건 되겠죠."}, {"s": null, "t": "단비가 콧등을 찡그리며 웃었다. 장부고에 들어선 뒤 처음 보이는 웃음이었다."}, {"s": "red_moon_cult:danbi", "t": "아저씨는 맨 뒤에 서세요. 저는 맨 앞이고요."}, {"s": null, "t": "단비가 항아리에서 엿 하나를 꺼내 다온의 손에 쥐여 주고, 하나는 월하의 손바닥에 올렸다. 마지막 하나는 내 손에 쥐여 주었다."}, {"s": "red_moon_cult:danbi", "t": "{이름} 님이 첫 손님이에요. 앵두 엿이에요. 값은 안 받아요. 대신 내년 동지에 같이 가 줘요. 그 집 마당에도 등 하나는 켜야 하니까요."}, {"s": null, "t": "나는 엿을 입에 넣었다. 붉은 인장 일 때 백골 장터에서 단비가 내밀던 사탕보다 덜 달았고, 오래 씹혔다. 나는 내년 동지에 함께 가겠다고 했다."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_md_yeotjar": 1}, "title": "md_keep_danbi"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_galmae_1', 'side', '외전·명등기', '꺼져 가는 흰 불씨', '장무현이 떠난 뒤 잔불촌 큰 화로의 흰 불씨가 겨울 내내 사그라진다. 갈매는 장무현이 칠십 해 동안 화로 앞에서 무엇을 세었는지 찾아 다시 불을 하얗게 피운다.', 'dark_yamen', 50, '{mdq_17}'::text[], null, 1440, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mde_galmae_1' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_1', 1, '수로를 타고 온 서신', '수로를 타고 온 서신', '{"at": ["dark_yamen"]}'::jsonb, '[{"s": null, "t": "동지가 지나고 두 달 가까이 흘렀다. 등도에 밤이 내리면 꺼진 관아 터 마당에는 늘 구리 화로 불빛 하나가 켜졌다."}, {"s": null, "t": "갈매는 화로 앞 돌에 걸터앉아 장무현이 쓰던 부지깽이로 숯을 고르고 있었다. 그 곁에서 서하람이 담요를 두르고 앉아 화로 쪽으로 손바닥을 펴고 있었다. 숯이 탁 튈 때마다 서하람의 고개가 그 소리 쪽으로 돌아갔다."}, {"s": null, "t": "관아 앞 돌계단 아래에서 콜록콜록 기침 소리가 올라왔다. 청파가 남문 수로 선착에 배를 대 놓고 걸어 올라오는 길이었다. 청파는 마당에 들어서자마자 품에서 기름종이에 싼 서신 한 통을 꺼냈다."}, {"s": "q:sn_cheongpa", "t": "갈매 누님, 잔불촌에서 온 서신이에요. 소이 님이 흑련 심부름꾼 편에 보냈는데, 선착에서 제가 받아 왔어요. 꼭 누님 손에 드리래요."}, {"s": null, "t": "갈매가 서신을 받아 들고 겉봉을 오래 내려다보았다. 겉봉을 뜯는 손가락이 굼떴다."}, {"s": null, "t": "서하람이 화로 쪽으로 내밀었던 손을 거두고 갈매 쪽으로 고개를 돌렸다."}, {"s": "q:r71_seoharam", "t": "소리 내서 읽어 줘요, 갈매 씨. 저도 듣고 싶어요."}, {"s": null, "t": "갈매가 헛기침을 한 번 하고 서신을 화로 불빛 쪽으로 기울였다."}, {"s": "southern_remnant:soi", "t": "「갈매에게. 장을 화로 밑에서 꺼내던 날부터 장군님 화로의 흰 불씨가 조금씩 줄었사온데, 장군님이 떠나신 동지를 지나고부터는 날마다 눈에 띄게 작아지고 있사옵니다. 숯을 아무리 넣어도 붉은 불만 일고, 흰빛은 이제 쌀알만 하옵니다.」"}, {"s": "southern_remnant:soi", "t": "「장군님께서는 칠십 해 동안 밤마다 그 걸상에 앉아 무언가를 세셨사옵니다. 소녀는 무엇을 세시는지 끝내 여쭙지 못하였사옵니다. 걸상은 겨울 내내 비어 있사옵니다. 한 번 와 주시옵소서.」"}, {"s": null, "t": "갈매가 서신을 무릎 위에 내려놓았다. 부지깽이를 쥔 손이 화로 가장자리에서 멈춰 있었다."}, {"s": "southern_remnant:galmae", "t": "…안 가. 할배 없는 걸상을 보러 가기 싫어."}, {"s": null, "t": "서하람이 담요 밖으로 손을 내밀어 구리 화로의 따뜻한 쪽을 더듬었다. 손바닥이 흰 불씨가 있는 자리 위에서 멈췄다."}, {"s": "q:r71_seoharam", "t": "이상해요. 여기 불씨는 겨울 내내 그대로였죠? 갈매 씨가 그랬잖아요. 아직 하얗다고요."}, {"s": null, "t": "갈매가 멈춰 있던 부지깽이로 숯을 한 번 툭 건드리고 어깨를 으쓱했다."}, {"s": "southern_remnant:galmae", "t": "그야 내가 밤마다 할배를 부르니까. 자기 전에 한 번씩."}, {"s": null, "t": "서하람이 화로 쪽으로 얼굴을 돌린 채 한참 아무 말도 하지 않았다. 손끝으로 담요 귀퉁이를 접었다 폈다 했다."}, {"s": "q:r71_seoharam", "t": "그거예요. 등도 등롱은 누가 이름을 불러 주는 동안 기름 없이 타잖아요. 임금님의 등 역시 등도에서 나온 명등이고요. 장이 화로 밑에 있을 땐 장의 흰 불꽃이 같이 받쳐 줬을 거예요. 이제 장은 재가 됐으니까, 남은 건 부르는 소리뿐이에요."}, {"s": "q:r71_seoharam", "t": "그러니까 장군님이 칠십 해 동안 센 건… 아마 이름이었을 거예요. 그 이름들을 아무도 안 부르니까 큰 화로가 식는 거고요. 관측이에요. 예언 말고요."}, {"s": null, "t": "갈매가 부지깽이를 화로에 걸쳐 두고 무릎을 끌어안았다. 갈매는 붉은 숯을 오래 노려보다가 나를 올려다보았다."}, {"s": null, "t": "나는 같이 가겠다고 했다. 걸상에는 앉지 않아도 되니 무엇을 세셨는지만 찾아보자고 했다."}, {"s": null, "t": "갈매가 입술을 비죽 내밀고 화로 쪽으로 고개를 돌렸다."}, {"s": "southern_remnant:galmae", "t": "…찾기만 하는 거야. 앉는다고는 안 했어."}, {"s": null, "t": "갈매가 벌떡 일어서며 화로 뚜껑을 덮었다. 청파가 기침을 참으며 손을 번쩍 들었다."}, {"s": "q:sn_cheongpa", "t": "수로까지는 제가 태워 드릴게요! 잔불촌까지도 따라갈래요. 노만 저으면 숨이 남아요."}, {"s": null, "t": "갈매가 화로 뚜껑 손잡이를 쥔 채 청파를 흘겨보다가 나를 돌아보았다."}, {"s": "southern_remnant:galmae", "t": "붉은 숯만 남았으면 숯부터 새로 넣어야 해. {이름}, 가는 길에 대장간이 보이면 정련 숯을 좀 챙겨. 할배 화로는 숯을 많이 먹어."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_1', 2, '빈 걸상', '잔불촌에 간다, 정련 숯을(를) 넘긴다', '{"at": ["ember_village"], "tasks": [{"t": "travel", "r": ["ember_village"], "n": 1}], "give": {"charcoal": 3}}'::jsonb, '[{"s": null, "t": "잔불촌 어귀에 들어서자 숯 냄새가 먼저 우리를 맞았다. 마을 한가운데 큰 화로는 여전히 붉게 타고 있었지만, 장무현의 이름을 부르며 둘러앉던 밤보다 불빛이 낮고 연기가 비스듬히 누워 있었다."}, {"s": null, "t": "화로 곁에 장무현이 앉던 낮은 걸상이 놓여 있었다. 걸상 위에는 아무것도 없었다. 마을 사람들은 걸상 둘레를 피해 한 걸음씩 떨어져 앉아 있었다."}, {"s": null, "t": "아이 하나가 갈매를 알아보고 손가락으로 가리켰다. 아이는 신이 나서 소리를 질렀다."}, {"s": "q:md_child", "t": "마지막 아이 누나 왔다! 마지막 아이 누나!"}, {"s": null, "t": "갈매의 어깨가 움찔 굳었다. 갈매는 아무 말도 하지 않고 장작더미 쪽으로 눈을 돌렸다. 장작더미를 걷어차지는 않았다."}, {"s": null, "t": "물동이를 인 아낙 하나가 배를 받치고 천천히 다가왔다. 배가 남산만 하게 불러 있었다. 아낙은 물동이를 내려놓고 아이의 뒤통수를 가볍게 쥐어박았다."}, {"s": "q:sx_md_meoru", "t": "이 녀석이, 누나한테 그게 무슨 소리냐. …갈매야, 왔구나. 혀를 차야 할지 반가워해야 할지 모르겠다. 겨우내 얼굴 한 번을 안 비치고."}, {"s": null, "t": "갈매가 아낙의 둥근 배를 보고 눈을 동그랗게 떴다."}, {"s": "southern_remnant:galmae", "t": "머루댁 배가 왜 그래. 벌써 그렇게 됐어?"}, {"s": null, "t": "머루댁이 둥근 배를 손바닥으로 쓸며 걸걸하게 웃었다."}, {"s": "q:sx_md_meoru", "t": "지난봄에 들어선 애다. 날 풀리기 전에 나올 거라더라. 끌끌, 네가 봐 주면 좋겠다고 노래를 불렀는데."}, {"s": null, "t": "화로 뒤에서 무녀 소이가 걸어 나왔다. 소이는 갈매 앞에서 걸음을 멈추고 오래 그 얼굴을 바라보다가 고개를 숙였다."}, {"s": "southern_remnant:soi", "t": "와 주셨사옵니다. 조사원님도, 관측관님도, 수향 분도 먼 길 오셨사옵니다."}, {"s": null, "t": "나는 들고 온 정련 숯을 화로 가장자리에 넣었다. 붉은 불이 숯을 핥으며 확 일었다. 소이가 부지깽이 대신 막대기로 숯을 헤쳐 보였다. 숯 밑바닥에 쌀알만 한 흰빛 하나가 가물거렸다."}, {"s": null, "t": "갈매가 구리 화로 뚜껑을 열고 흰 불씨 한 점을 떼어 큰 화로에 옮겨 넣었다. 흰빛이 한순간 손바닥만큼 피어올랐다가, 숨 몇 번 쉴 사이에 다시 쌀알만 하게 줄어들었다."}, {"s": null, "t": "서하람이 화로 쪽으로 귀를 기울이며 고개를 갸웃했다."}, {"s": "q:r71_seoharam", "t": "지금 어때요? 소리가 한 번 커졌다가 작아졌어요."}, {"s": null, "t": "갈매가 화로 속을 들여다본 채 부지깽이를 꽉 쥐었다."}, {"s": "southern_remnant:galmae", "t": "커졌다가… 도로 작아졌어. 불씨를 옮겨도 안 돼."}, {"s": null, "t": "갈매가 이를 악물고 걸상 앞에 쭈그려 앉았다. 갈매는 손바닥으로 걸상 앉는 판을 쓸어 보다가 부지깽이 끝으로 그 옆구리를 톡 두드렸다. 텅, 속이 빈 소리가 났다."}, {"s": null, "t": "갈매가 걸상을 번쩍 들어 뒤집었다. 앉는 판 밑에 기름 먹인 천 보따리 하나가 노끈으로 단단히 묶여 있었다. 노끈 매듭은 한 손으로 묶은 매듭이었다."}, {"s": "southern_remnant:galmae", "t": "…할배 매듭이야. 한 팔로 묶으면 이렇게 돼. 맨날 내 짚신 끈을 이렇게 묶어 줬어."}, {"s": null, "t": "보따리 안에서 두꺼운 이름첩 한 권이 나왔다. 칠십 해 묵은 그을음이 배어 겉장이 새카맸고, 장과 장이 그을음에 눌어붙어 있었다."}, {"s": null, "t": "소이가 이름첩을 내려다보며 두 손을 가슴께에 모았다."}, {"s": "southern_remnant:soi", "t": "장군님께서 밤마다 무릎에 올려 두시던 것이옵니다. 소녀는 장부인 줄로만 알았사옵니다."}, {"s": null, "t": "청파가 이름첩을 들여다보다가 기침을 꾹 참았다. 청파는 숨을 아끼느라 목소리를 낮췄다."}, {"s": "q:sn_cheongpa", "t": "붙은 장을 떼려면 불가에서 천천히 데워야 해요. 젖은 장부도 그렇게 떼요. 밤새 불이 세야 하고요."}, {"s": null, "t": "갈매가 부지깽이를 허리춤에 꽂으며 일어섰다."}, {"s": "southern_remnant:galmae", "t": "그럼 장작부터 해 오자. 오늘 밤은 할배 화로를 할배 있을 때처럼 피울 거야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_1', 3, '칠십 해 동안 센 이름', '불씨 고개에서 채집한다, 잔불촌에서 쉰다', '{"at": ["ember_village"], "tasks": [{"t": "gather", "r": ["ember_pass"], "n": 4}, {"t": "rest", "r": ["ember_village"], "n": 1}]}'::jsonb, '[{"s": null, "t": "그날 밤 화로는 장무현이 있던 밤처럼 높이 타올랐다. 청파가 이름첩을 불가에 비스듬히 세워 두고 한 장씩 손톱 끝으로 떼어 냈다. 눌어붙은 장이 떨어질 때마다 바삭, 오래된 종이 소리가 났다."}, {"s": null, "t": "첫 장 머리에 「백 년 전 동지, 정청 정리 명부 맨 앞줄」이라는 글이 적혀 있었다. 그 아래로 사람 이름이 빽빽했다. 이름마다 끝에 작은 점 하나가 찍혀 있었다. 다음 장에도, 그다음 장에도 해마다 같은 머리글과 같은 점이 이어졌다."}, {"s": null, "t": "갈매가 청파 곁에 쪼그려 앉아 떼어 낸 장 하나를 손끝으로 짚었다."}, {"s": "southern_remnant:galmae", "t": "남명 사람들이야. 해마다 맨 앞줄에 오른 사람들. 할배는 이걸… 칠십 해 동안 밤마다 불렀던 거야. 점은 그날 밤 부른 표시고."}, {"s": null, "t": "서하람이 화로 곁에 무릎을 세우고 앉아 손가락을 하나씩 접었다. 입술이 소리 없이 숫자를 셌다."}, {"s": "q:r71_seoharam", "t": "한 해에 서른 남짓이고, 일흔 해 치면 이천백쯤이에요. 한 이름에 숨 한 번이면 이천백 숨이에요. 한 사람이 다 부르면 목이 먼저 쉬어요. 시간표를 짤게요. 이번엔 종이에 못 쓰니까 머리로 짤게요."}, {"s": null, "t": "서하람이 마을 사람들 쪽으로 고개를 돌려 이름을 물어 가며 차례를 정했다. 한 사람이 쉰 이름씩 맡았다. 아이들은 열 이름씩이었고, 청파는 스무 이름이었다."}, {"s": "q:sn_cheongpa", "t": "스무 개요? 저 서른 개도 할 수 있는데요."}, {"s": null, "t": "서하람이 청파의 목소리가 나는 쪽으로 고개를 돌리고 빙긋 웃었다."}, {"s": "q:r71_seoharam", "t": "다온이가 그랬잖아요. 숨이 짧으면 작게 부르라고요. 작게 스무 개 하세요. 그래도 닿아요."}, {"s": null, "t": "첫 차례는 갈매였다. 갈매가 이름첩 첫 장을 무릎에 펴고 맨 윗줄 이름을 불렀다. 금빛 입김이 가늘게 맺혀 화로 쪽으로 날아갔다. 숯 밑의 흰빛이 콩알만큼 자랐다."}, {"s": null, "t": "갈매는 다음 이름을 불렀고, 그다음 이름을 불렀다. 쉰 이름을 다 부르자 소이가 낮게 노래 한 소절을 불렀다. 노래가 끝나면 다음 사람이 이름첩을 받아 들었다."}, {"s": null, "t": "마을 사람들은 제 차례가 되면 일어서서 이름을 불렀다. 낯익은 이름이 나오면 목소리가 떨렸다. 어떤 노인은 제 형의 이름을 부르고 한참 화로 앞에 서 있었다."}, {"s": null, "t": "내 차례에 나는 이름 쉰을 불렀다. 낯선 이름들이었지만 부를 때마다 입김이 금빛으로 맺혔다. 흰빛이 화로 바닥에서 주먹만큼 자라 있었다."}, {"s": null, "t": "새벽 무렵 이름첩이 마지막 장에 닿았다. 서른 해 전 동지 장이었다. 그 장에는 이름이 하나뿐이었다. 장무현의 굵은 글씨로 「갈매. 세지 않는다. 남명이 마지막으로 지켜 낸 아이.」라고 적혀 있었다."}, {"s": null, "t": "이름첩을 받쳐 든 갈매의 손이 떨렸다. 그 줄 끝에는 점이 찍혀 있지 않았다. 다음 장들은 모두 비어 있었다."}, {"s": "southern_remnant:galmae", "t": "…나는 안 세고. 할배는 할배를 안 적었어. 서른 해 동안 맨 앞줄에 서 있던 게 할배였는데."}, {"s": null, "t": "갈매가 부지깽이를 화로에 쑥 밀어 넣었다가 꺼냈다. 그을린 끝으로 마지막 장 빈칸에 「장무현」 세 글자를 꾹꾹 눌러 썼다. 갈매는 이름 끝에 점 하나를 찍었다."}, {"s": "southern_remnant:galmae", "t": "할배도 세야지. 할배가 맨 끝이야. …장무현."}, {"s": null, "t": "갈매가 그 이름을 부르자 금빛 입김이 굵게 맺혀 화로 속으로 날아들었다. 숯 밑에서 흰 불씨가 화르르 솟았다. 흔들리지도 않고 연기도 나지 않는 흰빛이 화로 둘레를 환하게 비추었다."}, {"s": null, "t": "마을 사람들이 숨을 들이켰다. 서하람이 화로 쪽으로 얼굴을 들고 두 손을 무릎 위에 모았다."}, {"s": "q:r71_seoharam", "t": "따뜻해졌어요. 볼이 따뜻해요. 지금 하얘졌죠? 갈매 씨, 지금 어때요?"}, {"s": null, "t": "갈매는 흰빛에서 눈을 떼지 못했다. 갈매의 목울대가 한 번 크게 움직였다."}, {"s": "southern_remnant:galmae", "t": "…하얘. 할배 있을 때만큼 하얘."}, {"s": null, "t": "소이가 화로 앞에 무릎을 꿇고 이마를 땅에 댔다. 소이는 오래 그 자리에서 일어나지 않았다."}, {"s": "southern_remnant:soi", "t": "장군님께서 칠십 해를 부르신 이름이었사옵니다. 소녀가 곁에서 듣고도 몰랐사옵니다. 이제 알았으니 마을이 나눠 부르겠사옵니다."}, {"s": null, "t": "청파가 떼어 낸 장들을 손바닥으로 조심스럽게 펴다가 얼굴을 찌푸렸다. 그을음에 삭은 장 귀퉁이가 손끝에서 부스러졌다."}, {"s": "q:sn_cheongpa", "t": "이대로 밤마다 넘기면 금방 다 바스러지겠어요. 옮겨 적어야 해요. 마을 분들이 돌려 가며 읽으려면 몇 벌은 있어야 하고요."}, {"s": null, "t": "소이가 무릎을 털고 일어나 청파 손바닥 위의 부스러기를 들여다보았다."}, {"s": "southern_remnant:soi", "t": "황지가 있으면 소녀가 옮겨 적겠사옵니다. 글씨는 장군님만 못하여도 이름은 틀리지 않게 적겠사옵니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_1', 4, '걸상', '황지을(를) 넘긴다', '{"at": ["ember_village"], "give": {"seal_paper": 4}}'::jsonb, '[{"s": null, "t": "소이는 사흘 동안 화로 곁에서 이름첩을 옮겨 적었다. 옮겨 적은 첩은 네 벌이 되었다. 마을 사람들은 해 질 녘이면 첩 한 벌을 돌려 가며 화로 앞에서 이름을 불렀다."}, {"s": null, "t": "흰 불씨는 그 뒤로 사그라지지 않았다. 아이들이 부를 차례가 되면 서로 먼저 하겠다고 다퉜다. 다투는 소리에 머루댁이 혀를 끌끌 찼다."}, {"s": null, "t": "셋째 날 저녁, 소이가 걸상을 화로 앞 제자리에 바로 놓았다. 소이는 걸상 위에 원본 이름첩을 올려 두고 갈매를 돌아보았다."}, {"s": "southern_remnant:soi", "t": "이 걸상에 앉을 사람이 있어야 하옵니다. 마을이 다 함께 부르더라도, 첩을 무릎에 얹을 사람은 하나여야 하옵니다. 장군님께서 그리하셨듯이요."}, {"s": null, "t": "갈매는 걸상을 내려다보며 아무 대답도 하지 않았다. 손가락이 부지깽이 자루를 오래 쓸었다. 갈매가 서하람 쪽을 한 번 돌아보았다."}, {"s": "southern_remnant:galmae", "t": "나는 관아 터에도 화로가 있어. 봉연 문 앞 등잔도 동지마다 갈아야 하고. 그리고… 이 잠꾸러기는 별을 못 보잖아. 내가 읽어 줘야 돼."}, {"s": null, "t": "서하람이 담요 끝을 움켜쥐고 입을 삐죽 내밀었다."}, {"s": "q:r71_seoharam", "t": "저 이제 안 졸려요. 잠꾸러기 아니에요."}, {"s": null, "t": "갈매가 서하람의 이마를 손가락으로 톡 튕겼다."}, {"s": "southern_remnant:galmae", "t": "시끄러. 너는 평생 잠꾸러기야."}, {"s": null, "t": "서하람이 웃음을 참으며 입을 다물었다. 나는 소이에게 걸상 주인을 꼭 하나로만 정해야 하냐고 물었다. 갈매가 오가는 동안에는 마을이 앉고, 갈매가 오면 갈매가 앉으면 되지 않겠냐고 했다."}, {"s": null, "t": "소이가 걸상과 갈매와 나를 번갈아 보았다. 소이의 얼굴에 웃음 비슷한 것이 스쳤다."}, {"s": "southern_remnant:soi", "t": "…장군님께서도 그 말씀을 반기실 것이옵니다. 장군님은 늘 혼자 앉으셨사옵니다. 혼자 앉지 마시라고 소녀가 여쭐 걸 그랬사옵니다."}, {"s": null, "t": "갈매가 한참 걸상을 노려보다가 털썩 앉았다. 갈매는 이름첩을 무릎에 얹고 부지깽이로 숯을 골랐다. 장무현이 하던 손길이었다. 흰 불씨가 숯 밑에서 반짝 빛났다."}, {"s": "southern_remnant:galmae", "t": "오늘만이야. 보름마다 올게. 그 사이엔 마을이 앉아. 머루댁도 앉고."}, {"s": null, "t": "머루댁이 불룩한 배를 두 손으로 받쳐 보이며 눈을 흘겼다."}, {"s": "q:sx_md_meoru", "t": "이 배로 그 낮은 걸상에 앉으라고? 앉았다가는 못 일어난다, 이것아."}, {"s": null, "t": "화로 둘레에서 웃음이 터졌다. 갈매도 따라 웃다가 고개를 숙였다. 화로의 흰빛이 갈매의 얼굴을 비추었다."}, {"s": null, "t": "웃음이 가라앉을 무렵 머루댁이 배를 감싸 쥐고 얼굴을 찡그렸다. 소이가 얼른 다가가 아낙의 팔을 붙들었다."}, {"s": "southern_remnant:soi", "t": "…오늘 밤일지도 모르겠사옵니다. 머루댁, 집으로 가시옵소서."}, {"s": null, "t": "머루댁이 가쁜 숨을 몰아쉬면서도 입꼬리를 올렸다."}, {"s": "q:sx_md_meoru", "t": "끌끌, 이 녀석이 화로 하얘지는 걸 기다렸나 보다. 갈매야, 가지 마라. 아침까지 있어라."}, {"s": null, "t": "갈매가 걸상에서 벌떡 일어나 머루댁의 다른 팔을 붙잡았다. 서하람이 갈매의 허리띠를 붙잡고 그 뒤를 따랐다. 청파는 어쩔 줄 몰라 물동이를 들었다 놓았다 했다."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_galmae_2', 'side', '외전·명등기', '새벽이라는 이름', '진이 꺼진 뒤 잔불촌에 처음 아기가 태어난다. 마을이 그 아기를 「첫 아이」라 부르려 하자 갈매는 아이에게 이름을 지어 주고, 저도 「마지막 아이」가 아닌 제 이름으로 불리기 시작한다.', 'ember_village', 50, '{mde_galmae_1}'::text[], null, 1441, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mde_galmae_2' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_2', 1, '첫울음', '첫울음', '{"at": ["ember_village"]}'::jsonb, '[{"s": null, "t": "동틀 녘 머루댁의 집에서 아기 울음소리가 터져 나왔다. 화로 둘레에서 밤을 새운 마을 사람들이 한꺼번에 고개를 들었다."}, {"s": null, "t": "하늘이 불씨 고개 위로 붉게 물들고 있었다. 동지 전 잿빛 왕궁 터에서 본 흰 동틀 녘과는 다른 빛깔이었다."}, {"s": null, "t": "소이가 포대기에 싼 아기를 안고 문을 나섰다. 아기는 주먹을 꼭 쥐고 얼굴이 빨갛도록 울고 있었다. 소이가 화로 곁으로 와 아기를 마을 사람들 앞에 내보였다."}, {"s": "southern_remnant:soi", "t": "사내아이이옵니다. 어미도 아기도 무탈하옵니다."}, {"s": null, "t": "마을 노인 하나가 지팡이를 짚고 일어섰다. 노인의 목소리가 떨렸다."}, {"s": "q:sx_md_elder", "t": "진이 꺼지고 처음 난 남명 아이로구먼. 이 아이는 명부 맨 앞줄에 안 오른다. 이 아이가 첫 아이고, 갈매가 마지막 아이였으니, 마지막과 처음이 한 화로 앞에서 만났네."}, {"s": null, "t": "마을 사람들이 고개를 끄덕이며 「첫 아이」라고 수군거렸다. 갈매의 얼굴이 굳었다. 갈매가 노인 앞으로 한 걸음 나섰다."}, {"s": "southern_remnant:galmae", "t": "그 말 하지 마. 첫 아이라는 말도 하지 마. 마지막 아이도, 첫 아이도, 애한테 그런 걸 붙이지 마. 붙이면 애가 평생 그걸 지고 다녀."}, {"s": null, "t": "노인이 머쓱한 얼굴로 지팡이를 고쳐 짚었다. 방문이 다시 열리고, 머루댁이 이불을 두른 채 문지방에 기대 섰다. 지친 얼굴로 갈매를 불렀다."}, {"s": "q:sx_md_meoru", "t": "갈매야. 그럼 네가 지어라. 이 애 이름."}, {"s": null, "t": "갈매가 제 가슴을 손가락으로 짚으며 눈을 끔뻑였다."}, {"s": "southern_remnant:galmae", "t": "…내가? 왜 내가 지어. 머루댁 애잖아."}, {"s": null, "t": "머루댁이 이불 자락을 여미며 갈매를 빤히 보았다."}, {"s": "q:sx_md_meoru", "t": "네가 붙이지 말라며. 그럼 붙일 걸 줘야지. 끌끌, 그리고 명부라는 데 칸이 있다며. 부르는 사람을 적는 칸. 그 칸에도 네 이름을 적어 줘라."}, {"s": null, "t": "갈매는 대답을 못 하고 입만 벌렸다. 서하람이 갈매의 소매를 살짝 당겼다."}, {"s": "q:r71_seoharam", "t": "갈매 씨, 이름은 할아버지한테 여쭤 보고 지어요. 갈매 씨는 큰일 정할 때 늘 할아버지한테 갔잖아요."}, {"s": null, "t": "소이가 아기를 머루댁 품에 돌려주고, 마을 젊은이 하나를 불러 무언가를 일렀다. 젊은이가 들소 우리 쪽으로 뛰어갔다."}, {"s": "southern_remnant:soi", "t": "명등청에 사람을 보냈사옵니다. 아기 이름을 명부에 올리려면 서리님이 와 주셔야 하옵니다. 그 사이에 고개에 다녀오시옵소서. 장군님 무덤 둘레에 요즘 짐승들이 어슬렁거린다 하옵니다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_2', 2, '고개 소나무 아래', '불씨 고개에 간다, 불씨 고개의 요괴를 물리친다', '{"at": ["ember_pass"], "tasks": [{"t": "travel", "r": ["ember_pass"], "n": 1}, {"t": "win", "r": ["ember_pass"], "n": 8}]}'::jsonb, '[{"s": null, "t": "고갯마루 늙은 소나무 아래 작은 봉분 둘이 나란히 있었다. 하나는 장무현 어머니의 무덤이었고, 하나는 우리가 맨손으로 흙을 덮어 장무현의 옷과 신을 묻은 봉분이었다. 봉분 위에 마른 솔잎이 고르게 덮여 있었다."}, {"s": null, "t": "갈매가 봉분 앞에 털썩 앉았다. 서하람은 갈매가 「돌 하나, 발 앞에」 하고 일러 주는 대로 더듬어 그 곁에 앉았다. 나는 조금 떨어져 앉아 숲 쪽을 살폈다."}, {"s": "southern_remnant:galmae", "t": "할배. 진이 꺼졌어. 도제조 영감은 할배한테 미안하대. 내가 들었다고만 했어. 그리고 할배 화로가 다시 하얘졌어. 할배가 센 이름들, 이제 마을이 같이 불러."}, {"s": "southern_remnant:galmae", "t": "그리고… 머루댁이 애를 낳았어. 사내애. 근데 나보고 이름을 지으래. 나는 이름 같은 걸 지어 본 적이 없는데."}, {"s": null, "t": "갈매는 봉분에 대고 한참 말을 멈췄다. 솔잎 사이로 바람이 지나갔다. 서하람이 고개를 갸웃했다."}, {"s": "q:r71_seoharam", "t": "별 이름은 짧아야 부르기 좋아요. 「하람」처럼요. 두 글자로 지으면 어때요?"}, {"s": null, "t": "갈매가 봉분에서 눈을 떼지 않고 고개를 세차게 저었다."}, {"s": "southern_remnant:galmae", "t": "별 이름은 싫어. 별은 너 하나로 충분해. 애가 별에 묶이면 어떡해."}, {"s": null, "t": "서하람이 무언가 말하려고 입을 벌렸다가 도로 다물고 고개를 끄덕였다."}, {"s": "q:r71_seoharam", "t": "…그건 그렇네요."}, {"s": null, "t": "고개 너머로 해가 솟고 있었다. 붉은빛이 소나무 가지 사이로 쏟아져 봉분 위 솔잎을 물들였다. 갈매가 그 빛을 오래 바라보았다."}, {"s": "southern_remnant:galmae", "t": "할배 간 날도 동틀 녘이었어. 근데 그날 새벽은 하얬어. 아무 색도 없었어. 오늘 새벽은 빨개. 애가 이 새벽에 울었어."}, {"s": "southern_remnant:galmae", "t": "…새벽. 새벽이라고 할래. 할배가 하얀 새벽에 갔으니까, 얘는 색 있는 새벽에 온 거라고."}, {"s": null, "t": "서하람이 입술을 달싹여 그 이름을 소리 없이 한 번 불러 보고는 고개를 끄덕였다."}, {"s": "q:r71_seoharam", "t": "좋아요. 부르기 쉬워요. 숨 한 번에 다 불러져요. 청파 씨도 부를 수 있겠어요."}, {"s": null, "t": "갈매가 봉분 위 솔잎 하나를 집어 들고 일어섰다. 갈매가 무언가 생각난 듯 손가락을 탁 튕겼다."}, {"s": "southern_remnant:galmae", "t": "이름 짓는 날엔 국수야. 남명은 먼 길 가는 사람한테 국수를 먹여. 길게 가라고. 애는 이제부터 제일 먼 길 가는 사람이잖아. 할배 국수로 할 거야. 굵게."}, {"s": "southern_remnant:galmae", "t": "{이름}, 메밀이랑 들나물을 좀 뜯어 줘. 반죽은 내가 해. 할배가 그랬어. 손목 말고 손바닥으로 밀라고."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_2', 3, '굵게 썬 국수', '불씨 고개에서 채집한다', '{"at": ["ember_village"], "tasks": [{"t": "gather", "r": ["ember_pass"], "n": 4}]}'::jsonb, '[{"s": null, "t": "메밀과 들나물을 지고 잔불촌으로 돌아오자 갈매가 화로 곁에서 소매를 걷고 반죽을 밀기 시작했다. 국수 솥에서 김이 오를 무렵, 낯선 사람 하나가 걸상 옆에 엉거주춤 서 있었다. 정청 서리 옷을 입은 문수였다. 들소 등에 실려 밤새 달려온 얼굴이 하얗게 질려 있었다."}, {"s": "q:dh_munsu", "t": "조, 조사원님! 다행이에요. 남명 땅에 혼자 떨어진 줄 알았거든요. 들소가 그렇게 빨리 달리는 줄 몰랐거든요. 엉덩이가 아직 제 것 같지 않거든요."}, {"s": null, "t": "갈매가 문수를 위아래로 훑어보았다. 문수가 저도 모르게 한 걸음 물러섰다."}, {"s": "southern_remnant:galmae", "t": "정청 사람이 왜 여기 있어."}, {"s": null, "t": "문수가 엉겁결에 두 손을 마구 내저었다."}, {"s": "q:dh_munsu", "t": "이, 이제 명등청이거든요! 아기 이름을 올린다고 해서 왔어요. 명등청 첫 명부는 희수 서리님이 엮지만, 새로 나는 아기 줄은 서리들이 나눠 맡거든요. 줄 끝에 칸도 다 있거든요."}, {"s": null, "t": "문수가 품에서 낱장 하나와 붓을 꺼냈다. 줄 끝마다 손바닥만 한 빈 네모가 그려진 장이었다. 문수의 손은 아직 떨리고 있었지만, 붓끝은 반듯했다."}, {"s": null, "t": "머루댁이 아기를 안고 화로 앞에 나와 앉았다. 갈매가 국수 그릇을 아낙 앞에 내려놓았다. 메밀 면이 굵고 투박했다."}, {"s": "q:sx_md_meoru", "t": "끌끌, 굵기도 하다. 장군님이 썬 것보다 더 굵네."}, {"s": null, "t": "갈매가 젓가락을 쥔 채 어깨를 으쓱했다."}, {"s": "southern_remnant:galmae", "t": "할배가 굵게 썰랬어. 남명 국수는 씹히는 맛이라고."}, {"s": null, "t": "마을 사람들이 국수를 나눠 들고 화로를 빙 둘러앉았다. 후루룩 소리가 화로 둘레를 메웠다. 서하람은 국수를 한 입 먹고 고개를 끄덕였다."}, {"s": "q:r71_seoharam", "t": "장군님 국수 맛이 나요. 이번엔 반죽이 안 끊겼네요."}, {"s": null, "t": "갈매가 귀 끝이 붉어진 채 서하람의 그릇에 국수를 한 젓가락 더 얹었다."}, {"s": "southern_remnant:galmae", "t": "먹기나 해."}, {"s": null, "t": "국수 그릇이 다 비자 문수가 낱장을 화로 앞 돌 위에 펼쳤다. 문수가 붓을 머루댁 쪽으로 내밀었다."}, {"s": "q:dh_munsu", "t": "이름하고 태어난 해하고 사는 고을을 적거든요. 이름은요?"}, {"s": null, "t": "머루댁이 갈매를 보자 갈매가 아기를 받아 안았는데, 아기를 안은 팔이 칼을 쥘 때보다 굳어 있었다. 갈매가 아기 얼굴을 내려다보며 숨을 한 번 들이켰다."}, {"s": "southern_remnant:galmae", "t": "…새벽. 이름은 새벽이야."}, {"s": null, "t": "갈매가 그 이름을 부르자 금빛 입김이 가늘게 맺혀 아기의 가슴께에 닿았다. 아기가 울음을 뚝 그치고 눈을 끔뻑였다."}, {"s": null, "t": "머루댁이 아기의 이름을 불렀다. 소이가 불렀고, 마을 사람들이 한목소리로 「새벽」 하고 불렀다. 금빛 실 수십 가닥이 아기의 가슴께로 날아들어 포대기 위에서 실타래처럼 엉켰다."}, {"s": null, "t": "문수가 줄 첫머리에 「새벽」, 그 옆에 올해와 「잔불촌」을 적었다. 갈매가 붓을 받아 줄 끝 칸에 제 이름을 적고 엄지 도장을 꾹 눌렀다."}, {"s": "q:dh_munsu", "t": "맨 앞줄 아니거든요. 그냥 줄이에요. 이 장에 오늘 오른 아기가 아홉 명이거든요. 새벽이는 일곱째 줄이에요."}, {"s": null, "t": "갈매가 그 말을 듣고 아무 말 없이 낱장을 오래 내려다보았다. 갈매의 입꼬리가 아주 조금 올라갔다."}, {"s": null, "t": "아까 소리를 질렀던 아이가 국수 그릇을 든 채 갈매 곁으로 쪼르르 다가왔다. 아이는 갈매의 소매를 잡아당겼다."}, {"s": "q:md_child", "t": "갈매 누나. 새벽이한테 나중에 칼을 가르쳐 줄 거야? 나도 가르쳐 줘."}, {"s": null, "t": "갈매가 아이를 내려다보았다. 아이는 「마지막 아이」라고 부르지 않았다. 갈매는 대답 대신 아이의 머리를 헝클었다."}, {"s": null, "t": "소이가 화로에 장작 하나를 더 넣었다. 흰 불씨가 숯 밑에서 반짝 빛났다. 소이가 갈매를 보지 않고 화로만 보며 말했다."}, {"s": "southern_remnant:soi", "t": "「마지막 아이」라는 말은 장군님 걸상 밑에 묶어 두겠사옵니다. 장군님이 고쳐 쓰신 뜻이 좋은 뜻이어도, 이제 남명에는 마지막으로 지켜 낼 아이가 없사옵니다. 다들 그저 이름으로 부를 것이옵니다."}, {"s": null, "t": "갈매는 고개를 숙인 채 한참 일어나지 않았다. 문수가 낱장을 말아 쥐며 헛기침을 했다."}, {"s": "q:dh_munsu", "t": "저, 그런데요. 이 장을 명등청에 가져가야 하거든요. 근데 오는 길에 객사에 들렀더니, 이야기꾼 춘보 씨가 손님들 앞에서 「남명의 마지막 아이」 이야기를 하고 있었거든요. 칼 한 자루로 먹 낀 짐승 백 마리를 베었다던가요."}, {"s": null, "t": "빈 그릇을 내려놓던 갈매의 손이 허공에서 멈췄다."}, {"s": "southern_remnant:galmae", "t": "…뭐? 백 마리?"}, {"s": null, "t": "문수가 손가락 다섯을 펴 보였다가 두 손을 다 펴 보였다."}, {"s": "q:dh_munsu", "t": "어제는 쉰 마리였거든요. 하루 사이에 갑절이 됐거든요."}, {"s": null, "t": "갈매가 벌떡 일어섰다. 서하람이 그 기세에 놀라 갈매의 허리띠를 놓쳤다가 도로 붙잡았다."}, {"s": "southern_remnant:galmae", "t": "나도 간다. 그 이야기꾼 입부터 막아야겠어. 문수 너, 혼자 가기 무섭지? 따라와."}, {"s": null, "t": "문수가 낱장을 끌어안은 채 펄쩍 뛰었다."}, {"s": "q:dh_munsu", "t": "무섭다고 한 적 없거든요! …무섭긴 하거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_2', 4, '이야기꾼', '본부 객사에 간다, 본부 객사에서 쉰다', '{"at": ["hq_dorm"], "tasks": [{"t": "travel", "r": ["hq_dorm"], "n": 1}, {"t": "rest", "r": ["hq_dorm"], "n": 1}]}'::jsonb, '[{"s": null, "t": "저녁이 되자 본부 객사 대청에 손님들이 빽빽이 모였다. 대청 한가운데 낮은 탁자 위에 이야기꾼 하나가 올라앉아 쥘부채를 폈다 접었다 하고 있었다. 손님들이 그 사람을 춘보라고 불렀다."}, {"s": "q:sx_md_chunbo", "t": "자, 들어 보시오! 남명의 마지막 아이가 불씨 고개에 섰는데, 고개 너머에서 먹 낀 짐승이 백, 아니 이백 마리가 넘어왔단 말이오! 마지막 아이는 칼 한 자루를 들고…"}, {"s": null, "t": "대청 뒤쪽에 서 있던 갈매가 팔짱을 풀었다. 갈매가 손님들 사이를 헤치고 탁자 앞까지 성큼성큼 걸어갔다. 손님들이 하나둘 고개를 돌렸다."}, {"s": "southern_remnant:galmae", "t": "스물이었어. 스물 조금 넘었어. 그리고 혼자 안 했어. 북령 대장이 왼쪽을 막았고, 적월 무녀가 방울을 흔들었고, 수향 꼬맹이가 돌을 던졌어. 등 뒤에서 덮친 놈은 저 사람이 막았고."}, {"s": null, "t": "갈매가 턱으로 나를 가리켰다. 손님들의 눈이 한꺼번에 나에게 쏠렸다. 춘보가 쥘부채를 접은 채 갈매를 위아래로 훑어보았다."}, {"s": "q:sx_md_chunbo", "t": "허, 이야기 속 사람이 이야기꾼 앞에 나타나시다니. 그 마지막 아이가 당신이시오?"}, {"s": null, "t": "갈매의 턱이 굳었다. 갈매가 춘보를 똑바로 쳐다보았다."}, {"s": "southern_remnant:galmae", "t": "그 말 하지 마. 내 이름은 갈매야. 남명 정찰대장 갈매."}, {"s": null, "t": "춘보가 눈을 끔뻑이다가 쥘부채로 제 무릎을 탁 쳤다. 춘보의 얼굴에 장난기 어린 웃음이 번졌다."}, {"s": "q:sx_md_chunbo", "t": "이거 낭패요. 이야기꾼이 이야기 속 사람 이름을 틀렸구려. 그럼 그 이야기를 처음부터 들려주시오. 백 마리가 스물이 되어도 좋소. 이름이 맞는 편이 이야기가 오래가오."}, {"s": null, "t": "갈매가 입을 다물고 한참 서 있었다. 서하람이 갈매의 등 뒤에서 작게 말했다."}, {"s": "q:r71_seoharam", "t": "할아버지 이야기부터 해요, 갈매 씨. 국수 이야기요."}, {"s": null, "t": "갈매가 탁자 가장자리에 걸터앉았다. 갈매는 처음엔 퉁명스럽게, 나중엔 천천히 이야기를 했다. 잔불촌 화로와 한 팔로 젓던 부지깽이와 굵게 썬 국수 이야기였다. 장무현이 마지막 날 남긴 말은 갈매가 끝까지 하지 않았다."}, {"s": null, "t": "대청이 조용해졌다. 문수가 손등으로 코를 훔쳤다. 춘보는 한 번도 끼어들지 않고 들었다."}, {"s": null, "t": "이야기가 끝나자 춘보가 탁자에서 내려와 갈매 앞에 섰다. 춘보는 쥘부채를 품에 넣고 두 손을 모았다."}, {"s": "q:sx_md_chunbo", "t": "오늘부터 객사에서는 이 이야기를 이렇게 하겠소. 「남명 정찰대장 갈매가 불씨 고개에 섰는데, 짐승이 스물 남짓 넘어왔고, 그 곁에 동무 셋과 조사원 하나가 있었다.」 숫자는 부풀리지 않겠소. 이름은 더더욱."}, {"s": "q:sx_md_chunbo", "t": "그리고 끝에는 국수 이야기를 붙이겠소. 굵게 썬 국수. 이야기꾼이 사람을 울리는 데는 백 마리보다 국수 한 그릇이 낫더이다."}, {"s": null, "t": "손님들 사이에서 누군가 「갈매!」 하고 외쳤다. 다른 손님이 따라 외쳤고, 대청 여기저기서 그 이름이 터져 나왔다. 금빛 입김 여러 가닥이 대청 등잔 아래로 날아와 갈매의 가슴께에 닿았다."}, {"s": null, "t": "갈매의 귀 끝이 새빨개졌다. 갈매는 손님들을 노려보다가 내 소매를 홱 잡아끌고 대청 밖으로 나갔다."}, {"s": "southern_remnant:galmae", "t": "다 너 때문이야. 네가 거기 서 있어서 다들 쳐다봤잖아."}, {"s": null, "t": "나는 쳐다본 것은 갈매였다고 했다. 갈매가 콧방귀를 뀌었다. 객사 처마 끝 등잔 불빛에 갈매의 얼굴이 아직 붉었다."}, {"s": "southern_remnant:galmae", "t": "…관아 터로 가자. 화로 불씨를 나눠 줄게. 너도 하나 가져가. 할배 불씨야. 네 별채에 두고 동지마다 이름 하나씩 불러. 화로는 네가 만들어. 놋쇠로 둘. 하나는 잠꾸러기 관성대에 둘 거야. 남명 화로는 놋쇠가 제일이야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_galmae_2', 5, '세 번째 불씨', '꺼진 관아 터에 간다, 놋쇠 화로을(를) 만든다, 놋쇠 화로을(를) 넘긴다', '{"at": ["dark_yamen"], "tasks": [{"t": "travel", "r": ["dark_yamen"], "n": 1}, {"t": "craft", "items": ["hf_brazier_brass"], "n": 2}], "give": {"hf_brazier_brass": 2}}'::jsonb, '[{"s": null, "t": "꺼진 관아 터 마당에 밤이 내려앉아 있었다. 처마 끝 등롱들이 하나둘 불을 밝히고, 하늘에는 별이 촘촘했다. 구리 화로의 흰 불씨가 마당 한가운데서 고요히 빛났다."}, {"s": null, "t": "갈매가 내가 만든 놋쇠 화로를 받아 들고 이리저리 돌려 보았다. 손가락으로 가장자리를 톡톡 두드리고, 바닥을 뒤집어 보았다."}, {"s": "southern_remnant:galmae", "t": "남명 대장장이였으면 더 두껍게 했을 거야. 그래도 쓸 만해. 할배라면 「나쁘지 않네」 했겠다. 북령 말투로는 아니고."}, {"s": null, "t": "갈매가 놋쇠 화로 하나를 서하람 무릎 곁에 내려놓고, 남은 하나에 정련 숯을 깔았다. 부지깽이 끝으로 구리 화로의 흰 불씨 한 점을 떼어 놋쇠 화로로 옮겨 놓았다. 흰빛이 숯 위에서 작게 피어올랐다."}, {"s": "southern_remnant:galmae", "t": "이제 이 불씨는 셋이야. 잔불촌 큰 화로, 관아 터 구리 화로, 그리고 네 거. 봉연 문 앞 등잔까지 치면 넷이고."}, {"s": null, "t": "서하람이 놋쇠 화로 쪽으로 손을 뻗었다. 갈매가 그 손을 끌어다 화로 가장자리의 따뜻한 데에 대 주었다."}, {"s": "q:r71_seoharam", "t": "따뜻하네요. 그런데 불러 주는 사람이 없으면 이 불도 작아지잖아요. {이름} 님, 이 화로 앞에서는 누구 이름을 부를 거예요?"}, {"s": null, "t": "나는 장무현의 이름부터 부르겠다고 했다. 그다음에는 해마다 한 이름씩 늘리겠다고 했다. 갈매가 고개를 끄덕였다."}, {"s": "southern_remnant:galmae", "t": "그거면 돼. 할배가 칠십 해 동안 한 거, 우리가 나눠서 하면 금방이야."}, {"s": null, "t": "갈매가 부지깽이를 무릎에 가로놓고 하늘을 올려다보았다. 갈매는 서하람의 손을 잡아 북쪽 하늘을 가리키게 했다."}, {"s": "southern_remnant:galmae", "t": "오늘 별이 많아. 국자 모양 별이 제일 또렷해. 예뻐."}, {"s": null, "t": "서하람이 갈매 손에 잡힌 손가락을 북쪽으로 뻗은 채 웃었다."}, {"s": "q:r71_seoharam", "t": "또 감상이네요. 그래도 좋아요. 다음엔 새벽이 이야기도 해 줘요. 그 애가 뭘 잡는지, 누구 닮았는지요."}, {"s": null, "t": "갈매가 불씨를 들여다보며 픽 웃었다."}, {"s": "southern_remnant:galmae", "t": "머루댁 닮았어. 울 때 혀 차는 소리가 똑같아."}, {"s": null, "t": "서하람이 웃음을 터뜨렸다. 갈매가 놋쇠 화로 뚜껑을 덮어 내 손에 쥐여 주었다. 뚜껑 틈으로 흰빛이 새어 나왔다. 손바닥이 은근히 데워졌다."}, {"s": "southern_remnant:galmae", "t": "장무현. 내 할배야. 잊지 마. 원망하라는 게 아니라, 있었다는 것만."}, {"s": null, "t": "갈매는 그 말을 하고 얼른 고개를 돌렸다. 나는 놋쇠 화로를 품에 안고 그 이름을 한 번 불렀다. 금빛 입김 한 가닥이 화로 뚜껑 틈으로 스며들었다."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_md_brazier": 1}, "title": "md_keep_galmae"}'::jsonb)
