insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_hanseol', 'side', '외전·명등기', '이름 없는 등롱', '이듬해 동지를 앞두고 한설이 명등제 명단을 처음부터 다시 짠다. 흑련과 객사와 등도에서 모은 이름을 명단에 올리고, 첫 명등제에 이름 없이 걸어 둔 등롱에 내가 등도에서 찾은 이름들을 적는다.', 'hq_yard', 50, '{mde_danbi_2,mde_unbi_2,mde_cheongpa_2,mde_galmae_2,mde_haram_2}'::text[], null, 1442, '[]'::jsonb, true, null, null)
