delete from public.world_quest_steps where quest_id = 'mde_hanseol' and step > 6;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_hanseol', 1, '쌓인 명단', '쌓인 명단', '{"at": ["hq_yard"]}'::jsonb, '[{"s": null, "t": "동지를 스무날쯤 앞둔 밤이었다. 명등청 대청에는 일곱 세력의 깃발이 그대로 걸려 있었고, 감찰관 방에만 늦도록 등잔이 켜져 있었다."}, {"s": null, "t": "한설은 책상 앞에 앉아 붓을 닦고 있었다. 붓은 이미 깨끗했는데도 한설은 천으로 붓대를 천천히, 몇 번이고 다시 닦았다. 책상 위에 명단 뭉치가 무릎 높이만큼 쌓여 있었다. 그 곁에 모서리가 다 펴진 경현의 장부가 놓여 있었다."}, {"s": null, "t": "문 앞에서 서리 문수가 손짓으로 나를 불렀다. 문수는 목소리를 한껏 낮췄다."}, {"s": "q:dh_munsu", "t": "조사원님, 오셨어요. 감찰관님이 붓 닦으시는 거 보셨죠. 저렇게 천천히 닦으시면 큰일 난 거거든요. 사흘째 저러고 계시거든요."}, {"s": "q:dh_munsu", "t": "작년 명등제 뒤에 보니까, 어느 고을은 맡은 이름이 남아서 밤을 새워도 다 못 불렀고, 어느 고을은 모자라서 같은 이름을 열 번씩 불렀거든요. 감찰관님이 올해는 하나도 안 빠지게 처음부터 다시 짜신대요. 혼자서요."}, {"s": null, "t": "한설이 붓을 내려놓고 고개를 들었다. 눈 밑이 까맸다. 한설은 나를 보고 붓 닦던 천을 책상 한쪽에 반듯하게 갰다."}, {"s": "night_office:han", "t": "왔구나, 조사원. 앉아라. 문수 서리, 다 들린다."}, {"s": null, "t": "문수가 문틀을 붙잡고 얼굴이 빨개진 채 고개를 쏙 내밀었다."}, {"s": "q:dh_munsu", "t": "들으시라고 한 말이거든요!"}, {"s": null, "t": "한설이 명단 맨 위 장을 들어 보였다. 고을 이름 아래 이름이 빽빽했고, 군데군데 붉은 점이 찍혀 있었다."}, {"s": "night_office:han", "t": "붉은 점은 작년에 아무도 안 맡은 이름이다. 맡을 사람이 없어서 비었다. 올해는 한 이름도 비우지 않을 거다. 비면 문이 흔들린다."}, {"s": "night_office:han", "t": "그런데 명단에 아직 안 오른 이름이 있다. 흑련이 맡아 뒀다가 돌려줄 사람을 못 찾은 이름, 객사 기록관이 서른 해 동안 정서하며 외운 이름, 그리고 네가 등도에서 찾아 준 이름들이다. 셋 다 모아 와라. 그래야 명단이 맞는다."}, {"s": null, "t": "나는 등도에서 찾은 이름들은 이미 적어 두었다고 했다. 한설이 고개를 끄덕였다."}, {"s": "night_office:han", "t": "그럼 흑련부터 가라. 구슬 행수가 서신을 보냈다. 깊은 서가에 이름 쪽지가 새어 나와 돌아다닌다더군. 장부에서 샌 이름을 붙잡아 쪽지로 돌려놔야 명단에 옮길 수 있다고."}, {"s": null, "t": "문수가 한설 몰래 내 소매를 당겼다. 문수의 목소리가 다시 작아졌다."}, {"s": "q:dh_munsu", "t": "그리고요, 오시는 길에 객사에서 차라도 좀 끓여 오세요. 감찰관님 사흘째 물만 드시거든요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_hanseol', 2, '돌려줄 데 없는 이름', '흑련 장부고에 간다, 장부에서 샌 이름을(를) 물리친다', '{"at": ["ledger_cellar"], "tasks": [{"t": "travel", "r": ["ledger_cellar"], "n": 1}, {"t": "win", "m": ["r220_ledger_1"], "n": 8}]}'::jsonb, '[{"s": null, "t": "깊은 서가를 떠돌던 것들은 쓰러지면서 종잇조각으로 돌아왔다. 조각마다 이름 하나씩이 적혀 있었다. 나는 조각을 모아 장부고 안쪽으로 들고 갔다."}, {"s": null, "t": "장부고 금고 문은 활짝 열려 있었다. 장부지기 구슬이 주판을 끼고 앉아 내가 건넨 조각을 한 장씩 장부 갈피에 끼웠다. 주판알이 딸깍딸깍 울렸다."}, {"s": "black_lotus:guseul", "t": "셈이 다 맞아요. 여덟 다 돌아왔어요. 이것들은 돌려줄 사람이 없는 이름이라 갈피에서 자꾸 빠져나가요. 아무도 안 찾으러 오니까 제 발로 찾으러 나가는 거죠."}, {"s": null, "t": "금고 안쪽에서 낮고 느린 목소리가 울렸다. 회주 무명이 검은 천을 두른 채 걸어 나왔다. 굽은 등 위로 장부 한 권을 받쳐 들고 있었다."}, {"s": "black_lotus:mumyeong", "t": "지난겨울 나는 맡아 둔 이름을 회원들에게 돌려주었소. 대부분은 제 주인을 찾아갔지. 그런데 이 장에 남은 이름들은 주인이 이미 세상에 없고, 이름을 받아 갈 집안도 없었소."}, {"s": null, "t": "무명이 장부를 내 앞에 펼쳤다. 검은 천 사이로 먹 줄이 수없이 그어진 손이 나와 이름들 위를 천천히 쓸었다."}, {"s": "black_lotus:mumyeong", "t": "흑련이 동짓밤마다 부르겠소. 그래도 감찰관께 가져가 명단에 올려 주시오. 흑련 장부고 밖에서도 누군가 이 이름을 불렀으면 하오. 맡아 두는 것과 불리는 것은 다르니까."}, {"s": null, "t": "침상 쪽에서 엽전 튕기는 소리가 났다. 월하가 침상 끝에 걸터앉아 오른손으로 엽전을 튕기고 있었다. 엽전은 손등에 반듯하게 내려앉았다. 다온이 그 곁에서 공책을 펴 놓고 무언가를 쓰고 있었다."}, {"s": "q:mk_wolha", "t": "어서 와요, 조사원. 이번엔 안 떨어뜨렸죠? 꼬맹이가 오늘 아직 한 번도 안 주웠어요."}, {"s": null, "t": "다온이 공책에서 고개를 들고 손가락 셋을 펴 보였다."}, {"s": "q:mk_daon", "t": "어제는 세 번 주웠어요. 오늘은 아직 영 번이에요."}, {"s": null, "t": "월하가 품에서 손바닥만 한 낡은 수첩 하나를 꺼냈다. 귀퉁이가 닳아 둥글었다. 월하는 수첩을 한참 손바닥 위에서 굴리다가 내게 내밀었다."}, {"s": "q:mk_wolha", "t": "거둠꾼 시절에 판 이름들이에요. 장부에서는 다 지웠는데, 머리에 남은 걸 하나씩 다시 적었어요. 작년엔 판 사람이 부르면 안 될 것 같아서 적월 무녀님한테 하나만 넘겼죠."}, {"s": "q:mk_wolha", "t": "근데 엿집 할머니 얘기를 듣고 일 년 엽전 튕기면서 생각해 보니까, 판 사람이 안 부르면 그 이름은 판 데서 끝나더라고요. 셈이 안 맞아요. 올해는 내가 부를래요. 아홉 손가락으로."}, {"s": null, "t": "다온이 공책을 들어 월하의 수첩 옆에 나란히 놓았다. 공책에는 삐뚤빼뚤한 글씨로 월하 수첩의 이름들이 옮겨 적혀 있었다."}, {"s": "q:mk_daon", "t": "제가 다 옮겨 적었어요. 아저씨 혼자 부르면 목이 쉬니까, 반은 제가 부를 거예요. 그리고 서하 누나 줄도 제가 또 맡았어요."}, {"s": null, "t": "구슬이 주판알 하나를 탁 튕기고 일어섰다. 구슬은 무명의 장부와 월하의 수첩과 다온의 공책을 한데 묶어 보자기에 쌌다."}, {"s": "black_lotus:guseul", "t": "감찰관님께 가져가세요. 셈은 감찰관님이 하실 거고요. 객사도 들르시죠? 기록관님이 일 년 내내 받아쓰기를 하셨대요. 서른 해 치를요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_hanseol', 3, '객사의 두 목소리', '본부 객사에 간다, 밤빛 차을(를) 만든다, 밤빛 차을(를) 넘긴다', '{"at": ["hq_dorm"], "tasks": [{"t": "travel", "r": ["hq_dorm"], "n": 1}, {"t": "craft", "items": ["night_tea"], "n": 3}], "give": {"night_tea": 3}}'::jsonb, '[{"s": null, "t": "객사 작은 방 창가에 기록관 모가람이 앉아 있었다. 굳은 두 손을 무릎 위에 포개 놓은 채였다. 그 앞에서 곽두칠이 붓을 들고 받아 적고 있었다. 곽두칠 곁에 종이 더미가 사람 키 반만큼 쌓여 있었다."}, {"s": "night_office:mo", "t": "…그다음 줄이요. 그해 동지 사본 넷째 장, 맨 아랫줄이에요. 아, 조사원님! 마침 잘 오셨어요. 두칠 씨, 잠깐 쉬어요."}, {"s": null, "t": "모가람이 나를 보고 활짝 웃었다. 나는 밤빛 차 한 잔을 들어 모가람의 입에 대 주었다. 모가람이 한 모금 마시고 눈을 감았다."}, {"s": "night_office:mo", "t": "따뜻하다. 서른 해 동안 정리소에서 올라오는 사본을 정서했잖아요. 거둬진 이름들이요. 그땐 적기만 하고 한 번도 안 불렀어요. 이제 하나도 안 빼고 말로 다 불러 주는 중이에요. 열한 해 치 남았어요."}, {"s": null, "t": "곽두칠이 붓을 내려놓고 남은 밤빛 차 한 잔을 두 손으로 받았다. 발밑의 그림자가 등잔 불빛에 또렷했다."}, {"s": "q:md_gwak_duchil", "t": "기록관님은 이름을 하나도 안 틀리십니다. 제가 틀리게 적으면 꼭 다시 부르십니다. 그래서 오래 걸립니다."}, {"s": null, "t": "모가람이 곽두칠 쪽으로 고개를 돌리고 굳은 손등으로 종이 더미를 톡 건드렸다."}, {"s": "night_office:mo", "t": "이름은 틀리면 안 되잖아요. 틀린 이름으로 부르면 금빛이 안 나와요. 「무녀」라고 부르는 거나 마찬가지예요."}, {"s": null, "t": "그때 객사 대청 쪽에서 쥘부채 접는 소리가 탁 울렸다. 손님들의 웃음소리가 터졌다. 이야기꾼 춘보의 목소리가 창호지를 넘어 들어왔다."}, {"s": "q:sx_md_chunbo", "t": "…그래서 남명 정찰대장 갈매가 굵게 썬 국수를 갓난아이 앞에 놓았단 말이오! 짐승은 스물 남짓이었고, 국수는 세 그릇이었소. 부풀린 데 하나 없소!"}, {"s": null, "t": "모가람이 쿡쿡 웃었다. 대청 문이 열리고 춘보가 쥘부채로 제 어깨를 두드리며 들어섰다. 춘보는 나를 보자 쥘부채를 활짝 폈다."}, {"s": "q:sx_md_chunbo", "t": "조사원 아니시오! 마침 잘 오셨소. 감찰관께서 명단에 넣을 이름을 모은다길래 나도 들고 왔소. 이야기꾼은 숫자는 부풀려도 이름은 안 버리오."}, {"s": null, "t": "춘보가 품에서 둘둘 만 종이 한 장을 꺼냈다. 종이에는 이름이 길게 적혀 있었고, 이름마다 「북령 가는 짐꾼, 장마 때 떠남」이나 「수향 사공, 돌아오는 배 없음」 같은 짧은 말이 붙어 있었다."}, {"s": "q:sx_md_chunbo", "t": "객사 문간 기둥에 손님들이 길 떠나기 전에 이름을 새기고 가오. 돌아오면 그 이름 옆에 점을 찍지. 이건 서른 해 동안 점이 안 찍힌 이름들이오. 내가 기둥에서 옮겨 적었소."}, {"s": "q:sx_md_chunbo", "t": "이야기꾼이 이 이름들로 이야기를 지어 본 적은 없소. 이 사람들 이야기는 끝을 몰라서. 끝 모르는 이야기는 부르기라도 해야 하지 않겠소."}, {"s": null, "t": "나는 춘보의 종이를 보자기에 함께 쌌다. 춘보가 쥘부채를 접다 말고 내 얼굴을 빤히 보았다."}, {"s": "q:sx_md_chunbo", "t": "그리고 부탁이 하나 있소. 올해 명등제는 등도 관아 터에서도 연다지. 나도 데려가 주시오. 이야기꾼이 남의 말만 듣고 떠들기는 이제 질렸소. 한 번은 제 눈으로 보고 싶소."}, {"s": null, "t": "모가람이 창가에서 몸을 일으키며 굳은 손을 춘보 쪽으로 들어 보였다."}, {"s": "night_office:mo", "t": "데려가세요, 조사원님. 저는 손이 이래서 배를 못 타요. 춘보 씨가 가서 제 몫까지 보고 와 줘요. 와서 다 말해 줘요. 부풀리지 말고요."}, {"s": null, "t": "춘보가 쥘부채로 제 입을 가리며 껄껄 웃었다."}, {"s": "q:sx_md_chunbo", "t": "기록관 앞에서 부풀렸다간 두칠 씨가 받아 적어 증거로 남기겠지. 약속하오."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_hanseol', 4, '다시 짠 명단', '야행국 본부 정청에 간다, 야행국 본부 정청에서 쉰다', '{"at": ["hq_yard"], "tasks": [{"t": "travel", "r": ["hq_yard"], "n": 1}, {"t": "rest", "r": ["hq_yard"], "n": 1}]}'::jsonb, '[{"s": null, "t": "나는 그 밤 한설의 책상 곁에 앉아 있었다. 한설은 보자기를 풀어 무명의 장부, 월하의 수첩과 다온의 공책, 모가람의 받아쓰기, 춘보의 종이를 책상 위에 한 줄로 늘어놓았다."}, {"s": null, "t": "한설은 이름 하나를 읽을 때마다 고을 하나를 정해 옆에 적었다. 맡을 사람이 많은 고을에는 이름을 더 얹고, 적은 고을에서는 덜었다. 붉은 점이 하나씩 지워졌다. 한설의 붓은 한 번도 멈추지 않았다."}, {"s": null, "t": "내가 등도에서 찾아 적어 둔 종이를 내밀었다. 바랜 옷가지와 물건마다 남아 있던 이름들이었다. 한설이 그 종이를 오래 읽다가, 명단 맨 끝에 새 장을 하나 붙였다."}, {"s": "night_office:han", "t": "이 이름들은 고을이 없다. 일흔 해 전 등도 사람들이라, 고을째 거둬졌으니까. 그러니 등도에서 부르자. 관아 터에서. 우리가 맡자."}, {"s": null, "t": "한설이 새 장 머리에 「등도 · 꺼진 관아 터」라고 적었다. 한설은 그 장을 내 앞으로 밀었다."}, {"s": "night_office:han", "t": "첫 명등제 날 이름 없는 등롱 하나에 불을 붙였지. 단비가 아랫단에 날짜를 적었고. 이름은 네가 적기로 했다. 이 이름들을 거기 적어라. 등롱 하나에 다 안 들어가면 더 만들면 된다."}, {"s": null, "t": "방문이 열리고 서리 희수가 들어섰다. 품에 새로 엮은 명부 한 권을 안고 있었다. 희수는 책상 위의 명단을 보고 눈을 크게 떴다."}, {"s": "q:mk_hisu", "t": "감찰관님, 명등청 둘째 명부예요. 첫 명부가 다 찼어요. 올해 새로 오른 줄이 첫 명부보다 많아요. 잔불촌 아기 줄도, 관성대 줄도 있어요."}, {"s": null, "t": "한설이 희수의 명부를 받아 첫 장을 펼쳤다. 줄마다 끝의 칸에 이름이 하나 이상 적혀 있었다. 빈 칸은 하나도 없었다."}, {"s": "night_office:han", "t": "…빈 칸이 없군. 희수 서리, 이번에도 동짓밤에 관아 터로 와 주겠나."}, {"s": null, "t": "희수가 명부를 가슴께로 끌어안으며 고개를 끄덕였다."}, {"s": "q:mk_hisu", "t": "네. 다온이가 또 같이 간대요. 이번엔 월하 님도요. 배는 청파 님이 낸대요."}, {"s": null, "t": "한설이 고개를 끄덕이고 붓을 내려놓았다. 이번에는 붓을 닦지 않았다. 한설이 남은 밤빛 차를 한 모금에 다 마셨다."}, {"s": "night_office:han", "t": "문수 서리, 이제 자도 된다. 나도 잔다."}, {"s": null, "t": "문밖에서 엿듣던 문수가 「드디어」 하고 소리를 냈다가 제 입을 틀어막았다. 한설은 못 들은 척 등잔 심지를 낮췄다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_hanseol', 5, '이름을 적는 등롱', '꺼진 관아 터에 간다, 명등 등롱을(를) 만든다, 명등 등롱을(를) 넘긴다', '{"at": ["dark_yamen"], "tasks": [{"t": "travel", "r": ["dark_yamen"], "n": 1}, {"t": "craft", "items": ["myeongdeung_lamp"], "n": 3}], "give": {"myeongdeung_lamp": 3}}'::jsonb, '[{"s": null, "t": "동짓날 저녁, 꺼진 관아 터 마당에 사람들이 하나둘 모여들었다. 처마 끝에는 작년에 내가 불을 붙인 등롱이 그대로 걸려 있었다. 불은 봄이 오기 전에 꺼져, 종이만 처마 끝에서 흔들리고 있었다. 아랫단에 단비가 적은 「내년 동지 · 꺼진 관아 터」는 바래지 않고 남아 있었다."}, {"s": null, "t": "갈매가 마당 한가운데 구리 화로를 내려놓았다. 흰 불씨가 숯 위에서 고요히 빛났다. 서하람이 갈매의 허리띠를 놓고 화로 곁에 앉아 손바닥을 폈다."}, {"s": "southern_remnant:galmae", "t": "잔불촌 화로는 소이랑 마을이 지켜. 오늘 밤 걸상엔 머루댁이 앉는대. 새벽이 안고. 그 애가 벌써 내 칼집을 잡아당겨."}, {"s": null, "t": "서하람이 화로 온기 쪽으로 얼굴을 든 채 말을 받았다."}, {"s": "q:r71_seoharam", "t": "관성대에선 할머니랑 태사령님이 불러요. 태사령님이 오늘은 말로 부르신대요. 석판 말고요."}, {"s": null, "t": "돌계단 아래에서 노 젓는 소리와 기침 소리가 함께 올라왔다. 청파가 남문 수로 선착에 배를 대고 사람들을 이끌고 올라왔다. 월하와 다온과 희수가 뒤따랐고, 맨 끝에 춘보가 쥘부채를 쥔 채 두리번거리며 올라왔다."}, {"s": "q:sn_cheongpa", "t": "다 실어 왔어요! 값은 하나도 안 받았어요. 춘보 씨가 뱃삯 대신 이야기를 해 준다는 것도 안 받았어요. 노 저으면서 들으면 숨이 차서요."}, {"s": null, "t": "춘보가 돌계단 위에서 숨을 몰아쉬며 수로 쪽을 돌아보았다."}, {"s": "q:sx_md_chunbo", "t": "이 수로가 그 수로요? 일흔 해 전 여든둘이 빠져나온? 허, 내 이야기 속에선 수로 폭이 강만 했는데. 실제론 배 두 척이 겨우 비껴가는구려."}, {"s": null, "t": "마당 어귀에서 방울 소리가 딸랑 울렸다. 단비와 여운비가 나란히 걸어 들어왔다. 여운비는 단비의 오른쪽에 서 있었고, 오른 뺨을 밤바람 쪽으로 내밀고 있었다. 단비가 품에서 엿 꾸러미를 꺼내 흔들었다."}, {"s": "red_moon_cult:danbi", "t": "다들 모였네요! 엿은 올해도 제가 가져왔어요. 앵두 엿이요. 대장님이 백골 장터 엿판 곁에서 장부를 적으셨어요. 짐 수만요. 손님이 대장님 얼굴을 보고 다 도망갔지만요."}, {"s": null, "t": "여운비가 귀 끝이 빨개진 채 헛기침을 했다."}, {"s": "north_league:yeo", "t": "…장부만 적었소. 칼은 뽑지도 않았소. 손님들이 내 눈을 보고 도망간 거요."}, {"s": null, "t": "여운비가 칼자루 끝에 볼에 스치도록 짧게 다시 맨 붉은 술 몇 가닥을 손가락으로 쓸며 나를 돌아보았다. 남은 왼 눈이 웃고 있었다."}, {"s": "north_league:yeo", "t": "봄에 당신이 짚을 해 오고 받침을 깎아 주던 그 목인 말이오. 그 뒤로 고찰 아이들이 목인 앞을 지날 때마다 작은증조할아버지 이름을 부르오. 맹주께서는 그 곁 아버지 목인의 짚도 새로 감으라 하셨소."}, {"s": null, "t": "한설이 마지막으로 마당에 들어섰다. 경현의 장부와 새 명단을 품에 안고 있었다. 한설이 처마 끝의 이름 없는 등롱을 올려다보았다."}, {"s": "night_office:han", "t": "조사원. 네 차례다."}, {"s": null, "t": "나는 등롱을 처마에서 내려 마당 한가운데에 놓았다. 붓을 들고 등롱 종이에 이름을 하나씩 적었다. 내가 등도 곳곳에서 찾아 모은 이름들이었다. 한 등롱에 다 들어가지 않아, 새로 만든 등롱 셋에도 나누어 적었다."}, {"s": null, "t": "이름을 하나 적을 때마다 누군가 그 이름을 소리 내어 읽었다. 단비가 읽었고, 청파가 읽었고, 다온이 큰 소리로 읽었다. 서하람은 읽을 수 없어 대신 따라 불렀다. 금빛 입김이 등롱 종이에 하나씩 스며들었다."}, {"s": null, "t": "마지막 이름을 적자 꺼져 있던 작년 등롱에 화르르 불이 붙었다. 기름도 넣지 않았는데, 이름 글자마다 불빛이 번져 종이가 저녁 빛깔로 물들었다."}, {"s": null, "t": "다온이 등롱 앞으로 뛰어나가 손뼉을 쳤다."}, {"s": "q:mk_daon", "t": "켜졌어요! 이름 적으니까 켜졌어요! 작년엔 이름이 없어서 조금 쓸쓸해 보였는데요."}, {"s": null, "t": "춘보가 쥘부채를 쥔 채 입을 벌리고 등롱을 올려다보았다."}, {"s": "q:sx_md_chunbo", "t": "…이야기꾼 삼십 년에 이런 건 처음 보오. 이건 부풀릴 데가 없구려. 있는 그대로 말해도 사람들이 안 믿을 거요."}, {"s": null, "t": "갈매가 춘보를 흘끗 보고 코웃음을 치더니 화로에 숯 하나를 더 넣었다. 하늘에 별이 하나둘 돋기 시작했다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_hanseol', 6, '두 번째 동짓밤', '꺼진 관아 터에서 쉰다', '{"at": ["dark_yamen"], "tasks": [{"t": "rest", "r": ["dark_yamen"], "n": 1}]}'::jsonb, '[{"s": null, "t": "그 밤 우리는 화로를 가운데 두고 둘러앉아 맡은 이름을 불렀다. 처마 끝 네 등롱의 불빛이 마당을 저녁 빛깔로 채웠다."}, {"s": null, "t": "희수가 둘째 명부를 펼쳤다. 다온이 「서하 누나」 줄을 맡아 불렀고, 월하가 「서율」 줄을 맡아 불렀다. 월하는 그다음 제 수첩을 펴고 거둠꾼 시절에 판 이름들을 하나씩 불렀다. 다온이 반을 받아 불렀다. 엽전은 월하의 무릎 위에 가만히 놓여 있었다."}, {"s": null, "t": "단비가 오른손으로 방울을 흔들며 앵두의 이름을 불렀다. 월하가 단비 쪽을 한 번 보고 고개를 끄덕였다. 단비는 그 끄덕임을 보고 웃었다."}, {"s": null, "t": "여운비가 단비의 오른쪽에 서서 여사온의 이름을 불렀다. 청파가 배 밑창에서 건진 명단을 펴고, 숨을 고르며 한 이름씩 불렀다. 기침이 나오면 단비가 그 자리를 받았다."}, {"s": null, "t": "갈매가 장무현을 부르고, 이름첩에서 옮겨 온 남명 이름 몇을 불렀다. 갈매는 서하람의 손을 끌어 북쪽 하늘을 가리키게 했다."}, {"s": "southern_remnant:galmae", "t": "국자 옆에 「빈」이 있어. 작년보다 조금 밝아. 진짜야. 관측이야."}, {"s": null, "t": "서하람이 갈매 손에 잡힌 손가락을 북쪽 하늘 쪽으로 곧게 폈다."}, {"s": "q:r71_seoharam", "t": "…갈매 씨가 관측이라고 하니까 이상하네요. 그래도 믿을게요. 기록판엔 「갈매 관측」이라고 적어 둘게요."}, {"s": null, "t": "서하람이 부모의 이름을 불렀다. 작은 목소리였지만 금빛 입김은 굵었다. 갈매가 그 곁에서 같은 이름을 따라 불렀다."}, {"s": null, "t": "한설은 새 명단의 「등도 · 꺼진 관아 터」 장을 펴고, 내가 등롱에 적은 이름들을 하나씩 불렀다. 그다음 경현의 장부를 펴고 솔내 사람들의 이름을 불렀다. 마지막 장의 어머니 이름과 맨 끝줄의 「경현」까지 부르고 나서, 한설은 장부를 덮고 한참 화로를 바라보았다."}, {"s": "night_office:han", "t": "작년엔 다 부르고 나서 손이 떨렸다. 올해는 안 떨린다. 다들 같이 불러서 그런 모양이다."}, {"s": null, "t": "희수가 둘째 명부를 덮으며 한설 쪽으로 몸을 기울였다. 희수의 목소리는 작았지만 또렷했다."}, {"s": "q:mk_hisu", "t": "감찰관님. 올해 명단엔 빈 칸이 하나도 없었어요. 문이 흔들릴 틈이 없을 거예요."}, {"s": null, "t": "춘보는 밤새 한마디도 보태지 않고 들었다. 동이 틀 무렵이 되어서야 쥘부채를 무릎에 가만히 내려놓았다. 춘보가 제 종이를 펴, 객사 기둥에서 옮겨 온 이름들을 마지막으로 불렀다. 이야기를 할 때와 다른, 낮고 느린 목소리였다."}, {"s": "q:sx_md_chunbo", "t": "…객사에 돌아가면 이렇게 말하겠소. 「등도 관아 터에서 한 무리가 밤새 이름을 불렀는데, 그 수는 세지 못했고, 등롱은 넷이었다.」 세지 못한 건 부풀린 게 아니오. 정말 못 셌소."}, {"s": null, "t": "날이 밝아 오자 마지막 이름이 끝났다. 단비가 하품을 하며 일어나 새 등롱 하나를 들고 왔다. 아무 이름도 적히지 않은 등롱이었다. 단비가 붓을 들어 아랫단에 작은 글씨를 적었다. 「내년 동지 · 꺼진 관아 터」였다."}, {"s": "red_moon_cult:danbi", "t": "작년 거는 이제 이름이 생겼으니까, 내년 거가 또 있어야죠. 이름은 내년에 또 {이름} 님이 적고요. 해마다 이러면 되잖아요."}, {"s": null, "t": "청파가 콜록거리며 손을 번쩍 들었다."}, {"s": "q:sn_cheongpa", "t": "그럼 저는 내년에도 배를 낼게요! 내후년에도요."}, {"s": null, "t": "여운비가 등롱을 올려다보며 고개를 한 번 끄덕였다."}, {"s": "north_league:yeo", "t": "…나쁘지 않소. 내후년 것까지 셈해 두겠소."}, {"s": null, "t": "갈매가 여운비를 곁눈질하며 픽 웃었다."}, {"s": "southern_remnant:galmae", "t": "올해는 한마디 더 붙었네. 북령도 늘긴 느는구나."}, {"s": null, "t": "웃음소리가 새벽 공기를 타고 멀리 퍼졌다. 한설도 소리 내어 웃었다. 짧은 웃음이었다. 한설은 웃음을 거두고 내게 명단 한 장을 건넸다. 「등도 · 꺼진 관아 터」 장이었다. 맨 아래 「부르는 이」 칸에 한설의 이름과 나란히 빈자리가 하나 남아 있었다."}, {"s": "night_office:han", "t": "네 이름을 적어라. 이 장은 해마다 네가 맡는 거다. 부르는 이로."}, {"s": null, "t": "나는 그 칸에 내 이름을 적고 엄지 도장을 꾹 눌렀다. 처마 끝에서 이름 없는 새 등롱 하나가 새벽바람에 가만히 흔들렸다."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_md_feastlamp": 1}, "title": "md_keep_hanseol"}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_haram_1', 'side', '외전·명등기', '빈자리에 뜬 별', '서하람의 별이 타 버린 빈자리에 새 별 하나가 떠오른다. 두 눈을 잃은 서하람은 갈매가 읽어 주는 하늘을 손끝으로 재어, 새 별을 처음으로 받아 적는다.', 'star_observatory', 50, '{mdq_17}'::text[], null, 1443, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mde_haram_1' and step > 5;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_1', 1, '석판 대신', '석판 대신', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "봄밤이었다. 무극 관성대 계단을 오르는 동안 갈매가 앞에서 계단 수를 일러 주었다. 「다섯. 쉬고. 다시 다섯.」 서하람은 갈매의 허리띠를 쥐고 한 칸씩 발로 더듬어 올랐다."}, {"s": null, "t": "관성대 안쪽 방에서 태사령 하후정이 석판 앞에 앉아 있었다. 그 곁에 수석 관측관 서이연이 서 있었다. 서이연은 서하람을 보자마자 다가와 두 손으로 그 얼굴을 감쌌다."}, {"s": "mandate_court:seo", "t": "람아. 계단에서 넘어지진 않았니. 손이 차구나."}, {"s": null, "t": "서하람이 할머니 손에 얼굴을 맡긴 채 배시시 웃었다."}, {"s": "q:r71_seoharam", "t": "안 넘어졌어요, 할머니. 갈매 씨가 계단을 하나도 안 빼고 세 줬어요. 근데 왜 부르셨어요? 서신에는 「와라」 두 글자밖에 없던데요."}, {"s": null, "t": "서이연이 서하람의 얼굴에서 손을 떼고 하후정 쪽을 돌아보았다."}, {"s": "mandate_court:seo", "t": "그건 태사령께서 쓰신 거란다."}, {"s": null, "t": "하후정이 분필을 들어 석판에 무언가를 적기 시작했다. 몇 글자를 적던 노인의 손이 멈췄다. 하후정은 석판과 서하람의 하얗게 바랜 눈을 번갈아 보았다."}, {"s": null, "t": "하후정이 소매로 석판을 쓱 지웠다. 노인은 분필을 내려놓고 입을 열었다. 마른 나뭇가지가 부러지는 듯한 소리가 두어 번 새어 나온 뒤에야 말이 되었다."}, {"s": "mandate_court:hahu", "t": "…석판은 이제 못 읽겠구나. 그러니 말로 하마. 북쪽 국자 곁, 빈자리에 별이 떴다."}, {"s": null, "t": "방 안이 조용해졌다. 서이연이 숨을 들이켰다. 갈매가 서하람의 어깨를 꽉 쥐었다. 서하람은 하후정 쪽으로 얼굴을 돌린 채 움직이지 않았다."}, {"s": "q:r71_seoharam", "t": "…제 별 자리예요?"}, {"s": null, "t": "하후정이 고개를 천천히 저었다."}, {"s": "mandate_court:hahu", "t": "네 별은 아니다. 새 별이다. 아주 흐리다."}, {"s": null, "t": "서이연이 창 쪽으로 눈을 가늘게 떴다가 고개를 저었다."}, {"s": "mandate_court:seo", "t": "내 눈으로는 안 보이는구나. 요즘은 큰 별도 번져 보여서. 태사령께서 사흘을 보시고 나서야 말씀하셨다."}, {"s": null, "t": "갈매가 창가로 가서 북쪽 하늘을 올려다보았다. 갈매는 눈을 가늘게 뜨고 한참 그 자리를 노려보았다."}, {"s": "southern_remnant:galmae", "t": "…있어. 진짜 있어. 쌀알만 한 거. 아까 계단 오를 땐 몰랐는데."}, {"s": null, "t": "서하람이 두 손을 무릎 위에 모았다. 손가락이 바들바들 떨렸다. 서하람이 고개를 들어 하후정 쪽을 똑바로 향했다."}, {"s": "q:r71_seoharam", "t": "제가 적을게요. 새 별은 처음 본 관측관이 적는 거잖아요. …처음 본 건 태사령님이지만, 태사령님은 말을 안 하시니까요."}, {"s": null, "t": "서이연이 손을 뻗어 서하람의 팔을 붙잡았다."}, {"s": "mandate_court:seo", "t": "람아, 너는 이제…"}, {"s": null, "t": "서하람이 할머니 손 위에 제 손을 포개고 고개를 저었다."}, {"s": "q:r71_seoharam", "t": "알아요. 안 보여요. 그래도 재는 건 손으로도 돼요. 첫 관상대는 「첫 눈」이잖아요. 별을 처음 본 눈이요. 거기 혼천의 고리를 손으로 돌리면서 갈매 씨가 하늘을 읽어 주면, 저는 고리 눈금을 손끝으로 셀게요."}, {"s": "q:r71_seoharam", "t": "그리고 동판에 송곳으로 점을 찍을게요. 점은 손끝으로 읽을 수 있으니까요. 첫 관상대에 빈 별 기록 동판이 아직 있을 거예요."}, {"s": null, "t": "하후정이 서하람을 오래 바라보다가 고개를 한 번 끄덕였다. 서이연이 무어라 말하려다 입을 다물고, 서하람의 손등을 토닥였다."}, {"s": null, "t": "갈매가 창가에서 돌아보며 눈썹을 찌푸렸다."}, {"s": "southern_remnant:galmae", "t": "내가 읽는 거야? 나는 별 이름을 하나도 모르는데."}, {"s": null, "t": "서하람이 갈매 목소리가 나는 쪽으로 얼굴을 돌리고 손가락 두 개를 세워 보였다."}, {"s": "q:r71_seoharam", "t": "이름은 몰라도 돼요. 어디에 있는지만 말해 주면 돼요. 「국자 손잡이 끝에서 손가락 두 마디」 이렇게요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_1', 2, '녹슨 바퀴', '첫 관상대에 간다, 첫 관상대에서 별 기록 동판을(를) 모은다', '{"at": ["first_observatory"], "tasks": [{"t": "travel", "r": ["first_observatory"], "n": 1}, {"t": "gather", "items": ["star_record_plate"], "r": ["first_observatory"], "n": 2}]}'::jsonb, '[{"s": null, "t": "첫 관상대 위 하늘에는 이제 별이 떠 있었다. 일흔 해 동안 희기만 하던 하늘이었다. 녹슨 혼천의가 별빛 아래 멈춰 서 있었다."}, {"s": null, "t": "서하람이 혼천의 앞에 서서 두 손으로 고리를 더듬었다. 손끝이 바깥 고리를 따라 돌다가 어느 자리에서 허공을 짚었다. 고리 몇 개가 비어 있었다."}, {"s": "q:r71_seoharam", "t": "…고리가 없어요. 바깥 고리 둘이랑 안쪽 고리 하나요. 이러면 못 재요."}, {"s": null, "t": "갈매가 서하람 어깨 너머로 혼천의를 들여다보며 눈살을 찌푸렸다."}, {"s": "southern_remnant:galmae", "t": "누가 떼어 갔어? 팔아먹었나?"}, {"s": null, "t": "마당 저편에서 덜그럭덜그럭 쇠 굴러가는 소리가 났다. 녹이 두껍게 앉은 바퀴 몇 개가 제멋대로 마당을 굴러다니고 있었다. 바퀴들이 별빛을 받아 녹슨 테두리를 번뜩였다."}, {"s": null, "t": "서하람이 소리 나는 쪽으로 고개를 돌리고 귀를 기울였다."}, {"s": "q:r71_seoharam", "t": "저 소리예요. 혼천의에서 빠져나간 고리들이 바퀴가 돼서 굴러다니는 거예요. 지난번에도 저것들이 있었어요. 제가 그땐 고리인 줄 몰랐어요."}, {"s": null, "t": "갈매가 굴러다니는 바퀴를 노려보며 칼자루에 손을 얹었다."}, {"s": "southern_remnant:galmae", "t": "그럼 잡아 오면 되네. 굴러다니는 고리는 처음 잡아 본다."}, {"s": null, "t": "갈매가 칼을 뽑아 들었다. 서하람이 갈매의 소매를 붙잡았다."}, {"s": "q:r71_seoharam", "t": "베지 마요! 고리가 상하면 눈금이 틀어져요. 칼등으로 쳐서 쓰러뜨려 주세요. 쓰러지면 도로 고리가 될 거예요."}, {"s": null, "t": "갈매가 칼을 뒤집어 칼등을 앞으로 쥐며 혀를 찼다."}, {"s": "southern_remnant:galmae", "t": "…까다롭기는. {이름}, 너도 칼등이야. 눈금이 틀어지면 저 잠꾸러기가 밤새 잔소리한다."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_1', 3, '손끝으로 재는 하늘', '녹슨 혼천의 바퀴을(를) 물리친다', '{"at": ["first_observatory"], "tasks": [{"t": "win", "m": ["dd_obs_2"], "n": 8}]}'::jsonb, '[{"s": null, "t": "쓰러진 바퀴들은 굴러다니던 기세를 잃고 녹슨 쇠고리로 돌아갔다. 서하람이 고리를 하나씩 손으로 더듬어 제자리에 끼웠다. 끼울 때마다 철컥, 맞물리는 소리가 마당에 울렸다."}, {"s": null, "t": "고리가 다 맞물리자 서하람이 혼천의 받침에 손바닥을 얹었다. 손끝이 고리 안쪽의 눈금을 하나씩 훑었다. 서하람의 얼굴이 별빛 아래서 환해졌다."}, {"s": "q:r71_seoharam", "t": "돼요. 다 맞아요. 이제 갈매 씨가 읽어 주기만 하면 돼요."}, {"s": null, "t": "갈매가 혼천의 곁에 서서 북쪽 하늘을 올려다보았다. 갈매는 손가락을 뻗어 허공에 대고 이리저리 재었다."}, {"s": "southern_remnant:galmae", "t": "국자 있지. 손잡이 끝에서… 왼쪽으로 손가락 두 마디. 아니, 세 마디. 아니다, 두 마디 반."}, {"s": null, "t": "서하람이 고리를 쥔 손을 멈추고 미간을 찌푸렸다."}, {"s": "q:r71_seoharam", "t": "반은 없어요. 두 마디예요, 세 마디예요?"}, {"s": null, "t": "갈매가 허공에 뻗었던 팔을 홱 내렸다."}, {"s": "southern_remnant:galmae", "t": "네가 해 봐. 별이 가만히 안 있잖아."}, {"s": null, "t": "서하람이 고리를 손끝으로 톡 두드리며 태연하게 웃었다."}, {"s": "q:r71_seoharam", "t": "별은 가만히 있어요. 갈매 씨 손가락이 움직이는 거예요."}, {"s": null, "t": "갈매가 씩씩거리며 팔을 다시 뻗었다. 서하람은 고리를 손끝으로 한 칸씩 돌리며 갈매의 말을 기다렸다. 나는 그 곁에서 동판을 받쳐 들었다. 갈매는 별 하나를 읽을 때마다 서하람 쪽으로 몸을 돌려 손가락을 흔들어 보였다."}, {"s": null, "t": "서하람이 송곳을 쥐고 동판에 첫 점을 찍었다. 똑, 작은 소리가 났다. 서하람은 찍은 점을 손끝으로 쓸어 보고 고개를 갸웃했다."}, {"s": "q:r71_seoharam", "t": "이 점, 너무 오른쪽이에요. {이름} 님, 갈매 씨가 아까 「왼쪽」이라고 한 거, 갈매 씨 왼쪽이었어요, 하늘 왼쪽이었어요?"}, {"s": null, "t": "갈매가 팔을 하늘로 뻗은 채 버럭 소리를 질렀다."}, {"s": "southern_remnant:galmae", "t": "내 왼쪽이 하늘 왼쪽이지 뭐야!"}, {"s": null, "t": "서하람이 고개를 갸웃하고 갈매 목소리가 난 쪽을 손가락으로 가리켰다."}, {"s": "q:r71_seoharam", "t": "갈매 씨 목소리가 제 쪽에서 들려요. 하늘을 등지고 저를 보면서 말하잖아요. 그러면 갈매 씨 왼쪽은 하늘 오른쪽이에요."}, {"s": null, "t": "갈매가 입을 벌린 채 굳었다. 갈매가 몸을 홱 돌려 하늘 쪽으로 섰다. 나는 웃음을 참으며 첫 동판을 내려놓고 둘째 동판을 받쳐 들었다."}, {"s": "southern_remnant:galmae", "t": "…첫 장은 버려. 처음부터 다시 해."}, {"s": null, "t": "서하람이 첫 동판을 두 손으로 끌어안았다."}, {"s": "q:r71_seoharam", "t": "버리지 마요. 처음 찍은 거니까 둘게요. 갈매 씨가 왼쪽 오른쪽을 헷갈린 기록도 기록이에요."}, {"s": null, "t": "그 밤은 길었다. 갈매가 손가락으로 재어 부르면, 서하람이 고리를 돌려 눈금을 세고 송곳으로 점을 찍었다. 별이 조금씩 자리를 옮길 때마다 갈매가 투덜거리며 처음부터 다시 쟀다."}, {"s": null, "t": "별빛이 조금씩 옅어질 무렵, 갈매의 목소리가 쉬어 있었다. 서하람은 송곳을 쥐었던 손가락을 주무르고 있었는데, 밤새 동판을 짚은 손끝이 하얗게 굳어 있었다."}, {"s": "q:r71_seoharam", "t": "손이 무거워요. 졸린 건 아니에요. 이제는 밤을 새워도 하나도 안 졸려요."}, {"s": null, "t": "갈매가 코웃음을 치며 서하람의 굳은 손가락을 끌어다 주물러 주었다."}, {"s": "southern_remnant:galmae", "t": "안 졸려도 넌 평생 잠꾸러기야."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_1', 4, '한 글자', '자율 활동을 끝까지 마친다', '{"at": ["first_observatory"], "tasks": [{"t": "idle", "n": 1, "k": "research"}]}'::jsonb, '[{"s": null, "t": "동이 틀 무렵 둘째 동판에 마지막 점이 찍혔다. 서하람이 동판을 무릎에 올려놓고 손끝으로 점을 처음부터 끝까지 천천히 쓸었다. 입술이 소리 없이 숫자를 셌다."}, {"s": "q:r71_seoharam", "t": "…됐어요. 국자 손잡이 끝에서 두 마디, 하늘 왼쪽으로요. 갈매 씨 말로는 「졸음별」보다 조금 더 흐리대요. 갈매 씨, 맞죠?"}, {"s": null, "t": "갈매가 쉰 목소리로 하품을 참으며 어깨를 으쓱했다."}, {"s": "southern_remnant:galmae", "t": "몰라. 네가 맞다면 맞는 거야. 나는 손가락밖에 안 썼어."}, {"s": null, "t": "서하람이 동판을 가슴께에 끌어안았다. 동트는 하늘 쪽으로 얼굴을 들었다. 별빛이 남아 있을 리 없는 눈이었지만, 그 얼굴은 별을 보는 사람의 얼굴이었다."}, {"s": "q:r71_seoharam", "t": "이제 이름을 붙여야 해요. 새 별은 처음 본 사람이 이름을 붙여요. 처음 본 건 태사령님인데, 태사령님은 이름 같은 걸 안 붙이실 거예요. 그다음으로 본 건 갈매 씨예요."}, {"s": null, "t": "갈매가 혼천의 고리에서 팔을 떼며 눈을 휘둥그레 떴다."}, {"s": "southern_remnant:galmae", "t": "나? 별 이름을 내가 왜 지어."}, {"s": null, "t": "서하람이 동판을 끌어안은 채 갈매 쪽으로 얼굴을 돌렸다."}, {"s": "q:r71_seoharam", "t": "갈매 씨가 그랬잖아요. 그 빈자리가 예쁘다고요. 첫 명등제 날 밤에요."}, {"s": null, "t": "갈매가 입을 다물었다. 갈매는 혼천의 고리에 팔을 걸친 채 하늘을 오래 올려다보았다."}, {"s": "southern_remnant:galmae", "t": "…「졸음별」은 안 돼. 그건 벌써 있다며."}, {"s": null, "t": "서하람이 쿡 웃음을 터뜨렸다."}, {"s": "q:r71_seoharam", "t": "네. 저 닮았다는 별이요."}, {"s": null, "t": "갈매가 혼천의 고리에 턱을 괴고 서하람을 흘겨보았다."}, {"s": "southern_remnant:galmae", "t": "「잠꾸러기별」도 안 되겠네. 그건 너 같으니까."}, {"s": null, "t": "서하람이 정색을 하고 고개를 저었다."}, {"s": "q:r71_seoharam", "t": "그건 제가 싫어요."}, {"s": null, "t": "갈매가 콧방귀를 뀌다 말고 고리를 손가락으로 톡 쳤다. 갈매의 목소리가 조금 낮아졌다."}, {"s": "southern_remnant:galmae", "t": "「빈」. 빈자리에 떴으니까 빈. 네 별 있던 자리, 비었어도 예쁘다고 했던 그 자리 이름이야."}, {"s": null, "t": "서하람이 그 이름을 입속으로 한 번 굴려 보고는 동판의 점을 다시 쓸어 보았다."}, {"s": "q:r71_seoharam", "t": "…빈. 좋아요. 이 별은 누구 이름도 아니에요. 사람이 묶인 별이 아니라 그냥 별이에요. 별은 이제 그냥 별이었으면 좋겠어요."}, {"s": "q:r71_seoharam", "t": "그래도 이름은 있어야죠. 불러 줄 수 있게요."}, {"s": null, "t": "서하람이 망가진 첫 동판을 집어 내 손에 쥐여 주었다. 점들이 엉뚱한 데 찍혀 있었다."}, {"s": "q:r71_seoharam", "t": "이건 {이름} 님 가지세요. 갈매 씨가 왼쪽 오른쪽을 헷갈린 첫 기록이에요. 천명원 기록엔 안 넣어도, 저한텐 제일 웃긴 기록이에요. 좋은 건 태사령님께 드려요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_1', 5, '맞다', '무극 관성대에 간다, 별 기록 동판을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "travel", "r": ["star_observatory"], "n": 1}], "give": {"star_record_plate": 1}}'::jsonb, '[{"s": null, "t": "하후정이 서하람이 내민 동판을 받아 들었다. 노인은 눈으로 보지 않고 서하람처럼 손끝으로 점을 하나씩 짚어 나갔다. 마른 손가락이 동판 위에서 오래 머물렀다."}, {"s": null, "t": "방 안의 누구도 말하지 않았다. 서이연은 두 손을 앞치마 위에 꼭 맞잡고 있었다. 갈매는 문기둥에 기대 팔짱을 끼고 있었지만 눈은 노인의 손을 따라가고 있었다. 하후정의 손끝이 마지막 점 위에서 멈췄다."}, {"s": "mandate_court:hahu", "t": "…맞다."}, {"s": null, "t": "하후정이 단 한 마디를 하고 동판을 내려놓았다. 노인은 서랍에서 천명원 별 기록 책을 꺼내 마지막 장을 폈다. 붓을 들어 「빈. 북쪽 국자 곁. 관측 서하람.」이라는 새 줄 하나를 적었다."}, {"s": null, "t": "서이연이 그 글씨를 소리 내어 읽었다. 읽는 목소리가 끝에서 떨렸다. 서이연은 서하람의 손을 끌어다 그 줄 위에 얹어 주었다. 먹이 아직 마르지 않아 서하람의 손끝에 먹이 묻어났다."}, {"s": "mandate_court:seo", "t": "람아. 네 이름이 천명원 기록에 관측관으로 적혔구나. 별로 적힌 게 아니라, 별을 본 사람으로."}, {"s": null, "t": "서하람이 먹 묻은 손끝을 코앞으로 가져가 냄새를 맡았다."}, {"s": "q:r71_seoharam", "t": "…손끝이 까매졌어요. 그래도 좋아요. 먹 묻은 손은 기록한 손이잖아요."}, {"s": null, "t": "서하람이 웃으며 손끝을 비볐다. 서이연이 그 손을 제 앞치마로 닦아 주다가 손을 멈췄다. 서이연의 얼굴에 무언가 떠오른 듯한 기색이 스쳤다."}, {"s": "mandate_court:seo", "t": "그런데 람아. 할머니가 생각해 보니, 너는 이제 어느 명부에도 없구나. 스무 해 동안 네 이름은 별 기록 안에만 있었지. 그 별이 탔으니, 사람의 명부에는 아직 네 줄이 없어."}, {"s": null, "t": "서하람의 웃음이 멈췄다. 서하람은 먹 묻은 손끝을 내려다보다가 갈매 쪽으로 얼굴을 돌렸다."}, {"s": "q:r71_seoharam", "t": "…그럼 저는 지금 어디에도 안 적힌 사람이에요?"}, {"s": null, "t": "갈매가 문기둥에서 등을 떼고 책 쪽으로 턱짓을 했다."}, {"s": "southern_remnant:galmae", "t": "여기 적혔잖아. 방금. 관측 서하람."}, {"s": null, "t": "서하람이 고개를 저으며 손끝으로 책 모서리를 더듬었다."}, {"s": "q:r71_seoharam", "t": "그건 별 기록이에요. 사람 명부가 아니고요."}, {"s": null, "t": "서이연이 서하람의 손을 꼭 쥐었다. 서이연의 눈에 물기가 고였지만 목소리는 또렷했다."}, {"s": "mandate_court:seo", "t": "명등청에 서신을 쓰마. 희수 서리님이 새 명부를 엮는다지. 스무 해 전에 할머니가 너를 사람의 명부에서 빼냈으니, 이번에는 할머니가 도로 넣으마."}, {"s": null, "t": "하후정이 분필을 들었다가 내려놓았다. 노인은 말없이 고개를 한 번 끄덕였다. 창밖 북쪽 하늘 국자 곁에서, 흐린 별 하나가 깜빡였다."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2}}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quests(quest_id, kind, cat, title, summary, region_id, min_level, after, chapter_id, sort, epilogue, active, job_key, faction_key)
values ('mde_haram_2', 'side', '외전·명등기', '사람 명부의 한 줄', '서하람이 제 이름으로 처음 사람의 명부에 적힌다. 정리소 서가에서 스무 해 전 명부 사본을 찾아, 얼굴도 모르는 부모의 이름을 처음 듣고 그 칸에 제 이름을 적는다.', 'star_observatory', 50, '{mde_haram_1}'::text[], null, 1444, '[]'::jsonb, true, null, null)
on conflict (quest_id) do update set cat = excluded.cat, title = excluded.title, summary = excluded.summary, region_id = excluded.region_id, min_level = excluded.min_level, after = excluded.after, sort = excluded.sort, active = true;
delete from public.world_quest_steps where quest_id = 'mde_haram_2' and step > 4;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_2', 1, '명부를 안고 온 서리', '명부를 안고 온 서리', '{"at": ["star_observatory"]}'::jsonb, '[{"s": null, "t": "여름 초입, 무극 관성대에 묵창 나루의 서리 희수가 왔다. 희수는 두꺼운 명부 한 권을 보자기에 싸 품에 안고 계단을 올라왔다. 숨이 가빴지만 보자기를 고쳐 안는 손은 조심스러웠다."}, {"s": "q:mk_hisu", "t": "조사원. 서이연 님 서신을 받고 왔어요. 명등청 첫 명부예요. 줄마다 칸을 그어 뒀어요. 서하람 님 줄을 오늘 적으려고요."}, {"s": null, "t": "희수가 관성대 안쪽 방 탁자에 명부를 펼쳤다. 빈 줄 끝마다 손바닥만 한 네모가 반듯하게 그어져 있었다. 서하람이 탁자 가장자리를 더듬어 명부 쪽으로 손을 뻗었다."}, {"s": null, "t": "희수가 서하람의 손을 끌어다 빈 줄 하나에 얹어 주었다."}, {"s": "q:mk_hisu", "t": "한 줄에 이름, 태어난 해, 사는 고을을 적어요. 그리고 끝에 부르는 이 칸이요."}, {"s": null, "t": "서이연이 서하람의 등 뒤에 서서 그 어깨에 손을 얹었다."}, {"s": "mandate_court:seo", "t": "태어난 해는 내가 안다. 스무 해 전 동지 밤에 온 아기니까. 사는 고을은… 람아, 네가 정하렴."}, {"s": null, "t": "서하람이 서이연의 손을 더듬어 찾아 쥐었다."}, {"s": "q:r71_seoharam", "t": "그건 나중에 정할게요. 할머니, 그보다 하나 물어봐도 돼요?"}, {"s": null, "t": "서하람이 명부 위에서 손을 거두었다. 손가락이 탁자 모서리를 천천히 쓸었다."}, {"s": "q:r71_seoharam", "t": "저를 낳은 사람들 이름이요. 부모가 둘 다 거둬진 집 아기였다고 하셨잖아요. 그 사람들 이름은요?"}, {"s": null, "t": "서이연의 얼굴이 굳었다. 서이연이 탁자를 짚고 의자에 천천히 앉았다."}, {"s": "mandate_court:seo", "t": "…모른다. 할머니는 사본에 오른 람이 줄만 보고 그 이름을 별 기록에 옮겼어. 위아래 줄은 보지 않았다. 보면 붓을 못 들 것 같아서. 그 사본은 해가 바뀌자 정리소로 도로 내려갔지."}, {"s": null, "t": "갈매가 문기둥에서 등을 떼었다. 갈매가 서하람 쪽으로 한 걸음 다가섰다."}, {"s": "southern_remnant:galmae", "t": "그럼 정리소에 있겠네. 거기 서가에 명부 사본이 꽉 차 있었잖아."}, {"s": null, "t": "희수가 명부를 덮으며 보자기 매듭을 만지작거렸다."}, {"s": "q:mk_hisu", "t": "정리소 서가는 지금 명등청 서리들이 갈라 정리하고 있어요. 문수 서리님이 맡았는데, 백 년 치라 아직 반도 못 봤대요. 스무 해 전 동지 사본이면… 찾는 데 도움이 필요할 거예요."}, {"s": null, "t": "서하람이 내 쪽으로 손을 뻗어 소매 끝을 붙잡았다."}, {"s": "q:r71_seoharam", "t": "같이 가 줘요, {이름} 님. 저 혼자서는 서가 칸도 못 세요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_2', 2, '스무 해 전 서가', '정리소에 간다, 정리소에서 실마리를 찾는다', '{"at": ["jeongni_vault"], "tasks": [{"t": "travel", "r": ["jeongni_vault"], "n": 1}, {"t": "clue", "r": ["jeongni_vault"], "n": 2}]}'::jsonb, '[{"s": null, "t": "정리소는 조용했다. 먹 도랑의 먹물은 흐르지 않았고, 가늠 저울은 멈춰 있었다. 저울 옆 촛불 일곱은 꺼진 채 촛농만 남아 있었다."}, {"s": null, "t": "정리 명부 서가 앞에서 서리 문수가 사다리에 올라 장부를 한 권씩 내리고 있었다. 우리 발소리에 문수가 화들짝 놀라 사다리를 붙잡았다."}, {"s": "q:dh_munsu", "t": "조, 조사원님이셨어요? 놀랐거든요. 여기 혼자 있으면 먹 도랑에서 자꾸 소리가 나는 것 같거든요. 실은 아무 소리도 안 나는데요."}, {"s": null, "t": "문수가 사다리에서 내려와 서가 한쪽을 가리켰다. 칸마다 모서리 접힌 장부가 빽빽했다."}, {"s": "q:dh_munsu", "t": "스무 해 전 동지면 저쪽 셋째 칸쯤이거든요. 정리관이… 그분이 장부를 해마다 같은 자리에 꽂았거든요. 모서리 접는 너비까지 똑같아서, 해를 세기는 쉬워요."}, {"s": null, "t": "나는 셋째 칸에서 장부를 하나씩 꺼내 표지를 읽었다. 스무 해 전 동지 사본은 칸 맨 안쪽에 있었다. 장부를 펴자 붉은 줄이 그어진 이름들이 줄줄이 이어졌다."}, {"s": null, "t": "한 장에서 내 손가락이 멈췄다. 붉은 줄이 그어지지 않은 줄이 하나 있었다. 이름 자리에 「하람」 두 글자가 있었고, 그 옆에 다른 손으로 「별로 옮김 — 천명원」이 적혀 있었다."}, {"s": null, "t": "「옮김」의 마지막 획이 세 번이나 미끄러져 있었다. 붓을 대다 떼고, 다시 대다 뗀 자국이었다."}, {"s": null, "t": "그 바로 위 두 줄에는 붉은 줄과 인장이 찍혀 있었다. 같은 해, 같은 고을이었다. 줄 끝 「부르는 이」 칸 자리는 긁혀 있었다."}, {"s": null, "t": "나는 장부를 서하람 앞에 내밀었다. 서하람이 손끝을 대려다 멈추고 갈매 쪽으로 얼굴을 돌렸다."}, {"s": "q:r71_seoharam", "t": "갈매 씨가 읽어 줘요. 크게 말고요. 저만 듣게요."}, {"s": null, "t": "갈매가 서하람 곁에 무릎을 꿇고 장부를 들여다보았다. 갈매는 서하람의 귀에 입을 대고 위 두 줄의 이름을 아주 작게 읽었다. 서하람이 처음 듣는 부모의 이름이었다."}, {"s": null, "t": "서하람이 숨을 멈췄다. 서하람은 손을 뻗어 그 두 줄에 손끝을 얹었다. 손끝이 글자 위에서 움찔했다."}, {"s": "q:r71_seoharam", "t": "…차가워요. 이름 글자는 미지근하다고 했는데, 이건 차가워요."}, {"s": null, "t": "사다리 곁에 서 있던 문수가 머뭇거리며 한 걸음 다가섰다."}, {"s": "q:dh_munsu", "t": "그, 그건요. 명부에 붉은 줄이 그어진 글자는 다 그래요. 먹은 도랑으로 빠져나가고 종이에는 획만 남은 데다, 아무도 안 불러서 그렇대요. 희수 서리님이 그랬거든요. 불러 주면 조금 데워진대요."}, {"s": null, "t": "서하람이 두 줄 위에 손바닥을 펴 얹었다. 서하람이 그 두 이름을 처음으로 소리 내어 불렀다. 작은 목소리였다. 금빛 입김 두 가닥이 가늘게 맺혀 장부 위로 떨어졌다."}, {"s": null, "t": "서하람이 손을 떼지 않았다. 한참 뒤에 서하람의 어깨가 조금 풀렸다."}, {"s": "q:r71_seoharam", "t": "…조금 데워졌어요. 얼굴도 모르는데, 이름 부르니까 따뜻해요. 이상하죠."}, {"s": null, "t": "갈매가 서하람의 어깨에 팔을 둘렀다. 갈매는 아무 말도 하지 않았다. 문수가 사다리 뒤로 돌아서서 소매로 눈가를 훔쳤다. 문수는 코를 한 번 훌쩍이고, 그 두 줄과 하람 줄을 종이에 반듯하게 베껴 갈매에게 건넸다."}, {"s": null, "t": "서하람이 장부에서 손을 떼고 문수가 있는 쪽으로 얼굴을 돌렸다."}, {"s": "q:r71_seoharam", "t": "명등청 명부에 이분들 줄도 올려요. 그리고 칸에는… 제가 적을래요. 할머니 칸은 할머니가 적고요."}, {"s": null, "t": "서하람이 장부의 「옮김」 글자를 손끝으로 더듬었다. 세 번 미끄러진 획 위에서 손가락이 오래 멈춰 있었다."}, {"s": "q:r71_seoharam", "t": "할머니 붓이 여기서 미끄러졌네요. 경현 그 사람 말이 맞았어요. …할머니 눈이 요즘 많이 침침하대요. 칸을 적으실 때 손이 안 떨리게, 안신탕 두 그릇 올려 드리고 싶어요. 태사령님 몫까지요. 지난번에도 {이름} 님이 같이 약초를 뜯어 줬잖아요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_2', 3, '할머니의 붓', '안신탕을(를) 만든다, 무극 관성대에 간다, 안신탕을(를) 넘긴다', '{"at": ["star_observatory"], "tasks": [{"t": "craft", "items": ["calm_brew"], "n": 2}, {"t": "travel", "r": ["star_observatory"], "n": 1}], "give": {"calm_brew": 2}}'::jsonb, '[{"s": null, "t": "그날 밤 관성대 지붕 위에 명부를 펼쳤다. 별이 은가루를 뿌린 듯 촘촘했다. 희수가 등잔을 명부 곁에 놓고 붓을 먹물에 적셨다. 서이연은 안신탕을 천천히 다 마시고 빈 그릇을 내려놓았다."}, {"s": "mandate_court:seo", "t": "눈이 한결 낫구나. 별이 좀 덜 번져 보여."}, {"s": null, "t": "희수가 첫 빈 줄에 붓을 대고 서하람을 돌아보았다."}, {"s": "q:mk_hisu", "t": "이름은요?"}, {"s": null, "t": "서하람이 명부 쪽으로 몸을 기울였다."}, {"s": "q:r71_seoharam", "t": "서하람이요. 성은 할머니 성이에요."}, {"s": null, "t": "희수가 「서하람」 세 글자를 반듯하게 적었다. 그 옆에 「스무 해 전 동지」를 적었다. 희수의 붓이 사는 고을 칸에서 멈췄다."}, {"s": "q:mk_hisu", "t": "사는 고을은요? 관성대라고 적을까요, 등도 관아 터라고 적을까요?"}, {"s": null, "t": "서하람이 입을 다물고 생각에 잠겼다. 갈매가 지붕 끝에서 괜히 헛기침을 했다. 서하람이 그 소리 쪽으로 고개를 돌렸다가 피식 웃었다."}, {"s": "q:r71_seoharam", "t": "…무극 관성대요. 여기가 제 집이에요. 갈매 씨는 잔불촌이랑 관아 터를 오가니까, 제가 오가면 돼요. 오가는 길은 갈매 씨가 계단 세어 줄 거고요."}, {"s": null, "t": "갈매가 지붕 끝에서 고개를 홱 돌렸다."}, {"s": "southern_remnant:galmae", "t": "누가 세어 준대."}, {"s": null, "t": "서하람이 그쪽으로 얼굴을 돌리고 빙긋 웃었다."}, {"s": "q:r71_seoharam", "t": "세어 줄 거잖아요."}, {"s": null, "t": "갈매가 대꾸하지 않았다. 희수가 웃음을 참으며 「무극 관성대」를 적었다. 희수는 붓을 서이연에게 내밀었다. 서이연이 붓을 받아 쥐고 서하람 줄 끝의 빈 네모 앞에 붓끝을 댔다."}, {"s": null, "t": "서이연의 손이 잠깐 떨렸다. 서이연은 숨을 한 번 고르고 칸에 제 이름을 적었다. 세 글자가 한 번에 반듯하게 앉았다. 희수가 그 칸을 들여다보고 작게 감탄했다."}, {"s": "q:mk_hisu", "t": "한 번도 안 미끄러졌어요."}, {"s": null, "t": "서이연이 붓을 내려놓으며 희수를 보고 웃었다."}, {"s": "mandate_court:seo", "t": "스무 해 전에 다 미끄러졌으니, 이번엔 안 미끄러지는 게 셈이 맞지."}, {"s": null, "t": "서이연이 엄지에 인주를 묻혀 칸에 꾹 눌렀다. 갈매가 지붕 끝에서 내려와 명부 곁에 쪼그려 앉았다. 갈매는 칸을 손가락으로 가리켰다."}, {"s": "southern_remnant:galmae", "t": "칸에 한 사람만 적어야 돼?"}, {"s": null, "t": "희수가 붓을 갈매 쪽으로 돌려 쥐여 주었다."}, {"s": "q:mk_hisu", "t": "아니에요. 부르는 사람은 몇이어도 돼요. 칸이 좁으면 작게 적으면 돼요."}, {"s": null, "t": "갈매가 붓을 받아 서이연의 이름 곁에 제 이름을 작게, 그러나 꾹꾹 눌러 적었다. 엄지 도장도 서이연의 도장 옆에 바싹 붙여 찍었다."}, {"s": null, "t": "희수가 다음 두 줄에 서하람 부모의 이름을 적었다. 문수가 정리소에서 베껴 준 종이를 보고 옮긴 대로, 같은 해와 같은 고을이었다. 희수는 붓을 서하람의 손에 쥐여 주었다."}, {"s": "q:mk_hisu", "t": "이 두 줄 칸은 서하람 님이 적으세요. 제가 칸 자리를 짚어 드릴게요."}, {"s": null, "t": "서하람이 붓을 쥐었지만, 붓끝이 허공에서 갈 곳을 몰라 흔들렸다. 갈매가 서하람의 등 뒤로 돌아가 그 손을 제 손으로 감쌌다. 갈매가 서하람의 손을 칸 쪽으로 천천히 끌어 주었다."}, {"s": "southern_remnant:galmae", "t": "여기야. 손가락 한 마디 아래. 이번엔 진짜 하늘 왼쪽 맞아."}, {"s": null, "t": "서하람이 웃음을 터뜨렸다. 웃음 끝이 젖어 있었다. 서하람은 갈매의 손에 손을 맡긴 채 칸에 제 이름을 적었다. 글씨가 삐뚤빼뚤했다. 둘째 칸에도 적었다. 둘째 칸 글씨는 조금 덜 삐뚤었다."}, {"s": null, "t": "서하람이 엄지를 칸에 눌렀다. 서하람은 붓을 내려놓고 두 줄 위에 손바닥을 펴 얹었다. 서하람은 부모의 이름을 다시 불렀다. 이번에는 갈매와 서이연과 희수와 내가 따라 불렀다. 금빛 입김이 별빛 아래서 실처럼 이어져 명부 위로 내려앉았다."}, {"s": "q:r71_seoharam", "t": "…미지근해요. 이제 사람 글자예요."}, {"s": null, "t": "계단 쪽에서 지팡이 짚는 소리가 났다. 하후정이 지붕 위로 올라와 명부 곁에 섰다. 노인은 서하람의 줄을 내려다보고, 서하람의 먹 묻은 손을 내려다보았다."}, {"s": "mandate_court:hahu", "t": "…잘 적었다."}, {"s": null, "t": "하후정이 그 말만 하고 하늘을 올려다보았다. 북쪽 국자 곁에서 흐린 별 「빈」이 깜빡였다. 서이연이 노인의 눈길을 따라 하늘을 보다가 눈가를 훔쳤다."}, {"s": "mandate_court:seo", "t": "오늘 밤은 다들 여기서 자요. 람이가 사람 명부에 적힌 첫 밤이니까요."}]'::jsonb, '{}'::jsonb)
on conflict (quest_id, step) do update set title = excluded.title, goal = excluded.goal, need = excluded.need, lines = excluded.lines, reward = excluded.reward;
insert into public.world_quest_steps(quest_id, step, title, goal, need, lines, reward) values ('mde_haram_2', 4, '아침의 기록판', '무극 관성대에서 쉰다', '{"at": ["star_observatory"], "tasks": [{"t": "rest", "r": ["star_observatory"], "n": 1}]}'::jsonb, '[{"s": null, "t": "아침 햇살이 관성대 지붕 기와를 데우고 있었다. 희수는 밤새 마른 명부를 보자기에 다시 싸고 있었다. 명부를 싸는 손이 처음 왔을 때보다 느긋했다."}, {"s": "q:mk_hisu", "t": "명등청에 가져가면 동짓밤에 이 줄도 불리게 돼요. 서하람 님 부모님 줄도요. 동짓밤엔 부르는 이 칸에 이름 적힌 사람들이 그 줄을 맡아 불러요."}, {"s": null, "t": "서하람이 보자기 쪽으로 손을 뻗어 매듭을 더듬었다."}, {"s": "q:r71_seoharam", "t": "그럼 동짓밤엔 제가 불러야겠네요. 등도 관아 터에서요. 다 같이 모이는 데서요."}, {"s": null, "t": "하후정이 계단을 올라왔다. 노인의 품에 손바닥 두 개만 한 돌판 하나가 들려 있었다. 첫 관상대 별 기록판을 그대로 줄여 깎은 판이었다. 판 위에 송곳으로 찍은 점 몇 개가 별자리를 이루고 있었다."}, {"s": null, "t": "하후정이 그 판을 내 손에 올려놓았다. 판 한쪽에 「빈」 한 글자가 새겨져 있었고, 그 옆에 송곳 자국이 엉뚱한 데 찍힌 점 하나가 남아 있었다."}, {"s": null, "t": "서이연이 내 곁으로 다가와 송곳 자국 하나를 손가락으로 짚었다."}, {"s": "mandate_court:seo", "t": "태사령께서 밤새 깎으셨어요. 람이가 찍은 점을 그대로 옮기셨대요. 그 엉뚱한 점은… 갈매 씨가 왼쪽 오른쪽을 헷갈린 자리래요. 그것도 기록이라고 남기셨어요."}, {"s": null, "t": "갈매가 판을 들여다보다가 얼굴이 빨개졌다."}, {"s": "southern_remnant:galmae", "t": "…그걸 왜 남겨. 다 지우지."}, {"s": null, "t": "하후정이 계단 쪽으로 몸을 돌리다 말고 갈매를 한 번 보았다."}, {"s": "mandate_court:hahu", "t": "기록은 지우지 않는다."}, {"s": null, "t": "하후정은 더 말하지 않고 돌아섰다. 갈매가 입을 떡 벌렸다가 다물었다. 서하람이 판 위의 점들을 손끝으로 더듬었다."}, {"s": "q:r71_seoharam", "t": "{이름} 님, 별채에 걸어 두세요. 밤에 그 판을 보고 북쪽 하늘을 보면 「빈」이 어딨는지 알 수 있어요. 저는 못 보지만, {이름} 님이 보고 나중에 말해 주세요. 갈매 씨처럼 헷갈리지 말고요."}, {"s": null, "t": "갈매가 서하람의 어깨를 팔꿈치로 툭 쳤다."}, {"s": "southern_remnant:galmae", "t": "야."}, {"s": null, "t": "서하람이 갈매 쪽으로 얼굴을 돌리고 웃었다. 갈매가 그 머리를 헝클고, 계단 첫 칸 앞에 서서 손을 내밀었다."}, {"s": "southern_remnant:galmae", "t": "내려가자. 계단 다섯. 쉬고. 다시 다섯."}]'::jsonb, '{"gil": 205, "items": {"moonlight_essence": 2, "travel_ration": 2, "hf_md_starplate": 1}, "title": "md_keep_haram"}'::jsonb)
