$q$'has_stable', r.has_stable OR public.world_weak_lift(uid, r.region_id, 'stable'), 'weak', public.world_weak_view(uid, r.region_id), 'project', public.world_project_brief(uid),$q$]);

do $g$
declare f text;
begin
  foreach f in array array['world_project_rules()', 'world_project_rule(text)', 'world_project_items(text, int)', 'world_project_urgent(text, int, date)',
    'world_project_goal(text, int)', 'world_project_text(text, int)'] loop
    perform pg_temp.pj_share('public.' || f);
  end loop;
  foreach f in array array['world_project_stage(text)', 'world_project_role(uuid, text)', 'world_project_day_pts(uuid, date)', 'world_project_member(uuid, text)', 'world_project_story(uuid, text)',
    'world_project_at(uuid)', 'world_project_rel_up(uuid, text, int, bigint)', 'world_project_stage_up(text, uuid)', 'world_project_have(uuid, jsonb, jsonb, text)', 'world_project_st_ok(uuid)',
    'world_project_brief(uuid)', 'world_project_rule_count(uuid, jsonb)', 'world_project_view(text)', 'world_project_give(text, jsonb)'] loop
    perform pg_temp.pj_share('public.' || f);
    perform pg_temp.pj_own('public.' || f, 'fn_owner_field');
  end loop;
end $g$;
grant execute on function public.world_project_view(text) to authenticated;
grant execute on function public.world_project_give(text, jsonb) to authenticated;
grant execute on function public.world_project_rules() to anon, authenticated;
grant select, update on public.world_faction_relations to fn_owner_field;
grant insert on public.world_faction_log to fn_owner_field;
grant usage on sequence public.world_faction_log_id_seq to fn_owner_field;

insert into public.world_shop_catalog(shop_id, item_id, base_price, stock_min, stock_max, daily_cap)
select s.shop, x.item, greatest(1, round(i.reference_price * x.mul))::bigint, 1, 1, x.cap
  from jsonb_to_recordset($J$[{"k":"f:night_office","item":"rejuv_pill","mul":1.3,"cap":5},{"k":"f:night_office","item":"calm_brew","mul":1.3,"cap":5},{"k":"f:red_moon_cult","item":"exp_elixir_tiger","mul":1.3,"cap":5},{"k":"f:red_moon_cult","item":"skate_ferment","mul":1.3,"cap":5},{"k":"f:black_lotus","item":"dark_eye_drops","mul":1.3,"cap":5},{"k":"f:black_lotus","item":"ray_steam","mul":1.3,"cap":5},{"k":"f:north_league","item":"exp_elixir_iron","mul":1.3,"cap":5},{"k":"f:north_league","item":"cod_soup","mul":1.3,"cap":5},{"k":"f:river_alliance","item":"purify_water","mul":1.3,"cap":5},{"k":"f:river_alliance","item":"eel_tonic","mul":1.3,"cap":5},{"k":"f:southern_remnant","item":"fish_oil_lamp","mul":1.3,"cap":5},{"k":"f:southern_remnant","item":"hairtail_braise","mul":1.3,"cap":5},{"k":"f:mandate_court","item":"exp_elixir_clear","mul":1.3,"cap":5},{"k":"f:mandate_court","item":"marlin_grill","mul":1.3,"cap":5},{"k":"c:gwiheo","item":"rejuv_pill","mul":3.5,"cap":5},{"k":"c:gwiheo","item":"moonlight_essence","mul":3.5,"cap":5},{"k":"c:mukjeok","item":"grand_pill","mul":3.5,"cap":5},{"k":"c:mukjeok","item":"heavenly_dew","mul":3.5,"cap":5},{"k":"c:deungdo","item":"grand_pill","mul":3.5,"cap":5},{"k":"c:deungdo","item":"heavenly_dew","mul":3.5,"cap":5}]$J$::jsonb) as x(k text, item text, mul numeric, cap int)
  join public.world_item_catalog i on i.item_id = x.item
  cross join lateral jsonb_array_elements_text(public.world_project_rule(x.k) -> 'shops') s(shop)
on conflict (shop_id, item_id) do update set base_price = excluded.base_price, daily_cap = excluded.daily_cap;
